import React, { Component, ErrorInfo, ReactNode } from 'react';

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorId: string;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { hasError: false, error: null, errorId: '' };

  static getDerivedStateFromError(error: Error): State {
    return {
      hasError: true,
      error,
      errorId: `ERR-${Date.now().toString(36).toUpperCase()}`,
    };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error('[ErrorBoundary]', error, info.componentStack);
  }

  handleReset = () => {
    this.setState({ hasError: false, error: null, errorId: '' });
  };

  render() {
    if (this.state.hasError) {
      if (this.props.fallback) return this.props.fallback;
      return <ErrorScreen error={this.state.error} errorId={this.state.errorId} onReset={this.handleReset} />;
    }
    return this.props.children;
  }
}

function ErrorScreen({
  error,
  errorId,
  onReset,
}: {
  error: Error | null;
  errorId: string;
  onReset: () => void;
}) {
  const isOffline = !navigator.onLine;

  return (
    <div
      style={{
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        background: 'linear-gradient(135deg, #0f172a 0%, #1e293b 100%)',
        fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
        padding: '1rem',
      }}
    >
      <div
        style={{
          background: '#1e293b',
          border: '1px solid #334155',
          borderRadius: '1.5rem',
          padding: '2.5rem 2rem',
          maxWidth: '460px',
          width: '100%',
          color: '#f1f5f9',
          boxShadow: '0 25px 50px rgba(0,0,0,.5)',
        }}
      >
        {/* Icono */}
        <div
          style={{
            width: 72, height: 72,
            background: '#450a0a',
            borderRadius: '50%',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            margin: '0 auto 1.5rem',
          }}
        >
          <svg width="36" height="36" fill="none" viewBox="0 0 24 24" stroke="#f87171" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round"
              d="M12 9v3m0 3h.01M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z" />
          </svg>
        </div>

        <h1 style={{ textAlign: 'center', fontSize: '1.6rem', fontWeight: 800, marginBottom: '.5rem' }}>
          Algo salió mal
        </h1>
        <p style={{ textAlign: 'center', color: '#94a3b8', lineHeight: 1.6, marginBottom: '1.5rem', fontSize: '.9rem' }}>
          {isOffline
            ? 'Parece que no hay conexión. Recupera la señal e intenta de nuevo.'
            : 'Ocurrió un error inesperado en la aplicación.'}
        </p>

        {/* Código de error */}
        <div
          style={{
            background: '#0f172a',
            border: '1px solid #334155',
            borderRadius: '.75rem',
            padding: '.75rem 1rem',
            marginBottom: '1.5rem',
            fontFamily: 'monospace',
            fontSize: '.8rem',
            color: '#94a3b8',
          }}
        >
          <div style={{ color: '#64748b', marginBottom: '.25rem', fontSize: '.7rem', textTransform: 'uppercase', letterSpacing: '.08em' }}>
            ID: {errorId}
          </div>
          <div style={{ color: '#f87171', wordBreak: 'break-word' }}>
            {error?.message || 'Error desconocido'}
          </div>
        </div>

        {/* Acciones */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '.75rem' }}>
          <button
            onClick={onReset}
            style={{
              padding: '.8rem 1.25rem', border: 'none', borderRadius: '.75rem',
              background: '#2563eb', color: '#fff',
              fontSize: '.95rem', fontWeight: 600, cursor: 'pointer',
            }}
          >
            Intentar de nuevo
          </button>
          <button
            onClick={() => { window.location.href = '/dashboard'; }}
            style={{
              padding: '.8rem 1.25rem', border: 'none', borderRadius: '.75rem',
              background: '#334155', color: '#e2e8f0',
              fontSize: '.95rem', fontWeight: 600, cursor: 'pointer',
            }}
          >
            Ir al Dashboard
          </button>
          <button
            onClick={() => { window.location.reload(); }}
            style={{
              padding: '.8rem 1.25rem', border: '1px solid #334155', borderRadius: '.75rem',
              background: 'transparent', color: '#64748b',
              fontSize: '.9rem', fontWeight: 500, cursor: 'pointer',
            }}
          >
            Recargar página
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { StrictMode, Fragment, useEffect, useRef } from 'react'
import { createRoot } from 'react-dom/client'
import { BrowserRouter } from 'react-router-dom';
import '@/app/styles/index.css';
import AppRoutes from './routes/AppRoutes'
import { AuthProvider } from '@/app/providers/AuthenticationContext'
import { SystemAlertsHub } from '@/shared/components/notifications/SystemAlertsHub'
// Removed setupApiInterceptors import; interceptors are configured within services/api on module load
import { CacheProvider } from '@/app/providers/CacheContext'
import { SidebarProvider } from '@/app/providers/SidebarContext'
import { ThemeProvider } from '@/app/providers/ThemeContext'
import { ToastProvider } from '@/app/providers/ToastContext'
import { I18nProvider } from '@/shared/i18n'
import { InventoryProvider } from '@/app/providers/InventoryContext'
import { FieldModeProvider } from '@/app/providers/FieldModeContext'
import { useToast } from '@/app/providers/ToastContext'
import { useCache } from '@/app/providers/CacheContext'
import { useAuth } from '@/features/auth/model/useAuth'
import { hasSessionCookies } from '@/shared/utils/cookieUtils'
import { refetchAllResources } from '@/shared/hooks/useResource'
import { PWAUpdateHandler } from '@/shared/ui/common/PWAUpdateHandler'
import { SyncPulse } from '@/shared/components/SyncPulse'
import { ErrorBoundary } from '@/app/ErrorBoundary'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { PrefetchManager } from '@/shared/ui/common/PrefetchManager'
// Eliminado OnlineStatusIndicator redundante

import sse, { connectSSE, closeSSE } from '@/lib/events'
import { publishEvent, subscribeBridge, claimLeadership } from '@/lib/eventsBridge'
import { initStoragePersistence } from '@/shared/utils/storagePersistence'

// Configurar React Query Client con optimizaciones agresivas de caché
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      // Estrategia stale-while-revalidate para máxima fluidez
      refetchOnWindowFocus: false, // No refetch al cambiar de ventana
      refetchOnMount: false, // No refetch al montar si hay datos en caché
      refetchOnReconnect: true, // Solo refetch al reconectar
      retry: 2, // 2 reintentos para mayor resiliencia
      retryDelay: (attemptIndex) => Math.min(1000 * 2 ** attemptIndex, 30000), // Backoff exponencial

      // Tiempos de caché optimizados para máxima fluidez
      staleTime: 5 * 60 * 1000, // 5 minutos - datos considerados frescos
      gcTime: 30 * 60 * 1000, // 30 minutos - mantener en memoria (antes: cacheTime)

      // Optimizaciones de red
      networkMode: 'offlineFirst', // Priorizar caché offline

      // Estructuración de errores
      throwOnError: false, // No lanzar errores, manejarlos gracefully

      // Refetch estratégico
      refetchInterval: false, // No refetch automático (salvo casos específicos)
      refetchIntervalInBackground: false,
    },
    mutations: {
      // Optimizaciones para mutaciones
      retry: 1, // 1 reintento para mutaciones
      retryDelay: 1000, // 1 segundo entre reintentos
      networkMode: 'online', // Mutaciones solo cuando hay conexión

      // Optimistic updates por defecto
      onMutate: undefined, // Permitir optimistic updates en componentes individuales
    },
  },
});

// CSS principal cargado desde index.html para evitar FOUC

// Recuperación defensiva ante fallos de carga de chunks (MIME incorrecto / módulo no encontrado)
(function registerChunkRecovery() {
  if (typeof window === 'undefined') return;
  const RECOVERY_FLAG = 'chunk-recovery-at';
  const now = Date.now();
  const last = Number(sessionStorage.getItem(RECOVERY_FLAG) || '0');
  // Evitar bucles infinitos: solo intentar una vez cada 90s
  if (now - last < 90_000) return;

  const recover = async () => {
    try {
      sessionStorage.setItem(RECOVERY_FLAG, String(Date.now()));
      // Limpiar caches del Service Worker y desregistrarlo
      if ('caches' in window) {
        const keys = await caches.keys();
        await Promise.all(keys.map((k) => caches.delete(k).catch(() => { })));
      }
      if ('serviceWorker' in navigator) {
        const regs = await navigator.serviceWorker.getRegistrations();
        await Promise.all(regs.map((r) => r.unregister().catch(() => { })));
      }
    } catch (err) {
      console.warn('[Recovery] Error limpiando caches/SW tras fallo de chunk', err);
    } finally {
      window.location.reload();
    }
  };

  const shouldRecover = (reason: any): boolean => {
    const msg = typeof reason === 'string'
      ? reason
      : reason?.message || reason?.toString?.() || '';
    return msg.includes('Failed to fetch dynamically imported module')
      || msg.includes('Expected a JavaScript or Wasm module script');
  };

  window.addEventListener('unhandledrejection', (event) => {
    if (shouldRecover(event?.reason)) {
      event?.preventDefault?.();
      recover();
    }
  });

  window.addEventListener('error', (event) => {
    // Detectar errores de módulo o scripts con MIME incorrecto
    const target = event?.target as any;
    const isScriptTag = target && target.tagName === 'SCRIPT';
    const msg = event?.message || '';
    if (shouldRecover(msg) || (isScriptTag && msg.includes('Failed to load module script'))) {
      event?.preventDefault?.();
      recover();
    }
  }, true);
})();

// Eliminar persistencia de autenticación en sessionStorage en main.tsx
// Limpieza one-time de claves legacy en localStorage (solo lectura/eliminación; no se vuelve a usar para persistencia)
(function legacyLocalStorageCleanup() {
  try {
    if (typeof window === 'undefined' || !('localStorage' in window)) return;
    const knownKeys = [
      'finca_access_token',
      'dev_user_data',
      'jwt_metadata',
      'auth:user',
      'auth:recent_ts',
      'auth:user:cache',
      'auth:auto_login_block',
      'auth:session_active',
      'offline_queue_v1',
      'sidebar-width',
      'theme',
      'finca_auth_login_path',
    ];
    for (const k of knownKeys) {
      try { window.localStorage.removeItem(k); } catch { /* noop */ }
    }
    const prefixList = ['app-cache:', 'offline_cache_v1:'];
    try {
      for (let i = window.localStorage.length - 1; i >= 0; i--) {
        const key = window.localStorage.key(i);
        if (!key) continue;
        if (prefixList.some(p => key.startsWith(p))) {
          try { window.localStorage.removeItem(key); } catch { /* noop */ }
        }
      }
    } catch { /* noop */ }
  } catch { /* noop */ }
})();

// Registrar Service Worker (PWA) con optimización de carga
const ENABLE_PWA = (import.meta as any)?.env?.VITE_ENABLE_PWA === 'true' || import.meta.env.PROD;

if (ENABLE_PWA && 'serviceWorker' in navigator) {
  // Registrar SW inmediatamente para mejor rendimiento
  const registerServiceWorker = async () => {
    try {
      const { registerSW } = await import('virtual:pwa-register');
      registerSW({
        immediate: true,
        onRegistered(swReg) {
          console.log('[PWA] Service Worker registrado', swReg);
          // Estrategia de precarga inteligente
          if (swReg?.active) {
            // Precargar rutas críticas después de que la app esté lista
            setTimeout(() => {
              // Prefetch SPA shell bajo el base proxied; evitar prefetch de endpoints API para no generar aborts en dev
              const ENABLE_PWA_PREFETCH = (import.meta as any)?.env?.VITE_ENABLE_PWA_PREFETCH === 'true';
              if (ENABLE_PWA_PREFETCH) {
                const criticalRoutes = ['/dashboard'];
                criticalRoutes.forEach(route => {
                  fetch(route, {
                    // Use GET for broader compatibility (some backends don't implement HEAD)
                    method: 'GET',
                    cache: 'force-cache',
                    credentials: 'include'
                  }).catch(() => {
                    // Silenciosamente fallar precarga
                  });
                });
              }
            }, 2000);
          }
        },
        onRegisterError(error) {
          console.error('[PWA] Error registrando Service Worker', error);
        },
      });

      // Obtener la instancia real del Service Worker registration para manejar actualizaciones
      navigator.serviceWorker.ready.then((registration) => {
        registration.addEventListener('updatefound', () => {
          const installingWorker = registration.installing;
          installingWorker?.addEventListener('statechange', () => {
            if (installingWorker.state === 'installed' && navigator.serviceWorker.controller) {
              // Notificar al usuario sobre actualización disponible
              const event = new CustomEvent('pwa-update-available');
              window.dispatchEvent(event);
            }
          });
        });
      }).catch(() => {
        // Silenciosamente fallar manejo de actualizaciones
      });

      // Escuchar mensajes de Background Sync
      navigator.serviceWorker.addEventListener('message', (event) => {
        if (event.data && event.data.type === 'OFFLINE_SYNC_SUCCESS') {
          const customEvent = new CustomEvent('pwa-offline-sync-success', {
            detail: { url: event.data.url }
          });
          window.dispatchEvent(customEvent);
        }
      });

    } catch (err) {
      console.warn('[PWA] Registro SW no disponible en este entorno', err);
    }
  };

  // Registrar SW en load pero también intentar inmediatamente para mejor PWA
  if (document.readyState === 'complete') {
    registerServiceWorker();
  } else {
    window.addEventListener('load', registerServiceWorker);
  }
} else {
  // En preview/desarrollo sin PWA: asegurarse de no tener SW/caches antiguas que sirvan bundles obsoletos
  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.getRegistrations?.().then((registrations) => {
      for (const registration of registrations) {
        registration.unregister().catch(() => { });
      }
    }).catch(() => { });
  }
  if (window.caches?.keys) {
    window.caches.keys().then((keys) => {
      keys.forEach((key) => {
        window.caches.delete(key).catch(() => { });
      });
    }).catch(() => { });
  }
}

// Puente React para notificaciones y sincronización al cambiar estado de red
function GlobalNetworkHandlers() {
  const { showToast } = useToast();
  const { preloadCriticalRoutes } = useCache();
  const { isAuthenticated } = useAuth();
  const preloadStartedRef = useRef(false);
  const lastRateLimitAtRef = useRef<number>(0);
  const cookiesReadyRef = useRef(false);

  useEffect(() => {
    const onOnline = async () => {
      try {
        showToast('Conexión restablecida. Sincronizando operaciones y refrescando datos…', 'info');
        await refetchAllResources();
        showToast('Datos actualizados tras recuperar la red.', 'success');
      } catch (e) {
        console.warn('[Network] Error al refrescar datos tras reconexión', e);
        showToast('Reconectado, pero ocurrió un error al refrescar datos.', 'warning');
      }
    };

    const onOffline = () => {
      showToast('Sin conexión. Navegación offline habilitada con datos cacheados.', 'warning');
    };

    const onQueueFlushed = (e: Event) => {
      try {
        const detail = (e as CustomEvent).detail;
        const remaining = detail?.remaining ?? 0;
        const message = remaining === 0
          ? 'Sincronización offline completada. Todo al día.'
          : `Sincronización completada con ${remaining} pendientes.`;
        showToast(message, 'success');
      } catch {
        showToast('Sincronización offline completada.', 'success');
      }
    };

    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOffline);
    window.addEventListener('offline-queue-flushed', onQueueFlushed as EventListener);
    return () => {
      window.removeEventListener('online', onOnline);
      window.removeEventListener('offline', onOffline);
      window.removeEventListener('offline-queue-flushed', onQueueFlushed as EventListener);
    };
  }, [showToast]);

  // Aviso global para límite de solicitudes excedido (HTTP 429)
  useEffect(() => {
    const onRateLimitExceeded = (e: Event) => {
      const detail = (e as CustomEvent).detail || {};
      const endpointLabel =
        typeof detail?.endpoint === 'string'
          ? (detail.endpoint.includes('animals') ? 'Animales' : detail.endpoint)
          : 'API';
      const now = Date.now();
      if (now - lastRateLimitAtRef.current < 15000) return; // evitar spam de toasts
      lastRateLimitAtRef.current = now;
      const wait = typeof detail?.waitSeconds === 'number' && detail.waitSeconds > 0 ? detail.waitSeconds : undefined;
      const waitText = wait ? ` Inténtalo nuevamente en ${wait} segundos.` : '';
      showToast(
        `Se alcanzó el límite de solicitudes en ${endpointLabel}. El servidor indicó RATE_LIMIT_EXCEEDED.${waitText}`,
        'warning',
        6000
      );
    };
    window.addEventListener('rate-limit-exceeded', onRateLimitExceeded as EventListener);
    return () => {
      window.removeEventListener('rate-limit-exceeded', onRateLimitExceeded as EventListener);
    };
  }, [showToast]);

  useEffect(() => {
    if (!isAuthenticated) return;
    const parseEvent = (raw: any) => {
      try {
        const obj = typeof raw === 'string' ? JSON.parse(raw) : raw || {};
        const endpoint = obj.endpoint || obj.path || obj.resource || obj.collection || obj.model || obj.entity || obj.table;
        const action = obj.action || obj.event || obj.type;
        const id = obj.id ?? obj.pk ?? obj.item_id ?? obj.itemId;
        const ep = endpoint ? String(endpoint).split('/').filter(Boolean).pop() : undefined;
        return { endpoint: ep, action, id };
      } catch {
        return {};
      }
    };

    let unsubscribeSse: (() => void) | null = null;
    let unsubscribeBridge: (() => void) | null = null;
    let releaseLeader: (() => void) | null = null;
    let isCurrentLeader = false;

    const init = () => {
      const { isLeader, release } = claimLeadership();
      releaseLeader = release;
      if (isLeader) {
        isCurrentLeader = true;
        connectSSE();
        unsubscribeSse = sse.subscribe((payload) => {
          publishEvent(payload);
          const parsed = parseEvent(payload);
          try { window.dispatchEvent(new CustomEvent('server-global-change', { detail: parsed })); } catch { /* noop */ }
          try { window.dispatchEvent(new CustomEvent('server-resource-changed', { detail: parsed })); } catch { /* noop */ }
        });
      } else {
        isCurrentLeader = false;
        unsubscribeBridge = subscribeBridge((payload) => {
          const parsed = parseEvent(payload);
          try { window.dispatchEvent(new CustomEvent('server-global-change', { detail: parsed })); } catch { /* noop */ }
          try { window.dispatchEvent(new CustomEvent('server-resource-changed', { detail: parsed })); } catch { /* noop */ }
        });
      }
    };

    if (!cookiesReadyRef.current && !hasSessionCookies()) {
      const t = setTimeout(() => {
        cookiesReadyRef.current = hasSessionCookies();
        if (cookiesReadyRef.current) init();
      }, 1000);
      return () => clearTimeout(t);
    }
    init();

    return () => {
      if (isCurrentLeader) {
        closeSSE();
      }
      try { unsubscribeSse?.(); } catch { /* noop */ }
      try { unsubscribeBridge?.(); } catch { /* noop */ }
      try { releaseLeader?.(); } catch { /* noop */ }
    };
  }, [isAuthenticated]);

  // Precarga inteligente SÓLO cuando la autenticación está lista y DESPUÉS de que cargue el dashboard
  useEffect(() => {
    if (preloadStartedRef.current) return;
    if (!isAuthenticated) return; // Gate por auth: sin sesión no se precargan endpoints protegidos
    // Gate adicional: requerir cookies de sesión visibles
    if (!cookiesReadyRef.current && !hasSessionCookies()) {
      // Reintentar en breve para dar tiempo a que el navegador persista las cookies HttpOnly
      setTimeout(() => {
        cookiesReadyRef.current = hasSessionCookies();
        if (cookiesReadyRef.current && !preloadStartedRef.current) {
          preloadStartedRef.current = true;
          preloadCriticalRoutes();
          console.log('[Cache] Precarga inteligente activada tras detectar cookies de sesión');
        }
      }, 1500);
      return;
    }
    preloadStartedRef.current = true;

    // OPTIMIZACIÓN: Reducir delay para precarga más rápida (1s vs 5s)
    const timer = setTimeout(() => {
      try {
        preloadCriticalRoutes();
        console.log('[Cache] Precarga inteligente de rutas críticas activada (post-auth)');
      } catch (error) {
        console.warn('[Cache] Error en precarga inteligente:', error);
      }
    }, 1000); // 1s tras estar autenticado (optimizado para velocidad)

    return () => clearTimeout(timer);
  }, [preloadCriticalRoutes, isAuthenticated]);

  return null;
}

// Verificación de Tailwind en runtime (solo en desarrollo)
if ((import.meta as any)?.env?.DEV) {
  setTimeout(() => {
    const el = document.createElement('div');
    el.className = 'hidden bg-red-500';
    document.body.appendChild(el);
    const style = window.getComputedStyle(el);
    const hasDisplayNone = style.display === 'none';
    const hasBg = !!style.backgroundColor && style.backgroundColor !== 'rgba(0, 0, 0, 0)';
    console.log('[TailwindCheck] active:', hasDisplayNone || hasBg, { display: style.display, background: style.backgroundColor });
    document.body.removeChild(el);
  }, 0);
}

// Helper DEV: permitir impersonar rol vía querystring (?devRole=Administrador)
if ((import.meta as any)?.env?.DEV) {
  try {
    const params = new URLSearchParams(window.location.search);
    if (params.has('clearDev')) {
      sessionStorage.removeItem('dev_user_data_session');
      console.log('[DevImpersonate] cleared dev_user_data_session');
    }
    const devRole = params.get('devRole') || params.get('impersonate') || params.get('role');
    if (devRole) {
      const devName = params.get('devName') || 'Dev User';
      const devId = params.get('devId') || '0';
      const payload = { role: devRole, fullname: devName, id: devId };
      sessionStorage.setItem('dev_user_data_session', JSON.stringify(payload));
      console.log('[DevImpersonate] session set:', payload);
    }
  } catch (e) {
    console.warn('[DevImpersonate] failed to set from query:', e);
  }
}

const UseWrapper = (import.meta as any)?.env?.VITE_ENABLE_STRICT_MODE === 'true' ? StrictMode : Fragment;

// Inicializar persistencia de almacenamiento (IndexedDB)
initStoragePersistence().catch(err => console.warn('[Storage] Error:', err));

createRoot(document.getElementById('root')!).render(
  <UseWrapper>
    <ErrorBoundary>
    <QueryClientProvider client={queryClient}>
      <BrowserRouter
        future={{
          v7_startTransition: true,
          v7_relativeSplatPath: true,
        }}
      >
        <AuthProvider>
          <CacheProvider>
            <SidebarProvider>
              <ThemeProvider>
                <I18nProvider>
                  <ToastProvider>
                    <InventoryProvider>
                      <FieldModeProvider>
                        {/* Bridge para toasts y refetch al recuperar red y precargas post-auth */}
                        <GlobalNetworkHandlers />
                        {/* Sistema inteligente de prefetching para máxima fluidez */}
                        <PrefetchManager />
                        <AppRoutes />
                        {/* OnlineStatusIndicator movido a NotificationCenter y GlobalAlertBanner */}

                        <SyncPulse />
                        <PWAUpdateHandler />
                        <SystemAlertsHub />
                      </FieldModeProvider>
                    </InventoryProvider>
                  </ToastProvider>
                </I18nProvider>
              </ThemeProvider>
            </SidebarProvider>
          </CacheProvider>
        </AuthProvider>
      </BrowserRouter>
    </QueryClientProvider>
    </ErrorBoundary>
  </UseWrapper>
);

import React, { createContext, useContext, useReducer, useEffect, useRef, useCallback, ReactNode } from 'react';
import { useAuth } from '@/features/auth/model/useAuth';
import { useToast } from './ToastContext';
import dataPreloadService, { 
  DashboardCriticalData, 
  AnimalModuleData, 
  UserModuleData,
  PreloadError,
  PreloadErrorType 
} from '@/features/dashboard/api/dataPreload.service';

/**
 * Estados de la aplicación
 */
export enum AppStateStatus {
  INITIALIZING = 'INITIALIZING',
  LOADING_DASHBOARD = 'LOADING_DASHBOARD',
  DASHBOARD_READY = 'DASHBOARD_READY',
  LOADING_MODULES = 'LOADING_MODULES',
  READY = 'READY',
  ERROR = 'ERROR',
  OFFLINE = 'OFFLINE'
}

/**
 * Interfaz para el estado global de la aplicación
 */
export interface AppState {
  // Estado general
  status: AppStateStatus;
  isOnline: boolean;
  
  // Datos de la aplicación
  dashboardData: DashboardCriticalData | null;
  animalModuleData: AnimalModuleData | null;
  userModuleData: UserModuleData | null;
  
  // Estado de carga
  isLoading: boolean;
  dashboardLoaded: boolean;
  animalModuleLoaded: boolean;
  userModuleLoaded: boolean;
  
  // Errores
  errors: PreloadError[];
  hasCriticalErrors: boolean;
  
  // Metadatos
  lastUpdate: number | null;
  sessionId: string;
}

/**
 * Acciones disponibles para el estado de la aplicación
 */
export type AppStateAction =
  | { type: 'SET_STATUS'; payload: AppStateStatus }
  | { type: 'SET_ONLINE_STATUS'; payload: boolean }
  | { type: 'SET_DASHBOARD_DATA'; payload: DashboardCriticalData }
  | { type: 'SET_ANIMAL_MODULE_DATA'; payload: AnimalModuleData }
  | { type: 'SET_USER_MODULE_DATA'; payload: UserModuleData }
  | { type: 'SET_LOADING_STATE'; payload: { isLoading: boolean } }
  | { type: 'SET_MODULE_LOADED'; payload: { module: 'dashboard' | 'animal' | 'user'; loaded: boolean } }
  | { type: 'ADD_ERROR'; payload: PreloadError }
  | { type: 'CLEAR_ERRORS' }
  | { type: 'CLEAR_NON_CRITICAL_ERRORS' }
  | { type: 'INVALIDATE_CACHE'; payload?: { module?: 'dashboard' | 'animal' | 'user' } }
  | { type: 'RESET_STATE' }
  | { type: 'UPDATE_LAST_UPDATE' };

/**
 * Estado inicial de la aplicación
 */
const initialState: AppState = {
  status: AppStateStatus.INITIALIZING,
  isOnline: navigator.onLine,
  dashboardData: null,
  animalModuleData: null,
  userModuleData: null,
  isLoading: false,
  dashboardLoaded: false,
  animalModuleLoaded: false,
  userModuleLoaded: false,
  errors: [],
  hasCriticalErrors: false,
  lastUpdate: null,
  sessionId: generateSessionId()
};

/**
 * Genera un ID de sesión único
 */
function generateSessionId(): string {
  return `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}

/**
 * Reducer para gestionar el estado de la aplicación
 */
function appStateReducer(state: AppState, action: AppStateAction): AppState {
  switch (action.type) {
    case 'SET_STATUS':
      return {
        ...state,
        status: action.payload
      };

    case 'SET_ONLINE_STATUS':
      return {
        ...state,
        isOnline: action.payload,
        status: action.payload 
          ? (state.hasCriticalErrors ? AppStateStatus.ERROR : AppStateStatus.READY)
          : AppStateStatus.OFFLINE
      };

    case 'SET_DASHBOARD_DATA':
      return {
        ...state,
        dashboardData: action.payload,
        dashboardLoaded: true,
        lastUpdate: Date.now()
      };

    case 'SET_ANIMAL_MODULE_DATA':
      return {
        ...state,
        animalModuleData: action.payload,
        animalModuleLoaded: true,
        lastUpdate: Date.now()
      };

    case 'SET_USER_MODULE_DATA':
      return {
        ...state,
        userModuleData: action.payload,
        userModuleLoaded: true,
        lastUpdate: Date.now()
      };

    case 'SET_LOADING_STATE':
      return {
        ...state,
        isLoading: action.payload.isLoading
      };

    case 'SET_MODULE_LOADED': {
      const { module: moduleKey, loaded } = action.payload;
      return {
        ...state,
        [`${moduleKey}Loaded`]: loaded
      };
    }

    case 'ADD_ERROR':
      {
        const newErrors = [...state.errors, action.payload];
        const hasCriticalErrors = newErrors.some(error => error.critical);
        return {
          ...state,
          errors: newErrors,
          hasCriticalErrors,
          status: hasCriticalErrors ? AppStateStatus.ERROR : state.status
        };
      }

    case 'CLEAR_ERRORS':
      return {
        ...state,
        errors: [],
        hasCriticalErrors: false,
        status: state.dashboardLoaded ? AppStateStatus.READY : AppStateStatus.INITIALIZING
      };

    case 'CLEAR_NON_CRITICAL_ERRORS':
      {
        const criticalErrors = state.errors.filter(error => error.critical);
        return {
          ...state,
          errors: criticalErrors,
          hasCriticalErrors: criticalErrors.length > 0
        };
      }

    case 'INVALIDATE_CACHE': {
      {
        const moduleKey = action.payload?.module;
        if (moduleKey) {
          return {
            ...state,
            [`${moduleKey}Data`]: null,
            [`${moduleKey}Loaded`]: false
          };
        } else {
          return {
            ...state,
            dashboardData: null,
            animalModuleData: null,
            userModuleData: null,
            dashboardLoaded: false,
            animalModuleLoaded: false,
            userModuleLoaded: false,
            status: AppStateStatus.INITIALIZING
          };
        }
      }
    }

    case 'RESET_STATE':
      return {
        ...initialState,
        sessionId: generateSessionId()
      };

    case 'UPDATE_LAST_UPDATE':
      return {
        ...state,
        lastUpdate: Date.now()
      };

    default:
      return state;
  }
}

/**
 * Contexto para el estado global de la aplicación
 */
const AppStateContext = createContext<{
  state: AppState;
  dispatch: React.Dispatch<AppStateAction>;
  // Acciones convenientes
  startPreload: () => Promise<void>;
  retryPreload: () => Promise<void>;
  refreshDashboard: () => Promise<void>;
  refreshAnimalModule: () => Promise<void>;
  refreshUserModule: () => Promise<void>;
  clearErrors: () => void;
  clearNonCriticalErrors: () => void;
  invalidateCache: (module?: 'dashboard' | 'animal' | 'user') => void;
  isDataFresh: (maxAgeMs?: number) => boolean;
} | null>(null);

/**
 * Props para el provider del estado de la aplicación
 */
interface AppStateProviderProps {
  children: ReactNode;
  /**
   * Iniciar precarga automáticamente cuando el usuario está autenticado
   */
  autoStart?: boolean;
}

/**
 * Provider para el estado global de la aplicación
 * 
 * Características:
 * - Gestión centralizada del estado de la aplicación
 * - Integración con el servicio de precarga de datos
 * - Sincronización con el estado de autenticación
 * - Manejo automático de errores y estados de conexión
 */
export const AppStateProvider: React.FC<AppStateProviderProps> = ({
  children,
  autoStart = true
}) => {
  const [state, dispatch] = useReducer(appStateReducer, initialState);
  const { isAuthenticated, user: _user } = useAuth();
  const { showToast } = useToast();
  const preloadPromiseRef = useRef<Promise<void> | null>(null);

  // Sincronizar con el servicio de precarga
  useEffect(() => {
    const unsubscribe = dataPreloadService.onStateChange((serviceState) => {
      // Actualizar estado local basado en el estado del servicio
      dispatch({ type: 'SET_LOADING_STATE', payload: { isLoading: serviceState.isLoading } });
      dispatch({ type: 'SET_MODULE_LOADED', payload: { module: 'dashboard', loaded: serviceState.dashboardLoaded } });
      dispatch({ type: 'SET_MODULE_LOADED', payload: { module: 'animal', loaded: serviceState.animalModuleLoaded } });
      dispatch({ type: 'SET_MODULE_LOADED', payload: { module: 'user', loaded: serviceState.userModuleLoaded } });
      
      // Actualizar datos desde caché del servicio
      const dashboardData = dataPreloadService.getDashboardData();
      const animalModuleData = dataPreloadService.getAnimalModuleData();
      const userModuleData = dataPreloadService.getUserModuleData();
      
      if (dashboardData) {
        dispatch({ type: 'SET_DASHBOARD_DATA', payload: dashboardData });
      }
      if (animalModuleData) {
        dispatch({ type: 'SET_ANIMAL_MODULE_DATA', payload: animalModuleData });
      }
      if (userModuleData) {
        dispatch({ type: 'SET_USER_MODULE_DATA', payload: userModuleData });
      }
      
      // Actualizar errores
      serviceState.errors.forEach(error => {
        dispatch({ type: 'ADD_ERROR', payload: error });
      });
      
      // Actualizar estado general
      if (serviceState.isLoading) {
        if (serviceState.dashboardLoaded) {
          dispatch({ type: 'SET_STATUS', payload: AppStateStatus.LOADING_MODULES });
        } else {
          dispatch({ type: 'SET_STATUS', payload: AppStateStatus.LOADING_DASHBOARD });
        }
      } else if (serviceState.dashboardLoaded && !state.hasCriticalErrors) {
        dispatch({ type: 'SET_STATUS', payload: AppStateStatus.READY });
      } else if (state.hasCriticalErrors) {
        dispatch({ type: 'SET_STATUS', payload: AppStateStatus.ERROR });
      }
    });

    return unsubscribe;
  }, [state.hasCriticalErrors]);

  // Función para iniciar la precarga
  const startPreload = useCallback(async () => {
    if (preloadPromiseRef.current) {
      return preloadPromiseRef.current;
    }

    if (!isAuthenticated) {
      console.warn('[AppStateProvider] Usuario no autenticado, omitiendo precarga');
      return;
    }

    console.log('[AppStateProvider] Iniciando precarga de datos...');
    dispatch({ type: 'SET_STATUS', payload: AppStateStatus.LOADING_DASHBOARD });

    preloadPromiseRef.current = (async () => {
      try {
        await dataPreloadService.preloadData();
        dispatch({ type: 'SET_STATUS', payload: AppStateStatus.READY });
        console.log('[AppStateProvider] Precarga completada exitosamente');
      } catch (error: any) {
        console.error('[AppStateProvider] Error en la precarga:', error);
        
        // Añadir error al estado
        dispatch({
          type: 'ADD_ERROR',
          payload: {
            type: PreloadErrorType.DASHBOARD_CRITICAL,
            message: error?.message || 'Error crítico en la precarga',
            critical: true,
            timestamp: Date.now(),
            context: error
          }
        });
        
        dispatch({ type: 'SET_STATUS', payload: AppStateStatus.ERROR });
        
        showToast(
          'Error crítico al cargar los datos. La aplicación podría no funcionar correctamente.',
          'error',
          8000
        );
      } finally {
        preloadPromiseRef.current = null;
      }
    })();

    return preloadPromiseRef.current;
  }, [isAuthenticated, showToast]);

  // Manejar cambios en el estado de autenticación
  useEffect(() => {
    if (isAuthenticated) {
      dispatch({ type: 'SET_STATUS', payload: AppStateStatus.INITIALIZING });
      
      if (autoStart) {
        // Pequeño retraso para asegurar que todo esté inicializado
        setTimeout(() => {
          startPreload();
        }, 100);
      }
    } else {
      // Limpiar estado cuando el usuario no está autenticado
      dispatch({ type: 'RESET_STATE' });
    }
  }, [isAuthenticated, autoStart, startPreload]);

  // Manejar cambios en el estado de conexión
  useEffect(() => {
    const handleOnline = () => {
      dispatch({ type: 'SET_ONLINE_STATUS', payload: true });
      showToast('Conexión restablecida', 'success');
      
      // Reintentar precarga automáticamente al recuperar conexión
      if (isAuthenticated && state.dashboardLoaded) {
        startPreload();
      }
    };

    const handleOffline = () => {
      dispatch({ type: 'SET_ONLINE_STATUS', payload: false });
      showToast('Sin conexión a internet', 'warning');
    };

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [isAuthenticated, state.dashboardLoaded, showToast, startPreload]);

  // Función para reintentar la precarga
  const retryPreload = async () => {
    console.log('[AppStateProvider] Reintentando precarga...');
    dispatch({ type: 'CLEAR_ERRORS' });
    dataPreloadService.invalidateCache();
    await startPreload();
  };

  // Funciones para refrescar módulos específicos
  const refreshDashboard = async () => {
    console.log('[AppStateProvider] Refrescando dashboard...');
    dataPreloadService.invalidateModuleData('dashboard');
    
    if (!state.isLoading) {
      await startPreload();
    }
  };

  const refreshAnimalModule = async () => {
    console.log('[AppStateProvider] Refrescando módulo Animal...');
    dataPreloadService.invalidateModuleData('animal');
    
    if (!state.isLoading) {
      await startPreload();
    }
  };

  const refreshUserModule = async () => {
    console.log('[AppStateProvider] Refrescando módulo Usuario...');
    dataPreloadService.invalidateModuleData('user');
    
    if (!state.isLoading) {
      await startPreload();
    }
  };

  // Funciones para manejar errores
  const clearErrors = () => {
    dispatch({ type: 'CLEAR_ERRORS' });
  };

  const clearNonCriticalErrors = () => {
    dispatch({ type: 'CLEAR_NON_CRITICAL_ERRORS' });
  };

  // Función para invalidar caché
  const invalidateCache = (module?: 'dashboard' | 'animal' | 'user') => {
    dispatch({ type: 'INVALIDATE_CACHE', payload: { module } });
    if (module) {
      dataPreloadService.invalidateModuleData(module);
    } else {
      dataPreloadService.invalidateCache();
    }
  };

  // Utilidad para verificar si los datos están frescos
  const isDataFresh = (maxAgeMs = 5 * 60 * 1000) => { // 5 minutos por defecto
    if (!state.lastUpdate) return false;
    return Date.now() - state.lastUpdate < maxAgeMs;
  };

  const value = {
    state,
    dispatch,
    startPreload,
    retryPreload,
    refreshDashboard,
    refreshAnimalModule,
    refreshUserModule,
    clearErrors,
    clearNonCriticalErrors,
    invalidateCache,
    isDataFresh
  };

  return (
    <AppStateContext.Provider value={value}>
      {children}
    </AppStateContext.Provider>
  );
};

/**
 * Hook para acceder al estado global de la aplicación
 */
export const useAppState = () => {
  const context = useContext(AppStateContext);
  if (context === null) {
    throw new Error('useAppState debe ser usado dentro de un AppStateProvider');
  }
  return context;
};

export default AppStateContext;

import { useState, useEffect, ReactNode, useCallback, useRef, useMemo } from "react"
import { useNavigate } from "react-router-dom"
import { User, AuthContextType, Role, role as RoleType } from "@/entities/user/model/types"
import { getUserProfile, normalizeRole, authServiceLogout } from "@/features/auth/api/auth.service"
import { AuthContext } from "./AuthContext"
import { isDevelopment } from "@/shared/utils/envConfig"
import * as utils from "./auth/auth.utils"
import { usePermissions } from "./auth/hooks/usePermissions"
import { useLocationSync } from "./auth/hooks/useLocationSync"

export { AuthContext }

const AUTH_CHECK_TIMEOUT_MS = 9000

const withAuthTimeout = async <T,>(promise: Promise<T>, controller: AbortController): Promise<T> => {
  let timeoutId: ReturnType<typeof setTimeout> | null = null
  let timedOut = false
  const timeout = new Promise<never>((_, reject) => {
    timeoutId = setTimeout(() => {
      timedOut = true
      controller.abort()
      reject(new Error('La verificación de sesión tardó demasiado'))
    }, AUTH_CHECK_TIMEOUT_MS)
  })

  try {
    return await Promise.race([promise, timeout])
  } finally {
    if (timeoutId) clearTimeout(timeoutId)
    if (timedOut && !controller.signal.aborted) controller.abort()
  }
}

export const AuthProvider = ({ children }: { children: ReactNode }) => {
  const [user, setUser] = useState<User | null>(null)
  const [role, setRole] = useState<string | null>(null)
  const [name, setName] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)
  const [isAuthenticated, setIsAuthenticated] = useState(false)
  const navigate = useNavigate()
  const enableRoleSwitch = isDevelopment()

  const meAbortRef = useRef<AbortController | null>(null)
  const last429AtRef = useRef<number>(0)
  const meActiveOptsRef = useRef<{ background?: boolean } | null>(null)
  const bcRef = useRef<any>(null)
  const lastInflightRxAtRef = useRef<number>(0)

  const clearAuthState = useCallback(() => {
    setUser(null); setRole(null); setName(null); setIsAuthenticated(false);
    utils.persistUser(null);
    utils.blockAutoLogin();
  }, [])

  const postBC = useCallback((type: string, payload?: any) => {
    if (!bcRef.current) return
    try { bcRef.current.postMessage({ type, payload, ts: Date.now() }) } catch { /* noop */ }
  }, [])

  const checkAuthStatus = useCallback(async (opts?: { background?: boolean; force?: boolean }) => {
    if (opts?.background && meAbortRef.current && meActiveOptsRef.current && !meActiveOptsRef.current.background) return
    if (opts?.background && lastInflightRxAtRef.current && (Date.now() - lastInflightRxAtRef.current) < utils.INFLIGHT_SUPPRESSION_WINDOW_MS) return

    if (!opts?.force) {
      const cached = utils.getCachedUser()
      if (cached) {
        setUser(cached); setRole(cached.role); setName(cached.fullname);
        setIsAuthenticated(true); setLoading(false);
        utils.prefetchRoleRoutes(cached.role);
        return
      }
    }

    if (utils.isAutoLoginBlocked()) { setLoading(false); return }

    const since429 = Date.now() - (last429AtRef.current || 0)
    if (last429AtRef.current && since429 < utils.RATE_LIMIT_COOLDOWN_MS) {
      if (opts?.background) return
      if (utils.readPersistedUser()) { setLoading(false); return }
    }

    if (meAbortRef.current) meAbortRef.current.abort()
    const ctrl = new AbortController()
    meAbortRef.current = ctrl
    meActiveOptsRef.current = { background: !!opts?.background }

    if (!opts?.background) setLoading(true)
    postBC('me:inflight')

    try {
      const profile = await withAuthTimeout(getUserProfile({ signal: ctrl.signal }), ctrl)
      if (meAbortRef.current !== ctrl || ctrl.signal.aborted) return

      const userFromApi = (profile as any)?.user ?? (profile as any)?.data?.user ?? null
      if (userFromApi) {
        const canon = normalizeRole(userFromApi.role) || userFromApi.role
        const normalizedUser = { ...userFromApi, role: canon } as User
        setUser(normalizedUser); setRole(canon); setName(normalizedUser.fullname);
        setIsAuthenticated(true); utils.persistUser(normalizedUser);
        utils.prefetchRoleRoutes(canon);
        postBC('me:success', { user: normalizedUser })
      } else {
        clearAuthState()
      }
    } catch (error: any) {
      if (error?.name !== 'CanceledError') clearAuthState()
    } finally {
      if (meAbortRef.current === ctrl && !meActiveOptsRef.current?.background) setLoading(false)
    }
  }, [clearAuthState, postBC])

  useEffect(() => {
    const persisted = utils.readPersistedUser()
    if (persisted) {
      setUser(persisted); setRole(persisted.role); setName(persisted.fullname);
      setIsAuthenticated(true); setLoading(false);
      utils.prefetchRoleRoutes(persisted.role);
      checkAuthStatus({ background: true, force: true })
    } else {
      checkAuthStatus()
    }
    return () => meAbortRef.current?.abort()
  }, [checkAuthStatus])

  // Sync between tabs
  useEffect(() => {
    const BC = (globalThis as any).BroadcastChannel
    if (!BC) return
    const bc = new BC(utils.AUTH_BC_NAME)
    bcRef.current = bc
    bc.onmessage = (ev: any) => {
      const { type, payload } = ev.data
      if (type === 'me:success' && payload?.user) {
        const u = payload.user; const canon = normalizeRole(u.role) || u.role
        setUser({ ...u, role: canon }); setRole(canon); setName(u.fullname);
        setIsAuthenticated(true); setLoading(false);
      } else if (type === 'logout') {
        clearAuthState(); navigate('/');
      }
    }
    return () => bc.close()
  }, [clearAuthState, navigate])

  const login = useCallback((userData?: User, token?: string) => {
    if (userData) {
      const canon = normalizeRole(userData.role) || userData.role
      const normalized = { ...userData, role: canon as any } as User
      setUser(normalized); setRole(normalized.role); setName(normalized.fullname);
      setIsAuthenticated(true); utils.persistUser(normalized);
      utils.prefetchRoleRoutes(normalized.role);
      const roleToPath: any = { [Role.Administrador]: '/admin/dashboard', [Role.Instructor]: '/instructor/dashboard', [Role.Aprendiz]: '/apprentice/dashboard' }
      navigate(roleToPath[normalized.role as Role] || '/admin/dashboard')
    } else {
      clearAuthState(); navigate('/')
    }
  }, [clearAuthState, navigate])

  const logout = useCallback(async () => {
    try { await authServiceLogout() } catch { /* ignore */ }
    clearAuthState(); postBC('logout'); navigate('/');
  }, [clearAuthState, navigate, postBC])

  const { hasPermission } = usePermissions(user, isAuthenticated)
  useLocationSync(user, isAuthenticated)

  const value = useMemo<AuthContextType>(() => ({
    user, role: role as any, name, loading, isAuthenticated,
    login, logout, checkAuthStatus, refreshUserData: () => checkAuthStatus({ force: true }),
    enableRoleSwitch, hasPermission,
    impersonateRole: (r: any) => {
      if (!enableRoleSwitch || !user) return
      const newUser = { ...user, role: r } as User
      setUser(newUser); setRole(r); utils.persistUser(newUser);
      navigate('/admin/dashboard', { replace: true })
    }
  }), [user, role, name, loading, isAuthenticated, login, logout, checkAuthStatus, enableRoleSwitch, hasPermission, navigate])

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}

import React, { createContext, useContext, useState, useCallback, ReactNode } from 'react';
import { getApiBaseURL } from '@/shared/utils/envConfig';
import { API_CONFIG } from '@/shared/api/config';
import { hasSessionCookies } from '@/shared/utils/cookieUtils';
import { speciesService } from '@/entities/species/api/species.service';
import { breedsService } from '@/entities/breed/api/breeds.service';
import { fieldService } from '@/entities/field/api/field.service';
import { diseaseService } from '@/entities/disease/api/disease.service';
import { medicationsService } from '@/entities/medication/api/medications.service';
import { vaccinesService } from '@/entities/vaccine/api/vaccines.service';
import { foodTypesService } from '@/entities/food-type/api/foodTypes.service';
import { animalService } from '@/entities/animal/api/animal.service';

interface CacheEntry<T> {
  data: T;
  timestamp: number;
  expiry: number;
}

interface CacheContextType {
  getCache: <T>(key: string) => T | null;
  setCache: <T>(key: string, data: T, ttl?: number) => void;
  invalidateCache: (key: string) => void;
  invalidatePattern: (pattern: string) => void;
  // Nuevo: invalidar por endpoint real (coincide con las claves generadas por useCacheKey)
  invalidateByEndpoint: (endpoint: string) => void;
  clearCache: () => void;
  preloadData: <T>(key: string, fetchFn: () => Promise<T>, ttl?: number) => Promise<T>;
  preloadCriticalRoutes: () => void;
}

const CacheContext = createContext<CacheContextType | undefined>(undefined);

export const useCache = () => {
  const context = useContext(CacheContext);
  if (context === undefined) {
    throw new Error('useCache must be used within a CacheProvider');
  }
  return context;
};

interface CacheProviderProps {
  children: ReactNode;
  defaultTTL?: number; // Time to live en milisegundos
}

// Persistencia priorizando localStorage (fallback a sessionStorage) con TTL + tolerancia offline
const CACHE_PREFIX = 'offline_cache_v2:';
const OFFLINE_GRACE_MS = 24 * 60 * 60 * 1000; // 24h de gracia para redes intermitentes

const getPreferredStorage = (): Storage | null => {
  try {
    if (typeof window === 'undefined') return null;
    if (window.localStorage) return window.localStorage;
    if (window.sessionStorage) return window.sessionStorage;
    return null;
  } catch {
    return null;
  }
};

const storageGet = (k: string): string | null => {
  const storage = getPreferredStorage();
  if (!storage) return null;
  try { return storage.getItem(k); } catch { return null; }
};
const storageSet = (k: string, v: string) => {
  const storage = getPreferredStorage();
  if (!storage) return;
  try { storage.setItem(k, v); } catch { /* quota/disabled */ }
};
const storageRemove = (k: string) => {
  const storage = getPreferredStorage();
  if (!storage) return;
  try { storage.removeItem(k); } catch { /* noop */ }
};
const storageKeys = (): string[] => {
  const storage = getPreferredStorage();
  if (!storage) return [];
  try {
    return Array.from({ length: storage.length }, (_, i) => storage.key(i)!).filter(Boolean) as string[];
  } catch {
    return [];
  }
};

const isOffline = (): boolean => {
  try {
    return typeof navigator !== 'undefined' && navigator.onLine === false;
  } catch {
    return false;
  }
};

const getCurrentFincaId = (): number | string | null => {
  try {
    if (typeof window === 'undefined') return null;
    const raw = window.sessionStorage?.getItem('auth:user');
    const parsed = raw ? JSON.parse(raw) : null;
    const user = parsed?.user ?? parsed;
    return user?.finca_id ?? user?.finca?.id ?? user?.active_finca_id ?? user?.current_finca_id ?? null;
  } catch {
    return null;
  }
};

// Hook para generar claves de cache consistentes y multi-tenant
export const useCacheKey = (fincaId?: number) => {
  const generateKey = useCallback((endpoint: string, params?: Record<string, any>): string => {
    const apiBaseURL = getApiBaseURL();
    // Incluir finca_id en la clave base para aislamiento multi-tenant
    const resolvedFincaId = fincaId ?? getCurrentFincaId();
    const fincaSuffix = resolvedFincaId ? `@finca:${resolvedFincaId}` : '';
    const baseKey = `${apiBaseURL}/${endpoint}${fincaSuffix}`;
    
    if (!params || Object.keys(params).length === 0) {
      return baseKey;
    }
    
    // Ordenar parámetros para consistencia
    const sortedParams = Object.keys(params)
      .sort()
      .reduce((result, key) => {
        result[key] = params[key];
        return result;
      }, {} as Record<string, any>);
    
    const paramString = JSON.stringify(sortedParams);
    return `${baseKey}:${btoa(paramString)}`;
  }, [fincaId]);

  return { generateKey };
};

export const CacheProvider: React.FC<CacheProviderProps> = ({
  children,
  defaultTTL = 5 * 60 * 1000 // 5 minutos por defecto (optimizado para primera carga)
}) => {
  const [cache, setCache] = useState<Map<string, CacheEntry<any>>>(new Map());
  const [, setPreloadQueue] = useState<string[]>([]);

  const getCache = useCallback(<T,>(key: string): T | null => {
    const now = Date.now();
    const offline = isOffline();

    const purgeKey = () => {
      const mem = new Map(cache);
      mem.delete(key);
      setCache(mem);
      storageRemove(CACHE_PREFIX + key);
    };

    // 1) Intentar en memoria
    const inMem = cache.get(key);
    if (inMem) {
      const offlineAllowedUntil = inMem.expiry + OFFLINE_GRACE_MS;
      const expired = now > inMem.expiry;
      if (expired && !(offline && now <= offlineAllowedUntil)) {
        purgeKey();
        return null;
      }
      return inMem.data as T;
    }

    // 2) Intentar desde storage persistente (hidratar si válido).
    // En línea preferimos red para evitar que una finca vea un listado vacío/stale de otra sesión.
    if (!offline && !API_CONFIG.idbReadOnline) {
      return null;
    }

    const raw = storageGet(CACHE_PREFIX + key);
    if (raw) {
      try {
        const parsed = JSON.parse(raw) as CacheEntry<T>;
        if (parsed && typeof parsed.expiry === 'number') {
          const offlineAllowedUntil = parsed.expiry + OFFLINE_GRACE_MS;
          const expired = now > parsed.expiry;
          if (expired && !(offline && now <= offlineAllowedUntil)) {
            storageRemove(CACHE_PREFIX + key);
            return null;
          }
          const mem = new Map(cache);
          mem.set(key, parsed);
          setCache(mem);
          return parsed.data as T;
        }
        storageRemove(CACHE_PREFIX + key);
      } catch {
        storageRemove(CACHE_PREFIX + key);
      }
    }

    return null;
  }, [cache]);

  const setCacheData = useCallback(<T,>(key: string, data: T, ttl?: number): void => {
    const timeToLive = ttl || defaultTTL;
    const entry: CacheEntry<T> = {
      data,
      timestamp: Date.now(),
      expiry: Date.now() + timeToLive
    };
    // memoria
    const newCache = new Map(cache);
    newCache.set(key, entry);
    setCache(newCache);
    // persistencia
    try { storageSet(CACHE_PREFIX + key, JSON.stringify(entry)); } catch { /* noop */ }
  }, [cache, defaultTTL]);

  const invalidateCache = useCallback((key: string): void => {
    const newCache = new Map(cache);
    newCache.delete(key);
    setCache(newCache);
    // eliminar persistencia
    storageRemove(CACHE_PREFIX + key);
  }, [cache]);

  const invalidatePattern = useCallback((pattern: string): void => {
    const newCache = new Map(cache);
    const regex = new RegExp(pattern);
    // memoria
    for (const key of newCache.keys()) {
      if (regex.test(key)) {
        newCache.delete(key);
      }
    }
    setCache(newCache);
    // storage (buscar por prefijo y probar la parte de la clave)
    for (const k of storageKeys()) {
      if (!k || !k.startsWith(CACHE_PREFIX)) continue;
      const logicalKey = k.slice(CACHE_PREFIX.length);
      if (regex.test(logicalKey)) {
        storageRemove(k);
      }
    }
  }, [cache]);

  // Invalidación consistente por endpoint real
  const invalidateByEndpoint = useCallback((endpoint: string): void => {
    const apiBaseURL = getApiBaseURL();
    // Normalizar endpoint para evitar dobles barras
    const normalized = (endpoint || '').replace(/^\/+/, '');
    const escapeRegex = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    // Las claves generadas por useCacheKey son `${apiBaseURL}/${endpoint}` + opcional `:<paramsBase64>`
    const prefix = `^${escapeRegex(`${apiBaseURL}/${normalized}`)}`;
    try {
      invalidatePattern(prefix);
    } catch (e) {
      // fallback defensivo
      console.warn('[CacheContext] invalidateByEndpoint fallback using invalidatePattern', e);
      invalidatePattern(prefix);
    }
  }, [invalidatePattern]);

  const clearCache = useCallback((): void => {
    setCache(new Map());
    // remover todas las entradas del prefijo
    for (const k of storageKeys()) {
      if (k && k.startsWith(CACHE_PREFIX)) {
        storageRemove(k);
      }
    }
  }, []);

  // Estrategia de precarga inteligente
  const preloadData = useCallback(async (key: string, fetchFn: () => Promise<any>, ttl?: number) => {
    // Verificar si ya está en caché y es válido
    const existing = getCache(key);
    if (existing) {
      return existing;
    }

    // Añadir a la cola de precarga si no está ya en proceso
    setPreloadQueue(prev => {
      if (prev.includes(key)) {
        return prev;
      }
      return [...prev, key];
    });

    try {
      const data = await fetchFn();
      setCacheData(key, data, ttl);
      return data;
    } catch (error) {
      console.warn(`[CacheContext] Error en precarga de ${key}:`, error);
      throw error;
    } finally {
      // Remover de la cola de precarga
      setPreloadQueue(prev => prev.filter(k => k !== key));
    }
  }, [getCache, setCacheData]);

  const value: CacheContextType = {
    getCache,
    setCache: setCacheData,
    invalidateCache,
    invalidatePattern,
    invalidateByEndpoint,
    clearCache,
    preloadData,
    preloadCriticalRoutes: () => {
      // Gate: Solo precargar si hay cookies de sesión (evitar 401 en boot)
      if (!hasSessionCookies()) return;

      console.log('[Cache] Iniciando precarga de datos maestros...');

      // Precarga paralela de entidades base (alta prioridad)
      void speciesService.getPaginated({ limit: 100 }).catch(() => {});
      void breedsService.getPaginated({ limit: 200 }).catch(() => {});
      void fieldService.getPaginated({ limit: 50 }).catch(() => {});

      // Precarga de entidades de apoyo (media prioridad)
      setTimeout(() => {
        if (!hasSessionCookies()) return;
        void diseaseService.getAll().catch(() => {});
        void vaccinesService.getAll().catch(() => {});
        void medicationsService.getAll().catch(() => {});
      }, 2000);
    }
  };

  return (
    <CacheContext.Provider value={value}>
      {children}
    </CacheContext.Provider>
  );
};

