/**
 * Helper component to handle redirects with dynamic params.
 * Declared at the top to prevent ReferenceErrors during component initialization.
 */
function NavigateWithParam({ param }: { param: string }) {
  const { id } = useParams();
  const location = useLocation();
  const pathSegments = location.pathname.split('/');
  // El padre es el segmento anterior al último (que es 'create' o 'edit')
  const parentPath = pathSegments.slice(0, -1).join('/');
  
  if (param === 'edit' && id) {
    return <Navigate to={`${parentPath}?edit=${id}`} replace />;
  }
  
  return <Navigate to={`${parentPath}?${param}`} replace />;
}

