import { useMemo } from 'react';
import { alertService, AlertConfig, Alert } from '@/entities/alert/api/alert.service';
import { animalsService } from '@/entities/animal/api/animal.service';
import { controlService } from '@/entities/control/api/control.service';
import { milkService } from '@/entities/milk/api/milk.service';
import { animalFieldsService } from '@/entities/animal-field/api/animalFields.service';
import { useResource } from '@/shared/hooks/useResource';
import { evaluateCondition, getValueByDimension } from '@/shared/utils/conditionEvaluator';

/**
 * Motor de Evaluación Local de Alertas
 * Compara los datos locales (animales y controles) con las reglas configuradas
 * para generar alertas virtuales sin necesidad de conexión.
 */
export const useAlertEngine = () => {
  // 1. Obtener reglas (Configs)
  const { data: configs } = useResource<AlertConfig[]>(
    { 
      getAll: () => alertService.getConfigs(),
      getPaginated: async (params: any) => {
        const data = await alertService.getConfigs(params);
        return { data, total: data.length, page: 1, limit: data.length, totalPages: 1 };
      }
    } as any,
    { key: 'alert-configs', cache: true }
  );

  // 2. Obtener datos operativos
  const { data: animals } = useResource<any[]>(
    { 
      getAll: () => animalsService.getAnimals({ limit: 1000 }),
      getPaginated: async (params: any) => {
        const data = await animalsService.getAnimals({ ...params, limit: 1000 });
        return { data, total: data.length, page: 1, limit: data.length, totalPages: 1 };
      }
    } as any,
    { key: 'animals-local', cache: true }
  );

  const { data: controls } = useResource<any[]>(
    { 
      getAll: () => controlService.getAll({ limit: 1000 }),
      getPaginated: async (params: any) => {
        const data = await controlService.getAll({ ...params, limit: 1000 });
        return { data, total: data.length, page: 1, limit: data.length, totalPages: 1 };
      }
    } as any,
    { key: 'controls-local', cache: true }
  );

  const { data: milkRecords } = useResource<any[]>(
    { 
      getAll: () => milkService.getAll({ limit: 1000 }),
      getPaginated: async (params: any) => {
        const data = await milkService.getAll({ ...params, limit: 1000 });
        return { data, total: data.length, page: 1, limit: data.length, totalPages: 1 };
      }
    } as any,
    { key: 'milk-local', cache: true }
  );

  const { data: fieldAssignments } = useResource<any[]>(
    { 
      getAll: () => animalFieldsService.getAnimalFields({ limit: 1000 }),
      getPaginated: async (params: any) => {
        const resp = await animalFieldsService.getAnimalFields({ ...params, limit: 1000 });
        return resp;
      }
    } as any,
    { key: 'field-assignments-local', cache: true }
  );

  // 3. Evaluar reglas localmente
  const localAlerts = useMemo(() => {
    if (!configs || !animals) return [];

    const virtualAlerts: Alert[] = [];
    const activeConfigs = configs.filter(c => c.is_active);

    const extraData = {
      milkHistory: milkRecords || [],
      fieldAssignments: fieldAssignments || []
    };

    animals.forEach(animal => {
      // Obtener el último control de este animal
      const animalControls = (controls || [])
        .filter(c => c.animal_id === animal.id)
        .sort((a, b) => new Date(b.checkup_date || b.control_date).getTime() - new Date(a.checkup_date || a.control_date).getTime());

      const latestControl = animalControls[0];

      activeConfigs.forEach(config => {
        // Si la regla es para un animal específico y no es este, saltar
        if (config.animal_id && config.animal_id !== animal.id) return;

        const value = getValueByDimension(animal, latestControl, config.dimension, extraData);
        const isTriggered = evaluateCondition(value, config.condition_value);

        if (isTriggered) {
          virtualAlerts.push({
            animal_id: animal.id,
            alert_type: config.alert_type,
            message: `${animal.record}: ${config.message}`,
            priority: config.priority,
            is_read: false,
            triggered_at: new Date().toISOString(),
            config_id: config.id,
            recommendation: `Valor detectado: ${value}. Umbral: ${config.condition_value}`
          });
        }
      });
    });

    return virtualAlerts;
  }, [configs, animals, controls]);

  return {
    localAlerts,
    totalLocalCount: localAlerts.length,
    isLoading: !configs || !animals
  };
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { animalFieldsService } from '@/entities/animal-field/api/animalFields.service';
import { AnimalFields } from '@/entities/animal-field/model/types';
import type { AnimalFieldResponse, AnimalFieldInput } from '@/shared/api/generated/swaggerTypes';

export const useAnimalFields = () => {
    const [animalFields, setAnimalFields] = useState<AnimalFields[]>([]);
    const [loading, setLoading] = useState<boolean>(false);
    const [error, setError] = useState<string | null>(null);
    const [refreshing, setRefreshing] = useState<boolean>(false);
    const hasDataRef = useRef(false);

    const fetchAnimalFields = useCallback(async () => {
      const hasData = hasDataRef.current;
      if (hasData) setRefreshing(true); else setLoading(true);
      try {
  const data = await animalFieldsService.getAll();
  const normalized: AnimalFields[] = (Array.isArray(data) ? data : []).map(mapAnimalFieldResponseToLocal);
  setAnimalFields(normalized);
  hasDataRef.current = normalized.length > 0;
      } catch (err) {
        setError('Error al cargar los Potreros de animales');
      } finally {
        if (hasData) setRefreshing(false); else setLoading(false);
      }
    }, []);

    const addAnimalFields = async (animalFieldData: AnimalFields) => {
        setLoading(true);
        try {
          const payload: AnimalFieldInput = {
            animal_id: animalFieldData.animal_id,
            field_id: animalFieldData.field_id,
            assignment_date: animalFieldData.assignment_date,
            removal_date: animalFieldData.removal_date,
          };
          const newAnimalField = await animalFieldsService.create(payload as Partial<AnimalFieldInput>);
          setAnimalFields((prev) => [...prev, mapAnimalFieldResponseToLocal(newAnimalField as AnimalFieldResponse)]);
        } catch (err) {
          setError('Error al agregar el campo de animal');
        } finally {
          setLoading(false);
        }
      };

      const editAnimalFields = async (id: number, animalFieldData: AnimalFields) => {
        setLoading(true);
        try {
          const payload: AnimalFieldInput = {
            animal_id: animalFieldData.animal_id,
            field_id: animalFieldData.field_id,
            assignment_date: animalFieldData.assignment_date,
            removal_date: animalFieldData.removal_date,
          };
          const updatedAnimalFieldData = await animalFieldsService.update(id, payload as Partial<AnimalFieldInput>); 
          setAnimalFields((prev) => prev.map((animalField) => animalField.id === id ? mapAnimalFieldResponseToLocal(updatedAnimalFieldData as AnimalFieldResponse) : animalField));
        } catch (err) {
          setError('Error al actualizar el campo de animal');
        } finally {
          setLoading(false);
        }
      };

      const deleteAnimalFields = async (id: number) => {
        setLoading(true);
        try {
          await animalFieldsService.delete(id);
          setAnimalFields((prev) => prev.filter((item) => item.id !== id));
        } catch (err) {
          setError('Error al eliminar el campo de animal');
        } finally {
          setLoading(false);
        }
      };

      useEffect(() => {
        fetchAnimalFields();
      }, [fetchAnimalFields]);

  return { animalFields, data: animalFields, loading, refreshing, error, fetchAnimalFields, refetch: fetchAnimalFields, addAnimalFields, editAnimalFields, deleteAnimalFields, deleteItem: deleteAnimalFields, createItem: addAnimalFields, updateItem: editAnimalFields };
};

function mapAnimalFieldResponseToLocal(r: AnimalFieldResponse): AnimalFields {
  // Normalizamos para que la tabla pueda acceder a fields.name y animals.record
  const rawAnimals: any = (r as any).animals;
  const rawFields: any = (r as any).fields;

  const animalsRecord = (rawAnimals?.record)
    || ((r as any).animal_record)
    || (rawAnimals?.name)
    || (r.animal_id ? `#${r.animal_id}` : '');

  const animals = rawAnimals ?? (
    ((r as any).animal_record || r.animal_id)
      ? { id: rawAnimals?.id ?? r.animal_id, record: animalsRecord }
      : undefined
  );

  const fieldName = (rawFields?.name)
    || ((r as any).field_name)
    || (r.field_id ? `#${r.field_id}` : '');

  const fields = rawFields ?? (
    ((r as any).field_name || r.field_id)
      ? { id: rawFields?.id ?? r.field_id, name: fieldName }
      : undefined
  );

  const assignment_date = (r as any).assignment_date ?? (r as any).treatment_date ?? '';
  const removal_date = (r as any).removal_date ?? (r as any).end_date ?? '';

  // Calcular duración si no viene desde el backend
  const computeDuration = (start?: string, end?: string): string => {
    if (!start) return '';
    const startDt = new Date(start);
    const endDt = end ? new Date(end) : new Date();
    if (isNaN(startDt.getTime()) || isNaN(endDt.getTime())) return '';
    const diffMs = endDt.getTime() - startDt.getTime();
    if (diffMs < 0) return '';
    const days = Math.ceil(diffMs / (1000 * 60 * 60 * 24));
    return `${days} días`;
  };

  const duration = (r as any).duration ?? computeDuration(assignment_date, removal_date || undefined);

  return {
    id: r.id,
    animal_id: r.animal_id,
    field_id: r.field_id,
    assignment_date,
    removal_date,
    duration,
    reason: (r as any).reason,
    notes: (r as any).notes,
    is_active: typeof (r as any).is_active === 'boolean' ? (r as any).is_active : !removal_date,
    status: typeof (r as any).status === 'string' ? (r as any).status : (!removal_date ? 'Dentro' : 'Fuera'),
    // compat fields para UI
    animal_record: (r as any).animal_record ?? animalsRecord,
    field_name: (r as any).field_name ?? fieldName,
    animals,
    fields,
  };
}

import { ControlResponse, AnimalsResponse } from '@/shared/api/generated/swaggerTypes';

export interface HealthInsight {
  status: 'optimal' | 'warning' | 'critical';
  message: string;
  trend: 'up' | 'down' | 'stable';
  score: number; // 0-100
}

/**
 * HealthAnalyzer: IA Local para análisis de salud animal en campo.
 */
export class HealthAnalyzer {
  /**
   * Analiza el estado de un animal basado en sus controles históricos (en caché).
   */
  static analyze(animal: any, controls: ControlResponse[]): HealthInsight {
    if (!controls || controls.length === 0) {
      return { 
        status: 'warning', 
        message: 'Sin historial suficiente para diagnóstico.', 
        trend: 'stable', 
        score: 50 
      };
    }

    // Ordenar por fecha descendente
    const sorted = [...controls].sort((a, b) => 
      new Date(b.checkup_date).getTime() - new Date(a.checkup_date).getTime()
    );

    const latest = sorted[0];
    const previous = sorted[1];

    let trend: 'up' | 'down' | 'stable' = 'stable';
    let score = 70;
    let status: HealthInsight['status'] = 'optimal';
    let message = 'Estado general saludable.';

    // 1. Análisis de Peso (Crecimiento)
    if (latest.weight && previous?.weight) {
      const diff = latest.weight - previous.weight;
      if (diff > 0) trend = 'up';
      else if (diff < 0) {
        trend = 'down';
        score -= 20;
        message = 'Pérdida de peso detectada. Revisar nutrición.';
      }
    }

    // 2. Análisis de Estado de Salud
    if (latest.health_status === 'Malo' || latest.health_status === 'Regular') {
      status = latest.health_status === 'Malo' ? 'critical' : 'warning';
      score -= 30;
      message = `Reportado con estado ${latest.health_status}.`;
    }

    // 3. Análisis de Frecuencia de Control
    const daysSinceLast = (Date.now() - new Date(latest.checkup_date).getTime()) / (1000 * 60 * 60 * 24);
    if (daysSinceLast > 30) {
      status = 'warning';
      message = 'Control veterinario vencido (>30 días).';
      score -= 10;
    }

    if (score < 40) status = 'critical';
    else if (score < 70) status = 'warning';

    return { status, message, trend, score };
  }
}

import { BaseService } from '@/shared/api/base-service';
import { AnimalResponse, AnimalInput, AnimalStatistics, PaginatedResponse } from '@/shared/api/generated/swaggerTypes';
import { BulkResponse } from '@/shared/types/common.types';
import analyticsService from '@/features/reporting/api/analytics.service';
import { checkAnimalDependencies, clearAnimalDependencyCache } from '@/features/diagnostics/api/dependencyCheck.service';
import type { AnimalTreeGraph, TreeQueryParams } from '@/entities/animal/model/tree.types';

interface AnimalStatusStats {
  by_status: Record<string, number>;
  total_animals: number;
}

class AnimalsService extends BaseService<AnimalResponse> {
  constructor() {
    super('animals', {
      enableCache: true,
      preferredListKeys: ['animals', 'results'],
    });
  }

  // Normaliza valores de sexo a forma canónica ("Macho" | "Hembra")
  private normalizeSex(value: any): 'Macho' | 'Hembra' | undefined {
    if (!value && value !== 0) return undefined;
    const s = String(value).trim().toLowerCase();
    if (s === 'm' || s === 'male' || s === 'macho' || s === '1' || s === '01') return 'Macho';
    if (s === 'f' || s === 'female' || s === 'hembra' || s === '2' || s === '02') return 'Hembra';
    // Fallback: si viene ya correcto, respétalo
    if (s === 'macho') return 'Macho';
    if (s === 'hembra') return 'Hembra';
    return undefined;
  }

  // Detecta si el término de búsqueda parece una fecha o año (para habilitar búsqueda por columnas de fecha)
  private isDateLike(term: any): boolean {
    if (term === null || term === undefined) return false;
    const s = String(term).trim();
    if (!s) return false;
    // Año (YYYY)
    if (/^\d{4}$/.test(s)) return true;
    // Formatos comunes de fecha: YYYY-MM-DD, DD/MM/YYYY, DD-MM-YYYY, YYYY/MM/DD, YYYY-MM-DD
    if (/^\d{4}[-/]\d{1,2}[-/]\d{1,2}$/.test(s)) return true;
    if (/^\d{1,2}[-/]\d{1,2}[-/]\d{2,4}$/.test(s)) return true;
    return false;
  }

  // Enriquece parámetros para que el backend busque también en columnas de fecha cuando el término es un año/fecha
  private enrichParamsForDateSearch(params: Record<string, any> = {}): Record<string, any> {
    const searchTerm = params.search ?? params.q;
    if (!this.isDateLike(searchTerm)) return params;

    const extraDateFields = ['birth_date', 'created_at', 'updated_at'];
    const existingFields = (params.fields ? String(params.fields) : '').split(',').map(f => f.trim()).filter(Boolean);
    const merged = Array.from(new Set([...existingFields, ...extraDateFields]));

    return {
      ...params,
      // Forzar que ambos parámetros se envíen por compatibilidad y que fields incluya columnas de fecha
      search: searchTerm,
      q: searchTerm,
      fields: merged.join(','),
    };
  }

  // Normaliza estado a forma canónica usada en UI
  private normalizeStatus(value: any): string | undefined {
    if (value === null || value === undefined) return undefined;
    const s = String(value).trim().toLowerCase();
    if (s === 'vivo' || s === 'activo' || s === 'alive') return 'Activo';
    if (s === 'muerto' || s === 'dead' || s === 'fallecido') return 'Muerto';
    if (s === 'vendido' || s === 'sold') return 'Vendido';
    if (s === 'inactivo' || s === 'inactive') return 'Inactivo';
    return value as string;
  }

  // Mapea estado del UI a valores aceptados por backend
  private mapStatusToBackend(value: any): 'Vivo' | 'Muerto' | 'Vendido' | undefined {
    if (value === null || value === undefined) return undefined;
    const s = String(value).trim().toLowerCase();
    if (s === 'vivo' || s === 'activo' || s === 'alive') return 'Vivo';
    if (s === 'muerto' || s === 'dead' || s === 'fallecido') return 'Muerto';
    if (s === 'vendido' || s === 'sold') return 'Vendido';
    // "inactivo" no es aceptado por backend; omitir para que use default si existe
    return undefined;
  }

  // Construye payload compatible con backend (sex, breeds_id, etc.)
  private buildApiPayload(data: Partial<AnimalInput> & { [k: string]: any }): Record<string, any> {

    const birthDate = this.parseDate(data.birth_date ?? (data as any).birthDate);
    const sex = this.normalizeSex(data.gender ?? (data as any).sex ?? (data as any).sexo);
    const breedsId = data.breed_id ?? (data as any).breeds_id ?? (data as any).raza_id ?? (data as any).breedId;
    const status = this.mapStatusToBackend(data.status ?? (data as any).estado);



    // Validar campos requeridos por el backend
    if (!sex) {
      throw new Error('El campo "gender/sex" es requerido y no puede estar vacío');
    }
    if (!breedsId || breedsId <= 0) {
      throw new Error('El campo "breed_id/breeds_id" es requerido y debe ser mayor a 0');
    }
    if (data.weight === undefined || data.weight === null) {
      throw new Error('El campo "weight" es requerido');
    }

    const payload: Record<string, any> = {
      record: data.record ?? (data as any).code ?? (data as any).registro,
      birth_date: birthDate,
      weight: data.weight,
      breeds_id: breedsId,
      sex,
      status,
      idFather: data.father_id ?? data.idFather,
      idMother: data.mother_id ?? data.idMother,
      notes: data.notes ?? (data as any).observations ?? (data as any).observaciones,
      entry_date: this.parseDate(data.entry_date),
      purchase_date: this.parseDate(data.purchase_date),
      sale_date: this.parseDate(data.sale_date),
      exit_date: this.parseDate(data.exit_date),
      exit_reason: data.exit_reason,
    };



    // Eliminar claves con undefined/null/0 inválidos (pero mantener weight=0 como válido)
    Object.keys(payload).forEach((k) => {
      const v = (payload as any)[k];
      // Eliminar undefined, null, strings vacíos
      if (v === undefined || v === null || (typeof v === 'string' && !v.trim())) {
        delete (payload as any)[k];
      }
      // Eliminar breeds_id si es 0 o negativo (valor inválido)
      else if (k === 'breeds_id' && (typeof v === 'number') && v <= 0) {

        delete (payload as any)[k];
      }
      // Eliminar idFather/idMother si son 0 (significa "sin padre/madre")
      else if ((k === 'idFather' || k === 'idMother') && v === 0) {
        delete (payload as any)[k];
      }
    });


    return payload;
  }

  private parseDate(value: any): string | undefined {
    if (!value) return undefined;
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (value instanceof Date) return value.toISOString().slice(0, 10);
    const v = (value as any)?.$d;
    if (v instanceof Date) return v.toISOString().slice(0, 10);
    return undefined;
  }

  private computeAgeDays(birth_date?: string): number | undefined {
    if (!birth_date) return undefined;
    const bd = new Date(birth_date);
    if (isNaN(bd.getTime())) return undefined;
    const now = new Date();
    const diffMs = now.getTime() - bd.getTime();
    return Math.floor(diffMs / (1000 * 60 * 60 * 24));
  }

  private normalizeAnimal(item: any): AnimalResponse & { [k: string]: any } {
    const birth_date = this.parseDate(item?.birth_date ?? item?.birthDate);
    const age_in_days = item?.age_in_days ?? this.computeAgeDays(birth_date);
    const age_in_months = item?.age_in_months ?? (typeof age_in_days === 'number' ? Math.floor(age_in_days / 30) : undefined);
    const gender = this.normalizeSex(item?.gender ?? item?.sex ?? item?.sexo ?? item?.genero);

    // Asegurar que breeds_id se mapee correctamente a breed_id para compatibilidad con la UI
    const breedsId = item?.breeds_id;
    const breedId = item?.breed_id ?? item?.breedId ?? item?.raza_id;

    return {
      // Mantener otros campos originales por compatibilidad (pero SIN sobreescribir normalizaciones)
      ...item,

      // IDs y códigos
      id: item?.id ?? item?.idAnimal ?? item?.animal_id,
      record: item?.record ?? item?.code ?? item?.registro ?? '',
      name: item?.name ?? item?.nombre,
      // Fechas y métricas
