import { BaseService } from '@/shared/api/base-service';
import api from '@/shared/api/client';
import { apiFetch } from '@/shared/api/apiFetch';
import { ANIMAL_IMAGES_ENDPOINTS } from '@/shared/config/apiEndpoints';
import { getBackendBaseURL, getApiBaseURL, isDevelopment } from '@/shared/utils/envConfig';

const IMAGE_FETCH_CONCURRENCY = 4;
const IMAGE_FETCH_TIMEOUT_MS = 15000;
let imageFetchActive = 0;
const imageFetchQueue: Array<() => void> = [];
const imageFetchInflight = new Map<number, Promise<AnimalImagesResponse>>();

const acquireImageFetchSlot = () =>
  new Promise<void>((resolve) => {
    if (imageFetchActive < IMAGE_FETCH_CONCURRENCY) {
      imageFetchActive += 1;
      resolve();
      return;
    }
    imageFetchQueue.push(resolve);
  });

const releaseImageFetchSlot = () => {
  imageFetchActive = Math.max(0, imageFetchActive - 1);
  const next = imageFetchQueue.shift();
  if (next) {
    imageFetchActive += 1;
    next();
  }
};

/**
 * Interfaz para una imagen de animal
 */
export interface AnimalImage {
  id: number;
  animal_id: number;
  filename: string;
  filepath: string;
  file_size: number;
  mime_type: string;
  is_primary: boolean;
  url: string;
  created_at: string;
  updated_at: string;
}

/**
 * Respuesta al subir imágenes
 */
export interface ImageUploadResponse {
  success: boolean;
  message: string;
  data: {
    uploaded: AnimalImage[];
    total_uploaded: number;
    total_errors: number;
    errors?: Array<{
      filename: string;
      error: string;
    }> | null;
  };
}

/**
 * Respuesta al obtener imágenes de un animal
 */
export interface AnimalImagesResponse {
  success: boolean;
  message: string;
  data: {
    animal_id: number;
    total: number;
    images: AnimalImage[];
  };
  errorCode?: string;
  traceId?: string;
}

/**
 * Opciones para la subida de imágenes
 */
export interface UploadOptions {
  /** Callback para progreso de subida (0-100) */
  onProgress?: (progress: number) => void;
  /** Comprimir imágenes antes de subir */
  compress?: boolean;
  /** Calidad de compresión (0-1) */
  quality?: number;
  /** Tamaño máximo en bytes antes de comprimir */
  maxSizeBeforeCompress?: number;
}

/**
 * Servicio para gestionar imágenes de animales
 */
class AnimalImageService extends BaseService<AnimalImage> {
  constructor() {
    super('animal-images', {
      enableCache: true, // Habilitar caché para evitar re-peticiones constantes
      cacheTimeout: 5 * 60 * 1000, // 5 minutos
    });
  }

  /**
   * Sube múltiples imágenes para un animal
   * @param animalId ID del animal
   * @param files Array de archivos a subir
   * @param options Opciones de subida
   */
  async uploadImages(
    animalId: number,
    files: File[],
    options: UploadOptions = {}
  ): Promise<ImageUploadResponse> {
    const {
      onProgress,
      compress = false,
      quality = 0.8,
      maxSizeBeforeCompress = 1024 * 1024, // 1MB
    } = options;

    // Validaciones
    if (!animalId || animalId <= 0) {
      throw new Error('El ID del animal es requerido');
    }

    if (!files || files.length === 0) {
      throw new Error('Debe seleccionar al menos una imagen');
    }

    // Validar tipos de archivo
    const allowedTypes = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];
    for (const file of files) {
      if (!allowedTypes.includes(file.type)) {
        throw new Error(
          `Tipo de archivo no permitido: ${file.type}. Solo se permiten: ${allowedTypes.join(', ')}`
        );
      }
    }

    // Comprimir imágenes si está habilitado
    let processedFiles = files;
    if (compress) {
      processedFiles = await Promise.all(
        files.map((file) =>
          file.size > maxSizeBeforeCompress
            ? this.compressImage(file, quality)
            : Promise.resolve(file)
        )
      );
    }

    // Crear FormData
    const formData = new FormData();
    formData.append('animal_id', animalId.toString());

    for (const file of processedFiles) {
      formData.append('files', file);
    }

    // Enviar request
    try {
      const response = await api.post<ImageUploadResponse>(
        ANIMAL_IMAGES_ENDPOINTS.UPLOAD,
        formData,
        {
          // No especificar Content-Type para que el navegador lo establezca automáticamente
          // con el boundary correcto para multipart/form-data
          headers: {},
          onUploadProgress: (progressEvent) => {
            if (onProgress && progressEvent.total) {
              const percentCompleted = Math.round(
                (progressEvent.loaded * 100) / progressEvent.total
              );
              onProgress(percentCompleted);
            }
          },
        }
      );

      await this.clearCache();
      return response.data;
    } catch (error: any) {
      console.error('[AnimalImageService] Error uploading images:', error);
      throw this.handleUploadError(error);
    }
  }

  /**
   * Obtiene todas las imágenes de un animal
   * @param animalId ID del animal
   */
  async getAnimalImages(animalId: number): Promise<AnimalImagesResponse> {
    if (!animalId || animalId <= 0) {
      throw new Error('El ID del animal es requerido');
    }

    const cacheKey = `animal-images:${animalId}`;
    const cached = await this.getFromCache(cacheKey);
    if (cached) return cached as AnimalImagesResponse;

    const existing = imageFetchInflight.get(animalId);
    if (existing) return existing;

    const request = this.fetchAnimalImages(animalId, cacheKey);
    imageFetchInflight.set(animalId, request);
    request.finally(() => imageFetchInflight.delete(animalId));
    return request;
  }

  private async fetchAnimalImages(animalId: number, cacheKey: string): Promise<AnimalImagesResponse> {

    await acquireImageFetchSlot();
    try {
      const response = await api.get<AnimalImagesResponse>(
        ANIMAL_IMAGES_ENDPOINTS.GET_BY_ANIMAL(animalId),
        {
          params: { _ts: Date.now() },
          headers: { 'Cache-Control': 'no-cache' },
          timeout: IMAGE_FETCH_TIMEOUT_MS, // Timeout más agresivo para imágenes
          skipTimeoutRetry: true,
        }
      );

      // Asegurar que las URLs de las imágenes sean absolutas y evitar contenido mixto en dev
      if (response.data && response.data.data && response.data.data.images) {
        const backendBaseURL = getBackendBaseURL();
        const apiBaseURL = getApiBaseURL();
        const addVersionParam = (url: string, updatedAt?: string): string => {
          try {
            const hasProtocol = url.startsWith('http://') || url.startsWith('https://');
            if (hasProtocol) {
              const u = new URL(url);
              // usar updated_at si existe; si no, timestamp actual para asegurar recarga mínima
              const version = updatedAt ? String(new Date(updatedAt).getTime()) : String(Date.now());
              u.searchParams.set('v', version);
              return u.toString();
            }
            // URL relativa: agregar ?v= o &v=
            const concatChar = url.includes('?') ? '&' : '?';
            const version = updatedAt ? String(new Date(updatedAt).getTime()) : String(Date.now());
            return `${url}${concatChar}v=${version}`;
          } catch {
            return url;
          }
        };

        const buildStaticAssetUrl = (path: string, updatedAt?: string) => {
          const cleanPath = path.startsWith('/') ? path : `/${path}`;
          const backendBase = backendBaseURL.endsWith('/')
            ? backendBaseURL.slice(0, -1)
            : backendBaseURL;
          if (isDevelopment()) {
            try {
              if (typeof window !== 'undefined') {
                // Dejar que el dev server proxy /public o /static al backend
                return addVersionParam(cleanPath, updatedAt);
              }
            } catch {
              // noop - fallback a opciones siguientes
            }
            if (apiBaseURL.startsWith('/')) {
              const baseRel = apiBaseURL.endsWith('/') ? apiBaseURL.slice(0, -1) : apiBaseURL;
              return addVersionParam(`${baseRel}${cleanPath}`, updatedAt);
            }
          }
          return addVersionParam(`${backendBase}${cleanPath}`, updatedAt);
        };

        response.data.data.images = response.data.data.images.map((image: AnimalImage) => {
          // Si la URL ya es absoluta, respetarla para evitar 404 innecesarios
          if (image.url && (image.url.startsWith('http://') || image.url.startsWith('https://'))) {
            return { ...image, url: addVersionParam(image.url, image.updated_at) };
          }

          // Si la URL es relativa, construir URL adecuada según entorno
          if (image.url) {
            const imageUrl = image.url.startsWith('/') ? image.url : `/${image.url}`;

            if (imageUrl.startsWith('/public/images') || imageUrl.startsWith('/static/uploads')) {
              return {
                ...image,
                url: buildStaticAssetUrl(imageUrl, image.updated_at),
              };
            }

            // En desarrollo, enviar otras rutas relativas de API usando el proxy /api/v1
            if (isDevelopment()) {
              // Para otras rutas relativas de API, construir con /api/v1
              if (apiBaseURL.startsWith('/')) {
                const baseRel = apiBaseURL.endsWith('/') ? apiBaseURL.slice(0, -1) : apiBaseURL;
                return { ...image, url: addVersionParam(`${baseRel}${imageUrl}`, image.updated_at) };
              }
            }

            // En producción o cuando hay backend explícito, usar backend base
            const baseUrl = backendBaseURL.endsWith('/') ? backendBaseURL.slice(0, -1) : backendBaseURL;
            return { ...image, url: addVersionParam(`${baseUrl}${imageUrl}`, image.updated_at) };
          }

          return image;
        });
      }

      this.setCache(cacheKey, response.data);
      return response.data;
    } catch (error: any) {
      const status = error?.response?.status;
      const apiError = error?.response?.data?.error;

      if (status === 404 || apiError?.code === 'NOT_FOUND') {
        return {
          success: false,
          message: apiError?.message || 'Las imágenes solicitadas no existen o fueron eliminadas.',
          errorCode: apiError?.code || 'NOT_FOUND',
          traceId: apiError?.trace_id,
          data: {
            animal_id: animalId,
            total: 0,
            images: [],
          },
        };
      }

      console.error('[AnimalImageService] Error fetching images:', error);
      throw error;
    } finally {
      releaseImageFetchSlot();
    }
  }

  /**
   * Elimina una imagen específica
   * @param imageId ID de la imagen
   */
  async deleteImage(imageId: number): Promise<void> {
    if (!imageId || imageId <= 0) {
      throw new Error('El ID de la imagen es requerido');
    }

    try {
      await apiFetch({ url: ANIMAL_IMAGES_ENDPOINTS.DELETE(imageId), method: 'DELETE' });
      await this.clearCache();
    } catch (error: any) {
      const status = error?.response?.status;
      const message =
        error?.response?.data?.message ||
        error?.message ||
        'Error al eliminar imagen';

      // Si la imagen ya no existe en el servidor, considerar la operación exitosa
      if (status === 404 || status === 410) {
        console.warn('[AnimalImageService] Imagen ya no existe, se omite el error');
        return;
      }

      // Si la sesión expiró o el refresh falló, lanzar error controlado
      const isAuthError =
        status === 401 ||
        status === 403 ||
        (status === 500 && typeof error?.config?.url === 'string' && error.config.url.includes('/auth/refresh'));

      if (isAuthError) {
        const authError = new Error(
          message || 'La sesión expiró. Inicia sesión nuevamente para administrar imágenes.'
        );
        (authError as any).code = 'AUTH_REQUIRED';
        throw authError;
      }

      console.error('[AnimalImageService] Error deleting image:', error);
      throw error;
    }
  }

  /**
   * Establece una imagen como principal
   * @param imageId ID de la imagen
   */
  async setPrimaryImage(imageId: number): Promise<AnimalImage> {
    if (!imageId || imageId <= 0) {
      throw new Error('El ID de la imagen es requerido');
    }

    try {
      const response = await api.put<{ success: boolean; data: AnimalImage }>(
        ANIMAL_IMAGES_ENDPOINTS.SET_PRIMARY(imageId)
      );
      await this.clearCache();
      return response.data.data;
    } catch (error: any) {
      console.error('[AnimalImageService] Error setting primary image:', error);
      throw error;
    }
  }

  /**
   * Comprime una imagen antes de subirla
   * @param file Archivo a comprimir
   * @param quality Calidad de compresión (0-1)
   */
  private async compressImage(file: File, quality: number): Promise<File> {
    return new Promise((resolve) => {
      const reader = new FileReader();

      reader.onload = (e) => {
        const img = new Image();

        img.onload = () => {
          const canvas = document.createElement('canvas');
          const ctx = canvas.getContext('2d');

          if (!ctx) {
            resolve(file); // Si no hay contexto, retornar archivo original
            return;
          }

          // Calcular dimensiones manteniendo aspect ratio
          let width = img.width;
          let height = img.height;
          const maxDimension = 1920; // Máximo ancho/alto

          if (width > maxDimension || height > maxDimension) {
            if (width > height) {
              height = (height / width) * maxDimension;
              width = maxDimension;
            } else {
              width = (width / height) * maxDimension;
              height = maxDimension;
            }
          }

          canvas.width = width;
          canvas.height = height;

          // Dibujar imagen redimensionada
          ctx.drawImage(img, 0, 0, width, height);

          // Convertir a blob
          canvas.toBlob(
            (blob) => {
              if (!blob) {
                resolve(file);
                return;
              }

              // Crear nuevo archivo con el blob comprimido
              const compressedFile = new File([blob], file.name, {
                type: file.type,
                lastModified: Date.now(),
              });

              console.log(
                `[AnimalImageService] Imagen comprimida: ${file.name} (${(
                  file.size / 1024
                ).toFixed(2)}KB -> ${(compressedFile.size / 1024).toFixed(2)}KB)`
              );

              resolve(compressedFile);
            },
            file.type,
            quality
          );
        };

        img.onerror = () => {
          console.warn(
            '[AnimalImageService] Error al cargar imagen para compresión, usando original'
          );
          resolve(file);
        };

        img.src = e.target?.result as string;
      };

      reader.onerror = () => {
        console.warn(
          '[AnimalImageService] Error al leer archivo para compresión, usando original'
        );
        resolve(file);
      };

      reader.readAsDataURL(file);
    });
  }

  /**
   * Maneja errores de subida de imágenes
   */
  private handleUploadError(error: any): Error {
    const status = error?.response?.status;
    const data = error?.response?.data;

    if (status === 400) {
      return new Error(
        data?.message || 'Datos de solicitud inválidos. Verifique los archivos.'
      );
    }

    if (status === 404) {
      return new Error(
        data?.message || 'Animal no encontrado. Verifique el ID.'
      );
    }

    if (status === 413) {
      return new Error(
        data?.message ||
        'El archivo es demasiado grande. Tamaño máximo: 5MB por archivo.'
      );
    }

    if (status === 415) {
      return new Error(
        data?.message ||
        'Tipo de archivo no permitido. Solo se permiten: JPG, PNG, WEBP, GIF.'
      );
    }

    return new Error(
      data?.message || error?.message || 'Error al subir las imágenes'
    );
  }
}

export const animalImageService = new AnimalImageService();

import { useState, useCallback } from 'react';
import { animalsService } from '@/entities/animal/api/animal.service';
import { animalDependenciesService } from '@/entities/animal/api/animalDependencies.service';
import type { AnimalTreeGraph, TreeLoadMoreOptions } from '@/entities/animal/model/tree.types';
import { getIndexedDBCache, setIndexedDBCache } from '@/shared/api/cache/indexedDBCache';

const DEFAULT_TTL_MS = 8 * 60 * 1000; // 8 minutos (recomendado 5–10 min)

function normalizeFieldsSig(fields?: string): string {
  if (!fields) return 'all';
  const list = fields.split(',').map(s => s.trim()).filter(Boolean).sort();
  return list.join(',');
}

function cacheKey(type: 'ancestors' | 'descendants', rootId: number, maxDepth: number, fields?: string): string {
  const sig = normalizeFieldsSig(fields);
  return `animal_tree:${type}:${rootId}:d${maxDepth}:f${sig}`;
}

function dedupeEdges(edges: AnimalTreeGraph['edges']): AnimalTreeGraph['edges'] {
  const seen = new Set<string>();
  const out: AnimalTreeGraph['edges'] = [];
  for (const e of edges) {
    const key = `${e.from}-${e.to}-${e.relation}`;
    if (!seen.has(key)) {
      seen.add(key);
      out.push(e);
    }
  }
  return out;
}

function mergeGraphs(a: AnimalTreeGraph, b: AnimalTreeGraph): AnimalTreeGraph {
  const nodes = { ...a.nodes, ...b.nodes };
  const edges = dedupeEdges([...(a.edges || []), ...(b.edges || [])]);
  return {
    rootId: a.rootId,
    nodes,
    edges,
    depth: Math.max(a.depth || 0, b.depth || 0),
    counts: { nodes: Object.keys(nodes).length, edges: edges.length },
    generated_at: Math.max(a.generated_at || 0, b.generated_at || 0),
    type: a.type || b.type,
  };
}

// Construye niveles ascendente (padres) desde grafo plano
export function graphToAncestorLevels(graph: AnimalTreeGraph): any[][] {
  if (!graph || !graph.nodes || !graph.rootId) return [];

  const levels: any[][] = [];
  const root = graph.nodes[graph.rootId];
  if (!root) return [];

  levels.push([root]);
  let current = [root];

  // Pre-construir mapas de relaciones para mejor rendimiento
  const parentsMap = new Map<number, any[]>();
  const getNode = (id?: number) => (id ? graph.nodes[id] : undefined);

  // Detectar orientación de aristas: padre->hijo (esperada) vs hijo->padre (invertida)
  const edges = graph.edges || [];
  const towardRoot = edges.filter(e => e.to === graph.rootId).length;
  const fromRoot = edges.filter(e => e.from === graph.rootId).length;
  const inverted = fromRoot > towardRoot; // si hay más aristas desde la raíz que hacia la raíz, asumimos invertidas

  // Construir mapa de padres para cada nodo según orientación
  for (const edge of edges) {
    // childId es el nodo para el cual buscaremos sus padres en el mapa
    const childId = inverted ? edge.from : edge.to;
    const parentId = inverted ? edge.to : edge.from;
    if (!parentsMap.has(childId)) parentsMap.set(childId, []);
    const parent = getNode(parentId);
    if (parent && parent.id) {
      parentsMap.get(childId)!.push(parent);
    }
  }

  // Si el backend reporta depth=0, usamos un fallback razonable (10)
  const maxDepth = graph.depth && graph.depth > 0 ? graph.depth : 10;
  for (let d = 1; d <= maxDepth; d++) {
    const next: any[] = [];
    const seen = new Set<number>();

    for (const node of current) {
      const nodeId = node?.id;
      if (!nodeId) continue;

      const parents = parentsMap.get(nodeId) || [];
      for (const parent of parents) {
        if (parent.id && !seen.has(parent.id)) {
          seen.add(parent.id);
          next.push(parent);
        }
      }
    }

    if (next.length === 0) break;
    levels.push(next);
    current = next;
  }

  return levels;
}

// Construye niveles descendente (hijos) desde grafo plano
export function graphToDescendantLevels(graph: AnimalTreeGraph): any[][] {
  if (!graph || !graph.nodes || !graph.rootId) return [];

  const levels: any[][] = [];
  const root = graph.nodes[graph.rootId];
  if (!root) return [];

  levels.push([root]);
  let current = [root];

  // Pre-construir mapas de relaciones para mejor rendimiento
  const childrenMap = new Map<number, any[]>();
  const getNode = (id?: number) => (id ? graph.nodes[id] : undefined);

  // Detectar orientación de aristas
  const edges = graph.edges || [];
  const towardRoot = edges.filter(e => e.to === graph.rootId).length;
  const fromRoot = edges.filter(e => e.from === graph.rootId).length;
  const inverted = towardRoot > fromRoot; // si hay más aristas hacia la raíz (hijo->padre), asumimos invertidas

  // Construir mapa de hijos según orientación
  for (const edge of edges) {
    // parentId es el nodo desde el que obtendremos sus hijos
    const parentId = inverted ? edge.to : edge.from;
    const childId = inverted ? edge.from : edge.to;
    if (!childrenMap.has(parentId)) childrenMap.set(parentId, []);
    const child = getNode(childId);
    if (child && child.id) {
      childrenMap.get(parentId)!.push(child);
    }
  }

  // Si el backend reporta depth=0, usamos un fallback razonable (10)
  const maxDepth = graph.depth && graph.depth > 0 ? graph.depth : 10;
  for (let d = 1; d <= maxDepth; d++) {
    const next: any[] = [];
    const seen = new Set<number>();

    for (const node of current) {
      const nodeId = node?.id;
      if (!nodeId) continue;

      const children = childrenMap.get(nodeId) || [];
      for (const child of children) {
        if (child.id && !seen.has(child.id)) {
          seen.add(child.id);
          next.push(child);
        }
      }
    }

    if (next.length === 0) break;
    levels.push(next);
    current = next;
  }

  return levels;
}

export function useAnimalTreeApi() {
  const [graph, setGraph] = useState<AnimalTreeGraph | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [dependencyInfo, setDependencyInfo] = useState<any>(null);

  const fetchAncestors = useCallback(async (rootId: number, maxDepth: number = 3, fields: string = 'id,record,sex') => {
    setLoading(true); setError(null);
    const key = cacheKey('ancestors', rootId, maxDepth, fields);
    
    try {
      // Primero verificar dependencias para dar mejor retroalimentación
      const dependencies = await animalDependenciesService.getAnimalDependencies(rootId);
      setDependencyInfo(dependencies);
      
      // Si no hay padres, podemos anticipar que el árbol estará vacío
      if (!dependencies.has_parents) {
        console.warn(`[useAnimalTreeApi] Este animal no tiene padres registrados. El árbol de ancestros mostrará solo la raíz.`);
        // No retornamos error, solo registramos la advertencia
      }
      
      const cached = await getIndexedDBCache<AnimalTreeGraph>(key);
      if (cached) {
        setGraph(cached);
        setLoading(false);
        // Refresh en background por si el backend tiene generated_at más reciente
        void animalsService.getAncestorTree({ animal_id: rootId, max_depth: maxDepth, fields }).then(fresh => {
          if (!graph || (fresh.generated_at > (cached.generated_at || 0))) {
            setGraph(fresh);
            void setIndexedDBCache(key, fresh, DEFAULT_TTL_MS);
          }
        }).catch(() => {/* noop */});
        return cached;
      }

      const resp = await animalsService.getAncestorTree({ animal_id: rootId, max_depth: maxDepth, fields });
      
      // Verificar si el árbol solo contiene la raíz
      if (resp && resp.counts && resp.counts.edges === 0 && dependencies.has_parents) {
        console.warn(`[useAnimalTreeApi] El backend indicó padres en BD pero el árbol no tiene aristas. Posible inconsistencia de datos o max_depth demasiado bajo.`);
      }
      
      setGraph(resp);
      await setIndexedDBCache(key, resp, DEFAULT_TTL_MS);
      return resp;
    } catch (e: any) {
      console.error(`[useAnimalTreeApi] Error cargando ancestros para animal ${rootId}:`, e);
      
      // Proporcionar mensajes de error más específicos
      if (e?.message?.includes('401')) {
        setError('No autorizado: inicie sesión nuevamente');
      } else if (e?.message?.includes('404')) {
        setError('Animal no encontrado o sin datos genealógicos disponibles');
      } else if (e?.message?.includes('500')) {
        setError('Error del servidor al cargar datos genealógicos');
      } else {
        setError(e?.message || 'Error cargando árbol de ancestros');
      }
      return null;
    } finally {
      setLoading(false);
    }
  }, [graph]);

  const fetchDescendants = useCallback(async (rootId: number, maxDepth: number = 3, fields: string = 'id,record,sex') => {
    setLoading(true); setError(null);
    const key = cacheKey('descendants', rootId, maxDepth, fields);
    
    try {
      // Primero verificar dependencias para dar mejor retroalimentación
      const dependencies = await animalDependenciesService.getAnimalDependencies(rootId);
      setDependencyInfo(dependencies);
      
      // Si no hay hijos, podemos anticipar que el árbol estará vacío
      if (!dependencies.has_children) {
        console.warn(`[useAnimalTreeApi] Este animal no tiene hijos registrados. El árbol de descendientes mostrará solo la raíz.`);
        // No retornamos error, solo registramos la advertencia
      }
      
      const cached = await getIndexedDBCache<AnimalTreeGraph>(key);
      if (cached) {
        setGraph(cached);
        setLoading(false);
        void animalsService.getDescendantTree({ animal_id: rootId, max_depth: maxDepth, fields }).then(fresh => {
          if (!graph || (fresh.generated_at > (cached.generated_at || 0))) {
            setGraph(fresh);
            void setIndexedDBCache(key, fresh, DEFAULT_TTL_MS);
          }
        }).catch(() => {/* noop */});
        return cached;
      }

      const resp = await animalsService.getDescendantTree({ animal_id: rootId, max_depth: maxDepth, fields });
      
      // Verificar si el árbol solo contiene la raíz
      if (resp && resp.counts && resp.counts.edges === 0 && dependencies.has_children) {
        console.warn(`[useAnimalTreeApi] El backend indicó hijos en BD pero el árbol no tiene aristas. Posible inconsistencia de datos o max_depth demasiado bajo.`);
      }
      
      setGraph(resp);
      await setIndexedDBCache(key, resp, DEFAULT_TTL_MS);
      return resp;
    } catch (e: any) {
      console.error(`[useAnimalTreeApi] Error cargando descendientes para animal ${rootId}:`, e);
      
      // Proporcionar mensajes de error más específicos
      if (e?.message?.includes('401')) {
        setError('No autorizado: inicie sesión nuevamente');
      } else if (e?.message?.includes('404')) {
        setError('Animal no encontrado o sin datos genealógicos disponibles');
      } else if (e?.message?.includes('500')) {
        setError('Error del servidor al cargar datos genealógicos');
      } else {
        setError(e?.message || 'Error cargando árbol de descendientes');
      }
      return null;
    } finally {
      setLoading(false);
    }
  }, [graph]);

  const loadMore = useCallback(async (
    type: 'ancestors' | 'descendants',
    rootId: number,
    current: AnimalTreeGraph,
    opts: TreeLoadMoreOptions = { increment: 2 }
  ) => {
    const nextDepth = (current?.depth || 0) + (opts.increment || 2);
    const fields = opts.fields || 'id,record,sex';
    const key = cacheKey(type, rootId, nextDepth, fields);
    try {
      const fresh = type === 'ancestors'
        ? await animalsService.getAncestorTree({ animal_id: rootId, max_depth: nextDepth, fields })
        : await animalsService.getDescendantTree({ animal_id: rootId, max_depth: nextDepth, fields });
      const merged = mergeGraphs(current, fresh);
      setGraph(merged);
      await setIndexedDBCache(key, merged, DEFAULT_TTL_MS);
      return merged;
    } catch (e: any) {
      setError(e?.message || 'Error expandiendo profundidad del árbol');
      return current;
    }
  }, []);

  const clearError = useCallback(() => {
    setError(null);
  }, []);

  return {
    graph,
    loading,
    error,
    dependencyInfo,
    fetchAncestors,
    fetchDescendants,
    loadMore,
    clearError,
  };
}

import { useState, useEffect, useCallback } from 'react';
import { useResource } from '@/shared/hooks/useResource';
import { animalsService } from '@/entities/animal/api/animal.service';
import { AnimalResponse } from '@/shared/api/generated/swaggerTypes';
import { animalStatsToChartData, withRetry } from '@/shared/utils/dataUtils';
import { ChartDataItem } from '@/shared/types/common.types';
import type { Dispatch, SetStateAction } from 'react';

// Normalizer: ensure required fields are present
const mapAnimalResponseToLocal = (a: Partial<AnimalResponse> & { [key: string]: any }): AnimalResponse => ({
  id: a.id ?? 0,
  record: a.record ?? '',
  // removed deprecated name field mapping to avoid reliance in UI labels
  birth_date: a.birth_date ?? '',
  weight: a.weight ?? 0,
  breed_id: a.breed_id ?? a.breeds_id ?? 0,
  breeds_id: a.breeds_id ?? a.breed_id ?? 0,
  gender: a.gender ?? a.sex ?? 'Macho',
  sex: a.sex ?? a.gender ?? 'Macho',
  status: a.status ?? 'Sano',
  // CRÍTICO: Mantener idFather/idMother del backend + aliases para compatibilidad
  idFather: a.idFather ?? a.father_id,
  idMother: a.idMother ?? a.mother_id,
  father_id: a.idFather ?? a.father_id,
  mother_id: a.idMother ?? a.mother_id,
  notes: a.notes,
  breed: a.breed,
  father: a.father,
  mother: a.mother,
  created_at: a.created_at,
  updated_at: a.updated_at,
} as any);

export interface UseAnimalsResult {
  animals: AnimalResponse[];
  data: AnimalResponse[];
  loading: boolean;
  error: string | null;
  fetchAnimals: (params?: Record<string, any>) => Promise<AnimalResponse[]>;
  addAnimal: (payload: Partial<AnimalResponse>) => Promise<AnimalResponse | null>;
  editAnimal: (id: number | string, payload: Partial<AnimalResponse>) => Promise<AnimalResponse | null>;
  deleteAnimal: (id: number | string) => Promise<boolean>;
  createItem: (payload: Partial<AnimalResponse>) => Promise<AnimalResponse | null>;
  updateItem: (id: number | string, payload: Partial<AnimalResponse>) => Promise<AnimalResponse | null>;
  deleteItem: (id: number | string) => Promise<boolean>;
  setData: Dispatch<SetStateAction<AnimalResponse[]>>;
  animalStatusData: ChartDataItem[];
  fetchAnimalStatus: () => Promise<void>;
  reload: (params?: Record<string, any>) => Promise<AnimalResponse[]>;
  clearError: () => void;
}

export function useAnimals(params?: Record<string, any>): UseAnimalsResult {
  // Use generic resource hook for CRUD
  const resource = useResource<AnimalResponse, any>(animalsService as any, {
    autoFetch: true,
    initialParams: params,
    map: ((items: any[]) => (items as AnimalResponse[]).map(mapAnimalResponseToLocal)) as any,
  });

  // Custom animal status/statistics logic
  const [animalStatusData, setAnimalStatusData] = useState<ChartDataItem[]>([]);
  const [statusLoading, setStatusLoading] = useState<boolean>(false);
  const [statusError, setStatusError] = useState<string | null>(null);

  const fetchAnimalStatus = useCallback(async (): Promise<void> => {
    setStatusLoading(true);
    setStatusError(null);
    try {
      const response = await withRetry(
        () => animalsService.getAnimalStatusStats(),
        3,
        1000
      );
      if (response && typeof response === 'object') {
        const chartData = animalStatsToChartData(response);
        setAnimalStatusData(chartData);
      } else {
        setAnimalStatusData([]);
        setStatusError('Formato de respuesta inválido');
      }
    } catch (err) {
      setStatusError('Error al cargar el estado de los animales');
      setAnimalStatusData([]);
    } finally {
      setStatusLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchAnimalStatus();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const mapped = resource.data as unknown as AnimalResponse[];

  const addAnimal = async (payload: Partial<AnimalResponse>): Promise<AnimalResponse | null> => {
    const created = await (resource.createItem as any)(payload as any);
    if (!created) return null;
    const mappedCreated = mapAnimalResponseToLocal(created as any);
    (resource.setData as any)((prev: any[]) => {
      const arr = Array.isArray(prev) ? prev : [];
      const clean = arr.filter((x: any) => x?.id !== (created as any)?.id);
      return [...clean, mappedCreated] as any;
    });
    return mappedCreated;
  };

  const editAnimal = async (id: number | string, payload: Partial<AnimalResponse>): Promise<AnimalResponse | null> => {
    const updated = await (resource.updateItem as any)(id, payload as any);
    if (!updated) return null;
    const mappedUpdated = mapAnimalResponseToLocal(updated as any);
    (resource.setData as any)((prev: any[]) => {
      const arr = Array.isArray(prev) ? prev : [];
      return arr.map((x: any) => (x?.id === (updated as any)?.id || x?.id === id) ? { ...x, ...mappedUpdated } : x) as any;
    });
    return mappedUpdated;
  };

  return {
    animals: mapped,
    data: mapped,
    loading: (resource as any).loading || statusLoading,
    error: ((resource as any).error || statusError) as string | null,
    fetchAnimals: resource.refetch as unknown as (params?: Record<string, any>) => Promise<AnimalResponse[]>,
    addAnimal,
    editAnimal,
    createItem: addAnimal,
    updateItem: editAnimal,
    deleteAnimal: resource.deleteItem,
    deleteItem: resource.deleteItem,
    setData: resource.setData as unknown as Dispatch<SetStateAction<AnimalResponse[]>>,
    animalStatusData,
    fetchAnimalStatus,
    reload: resource.refetch as unknown as (params?: Record<string, any>) => Promise<AnimalResponse[]>,
    clearError: () => (resource.setData as any)([]),
  };
}

