import { useAnimals } from "./useAnimals";

interface AnimalNode {
  idAnimal?: number;
  id?: number;
  record?: string;
  name?: string;
  birth_date?: string;
  sex?: string;
  gender?: 'Macho' | 'Hembra';
  breed?: any;
  idFather?: number | null;
  father_id?: number | null;
  idMother?: number | null;
  mother_id?: number | null;
}

export const useDescendantsTree = () => {
  const { animals } = useAnimals();

  // Construye el árbol hacia abajo (descendientes) a partir de un animal raíz
  const buildDescendantsTree = async (
    animalId: number | undefined,
    maxDepth = 10
  ): Promise<{ animal: AnimalNode | null; levels: AnimalNode[][] }> => {
    if (animalId === undefined || animalId === null) return { animal: null, levels: [] };

    console.log(`[descendantsTree] === INICIANDO buildDescendantsTree para id=${animalId} ===`);
    console.log(`[descendantsTree] Total animales disponibles: ${animals.length}`);

    // Buscar el nodo raíz por idAnimal o id
    const rootNode = animals.find(a => (a as any).idAnimal === animalId || a.id === animalId) || null;
    if (!rootNode) {
      console.log(`[descendantsTree] ❌ Animal raíz NO encontrado para id=${animalId}`);
      return { animal: null, levels: [] };
    }

    console.log(`[descendantsTree] ✅ Animal raíz encontrado:`, {
      id: rootNode.id,
      record: rootNode.record,
      sex: rootNode.gender,
      idFather: rootNode.father_id,
      idMother: rootNode.mother_id,
    });

    const levels: AnimalNode[][] = [];
    levels.push([rootNode as AnimalNode]); // nivel 0

    let currentLevel: AnimalNode[] = [rootNode as AnimalNode];
    for (let depth = 1; depth <= maxDepth; depth++) {
      const nextLevel: AnimalNode[] = [];
      console.log(`[descendantsTree] --- Procesando nivel ${depth}, nodos padres actuales: ${currentLevel.length} ---`);

      for (const node of currentLevel) {
        // Obtener el ID del nodo actual con múltiples fallbacks
        const id = (node as any).idAnimal ?? (node as any).id;
        if (!id) {
          console.log(`[descendantsTree] ⚠️ Nodo sin ID, omitiendo`);
          continue;
        }

        // Validar que el ID sea un número válido
        const validId = Number.isInteger(Number(id)) && Number(id) > 0 ? Number(id) : null;
        if (!validId) {
          console.log(`[descendantsTree] ⚠️ ID inválido: ${id}, omitiendo`);
          continue;
        }

        console.log(`[descendantsTree] 🔍 Buscando hijos de: id=${validId} record=${node.record}`);

        // Buscar hijos: animales cuyo idFather o idMother coinciden con el ID del nodo actual
        const children = animals.filter(a => {
          // Extraer IDs de padre y madre - PRIORIZAR idFather/idMother (formato del backend)
          const fId = (a as any).idFather ?? (a as any).father_id ?? (a as any).father?.id ?? (a as any).father?.idAnimal;
          const mId = (a as any).idMother ?? (a as any).mother_id ?? (a as any).mother?.id ?? (a as any).mother?.idAnimal;

          // Validar que los IDs sean números válidos antes de comparar
          const validFId = fId && Number.isInteger(Number(fId)) && Number(fId) > 0 ? Number(fId) : null;
          const validMId = mId && Number.isInteger(Number(mId)) && Number(mId) > 0 ? Number(mId) : null;

          const isChild = validFId === validId || validMId === validId;

          if (isChild) {
            console.log(`[descendantsTree] ✅ Hijo encontrado: id=${a.id} record=${a.record} (idFather=${validFId}, idMother=${validMId})`);
          }

          return isChild;
        }) as AnimalNode[];

        if (children.length > 0) {
          console.log(`[descendantsTree] 👶 Total hijos de id=${validId}: ${children.length}`);
        } else {
          console.log(`[descendantsTree] ❌ No se encontraron hijos para id=${validId}`);
        }

        nextLevel.push(...children);
      }

      // Quitar duplicados por idAnimal/id
      const unique = nextLevel.filter((v, i, arr) => {
        const vid = (v as any).idAnimal ?? (v as any).id;
        return vid && arr.findIndex(x => ((x as any).idAnimal ?? (x as any).id) === vid) === i;
      });

      console.log(`[descendantsTree] Nivel ${depth}: ${unique.length} descendientes únicos`);

      if (unique.length === 0) break;
      levels.push(unique);
      currentLevel = unique;
    }

    console.log(`[descendantsTree] === ÁRBOL DE DESCENDIENTES COMPLETO ===`);
    console.log(`[descendantsTree] Total niveles construidos: ${levels.length}`);
    levels.forEach((level, idx) => {
      console.log(`[descendantsTree] Nivel ${idx}: ${level.length} animales`, level.map(a => `${a.record}(${a.id})`));
    });

    return { animal: rootNode, levels };
  };

  return { buildDescendantsTree };
};

import { useAnimals } from "./useAnimals";
import { animalService } from '@/entities/animal/api/animal.service';

interface AnimalNode {
  id?: number;
  record?: string;
  name?: string;
  birth_date?: string;
  sex?: string;
  breed?: any;
  father_id?: number | null;
  mother_id?: number | null;
}

export const useGeneticTree = () => {
  const { animals } = useAnimals();

  const buildGeneticTree = async (animalId: number | undefined, maxDepth = 10) => {
    if (animalId === undefined || animalId === null) return { animal: null, levels: [] };

    console.log(`[geneticTree] === INICIANDO buildGeneticTree para id=${animalId} ===`);
    console.log(`[geneticTree] Total animales disponibles: ${animals.length}`);

    // First, try to build the tree synchronously from the cached `animals` list.
    const buildFromList = (list: any[], id: number | undefined, depth = maxDepth) => {
      if (!id) return { animal: null, levels: [] };
      const rootNode = list.find(a => a.id === id) || null;
      if (!rootNode) {
        console.log(`[geneticTree] buildFromList: Animal raíz NO encontrado para id=${id}`);
        return { animal: null, levels: [] };
      }

      console.log(`[geneticTree] buildFromList: Animal raíz encontrado:`, {
        id: rootNode.id,
        record: rootNode.record,
        idFather: rootNode.idFather,
        father_id: rootNode.father_id,
        idMother: rootNode.idMother,
        mother_id: rootNode.mother_id,
      });

      const levels: any[][] = [];
      levels.push([rootNode]);
      let currentLevel: any[] = [rootNode];

      for (let d = 1; d <= depth; d++) {
        const nextLevel: any[] = [];
        console.log(`[geneticTree] buildFromList: Procesando nivel ${d}, nodos actuales: ${currentLevel.length}`);

        for (const node of currentLevel) {
          // Extraer IDs de padre y madre - PRIORIZAR idFather/idMother
          const fatherId = (node as any)?.idFather ?? (node as any)?.father_id;
          const motherId = (node as any)?.idMother ?? (node as any)?.mother_id;

          console.log(`[geneticTree] buildFromList: Nodo id=${node.id} record=${node.record} -> fatherId=${fatherId}, motherId=${motherId}`);

          // Buscar padre: primero objeto embebido, luego por ID en lista
          const father = (node as any)?.father ?? (fatherId ? list.find((a: any) => a.id === fatherId) : null) ?? null;
          // Buscar madre: primero objeto embebido, luego por ID en lista
          const mother = (node as any)?.mother ?? (motherId ? list.find((a: any) => a.id === motherId) : null) ?? null;

          if (father) {
            console.log(`[geneticTree] buildFromList: Padre encontrado id=${father.id} record=${father.record}`);
            nextLevel.push(father);
          }
          if (mother) {
            console.log(`[geneticTree] buildFromList: Madre encontrada id=${mother.id} record=${mother.record}`);
            nextLevel.push(mother);
          }
        }
        const unique = nextLevel.filter((v, i, arr) => v && v.id && arr.findIndex(x => x.id === v.id) === i);
        console.log(`[geneticTree] buildFromList: Nivel ${d} tiene ${unique.length} padres únicos`);
        levels.push(unique);
        currentLevel = unique;
        if (!unique || unique.length === 0) break;
      }

      return { animal: rootNode, levels };
    };

    // Try local list first (no network). If it yields parents, return early.
    try {
      const local = buildFromList(animals, animalId, maxDepth);
      if (local && local.animal && local.levels && local.levels.length > 1) {
        console.debug(`[geneticTree] built from local list for id=${animalId}`);
        return local;
      }
    } catch (e) {
      console.debug('[geneticTree] local build failed', e);
    }

    // find root animal in cached list first, otherwise fetch
    let root = animals.find(a => a.id === animalId) || null as any;
    if (root) {
      console.debug(`[geneticTree] root found in cache id=${root.id} record=${root.record}`);
    } else {
      try {
        root = await animalService.getById(animalId as number);
        console.debug(`[geneticTree] root fetched id=${animalId} -> ${root ? `record=${root.record}` : 'null'}`);
      } catch (e) {
        console.debug(`[geneticTree] failed to fetch root id=${animalId}`, e);
        return { animal: null, levels: [] };
      }
    }
    if (!root) {
      console.debug(`[geneticTree] no root found for id=${animalId}`);
      return { animal: null, levels: [] };
    }

    const levels: AnimalNode[][] = [];
    levels.push([root]); // level 0

    let currentLevel: any[] = [root];
    let hasMoreGenerations = true;

    // Continuar buscando generaciones hasta que no haya más padres o alcanzemos el máximo
    for (let depth = 1; depth <= maxDepth && hasMoreGenerations; depth++) {
      const nextLevel: any[] = [];
      let foundAnyParent = false;

      for (const node of currentLevel) {
        // Extraer IDs de padre y madre - PRIORIZAR idFather/idMother (formato del backend)
        const fatherId = (node as any)?.idFather ?? (node as any)?.father_id ?? (node as any)?.father?.id ?? (node as any)?.father?.idAnimal ?? null;
        const motherId = (node as any)?.idMother ?? (node as any)?.mother_id ?? (node as any)?.mother?.id ?? (node as any)?.mother?.idAnimal ?? null;

        console.debug(`[geneticTree] node id=${node?.id} record=${node?.record} idFather=${fatherId} idMother=${motherId}`);

        // Validar que los IDs sean números válidos antes de buscar
        const validFatherId = fatherId && Number.isInteger(Number(fatherId)) && Number(fatherId) > 0 ? Number(fatherId) : null;
        const validMotherId = motherId && Number.isInteger(Number(motherId)) && Number(motherId) > 0 ? Number(motherId) : null;

        if (validFatherId) {
          // Buscar padre en caché primero
          let father = animals.find(a => a.id === validFatherId);
          if (father) {
            console.debug(`[geneticTree] father found in cache id=${validFatherId} record=${father.record}`);
            foundAnyParent = true;
          } else {
            // Si no está en caché, intentar buscar por objeto embebido
            const embeddedFather = (node as any)?.father;
            if (embeddedFather && (embeddedFather.id === validFatherId || embeddedFather.idAnimal === validFatherId)) {
              father = embeddedFather;
              console.debug(`[geneticTree] father found embedded id=${validFatherId}`);
              foundAnyParent = true;
            } else {
              // Último recurso: fetch del servidor
              try {
                father = await animalService.getById(validFatherId);
                console.debug(`[geneticTree] father fetched id=${validFatherId} record=${father?.record}`);
                foundAnyParent = true;
              } catch (e) {
                console.debug(`[geneticTree] failed to fetch father id=${validFatherId}`, e);
                father = undefined;
              }
            }
          }
          // Validar que el padre sea macho antes de agregarlo
          if (father) {
            const fatherSex = father.gender;
            if (fatherSex === 'Macho' || !fatherSex) { // Permitir si no hay sexo definido
              nextLevel.push(father);
            } else {
              console.warn(`[geneticTree] father id=${validFatherId} has invalid sex: ${fatherSex}`);
            }
          }
        }

        if (validMotherId) {
          // Buscar madre en caché primero
          let mother = animals.find(a => a.id === validMotherId);
          if (mother) {
            console.debug(`[geneticTree] mother found in cache id=${validMotherId} record=${mother.record}`);
            foundAnyParent = true;
          } else {
            // Si no está en caché, intentar buscar por objeto embebido
            const embeddedMother = (node as any)?.mother;
            if (embeddedMother && (embeddedMother.id === validMotherId || embeddedMother.idAnimal === validMotherId)) {
              mother = embeddedMother;
              console.debug(`[geneticTree] mother found embedded id=${validMotherId}`);
              foundAnyParent = true;
            } else {
              // Último recurso: fetch del servidor
              try {
                mother = await animalService.getById(validMotherId);
                console.debug(`[geneticTree] mother fetched id=${validMotherId} record=${mother?.record}`);
                foundAnyParent = true;
              } catch (e) {
                console.debug(`[geneticTree] failed to fetch mother id=${validMotherId}`, e);
                mother = undefined;
              }
            }
          }
          // Validar que la madre sea hembra antes de agregarla
          if (mother) {
            const motherSex = mother.gender;
            if (motherSex === 'Hembra' || !motherSex) { // Permitir si no hay sexo definido
              nextLevel.push(mother);
            } else {
              console.warn(`[geneticTree] mother id=${validMotherId} has invalid sex: ${motherSex}`);
            }
          }
        }
      }

      // dedupe by id
      const unique = nextLevel.filter((v, i, arr) => v && v.id && arr.findIndex(x => x.id === v.id) === i);

      // Si no encontramos padres en esta iteración, terminamos
      if (!foundAnyParent || unique.length === 0) {
        hasMoreGenerations = false;
      }

      if (unique.length > 0) {
        levels.push(unique);
        currentLevel = unique;
      }
    }

    console.log(`[geneticTree] === ÁRBOL COMPLETO ===`);
    console.log(`[geneticTree] Total niveles construidos: ${levels.length}`);
    levels.forEach((level, idx) => {
      console.log(`[geneticTree] Nivel ${idx}: ${level.length} animales`, level.map(a => `${a.record}(${a.id})`));
    });

    return { animal: root, levels };
  };

  return { buildGeneticTree };
};

import React, { useState, useRef } from 'react';
import { TrendingUp } from 'lucide-react';
import { ForeignKeyLink } from '@/shared/ui/common/ForeignKeyLink';
import { animalsService } from '@/entities/animal/api/animal.service';
import { useAuth } from '@/features/auth/model/useAuth';
import { Button } from '@/shared/ui/button';

// Widgets (Permitido desde entities a widgets? NO. Entities NO puede importar de Widgets)
// AH! Aquí hay otro problema de FSD.
// Si AnimalLink necesita AnimalModalContent (widget), entonces AnimalLink DEBE ser un WIDGET o un FEATURE.
// O AnimalModalContent debe ser movido a Entities si es puramente informativo.

// Revisando AnimalModalContent...
import { AnimalModalContent } from '@/widgets/dashboard/animals/AnimalModalContent';
import { AnimalHistoryModal } from '@/widgets/dashboard/AnimalHistoryModal';
import GeneticTreeModal from '@/widgets/dashboard/GeneticTreeModal';
import DescendantsTreeModal from '@/widgets/dashboard/DescendantsTreeModal';
import { useAnimalTreeApi, graphToAncestorLevels, graphToDescendantLevels } from '@/entities/animal/model/useAnimalTreeApi';

export const AnimalLink: React.FC<{ id: number | string; label: string; children?: React.ReactNode }> = ({ id, label, children }) => {
  const renderAnimalContent = (initialAnimal: any) => {
    const Wrapper: React.FC<{ initial: any }> = ({ initial }) => {
      const [animal, setAnimal] = useState<any>(initial);
      const { user } = useAuth();

      const [isHistoryOpen, setIsHistoryOpen] = useState(false);
      const [historyAnimal, setHistoryAnimal] = useState<any | null>(null);

      const ancestorsApi = useAnimalTreeApi();
      const descendantsApi = useAnimalTreeApi();
      
      const [isTreeOpen, setIsTreeOpen] = useState(false);
      const [treeAnimal, setTreeAnimal] = useState<any | null>(null);
      const [treeLevels, setTreeLevels] = useState<any[][]>([]);
      const [ancestorCounts, setAncestorCounts] = useState<any>();
      const [ancestorSummary, setAncestorSummary] = useState<any>();
      const [ancestorEdgeExamples, setAncestorEdgeExamples] = useState<any>();
      const [treeRootId, setTreeRootId] = useState<number | null>(null);

      const [isDescOpen, setIsDescOpen] = useState(false);
      const [descAnimal, setDescAnimal] = useState<any | null>(null);
      const [descLevels, setDescLevels] = useState<any[][]>([]);
      const [descCounts, setDescCounts] = useState<any>();
      const [descSummary, setDescSummary] = useState<any>();
      const [descEdgeExamples, setDescEdgeExamples] = useState<any>();
      const [descRootId, setDescRootId] = useState<number | null>(null);

      const loadAnimal = async (animalId: number) => {
        const next = await animalsService.getById(animalId);
        setAnimal(next);
      };

      const openHistory = (record: any) => {
        const payload = {
          idAnimal: Number(record?.id ?? 0),
          record: record?.record || '',
          breed: record?.breed,
          birth_date: record?.birth_date,
          sex: record?.sex || record?.gender,
          status: record?.status,
        };
        setHistoryAnimal(payload);
        setIsHistoryOpen(true);
      };

      const openAncestorsTree = async (record: any) => {
        const idNum = Number(record?.id ?? 0);
        if (!idNum) return;
        const resp = await ancestorsApi.fetchAncestors(idNum, 3, 'id,record,sex,breeds_id,idFather,idMother');
        if (!resp) {
          setTreeAnimal(record);
          setTreeLevels([]);
          setTreeRootId(idNum);
          setIsTreeOpen(true);
          return;
        }
        setTreeRootId(resp.rootId);
        setTreeAnimal(resp.nodes[resp.rootId]);
        setTreeLevels(graphToAncestorLevels(resp));
        setAncestorCounts(resp.counts);
        setAncestorSummary(resp.summary);
        setAncestorEdgeExamples(resp.edge_examples);
        setIsTreeOpen(true);
      };

      const openDescendantsTree = async (record: any) => {
        const idNum = Number(record?.id ?? 0);
        if (!idNum) return;
        const resp = await descendantsApi.fetchDescendants(idNum, 3, 'id,record,sex,breeds_id,idFather,idMother');
        if (!resp) {
          setDescAnimal(record);
          setDescLevels([]);
          setDescRootId(idNum);
          setIsDescOpen(true);
          return;
        }
        setDescRootId(resp.rootId);
        setDescAnimal(resp.nodes[resp.rootId]);
        setDescLevels(graphToDescendantLevels(resp));
        setDescCounts(resp.counts);
        setDescSummary(resp.summary);
        setDescEdgeExamples(resp.edge_examples);
        setIsDescOpen(true);
      };

      return (
        <>
          <AnimalModalContent
            animal={animal}
            breedLabel={animal?.breed?.name || '-'}
            fatherLabel={animal?.idFather ? `ID ${animal.idFather}` : '-'}
            motherLabel={animal?.idMother ? `ID ${animal.idMother}` : '-'}
            onFatherClick={animal?.idFather ? (id: number) => loadAnimal(id) : undefined}
            onMotherClick={animal?.idMother ? (id: number) => loadAnimal(id) : undefined}
            currentUserId={user?.id}
            onOpenHistory={() => openHistory(animal)}
            onOpenAncestorsTree={() => openAncestorsTree(animal)}
            onOpenDescendantsTree={() => openDescendantsTree(animal)}
          />

          {isHistoryOpen && historyAnimal && (
            <AnimalHistoryModal
              animal={historyAnimal}
              onClose={() => {
                setIsHistoryOpen(false);
                setHistoryAnimal(null);
              }}
            />
          )}

          <GeneticTreeModal
            isOpen={isTreeOpen}
            onClose={() => {
              setIsTreeOpen(false);
              setTreeAnimal(null);
              setTreeLevels([]);
            }}
            animal={treeAnimal}
            levels={treeLevels}
            counts={ancestorCounts}
            summary={ancestorSummary}
            edgeExamples={ancestorEdgeExamples}
            dependencyInfo={ancestorsApi.dependencyInfo}
            treeError={ancestorsApi.error}
            loadingMore={ancestorsApi.loading}
            onNavigateToAnimal={openAncestorsTree}
            onOpenDescendantsTreeForAnimal={openDescendantsTree}
            onLoadMore={async () => {
              if (!treeRootId || !ancestorsApi.graph) return;
              const merged = await ancestorsApi.loadMore('ancestors', treeRootId, ancestorsApi.graph, {
                increment: 2,
                fields: 'id,record,sex,breeds_id,idFather,idMother',
              });
              setTreeAnimal(merged.nodes[merged.rootId]);
              setTreeLevels(graphToAncestorLevels(merged));
              setAncestorCounts(merged.counts);
              setAncestorSummary(merged.summary);
              setAncestorEdgeExamples(merged.edge_examples);
            }}
          />

          <DescendantsTreeModal
            isOpen={isDescOpen}
            onClose={() => {
              setIsDescOpen(false);
              setDescAnimal(null);
              setDescLevels([]);
            }}
            animal={descAnimal}
            levels={descLevels}
            counts={descCounts}
            summary={descSummary}
            edgeExamples={descEdgeExamples}
            dependencyInfo={descendantsApi.dependencyInfo}
            treeError={descendantsApi.error}
            loadingMore={descendantsApi.loading}
            onNavigateToAnimal={openDescendantsTree}
            onOpenAncestorsTreeForAnimal={openAncestorsTree}
            onLoadMore={async () => {
              if (!descRootId || !descendantsApi.graph) return;
              const merged = await descendantsApi.loadMore('descendants', descRootId, descendantsApi.graph, {
                increment: 2,
                fields: 'id,record,sex,breeds_id,idFather,idMother',
              });
              setDescAnimal(merged.nodes[merged.rootId]);
              setDescLevels(graphToDescendantLevels(merged));
              setDescCounts(merged.counts);
              setDescSummary(merged.summary);
              setDescEdgeExamples(merged.edge_examples);
            }}
          />
        </>
      );
    };

    return <Wrapper initial={initialAnimal} />;
  };

  return (
    <ForeignKeyLink
      id={id}
      label={label}
      service={animalsService}
      modalTitle="Detalle del Animal"
      renderContent={renderAnimalContent}
      size="full"
      enableFullScreenToggle
    >
      {children}
    </ForeignKeyLink>
  );
};

