import { useResource } from '@/shared/hooks/useResource';
import { Treatments } from '@/entities/treatment/model/types';
import type { TreatmentResponse } from '@/shared/api/generated/swaggerTypes';
import { treatmentsService } from '@/entities/treatment/api/treatments.service';

// Normalizador único para evitar duplicidad y errores de tipo
import type { Dispatch, SetStateAction } from 'react';

const mapTreatmentResponseToLocal = (r: Partial<TreatmentResponse> & { [key: string]: any }): Treatments => ({
  id: r.id ?? 0,
  // aceptar treatment_date o treatment_date o date
  treatment_date: (r as any).treatment_date ?? (r as any).treatment_date ?? (r as any).date ?? '',
  end_date: (r as any).end_date ?? '',
  // aceptar description (nuevo) o diagnosis (legacy)
  description: (r as any).description ?? (r as any).diagnosis ?? '',
  frequency: (r as any).frequency ?? '',
  observations: (r as any).observations ?? '',
  dosis: (r as any).dosis ?? '',
  animal_id: (r as any).animal_id ?? 0,
  // si no viene animals, crear un stub con id para poder mostrar #id en la tabla
  animals: (r as any).animals ?? ((r as any).animal_id != null ? ({ id: (r as any).animal_id } as any) : undefined),
  vaccines_treatments: (r as any).vaccines_treatments,
  medication_treatments: (r as any).medication_treatments,
});

export interface UseTreatmentResult {
  treatments: Treatments[];
  data: Treatments[];
  loading: boolean;
  error: string | null;
  refetch: (params?: Record<string, any>) => Promise<Treatments[]>;
  // Compatibilidad hacia atrás
  createItem: (payload: Partial<Treatments>) => Promise<Treatments | null>;
  updateItem: (id: number | string, payload: Partial<Treatments>) => Promise<Treatments | null>;
  // Nuevos wrappers normalizados
  addTreatment: (payload: Partial<Treatments>) => Promise<Treatments | null>;
  editTreatment: (id: number | string, payload: Partial<Treatments>) => Promise<Treatments | null>;
  deleteItem: (id: number | string) => Promise<boolean>;
  setData: Dispatch<SetStateAction<Treatments[]>>;
  // Meta y setters opcionales provenientes de useResource
  meta?: any;
  setPage?: (p: number) => void;
  setLimit?: (l: number) => void;
  setSearch?: (s: string) => void;
  setFields?: (f: string) => void;
}

// El tipo base para useResource será TreatmentResponse, pero el resultado se normaliza a Treatments
export function useTreatment(): UseTreatmentResult {
  const resource = useResource<TreatmentResponse, any>(treatmentsService as any, {
    autoFetch: true,
    initialParams: { page: 1, limit: 10 },
    map: ((items: any[]) => (items as TreatmentResponse[]).map(mapTreatmentResponseToLocal)) as any,
  });

  const mapped = resource.data as unknown as Treatments[];

  const addTreatment = async (payload: Partial<Treatments>): Promise<Treatments | null> => {
    const created = await (resource.createItem as any)(payload as any);
    if (!created) return null;
    const mappedCreated = mapTreatmentResponseToLocal(created as any);
    resource.setData((prev: any[]) => {
      const arr = Array.isArray(prev) ? prev : [];
      const clean = arr.filter((x: any) => x?.id !== (created as any)?.id);
      return [...clean, mappedCreated] as any;
    });
    return mappedCreated;
  };

  const editTreatment = async (id: number | string, payload: Partial<Treatments>): Promise<Treatments | null> => {
    const updated = await (resource.updateItem as any)(id, payload as any);
    if (!updated) return null;
    const mappedUpdated = mapTreatmentResponseToLocal(updated as any);
    resource.setData((prev: any[]) => {
      const arr = Array.isArray(prev) ? prev : [];
      return arr.map((x: any) => (x?.id === (updated as any)?.id || x?.id === id) ? { ...x, ...mappedUpdated } : x) as any;
    });
    return mappedUpdated;
  };

  // Alias de compatibilidad
  const createItem = addTreatment;
  const updateItem = editTreatment;

  return {
    treatments: mapped,
    data: mapped,
    loading: (resource as any).loading,
    error: (resource as any).error,
    refetch: resource.refetch as unknown as (params?: Record<string, any>) => Promise<Treatments[]>,
    createItem,
    updateItem,
    addTreatment,
    editTreatment,
    deleteItem: resource.deleteItem,
    setData: resource.setData as unknown as Dispatch<SetStateAction<Treatments[]>>,
    meta: (resource as any).meta,
    setPage: (resource as any).setPage,
    setLimit: (resource as any).setLimit,
    setSearch: (resource as any).setSearch,
    setFields: (resource as any).setFields,
  };
}

import { BaseService } from '@/shared/api/base-service';
import { UserResponse, UserInput, PaginatedResponse } from '@/shared/api/generated/swaggerTypes';
import { UserStatistics, BulkResponse } from '@/shared/types/common.types';
import { apiFetch } from '@/shared/api/apiFetch';

class UsersService extends BaseService<UserResponse> {
  constructor() {
    super('users');
  }

  async getUsers(params?: Record<string, any>): Promise<PaginatedResponse<UserResponse>> {
    return this.getPaginated(params);
  }

  async getUserById(id: number): Promise<UserResponse> {
    return this.getById(id);
  }

  async createUser(userData: UserInput): Promise<UserResponse> {
    return this.create(userData);
  }

  async updateUser(id: number, userData: Partial<UserInput>): Promise<UserResponse> {
    return this.update(id, userData);
  }

  async patchUser(id: number, userData: Partial<UserInput>): Promise<UserResponse> {
    return this.patch(id, userData);
  }

  async deleteUser(id: number): Promise<boolean> {
    return this.delete(id);
  }

  async createBulk(data: UserInput[]): Promise<BulkResponse<UserResponse>> {
    return this.customRequest('bulk', 'POST', data);
  }

  async createPublicUser(userData: UserInput): Promise<UserResponse> {
    // Preparar payload con created_at para evitar fallos en BD sin default
    const createdAt = (await import('@/shared/utils/dateUtils')).getNowColombiaISO?.() || new Date().toISOString();
    // Normalizar a formato 'YYYY-MM-DD HH:mm:ss' si viene con 'T'
    const normalizedCreatedAt = String(createdAt).replace('T', ' ').split('.')[0];
    const payload = {
      ...(userData as any),
      created_at: normalizedCreatedAt,
      password_confirmation:
        (userData as any).password_confirmation ?? (userData as any).password,
    } as any;

    const requestConfig = {
      method: 'POST',
      data: payload,
      // Forzar request pública sin credenciales/session cookies
      withCredentials: false,
      skipAuth: true,
      __skipAuthHeader: true,
      __skipAuthGate: true,
      disableAuth: true,
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
      },
    } as const;

    const performRequest = async (url: string) => {
      const response = await apiFetch({
        url,
        ...requestConfig,
      } as any);
      return (response as any).data?.data || (response as any).data;
    };

    try {
      // Preferir siempre el endpoint público explícito; si no existe, caer a /users legacy
      try {
        return await performRequest(`${this.endpoint}/public`);
      } catch (publicErr: any) {
        const status = publicErr?.response?.status;
        // Solo intentar /users si el endpoint público no existe en el backend
        if (status === 404 || status === 405) {
          return await performRequest(`${this.endpoint}`);
        }
        throw publicErr;
      }
    } catch (error: any) {
      const status = error?.response?.status;
      const errorData = error?.response?.data;

      if (status === 409) {
        const message = errorData?.message || errorData?.detail || 'Usuario ya existe';
        error.message = message;
      } else if (status === 400) {
        const message = errorData?.message || errorData?.detail || errorData?.error;
        if (message) error.message = message;
      } else if (status === 401 || status === 403) {
        const message = errorData?.message || errorData?.detail;
        error.message = message || 'El registro público está deshabilitado o requiere permisos de administrador.';
      }

      throw error;
    }
  }

  async getUserRoles(): Promise<{
    roles: Record<string, { count: number; percentage: number }>;
    total_users: number;
  }> {
    return this.customRequest('roles', 'GET');
  }

  async getUserStatistics(): Promise<UserStatistics> {
    return this.customRequest('statistics', 'GET');
  }

  async getUserStats(): Promise<UserStatistics> {
    return this.customRequest('stats', 'GET');
  }

  async getUserStatus(): Promise<UserStatistics> {
    return this.customRequest('status', 'GET');
  }

  // Chequeos ligeros con HEAD
  async checkAvailability(): Promise<{ ok: boolean; status?: number; headers?: Record<string, any> }> {
    try {
      const res = await apiFetch({ url: this.endpoint, method: 'HEAD', validateStatus: () => true });
      return { ok: res.status >= 200 && res.status < 300, status: res.status, headers: res.headers };
    } catch (e: any) {
      return { ok: false, status: e?.response?.status, headers: e?.response?.headers };
    }
  }

  async checkItemAvailability(id: number | string): Promise<{ ok: boolean; status?: number; headers?: Record<string, any> }> {
    try {
      const res = await apiFetch({ url: `${this.endpoint}/${id}`, method: 'HEAD', validateStatus: () => true });
      return { ok: res.status >= 200 && res.status < 300, status: res.status, headers: res.headers };
    } catch (e: any) {
      return { ok: false, status: e?.response?.status, headers: e?.response?.headers };
    }
  }

  /**
   * [ADMIN] Obtener todos los usuarios del sistema con sus fincas asociadas
   */
  async getGlobalUsers(): Promise<UserResponse[]> {
    return this.customRequest('global', 'GET');
  }
}

