// Simple retry helpers emulating older API expected by hooks
async function withRetry<T>(fn: () => Promise<T>, attempts = 2, delayMs = 1000): Promise<T> {
  let lastErr: any;
  for (let i=0;i<attempts;i++) {
    try { return await fn(); } catch (e) { 
      lastErr = e; 
      if (i<attempts-1) {
        // Aumentar delay exponencialmente para evitar spam
        await new Promise(r=>setTimeout(r, delayMs * Math.pow(2, i))); 
      }
    }
  }
  throw lastErr;
}

export const getUsersWithRetry = (params?: any) => withRetry(()=> usersService.getUsers(params) as any);
export const getUserRolesWithRetry = () => withRetry(()=> usersService.getUserRoles());
export const getUserStatusWithRetry = () => withRetry(()=> usersService.getUserStatus());

import { useState } from 'react';
import { useResource } from '@/shared/hooks/useResource';
import { usersService, getUserRolesWithRetry } from '@/entities/user/api/user.service';
import { UserResponse } from '@/shared/api/generated/swaggerTypes';
// import { userStatsToChartData } from '@/shared/utils/dataUtils';


interface RoleInfo {
  count: number;
  percentage: number;
}
interface RolesResponse {
  roles: Record<string, RoleInfo>;
  total_users: number;
}
interface RoleArrayItem {
  role: string;
  count: number;
  percentage: number;
}
interface UserRolesData extends RolesResponse {
  rolesArray: RoleArrayItem[];
}

export const useUsers = (options?: { autoFetch?: boolean }) => {
  const resource = useResource<UserResponse, any>(usersService as any, {
    autoFetch: options?.autoFetch !== false,
  });

  // Custom state for roles and status
  // const [usersStatusData, setUsersStatusData] = useState<ChartDataItem[]>([]);
  const [userRolesData, setUserRolesData] = useState<any[] | UserRolesData>([]);
  const [userStatusData, setUserStatusData] = useState<any[]>([]);
  const [loadingRoles, setLoadingRoles] = useState(false);
  const [loadingStatus, setLoadingStatus] = useState(false);

  const fetchUserRoles = async () => {
    setLoadingRoles(true);
    try {
      const data: RolesResponse = await getUserRolesWithRetry();
      if (data && data.roles) {
        const rolesArray: RoleArrayItem[] = Object.entries(data.roles).map(([role, info]: [string, RoleInfo]) => ({
          role,
          count: info.count,
          percentage: info.percentage
        }));
        const userRolesData: UserRolesData = { ...data, rolesArray };
        setUserRolesData(userRolesData);
      } else {
        setUserRolesData({ ...data, rolesArray: [] });
      }
    } catch (err) {
      setUserRolesData([]);
    } finally {
      setLoadingRoles(false);
    }
  };

  const fetchUserStatus = async () => {
    setLoadingStatus(true);
    try {
      const data = await usersService.getUserStatus();
      setUserStatusData(data as any);
    } catch (error) {
      console.error('Error fetching user status:', error);
    } finally {
      setLoadingStatus(false);
    }
  };

  return {
  ...resource,
  users: (resource as any).data,
  addUser: (resource as any).createItem,
  editUser: (resource as any).updateItem,
  deleteUser: (resource as any).deleteItem,
    userRolesData,
    userStatusData,
    loadingRoles,
    loadingStatus,
    fetchUserRoles,
    fetchUserStatus,
  };
};

import { useState, useEffect } from 'react';
import { vaccinationsService } from '@/entities/vaccination/api/vaccinations.service';
import { Vaccinations } from '@/entities/vaccination/model/types';
import type { VaccinationInput, VaccinationResponse } from '@/shared/api/generated/swaggerTypes';

export const useVaccinations = () => {
  const [vaccinations, setVaccinations] = useState<Vaccinations[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [reload, setReload] = useState<boolean>(false);

  const fetchVaccinations = async () => {
    setLoading(true);
    try {
      const page = await vaccinationsService.getVaccinations({ page: 1, limit: 10 });
      const normalized: Vaccinations[] = (Array.isArray((page as any)?.data) ? (page as any).data : []).map(mapVaccinationResponseToLocal);
      setVaccinations(normalized);
    } catch (err) {
      setError('Error al cargar las vacunaciones');
    } finally {
      setLoading(false);
    }
  };

  const addVaccination = async (vaccinationData: Vaccinations) => {
    setLoading(true);
    try {
      const payload: VaccinationInput = {
        animal_id: vaccinationData.animal_id,
        vaccine_id: vaccinationData.vaccine_id,
        vaccination_date: vaccinationData.application_date,
        apprentice_id: vaccinationData.apprentice_id,
        instructor_id: vaccinationData.instructor_id,
      };
      const newVaccination = await vaccinationsService.create(payload as Partial<VaccinationInput>);
      const mapped = mapVaccinationResponseToLocal(newVaccination as VaccinationResponse);
      setVaccinations((prev) => [...prev, mapped]);
      setReload(!reload);
      return mapped;
    } catch (err) {
      setError('Error al agregar la vacunacion');
      return null;
    } finally {
      setLoading(false);
    }
  };

  const editVaccination = async (id: number, vaccinationData: Vaccinations) => {
    setLoading(true);
    try {
      const payload: VaccinationInput = {
        animal_id: vaccinationData.animal_id,
        vaccine_id: vaccinationData.vaccine_id,
        vaccination_date: vaccinationData.application_date,
        apprentice_id: vaccinationData.apprentice_id,
        instructor_id: vaccinationData.instructor_id,
      };
      const updatedVaccination = await vaccinationsService.update(id, payload as Partial<VaccinationInput>);
      const mapped = mapVaccinationResponseToLocal(updatedVaccination as VaccinationResponse);
      setVaccinations((prev) => prev.map((vaccination) => (vaccination.id === id ? mapped : vaccination)));
      setReload(!reload);
      return mapped;
    } catch (err) {
      setError('Error al actualizar la vacunacion');
      return null;
    } finally {
      setLoading(false);
    }
  };

  const deleteVaccination = async (id: number | string): Promise<boolean> => {
    setLoading(true);
    try {
      await vaccinationsService.delete(id);
      setVaccinations((prev) => prev.filter((v) => v.id !== Number(id)));
      setReload(!reload);
      return true;
    } catch (err) {
      setError('Error al eliminar la vacunacion');
      return false;
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchVaccinations();
  }, [reload]);

  // Aliases estandarizados para compatibilidad
  const createItem = (payload: Partial<Vaccinations>) => addVaccination(payload as Vaccinations);
  const updateItem = (id: number | string, payload: Partial<Vaccinations>) => editVaccination(Number(id), payload as Vaccinations);
  const deleteItem = (id: number | string) => deleteVaccination(id);
  const refetch = () => fetchVaccinations();

  return {
    vaccinations,
    data: vaccinations,
    loading,
    error,
    fetchVaccinations,
    addVaccination,
    editVaccination,
    deleteVaccination,
    createItem,
    updateItem,
    deleteItem,
    setData: setVaccinations,
    refetch,
  };
};

function mapVaccinationResponseToLocal(r: VaccinationResponse): Vaccinations {
  return {
    id: r.id,
    animal_id: r.animal_id,
    vaccine_id: r.vaccine_id,
    application_date: r.vaccination_date,
    apprentice_id: r.apprentice_id,
    instructor_id: r.instructor_id || 0,
    animals: undefined,
    vaccines: undefined,
  };
}

import { vaccinesService } from '@/entities/vaccine/api/vaccines.service';
import { Vaccines, route_administration, vaccine_type } from '@/entities/vaccine/model/types';
import type { VaccineResponse } from '@/shared/api/generated/swaggerTypes';
import useResource from '@/shared/hooks/useResource';
import type { Dispatch, SetStateAction } from 'react';

// Normalizer: maps API VaccineResponse (flexible) to local Vaccines type
const mapVaccineResponseToLocal = (v: Partial<VaccineResponse> & { [key: string]: any }): Vaccines => {
  // Derive route administration name and id from multiple possible shapes
  const rawRouteName: string | undefined = (v as any).route_administration_name
    ?? (v as any).route_administration?.name
    ?? (v as any).administration_route
    ?? (v as any).route_administration;
  const route_administration_id: number | undefined = (v as any).route_administration_id
    ?? (v as any).route_administration?.id;

  // Normalize to our local union (fix common accent differences)
  const normalizeRoute = (name?: string): route_administration => {
    const n = (name || '').toLowerCase();
    if (n.includes('oral')) return 'Oral';
    if (n.includes('intranasal')) return 'Intranasal';
    if (n.includes('intramuscular')) return 'Intramuscular';
    if (n.includes('intravenosa')) return 'Intravenosa';
    if (n.includes('subcut')) return 'Subcutánea';
    if (n.includes('top') || n.includes('tóp')) return 'Topica';
    return 'Oral';
  };

  // Support both "type" and "vaccine_type" coming from API/backoffice
  const vaccineType: vaccine_type = ((v as any).type as vaccine_type)
    ?? ((v as any).vaccine_type as vaccine_type)
    ?? 'Atenuada';

  // Map nacional plan as string for UI; prefer backend string when present
  const national_plan: string = (v as any).national_plan
    ?? (typeof (v as any).is_mandatory === 'boolean' ? ((v as any).is_mandatory ? 'Sí' : 'No') : '');

  // Target disease single id (our local type expects a single number)
  const target_disease_id: number = (v as any).target_disease_id
    ?? (Array.isArray((v as any).target_diseases) && (v as any).target_diseases[0])
    ?? 0;

  return {
    id: (v.id as number) ?? 0,
    name: (v.name as string) ?? '',
    dosis: (v as any).dosis ?? (v as any).dosage ?? (v as any).dose ?? '',
    route_administration: normalizeRoute(rawRouteName),
    route_administration_id,
    vaccination_interval: (v as any).vaccination_interval ?? '',
    vaccine_type: vaccineType,
    national_plan,
    target_disease_id,
    diseases: (v as any).diseases,
  } as Vaccines;
};

export interface UseVaccinesResult {
  vaccines: Vaccines[];
  data: Vaccines[];
  loading: boolean;
  refreshing: boolean;
  error: string | null;
  refetch: (params?: Record<string, any>) => Promise<Vaccines[]>;
  // Alias de compatibilidad en línea con otros hooks
  createItem: (payload: Partial<Vaccines>) => Promise<Vaccines | null>;
  updateItem: (id: number | string, payload: Partial<Vaccines>) => Promise<Vaccines | null>;
  // API específica ya adoptada por consumidores
  addVaccine: (payload: Partial<Vaccines>) => Promise<Vaccines | null>;
  editVaccine: (id: number | string, payload: Partial<Vaccines>) => Promise<Vaccines | null>;
  deleteVaccine: (id: number | string) => Promise<boolean>;
  // Alias consistente con el resto del proyecto
  deleteItem?: (id: number | string) => Promise<boolean>;
  setData: Dispatch<SetStateAction<Vaccines[]>>;
  // Meta y setters opcionales según useResource
  meta?: {
    page: number;
    limit: number;
    total: number;
    totalPages?: number;
    hasNextPage?: boolean;
    hasPreviousPage?: boolean;
    rawMeta?: any;
  } | null;
  setPage?: (page: number) => void;
  setLimit?: (limit: number) => void;
  setSearch?: (s: string) => void;
  setFields?: (f: string) => void;
}

export function useVaccines(): UseVaccinesResult {
  const resource = useResource<VaccineResponse, any>(vaccinesService as any, {
    initialParams: { page: 1, limit: 10 },
    map: ((items: any[]) => (items as VaccineResponse[]).map(mapVaccineResponseToLocal)) as any,
  });

  const mapped = resource.data as unknown as Vaccines[];

  // Envolver create/update para retornar y almacenar Vaccines (no VaccineResponse)
  const addVaccine = async (payload: Partial<Vaccines>): Promise<Vaccines | null> => {
    const created = await (resource.createItem as any)(payload as any);
    if (!created) return null;
    const mappedCreated = mapVaccineResponseToLocal(created as any);
    resource.setData((prev: any[]) => {
      const clean = Array.isArray(prev) ? prev.filter((x: any) => (x?.id) !== (created as any)?.id) : [];
      return [...clean, mappedCreated] as any;
    });
    return mappedCreated;
  };

  const editVaccine = async (id: number | string, payload: Partial<Vaccines>): Promise<Vaccines | null> => {
    const updated = await (resource.updateItem as any)(id, payload as any);
    if (!updated) return null;
    const mappedUpdated = mapVaccineResponseToLocal(updated as any);
    resource.setData((prev: any[]) => {
      const arr = Array.isArray(prev) ? prev : [];
      return arr.map((x: any) => (x?.id === (updated as any)?.id || x?.id === id) ? { ...x, ...mappedUpdated } : x) as any;
    });
    return mappedUpdated;
  };

  // Alias para API consistente con otros hooks
  const createItem = addVaccine;
  const updateItem = editVaccine;

  return {
    vaccines: mapped,
    data: mapped,
    loading: resource.loading,
    refreshing: (resource as any).refreshing ?? false,
    error: resource.error,
    refetch: resource.refetch as unknown as (params?: Record<string, any>) => Promise<Vaccines[]>,
    createItem,
    updateItem,
    addVaccine,
    editVaccine,
    deleteVaccine: resource.deleteItem,
    deleteItem: resource.deleteItem,
    setData: resource.setData as unknown as Dispatch<SetStateAction<Vaccines[]>>,
    // Nuevos: meta y setters de paginación/búsqueda/proyección
    meta: resource.meta,
    setPage: resource.setPage,
    setLimit: resource.setLimit,
    setSearch: resource.setSearch,
    setFields: resource.setFields,
  };
}

