import { apiFetch } from '@/shared/api/apiFetch';

export type ActivityAction = 'create' | 'update' | 'delete' | 'alert' | 'system';
export type ActivitySeverity = 'low' | 'medium' | 'high';
export type ActivityEntity =
  | 'animal'
  | 'treatment'
  | 'vaccination'
  | 'control'
  | 'field'
  | 'disease'
  | 'improvement'
  | (string & {});

export type ActivityLinks = Partial<{
  detail: string;
  animal: string;
  crud: string;
  analytics: string;
}>;

export type ActivityItem = {
  id: string | number;
  action: ActivityAction | (string & {});
  entity: ActivityEntity;
  entity_id?: string | number;
  user_id?: number;
  timestamp: string;
  severity?: ActivitySeverity | (string & {});
  title?: string;
  summary?: string;
  metadata?: Record<string, any>;
  links?: ActivityLinks;
  animal_id?: number;
};

export type ActivityQuery = {
  page?: number;
  limit?: number;
  per_page?: number;
  entity?: string;
  action?: string;
  severity?: string;
  from?: string;
  to?: string;
  animalId?: number | string;
  entityId?: number | string;
  userId?: number | string;
  fields?: string | string[];
  include?: string | string[];
  scope?: string;
  cursor?: string;
};

export type ActivityPage = {
  items: ActivityItem[];
  page: number;
  limit: number;
  total?: number;
  total_pages?: number;
  has_next?: boolean;
  next_cursor?: string;
};

const toNumber = (value: any): number | undefined => {
  const n = Number(value);
  return Number.isFinite(n) ? n : undefined;
};

const extractItems = (payload: any): ActivityItem[] => {
  if (!payload) return [];
  if (Array.isArray(payload)) return payload as ActivityItem[];
  if (Array.isArray(payload.items)) return payload.items as ActivityItem[];
  if (Array.isArray(payload.events)) return payload.events as ActivityItem[];
  if (Array.isArray(payload.data)) return payload.data as ActivityItem[];
  if (Array.isArray(payload.results)) return payload.results as ActivityItem[];
  return [];
};

type FetchOpts = { signal?: AbortSignal };

const buildActivityParams = ({
  page,
  limit,
  per_page,
  entity,
  action,
  severity,
  from,
  to,
  animalId,
  entityId,
  userId,
  fields,
  include,
  scope,
  cursor,
}: ActivityQuery) => {
  const resolvedPage = page ?? 1;
  const resolvedPerPage = per_page ?? limit ?? 20;

  const params = new URLSearchParams();
  // Solo enviar 'page' si no estamos usando cursor, o si el backend soporta ambos (híbrido).
  // La guía sugiere cursor para timeline.
  if (!cursor) {
    params.set('page', String(resolvedPage));
  } else {
    params.set('cursor', cursor);
  }

  params.set('per_page', String(resolvedPerPage));
  params.set('limit', String(resolvedPerPage));

  if (entity) params.set('entity', entity);
  if (action) params.set('action', action);
  if (severity) params.set('severity', severity);
  if (from) params.set('from', from);
  if (to) params.set('to', to);
  if (animalId != null && String(animalId).trim() !== '') params.set('animal_id', String(animalId));
  if (entityId != null && String(entityId).trim() !== '') params.set('entity_id', String(entityId));
  if (userId != null && String(userId).trim() !== '') params.set('user_id', String(userId));

  if (fields) params.set('fields', Array.isArray(fields) ? fields.join(',') : fields);
  if (include) params.set('include', Array.isArray(include) ? include.join(',') : include);
  if (scope) params.set('scope', scope);

  return { params, resolvedPage, resolvedPerPage };
};

function readPagination(raw: any): any {
  return (
    raw?.meta?.pagination ??
    raw?.data?.meta?.pagination ??
    raw?.data?.pagination ??
    raw?.data?.meta ??
    raw?.meta ??
    raw?.pagination ??
    raw ??
    {}
  );
}

function toActivityPage(raw: any, fallback: { page: number; limit: number }): ActivityPage {
  const data = raw?.data ?? raw;
  const items = extractItems(data);

  const pagination = readPagination(raw);
  const resolvedPage = toNumber(pagination.page) ?? fallback.page;
  const resolvedLimit =
    toNumber(pagination.limit) ??
    toNumber(pagination.per_page) ??
    toNumber(pagination.perPage) ??
    fallback.limit;

  return {
    items,
    page: resolvedPage,
    limit: resolvedLimit,
    total: toNumber(pagination.total),
    total_pages: toNumber(pagination.total_pages) ?? toNumber(pagination.totalPages),
    has_next: typeof pagination.has_next === 'boolean' ? pagination.has_next : undefined,
    next_cursor: pagination.next_cursor || pagination.cursor || undefined,
  };
}

export async function fetchActivity(
  {
    page = 1,
    limit = 20,
    per_page,
    entity,
    action,
    severity,
    from,
    to,
    animalId,
    entityId,
    userId,
  }: ActivityQuery = {},
  opts: FetchOpts = {}
): Promise<ActivityPage> {
  const { params } = buildActivityParams({
    page,
    limit,
    per_page,
    entity,
    action,
    severity,
    from,
    to,
    animalId,
    entityId,
    userId,
  });

  const basePath =
    userId != null && String(userId).trim() !== ''
      ? `users/${encodeURIComponent(String(userId))}/activity`
      : 'activity';

  const res = await apiFetch<any>({ url: `${basePath}?${params.toString()}`, method: 'GET', signal: opts.signal });

  return toActivityPage(res.data, { page, limit });
}

export type ActivitySummaryWindow = {
  totals?: {
    events?: number;
    distinct_animals?: number;
  };
  by_entity?: Array<{ entity: string; count: number }>;
  daily?: Array<{ date: string; count: number }>;
};

export type MyActivitySummary = {
  last_activity_at?: string | null;
  window_7d?: ActivitySummaryWindow;
  window_30d?: ActivitySummaryWindow;
};

export async function fetchMyActivity(query: ActivityQuery = {}, opts: FetchOpts = {}): Promise<ActivityPage> {
  const { params, resolvedPage, resolvedPerPage } = buildActivityParams(query);

  const res = await apiFetch<any>({ url: `activity/me?${params.toString()}`, method: 'GET', signal: opts.signal });

  return toActivityPage(res.data, { page: resolvedPage, limit: resolvedPerPage });
}

export async function fetchMyActivitySummary(opts: FetchOpts = {}): Promise<MyActivitySummary> {
  const res = await apiFetch<any>({ url: 'activity/me/summary', method: 'GET', signal: opts.signal });
  return (res.data?.data ?? res.data) as MyActivitySummary;
}

export async function fetchMyActivityStats(
  { days = 30, ...query }: ActivityQuery & { days?: number } = {},
  opts: FetchOpts = {}
) {
  const { params } = buildActivityParams(query);
  params.set('days', String(days));

  const res = await apiFetch<any>({ url: `activity/me/stats?${params.toString()}`, method: 'GET', signal: opts.signal });

  return res.data?.data ?? res.data;
}

export async function fetchActivityStats(
  { days = 30, ...query }: ActivityQuery & { days?: number } = {},
  opts: FetchOpts = {}
) {
  const { params } = buildActivityParams(query);
  params.set('days', String(days));

  const res = await apiFetch<any>({ url: `activity/stats?${params.toString()}`, method: 'GET', signal: opts.signal });

  return res.data?.data ?? res.data;
}

export async function fetchActivityFilters({ days = 365 }: { days?: number } = {}, opts: FetchOpts = {}) {
  const params = new URLSearchParams({ days: String(days) });

  const res = await apiFetch<any>({ url: `activity/filters?${params.toString()}`, method: 'GET', signal: opts.signal });

  return res.data?.data ?? res.data;
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { ActivityPage, ActivityQuery, fetchActivity } from '@/features/activity/api/activity.service';

type CacheEntry = { ts: number; data: ActivityPage };

const DEFAULT_TTL_MS = 30_000;

const buildCacheKey = (query: ActivityQuery) =>
  JSON.stringify({
    page: query.page,
    limit: query.limit,
    entity: query.entity ?? null,
    action: query.action ?? null,
    severity: query.severity ?? null,
    from: query.from ?? null,
    to: query.to ?? null,
    animalId: query.animalId ?? null,
    entityId: query.entityId ?? null,
    userId: query.userId ?? null,
    fields: query.fields ?? null,
    include: query.include ?? null,
    scope: query.scope ?? null,
    cursor: query.cursor ?? null,
  });

export function useActivityFeed(
  query: ActivityQuery,
  opts: {
    enableCache?: boolean;
    ttlMs?: number;
    enabled?: boolean;
    fetcher?: (q: ActivityQuery, o?: { signal?: AbortSignal }) => Promise<ActivityPage>;
  } = {}
) {
  const enabled = opts.enabled !== false;
  const fetcher = opts.fetcher ?? fetchActivity;
  const resolvedQuery = useMemo(
    () => ({
      page: query.page ?? 1,
      limit: query.limit ?? 20,
      per_page: query.per_page,
      entity: query.entity,
      action: query.action,
      severity: query.severity,
      from: query.from,
      to: query.to,
      animalId: query.animalId,
      entityId: query.entityId,
      userId: query.userId,
      fields: query.fields,
      include: query.include,
      scope: query.scope,
      cursor: query.cursor,
    }),
    [
      query.page,
      query.limit,
      query.per_page,
      query.entity,
      query.action,
      query.severity,
      query.from,
      query.to,
      query.animalId,
      query.entityId,
      query.userId,
      query.fields,
      query.include,
      query.scope,
      query.cursor,
    ]
  );

  const enableCache = opts.enableCache !== false;
  const ttlMs = typeof opts.ttlMs === 'number' ? opts.ttlMs : DEFAULT_TTL_MS;

  const cacheRef = useRef<Map<string, CacheEntry>>(new Map());
  const [data, setData] = useState<ActivityPage | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const cacheKey = useMemo(() => buildCacheKey(resolvedQuery), [resolvedQuery]);

  const load = useCallback(
    async (signal?: AbortSignal) => {
      setLoading(true);
      setError(null);
      try {
        if (enableCache) {
          const cached = cacheRef.current.get(cacheKey);
          if (cached && Date.now() - cached.ts < ttlMs) {
            setData(cached.data);
            setLoading(false);
            return;
          }
        }
        const page = await fetcher(resolvedQuery, { signal });
        if (enableCache) {
          cacheRef.current.set(cacheKey, { ts: Date.now(), data: page });
        }
        setData(page);
      } catch (e: any) {
        if (e?.name === 'AbortError') return;
        setError(e?.message || 'Error cargando actividad');
        setData(null);
      } finally {
        setLoading(false);
      }
    },
    [cacheKey, enableCache, fetcher, resolvedQuery, ttlMs]
  );

  useEffect(() => {
    if (!enabled) return;
    const controller = new AbortController();
    load(controller.signal);
    return () => controller.abort();
  }, [enabled, load]);

  const refetch = useCallback(() => {
    cacheRef.current.delete(cacheKey);
    load();
  }, [cacheKey, load]);

  return {
    items: data?.items ?? [],
    meta: data,
    loading,
    error,
    refetch,
  };
}

import { useMemo } from 'react';

// Tipos base para compatibilidad
export type ActivityAction = 'create' | 'update' | 'delete' | 'alert' | 'system';
export type ActivitySeverity = 'low' | 'medium' | 'high';
export type ActivityEntity =
    | 'animal'
    | 'treatment'
    | 'vaccination'
    | 'control'
    | 'field'
    | 'disease'
    | 'improvement'
    | (string & {});

export interface ActivityLink {
    detail?: string;
    animal?: string;
    crud?: string;
    analytics?: string;
}

export interface ActivityItem {
    id: string; // ID único compuesto
    action: ActivityAction;
    entity: ActivityEntity;
    entity_id: number | string;
    timestamp: string; // ISO string
    ts: number; // Epoch para ordenamiento rápido
    title: string;
    summary: string;
    severity: ActivitySeverity;
    links?: ActivityLink;
    animal_id?: number;
    animal_label?: string;
}

interface UseDerivedActivityProps {
    animals?: any[];
    treatments?: any[];
    vaccinations?: any[];
    controls?: any[];
    fields?: any[];
    genetics?: any[];
    diseases?: any[];
}

export function useDerivedActivity({
    animals = [],
    treatments = [],
    vaccinations = [],
    controls = [],
    fields = [],
    genetics = [],
    diseases = []
}: UseDerivedActivityProps) {

    // Helper para convertir fechas
    const toEpochMs = (value: any): number | null => {
        if (!value) return null;
        if (typeof value === 'number') return Number.isFinite(value) ? value : null;
        if (value instanceof Date) return value.getTime();
        const parsed = new Date(String(value)).getTime();
        return Number.isFinite(parsed) ? parsed : null;
    };

    const activityEvents = useMemo(() => {
        const now = Date.now();
        const events: ActivityItem[] = [];

        const pushEvent = (
            entity: ActivityEntity,
            entityId: number | string,
            action: ActivityAction,
            baseDate: any,
            title: string,
            summary: string,
            severity: ActivitySeverity = 'low',
            animalId?: number,
            animalLabel?: string,
            links?: ActivityLink
        ) => {
            const ts = toEpochMs(baseDate);
            if (!ts) return;

            const id = `${entity}:${entityId}:${action}:${ts}`;
            events.push({
                id,
                entity,
                entity_id: entityId,
                action,
                timestamp: new Date(ts).toISOString(),
                ts,
                title,
                summary,
                severity,
                animal_id: animalId,
                animal_label: animalLabel,
                links
            });
        };

        // 1. ANIMALES
        animals.forEach(a => {
            const animalId = Number(a.id);
            const label = a.name || a.code || a.record || 'Animal';

            // Creación / Registro
            pushEvent(
                'animal',
                a.id,
                'create',
                a.created_at || a.updated_at,
                `Animal registrado`,
                `${label} · ${a.breed?.name || ''} · ${a.gender || ''}`,
                'low',
                animalId,
                label
            );
        });

        // 2. TRATAMIENTOS
        treatments.forEach(t => {
            const animalId = t.animal_id || t.animal?.id;
            const label = t.animal_label || t.animal?.code || t.animal?.record || 'Animal';

            // Registro
            pushEvent(
                'treatment',
                t.id,
                'create',
                t.treatment_date || t.created_at,
                'Tratamiento iniciado',
                `${label} · ${t.medication?.name || 'Medicamento'} · ${t.diagnosis || ''}`,
                'medium',
                animalId,
                label
            );

            // Alerta de vencimiento / finalización
            const endTs = toEpochMs(t.end_date);
            if (endTs && endTs > 0) {
                const isOverdue = endTs < now;
                if (isOverdue) {
                    pushEvent(
                        'treatment',
                        t.id,
                        'alert',
                        endTs,
                        'Fin de tratamiento',
                        `${label} · Tratamiento finalizado o vencido`,
                        'high',
                        animalId,
                        label
                    );
                }
            }
        });

        // 3. VACUNACIONES
        vaccinations.forEach(v => {
            const animalId = v.animal_id || v.animal?.id;
            const label = v.animal_label || v.animal?.code || v.animal?.record || 'Animal';

            pushEvent(
                'vaccination',
                v.id,
                'create',
                v.application_date || v.created_at,
                'Vacuna aplicada',
                `${label} · ${v.vaccine?.name || 'Vacuna'}`,
                'low',
                animalId,
                label
            );

            // Próxima dosis
            const nextTs = toEpochMs(v.next_dose_date);
            if (nextTs && nextTs > 0) {
                const isOverdue = nextTs < now;
                const isUpcoming = !isOverdue && (nextTs - now < 7 * 24 * 60 * 60 * 1000); // 7 días

                if (isOverdue || isUpcoming) {
                    pushEvent(
                        'vaccination',
                        v.id,
                        'alert',
                        nextTs,
                        isOverdue ? 'Refuerzo vencido' : 'Próximo refuerzo',
                        `${label} · ${v.vaccine?.name || 'Vacuna'}`,
                        isOverdue ? 'high' : 'medium',
                        animalId,
                        label
                    );
                }
            }
        });

        // 4. CONTROLES
        controls.forEach(c => {
            const animalId = c.animal_id || c.animal?.id;
            const label = c.animal_label || c.animal?.code || c.animal?.record || 'Animal';

            pushEvent(
                'control',
                c.id,
                'create',
                c.checkup_date || c.created_at,
                'Control realizado',
                `${label} · ${c.health_status || 'Estado desconocido'}`,
                c.health_status === 'Enfermo' ? 'medium' : 'low',
                animalId,
                label
            );
        });

        // 5. MOVIMIENTOS / LOTES
        fields.forEach(f => {
            const animalId = f.animal_id || f.animal?.id;
            const label = f.animal_label || f.animal?.code || f.animal?.record || 'Animal';

            pushEvent(
                'field',
                f.id,
                'update',
                f.entry_date || f.created_at,
                'Traslado de lote',
                `${label} -> ${f.field?.name || 'Lote'}`,
                'low',
                animalId,
                label
            );
        });

        // 6. MEJORAS GENÉTICAS
        genetics.forEach(g => {
            const animalId = g.animal_id || g.animal?.id;
            const label = g.animal_label || g.animal?.code || g.animal?.record || 'Animal';

            pushEvent(
                'improvement',
                g.id,
                'create',
                g.date || g.created_at,
                'Mejora Genética',
                `${label} · ${g.type || 'Evento'}`,
                'low',
                animalId,
                label
            );
        });

        // 7. ENFERMEDADES
        diseases.forEach(d => {
            const animalId = d.animal_id || d.animal?.id;
            const label = d.animal_label || d.animal?.code || d.animal?.record || 'Animal';

            pushEvent(
                'disease',
                d.id,
                'create',
                d.diagnosis_date || d.created_at,
                'Diagnóstico Enfermedad',
                `${label} · ${d.disease?.name || 'Enfermedad'} · ${d.status || ''}`,
                'high',
                animalId,
                label
            );
        });

        // Ordenar descendente por fecha (más reciente primero)
        return events.sort((a, b) => b.ts - a.ts);
    }, [animals, treatments, vaccinations, controls, fields, genetics, diseases]);

    return {
        items: activityEvents,
        count: activityEvents.length,
        isEmpty: activityEvents.length === 0
    };
}

import React from 'react';
