            </Button>
          </div>
        </div>
      </motion.div>
    </AnimatePresence>
  );
};

import React, { useState, useEffect } from 'react';
import { 
  Dialog, 
  DialogContent, 
  DialogHeader, 
  DialogTitle, 
  DialogDescription,
  DialogFooter
} from '@/shared/ui/dialog';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Label } from '@/shared/ui/label';
import { Textarea } from '@/shared/ui/textarea';
import { 
  MapPin, 
  Calendar as CalendarIcon, 
  Loader2,
  CircleCheck,
  ArrowRightLeft,
  AlertTriangle
} from 'lucide-react';
import { animalFieldsService } from '@/entities/animal/api/animalFields.service';
import { fieldService } from '@/entities/field/api/field.service';
import { useToast } from '@/app/providers/ToastContext';
import { Badge } from '@/shared/ui/badge';
import { ScrollArea } from '@/shared/ui/scroll-area';

interface Field {
  id: number;
  name: string;
  ubication: string;
  state: string;
  capacity: string;
  animal_count: number;
}

interface SelectedAnimalSummary {
  id: number;
  label: string;
  status?: string;
  fieldName?: string;
}

interface BatchFieldTransferModalProps {
  isOpen: boolean;
  onClose: () => void;
  selectedAnimalIds: number[];
  selectedAnimals?: SelectedAnimalSummary[];
  onSuccess: () => void;
}

const getToday = () => new Date().toISOString().split('T')[0];

const getItemsFromResponse = <T,>(response: any): T[] => {
  if (Array.isArray(response)) return response as T[];
  if (Array.isArray(response?.data)) return response.data as T[];
  if (Array.isArray(response?.items)) return response.items as T[];
  if (Array.isArray(response?.results)) return response.results as T[];
  return [];
};

const parseCapacity = (value: unknown) => {
  const parsed = Number.parseInt(String(value ?? ''), 10);
  return Number.isFinite(parsed) ? parsed : null;
};

export const BatchFieldTransferModal: React.FC<BatchFieldTransferModalProps> = ({
  isOpen,
  onClose,
  selectedAnimalIds,
  selectedAnimals = [],
  onSuccess
}) => {
  const { showToast } = useToast();
  const [fields, setFields] = useState<Field[]>([]);
  const [loadingFields, setLoadingFields] = useState(false);
  const [selectedFieldId, setSelectedFieldId] = useState<number | null>(null);
  const [transferDate, setTransferDate] = useState(getToday());
  const [notes, setNotes] = useState('');
  const [transferring, setTransferring] = useState(false);

  // Cargar potreros disponibles
  useEffect(() => {
    if (isOpen) {
      setSelectedFieldId(null);
      setTransferDate(getToday());
      setNotes('');
      const fetchFields = async () => {
        setLoadingFields(true);
        try {
          const resp = await fieldService.getFields({ limit: 100 });
          setFields(getItemsFromResponse<Field>(resp));
        } catch (error) {
          showToast('Error al cargar potreros', 'error');
        } finally {
          setLoadingFields(false);
        }
      };
      fetchFields();
    }
  }, [isOpen, showToast]);

  const selectedField = fields.find((field) => field.id === selectedFieldId) || null;
  const selectedFieldCapacity = selectedField ? parseCapacity(selectedField.capacity) : null;
  const selectedFieldOccupancy = selectedField?.animal_count ?? 0;
  const projectedOccupancy = selectedFieldOccupancy + selectedAnimalIds.length;
  const isOverCapacity = selectedFieldCapacity !== null && projectedOccupancy > selectedFieldCapacity;
  const animalPreview = selectedAnimals.length > 0
    ? selectedAnimals
    : selectedAnimalIds.map((id) => ({ id, label: `Animal #${id}` }));

  const handleTransfer = async () => {
    if (!selectedFieldId) {
      showToast('Por favor selecciona un potrero de destino', 'warning');
      return;
    }

    setTransferring(true);
    try {
      const response = await animalFieldsService.bulkTransfer({
        animal_ids: selectedAnimalIds,
        field_id: selectedFieldId,
        date: transferDate,
        notes: notes || `Traslado masivo de ${selectedAnimalIds.length} animales`
      });

      if (response.success) {
        showToast(`Traslado exitoso: ${selectedAnimalIds.length} animales movidos`, 'success');
        onSuccess();
        onClose();
      } else {
        showToast(response.message || 'Error en el traslado', 'error');
      }
    } catch (error: any) {
      showToast(error.message || 'Error al conectar con el servidor', 'error');
    } finally {
      setTransferring(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent
        className="max-w-[95vw] bg-card/95 backdrop-blur-xl border-white/10 rounded-2xl overflow-hidden p-0"
        style={{ width: 'min(920px, 95vw)', maxWidth: '95vw' }}
      >
        <DialogHeader className="p-6 sm:p-8 bg-gradient-to-br from-emerald-500/10 to-transparent border-b border-white/5">
          <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
            <div className="flex items-center gap-4">
              <div className="h-12 w-12 rounded-2xl bg-emerald-500/20 flex items-center justify-center border border-emerald-500/30">
                <ArrowRightLeft className="h-6 w-6 text-emerald-500" />
              </div>
              <div>
                <DialogTitle className="text-2xl font-black tracking-tight">Mover animales a otro potrero</DialogTitle>
                <DialogDescription className="font-semibold text-sm text-muted-foreground">
                  Se moveran {selectedAnimalIds.length} animales seleccionados al potrero que elijas.
                </DialogDescription>
              </div>
            </div>
            <Badge variant="success" className="self-start sm:self-center">
              {selectedAnimalIds.length} seleccionados
            </Badge>
          </div>
        </DialogHeader>

        <div className="grid max-h-[68vh] grid-cols-1 overflow-y-auto lg:grid-cols-[300px_minmax(0,1fr)]">
          <aside className="border-b border-border/60 bg-muted/20 p-5 lg:border-b-0 lg:border-r">
            <div className="space-y-4">
              <div>
                <p className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground">
                  Animales marcados
                </p>
                <p className="mt-1 text-sm font-semibold text-foreground">
                  Revisa que el lote sea correcto antes de confirmar.
                </p>
              </div>

              <ScrollArea className="h-[180px] rounded-xl border border-border/60 bg-background/70 p-2">
                <div className="space-y-2 pr-2">
                  {animalPreview.slice(0, 12).map((animal) => (
                    <div key={animal.id} className="flex items-center justify-between gap-2 rounded-lg bg-card px-3 py-2 text-sm shadow-sm">
                      <span className="min-w-0 truncate font-bold">{animal.label}</span>
                      <span className="shrink-0 text-[11px] font-semibold text-muted-foreground">#{animal.id}</span>
                    </div>
                  ))}
                  {animalPreview.length > 12 && (
                    <div className="rounded-lg border border-dashed border-border px-3 py-2 text-center text-xs font-semibold text-muted-foreground">
                      +{animalPreview.length - 12} animales mas
                    </div>
                  )}
                </div>
              </ScrollArea>

              <div className="space-y-2">
                <Label htmlFor="batch-transfer-date" className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground">
                  Fecha del traslado
                </Label>
                <div className="relative">
                  <Input
                    id="batch-transfer-date"
                    type="date"
                    value={transferDate}
                    onChange={(e) => setTransferDate(e.target.value)}
                    className="h-11 rounded-xl pl-10"
                  />
                  <CalendarIcon className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                </div>
              </div>

              {selectedField && (
                <div className="rounded-xl border border-emerald-200 bg-emerald-50 p-4 text-emerald-950">
                  <p className="text-[10px] font-black uppercase tracking-[0.2em] text-emerald-700">
                    Destino
                  </p>
                  <p className="mt-1 text-base font-black">{selectedField.name}</p>
                  <p className="mt-1 text-xs font-semibold text-emerald-800">
                    Quedaria en {projectedOccupancy}
                    {selectedFieldCapacity !== null ? ` / ${selectedFieldCapacity}` : ''} animales.
                  </p>
                  {isOverCapacity && (
                    <div className="mt-3 flex items-start gap-2 rounded-lg bg-amber-100 px-3 py-2 text-amber-900">
                      <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />
                      <p className="text-xs font-semibold">
                        Este potrero quedaria por encima de su capacidad registrada.
                      </p>
                    </div>
                  )}
                </div>
              )}
            </div>
          </aside>

          <div className="p-5 sm:p-6 space-y-6">
            <div className="space-y-3">
              <div className="flex items-center justify-between gap-3">
                <Label className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground">
                  Potrero de destino
                </Label>
                {loadingFields && <Loader2 className="h-4 w-4 animate-spin text-primary" />}
              </div>

              <ScrollArea className="h-[300px] pr-3">
                <div className="grid grid-cols-1 gap-3">
                  {fields.map((field) => {
                    const capacity = parseCapacity(field.capacity);
                    const occupancy = field.animal_count ?? 0;
                    const projected = occupancy + selectedAnimalIds.length;
                    const overCapacity = capacity !== null && projected > capacity;

                    return (
                      <button
                        key={field.id}
                        type="button"
                        onClick={() => setSelectedFieldId(field.id)}
                        className={`relative w-full rounded-xl border p-4 text-left transition-all ${
                          selectedFieldId === field.id
                            ? 'border-emerald-500 bg-emerald-500/10 shadow-lg shadow-emerald-500/10'
                            : 'border-border bg-background/70 hover:border-emerald-300 hover:bg-emerald-500/5'
                        }`}
                      >
                        <div className="flex items-center justify-between gap-4">
                          <div className="flex min-w-0 items-center gap-3">
                            <div className={`h-11 w-11 shrink-0 rounded-xl flex items-center justify-center transition-colors ${
                              selectedFieldId === field.id ? 'bg-emerald-600 text-white' : 'bg-muted text-muted-foreground'
                            }`}>
                              <MapPin className="h-5 w-5" />
                            </div>
                            <div className="min-w-0">
                              <div className="truncate text-sm font-black tracking-tight">{field.name}</div>
                              <div className="mt-0.5 truncate text-xs font-semibold text-muted-foreground">
                                {field.ubication || 'Sin ubicacion registrada'}
                              </div>
                            </div>
                          </div>

                          <div className="shrink-0 text-right">
                            <div className={`text-sm font-black ${overCapacity ? 'text-amber-700' : 'text-foreground'}`}>
                              {projected}{capacity !== null ? ` / ${capacity}` : ''}
                            </div>
                            <div className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">
                              despues
                            </div>
                          </div>
                        </div>

                        <div className="mt-3 flex items-center justify-between gap-2">
                          <span className="text-xs font-semibold text-muted-foreground">
                            Ahora tiene {occupancy} animales.
                          </span>
                          {selectedFieldId === field.id && (
                            <span className="inline-flex items-center gap-1 rounded-full bg-emerald-600 px-2.5 py-1 text-xs font-black text-white">
                              <CircleCheck className="h-3.5 w-3.5" />
                              Elegido
                            </span>
                          )}
                          {selectedFieldId !== field.id && overCapacity && (
                            <span className="inline-flex items-center gap-1 rounded-full bg-amber-100 px-2.5 py-1 text-xs font-bold text-amber-800">
                              <AlertTriangle className="h-3.5 w-3.5" />
                              Sobre cupo
                            </span>
                          )}
                        </div>
                      </button>
                    );
                  })}

                  {!loadingFields && fields.length === 0 && (
                    <div className="rounded-xl border border-dashed border-border p-8 text-center">
                      <p className="text-sm font-bold text-foreground">No hay potreros disponibles.</p>
                      <p className="mt-1 text-xs text-muted-foreground">Crea un potrero antes de mover animales.</p>
                    </div>
                  )}
                </div>
              </ScrollArea>
            </div>

            <div className="space-y-3">
              <Label htmlFor="batch-transfer-notes" className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground">
                Nota del movimiento
              </Label>
              <Textarea
                id="batch-transfer-notes"
                placeholder="Ej: Rotacion programada, descanso del potrero anterior..."
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                className="min-h-[88px] resize-none rounded-xl"
              />
            </div>
          </div>
        </div>

        <DialogFooter className="p-5 sm:p-6 bg-muted/20 border-t border-white/5 flex items-center justify-between gap-3">
          <Button variant="ghost" onClick={onClose} disabled={transferring} className="rounded-xl font-bold">
            Cancelar
          </Button>
          <Button 
            onClick={handleTransfer} 
            disabled={!selectedFieldId || transferring}
            className="rounded-xl h-12 px-6 font-black uppercase tracking-widest text-[11px] gap-2 shadow-xl shadow-emerald-500/20"
          >
            {transferring ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <CircleCheck className="h-4 w-4" />
            )}
            {selectedField ? `Mover ${selectedAnimalIds.length} animales` : 'Elige un potrero'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
