export const loginUser = async (userData: any) => {
  try {
    const result = await authService.login(userData.identification, userData.password);

    // Los datos ya vienen normalizados de authService.login
    let normalizedUser = result.user;
    let normalizedToken = result.access_token;

    // Si no hay token visible, intentar validar sesión vía /auth/me (cookie HttpOnly)
    if (!normalizedToken) {
      console.warn('⚠️ Token no recibido en el objeto de respuesta. Intentando validar sesión vía /auth/me...');
      try {
        const profile = await authService.getUserProfile();
        const userFromProfile = (profile as any)?.user ?? (profile as any)?.data?.user ?? undefined;
        if (userFromProfile) {
          normalizedUser = userFromProfile;
          normalizedToken = 'cookie'; // Marcador de sesión por cookie
          console.log('✅ Sesión validada vía /auth/me.');
        }
      } catch (e) {
        console.error('❌ No se pudo validar la sesión vía /auth/me:', e);
      }
    }

    // Verificar que se obtuvo algún indicador de sesión (token o usuario)
    if (!normalizedToken && !normalizedUser) {
      console.error('❌ Fallo crítico: Ni token en body ni sesión en cookie/me:', result);
      throw new Error('No se pudo establecer una sesión de autenticación');
    }

    return {
      success: true,
      data: result,
      user: normalizedUser,
      access_token: normalizedToken || 'cookie',
      message: result.message || 'Login exitoso'
    };
  } catch (error: any) {
    const parsed = readStandardErrorPayload(error);
    throw { 
      status: parsed.status, 
      data: parsed.raw, 
      message: parsed.message || 'Error al iniciar sesión',
      code: parsed.code,
      details: parsed.details
    };
  }
};


export const isAuthenticated = async () => {
  try {
    const profile = await authService.getUserProfile();
    return !!profile?.user;
  } catch (error) {
    logAuthWarning('isAuthenticated', error);
    return false;
  }
};

