import { useEffect, useState, useCallback, useMemo, useRef } from 'react';
import axios from 'axios';
import { unwrapApi } from '@/shared/api/client';
import { apiFetch } from '@/shared/api/apiFetch';

interface StatsState<T=any> {
  data: T | null;
  loading: boolean;
  error: string | null;
  refresh: () => void;
}

const normalizeModel = (model: string) => model.replace(/Service$/,'').toLowerCase();

// Debounce helper with cancel capability
const debounce = <T extends (...args: any[]) => any>(func: T, delay: number) => {
  let timeoutId: any;
  const debounced = (...args: Parameters<T>) => {
    if (timeoutId) clearTimeout(timeoutId);
    timeoutId = setTimeout(() => func(...args), delay);
  };
  // attach cancel method to clear pending timer
  (debounced as any).cancel = () => { if (timeoutId) { clearTimeout(timeoutId); timeoutId = null; } };
  return debounced as T & { cancel?: () => void };
};

interface UsersStats { total_users?: number; status_distribution?: { active?: number; inactive?: number } }
interface AnimalsStats { total_animals?: number; by_sex?: { Hembra?: number; Macho?: number }; by_status?: Record<string, number>; average_weight?: number }
interface HealthStatsN { summary: { total_treatments?: number; active_treatments?: number; total_vaccinations?: number; pending_vaccinations?: number } }
interface ProductionStatsN { summary: { total_controls?: number; total_fields?: number; field_utilization?: number; animals_per_field?: number; monthly_costs?: number } }
type NormalizedStats = UsersStats | AnimalsStats | HealthStatsN | ProductionStatsN;

const coalesce = <T,>(...vals: (T | undefined | null)[]) => vals.find(v => v !== undefined && v !== null) as T | undefined;
const toNumber = (v: any): number | undefined => {
  const n = Number(v);
  return Number.isFinite(n) ? n : undefined;
};

const normalizeBySex = (raw: any): { Hembra?: number; Macho?: number } | undefined => {
  const hembra = toNumber(coalesce(raw?.bySex?.female, raw?.by_sex?.hembras, raw?.hembras));
  const macho = toNumber(coalesce(raw?.bySex?.male, raw?.by_sex?.machos, raw?.machos));
  if (hembra === undefined && macho === undefined) return undefined;
  return { Hembra: hembra, Macho: macho };
};

const normalizeByStatus = (raw: any): Record<string, number> | undefined => {
  const map = raw?.byStatus || raw?.by_status || raw?.status_distribution || raw?.status;
  if (!map || typeof map !== 'object') return undefined;
  const out: Record<string, number> = {};
  for (const [k, v] of Object.entries(map)) {
    const n = toNumber(v);
    if (n !== undefined) out[k] = n;
  }
  return out;
};

function normalizeModelStats(model: 'users'|'animals'|'health'|'production', raw: any): NormalizedStats {
  switch (model) {
    case 'users':
      return { total_users: toNumber(coalesce(raw?.totalUsers, raw?.total_users, raw?.count)), status_distribution: normalizeByStatus(raw) };
    case 'animals':
      return { total_animals: toNumber(coalesce(raw?.totalAnimals, raw?.total_animals, raw?.count)), by_sex: normalizeBySex(raw), by_status: normalizeByStatus(raw), average_weight: toNumber(coalesce(raw?.avgWeight, raw?.average_weight)) };
    case 'health':
      return { summary: { total_treatments: toNumber(coalesce(raw?.totalTreatments, raw?.summary?.total_treatments)), active_treatments: toNumber(coalesce(raw?.activeTreatments, raw?.summary?.active_treatments)), total_vaccinations: toNumber(coalesce(raw?.totalVaccinations, raw?.summary?.total_vaccinations)), pending_vaccinations: toNumber(coalesce(raw?.pendingVaccinations, raw?.summary?.pending_vaccinations)) } };
    case 'production':
      return { summary: { total_controls: toNumber(coalesce(raw?.totalControls, raw?.summary?.total_controls)), total_fields: toNumber(coalesce(raw?.totalFields, raw?.summary?.total_fields)), field_utilization: toNumber(coalesce(raw?.fieldUtilization, raw?.summary?.field_utilization)), animals_per_field: toNumber(coalesce(raw?.animalsPerField, raw?.summary?.animals_per_field)), monthly_costs: toNumber(coalesce(raw?.monthlyCosts, raw?.summary?.monthly_costs)) } };
    default:
      return {} as any;
  }
}

interface UseModelStatsOptions {
  enabled?: boolean;
  [key: string]: any;
}

export function useModelStats<T=any>(model: string, options?: UseModelStatsOptions): StatsState<T> {
  const { enabled = true, ...params } = options || {};
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(enabled);
  const [error, setError] = useState<string | null>(null);
  const cancelTokenSourceRef = useRef<ReturnType<typeof axios.CancelToken.source> | null>(null);

  // Memoizar params para evitar recreación innecesaria
  const stableParams = useMemo(() => params, [params]);

  const fetchStats = useCallback(async () => {
    if (!enabled) {
      setLoading(false);
      return;
    }
    setLoading(true); setError(null);
    // Cancel any previous inflight request
    if (cancelTokenSourceRef.current) {
      try { cancelTokenSourceRef.current.cancel('Nueva consulta de estadísticas, se cancela la anterior'); } catch { /* noop */ }
    }
    cancelTokenSourceRef.current = axios.CancelToken.source();

    try {
      let endpoint: string;
      const slug = normalizeModel(model);

      // Redirigir modelos conocidos a los endpoints correctos
      switch (slug) {
        case 'users':
          endpoint = '/users/statistics';
          break;
        case 'animals':
          endpoint = '/analytics/animals/statistics';
          break;
        case 'health':
          endpoint = '/analytics/health/statistics';
          break;
        case 'production':
          endpoint = '/analytics/production/statistics';
          break;
        default:
          // Fallback genérico para debugging
          endpoint = '/analytics/dashboard';
          break;
      }

      const res = await apiFetch({ url: endpoint, method: 'GET', params: stableParams, cancelToken: cancelTokenSourceRef.current.token });
      const raw = unwrapApi(res);
      const normalized = normalizeModelStats(slug as any, raw);
      if (process.env.NODE_ENV !== 'production') {
        console.debug('[useModelStats]', { model: slug, keys: Object.keys(raw || {}), normalized });
      }
      setData(normalized as T);
    } catch (e:any) {
      if (axios.isCancel(e)) {
        // Cancelled request: do not set error or log noisy messages
        return;
      }
      setError(e?.message || 'Error cargando estadísticas');
    } finally {
      setLoading(false);
    }
  }, [model, stableParams, enabled]);

  // Debounced version of fetchStats
  const debouncedFetchStats = useMemo(() => debounce(fetchStats, 300), [fetchStats]);

  useEffect(() => {
    if (enabled) {
      debouncedFetchStats();
    } else {
      setLoading(false);
    }
    return () => {
      // Cancel any pending debounce timer and inflight request on unmount or dependency change
      (debouncedFetchStats as any).cancel?.();
      if (cancelTokenSourceRef.current) {
        try { cancelTokenSourceRef.current.cancel('Componente desmontado'); } catch { /* noop */ }
        cancelTokenSourceRef.current = null;
      }
    };
  }, [model, debouncedFetchStats, enabled]);

  return { data, loading, error, refresh: fetchStats };
}

export default useModelStats;

import { useState, useCallback, useRef, useEffect } from 'react';
import { semanticSearchService, SearchResult, UnifiedSearchResponse } from '../api/semanticSearch.service';

interface UseSemanticSearchOptions {
  debounceMs?: number;
  minQueryLength?: number;
}

export function useSemanticSearch(options: UseSemanticSearchOptions = {}) {
  const { debounceMs = 300, minQueryLength = 2 } = options;
  
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<UnifiedSearchResponse>({ animals: [], records: [] });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [hasSearched, setHasSearched] = useState(false);
  
  const debounceRef = useRef<NodeJS.Timeout | null>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  const search = useCallback(async (searchQuery: string) => {
    // Cancelar búsqueda anterior
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
    
    // Limpiar debounce anterior
    if (debounceRef.current) {
      clearTimeout(debounceRef.current);
    }
    
    // Validar query
    if (!searchQuery || searchQuery.length < minQueryLength) {
      setResults({ animals: [], records: [] });
      setHasSearched(false);
      return;
    }
    
    // Debounce
    debounceRef.current = setTimeout(async () => {
      setLoading(true);
      setError(null);
      
      try {
        const data = await semanticSearchService.search(searchQuery);
        setResults(data);
        setHasSearched(true);
      } catch (err) {
        setError('Error al realizar la búsqueda');
        setResults({ animals: [], records: [] });
      } finally {
        setLoading(false);
      }
    }, debounceMs);
  }, [debounceMs, minQueryLength]);

  // Actualizar búsqueda cuando cambia el query
  useEffect(() => {
    search(query);
    
    return () => {
      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
      }
    };
  }, [query, search]);

  const clear = useCallback(() => {
    setQuery('');
    setResults({ animals: [], records: [] });
    setHasSearched(false);
    setError(null);
  }, []);

  // Resultados combinados para mostrar
  const allResults: SearchResult[] = [
    ...results.animals,
    ...results.records,
  ].sort((a, b) => b.score - a.score);

  return {
    query,
    setQuery,
    results,
    allResults,
    animals: results.animals,
    records: results.records,
    loading,
    error,
    hasSearched,
    clear,
    resultCount: allResults.length,
  };
}

type Handler = (data: any) => void;

const getSSEPath = () => {
  if (typeof window === 'undefined') return '';
  // Intentar obtener baseURL del cliente centralizado
  try {
    const config = (window as any).__vl_api_config;
    const baseURL = config?.baseURL || '';
    if (baseURL.endsWith('/api/v1')) return `${baseURL}/sse/events`;
    if (baseURL === '/' || baseURL === '') return '/api/v1/sse/events';
    return `${baseURL}/api/v1/sse/events`;
  } catch {
    return '/api/v1/sse/events';
  }
};

const BASE_RETRY_DELAY_MS = 10000;
const MAX_RETRY_DELAY_MS = 300000;
const RATE_LIMIT_BACKOFF_MS = 20000;
const MAX_RATE_LIMIT_DELAY_MS = 600000;
const RAPID_FAILURE_THRESHOLD_MS = 5000;
const RAPID_FAILURE_COUNT_THRESHOLD = 5;

const handlers = new Set<Handler>();
let source: EventSource | null = null;
let retryTimer: number | null = null;
let retryAttempt = 0;
let isRateLimited = false;
let rateLimitExpiry = 0;
let isConnecting = false;
let closeTimer: number | null = null;
let lastConnectionAttemptAt = 0;
let rapidFailureCount = 0;
let rateLimitStrikeCount = 0;

const LIMIT_STORAGE_KEY = 'sse:limit_ex';
const FAIL_COUNT_KEY = 'sse:fail_count';
const STRIKE_COUNT_KEY = 'sse:strike_count';

const loadState = () => {
  if (typeof window === 'undefined') return;
  try {
    const storedExpiry = localStorage.getItem(LIMIT_STORAGE_KEY);
    if (storedExpiry) {
      const expiry = parseInt(storedExpiry, 10);
      if (expiry > Date.now()) {
        isRateLimited = true;
        rateLimitExpiry = expiry;
      } else {
        localStorage.removeItem(LIMIT_STORAGE_KEY);
      }
    }
    const storedCount = localStorage.getItem(FAIL_COUNT_KEY);
    if (storedCount) rapidFailureCount = parseInt(storedCount, 10);
    const storedStrikes = localStorage.getItem(STRIKE_COUNT_KEY);
    if (storedStrikes) rateLimitStrikeCount = parseInt(storedStrikes, 10);
  } catch { /* noop */ }
};

const saveState = () => {
  if (typeof window === 'undefined') return;
  try {
    if (isRateLimited && rateLimitExpiry > Date.now()) {
      localStorage.setItem(LIMIT_STORAGE_KEY, String(rateLimitExpiry));
    } else {
      localStorage.removeItem(LIMIT_STORAGE_KEY);
    }
    if (rapidFailureCount > 0) localStorage.setItem(FAIL_COUNT_KEY, String(rapidFailureCount));
    else localStorage.removeItem(FAIL_COUNT_KEY);
    if (rateLimitStrikeCount > 0) localStorage.setItem(STRIKE_COUNT_KEY, String(rateLimitStrikeCount));
    else localStorage.removeItem(STRIKE_COUNT_KEY);
  } catch { /* noop */ }
};

loadState();

const dispatchMessage = (raw: any) => {
  const payload = (() => {
    if (typeof raw !== 'string') return raw;
    try { return JSON.parse(raw); } catch { return raw; }
  })();
  handlers.forEach((handler) => {
    try { handler(payload); } catch { /* noop */ }
  });
};

const closeSource = () => {
  if (!source) return;
  try { source.close(); } catch { /* noop */ }
  source = null;
  isConnecting = false;
};

const calculateRetryDelay = (): number => {
  const exponentialDelay = Math.min(BASE_RETRY_DELAY_MS * Math.pow(2, retryAttempt), MAX_RETRY_DELAY_MS);
  return exponentialDelay + Math.floor(Math.random() * 1000);
};

const scheduleReconnect = () => {
  if (retryTimer || typeof window === 'undefined') return;
  if (isRateLimited && Date.now() < rateLimitExpiry) {
    const waitMs = rateLimitExpiry - Date.now();
    retryTimer = window.setTimeout(() => {
      retryTimer = null;
      isRateLimited = false;
      saveState();
      retryAttempt = 0;
      connectSSE();
    }, waitMs);
    return;
  }
  const delay = calculateRetryDelay();
  retryTimer = window.setTimeout(() => {
    retryTimer = null;
    retryAttempt++;
    connectSSE();
  }, delay);
};

let isEndpointInvalid = false;

const validateEndpoint = async () => {
  if (isEndpointInvalid) return;
  try {
    const ssePath = getSSEPath();
    const res = await fetch(ssePath, { method: 'HEAD', headers: { 'Accept': 'text/event-stream' } });
    if (res.status === 429) {
      isRateLimited = true;
      rateLimitStrikeCount++;
      const backoffMs = Math.min(RATE_LIMIT_BACKOFF_MS * Math.pow(2, rateLimitStrikeCount - 1), MAX_RATE_LIMIT_DELAY_MS);
      rateLimitExpiry = Date.now() + backoffMs;
      saveState();
      return;
    }
    const contentType = res.headers.get('content-type') || '';
    if (contentType.includes('text/html') || res.status === 404 || res.status === 500) {
      isEndpointInvalid = true;
      closeSource();
    }
  } catch { /* noop */ }
};

const handleError = () => {
  closeSource();
  if (rapidFailureCount > 0 && !isRateLimited) void validateEndpoint();
  scheduleReconnect();
};

const createEventSource = () => {
  if (typeof window === 'undefined' || isEndpointInvalid || isConnecting) return source;
  loadState();
  if (isRateLimited && Date.now() < rateLimitExpiry) {
    scheduleReconnect();
    return null;
  }
  isConnecting = true;
  const connectionStartedAt = Date.now();
  lastConnectionAttemptAt = connectionStartedAt;
  try {
    const ssePath = getSSEPath();
    const es = new EventSource(ssePath, { withCredentials: true } as any);
    source = es;
    es.onopen = () => {
      console.log('[SSE] Connection established to', ssePath);
      retryAttempt = 0;
      rapidFailureCount = 0;
      rateLimitStrikeCount = 0;
      isRateLimited = false;
      saveState();
      isConnecting = false;
    };
    es.onmessage = (event: MessageEvent) => dispatchMessage(event.data);
    es.onerror = () => {
      isConnecting = false;
      const timeSinceStart = Date.now() - connectionStartedAt;
      if (timeSinceStart < RAPID_FAILURE_THRESHOLD_MS) {
        rapidFailureCount++;
        saveState();
        if (rapidFailureCount >= RAPID_FAILURE_COUNT_THRESHOLD) {
          isRateLimited = true;
          rateLimitStrikeCount++;
          const backoffMs = Math.min(RATE_LIMIT_BACKOFF_MS * Math.pow(2, rateLimitStrikeCount - 1), MAX_RATE_LIMIT_DELAY_MS);
          rateLimitExpiry = Date.now() + backoffMs;
          rapidFailureCount = 0;
          saveState();
        }
      } else if (rapidFailureCount > 0) {
        rapidFailureCount = 0;
        saveState();
      }
      handleError();
    };
    return es;
  } catch (err) {
    isConnecting = false;
    console.error('[SSE] Failed to create EventSource:', err);
    scheduleReconnect();
    return null;
  }
};

if (typeof window !== 'undefined') {
  window.addEventListener('rate-limit-exceeded', ((e: CustomEvent) => {
    const detail = e.detail || {};
    if (detail.endpoint?.includes('events')) {
      (window as any).__lastSSERateLimitAt = Date.now();
      isRateLimited = true;
      const waitSeconds = typeof detail.waitSeconds === 'number' ? detail.waitSeconds : 60;
      rateLimitExpiry = Date.now() + waitSeconds * 1000;
      saveState();
      closeSource();
      if (retryTimer) { clearTimeout(retryTimer); retryTimer = null; }
      scheduleReconnect();
    }
  }) as EventListener);
}

export function connectSSE(): EventSource | null {
  if (source) return source;
  if (retryTimer) { clearTimeout(retryTimer); retryTimer = null; }
  return createEventSource();
}

export function closeSSE(immediate = false) {
  if (closeTimer) { clearTimeout(closeTimer); closeTimer = null; }
  if (retryTimer) { clearTimeout(retryTimer); retryTimer = null; }
  if (immediate) {
    closeSource();
    retryAttempt = 0;
  } else {
    closeTimer = window.setTimeout(() => {
      closeTimer = null;
      if (retryTimer) { clearTimeout(retryTimer); retryTimer = null; }
      closeSource();
      retryAttempt = 0;
    }, 2000);
  }
}

export function subscribeSSE(handler: Handler) {
  handlers.add(handler);
  connectSSE();
  return () => { handlers.delete(handler); };
}

export function getSSEStatus() {
  return {
    connected: source?.readyState === EventSource.OPEN,
    connecting: isConnecting || source?.readyState === EventSource.CONNECTING,
    rateLimited: isRateLimited,
    rateLimitExpiry,
    retryAttempt,
    rapidFailureCount,
  };
}

const sse = {
  subscribe: subscribeSSE,
  connect: connectSSE,
  close: closeSSE,
  getStatus: getSSEStatus,
};

export default sse;

