  { id: 'uppercase', label: 'Al menos una mayúscula', test: (value: string) => /[A-Z]/.test(value) },
  { id: 'number', label: 'Al menos un número', test: (value: string) => /\d/.test(value) },
];

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const PHONE_REGEX = /^[+]?[0-9\s-]{7,15}$/;

const RegisterUserPage: React.FC = () => {
  const navigate = useNavigate();
  const { showToast } = useToast();
  const [formData, setFormData] = useState<SignUpFormData>({
    name: '',
    email: '',
    phone: '',
    password: '',
    confirmPassword: '',
    identification_number: '',
    role: 'Aprendiz',
    address: '',
  });

  const [errors, setErrors] = useState<FormErrors>({});
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [success, setSuccess] = useState(false);
  const [successMessage, setSuccessMessage] = useState('');
  const [touched, setTouched] = useState<Partial<Record<keyof SignUpFormData, boolean>>>({});
  const [submitAttempted, setSubmitAttempted] = useState(false);

  const setFieldError = (fieldName: keyof FormErrors, message?: string) => {
    setErrors((prev) => ({ ...prev, [fieldName]: message }));
  };

  const mapBackendFieldToUI = (field: string): keyof FormErrors | undefined => {
    const m: Record<string, keyof FormErrors> = {
      fullname: 'name',
      name: 'name',
      email: 'email',
      phone: 'phone',
      identification: 'identification_number',
      identification_number: 'identification_number',
      address: 'address',
      password: 'password',
      confirm_password: 'confirmPassword',
      confirmPassword: 'confirmPassword',
      role: undefined as any,
    };
    return m[field];
  };

  const labelForField = (field: string): string => {
    const map: Record<string, string> = {
      email: 'correo',
      fullname: 'nombre',
      name: 'nombre',
      phone: 'teléfono',
      identification: 'número de identificación',
      identification_number: 'número de identificación',
      address: 'dirección',
    };
    return map[field] || field;
  };

  const mapBackendValidationErrors = (details: any) => {
    if (!details || typeof details !== 'object') return;
    const validation = (details as any).validation_errors || (details as any).errors || details;
    if (!validation || typeof validation !== 'object') return;

    const map: Record<string, keyof FormErrors> = {
      fullname: 'name',
      name: 'name',
      email: 'email',
      phone: 'phone',
      identification: 'identification_number',
      identification_number: 'identification_number',
      password: 'password',
      confirmPassword: 'confirmPassword',
      address: 'address',
    };

    const newFieldErrors: FormErrors = {};
    Object.entries(validation).forEach(([key, val]) => {
      const uiKey = map[key];
      if (!uiKey) return;
      const messages = Array.isArray(val) ? val : [val];
      const msg = messages
        .map((e: any) => (typeof e === 'string' ? e : e?.message || e?.detail || e))
        .filter(Boolean)
        .join(' • ');
      if (msg) newFieldErrors[uiKey] = msg;
    });

    if (Object.keys(newFieldErrors).length > 0) {
      setErrors((prev) => ({ ...prev, ...newFieldErrors }));
    }
  };

  const buildValidationErrors = (values: SignUpFormData): FormErrors => {
    const e: FormErrors = {};
    if (!values.name.trim()) e.name = 'El nombre completo es requerido';
    if (!values.email.trim()) {
      e.email = 'El correo electrónico es requerido';
    } else if (!EMAIL_REGEX.test(values.email)) {
      e.email = 'Ingrese un correo válido';
    }
    if (!values.phone.trim()) {
      e.phone = 'El teléfono es requerido';
    } else if (!PHONE_REGEX.test(values.phone)) {
      e.phone = 'Ingrese un teléfono válido';
    }
    if (!values.identification_number.trim()) {
      e.identification_number = 'El número de identificación es requerido';
    }
    if (!values.password) {
      e.password = 'La contraseña es requerida';
    } else {
      if (values.password.length < 8) e.password = 'Mínimo 8 caracteres';
      if (!/[A-Z]/.test(values.password)) e.password = 'Debe contener al menos una mayúscula';
      if (!/\d/.test(values.password)) e.password = 'Debe contener al menos un número';
    }
    if (values.password !== values.confirmPassword) {
      e.confirmPassword = 'Las contraseñas no coinciden';
    }
    return e;
  };

  const validationSnapshot = useMemo(() => buildValidationErrors(formData), [formData]);
  const isFormValid = useMemo(() => Object.keys(validationSnapshot).length === 0, [validationSnapshot]);

  const getFieldError = (field: keyof FormErrors) => {
    const existing = errors[field];
    if (existing) return existing;
    if (!hasInteracted) return undefined;
    if (!submitAttempted && !touched[field as keyof SignUpFormData]) return undefined;
    return validationSnapshot[field];
  };

  const [hasInteracted, setHasInteracted] = useState(false);

  const blockingReasons = useMemo(() => {
    if (isFormValid) return [];

    const FIELD_LABELS: Partial<Record<keyof FormErrors, string>> = {
      name: 'Nombre completo',
      email: 'Correo electrónico',
      phone: 'Teléfono',
      identification_number: 'Número de identificación',
      password: 'Contraseña',
      confirmPassword: 'Confirmar contraseña',
    };

    return (Object.entries(validationSnapshot) as Array<[keyof FormErrors, string | undefined]>)
      .filter(([, message]) => Boolean(message))
      .map(([field, message]) => {
        const label = FIELD_LABELS[field] || String(field);
        return `${label}: ${message}`;
      })
      .slice(0, 4);
  }, [isFormValid, validationSnapshot]);

  const validateForm = (): boolean => {
    const newErrors = buildValidationErrors(formData);
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    setTouched((prev) =>
      prev[name as keyof SignUpFormData] ? prev : { ...prev, [name]: true }
    );

    if (errors[name as keyof FormErrors] || errors.general) {
      setErrors(prev => {
        const next = { ...prev, [name]: undefined } as FormErrors;
        if (prev.general) next.general = undefined;
        return next;
      });
    }
    if (!hasInteracted) setHasInteracted(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrors({});
    setSuccess(false);
    setSuccessMessage('');
    setSubmitAttempted(true);

    if (!validateForm()) {
      return;
    }

    setLoading(true);
    let userData: any = null;

    try {
      const cleanedPhone = formData.phone.replace(/[\s-]+/g, '').trim();
      userData = {
        fullname: formData.name.trim(),
        email: formData.email.trim().toLowerCase(),
        phone: cleanedPhone,
        password: formData.password,
        password_confirmation: formData.confirmPassword,
        identification: parseInt(formData.identification_number.trim(), 10),
        role: formData.role as "Administrador" | "Instructor" | "Aprendiz",
        address: formData.address?.trim() || undefined,
      };

      if (import.meta.env.DEV) {
        console.log('[RegisterUser] Sending user data:', {
          ...userData,
          password: '***',
          password_confirmation: '***'
        });
      }

      const created = (await usersService.createPublicUser(userData)) as any;
      const message = created?.message || created?.detail || 'Cuenta creada exitosamente. Por favor inicia sesión.';

      setSuccessMessage(message);
      setSuccess(true);

      setTimeout(() => {
        navigate('/login', {
          state: {
            message,
            email: formData.email
          }
        });
      }, 1800);

    } catch (error: any) {
      console.error('Error registering user:', error);

      const attemptAuthenticatedCreate = async () => {
        try {
          const profile = await getUserProfile();
          if (!profile?.user) return { ok: false as const };
        } catch {
          return { ok: false as const };
        }

        try {
          const created = (await usersService.createUser(userData as any)) as any;
          return { ok: true as const, created };
        } catch (authError: any) {
          return { ok: false as const, error: authError };
        }
      };

      const initialStatus = error?.response?.status ?? error?.status;
      let effectiveError: any = error;

      if (initialStatus === 401 || initialStatus === 403) {
        const fallback = await attemptAuthenticatedCreate();
        if (fallback.ok) {
          setSuccessMessage('Usuario creado exitosamente con sesión autenticada.');
          setSuccess(true);
          setTimeout(() => navigate('/login'), 1500);
          setLoading(false);
          return;
        }
        if (fallback.error) {
          effectiveError = fallback.error;
        }
      }

      const status = effectiveError?.response?.status ?? effectiveError?.status;
      const errorData = effectiveError?.response?.data ?? effectiveError?.data;

      if (status === 400) {
        const details = errorData?.details ?? errorData?.validation_errors ?? errorData?.errors ?? errorData;
        mapBackendValidationErrors({ validation_errors: details, errors: details });
        const generalMsg = errorData?.message || errorData?.error;
        if (generalMsg) {
          setFieldError('general', generalMsg);
          showToast(generalMsg, 'error');
        }
      } else if (status === 409) {
        const msg = errorData?.message || errorData?.detail || 'El usuario ya existe (email o identificación duplicada).';
        setFieldError('general', msg);
        showToast(msg, 'error');
      } else if (status === 422) {
        mapBackendValidationErrors(errorData);
        const msg = errorData?.message || errorData?.error || 'Datos inválidos. Verifique los campos.';
        setFieldError('general', msg);
        showToast(msg, 'error');
      } else {
        const fallbackMsg = effectiveError?.message || 'Error de conexión. Intente nuevamente.';
        setFieldError('general', fallbackMsg);
        showToast(fallbackMsg, 'error');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-green-50 via-emerald-50 to-teal-50 flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        <div className="text-center mb-6">
          <div className="inline-flex items-center justify-center w-14 h-14 bg-gradient-to-br from-green-500 to-emerald-600 rounded-2xl shadow-lg mb-4">
            <UserPlus className="h-7 w-7 text-white" />
          </div>
          <h1 className="text-2xl font-bold text-gray-900">Crear Cuenta</h1>
          <p className="text-gray-600 text-sm mt-1">
            Regístrate para unirte a una finca existente
          </p>
        </div>

        <Card className="shadow-xl border-0 bg-white/80 backdrop-blur-sm">
          <CardHeader className="pb-2">
            <CardTitle className="text-lg text-center">Información Personal</CardTitle>
          </CardHeader>
          <CardContent>
            {success ? (
              <div className="text-center py-8">
                <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4">
                  <CircleCheck className="h-8 w-8 text-green-600" />
                </div>
                <h3 className="text-lg font-semibold text-gray-900 mb-2">¡Registro Exitoso!</h3>
                <p className="text-gray-600 text-sm">{successMessage}</p>
                <p className="text-gray-500 text-xs mt-4">Redirigiendo al login...</p>
              </div>
            ) : (
              <form onSubmit={handleSubmit} className="space-y-4">
                {errors.general && (
                  <Alert variant="destructive" className="text-sm">
                    <AlertDescription>{errors.general}</AlertDescription>
                  </Alert>
                )}

                <div className="space-y-2">
                  <Label htmlFor="name" className="text-sm font-medium flex items-center gap-2">
                    <User className="h-4 w-4 text-gray-400" />
                    Nombre Completo
                  </Label>
                  <Input
                    id="name"
                    name="name"
                    type="text"
                    placeholder="Ej: Juan Pérez"
                    value={formData.name}
                    onChange={handleInputChange}
                    disabled={loading}
                    className={getFieldError('name') ? 'border-red-500' : ''}
                  />
                  {getFieldError('name') && (
                    <p className="text-red-500 text-xs">{getFieldError('name')}</p>
                  )}
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-2">
                    <Label htmlFor="email" className="text-sm font-medium flex items-center gap-2">
                      <Mail className="h-4 w-4 text-gray-400" />
                      Correo
                    </Label>
                    <Input
                      id="email"
                      name="email"
                      type="email"
                      placeholder="tu@email.com"
                      value={formData.email}
                      onChange={handleInputChange}
                      disabled={loading}
                      className={getFieldError('email') ? 'border-red-500' : ''}
                    />
                    {getFieldError('email') && (
                      <p className="text-red-500 text-xs">{getFieldError('email')}</p>
                    )}
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="phone" className="text-sm font-medium flex items-center gap-2">
                      <Phone className="h-4 w-4 text-gray-400" />
                      Teléfono
                    </Label>
                    <Input
                      id="phone"
                      name="phone"
                      type="tel"
                      placeholder="3001234567"
                      value={formData.phone}
                      onChange={handleInputChange}
                      disabled={loading}
                      className={getFieldError('phone') ? 'border-red-500' : ''}
                    />
                    {getFieldError('phone') && (
                      <p className="text-red-500 text-xs">{getFieldError('phone')}</p>
                    )}
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="identification_number" className="text-sm font-medium">
                    Número de Identificación
                  </Label>
                  <Input
                    id="identification_number"
                    name="identification_number"
                    type="text"
                    placeholder="Ej: 1234567890"
                    value={formData.identification_number}
                    onChange={handleInputChange}
                    disabled={loading}
                    className={getFieldError('identification_number') ? 'border-red-500' : ''}
                  />
                  {getFieldError('identification_number') && (
                    <p className="text-red-500 text-xs">{getFieldError('identification_number')}</p>
                  )}
                </div>

                <div className="space-y-2">
                  <Label htmlFor="role" className="text-sm font-medium">Rol Solicitado</Label>
                  <select
                    id="role"
                    name="role"
                    value={formData.role}
                    onChange={handleInputChange}
                    disabled={loading}
                    className="w-full px-3 py-2 border rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-green-500"
                  >
                    <option value="Aprendiz">Aprendiz (SENA)</option>
                    <option value="Instructor">Instructor (SENA)</option>
                    <option value="Operario">Operario</option>
                    <option value="Capataz">Capataz</option>
                    <option value="Veterinario">Veterinario</option>
                  </select>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="password" className="text-sm font-medium flex items-center gap-2">
                    <Lock className="h-4 w-4 text-gray-400" />
                    Contraseña
                  </Label>
                  <div className="relative">
                    <Input
                      id="password"
                      name="password"
                      type={showPassword ? 'text' : 'password'}
                      placeholder="Mínimo 8 caracteres"
                      value={formData.password}
                      onChange={handleInputChange}
                      disabled={loading}
                      className={getFieldError('password') ? 'border-red-500 pr-10' : 'pr-10'}
                    />
                    <button
                      type="button"
                      onClick={() => setShowPassword(!showPassword)}
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                    >
                      {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                    </button>
                  </div>
                  {getFieldError('password') && (
                    <p className="text-red-500 text-xs">{getFieldError('password')}</p>
                  )}
                </div>

                <div className="space-y-2">
                  <Label htmlFor="confirmPassword" className="text-sm font-medium">Confirmar Contraseña</Label>
                  <div className="relative">
                    <Input
                      id="confirmPassword"
                      name="confirmPassword"
                      type={showConfirmPassword ? 'text' : 'password'}
                      placeholder="Repite la contraseña"
                      value={formData.confirmPassword}
                      onChange={handleInputChange}
                      disabled={loading}
                      className={getFieldError('confirmPassword') ? 'border-red-500 pr-10' : 'pr-10'}
                    />
                    <button
                      type="button"
                      onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                    >
                      {showConfirmPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                    </button>
                  </div>
                  {getFieldError('confirmPassword') && (
                    <p className="text-red-500 text-xs">{getFieldError('confirmPassword')}</p>
                  )}
                </div>

                <Button
                  type="submit"
                  disabled={loading || !isFormValid}
                  className="w-full bg-gradient-to-r from-green-600 to-emerald-600 hover:from-green-700 hover:to-emerald-700"
                >
                  {loading ? (
                    <>
                      <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                      Creando cuenta...
                    </>
                  ) : (
                    <>
                      <UserPlus className="mr-2 h-4 w-4" />
                      Crear Cuenta
                    </>
                  )}
                </Button>
              </form>
            )}

            <div className="mt-6 pt-4 border-t border-gray-100 space-y-3">
              <p className="text-center text-sm text-gray-600">
                ¿Ya tienes una cuenta?{' '}
                <Link to="/login" className="text-green-600 hover:text-green-700 font-medium">
                  Inicia sesión
                </Link>
              </p>
              <p className="text-center text-xs text-gray-500">
                ¿Eres propietario y quieres crear tu finca?{' '}
                <Link to="/register/finca" className="text-green-600 hover:text-green-700 font-medium">
                  <Building2 className="inline h-3 w-3 mr-1" />
                  Registrar finca
                </Link>
              </p>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
};

export default RegisterUserPage;

import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/shared/ui/card';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Label } from '@/shared/ui/label';
import { Badge } from '@/shared/ui/badge';
import { 
  Building2, 
  User, 
  MapPin, 
  ChevronRight, 
  ChevronLeft,
  Check,
  Loader2,
  CircleAlert
} from 'lucide-react';
import { useToast } from '@/app/providers/ToastContext';
import { apiClient } from '@/shared/api/client';

interface FormData {
  finca: {
    name: string;
    type: 'Educativa' | 'Tradicional';
    department: string;
    municipality: string;
    nit: string;
  };
  owner: {
    identification: string;
    fullname: string;
    email: string;
    phone: string;
    password: string;
    confirmPassword: string;
  };
}

export default function RegisterPage() {
  const navigate = useNavigate();
  const { showToast } = useToast();
  const [step, setStep] = useState(1);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const [formData, setFormData] = useState<FormData>({
    finca: {
      name: '',
      type: 'Tradicional',
      department: '',
      municipality: '',
      nit: '',
    },
    owner: {
      identification: '',
      fullname: '',
      email: '',
      phone: '',
      password: '',
      confirmPassword: '',
    },
  });

  const validateStep = (currentStep: number): boolean => {
    const newErrors: Record<string, string> = {};

    if (currentStep === 1) {
      if (!formData.finca.name.trim()) {
        newErrors['finca.name'] = 'El nombre de la finca es requerido';
      }
      if (!formData.finca.type) {
        newErrors['finca.type'] = 'Seleccione el tipo de finca';
      }
    }

    if (currentStep === 2) {
      if (!formData.owner.identification.trim()) {
        newErrors['owner.identification'] = 'La identificación es requerida';
      }
      if (!formData.owner.fullname.trim()) {
        newErrors['owner.fullname'] = 'El nombre completo es requerido';
      }
      if (!formData.owner.email.trim()) {
        newErrors['owner.email'] = 'El correo electrónico es requerido';
      } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.owner.email)) {
        newErrors['owner.email'] = 'Ingrese un correo válido';
      }
      if (!formData.owner.phone.trim()) {
        newErrors['owner.phone'] = 'El teléfono es requerido';
      }
    }

    if (currentStep === 3) {
      if (!formData.owner.password) {
        newErrors['owner.password'] = 'La contraseña es requerida';
      } else if (formData.owner.password.length < 8) {
        newErrors['owner.password'] = 'La contraseña debe tener al menos 8 caracteres';
      }
      if (formData.owner.password !== formData.owner.confirmPassword) {
        newErrors['owner.confirmPassword'] = 'Las contraseñas no coinciden';
      }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleNext = () => {
    if (validateStep(step)) {
      setStep(step + 1);
    }
  };

  const handleBack = () => {
    setStep(step - 1);
  };

  const handleSubmit = async () => {
    if (!validateStep(step)) return;

    setIsSubmitting(true);
    try {
      const payload = {
        finca: {
          name: formData.finca.name,
          type: formData.finca.type,
          department: formData.finca.department || undefined,
          municipality: formData.finca.municipality || undefined,
          nit: formData.finca.nit || undefined,
        },
        owner: {
          identification: parseInt(formData.owner.identification.replace(/\D/g, '')),
          fullname: formData.owner.fullname,
          email: formData.owner.email,
          phone: formData.owner.phone,
          password: formData.owner.password,
        },
      };

      const response = await apiClient.post('/api/v1/public/register', payload);

      if (response.data?.success) {
        showToast('¡Finca registrada exitosamente! Redirigiendo...', 'success');
        
        // Guardar tokens si vienen en la respuesta
        const { access_token, refresh_token } = response.data.data || {};
        if (access_token) {
          localStorage.setItem('access_token', access_token);
          if (refresh_token) {
            localStorage.setItem('refresh_token', refresh_token);
          }
        }

        // Redirigir al dashboard después de 2 segundos
        setTimeout(() => {
          navigate('/dashboard');
        }, 2000);
      } else {
        showToast(response.data?.message || 'Error al registrar la finca', 'error');
      }
    } catch (error: any) {
      const errorMessage = error.response?.data?.message || 'Error al registrar la finca';
      const errorDetails = error.response?.data?.details;
      
      if (errorDetails && typeof errorDetails === 'object') {
        const fieldErrors: Record<string, string> = {};
        Object.entries(errorDetails).forEach(([key, value]) => {
          fieldErrors[key] = String(value);
        });
        setErrors(fieldErrors);
      }
      
      showToast(errorMessage, 'error');
    } finally {
      setIsSubmitting(false);
    }
  };

  const updateField = (section: 'finca' | 'owner', field: string, value: string) => {
    setFormData(prev => ({
      ...prev,
      [section]: {
        ...prev[section],
        [field]: value,
      },
    }));
    // Limpiar error del campo
    if (errors[`${section}.${field}`]) {
      setErrors(prev => {
        const newErrors = { ...prev };
        delete newErrors[`${section}.${field}`];
        return newErrors;
      });
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-green-50 to-blue-50 flex items-center justify-center p-4">
      <div className="w-full max-w-2xl">
        {/* Logo y título */}
