                    placeholder="Ej: usuario@email.com"
                    value={formData.owner.email}
                    onChange={(e) => updateField('owner', 'email', e.target.value)}
                    className={errors['owner.email'] ? 'border-red-500' : ''}
                  />
                  {errors['owner.email'] && (
                    <p className="text-sm text-red-500 mt-1">{errors['owner.email']}</p>
                  )}
                </div>

                <div>
                  <Label htmlFor="owner.phone">Teléfono *</Label>
                  <Input
                    id="owner.phone"
                    placeholder="Ej: 3001234567"
                    value={formData.owner.phone}
                    onChange={(e) => updateField('owner', 'phone', e.target.value)}
                    className={errors['owner.phone'] ? 'border-red-500' : ''}
                  />
                  {errors['owner.phone'] && (
                    <p className="text-sm text-red-500 mt-1">{errors['owner.phone']}</p>
