));

ContactItem.displayName = 'ContactItem';

// Componente memoizado para mensaje
const MessageItem = memo(({ 
  message, 
  isOwn 
}: { 
  message: ChatMessage; 
  isOwn: boolean; 
}) => (
  <div className={`flex ${isOwn ? 'justify-end' : 'justify-start'} mb-4`}>
