            </button>
            <h1 className="text-lg font-semibold">Mensajes</h1>
          </div>
          {/* Búsqueda de contactos */}
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-text-secondary" />
            <input
