import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  ArrowLeft, 
  Send, 
  MessageCircle, 
  Wifi, 
  WifiOff, 
  Search, 
  X, 
  Smile, 
  Paperclip, 
  FileImage, 
  Download,
  MoreVertical,
  Check,
  CheckCheck,
  User,
  ShieldCheck,
  Zap
} from 'lucide-react';
import { useAuth } from '@/features/auth/model/useAuth';
import { chatService, type ChatMessage, type ChatContact } from '@/features/chat/api/chat.service';
import { useRealtimeNotifications } from '@/shared/hooks/useRealtimeNotifications';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Badge } from '@/shared/ui/badge';
import { ScrollArea } from '@/shared/ui/scroll-area';
import { cn } from '@/shared/lib/utils';
import { motion, AnimatePresence } from 'framer-motion';
import { formatDistanceToNow } from 'date-fns';
import { es } from 'date-fns/locale';

export default function ChatPage() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Estados
  const [contacts, setContacts] = useState<ChatContact[]>([]);
  const [selectedContact, setSelectedContact] = useState<ChatContact | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [sending, setSending] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchInChatQuery, setSearchInChatQuery] = useState('');
  const [showSearchInChat, setShowSearchInChat] = useState(false);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);

  // Emojis comunes
  const commonEmojis = ['😀', '😂', '😍', '🤔', '👍', '👎', '❤️', '🎉', '🔥', '✅', '⚠️', '❓', '👋', '🙏', '👏', '💪'];

  // Conexión en tiempo real
  const { connected: isOnline } = useRealtimeNotifications({
    onEvent: (eventType, data) => {
      if (eventType === 'chat_message') {
        const msg = data.data as ChatMessage;
        // Si el mensaje es para la conversación actual, lo agregamos
        if (selectedContact && (msg.sender_id === selectedContact.id || msg.recipient_id === selectedContact.id)) {
          setMessages(prev => {
            // Evitar duplicados
            if (prev.some(m => m.id === msg.id)) return prev;
            return [...prev, msg];
          });
        }
      } else if (eventType === 'chat_message_sent') {
         const msg = data.data as ChatMessage;
         if (selectedContact && (msg.recipient_id === selectedContact.id)) {
            setMessages(prev => {
              if (prev.some(m => m.id === msg.id)) return prev;
              return [...prev, msg];
            });
         }
      }
    }
  });

  // Auto-scroll al final
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    if (messages.length > 0) {
      scrollToBottom();
    }
  }, [messages]);

  // Cargar contactos
  useEffect(() => {
    const loadContacts = async () => {
      setLoading(true);
      try {
        const data = await chatService.getContacts();
        setContacts(data);
      } catch (error) {
        console.error('Error cargando contactos:', error);
      } finally {
        setLoading(false);
      }
    };
    loadContacts();
  }, []);

  // Cargar historial
  useEffect(() => {
    if (!selectedContact) return;
    const loadHistory = async () => {
      try {
        const data = await chatService.getHistory(selectedContact.id);
        // El API devuelve historial en orden desc (más reciente primero), invertimos para el chat
        setMessages([...data].reverse());
      } catch (error) {
        console.error('Error cargando historial:', error);
      }
    };
    loadHistory();
  }, [selectedContact]);

  // Filtrado de mensajes dentro del chat
  const filteredMessages = useMemo(() => {
    if (!searchInChatQuery.trim()) return messages;
    return messages.filter(m => 
      m.message.toLowerCase().includes(searchInChatQuery.toLowerCase())
    );
  }, [messages, searchInChatQuery]);

  // Filtrado de contactos
  const filteredContacts = useMemo(() => {
    if (!Array.isArray(contacts)) return [];
    return contacts.filter(c => 
      c.fullname.toLowerCase().includes(searchQuery.toLowerCase()) ||
      c.role.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [contacts, searchQuery]);

  const handleSendMessage = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if ((!newMessage.trim() && !selectedFile) || !selectedContact || sending) return;

    setSending(true);
    try {
      let attachment = undefined;
      if (selectedFile) {
        attachment = await chatService.uploadFile(selectedFile);
      }

      const sentMsg = await chatService.sendMessage(
        selectedContact.id,
        newMessage.trim(),
        attachment
      );

      // Agregamos localmente si no llega por SSE (aunque debería llegar)
      setMessages(prev => {
        if (prev.some(m => m.id === sentMsg.id)) return prev;
        return [...prev, sentMsg];
      });

      setNewMessage('');
      setSelectedFile(null);
    } catch (error) {
      console.error('Error enviando mensaje:', error);
    } finally {
      setSending(false);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) setSelectedFile(file);
  };

  return (
    <div className="flex h-[calc(100vh-64px)] overflow-hidden bg-background/50 backdrop-blur-xl">
      {/* ── Panel Izquierdo: Contactos ── */}
      <div className={cn(
        "w-full md:w-[380px] flex flex-col border-r border-border/40 bg-card/30 backdrop-blur-md transition-all duration-500",
        selectedContact ? "hidden md:flex" : "flex"
      )}>
        <div className="p-6 border-b border-border/30 bg-muted/20">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-3">
              <Button 
                variant="ghost" 
                size="icon" 
                onClick={() => navigate('/dashboard')}
                className="h-9 w-9 rounded-xl hover:bg-primary/10"
              >
                <ArrowLeft className="h-5 w-5" />
              </Button>
              <h1 className="text-xl font-black uppercase tracking-tighter text-foreground">Mensajes</h1>
            </div>
            <Badge variant={isOnline ? "success" : "destructive"} className="px-2 py-0.5 animate-in fade-in zoom-in duration-500">
              {isOnline ? <Wifi className="h-3 w-3 mr-1" /> : <WifiOff className="h-3 w-3 mr-1" />}
              <span className="text-[10px] font-black uppercase tracking-widest">{isOnline ? 'Online' : 'Offline'}</span>
            </Badge>
          </div>

          <div className="relative group">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground group-focus-within:text-primary transition-colors" />
            <Input 
              placeholder="Buscar contactos..."
              value={searchQuery}
