  pending: number;
}

const emptyCounts: RuralCounts = {
  crops: 0,
  water: 0,
  risks: 0,
  market: 0,
  assistance: 0,
  learning: 0,
  pending: 0,
};

const quickActions: Array<{
  mode: QuickMode;
  title: string;
  help: string;
  icon: React.ReactNode;
  accent: string;
}> = [
  {
    mode: 'crop',
    title: 'Registrar cultivo',
    help: 'Siembra, lote o novedad del cultivo.',
    icon: <Sprout className="h-9 w-9" />,
    accent: 'bg-emerald-600',
  },
  {
    mode: 'water',
    title: 'Reportar agua',
    help: 'Fuente, lluvia, nivel o calidad.',
    icon: <Droplets className="h-9 w-9" />,
    accent: 'bg-cyan-700',
  },
  {
    mode: 'market',
    title: 'Publicar producto',
    help: 'Venta, compra o trueque comunitario.',
    icon: <PackageOpen className="h-9 w-9" />,
    accent: 'bg-amber-600',
  },
  {
    mode: 'assistance',
    title: 'Pedir asistencia',
