AlertItem.displayName = 'AlertItem';

// Definición de tipos
interface User {
  id: number;
  username: string;
  role: string;
  email?: string;
  isActive: boolean;
  lastLogin?: string;
  createdAt?: string;
  updatedAt?: string;
}

interface SystemStats {
  totalUsers: number;
  activeUsers: number;
  totalAnimals: number;
  activeTreatments: number;
  pendingTasks: number;
  systemAlerts: number;
}

interface SystemAlert {
  id: string;
  type: 'health' | 'vaccination' | 'growth' | 'productivity' | 'system' | 'info' | 'warning' | 'error' | 'success' | string;
  title: string;
  message: string;
  created_at: string;
  color?: 'red' | 'yellow' | 'green' | 'blue' | string;
  icon?: string; // emoji o nombre de icono
  priority?: 'low' | 'medium' | 'high' | 'critical';
  animal_id?: number;
  animal_record?: string;
  action_required?: string;
  isRead?: boolean;
}

const AdminDashboard: React.FC = () => {
  const t = useT();
  const { user } = useAuth();
  const { hasPermission } = usePermissions();
  const navigate = useNavigate();
  const { showToast } = useToast();

  // Estado local - declarar PRIMERO antes de usar
  const [users, setUsers] = useState<User[]>([]);
  const [, setSystemStats] = useState<SystemStats>({
    totalUsers: 0,
    activeUsers: 0,
    totalAnimals: 0,
    activeTreatments: 0,
    pendingTasks: 0,
    systemAlerts: 0,
  });
  const [loading, setLoading] = useState<boolean>(false);
  const [activeTab, setActiveTab] = useState('overview');
  const [isInitialLoad, setIsInitialLoad] = useState(true);

  // Guardas para evitar llamadas duplicadas/in-flight y doble invocación en StrictMode
  const initialFetchDoneRef = useRef(false)
  const isFetchingUsersRef = useRef(false)
  // Control de reintento único para /users
  const hasRetriedUsersRef = useRef(false)
  const usersRetryTimeoutRef = useRef<number | null>(null)

  // ===== Permisos evaluados como booleanos para estabilizar dependencias =====
  const canReadDashboard = hasPermission('dashboard:read')
  const canReadUsers = hasPermission('user:read')
  const canReadSystem = hasPermission('system:read')

  // OPTIMIZACIÓN: Usar SOLO useCompleteDashboardStats que trae TODAS las métricas en una sola llamada
  // Esto elimina 3 llamadas HTTP redundantes (dashboard, health, production)
  const { stats: completeStats, loading: completeLoading, error: completeError, refetch: refetchComplete, lastUpdated: _lastUpdated } = useCompleteDashboardStats(true);
  const kpiResumen = completeStats?.kpi_resumen;
  const rawKpiCards: KpiCardSummary[] = useMemo(
    () => kpiResumen?.cards ?? [],
    [kpiResumen]
  );
  const kpiCards = useMemo<KpiCardSummary[]>(() => {
    if (!rawKpiCards.length) return [];
    const indexOfId = (id: string) => KPI_ORDER.indexOf(id);
    return [...rawKpiCards].sort((a, b) => {
      const ai = indexOfId(a.id);
      const bi = indexOfId(b.id);
      if (ai === -1 && bi === -1) return a.id.localeCompare(b.id);
      if (ai === -1) return 1;
      if (bi === -1) return -1;
      return ai - bi;
    });
  }, [rawKpiCards]);

  // Helper: mapear color devuelto por backend a clases Tailwind
  const colorToClasses = (color?: string) => {
    switch (color) {
      case 'red':
        return 'border-red-200 bg-red-50';
      case 'orange':
      case 'yellow':
        return 'border-yellow-200 bg-yellow-50';
      case 'green':
        return 'border-green-200 bg-green-50';
      case 'blue':
        return 'border-blue-200 bg-blue-50';
      default:
        return 'border-blue-200 bg-blue-50';
    }
  };

  // Helper: icono según backend o fallback por tipo
  const renderAlertIcon = (alert: SystemAlert) => {
    if (alert.icon) {
      return <span className="text-xl mt-0.5">{alert.icon}</span>;
    }
    if (alert.type === 'vaccination') return <AlertTriangle className="h-5 w-5 text-yellow-500 mt-0.5" />;
    if (alert.type === 'health') return <AlertTriangle className="h-5 w-5 text-red-500 mt-0.5" />;
    if (alert.type === 'growth' || alert.type === 'productivity') return <CircleCheck className="h-5 w-5 text-green-500 mt-0.5" />;
    return <div className="h-5 w-5 rounded-full bg-blue-500 mt-0.5" />;
  };
  // Obtener usuarios del sistema
  const fetchUsers = useCallback(async () => {
    if (!canReadUsers) return
    if (isFetchingUsersRef.current) return
    isFetchingUsersRef.current = true
    setLoading(true)
    try {
      // Optimización: traer solo usuarios recientes y datos mínimos para el panel
      const res = await apiFetch({
        url: '/users',
        method: 'GET',
        params: {
          limit: 20,
          sort: 'createdAt',
          dir: 'desc',
        }
      } as any)
      const data: User[] = unwrapApi<User[]>(res)
      setUsers(data)
      // Nota: los conteos globales de usuarios provienen de useDashboardCounts.
      // Aquí solo mantenemos la lista reciente para la sección "Usuarios recientes".
    } catch (error) {
      console.error('Error fetching users:', error)
      showToast(t('dashboard.errors.fetchUsers'), 'error')
      // Reintento único con backoff si el backend responde 429 (rate limit)
      if (isAxiosError(error) && error.response?.status === 429 && !hasRetriedUsersRef.current) {
        const headers = error.response?.headers ?? {}
        const retryAfterHeader = (headers['retry-after'] as string | undefined) ?? (headers['Retry-After'] as string | undefined)
        const rateLimitReset = (headers['ratelimit-reset'] as string | undefined) ?? (headers['RateLimit-Reset'] as string | undefined)
        let delayMs = 30000 // fallback 30s
        const parseNum = (val?: string) => {
          if (!val) return undefined
          const n = parseInt(Array.isArray(val) ? (val as any)[0] : (val as any), 10)
          return Number.isNaN(n) ? undefined : n
        }
        const retryAfterSec = parseNum(retryAfterHeader)
        if (retryAfterSec !== undefined) {
          delayMs = Math.max(retryAfterSec * 1000, 5000)
        } else {
          const resetSec = parseNum(rateLimitReset)
          if (resetSec !== undefined) {
            const nowSec = Math.floor(Date.now() / 1000)
            delayMs = Math.max((resetSec - nowSec) * 1000, 5000)
          }
        }
        hasRetriedUsersRef.current = true
        showToast(`Límite alcanzado (429). Reintentando en ${Math.round(delayMs / 1000)}s…`, 'warning')
        usersRetryTimeoutRef.current = window.setTimeout(() => {
          fetchUsers()
        }, delayMs)
      }
    } finally {
      setLoading(false)
      isFetchingUsersRef.current = false
    }
  }, [canReadUsers, t, showToast])

  // Cargar datos iniciales (optimizado: llamadas paralelas con prioridad)
  useEffect(() => {
    if (!initialFetchDoneRef.current) {
      initialFetchDoneRef.current = true
      // OPTIMIZACIÓN: Ejecutar llamadas en paralelo para reducir tiempo total
      // Los hooks de React Query (useCompleteDashboardStats, useDashboardCounts) ya se ejecutan automáticamente
      // Solo llamar manualmente a los que no usan React Query
      if (canReadUsers) {
        fetchUsers()
      }
      // Alertas ahora se manejan via AlertsPanel (React Query)
    }
  }, [user, canReadDashboard, fetchUsers])

  // OPTIMIZACIÓN: si completeStats ya están listos, no mantener el skeleton por alertas
  useEffect(() => {
    if (!completeLoading) {
      setIsInitialLoad(false)
    }
  }, [completeLoading])

  // Cleanup de timeouts programados
  useEffect(() => {
    return () => {
      if (usersRetryTimeoutRef.current) {
        clearTimeout(usersRetryTimeoutRef.current)
        usersRetryTimeoutRef.current = null
      }
    }
  }, [])

  // ELIMINADO: Ya no necesitamos actualizar systemStats desde stats (usamos completeStats directamente)

  // Alertas ahora se manejan via AlertsPanel (React Query) - código eliminado

  const kpiIconMap: Record<string, React.ReactNode> = useMemo(
    () => ({
      health_index: <HeartPulse className="w-5 h-5 text-red-500" />,
      vaccination_coverage: <ShieldCheck className="w-5 h-5 text-emerald-600" />,
      control_compliance: <Stethoscope className="w-5 h-5 text-sky-600" />,
      mortality_rate_30d: <Skull className="w-5 h-5 text-zinc-600" />,
      sales_rate_30d: <ShoppingCart className="w-5 h-5 text-amber-600" />,
      treatments_intensity: <Pill className="w-5 h-5 text-indigo-600" />,
      controls_frequency: <ClipboardCheck className="w-5 h-5 text-blue-600" />,
      herd_growth_rate: <TrendingUp className="w-5 h-5 text-emerald-700" />,
      alert_pressure: <AlertTriangle className="w-5 h-5 text-red-500" />,
      task_load_index: <ListChecks className="w-5 h-5 text-orange-600" />,
    }),
    []
  );

  // Generación de tarjetas del dashboard usando estadísticas completas del backend
  const renderCompleteStatsCards = () => (
    <div className="space-y-6">
      {/* Errores del endpoint completo */}
      {completeError && (
        <Alert className="flex flex-col sm:flex-row items-start gap-2">
          <AlertTriangle className="h-4 w-4 mt-0.5 flex-shrink-0 text-destructive" />
          <AlertDescription className="flex-1 min-w-0">
            <span className="block sm:inline overflow-wrap-anywhere">
              Error cargando estadísticas: {completeError.message}
            </span>
            <Button
              variant="link"
              onClick={() => refetchComplete()}
              className="mt-1 sm:mt-0 sm:ml-2 h-auto p-0 text-sm"
            >
              Reintentar
            </Button>
          </AlertDescription>
        </Alert>
      )}

      <Accordion
        type="multiple"
        defaultValue={kpiCards.length > 0 ? ['kpis', 'general', 'alerts'] : ['general', 'alerts']}
        className="w-full"
      >
        {kpiCards.length > 0 && (
          <AccordionItem value="kpis">
            <AccordionTrigger className="text-left">
              <div className="flex items-center gap-2">
                <span>KPIs de salud y operación</span>
                {kpiResumen?.ventana_dias && (
                  <span className="text-xs text-muted-foreground">
                    Ventana móvil {kpiResumen.ventana_dias}d
                  </span>
                )}
                <Badge variant="secondary">{kpiCards.length}</Badge>
              </div>
            </AccordionTrigger>
            <AccordionContent className="pt-2">
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                {kpiCards.map((card) => {
                  const isBadWhenHigher =
                    card.id === 'mortality_rate_30d' ||
                    card.id === 'sales_rate_30d' ||
                    card.id === 'alert_pressure' ||
                    card.id === 'task_load_index';
                  const goodWhenHigher = !isBadWhenHigher;
                  const iconNode =
                    kpiIconMap[card.id] ?? (card.icono ? <span>{card.icono}</span> : null);
                  const unit = card.unidad || undefined;
                  const value =
                    typeof card.valor === 'number' && unit === '%'
                      ? card.valor.toFixed(1)
                      : card.valor;

                  return (
                    <KPICard
                      key={card.id}
                      title={card.titulo}
                      value={value}
                      unit={unit}
                      change={card.cambio}
                      icon={iconNode}
                      subtitle={card.descripcion}
                      goodWhenHigher={goodWhenHigher}
                    />
                  );
                })}
              </div>
            </AccordionContent>
          </AccordionItem>
        )}

        <AccordionItem value="general">
          <AccordionTrigger className="text-left">
            <div className="flex items-center gap-2">
              <span>Resumen general</span>
              <Badge variant="secondary">8</Badge>
            </div>
          </AccordionTrigger>
          <AccordionContent className="pt-2">
            <DashboardStatsGrid>
              <DashboardStatsCard title="Usuarios Registrados" icon={Users} stat={completeStats?.usuarios_registrados} description="Total de usuarios" onClick={() => navigate('/admin/users')} />
              <DashboardStatsCard title="Usuarios Activos" icon={Users} stat={completeStats?.usuarios_activos} description="Actividad reciente (30 días)" onClick={() => navigate('/admin/users?filter=active')} />
              <DashboardStatsCard title="Animales Registrados" icon={Building2} stat={completeStats?.animales_registrados} description="Total de animales" onClick={() => navigate('/admin/animals')} />
              <DashboardStatsCard title="Animales Activos" icon={Building2} stat={completeStats?.animales_activos} description="En seguimiento" onClick={() => navigate('/admin/animals')} />
              <DashboardStatsCard title="Tratamientos Activos" icon={ClipboardList} stat={completeStats?.tratamientos_activos} description="En proceso" onClick={() => navigate('/admin/treatments')} />
              <DashboardStatsCard title="Tratamientos Totales" icon={ClipboardList} stat={completeStats?.tratamientos_totales} description="Histórico" onClick={() => navigate('/admin/treatments')} />
              <DashboardStatsCard title="Vacunas Aplicadas" icon={ClipboardList} stat={completeStats?.vacunas_aplicadas} description="Total histórico" onClick={() => navigate('/admin/vaccinations')} />
              <DashboardStatsCard title="Controles Realizados" icon={ClipboardList} stat={completeStats?.controles_realizados} description="Sanidad" onClick={() => navigate('/admin/control')} />
              <DashboardStatsCard title="Producción de Leche" icon={ClipboardList} stat={completeStats?.produccion_leche} description="Registro diario" onClick={() => navigate('/admin/milk-production')} />
            </DashboardStatsGrid>
          </AccordionContent>
        </AccordionItem>

        <AccordionItem value="operation">
          <AccordionTrigger className="text-left">
            <div className="flex items-center gap-2">
              <span>Operación</span>
              <Badge variant="secondary">4</Badge>
            </div>
          </AccordionTrigger>
          <AccordionContent className="pt-2">
            <DashboardStatsGrid>
              <DashboardStatsCard title="Potreros" icon={Building2} stat={completeStats?.campos_registrados} description="Campos registrados" onClick={() => navigate('/admin/fields')} />
              <DashboardStatsCard title="Gastos Operativos" icon={ShoppingCart} stat={completeStats?.gastos_operativos} description="Costos de la finca" onClick={() => navigate('/admin/operational')} />
              <DashboardStatsCard title="Tareas Pendientes" icon={AlertTriangle} stat={completeStats?.tareas_pendientes} description="Requieren atención" onClick={() => navigate('/admin/tasks')} />
              <DashboardStatsCard title="Alertas del Sistema" icon={AlertTriangle} stat={completeStats?.alertas_sistema} description="Notificaciones" onClick={() => navigate('/admin/alerts')} />
              <DashboardStatsCard title="Mejoras Genéticas" icon={ClipboardList} stat={completeStats?.mejoras_geneticas} description="Programas activos" onClick={() => navigate('/admin/genetic_improvements')} />
            </DashboardStatsGrid>
          </AccordionContent>
        </AccordionItem>

        <AccordionItem value="analytics">
          <AccordionTrigger className="text-left">
            <div className="flex items-center gap-2">
              <span>Analítica y Finanzas</span>
              <Badge variant="secondary">2</Badge>
            </div>
          </AccordionTrigger>
          <AccordionContent className="pt-2">
            <DashboardStatsGrid columns={2}>
              <DashboardStatsCard title="Dashboard Financiero" icon={ClipboardList} stat={completeStats?.tratamientos_activos || 0} description="Gestión de transacciones y ROI" onClick={() => navigate('/admin/financial')} />
              <DashboardStatsCard title="Analítica Multi-Finca" icon={Building2} stat={completeStats?.campos_registrados || 0} description="Comparador de KPIs entre fincas" onClick={() => navigate('/admin/analytics/multi-finca')} />
            </DashboardStatsGrid>
          </AccordionContent>
        </AccordionItem>

        <AccordionItem value="catalogs">
          <AccordionTrigger className="text-left">
            <div className="flex items-center gap-2">
              <span>Catálogos</span>
              <Badge variant="secondary">6</Badge>
            </div>
          </AccordionTrigger>
          <AccordionContent className="pt-2">
            <DashboardStatsGrid columns={3}>
              <DashboardStatsCard title="Vacunas" icon={ClipboardList} stat={completeStats?.catalogo_vacunas} description="Catálogo" onClick={() => navigate('/admin/vaccines')} />
              <DashboardStatsCard title="Medicamentos" icon={ClipboardList} stat={completeStats?.catalogo_medicamentos} description="Catálogo" onClick={() => navigate('/admin/medications')} />
              <DashboardStatsCard title="Enfermedades" icon={ClipboardList} stat={completeStats?.catalogo_enfermedades} description="Catálogo" onClick={() => navigate('/admin/diseases')} />
              <DashboardStatsCard title="Especies" icon={ClipboardList} stat={completeStats?.catalogo_especies} description="Catálogo" onClick={() => navigate('/admin/species')} />
              <DashboardStatsCard title="Razas" icon={ClipboardList} stat={completeStats?.catalogo_razas} description="Catálogo" onClick={() => navigate('/admin/breeds')} />
              <DashboardStatsCard title="Tipos de Alimento" icon={ClipboardList} stat={completeStats?.catalogo_tipos_alimento} description="Catálogo" onClick={() => navigate('/admin/food-types')} />
            </DashboardStatsGrid>
          </AccordionContent>
        </AccordionItem>

        <AccordionItem value="relations">
          <AccordionTrigger className="text-left">
            <div className="flex items-center gap-2">
              <span>Relaciones y tratamientos</span>
              <Badge variant="secondary">4</Badge>
            </div>
          </AccordionTrigger>
          <AccordionContent className="pt-2">
            <DashboardStatsGrid columns={3}>
              <DashboardStatsCard title="Animales por Campo" icon={ClipboardList} stat={completeStats?.animales_por_campo} description="Distribución" onClick={() => navigate('/admin/animal-fields')} />
              <DashboardStatsCard title="Animales por Enfermedad" icon={ClipboardList} stat={completeStats?.animales_por_enfermedad} description="Sanidad" onClick={() => navigate('/admin/disease-animals')} />
              <DashboardStatsCard title="Tratamientos con Medicamentos" icon={ClipboardList} stat={completeStats?.tratamientos_medicamentos} description="Aplicados" onClick={() => navigate('/admin/treatment_medications')} />
              <DashboardStatsCard title="Tratamientos con Vacunas" icon={ClipboardList} stat={completeStats?.tratamientos_vacunas} description="Aplicados" onClick={() => navigate('/admin/treatment_vaccines')} />
            </DashboardStatsGrid>
          </AccordionContent>
        </AccordionItem>

        {/* Alertas del sistema - usando AlertsPanel consolidado */}
        {hasPermission('system:read') && (
          <AccordionItem value="alerts">
            <AccordionTrigger className="text-left">
              <div className="flex items-center gap-2">
                <span>{t('dashboard.alerts.title')}</span>
                <Badge variant="secondary">Vía React Query</Badge>
              </div>
            </AccordionTrigger>
            <AccordionContent className="pt-2">
              <AlertsPanel />
            </AccordionContent>
          </AccordionItem>
        )}
        
        <AccordionItem value="system">
          <AccordionTrigger className="text-left">
            <div className="flex items-center gap-2">
              <History className="h-4 w-4" />
              <span>Sistema y Auditoría</span>
              <Badge variant="secondary">2</Badge>
            </div>
          </AccordionTrigger>
          <AccordionContent className="pt-2">
            <DashboardStatsGrid columns={2}>
              <DashboardStatsCard title="Bitácora de Actividad" icon={History} stat={completeStats?.logs_actividad || 0} description="Auditoría de operaciones" onClick={() => navigate('/admin/activity-log')} />
              <DashboardStatsCard title="Mantenimiento" icon={SettingsIcon} stat={completeStats?.alertas_sistema || 0} description="Configuración técnica" onClick={() => navigate('/admin/diagnostics')} />
            </DashboardStatsGrid>
          </AccordionContent>
        </AccordionItem>
      </Accordion>
    </div>
  );

  // Renderizar contenido de la pestaña de resumen
  const renderOverviewTab = () => (
    <div className="space-y-6">
      {/* Tarjetas de estadísticas con skeleton screen mejorado */}
      {(completeLoading || isInitialLoad) ? (
        <DashboardStatsGrid>
          {Array.from({ length: 8 }).map((_, i) => (
            <SkeletonCard key={i} />
          ))}
        </DashboardStatsGrid>
      ) : (
        <div className="space-y-6">
          <Suspense fallback={Array.from({ length: 8 }).map((_, i) => <SkeletonCard key={i} />)}>
            {renderCompleteStatsCards()}
          </Suspense>

          {/* ── HERO ANALYTICS SECTION ── */}
          <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
            {/* Gráfica de Tendencia Global Premium */}
            <Card className="xl:col-span-2 border-none shadow-2xl shadow-primary/5 bg-gradient-to-br from-slate-900 to-slate-800 text-white rounded-[2.5rem] overflow-hidden">
              <CardHeader className="pb-2">
                <div className="flex items-center justify-between">
                  <div>
                    <CardTitle className="text-2xl font-black tracking-tighter flex items-center gap-3">
                      <div className="h-10 w-10 rounded-2xl bg-primary/20 flex items-center justify-center border border-primary/20">
                        <TrendingUp className="h-5 w-5 text-primary" />
                      </div>
                      Tendencia de Salud del Hato
                    </CardTitle>
                    <CardDescription className="text-slate-400 font-medium">Análisis de bienestar animal en tiempo real</CardDescription>
                  </div>
                  <div className="text-right">
                    <Badge variant="outline" className="bg-emerald-500/10 text-emerald-400 border-emerald-500/20 px-3 py-1 text-xs font-black">
                      +12.5% VS MES ANTERIOR
                    </Badge>
                  </div>
                </div>
              </CardHeader>
              <CardContent className="p-0 sm:p-8">
                <div className="h-[350px] w-full">
                  <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={completeStats?.health_trend || [
                      { name: 'Sem 1', value: 65, tasks: 40 },
                      { name: 'Sem 2', value: 78, tasks: 55 },
                      { name: 'Sem 3', value: 72, tasks: 45 },
                      { name: 'Sem 4', value: 85, tasks: 60 },
                    ]}>
                      <defs>
                        <linearGradient id="colorHealth" x1="0" y1="0" x2="0" y2="1">
                          <stop offset="5%" stopColor="#10b981" stopOpacity={0.4}/>
                          <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                        </linearGradient>
                        <linearGradient id="colorTasks" x1="0" y1="0" x2="0" y2="1">
                          <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.2}/>
                          <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                        </linearGradient>
                      </defs>
                      <CartesianGrid strokeDasharray="3 3" stroke="#ffffff10" vertical={false} />
                      <XAxis 
                        dataKey="name" 
                        stroke="#ffffff40" 
                        fontSize={10} 
                        fontWeight="bold"
                        tickLine={false}
                        axisLine={false}
                        dy={10}
                      />
                      <YAxis 
                        stroke="#ffffff40" 
                        fontSize={10} 
                        fontWeight="bold"
                        tickLine={false}
                        axisLine={false}
                        tickFormatter={(v) => `${v}%`}
                      />
                      <Tooltip 
                        content={({ active, payload, label }) => {
                          if (active && payload && payload.length) {
                            return (
                              <div className="bg-slate-900/80 backdrop-blur-xl border border-white/10 p-4 rounded-2xl shadow-2xl">
                                <p className="text-[10px] font-black text-white/40 uppercase tracking-widest mb-2">{label}</p>
                                {payload.map((p: any) => (
                                  <div key={p.name} className="flex items-center gap-3">
                                    <div className="h-2 w-2 rounded-full" style={{ backgroundColor: p.color }} />
                                    <p className="text-sm font-black text-white">
                                      {p.name === 'value' ? 'Salud' : 'Actividad'}: {p.value}{p.name === 'value' ? '%' : ''}
                                    </p>
                                  </div>
                                ))}
                              </div>
                            );
                          }
                          return null;
                        }}
                      />
                      <Area 
                        type="monotone" 
                        dataKey="value" 
                        stroke="#10b981" 
                        strokeWidth={4} 
                        fillOpacity={1} 
                        fill="url(#colorHealth)" 
                        animationDuration={2500}
                        activeDot={{ r: 8, strokeWidth: 0 }}
                      />
                      <Area 
                        type="monotone" 
                        dataKey="tasks" 
                        stroke="#3b82f6" 
                        strokeWidth={2} 
                        strokeDasharray="5 5"
                        fillOpacity={1} 
                        fill="url(#colorTasks)" 
                        animationDuration={3000}
                      />
                    </AreaChart>
                  </ResponsiveContainer>
                </div>
              </CardContent>
            </Card>

            {/* Panel lateral de distribución */}
            <div className="space-y-6">
              <Card className="border-none shadow-xl bg-white dark:bg-slate-900 rounded-[2.5rem] overflow-hidden p-6">
                <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">Carga de Trabajo</h3>
                <div className="h-[180px] w-full">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={[
                      { name: 'Vacunas', val: 45 },
                      { name: 'Controles', val: 32 },
                      { name: 'Trat.', val: 28 },
                      { name: 'Mueve', val: 15 },
                    ]}>
                       <Tooltip 
                        cursor={{fill: '#f1f5f9'}}
                        content={({ active, payload }) => {
                          if (active && payload && payload.length) {
                            return (
                              <div className="bg-white border shadow-lg p-2 rounded-lg">
                                <p className="text-xs font-bold">{payload[0].value} tareas</p>
                              </div>
                            );
                          }
                          return null;
                        }}
                      />
                      <Bar dataKey="val" radius={[10, 10, 10, 10]}>
                        {[0, 1, 2, 3].map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={['#10b981', '#3b82f6', '#8b5cf6', '#f59e0b'][index % 4]} />
                        ))}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
                <div className="mt-4 grid grid-cols-2 gap-2">
                  <div className="bg-emerald-50 dark:bg-emerald-500/10 p-3 rounded-2xl">
                    <p className="text-[10px] font-black text-emerald-600 dark:text-emerald-400 uppercase">Efectividad</p>
                    <p className="text-xl font-black text-emerald-700 dark:text-emerald-300">94%</p>
                  </div>
                  <div className="bg-blue-50 dark:bg-blue-500/10 p-3 rounded-2xl">
                    <p className="text-[10px] font-black text-blue-600 dark:text-blue-400 uppercase">Tiempo</p>
                    <p className="text-xl font-black text-blue-700 dark:text-blue-300">-15%</p>
                  </div>
                </div>
              </Card>

              <Card className="border-none shadow-xl bg-gradient-to-br from-indigo-600 to-violet-700 text-white rounded-[2.5rem] p-6">
                <div className="flex items-center gap-4 mb-4">
                  <div className="h-12 w-12 rounded-2xl bg-white/20 flex items-center justify-center">
                    <ShieldCheck className="h-6 w-6 text-white" />
                  </div>
                  <div>
                    <p className="text-[10px] font-black text-white/60 uppercase tracking-widest">Estado Sanitario</p>
                    <h4 className="text-lg font-black italic tracking-tighter uppercase">Excelente</h4>
                  </div>
                </div>
                <p className="text-xs font-medium text-white/80 leading-relaxed">
                  Todos los protocolos ICA se encuentran al día. La trazabilidad está asegurada al 100%.
                </p>
                <Button variant="link" className="text-white p-0 mt-2 h-auto text-xs font-black uppercase tracking-widest">
                  Ver Auditoría →
                </Button>
              </Card>
            </div>
          </div>

          {/* Mapa de Potreros e IoT */}
          <Suspense fallback={<SkeletonCard className="h-[500px]" />}>
            <FieldHealthMap />
          </Suspense>
        </div>
      )}



      {/* Asistente IA */}
      <Suspense fallback={<SkeletonCard className="h-[200px]" />}>
        <AIInsightsWidget />
      </Suspense>

      {/* Reportes Regulatorios */}
      <Suspense fallback={<SkeletonCard className="h-[200px]" />}>
        <RegulatoryReportsWidget />
      </Suspense>

      {/* Alertas de Celo */}
      <Suspense fallback={<SkeletonCard className="h-[200px]" />}>
        <HeatAlertsWidget />
      </Suspense>

      {/* Calendario Sanitario del Hato (ICA/FEDEGAN) */}
      <Card className="border-none shadow-lg rounded-2xl overflow-hidden">
        <CardHeader className="pb-2">
          <CardTitle className="text-lg font-black flex items-center gap-2">
            🗓️ Calendario Sanitario del Hato
          </CardTitle>
          <CardDescription>Eventos pendientes por animal — Basado en normas ICA y FEDEGAN</CardDescription>
        </CardHeader>
        <CardContent>
          <Suspense fallback={<SkeletonCard className="h-[200px]" />}>
            <CalendarioSanitarioWidget maxItems={15} />
          </Suspense>
        </CardContent>
      </Card>

      {/* Usuarios recientes */}
      {hasPermission('user:read') && (
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-xl font-bold tracking-tight">{t('dashboard.recentUsers.title')}</h2>
              <p className="text-sm text-muted-foreground">{t('dashboard.recentUsers.description')}</p>
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={() => navigate('/admin/users')}
              className="hidden sm:flex items-center gap-2"
            >
              {t('dashboard.recentUsers.viewAll')} <ExternalLink className="h-4 w-4" />
            </Button>
          </div>

          <Card className="border-none shadow-none bg-transparent">
            <CardContent className="p-0">
              {loading ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                  {Array.from({ length: 4 }).map((_, i) => (
                    <SkeletonCard key={i} />
                  ))}
                </div>
              ) : users.length === 0 ? (
                <div className="text-center py-12 border-2 border-dashed rounded-lg bg-gray-50/50">
                  <div className="mx-auto h-12 w-12 text-gray-400 mb-3">
                    <Users className="h-12 w-12 opacity-50" />
                  </div>
                  <h3 className="text-lg font-medium text-gray-900">{t('dashboard.recentUsers.noUsers')}</h3>
                  <p className="text-sm text-gray-500 mt-1">No hay usuarios registrados recientemente.</p>
                </div>
              ) : (
                <div className="space-y-4">
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                    {users.slice(0, 8).map((user) => (
                      <UserCard
                        key={user.id}
                        user={user}
                        onView={() => navigate(`/admin/users?id=${user.id}`)}
                      />
                    ))}
                  </div>
                </div>
              )}

              <Button
                variant="outline"
                className="w-full sm:hidden mt-4"
                onClick={() => navigate('/admin/users')}
              >
                {t('dashboard.recentUsers.viewAll')}
              </Button>
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  )


  const { isOnline, pendingOperations } = useOnlineStatus();

  return (
    <div className="min-h-screen bg-slate-50/50 dark:bg-black/20 pb-20">
      {/* Header Premium de Cristal */}
      <header className="sticky top-0 z-50 w-full border-b border-white/20 bg-white/60 dark:bg-slate-900/60 backdrop-blur-2xl">
        <div className="mx-auto flex h-24 max-w-[1600px] items-center justify-between px-8">
          <div className="flex items-center gap-5">
            <div className="flex h-12 w-12 items-center justify-center rounded-[1.25rem] bg-slate-900 text-white shadow-2xl shadow-slate-900/20">
              <Sprout className="h-6 w-6" />
            </div>
            <div>
              <h1 className="text-xl font-black tracking-tighter text-slate-900 dark:text-white uppercase">Villa Luz <span className="text-primary">Admin</span></h1>
              <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400">Panel de Control Maestro</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
             <div className={cn(
              "hidden items-center gap-2.5 rounded-2xl border px-5 py-2.5 text-[10px] font-black uppercase tracking-widest transition-all md:flex shadow-sm",
              isOnline ? "bg-emerald-500/10 border-emerald-500/20 text-emerald-600" : "bg-rose-500/10 border-rose-500/20 text-rose-600 animate-pulse"
            )}>
              {isOnline ? <Wifi className="h-3.5 w-3.5" /> : <WifiOff className="h-3.5 w-3.5" />}
              {isOnline ? 'Cloud Sync Activo' : 'Sin Conexión'}
            </div>
            
            <motion.button 
              whileHover={{ rotate: 180 }}
              onClick={() => refetchComplete()}
              className="flex h-12 w-12 items-center justify-center rounded-2xl border border-white/20 bg-white/50 dark:bg-black/20 text-slate-500 hover:text-slate-900 transition-all shadow-sm backdrop-blur-md"
            >
              <RefreshCw className={cn("h-5 w-5", completeLoading ? "animate-spin" : "")} />
            </motion.button>
          </div>
        </div>
      </header>

      <main className="mx-auto max-w-[1600px] space-y-12 px-8 py-10">
        {/* Banner de Bienvenida Premium */}
        <section className="relative overflow-hidden rounded-[3.5rem] bg-slate-950 p-12 text-white shadow-2xl">
           <div className="absolute top-0 right-0 w-2/3 h-full bg-gradient-to-l from-primary/30 to-transparent blur-3xl opacity-50" />
           <div className="absolute -bottom-24 -left-24 w-80 h-80 bg-blue-500/20 rounded-full blur-3xl" />
           
           <div className="relative z-10 max-w-3xl">
              <div className="flex items-center gap-3 mb-8">
                <Badge className="bg-primary text-slate-950 border-0 font-black uppercase tracking-[0.2em] text-[9px] py-2 px-6 rounded-full shadow-lg shadow-primary/20">
                  {isOnline ? 'SISTEMA CENTRALIZADO' : 'MODO RESILIENTE'}
                </Badge>
                {pendingOperations > 0 && (
                  <Badge variant="outline" className="border-white/20 text-white font-black text-[9px] tracking-[0.2em] py-2 px-6 rounded-full backdrop-blur-md">
                    {pendingOperations} CAMBIOS PENDIENTES
                  </Badge>
                )}
              </div>
              
              <h2 className="text-6xl font-black leading-[1] tracking-tighter md:text-7xl mb-6">
                Gestión total en <span className="text-transparent bg-clip-text bg-gradient-to-r from-primary to-blue-400">tiempo real.</span>
              </h2>
              
              <p className="max-w-xl text-lg font-medium text-slate-300 leading-relaxed mb-8">
                Bienvenido al núcleo de Villa Luz. Monitorea cada animal, recurso y operario con precisión milimétrica desde cualquier lugar.
              </p>

              <div className="flex flex-wrap gap-4">
                <Button 
                  onClick={() => navigate('/admin/reports')}
                  className="rounded-2xl h-14 px-8 font-black uppercase tracking-widest bg-white text-slate-900 hover:bg-slate-100 border-0"
                >
                  Generar Reporte ICA
                </Button>
                <Button 
                  variant="outline" 
                  onClick={() => navigate('/admin/users')}
                  className="rounded-2xl h-14 px-8 font-black uppercase tracking-widest border-white/20 text-white hover:bg-white/10 backdrop-blur-sm"
                >
                  Gestionar Equipo
                </Button>
              </div>
           </div>
        </section>

        <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
          <TabsList className="h-16 p-2 bg-white/50 dark:bg-slate-900/50 backdrop-blur-md border border-white/20 rounded-2xl mb-10 overflow-x-auto flex-nowrap w-fit [scrollbar-width:none] [-webkit-overflow-scrolling:touch]">
            <TabsTrigger value="overview" className="rounded-xl px-8 font-black text-[10px] uppercase tracking-widest data-[state=active]:bg-primary data-[state=active]:text-white transition-all">
              {t('dashboard.tabs.overview', 'Resumen')}
            </TabsTrigger>
            <TabsTrigger value="system" className="rounded-xl px-8 font-black text-[10px] uppercase tracking-widest data-[state=active]:bg-primary data-[state=active]:text-white transition-all">
              {t('dashboard.tabs.system', 'Infraestructura')}
            </TabsTrigger>
            <TabsTrigger value="settings" className="rounded-xl px-8 font-black text-[10px] uppercase tracking-widest data-[state=active]:bg-primary data-[state=active]:text-white transition-all">
              {t('dashboard.tabs.settings', 'Configuración')}
            </TabsTrigger>
          </TabsList>
          
          <TabsContent value="overview" className="focus-visible:outline-none">
            {renderOverviewTab()}
          </TabsContent>
          <TabsContent value="system" className="focus-visible:outline-none">
            <Suspense fallback={<div className="grid grid-cols-1 gap-4">{Array.from({ length: 3 }).map((_, i) => <SkeletonCard key={i} />)}</div>}>
              <SystemTab />
            </Suspense>
          </TabsContent>
          <TabsContent value="settings" className="focus-visible:outline-none">
            <Suspense fallback={<div className="grid grid-cols-1 gap-4">{Array.from({ length: 2 }).map((_, i) => <SkeletonCard key={i} />)}</div>}>
              <SettingsTab />
            </Suspense>
          </TabsContent>
        </Tabs>
      </main>
    </div>
  );
};

