                                setSelectedUser(user);
                                setIsDeleteDialogOpen(true);
                              }}
                              aria-label="Eliminar"
                            >
                              <Trash2 className="mr-2 h-4 w-4" /> Eliminar
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                        <UserActionsMenu user={user} />
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
