import React, { useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { LoadingDashboard, ProgressMetric, QuickStat } from './components/DashboardWidgets';
import { useAnalytics } from '@/features/reporting/model/useAnalytics';
import KPICard from '@/widgets/analytics/KPICard';
import AlertCard from '@/widgets/analytics/AlertCard';
import { Doughnut, Bar, Line } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  ArcElement,
  BarElement,
  Title,
  Tooltip,
  Legend,
  Filler,
} from 'chart.js';
import { COLORS, getChartColors } from '@/shared/utils/colors';
import { format } from 'date-fns';
import { es } from 'date-fns/locale';
import { KpiCardSummary } from '@/features/dashboard/model/useCompleteDashboardStats';
import {
  HeartPulse,
  ShieldCheck,
  Stethoscope,
  Skull,
  ShoppingCart,
  Pill,
  ClipboardCheck,
  TrendingUp,
  AlertTriangle,
  ListChecks,
} from 'lucide-react';
import { RegulatoryReportsControl } from '@/features/regulatory-reports/components/RegulatoryReportsControl';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  ArcElement,
  BarElement,
  Title,
  Tooltip,
  Legend,
  Filler
);

const KPI_ORDER = [
  'health_index',
  'vaccination_coverage',
  'control_compliance',
  'mortality_rate_30d',
  'sales_rate_30d',
  'treatments_intensity',
  'controls_frequency',
  'herd_growth_rate',
  'alert_pressure',
  'task_load_index',
];

const DashboardExecutive: React.FC = () => {
  const navigate = useNavigate();
  const {
    useDashboard,
    useAnimalStatistics,
    useHealthStatistics,
    useProductionStatistics,
    useAlerts,
  } = useAnalytics();

  const clickableChartOptions = (targetPath: string) => ({
    onClick: () => navigate(targetPath),
    onHover: (event: any, chartElement: any) => {
      event.native.target.style.cursor = chartElement[0] ? 'pointer' : 'default';
    }
  });

  const { data: dashboard, isLoading: loadingDashboard } = useDashboard();
  const {
    data: animalStats,
    isLoading: loadingAnimalStats,
  } = useAnimalStatistics();
  const {
    data: healthStats,
    isLoading: loadingHealthStats,
  } = useHealthStatistics();
  const {
    data: productionStats,
    isLoading: loadingProductionStats,
  } = useProductionStatistics();
  const { data: alerts, isLoading: loadingAlerts } = useAlerts({
    priority: 'critical',
    limit: 5,
  });

  const kpiResumen = dashboard?.kpi_resumen;
  const rawKpiCards: KpiCardSummary[] = useMemo(
    () => kpiResumen?.cards ?? [],
    [kpiResumen]
  );
  const kpiCards = useMemo<KpiCardSummary[]>(() => {
    if (!rawKpiCards.length) return [];
    const indexOfId = (id: string) => KPI_ORDER.indexOf(id);
    return [...rawKpiCards].sort((a, b) => {
      const ai = indexOfId(a.id);
      const bi = indexOfId(b.id);
      if (ai === -1 && bi === -1) return a.id.localeCompare(b.id);
      if (ai === -1) return 1;
      if (bi === -1) return -1;
      return ai - bi;
    });
  }, [rawKpiCards]);

  const kpiIconMap = useMemo<Record<string, React.ReactNode>>(
    () => ({
      health_index: <HeartPulse className="w-5 h-5 text-red-500" />,
      vaccination_coverage: <ShieldCheck className="w-5 h-5 text-emerald-600" />,
      control_compliance: <Stethoscope className="w-5 h-5 text-sky-600" />,
      mortality_rate_30d: <Skull className="w-5 h-5 text-zinc-600" />,
      sales_rate_30d: <ShoppingCart className="w-5 h-5 text-amber-600" />,
      treatments_intensity: <Pill className="w-5 h-5 text-indigo-600" />,
      controls_frequency: <ClipboardCheck className="w-5 h-5 text-blue-600" />,
      herd_growth_rate: <TrendingUp className="w-5 h-5 text-emerald-700" />,
      alert_pressure: <AlertTriangle className="w-5 h-5 text-red-500" />,
      task_load_index: <ListChecks className="w-5 h-5 text-orange-600" />,
    }),
    []
  );

  if (loadingDashboard) {
    return <LoadingDashboard />;
  }

  if (!dashboard) {
    return (
      <div className="h-full overflow-auto bg-background p-6" tabIndex={0}>
        <div className="text-center py-12">
          <p className="text-muted-foreground text-lg">No hay datos disponibles</p>
        </div>
      </div>
    );
  }

  const totalesSexo = {
    machos: dashboard.distribucion_sexo?.machos || animalStats?.by_gender?.Macho || 0,
    hembras: dashboard.distribucion_sexo?.hembras || animalStats?.by_gender?.Hembra || 0,
  };

  const sexDistributionData = {
    labels: ['Machos', 'Hembras'],
    datasets: [
      {
        data: [totalesSexo.machos, totalesSexo.hembras],
        backgroundColor: [COLORS.animals.male, COLORS.animals.female],
        borderWidth: 2,
        borderColor: '#fff',
      },
    ],
  };

  const statusChartData =
    animalStats?.by_status && Object.keys(animalStats.by_status).length > 0
      ? {
        labels: Object.keys(animalStats.by_status),
        datasets: [
          {
            label: 'Animales',
            data: Object.values(animalStats.by_status),
            backgroundColor: getChartColors(Object.keys(animalStats.by_status).length),
            borderRadius: 6,
          },
        ],
      }
      : null;

  const ageDistributionData =
    animalStats?.age_distribution && animalStats.age_distribution.length > 0
      ? {
        labels: animalStats.age_distribution.map((item) => item.age_range),
        datasets: [
          {
            label: 'Cantidad',
            data: animalStats.age_distribution.map((item) => item.count),
            backgroundColor: COLORS.charts.secondary,
            borderRadius: 4,
          },
        ],
      }
      : null;

  const topBreeds =
    animalStats?.by_breed?.length
      ? animalStats.by_breed
      : dashboard.distribucion_razas_top5 || [];

  const enfermedadesComunes = healthStats?.common_diseases || [];
  const fechaActualizacion = dashboard.generated_at
    ? new Date(dashboard.generated_at)
    : undefined;

  // KPIs derivados del backend (no usan hooks adicionales para evitar violar reglas de hooks)
  const percentageKpis = kpiCards.filter((card) =>
    [
      'health_index',
      'vaccination_coverage',
      'control_compliance',
      'mortality_rate_30d',
      'sales_rate_30d',
      'alert_pressure',
      'task_load_index',
    ].includes(card.id)
  );

  const intensityKpis = kpiCards.filter((card) =>
    ['treatments_intensity', 'controls_frequency', 'herd_growth_rate'].includes(card.id)
  );

  const healthTimeSeries = (() => {
    const treatments = healthStats?.treatments_by_month || [];
    const vaccinations = healthStats?.vaccinations_by_month || [];
    if (!treatments.length && !vaccinations.length) return null;
    // Unificar etiquetas por periodo
    const labels = Array.from(
      new Set([
        ...treatments.map((i: any) => i.period),
        ...vaccinations.map((i: any) => i.period),
      ])
    ).sort();

    const mapSeries = (src: any[]) =>
      labels.map((p) => src.find((i) => i.period === p)?.count ?? 0);

    return {
      labels,
      datasets: [
        {
          label: 'Tratamientos',
          data: mapSeries(treatments),
          borderColor: COLORS.charts.primary,
          backgroundColor: COLORS.charts.primary,
          tension: 0.25,
          fill: false,
        },
        {
          label: 'Vacunaciones',
          data: mapSeries(vaccinations),
          borderColor: COLORS.charts.secondary,
          backgroundColor: COLORS.charts.secondary,
          tension: 0.25,
          fill: false,
        },
      ],
    };
  })();

  const weightTrendSeries = (() => {
    const trends = productionStats?.weight_trends || [];
    if (!trends.length) return null;
    const labels = trends.map(
      (t: any) => t.period ?? `${t.year}-${String(t.month).padStart(2, '0')}`
    );
    const data = trends.map((t: any) => t.avg_weight ?? 0);
    return {
      labels,
      datasets: [
        {
          label: 'Peso promedio (kg)',
          data,
          borderColor: COLORS.charts.primary,
          backgroundColor: COLORS.charts.primary,
          tension: 0.3,
          fill: true,
        },
      ],
    };
  })();

  const formatNumber = (value?: number, options?: Intl.NumberFormatOptions) => {
    if (value === undefined || value === null || Number.isNaN(Number(value))) return '0';
    return Number(value).toLocaleString('es-CO', options);
  };

  return (
    <div
      className="h-full overflow-auto bg-background p-6 space-y-8"
      tabIndex={0}
    >
      <div>
        <h1 className="text-3xl font-bold text-foreground">Panel integral de analítica</h1>
        <p className="text-muted-foreground mt-2">
          Monitorea inventario, salud, producción y alertas en tiempo real
        </p>
        {fechaActualizacion && (
          <p className="text-xs text-muted-foreground mt-1">
            Última actualización:{' '}
            {format(fechaActualizacion, "d 'de' MMMM, h:mm a", { locale: es })}
          </p>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {kpiCards.length > 0
          ? kpiCards.slice(0, 4).map((card) => {
            const isBadWhenHigher =
              card.id === 'mortality_rate_30d' ||
              card.id === 'sales_rate_30d' ||
              card.id === 'alert_pressure' ||
              card.id === 'task_load_index';
            const unit = card.unidad || undefined;
            const value =
              typeof card.valor === 'number' && unit === '%'
                ? card.valor.toFixed(1)
                : card.valor;
            const iconNode =
              kpiIconMap[card.id] ||
              (card.icono ? <span className="text-lg">{card.icono}</span> : null);

            return (
              <KPICard
                key={card.id}
                title={card.titulo}
                value={value}
                unit={unit}
                change={card.cambio}
                icon={iconNode}
                subtitle={card.descripcion}
                goodWhenHigher={!isBadWhenHigher}
                loading={loadingDashboard}
              />
            );
          })
          : (
            <>
              <KPICard
                title="Animales registrados"
                value={dashboard.animales_registrados?.valor || 0}
                change={dashboard.animales_registrados?.cambio_porcentual}
                icon="🐄"
                loading={loadingDashboard}
              />
              <KPICard
                title="Animales vivos"
                value={dashboard.animales_activos?.valor || 0}
                change={dashboard.animales_activos?.cambio_porcentual}
                icon="💚"
                loading={loadingDashboard}
              />
              <KPICard
                title="Índice de salud"
                value={`${(dashboard.distribucion_salud?.excelente || 0) +
                  (dashboard.distribucion_salud?.bueno || 0)
                  }/${dashboard.animales_activos?.valor || 0}`}
                icon="🏥"
                loading={loadingDashboard}
                subtitle="Animales en condición óptima"
              />
              <KPICard
                title="Alertas activas"
                value={dashboard.alertas_sistema?.valor || 0}
                change={dashboard.alertas_sistema?.cambio_porcentual}
                icon="🔔"
                loading={loadingDashboard}
              />
            </>
          )}
      </div>

      {/* Visualización de KPIs como gauges (torta/oscilador) */}
      {percentageKpis.length > 0 && (
        <div className="bg-card rounded-lg shadow p-6">
          <h2 className="text-lg font-semibold text-foreground mb-4">
            Estado general del hato (KPIs porcentuales)
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-4">
            {percentageKpis.map((card) => {
              const unit = card.unidad || '%';
              const raw = typeof card.valor === 'number' ? card.valor : Number(card.valor) || 0;
              const clamped = Math.max(0, Math.min(raw, 100));
              const data = {
                labels: ['Valor', 'Resto'],
                datasets: [
                  {
                    data: [clamped, 100 - clamped],
                    backgroundColor: [COLORS.charts.primary, '#E5E7EB'],
                    borderWidth: 0,
                  },
                ],
              };
              const isBadWhenHigher =
                card.id === 'mortality_rate_30d' ||
                card.id === 'sales_rate_30d' ||
                card.id === 'alert_pressure' ||
                card.id === 'task_load_index';
              const goodWhenHigher = !isBadWhenHigher;
              const iconNode =
                kpiIconMap[card.id] ||
                (card.icono ? <span className="text-lg">{card.icono}</span> : null);

              return (
                <div key={card.id} className="flex flex-col items-center gap-2">
                  <div className="w-32 h-32">
                    <Doughnut
                      data={data}
                      options={{
                        cutout: '70%',
                        plugins: {
                          legend: { display: false },
                          tooltip: {
                            callbacks: {
                              label: (ctx) => `${ctx.parsed}%`,
                            },
                          },
                        },
                      }}
                    />
                  </div>
                  <div className="text-center space-y-1 text-card-foreground">
                    <div className="flex items-center justify-center gap-1 text-sm font-medium">
                      {iconNode}
                      <span>{card.titulo}</span>
                    </div>
                    <div className="text-sm font-semibold text-foreground">
                      {clamped.toFixed(1)}
                      {unit}
                    </div>
                    {typeof card.cambio === 'number' && (
                      <div className="text-xs">
                        <span
                          className={
                            (goodWhenHigher ? card.cambio >= 0 : card.cambio <= 0)
                              ? 'text-success-600'
                              : 'text-danger-600'
                          }
                        >
                          {card.cambio > 0 ? '+' : ''}
                          {card.cambio.toFixed(1)} pts
                        </span>{' '}
                        vs periodo anterior
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Comparación de intensidad/frecuencia/growth por periodo */}
      {intensityKpis.length > 0 && (
        <div className="bg-card rounded-lg shadow p-6">
          <h2 className="text-lg font-semibold text-foreground mb-4">
            Intensidad de manejo (aceleración de actividades)
          </h2>
          <div className="h-80">
            <Bar
              data={{
                labels: intensityKpis.map((c) => c.titulo),
                datasets: [
                  {
                    label: 'Periodo actual',
                    data: intensityKpis.map((c) => c.tendencia?.periodo_actual ?? c.valor ?? 0),
                    backgroundColor: COLORS.charts.primary,
                  },
                  {
                    label: 'Periodo anterior',
                    data: intensityKpis.map((c) => c.tendencia?.periodo_anterior ?? 0),
                    backgroundColor: COLORS.charts.secondary,
                  },
                ],
              }}
              options={{
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                  legend: { position: 'bottom' },
                },
                scales: {
                  y: {
                    beginAtZero: true,
                  },
                },
              }}
            />
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="bg-card rounded-lg shadow p-6">
          <h2 className="text-lg font-semibold text-foreground mb-4">Distribución por sexo</h2>
          <div className="h-64 flex items-center justify-center">
            <Doughnut
              data={sexDistributionData}
              options={{
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                  legend: { position: 'bottom' },
                  tooltip: {
                    callbacks: {
                      label: (context) => {
                        const total = totalesSexo.machos + totalesSexo.hembras;
                        const percentage =
                          total > 0 ? ((context.parsed / total) * 100).toFixed(1) : '0.0';
                        return `${context.label}: ${context.parsed} (${percentage}%)`;
                      },
                    },
                  },
                },
              }}
            />
          </div>
        </div>

        <div className="bg-card rounded-lg shadow p-6">
          <h2 className="text-lg font-semibold text-foreground mb-4">Estado de los animales</h2>
          <div className="h-64">
            {loadingAnimalStats ? (
              <div className="flex items-center justify-center h-full text-muted-foreground text-sm">
                Cargando estadísticas...
              </div>
            ) : statusChartData ? (
              <Bar
                data={statusChartData}
                options={{
                  responsive: true,
                  maintainAspectRatio: false,
                  plugins: { legend: { display: false } },
                  scales: {
                    y: { beginAtZero: true, ticks: { precision: 0 } },
                  },
                }}
              />
            ) : (
              <div className="flex items-center justify-center h-full text-muted-foreground text-sm">
                No hay datos de distribución por estado.
              </div>
            )}
          </div>
        </div>

        <div className="bg-card rounded-lg shadow p-6">
          <h2 className="text-lg font-semibold text-foreground mb-4">Resumen de inventario</h2>
          <div className="space-y-5">
            <QuickStat
              label="Total de animales"
              value={formatNumber(animalStats?.total ?? dashboard.animales_activos?.valor)}
              icon="🐮"
            />
            <QuickStat
              label="Peso promedio"
              value={
                animalStats?.average_weight ? `${animalStats.average_weight.toFixed(1)} kg` : '—'
              }
              icon="⚖️"
            />
            <QuickStat
              label="Animales por especie"
              value={dashboard.catalogo_especies?.valor || 0}
              icon="🧬"
            />
            <QuickStat
              label="Campos monitoreados"
              value={dashboard.campos_registrados?.valor || productionStats?.total_fields || 0}
              icon="🌱"
            />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-card rounded-lg shadow p-6">
          <h2 className="text-lg font-semibold text-foreground mb-4">Pirámide de edades</h2>
          <div className="h-64">
            {loadingAnimalStats ? (
              <div className="flex items-center justify-center h-full text-muted-foreground text-sm">
                Cargando distribución de edades...
              </div>
            ) : ageDistributionData ? (
              <Bar
                data={ageDistributionData}
                options={{
                  responsive: true,
                  maintainAspectRatio: false,
                  indexAxis: 'y',
                  plugins: { legend: { display: false } },
                  scales: {
                    x: { beginAtZero: true, ticks: { precision: 0 } },
                  },
                }}
              />
            ) : (
              <div className="flex items-center justify-center h-full text-muted-foreground text-sm">
                No hay datos de edades.
              </div>
            )}
          </div>
        </div>

        <div className="bg-card rounded-lg shadow p-6">
          <h2 className="text-lg font-semibold text-foreground mb-4">Razas destacadas</h2>
          {topBreeds && topBreeds.length > 0 ? (
            <div className="space-y-4">
              {topBreeds.slice(0, 5).map((breed: any, index: number) => {
                const nombre = breed.breed_name || breed.raza || breed.name || `Raza ${index + 1}`;
                const cantidad = breed.count ?? breed.cantidad ?? 0;
                const totalAnimales = animalStats?.total || dashboard.animales_activos?.valor || 1;
                const porcentaje = ((cantidad / totalAnimales) * 100).toFixed(1);
                return (
                  <div key={index}>
                    <div className="flex items-center justify-between text-sm font-medium text-card-foreground">
                      <span>{nombre}</span>
                      <span className="text-foreground">{cantidad}</span>
                    </div>
                    <div className="w-full bg-muted rounded-full h-2 mt-2">
                      <div
                        className="h-2 rounded-full bg-blue-500"
                        style={{ width: `${Math.min(Number(porcentaje), 100)}%` }}
                      />
                    </div>
                    <p className="text-xs text-muted-foreground mt-1">
                      {porcentaje}% del inventario
                    </p>
                  </div>
                );
              })}
            </div>
          ) : (
            <p className="text-sm text-muted-foreground">No hay datos de razas.</p>
          )}
        </div>
      </div>

      <div className="bg-card rounded-lg shadow p-6">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h2 className="text-xl font-bold text-foreground">Salud y bienestar</h2>
            <p className="text-sm text-muted-foreground">
              Seguimiento de tratamientos, vacunas y enfermedades recurrentes
            </p>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
          <KPICard
            title="Tratamientos registrados"
            value={healthStats?.total_treatments ?? dashboard.tratamientos_totales?.valor ?? 0}
            icon="💊"
            loading={loadingHealthStats}
          />
          <KPICard
            title="Tratamientos activos"
            value={healthStats?.active_treatments ?? dashboard.tratamientos_activos?.valor ?? 0}
            icon="🩺"
            loading={loadingHealthStats}
          />
          <KPICard
            title="Vacunas aplicadas"
            value={healthStats?.total_vaccinations ?? dashboard.vacunas_aplicadas?.valor ?? 0}
            icon="💉"
            loading={loadingHealthStats}
          />
          <KPICard
            title="Vacunas pendientes"
            value={healthStats?.pending_vaccinations ?? 0}
            icon="📅"
            loading={loadingHealthStats}
          />
        </div>

        {/* Evolución de tratamientos y vacunaciones */}
        {healthTimeSeries && (
          <div className="relative h-80 mt-4 mb-6 overflow-hidden">
            <h3 className="text-sm font-semibold text-foreground mb-2">
              Evolución de tratamientos y vacunaciones
            </h3>
            <Line
              data={healthTimeSeries}
              options={{
                responsive: true,
                maintainAspectRatio: false,
                ...clickableChartOptions('/admin/treatments'),
                plugins: {
                  legend: {
                    position: 'bottom',
                    align: 'start',
                    labels: {
                      boxWidth: 12,
                      boxHeight: 12,
                      padding: 14,
                      font: (ctx: any) => ({
                        size: ctx?.chart?.width && ctx.chart.width < 520 ? 10 : 12,
                      }),
                    },
                  },
                },
                layout: {
                  padding: { bottom: 8 },
                },
                scales: {
                  y: { beginAtZero: true, ticks: { precision: 0 } },
                  x: {
                    ticks: {
                      autoSkip: true,
                      maxRotation: 0,
                      minRotation: 0,
                    },
                  },
                },
              }}
            />
          </div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <div>
            <ProgressMetric
              label="Índice de éxito en tratamientos"
              value={healthStats?.treatment_success_rate ?? 0}
              suffix="%"
            />
            <p className="text-xs text-muted-foreground mt-2">
              Porcentaje de tratamientos concluidos satisfactoriamente.
            </p>
          </div>

          <div>
            <h3 className="text-sm font-semibold text-foreground mb-2">
              Enfermedades frecuentes
            </h3>
            {enfermedadesComunes.length > 0 ? (
              <ul className="space-y-2">
                {enfermedadesComunes.slice(0, 5).map((disease, index) => (
                  <li
                    key={`${disease.disease_name}-${index}`}
                    className="flex items-center justify-between text-sm text-card-foreground border-b border-gray-100 pb-2"
                  >
                    <span>{disease.disease_name}</span>
                    <span className="font-semibold text-foreground">{disease.count} casos</span>
                  </li>
                ))}
              </ul>
            ) : (
              <p className="text-sm text-muted-foreground">Sin registros recientes.</p>
            )}
          </div>
        </div>
      </div>

      <div className="bg-card rounded-lg shadow p-6">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h2 className="text-xl font-bold text-foreground">Producción y rendimiento</h2>
            <p className="text-sm text-muted-foreground">
              Utilización de potreros y eficiencia general
            </p>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
          <KPICard
            title="Campos registrados"
            value={productionStats?.total_fields ?? dashboard.campos_registrados?.valor ?? 0}
            icon="🏞️"
            loading={loadingProductionStats}
          />
          <KPICard
            title="Animales por campo"
            value={productionStats?.animals_per_field ?? 0}
            icon="🐄"
            loading={loadingProductionStats}
            subtitle="Promedio actual"
          />
          <KPICard
            title="Consumo de alimento"
            value={
              productionStats?.feed_consumption
                ? `${productionStats.feed_consumption} kg`
                : '—'
            }
            icon="🌾"
            loading={loadingProductionStats}
            subtitle="Último período reportado"
          />
          <KPICard
            title="Costos mensuales"
            value={`$ ${formatNumber(productionStats?.monthly_costs)}`}
            icon="💰"
            loading={loadingProductionStats}
          />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <div>
            <ProgressMetric
              label="Utilización de potreros"
              value={productionStats?.field_utilization ?? 0}
              suffix="%"
            />
          </div>
          <div>
            <ProgressMetric
              label="Índice de productividad"
              value={productionStats?.productivity_index ?? 0}
              suffix="%"
            />
          </div>
        </div>

        {/* Curva de peso promedio: aceleración del crecimiento */}
        {weightTrendSeries && (
          <div className="h-72 mt-6">
            <h3 className="text-sm font-semibold text-foreground mb-2">
              Tendencia de peso promedio (aceleración del crecimiento)
            </h3>
            <Line
              data={weightTrendSeries}
              options={{
                responsive: true,
                maintainAspectRatio: false,
                ...clickableChartOptions('/admin/controls'),
                plugins: {
                  legend: { position: 'bottom' },
                },
                scales: {
                  y: { beginAtZero: false },
                },
              }}
            />
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 gap-6">
        <RegulatoryReportsControl />
      </div>

      <div className="bg-card rounded-lg shadow p-6 mb-4">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-lg font-semibold text-foreground">Alertas críticas</h2>
          <span className="px-3 py-1 bg-red-100 text-red-800 text-sm font-medium rounded-full">
            {alerts?.alerts?.length || 0} activas
          </span>
        </div>

        {loadingAlerts ? (
          <div className="space-y-4">
            {[1, 2, 3].map((i) => (
              <div key={i} className="h-20 bg-muted rounded animate-pulse" />
            ))}
          </div>
        ) : alerts?.alerts && alerts.alerts.length > 0 ? (
          <div className="space-y-4">
            {alerts.alerts.map((alert: any, index: number) => (
              <AlertCard
                key={alert.id || index}
                alert={alert}
                onAction={(alert) => console.log('Action:', alert)}
              />
            ))}
          </div>
        ) : (
          <div className="text-center py-8 text-muted-foreground">
            <p className="text-4xl mb-2">✅</p>
            <p>No hay alertas críticas en este momento</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default DashboardExecutive;

import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { fieldService } from '@/entities/field/api/field.service';
import { useAnalytics } from '@/features/reporting/model/useAnalytics';
import FieldCard from '@/widgets/analytics/FieldCard';
import KPICard from '@/widgets/analytics/KPICard';
import FieldDetailsModal from '@/widgets/analytics/FieldDetailsModal';
import FieldAnalyticsModal from '@/widgets/analytics/FieldAnalyticsModal';
import { MagnifyingGlassIcon } from '@heroicons/react/24/outline';

/**
 * Página de gestión de potreros con analytics
 * Muestra métricas de ocupación y estado de cada potrero
 */
const FieldsPage: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedField, setSelectedField] = useState<any>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [analyticsField, setAnalyticsField] = useState<any>(null);
  const [isAnalyticsModalOpen, setIsAnalyticsModalOpen] = useState(false);

  // Obtener lista de potreros
  const { data: fieldsData, isLoading } = useQuery({
    queryKey: ['fields'],
    queryFn: async () => {
      return fieldService.getPaginated({ limit: 100 });
    },
  });

  // Obtener métricas de ocupación
  const { useFieldOccupation } = useAnalytics();
  const { data: occupation } = useFieldOccupation();

  const fields = fieldsData?.data || [];

  // Filtrar potreros por búsqueda
  const filteredFields = fields.filter(
    (field: any) =>
      field.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      field.ubication?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleViewDetails = (field: any) => {
    setSelectedField(field);
    setIsModalOpen(true);
  };

  const handleViewAnalytics = (field: any) => {
    setAnalyticsField(field);
    setIsAnalyticsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setTimeout(() => setSelectedField(null), 300); // Delay para animación
  };

  const handleCloseAnalyticsModal = () => {
    setIsAnalyticsModalOpen(false);
    setTimeout(() => setAnalyticsField(null), 300);
  };

  return (
    <div className="h-full overflow-auto bg-gray-50 p-6" tabIndex={0}>
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-900">Gestión de Potreros</h1>
        <p className="text-gray-600 mt-2">Administra y monitorea tus campos</p>
      </div>

      {/* Métricas Resumen */}
      {occupation && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
          <KPICard
            title="Capacidad Total"
            value={occupation.total_capacity || 0}
            icon="📊"
          />
          <KPICard
            title="Animales Ubicados"
            value={occupation.total_occupied || 0}
            icon="🐄"
          />
          <KPICard
            title="Ocupación Promedio"
            value={`${occupation.average_occupation || 0}%`}
            icon="📈"
          />
          <KPICard
            title="Espacios Disponibles"
            value={occupation.available_spots || 0}
            icon="✅"
          />
        </div>
      )}

      {/* Buscador */}
      <div className="mb-6">
        <div className="relative max-w-md">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <MagnifyingGlassIcon className="h-5 w-5 text-gray-400" />
          </div>
          <input
            type="text"
            placeholder="Buscar potreros..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="block w-full pl-10 pr-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          />
        </div>
      </div>

      {/* Grid de Potreros */}
      {isLoading ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {[1, 2, 3, 4, 5, 6].map((i) => (
            <div key={i} className="bg-white rounded-lg shadow p-6 animate-pulse">
              <div className="h-6 bg-gray-200 rounded w-3/4 mb-4"></div>
              <div className="h-4 bg-gray-200 rounded w-1/2 mb-6"></div>
              <div className="h-3 bg-gray-200 rounded mb-2"></div>
              <div className="h-12 bg-gray-200 rounded"></div>
            </div>
          ))}
        </div>
      ) : filteredFields.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredFields.map((field: any) => (
            <FieldCard
              key={field.id}
              field={field}
              onViewDetails={handleViewDetails}
              onViewAnalytics={handleViewAnalytics}
            />
          ))}
        </div>
      ) : (
        <div className="text-center py-12">
          <p className="text-gray-500 text-lg">
            {searchTerm
              ? `No se encontraron potreros que coincidan con "${searchTerm}"`
              : 'No hay potreros registrados'}
          </p>
        </div>
      )}

      {/* Estadísticas adicionales */}
      {occupation && occupation.fields && (
        <div className="mt-8 bg-white rounded-lg shadow p-6">
          <h2 className="text-lg font-semibold text-gray-900 mb-4">
            Distribución por Estado
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            {occupation.fields.map((fieldStat: any, index: number) => (
              <div
                key={index}
                className="p-4 bg-gray-50 rounded-lg border border-gray-200"
              >
                <h3 className="text-sm font-medium text-gray-600 mb-2">
                  {fieldStat.name}
                </h3>
                <div className="flex items-baseline justify-between">
                  <span className="text-2xl font-bold text-gray-900">
                    {fieldStat.occupied}
                  </span>
                  <span className="text-sm text-gray-500">
                    / {fieldStat.capacity}
                  </span>
                </div>
                <div className="mt-2 w-full bg-gray-200 rounded-full h-2">
                  <div
                    className={`h-2 rounded-full transition-all ${fieldStat.occupation_rate > 100
                        ? 'bg-red-500'
                        : fieldStat.occupation_rate > 80
                          ? 'bg-yellow-500'
                          : 'bg-green-500'
                      }`}
                    style={{
                      width: `${Math.min(fieldStat.occupation_rate, 100)}%`,
                    }}
                  />
                </div>
                <p className="text-xs text-gray-500 mt-1 text-right">
                  {fieldStat.occupation_rate.toFixed(0)}%
                </p>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Modal de Detalles */}
      <FieldDetailsModal
        field={selectedField}
        isOpen={isModalOpen}
        onClose={handleCloseModal}
      />

      {/* Modal de Analítica */}
      <FieldAnalyticsModal
        field={analyticsField}
        isOpen={isAnalyticsModalOpen}
        onClose={handleCloseAnalyticsModal}
      />
    </div>
  );
};

export default FieldsPage;

import React, { useState, useEffect, useCallback } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/shared/ui/card';
import { Button } from '@/shared/ui/button';
import { Badge } from '@/shared/ui/badge';
import { Input } from '@/shared/ui/input';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/shared/ui/table';
import { 
  ShieldCheck, 
  Search, 
  Download, 
  AlertTriangle, 
  CircleCheck, 
  CircleAlert,
  FileText,
  Filter,
  RefreshCw,
  Printer
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import analyticsService from '@/features/reporting/api/analytics.service';
import { useToast } from '@/app/providers/ToastContext';
import { CSVLink } from 'react-csv';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { cn } from '@/shared/ui/cn';

export default function ICADashboard() {
  const navigate = useNavigate();
  const { showToast } = useToast();
  const [loading, setLoading] = useState(true);
  const [isExporting, setIsExporting] = useState(false);
  const [data, setData] = useState<any>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filter, setFilter] = useState<'all' | 'red' | 'yellow' | 'green'>('all');

  const loadData = useCallback(async () => {
    setLoading(true);
    try {
      const response = await analyticsService.getHerdICAComplianceReport();
      setData(response);
    } catch (error) {
      console.error('Error loading ICA compliance:', error);
      showToast('Error al cargar reporte de cumplimiento', 'error');
    } finally {
      setLoading(false);
    }
  }, [showToast]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'green': return <CircleCheck className="w-5 h-5 text-emerald-500" />;
      case 'yellow': return <AlertTriangle className="w-5 h-5 text-amber-500" />;
      case 'red': return <CircleAlert className="w-5 h-5 text-rose-500" />;
      default: return null;
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'green': return <Badge className="bg-emerald-500/10 text-emerald-600 border-emerald-500/20 font-black uppercase text-[10px]">Al Día</Badge>;
      case 'yellow': return <Badge className="bg-amber-500/10 text-amber-600 border-amber-500/20 font-black uppercase text-[10px]">Revisar</Badge>;
      case 'red': return <Badge className="bg-rose-500/10 text-rose-600 border-rose-500/20 font-black uppercase text-[10px]">Vencido</Badge>;
      default: return null;
    }
  };

  const filteredAnimals = data?.animals?.filter((animal: any) => {
    const matchesSearch = animal.record.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          (animal.name && animal.name.toLowerCase().includes(searchTerm.toLowerCase()));
    const matchesFilter = filter === 'all' || animal.overall === filter;
    return matchesSearch && matchesFilter;
  }) || [];

  const exportToPDF = () => {
    setIsExporting(true);
    try {
      const doc = new jsPDF();
      
      // Wrapper de seguridad para autoTable en entornos ESM/Vite
      const runAutoTable = (docObj: any, options: any) => {
        try {
          if (typeof autoTable === 'function') {
            autoTable(docObj, options);
          } else if (typeof (autoTable as any).default === 'function') {
            (autoTable as any).default(docObj, options);
          } else if (typeof (docObj as any).autoTable === 'function') {
            (docObj as any).autoTable(options);
          } else {
            throw new Error('jspdf-autotable no está disponible como función.');
          }
        } catch (e) {
          console.error('Error en runAutoTable:', e);
          throw e;
        }
      };

      const pageWidth = doc.internal.pageSize.getWidth();
      const pageHeight = doc.internal.pageSize.getHeight();
      
      // --- CAPA DE DISEÑO PREMIUM (HEADER) ---
      // Bloque de color principal (Azul Profundo / Indigo)
      doc.setFillColor(30, 41, 59); 
      doc.rect(0, 0, pageWidth, 45, 'F');
      
      // Acento de color (Primary DevBrain)
      doc.setFillColor(79, 70, 229);
      doc.rect(0, 42, pageWidth, 3, 'F');
      
      doc.setTextColor(255, 255, 255);
      doc.setFontSize(24);
      doc.setFont('helvetica', 'bold');
      doc.text('REPORTE SANITARIO ICA', 20, 25);
      
      doc.setFontSize(9);
      doc.setFont('helvetica', 'normal');
      doc.setTextColor(200, 200, 200);
      doc.text(`ID DE REPORTE: DB-ICA-${new Date().getTime().toString().slice(-6)}`, 20, 34);
      doc.text(`FECHA DE EMISIÓN: ${new Date().toLocaleDateString('es-CO')} ${new Date().toLocaleTimeString('es-CO')}`, 20, 39);
      
      // Logo / Info Finca
      doc.setTextColor(255, 255, 255);
      doc.setFont('helvetica', 'bold');
      doc.text('FINCA VILLALUZ', pageWidth - 60, 25);
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(8);
      doc.text('Gestión Agropecuaria Inteligente', pageWidth - 60, 30);
      doc.text('Ecosistema Antigravity v5.0', pageWidth - 60, 34);

      // --- RESUMEN EJECUTIVO ---
      doc.setTextColor(30, 41, 59);
      doc.setFontSize(14);
      doc.setFont('helvetica', 'bold');
      doc.text('1. Resumen de Cumplimiento del Hato', 20, 60);
      
      const stats = [
        ['Total de Animales Auditados', String(data.total)],
        ['Cumplimiento Total (Al Día)', `${data.counts.green} (${(data.counts.green/data.total*100).toFixed(1)}%)`],
        ['Alertas Preventivas (Amarillo)', String(data.counts.yellow)],
        ['Vencimientos Cr¡ticos (Rojo)', String(data.counts.red)]
      ];

      runAutoTable(doc, {
        startY: 65,
        head: [['Parámetro de Control', 'Resultado']],
        body: stats,
        theme: 'striped',
        headStyles: { fillColor: [79, 70, 229], fontStyle: 'bold', halign: 'center' },
        styles: { fontSize: 10, cellPadding: 4 },
        columnStyles: { 1: { halign: 'center', fontStyle: 'bold' } }
      });

      // --- DETALLE GRANULAR ---
      const finalY_Stats = (doc as any).lastAutoTable?.finalY || 100;
      doc.setFontSize(14);
      doc.setFont('helvetica', 'bold');
      doc.text('2. Detalle Individual por Animal', 20, finalY_Stats + 15);

      const tableData = filteredAnimals.map((a: any) => [
        a.record,
        a.name || '---',
        a.overall === 'green' ? 'AL DÍA' : a.overall === 'yellow' ? 'PENDIENTE' : 'VENCIDO',
        a.checks.aftosa.status === 'ok' ? 'OK' : 'Falta',
        a.checks.brucelosis.status === 'ok' ? 'OK' : 'Falta',
        a.checks.clostridial.status === 'ok' ? 'OK' : 'Falta',
        a.checks.desparasitacion.status === 'ok' ? 'OK' : 'Falta'
      ]);

      runAutoTable(doc, {
        startY: finalY_Stats + 20,
        head: [['Registro', 'Nombre', 'Estado', 'Aftosa', 'Brucel.', 'Clostrid.', 'Despar.']],
        body: tableData,
        theme: 'grid',
        headStyles: { fillColor: [30, 41, 59], fontSize: 9, halign: 'center' },
        styles: { fontSize: 8, cellPadding: 3 },
        columnStyles: {
          2: { halign: 'center', fontStyle: 'bold' },
          3: { halign: 'center' },
          4: { halign: 'center' },
          5: { halign: 'center' },
          6: { halign: 'center' }
        },
        didParseCell: (dataCell: any) => {
          if (dataCell.section === 'body' && dataCell.column.index === 2) {
            const val = dataCell.cell.raw;
            if (val === 'AL DÍA') dataCell.cell.styles.textColor = [16, 185, 129];
            if (val === 'PENDIENTE') dataCell.cell.styles.textColor = [245, 158, 11];
            if (val === 'VENCIDO') dataCell.cell.styles.textColor = [239, 68, 68];
          }
        }
      });

      // --- VEREDICTO FINAL ---
      const finalY_Table = (doc as any).lastAutoTable?.finalY || 200;
      if (finalY_Table < pageHeight - 40) {
        doc.setFillColor(248, 250, 252);
        doc.rect(20, finalY_Table + 10, pageWidth - 40, 25, 'F');
        doc.setTextColor(71, 85, 105);
        doc.setFontSize(10);
        doc.setFont('helvetica', 'bold');
        doc.text('VEREDICTO SANITARIO:', 25, finalY_Table + 18);
        doc.setFont('helvetica', 'normal');
        const verdict = data.counts.red > 0 
          ? 'Se requieren acciones inmediatas de vacunación para el cumplimiento de normatividad ICA.' 
          : 'El hato se encuentra en condiciones óptimas de cumplimiento sanitario.';
        doc.text(verdict, 25, finalY_Table + 26);
      }

      // --- FOOTER CON NUMERACIàN ---
      const pageCount = (doc as any).internal.getNumberOfPages();
      for (let i = 1; i <= pageCount; i++) {
        doc.setPage(i);
        doc.setFontSize(8);
        doc.setTextColor(150, 150, 150);
        doc.text(`Página ${i} de ${pageCount}`, pageWidth / 2, pageHeight - 10, { align: 'center' });
        doc.text('Documento generado por el Ecosistema DevBrain. Validez legal según registros internos.', 20, pageHeight - 10);
      }

      doc.save(`VillaLuz_ICA_Report_${new Date().toISOString().split('T')[0]}.pdf`);
      showToast('Reporte Premium PDF generado', 'success');
    } catch (error) {
      console.error('Error generando PDF:', error);
      showToast('Error al generar PDF Premium', 'error');
    } finally {
      setIsExporting(false);
    }
  };

  const csvData = filteredAnimals.map((a: any) => ({
    'ID Animal': a.record,
    'Nombre': a.name || '---',
    'Sexo': a.sex,
    'Estado General': a.overall === 'green' ? 'Al Día' : a.overall === 'yellow' ? 'Revisar' : 'Vencido',
    'Aftosa': a.checks.aftosa.status === 'ok' ? 'OK' : a.checks.aftosa.days + 'd',
    'Brucelosis': a.checks.brucelosis.status === 'ok' ? 'OK' : a.checks.brucelosis.days + 'd',
    'Clostridial': a.checks.clostridial.status === 'ok' ? 'OK' : a.checks.clostridial.days + 'd',
    'Desparasitación': a.checks.desparasitacion.status === 'ok' ? 'OK' : a.checks.desparasitacion.days + 'd',
  }));

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-96 gap-4">
        <RefreshCw className="h-10 w-10 text-primary animate-spin" />
        <p className="text-sm font-black uppercase tracking-widest text-muted-foreground animate-pulse">Cargando datos ICA...</p>
      </div>
    );
  }

  return (
    <div className="space-y-8 pb-10">
      {/* Header Premium */}
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6 bg-card/40 backdrop-blur-xl p-8 rounded-[2.5rem] border border-border/50 shadow-2xl shadow-primary/5">
        <div className="flex items-center gap-5">
          <div className="h-16 w-16 rounded-[2rem] bg-primary flex items-center justify-center shadow-xl shadow-primary/20">
            <ShieldCheck className="h-8 w-8 text-white" />
          </div>
          <div>
            <h1 className="text-3xl font-black tracking-tighter text-foreground" id="ica-dashboard-title">
              Cumplimiento Sanitario <span className="text-primary">(ICA)</span>
            </h1>
            <p className="text-muted-foreground font-medium">Auditoría de salud y requisitos legales del hato</p>
          </div>
        </div>
        
        <div className="flex flex-wrap items-center gap-3 w-full lg:w-auto" role="toolbar" aria-label="Acciones de reporte">
          {data && (
            <>
              <CSVLink 
                data={csvData} 
                filename={`reporte-ica-${new Date().toISOString().split('T')[0]}.csv`}
                aria-label="Descargar reporte en formato CSV"
              >
                <Button variant="outline" className="rounded-2xl h-12 gap-2 border-dashed hover:border-solid transition-all">
                  <Download className="h-4 w-4" aria-hidden="true" />
                  CSV
                </Button>
              </CSVLink>
              <Button 
                onClick={exportToPDF} 
                disabled={isExporting}
                aria-label={isExporting ? "Generando PDF, por favor espere" : "Generar reporte premium en PDF"}
                className="rounded-2xl h-12 gap-2 bg-foreground text-background hover:bg-foreground/90 transition-all shadow-xl shadow-black/10"
              >
                {isExporting ? <RefreshCw className="h-4 w-4 animate-spin" aria-hidden="true" /> : <FileText className="h-4 w-4" aria-hidden="true" />}
                Reporte PDF
              </Button>
              <Button 
                variant="ghost" 
                className="h-12 w-12 rounded-2xl border border-border/50"
                aria-label="Imprimir vista actual"
              >
                <Printer className="h-5 w-5" aria-hidden="true" />
              </Button>
            </>
          )}
        </div>
      </div>

      {/* Stats Cards Premium */}
      {data && (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          <Card className="border-none shadow-xl shadow-primary/5 bg-card/50 backdrop-blur-xl rounded-[2rem] overflow-hidden group">
            <CardHeader className="pb-2">
              <CardDescription className="font-bold uppercase tracking-widest text-[10px]">Hato Total</CardDescription>
              <CardTitle className="text-4xl font-black">{data.total}</CardTitle>
            </CardHeader>
            <div className="h-1.5 w-full bg-muted mt-4">
              <div className="h-full bg-primary w-full" />
            </div>
          </Card>
          
          <Card 
            className={cn(
              "border-none shadow-xl shadow-emerald-500/5 bg-emerald-500/5 backdrop-blur-xl rounded-[2rem] overflow-hidden cursor-pointer transition-all hover:scale-[1.02]",
              filter === 'green' && "ring-2 ring-emerald-500/50"
            )}
            onClick={() => setFilter('green')}
            role="button"
            aria-pressed={filter === 'green'}
            tabIndex={0}
            aria-label={`Filtrar animales al d¡a: ${data.counts.green}`}
            onKeyDown={(e) => e.key === 'Enter' && setFilter('green')}
          >
            <CardHeader className="pb-2">
              <CardDescription className="font-bold uppercase tracking-widest text-[10px] text-emerald-600">Al D¡a</CardDescription>
              <CardTitle className="text-4xl font-black text-emerald-600">{data.counts.green}</CardTitle>
            </CardHeader>
            <div className="h-1.5 w-full bg-emerald-500/10 mt-4" role="progressbar" aria-valuenow={(data.counts.green / data.total * 100)} aria-valuemin={0} aria-valuemax={100}>
              <div className="h-full bg-emerald-500 transition-all duration-1000" style={{ width: `${(data.counts.green / data.total * 100)}%` }} />
            </div>
          </Card>
          
          <Card 
            className={cn(
              "border-none shadow-xl shadow-amber-500/5 bg-amber-500/5 backdrop-blur-xl rounded-[2rem] overflow-hidden cursor-pointer transition-all hover:scale-[1.02]",
              filter === 'yellow' && "ring-2 ring-amber-500/50"
            )}
            onClick={() => setFilter('yellow')}
            role="button"
            aria-pressed={filter === 'yellow'}
            tabIndex={0}
            aria-label={`Filtrar animales por revisar: ${data.counts.yellow}`}
            onKeyDown={(e) => e.key === 'Enter' && setFilter('yellow')}
          >
            <CardHeader className="pb-2">
              <CardDescription className="font-bold uppercase tracking-widest text-[10px] text-amber-600">Revisar</CardDescription>
              <CardTitle className="text-4xl font-black text-amber-600">{data.counts.yellow}</CardTitle>
            </CardHeader>
            <div className="h-1.5 w-full bg-amber-500/10 mt-4" role="progressbar" aria-valuenow={(data.counts.yellow / data.total * 100)} aria-valuemin={0} aria-valuemax={100}>
              <div className="h-full bg-amber-500 transition-all duration-1000" style={{ width: `${(data.counts.yellow / data.total * 100)}%` }} />
            </div>
          </Card>
          
          <Card 
            className={cn(
              "border-none shadow-xl shadow-rose-500/5 bg-rose-500/5 backdrop-blur-xl rounded-[2rem] overflow-hidden cursor-pointer transition-all hover:scale-[1.02]",
              filter === 'red' && "ring-2 ring-rose-500/50"
            )}
            onClick={() => setFilter('red')}
            role="button"
            aria-pressed={filter === 'red'}
            tabIndex={0}
            aria-label={`Filtrar animales vencidos: ${data.counts.red}`}
            onKeyDown={(e) => e.key === 'Enter' && setFilter('red')}
          >
            <CardHeader className="pb-2">
              <CardDescription className="font-bold uppercase tracking-widest text-[10px] text-rose-600">Vencidos</CardDescription>
              <CardTitle className="text-4xl font-black text-rose-600">{data.counts.red}</CardTitle>
            </CardHeader>
            <div className="h-1.5 w-full bg-rose-500/10 mt-4" role="progressbar" aria-valuenow={(data.counts.red / data.total * 100)} aria-valuemin={0} aria-valuemax={100}>
              <div className="h-full bg-rose-500 transition-all duration-1000" style={{ width: `${(data.counts.red / data.total * 100)}%` }} />
            </div>
          </Card>
        </div>
      )}

      {/* Main Table Card */}
      <Card className="border-none shadow-2xl shadow-primary/5 bg-card/40 backdrop-blur-xl rounded-[2.5rem] overflow-hidden">
        <CardHeader className="p-8 border-b border-border/30">
          <div className="flex flex-col lg:flex-row items-center justify-between gap-6">
            <div>
              <CardTitle className="text-xl font-black tracking-tight">Listado de Cumplimiento</CardTitle>
              <CardDescription className="font-medium">Detalle granular por animal y tipo de control</CardDescription>
            </div>
            <div className="flex items-center gap-4 w-full lg:w-auto">
              <div className="relative flex-1 lg:w-80">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Buscar animal o registro..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-11 h-12 bg-background/50 border-border/50 rounded-2xl focus:ring-primary/20"
                />
              </div>
              <Button 
                variant="outline" 
                className={cn(
                  "h-12 w-12 rounded-2xl p-0 transition-all",
                  filter !== 'all' && "bg-primary/10 border-primary text-primary"
                )}
                onClick={() => setFilter('all')}
              >
                <Filter className="h-5 w-5" />
              </Button>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          <div className="overflow-x-auto scrollbar-thin">
            <Table>
              <TableHeader className="bg-muted/30">
                <TableRow className="hover:bg-transparent border-none">
                  <TableHead className="w-16"></TableHead>
                  <TableHead className="font-black uppercase text-[10px] tracking-widest text-muted-foreground">Animal</TableHead>
                  <TableHead className="font-black uppercase text-[10px] tracking-widest text-muted-foreground">Sexo</TableHead>
                  <TableHead className="font-black uppercase text-[10px] tracking-widest text-muted-foreground">Estado Global</TableHead>
                  <TableHead className="text-center font-black uppercase text-[10px] tracking-widest text-muted-foreground">Aftosa</TableHead>
                  <TableHead className="text-center font-black uppercase text-[10px] tracking-widest text-muted-foreground">Brucel.</TableHead>
                  <TableHead className="text-center font-black uppercase text-[10px] tracking-widest text-muted-foreground">Clostrid.</TableHead>
                  <TableHead className="text-center font-black uppercase text-[10px] tracking-widest text-muted-foreground">Despar.</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredAnimals.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={8} className="text-center py-20">
                      <div className="flex flex-col items-center gap-3 opacity-40">
                        <Search className="h-12 w-12" />
                        <p className="font-black uppercase tracking-widest text-xs">Sin resultados para la búsqueda</p>
                      </div>
                    </TableCell>
                  </TableRow>
                ) : (
                  filteredAnimals.map((animal: any) => (
                    <TableRow 
                      key={animal.animal_id} 
                      className="group cursor-pointer hover:bg-primary/[0.02] border-b border-border/30 last:border-0 transition-colors" 
                      onClick={() => navigate(`/admin/animals?edit=${animal.animal_id}`)}
                    >
                      <TableCell className="pl-8">{getStatusIcon(animal.overall)}</TableCell>
                      <TableCell>
                        <div className="font-black text-sm text-foreground group-hover:text-primary transition-colors">{animal.record}</div>
                        {animal.name && <div className="text-[10px] font-bold text-muted-foreground uppercase">{animal.name}</div>}
                      </TableCell>
                      <TableCell>
                        <Badge variant="ghost" className="text-[10px] font-bold bg-muted/50">{animal.sex}</Badge>
                      </TableCell>
                      <TableCell>{getStatusBadge(animal.overall)}</TableCell>
                      
                      {['aftosa', 'brucelosis', 'clostridial', 'desparasitacion'].map(check => {
                        const info = animal.checks[check];
                        let colorClass = 'bg-slate-200';
                        if (info.status === 'ok') colorClass = 'bg-emerald-500 shadow-emerald-500/50';
                        else if (info.status === 'due_soon') colorClass = 'bg-amber-400 shadow-amber-400/50';
                        else if (info.status === 'missing') colorClass = 'bg-slate-300';
                        else if (info.status === 'overdue') colorClass = 'bg-rose-500 shadow-rose-500/50';
                        
                        return (
                          <TableCell key={check} className="text-center">
                            <div className="flex flex-col items-center justify-center gap-1.5">
                              <div 
                                className={cn(
                                  "w-2.5 h-2.5 rounded-full shadow-lg transition-transform group-hover:scale-125",
                                  colorClass
                                )} 
                                title={info.status}
                              />
                              {info.days !== null && (
                                <span className={cn(
                                  "text-[9px] font-black tracking-tighter uppercase",
                                  info.status === 'overdue' ? 'text-rose-500' : 'text-muted-foreground'
                                )}>
                                  {info.days}d
                                </span>
                              )}
                            </div>
                          </TableCell>
                        );
                      })}
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </div>
        </CardContent>
        <div className="p-6 bg-muted/30 border-t border-border/30 text-center">
          <p className="text-[10px] font-black text-muted-foreground/60 uppercase tracking-[0.2em]">VillaLuz Intelligence Reporting System v4.2</p>
        </div>
      </Card>
    </div>
  );
}

import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { BuildingOffice2Icon, ChartBarIcon } from '@heroicons/react/24/outline';
import { apiFetch } from '@/shared/api/apiFetch';
import { unwrapApi } from '@/shared/api/client';

const MultiFincaAnalytics = () => {
  const { data: fincas, isLoading, error } = useQuery({
    queryKey: ['multi_finca_compare'],
    queryFn: async () => {
      const res = await apiFetch({ url: '/multi-finca/compare-kpis' } as any);
      return unwrapApi(res);
    },
  });

  if (isLoading) {
    return <div className="p-6 text-center text-gray-500">Cargando métricas multi-finca...</div>;
  }

  if (error || !fincas) {
    return <div className="p-6 text-center text-red-500">Error cargando KPIs comparativos.</div>;
  }

  // Encontrar el máximo para graficar barras relativas
  const maxAnimals = Math.max(...fincas.map((f: any) => f.kpis.total_animals), 1);
  const maxMilk = Math.max(...fincas.map((f: any) => f.kpis.total_milk_liters), 1);

  return (
    <div className="p-6 h-full overflow-auto bg-gray-50">
      <div className="mb-8">
        <div className="flex items-center gap-3 mb-2">
          <BuildingOffice2Icon className="w-8 h-8 text-indigo-600" />
          <h1 className="text-3xl font-bold text-gray-900">Analítica Multi-Finca</h1>
        </div>
        <p className="text-gray-600">
          Compara el rendimiento y los inventarios entre todas tus fincas activas.
        </p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Gráfico 1: Inventario de Animales */}
        <div className="bg-white rounded-xl shadow p-6">
          <div className="flex items-center gap-2 mb-6">
            <ChartBarIcon className="w-6 h-6 text-blue-500" />
            <h2 className="text-xl font-bold text-gray-900">Total Animales Activos</h2>
          </div>
          <div className="space-y-6">
            {fincas.map((finca: any) => (
              <div key={`anim-${finca.finca_id}`}>
                <div className="flex justify-between text-sm font-medium mb-1">
                  <span className="text-gray-700">{finca.finca_name}</span>
                  <span className="text-blue-600">{finca.kpis.total_animals} cabezas</span>
                </div>
                <div className="w-full bg-gray-200 rounded-full h-3">
                  <div 
                    className="bg-blue-500 h-3 rounded-full transition-all duration-1000"
                    style={{ width: `${(finca.kpis.total_animals / maxAnimals) * 100}%` }}
                  ></div>
                </div>
              </div>
            ))}
            {fincas.length === 0 && <p className="text-gray-500 text-sm">No hay fincas para comparar.</p>}
          </div>
        </div>

        {/* Gráfico 2: Producción de Leche */}
        <div className="bg-white rounded-xl shadow p-6">
          <div className="flex items-center gap-2 mb-6">
            <ChartBarIcon className="w-6 h-6 text-sky-500" />
            <h2 className="text-xl font-bold text-gray-900">Producción Histórica de Leche</h2>
          </div>
          <div className="space-y-6">
            {fincas.map((finca: any) => (
              <div key={`milk-${finca.finca_id}`}>
                <div className="flex justify-between text-sm font-medium mb-1">
                  <span className="text-gray-700">{finca.finca_name}</span>
                  <span className="text-sky-600">{finca.kpis.total_milk_liters.toLocaleString('es-CO')} Litros</span>
                </div>
                <div className="w-full bg-gray-200 rounded-full h-3">
                  <div 
                    className="bg-sky-400 h-3 rounded-full transition-all duration-1000"
                    style={{ width: `${(finca.kpis.total_milk_liters / maxMilk) * 100}%` }}
                  ></div>
                </div>
              </div>
            ))}
             {fincas.length === 0 && <p className="text-gray-500 text-sm">No hay fincas para comparar.</p>}
          </div>
        </div>
      </div>
      
      {/* Resumen Tabular */}
      <div className="mt-8 bg-white rounded-xl shadow overflow-hidden">
        <div className="p-6 border-b border-gray-200">
          <h2 className="text-xl font-bold text-gray-900">Tabla Comparativa</h2>
        </div>
        <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-gray-50 text-sm font-medium text-gray-500 border-b">
                <th className="px-6 py-4">Finca</th>
                <th className="px-6 py-4 text-right">Animales</th>
                <th className="px-6 py-4 text-right">Leche Total (L)</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 text-sm">
              {fincas.map((f: any) => (
                <tr key={f.finca_id} className="hover:bg-gray-50">
                  <td className="px-6 py-4 font-medium text-gray-900">{f.finca_name}</td>
                  <td className="px-6 py-4 text-right font-medium">{f.kpis.total_animals}</td>
                  <td className="px-6 py-4 text-right font-medium text-sky-600">{f.kpis.total_milk_liters.toLocaleString('es-CO')}</td>
                </tr>
              ))}
            </tbody>
          </table>
      </div>
    </div>
  );
};

export default MultiFincaAnalytics;

import React, { useMemo } from 'react';
import { useSearchParams } from 'react-router-dom';
import { AdminCRUDPage } from '@/widgets/admin-crud';
import { CRUDColumn, CRUDFormSection, CRUDConfig } from '@/shared/types/crud';
import { animalDiseasesService } from '@/entities/animal-disease/api/animalDiseases.service';
import { animalsService } from '@/entities/animal/api/animal.service';
import { diseaseService } from '@/entities/disease/api/disease.service';
import { usersService } from '@/entities/user/api/user.service';
import { ANIMAL_DISEASE_STATUSES } from '@/shared/constants/enums';
import type { AnimalDiseaseResponse, AnimalDiseaseInput } from '@/shared/api/generated/swaggerTypes';
import { getTodayColombia } from '@/shared/utils/dateUtils';
import { AnimalLink } from '@/entities/animal/ui';
import { DiseaseLink } from '@/entities/disease/ui';
import { UserLink } from '@/entities/user/ui';
import { useForeignKeySelect } from '@/shared/hooks/useForeignKeySelect';

function AdminAnimalDiseasesPage() {
  const [searchParams] = useSearchParams();
  const preselectedUserId = searchParams.get('user_id');

  const { options: animalOptions, loading: animalLoading } = useForeignKeySelect(
    (p) => animalsService.getAnimals(p),
    (a) => ({ value: a.id, label: a.record || `ID ${a.id}` })
  );

  const { options: diseaseOptions, loading: diseaseLoading } = useForeignKeySelect(
    (p) => diseaseService.getDiseases(p),
    (d) => ({ value: d.id, label: d.disease || d.name || `Enfermedad ${d.id}` })
  );

  const { options: instructorOptions, loading: instructorLoading } = useForeignKeySelect(
    (p) => usersService.getUsers(p),
    (u) => ({ value: u.id, label: u.fullname || u.name || `Usuario ${u.id}` })
  );

  // Crear mapas de búsqueda optimizados
  const animalMap = useMemo(() => {
    const map = new Map<number | string, string>();
    animalOptions.forEach(opt => map.set(opt.value, opt.label));
    return map;
  }, [animalOptions]);

  const diseaseMap = useMemo(() => {
    const map = new Map<number | string, string>();
    diseaseOptions.forEach(opt => map.set(opt.value, opt.label));
    return map;
  }, [diseaseOptions]);

  const instructorMap = useMemo(() => {
    const map = new Map<number | string, string>();
    instructorOptions.forEach(opt => map.set(opt.value, opt.label));
    return map;
  }, [instructorOptions]);

  // Columnas de la tabla con renderizado optimizado y Foreign Key Links
  const columns: CRUDColumn<AnimalDiseaseResponse & { [k: string]: any }>[] = useMemo(() => [
    { key: 'id', label: 'ID', render: (v) => v ?? '-', hiddenOnMobile: true },

    {
      key: 'animal_id',
      label: 'Animal',
      render: (v) => {
        if (!v) return '-';
        const id = Number(v);
        const label = animalMap.get(id) || `Animal ${id}`;
        return <AnimalLink id={id} label={label} />;
      }
    },
    {
      key: 'disease_id',
      label: 'Enfermedad',
      render: (v) => {
        if (!v) return '-';
        const id = Number(v);
        const label = diseaseMap.get(id) || `Enfermedad ${id}`;
        return <DiseaseLink id={id} label={label} />;
      }
    },
    {
      key: 'instructor_id',
      label: 'Instructor',
      render: (v) => {
        if (!v) return '-';
        const id = Number(v);
        const label = instructorMap.get(id) || `Instructor ${id}`;
        return <UserLink id={id} label={label} role="Instructor" />;
      },
      hiddenOnMobile: true
    },
    { key: 'diagnosis_date', label: 'Diagn¢stico', render: (v) => (v ? new Date(v as string).toLocaleDateString('es-ES') : '-'), hiddenOnMobile: true },
    { key: 'status', label: 'Estado', render: (v) => v || '-' },
    { key: 'notes' as any, label: 'Notas', render: (v) => v || '-', hiddenOnMobile: true },
    { key: 'created_at' as any, label: 'Creado', render: (v) => (v ? new Date(v as string).toLocaleDateString('es-ES') : '-'), hiddenOnMobile: true },
    { key: 'updated_at' as any, label: 'Actualizado', render: (v) => (v ? new Date(v as string).toLocaleDateString('es-ES') : '-'), hiddenOnMobile: true },
  ], [animalMap, diseaseMap, instructorMap]);

  const formSections: CRUDFormSection<AnimalDiseaseInput & { [k: string]: any }>[] = [
    {
      title: 'Información Básica',
      gridCols: 2,
      fields: [
        { name: 'animal_id' as any, label: 'Animal', type: 'select', required: true, options: animalOptions, placeholder: 'Seleccionar animal', loading: animalLoading },
        { name: 'disease_id' as any, label: 'Enfermedad', type: 'select', required: true, options: diseaseOptions, placeholder: 'Seleccionar enfermedad', loading: diseaseLoading },
        { name: 'instructor_id' as any, label: 'Instructor', type: 'select', required: true, options: instructorOptions, placeholder: 'Seleccionar instructor', loading: instructorLoading },
        { name: 'diagnosis_date' as any, label: 'Fecha de Diagnóstico', type: 'date', required: true },
        { name: 'status' as any, label: 'Estado', type: 'select', options: ANIMAL_DISEASE_STATUSES as any, placeholder: 'Seleccionar estado', colSpan: 2 },
        { name: 'notes' as any, label: 'Notas', type: 'textarea', placeholder: 'Observaciones', colSpan: 2 },
      ],
    },
  ];

  const crudConfig: CRUDConfig<AnimalDiseaseResponse & { [k: string]: any }, AnimalDiseaseInput & { [k: string]: any }> = {
    title: 'Enfermedades de Animales',
    entityName: 'Enfermedad de animal',
    columns,
    formSections,
    searchPlaceholder: 'Buscar enfermedades de animales...',
    emptyStateMessage: 'No hay enfermedades de animales registradas.',
    emptyStateDescription: 'Crea el primer registro para comenzar.',
    enableDetailModal: true,
    enableCreateModal: true,
    enableEditModal: true,
    enableDelete: true,
  };

  // Crear initialFormData con usuario preseleccionado si existe
  const dynamicInitialFormData = useMemo(() => ({
    ...initialFormData,
    instructor_id: preselectedUserId ? Number(preselectedUserId) : undefined as any,
  }), [preselectedUserId]);

  // Opciones de configuración de AdminCRUDPage

  return (
    <AdminCRUDPage
      config={crudConfig}
      service={animalDiseasesService}
      initialFormData={dynamicInitialFormData}
      mapResponseToForm={mapResponseToForm}
      validateForm={validateForm}
      additionalFormContent={(_formData, editingItem) => {
        if (!editingItem) return null;
        return (
          <div className="mt-4 rounded-lg border border-border/50 bg-muted/20 p-3 text-xs sm:text-sm">
            <div className="grid grid-cols-1 gap-2 sm:grid-cols-3">
              <div><span className="font-semibold">ID:</span> {editingItem.id}</div>
              <div><span className="font-semibold">Creado:</span> {editingItem.created_at ? new Date(editingItem.created_at as any).toLocaleString("es-ES") : "-"}</div>
              <div><span className="font-semibold">Actualizado:</span> {editingItem.updated_at ? new Date(editingItem.updated_at as any).toLocaleString("es-ES") : "-"}</div>
            </div>
          </div>
        );
      }}
      realtime={true}
      pollIntervalMs={0}
      refetchOnFocus={false}
      refetchOnReconnect={true}
      cache={true}
      cacheTTL={300000}
      enhancedHover={true}
    />
  );
}

export default AdminAnimalDiseasesPage;

// Mapear respuesta a formulario
const mapResponseToForm = (item: AnimalDiseaseResponse & { [k: string]: any }): AnimalDiseaseInput & { [k: string]: any } => ({
  animal_id: item.animal_id,
  disease_id: item.disease_id,
  instructor_id: item.instructor_id,
  diagnosis_date: item.diagnosis_date,
  status: item.status,
  notes: item.notes || '',
});

// Validación
const validateForm = (formData: AnimalDiseaseInput & { [k: string]: any }): string | null => {
  // Validar animal_id: debe ser un número válido > 0
  const animalId = Number(formData.animal_id);
  if (!formData.animal_id || Number.isNaN(animalId) || animalId <= 0) {
    return '⚠️ Debe seleccionar un animal válido.';
  }

  // Validar disease_id: debe ser un número válido > 0
  const diseaseId = Number(formData.disease_id);
  if (!formData.disease_id || Number.isNaN(diseaseId) || diseaseId <= 0) {
    return '⚠️ Debe seleccionar una enfermedad válida.';
  }

  // Validar instructor_id: debe ser un número válido > 0
  const instructorId = Number(formData.instructor_id);
  if (!formData.instructor_id || Number.isNaN(instructorId) || instructorId <= 0) {
    return '⚠️ Debe seleccionar un instructor válido.';
  }

  if (!formData.diagnosis_date) return 'La fecha de diagnóstico es obligatoria.';
  return null;
};

// Datos iniciales
const initialFormData: AnimalDiseaseInput & { [k: string]: any } = {
  animal_id: undefined as any, // Forzar que el usuario seleccione
  disease_id: undefined as any, // Forzar que el usuario seleccione
  instructor_id: undefined as any, // Forzar que el usuario seleccione
  diagnosis_date: getTodayColombia(),
  status: ANIMAL_DISEASE_STATUSES[0]?.value ?? 'Activo',
  notes: '',
};

import React, { useMemo } from 'react';
import { AdminCRUDPage } from '@/widgets/admin-crud';
import { CRUDColumn, CRUDFormSection, CRUDConfig } from '@/shared/types/crud';
import { animalFieldsService } from '@/entities/animal-field/api/animalFields.service';
