// Mapear respuesta a formulario
const mapResponseToForm = (item: AnimalFieldResponse & { [k: string]: any }): AnimalFieldInput & { [k: string]: any } => ({
  animal_id: item.animal_id,
  field_id: item.field_id,
  assignment_date: item.assignment_date,
  removal_date: item.removal_date,
  notes: item.notes || '',
});

// Validación
const validateForm = (formData: AnimalFieldInput & { [k: string]: any }): string | null => {
  // Validar animal_id: debe ser un número válido > 0
  const animalId = Number(formData.animal_id);
  if (!formData.animal_id || Number.isNaN(animalId) || animalId <= 0) {
    return '⚠️ Debe seleccionar un animal válido.';
  }

  // Validar field_id: debe ser un número válido > 0
  const fieldId = Number(formData.field_id);
  if (!formData.field_id || Number.isNaN(fieldId) || fieldId <= 0) {
    return '⚠️ Debe seleccionar un campo válido.';
  }

  if (!formData.assignment_date) return 'La fecha de asignación es obligatoria.';

  // Validación adicional: la fecha de retiro no puede ser anterior a la de asignación
  if (formData.removal_date && formData.assignment_date) {
    const assignmentDate = new Date(formData.assignment_date);
    const removalDate = new Date(formData.removal_date);
    if (removalDate < assignmentDate) {
      return 'La fecha de retiro no puede ser anterior a la fecha de asignación.';
    }
  }

  return null;
};

// Datos iniciales
const initialFormData: AnimalFieldInput & { [k: string]: any } = {
  animal_id: undefined as any, // Forzar que el usuario seleccione
  field_id: undefined as any, // Forzar que el usuario seleccione
  assignment_date: getTodayColombia(),
  removal_date: undefined,
  notes: '',
};

import { getTodayColombia } from '@/shared/utils/dateUtils';
import type { AnimalResponse, AnimalInput } from '@/shared/api/generated/swaggerTypes';
import { ANIMAL_GENDERS } from '@/shared/constants/enums';

const ANIMAL_STATUS_OPTIONS = [
  { value: 'Vivo', label: 'Vivo' },
  { value: 'Vendido', label: 'Vendido' },
  { value: 'Muerto', label: 'Muerto' },
] as const;

const normalizeGender = (value: unknown): AnimalInput['gender'] | undefined => {
  if (value === null || value === undefined) return undefined;
  const normalized = String(value).trim().toLowerCase();
  let mapped: AnimalInput['gender'] | undefined;
  if (['m', 'macho', 'male'].includes(normalized)) mapped = 'Macho';
  if (['f', 'hembra', 'female'].includes(normalized)) mapped = 'Hembra';
  if (['c', 'castrado', 'castrated'].includes(normalized)) mapped = 'Castrado';
  if (!mapped) return undefined;
  return ANIMAL_GENDERS.some((opt) => opt.value === mapped) ? mapped : undefined;
};

const normalizeStatus = (value: unknown): string | undefined => {
  if (value === null || value === undefined) return undefined;
  const normalized = String(value).trim().toLowerCase();
  let mapped: string | undefined;
  if (['vivo', 'activo', 'sano'].includes(normalized)) mapped = 'Vivo';
  if (['vendido', 'sold'].includes(normalized)) mapped = 'Vendido';
  if (['muerto', 'fallecido', 'dead'].includes(normalized)) mapped = 'Muerto';
  if (!mapped) return undefined;
  return ANIMAL_STATUS_OPTIONS.some((opt) => opt.value === mapped) ? mapped : undefined;
};

const toNumber = (value: unknown): number | undefined => {
  if (value === null || value === undefined || value === '') return undefined;
  const num = Number(value);
  return Number.isNaN(num) ? undefined : num;
};

// Mapear respuesta del backend al formulario
const mapResponseToForm = (item: AnimalResponse & { [k: string]: any }): Partial<AnimalInput> => {
  const status = normalizeStatus(item.status ?? item.estado) || 'Vivo';
  return {
    record: item.record || item.code || item.registro || '',
    birth_date: item.birth_date || item.birthDate || item.fecha_nacimiento,
    weight: toNumber(item.weight ?? item.peso),
    breed_id: toNumber(item.breeds_id ?? item.breed_id ?? item.breedId ?? item.raza_id),
    gender: normalizeGender(item.sex ?? item.gender ?? item.sexo ?? item.genero),
    status: status as any,
    father_id: toNumber(item.idFather ?? item.father_id ?? item.padre_id ?? item.fatherId),
    mother_id: toNumber(item.idMother ?? item.mother_id ?? item.madre_id ?? item.motherId),
    notes: item.notes ?? item.observations ?? item.observaciones ?? '',
    entry_date: item.entry_date,
    purchase_date: item.purchase_date,
    sale_date: item.sale_date,
    exit_date: item.exit_date,
    exit_reason: item.exit_reason || '',
  };
};

// Validación mejorada con advertencias y recomendaciones
const validateForm = (formData: Partial<AnimalInput>): string | null => {
  if (!formData.record || !formData.record.trim()) {
    return '⚠️ El registro es obligatorio. Ejemplo: REC0001, BOV001, etc.';
  }

  if (!formData.birth_date) {
    return '⚠️ La fecha de nacimiento es obligatoria para calcular la edad del animal.';
  }

  // Validar que la fecha de nacimiento no sea futura
  const birthDate = new Date(formData.birth_date);
  const today = new Date();
  if (birthDate > today) {
    return '⚠️ La fecha de nacimiento no puede ser futura. Verifique la fecha ingresada.';
  }

  // Advertir si el animal es muy viejo (más de 20 años)
  const yearsDiff = (today.getTime() - birthDate.getTime()) / (1000 * 60 * 60 * 24 * 365);
  if (yearsDiff > 20) {
    return '⚠️ La fecha de nacimiento indica que el animal tendría más de 20 años. ¿Es correcta esta fecha?';
  }

  const breedNum = Number(formData.breed_id);
  if (formData.breed_id == null || Number.isNaN(breedNum) || breedNum <= 0) {
    return '⚠️ Debe seleccionar una raza. La raza es importante para el seguimiento genético.';
  }

  if (!formData.gender) {
    return '⚠️ El sexo del animal es obligatorio.';
  }

  // Validar peso (requerido por el backend)
  if (formData.weight === undefined || formData.weight === null) {
    return '⚠️ El peso del animal es obligatorio.';
  }

  const weightNum = Number(formData.weight);
  if (Number.isNaN(weightNum) || weightNum <= 0) {
    return '⚠️ El peso debe ser un valor positivo mayor a 0 kg.';
  }

  if (weightNum > 2000) {
    return '⚠️ El peso parece excesivo (>2000 kg). Verifique el valor ingresado.';
  }

  // Advertir si se selecciona el mismo animal como padre y madre
  if (formData.father_id && formData.mother_id && formData.father_id === formData.mother_id) {
    return '⚠️ No puede seleccionar el mismo animal como padre y madre.';
  }

  return null;
};

// Datos iniciales
const initialFormData: Partial<AnimalInput> = {
  record: '',
  birth_date: getTodayColombia(),
  weight: undefined, // Requerido: será validado antes de enviar
  breed_id: undefined as any, // Forzar que el usuario seleccione
  gender: 'Macho',
  status: 'Vivo' as any,
  father_id: undefined,
  mother_id: undefined,
  notes: '',
};

export {
  ANIMAL_STATUS_OPTIONS,
  normalizeGender,
  normalizeStatus,
  toNumber,
  mapResponseToForm,
  validateForm,
  initialFormData
};

import { useEffect, useState } from 'react';
import { useForm, FieldError } from 'react-hook-form';
import { useNavigate, useParams } from 'react-router-dom';
import { animalsService } from '@/entities/animal/api/animal.service';
import { breedsService } from '@/entities/breed/api/breeds.service';
import { useSpecies } from '@/entities/species/model/useSpecies';
import { Combobox } from '@/shared/ui/combobox';
import { Plus, Edit } from 'lucide-react';
import { getTodayColombia } from '@/shared/utils/dateUtils';

type AnimalStatus = 'Sano' | 'Enfermo' | 'En tratamiento' | 'En observación' | 'Cuarentena' | 'Vendido' | 'Fallecido';
type AnimalGender = 'Macho' | 'Hembra' | 'Castrado';
type AnimalFormFields = {
  // eliminado: name
  species_id: number;
  breed_id: number;
  record: string;
  birth_date: string;
  weight: number;
  gender: AnimalGender;
  status: AnimalStatus;
  notes?: string;
  entry_date?: string;
  purchase_date?: string;
  sale_date?: string;
  exit_date?: string;
  exit_reason?: string;
};

export default function AnimalForm() {
  const { id } = useParams<{ id?: string }>();
  const navigate = useNavigate();
  const { register, handleSubmit, setValue, formState: { errors, isSubmitting } } = useForm<AnimalFormFields>();
  
  // Cargar especies disponibles
  const { species } = useSpecies();
  
  // Estado para razas filtradas por especie
  const [breeds, setBreeds] = useState<any[]>([]);
  const [selectedSpeciesId, setSelectedSpeciesId] = useState<number | null>(null);
  const [selectedBreedId, setSelectedBreedId] = useState<number | null>(null);
  const [loadingBreeds, setLoadingBreeds] = useState(false);

  useEffect(() => {
    if (id) {
      animalsService.getAnimalById(Number(id)).then((animal: any) => {
        // eliminado: setValue('name', animal.name)
        setValue('species_id', animal.species_id);
        setSelectedSpeciesId(animal.species_id);
        setValue('breed_id', animal.breed_id);
        setSelectedBreedId(animal.breed_id);
        // Mapear estado del detalle a opciones válidas del formulario
        const s = String(animal.status || '').toLowerCase();
        const mappedStatus: AnimalStatus = s === 'sano' ? 'Sano'
          : s === 'enfermo' ? 'Enfermo'
          : s === 'en tratamiento' ? 'En tratamiento'
          : s === 'en observación' ? 'En observación'
          : s === 'cuarentena' ? 'Cuarentena'
          : s === 'vendido' ? 'Vendido'
          : s === 'fallecido' || s === 'muerto' ? 'Fallecido'
          : 'Sano';
        setValue('status', mappedStatus);
        setValue('record', animal.record);
        setValue('birth_date', animal.birth_date);
        setValue('weight', animal.weight || 0);
        setValue('gender', animal.gender);
        setValue('notes', animal.notes);
        setValue('entry_date', animal.entry_date);
        setValue('purchase_date', animal.purchase_date);
        setValue('sale_date', animal.sale_date);
        setValue('exit_date', animal.exit_date);
        setValue('exit_reason', animal.exit_reason);

        // Cargar razas para la especie seleccionada
        if (animal.species_id) {
          loadBreedsBySpecies(animal.species_id);
        }
      });
    }
  }, [id, setValue]);

  // Función para cargar razas por especie
  const loadBreedsBySpecies = async (speciesId: number) => {
    setLoadingBreeds(true);
    try {
      const breedsData = await breedsService.getBreedsBySpecies(speciesId.toString());
      setBreeds(breedsData);
    } catch (error) {
      console.error('Error al cargar razas:', error);
      setBreeds([]);
    } finally {
      setLoadingBreeds(false);
    }
  };

  const onSubmit = async (data: AnimalFormFields) => {
    try {
      if (id) {
        await animalsService.updateAnimal(Number(id), data);
      } else {
        await animalsService.createAnimal(data);
      }
      navigate('/admin/animals');
    } catch (error: any) {
      const msg = error?.response?.data?.message || error?.message || 'Error al guardar animal';
      alert(msg);
    }
  };

  const renderError = (err: unknown) => {
    if (!err) return null;
    if (typeof err === 'string') return <span>{err}</span>;
    if (typeof err === 'object' && err && 'message' in err) return <span>{(err as FieldError).message}</span>;
    return null;
  };

  const speciesOptions = species.map((specie) => ({
    value: String(specie.id),
    label: specie.name
  }));

  const breedOptions = breeds.map((breed) => ({
    value: String(breed.id),
    label: breed.name
  }));

  return (
    <form onSubmit={handleSubmit(onSubmit)}>
      {/* eliminado: campo Nombre */}
      <div>
        <label>Especie</label>
        <input type="hidden" {...register('species_id', { required: 'La especie es obligatoria' })} />
        <Combobox
          options={speciesOptions}
          value={selectedSpeciesId ? String(selectedSpeciesId) : undefined}
          onValueChange={(value) => {
            const speciesId = Number(value);
            setSelectedSpeciesId(speciesId);
            setValue('species_id', speciesId);
            setValue('breed_id', 0);
            setSelectedBreedId(null);

            if (speciesId) {
              loadBreedsBySpecies(speciesId);
            } else {
              setBreeds([]);
            }
          }}
          placeholder="Seleccionar"
          searchPlaceholder="Buscar"
          emptyMessage="Sin resultados"
        />
        {renderError(errors.species_id)}
      </div>
      <div>
        <label>Raza</label>
        <input type="hidden" {...register('breed_id', { required: 'La raza es obligatoria' })} />
        <Combobox
          options={breedOptions}
          value={selectedBreedId ? String(selectedBreedId) : undefined}
          onValueChange={(value) => {
            const breedId = Number(value);
            setSelectedBreedId(breedId);
            setValue('breed_id', breedId);
          }}
          placeholder="Seleccionar"
          searchPlaceholder="Buscar"
          emptyMessage={loadingBreeds ? "Cargando..." : "Sin resultados"}
          disabled={!selectedSpeciesId || loadingBreeds}
        />
        {renderError(errors.breed_id)}
      </div>
      <div>
        <label>Registro</label>
        <input {...register('record', { required: 'El registro es obligatorio' })} />
        {renderError(errors.record)}
      </div>
      <div>
        <label>Fecha de nacimiento</label>
        <input
          type="date"
          max={getTodayColombia()}
          {...register('birth_date', {
            required: 'La fecha de nacimiento es obligatoria',
            validate: value => {
              if (!value) return true;
              const selectedDate = new Date(value);
              const today = new Date();
              today.setHours(0, 0, 0, 0); // Resetear hora para comparación justa
              return selectedDate <= today || 'La fecha de nacimiento no puede ser futura';
            }
          })}
        />
        {renderError(errors.birth_date)}
      </div>
      <div>
        <label>Peso (kg)</label>
        <input type="number" step="0.01" {...register('weight', { required: 'El peso es obligatorio', min: { value: 0.01, message: 'El peso debe ser mayor a 0' } })} />
        {renderError(errors.weight)}
      </div>
      <div>
        <label>Género</label>
        <select {...register('gender', { required: 'El género es obligatorio' })}>
          <option value="">Seleccione</option>
          <option value="Macho">Macho</option>
          <option value="Hembra">Hembra</option>
        </select>
        {renderError(errors.gender)}
      </div>
      <div>
        <label>Estado</label>
        <select {...register('status', { required: 'El estado es obligatorio' })}>
          <option value="">Seleccione</option>
          <option value="Vivo">Vivo</option>
          <option value="Muerto">Muerto</option>
          <option value="Vendido">Vendido</option>
        </select>
        {renderError(errors.status)}
      </div>
      
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 border-t pt-4 mt-4">
        <h3 className="col-span-full font-semibold text-gray-700">Trazabilidad y Registro ICA</h3>
        <div>
          <label>Fecha de Ingreso</label>
          <input type="date" {...register('entry_date')} max={getTodayColombia()} />
          {renderError(errors.entry_date)}
        </div>
        <div>
          <label>Fecha de Compra</label>
          <input type="date" {...register('purchase_date')} max={getTodayColombia()} />
          {renderError(errors.purchase_date)}
        </div>
        <div>
          <label>Fecha de Salida</label>
          <input type="date" {...register('exit_date')} max={getTodayColombia()} />
          {renderError(errors.exit_date)}
        </div>
        <div>
          <label>Fecha de Venta</label>
          <input type="date" {...register('sale_date')} max={getTodayColombia()} />
          {renderError(errors.sale_date)}
        </div>
        <div className="col-span-full">
          <label>Motivo de Salida</label>
          <input {...register('exit_reason')} placeholder="Ej: Venta, Traslado, Muerte" />
          {renderError(errors.exit_reason)}
        </div>
      </div>
      <div>
        <label>Notas</label>
        <textarea {...register('notes')} placeholder="Observaciones o notas adicionales" />
        {renderError(errors.notes)}
      </div>
      <button type="submit" disabled={isSubmitting} className="flex items-center gap-2" aria-label={id ? 'Actualizar animal' : 'Crear animal'}>
        {id ? <><Edit className="h-4 w-4" /> Actualizar animal</> : <><Plus className="h-4 w-4" /> Crear animal</>}
      </button>
    </form>
  );
}

