    const id = Number(record.id);
    if (!id) return;
    const resp = await descendantsApi.fetchDescendants(id, 3, 'id,record,sex,breeds_id,idFather,idMother');
    if (!resp) {
      setDescAnimal(record);
      setDescLevels([]);
      setDescRootId(id);
      setIsDescOpen(true);
      return;
    }
    setDescRootId(resp.rootId);
    setDescAnimal(resp.nodes[resp.rootId]);
    setDescLevels(graphToDescendantLevels(resp));
    setDescCounts(resp.counts);
    setDescSummary(resp.summary);
    setDescEdgeExamples(resp.edge_examples);
    setIsDescOpen(true);
  }, [descendantsApi]);

  const openAnimalDetailModal = useCallback(async (animalId: number) => {
    try {
      const animal = await animalsService.getById(animalId);
      setSelectedAnimal(animal);
      setIsAnimalDetailOpen(true);
    } catch (err) {
      console.error('Error loading animal details:', err);
    }
  }, []);

  // Secciones del formulario
  const formSectionsLocal: CRUDFormSection<Partial<AnimalInput>>[] = [
    {
      title: 'Información Básica',
      gridCols: 3,
      fields: [
        { name: 'record', label: 'Registro', type: 'text', required: true, placeholder: 'Ej: REC0001' },
        { name: 'birth_date', label: 'Fecha de Nacimiento', type: 'date', required: true },
        { 
          name: 'breed_id', 
          label: 'Raza', 
          type: 'select', 
          required: true,
          loadOptions: async () => {
            const data = await breedsService.getPaginated({ limit: 200 });
            return getPageItems<{ id: number; name: string }>(data).map(b => ({ value: b.id, label: b.name }));
          }
        },
        { name: 'gender', label: 'Sexo', type: 'select', required: true, options: ANIMAL_GENDERS as any },
        { name: 'status', label: 'Estado', type: 'select', options: ANIMAL_STATUS_OPTIONS as any },
        { name: 'weight', label: 'Peso (kg)', type: 'number', required: true },
      ],
    },
    {
      title: 'Genealogía',
      gridCols: 2,
      fields: [
        {
          name: 'father_id',
          label: 'Padre',
          type: 'select',
          loadOptions: async () => {
            const data = await animalsService.getAnimalsPaginated({ sex: 'Macho', limit: 200 });
            return getPageItems<any>(data).map(a => ({ value: a.id, label: a.record || `ID ${a.id}` }));
          }
        },
        {
          name: 'mother_id',
          label: 'Madre',
          type: 'select',
          loadOptions: async () => {
            const data = await animalsService.getAnimalsPaginated({ sex: 'Hembra', limit: 200 });
            return getPageItems<any>(data).map(a => ({ value: a.id, label: a.record || `ID ${a.id}` }));
          }
        },
      ],
    }
  ];

  // Columnas de la tabla
  const columns: CRUDColumn<AnimalResponse & { [k: string]: any }>[] = [
    { key: 'record', label: 'Registro', width: 15 },
    { key: 'gender', label: 'Sexo', render: (v, rec) => v || rec.sex || '-' },
    { key: 'status', label: 'Estado' },
    { 
      key: 'breed_id', 
      label: 'Raza', 
      fkEntity: 'breeds',
      render: (v, rec) => {
        const id = v || rec.breeds_id || rec.breed_id;
        return breedOptions.find(b => Number(b.value) === Number(id))?.label || (rec.breed?.name) || '-';
      }
    },
    { key: 'birth_date', label: 'Nacimiento', render: (v) => v ? new Date(v as string).toLocaleDateString() : '-' },
    { key: 'weight', label: 'Peso', render: (v) => v ? `${Number(v).toFixed(1)} kg` : '-' },
  ];

  const renderAnimalCard = useCallback((item: any) => (
    <AnimalCard
      animal={item}
      breedLabel={breedOptions.find(b => Number(b.value) === Number(item.breed_id || item.breeds_id))?.label || item.breed?.name || '-'}
      fatherLabel={fatherOptions.find(o => Number(o.value) === Number(item.father_id || item.idFather))?.label || '-'}
      motherLabel={motherOptions.find(o => Number(o.value) === Number(item.mother_id || item.idMother))?.label || '-'}
      onFatherClick={openAnimalDetailModal}
      onMotherClick={openAnimalDetailModal}
      onOpenHistory={() => openHistoryModal(item)}
      onOpenAncestorsTree={() => openGeneticTreeModal(item)}
      onOpenDescendantsTree={() => openDescendantsTreeModal(item)}
      currentUserId={user?.id}
    />
  ), [breedOptions, fatherOptions, motherOptions, openAnimalDetailModal, openHistoryModal, openGeneticTreeModal, openDescendantsTreeModal, user?.id]);

  const renderAnimalDetail = (item: any) => (
    <AnimalModalContent
      animal={item}
      breedLabel={breedOptions.find(b => Number(b.value) === Number(item.breed_id || item.breeds_id))?.label || item.breed?.name || '-'}
      fatherLabel={fatherOptions.find(o => Number(o.value) === Number(item.father_id || item.idFather))?.label || '-'}
      motherLabel={motherOptions.find(o => Number(o.value) === Number(item.mother_id || item.idMother))?.label || '-'}
      onFatherClick={openAnimalDetailModal}
      onMotherClick={openAnimalDetailModal}
      currentUserId={user?.id}
      onOpenHistory={() => openHistoryModal(item)}
      onOpenAncestorsTree={() => openGeneticTreeModal(item)}
      onOpenDescendantsTree={() => openDescendantsTreeModal(item)}
      onEdit={() => {
        const sp = new URLSearchParams(window.location.search);
        sp.set('edit', String(item.id));
        navigate(`?${sp.toString()}`);
      }}
    />
  );

  const getAnimalDisplayName = useCallback((animal: any) => {
    return animal?.record || animal?.name || `Animal #${animal?.id}`;
  }, []);

  const crudConfigLocal: CRUDConfig<any, any> = {
    title: 'Animales',
    entityName: 'Animal',
    columns,
    formSections: formSectionsLocal,
    enableDetailModal: true,
    enableCreateModal: true,
    enableEditModal: true,
    enableDelete: true,
    viewMode,
    renderCard: renderAnimalCard,
    customToolbar: (
      <div className="flex items-center gap-1">
        <Button variant={viewMode === 'table' ? 'primary' : 'outline'} size="sm" className="h-7" onClick={() => setViewMode('table')}>Tabla</Button>
        <Button variant={viewMode === 'cards' ? 'primary' : 'outline'} size="sm" className="h-7" onClick={() => setViewMode('cards')}>Tarjetas</Button>
      </div>
    ),
    customActions: (record) => (
      <AnimalActionsMenu
        animal={record}
        currentUserId={user?.id}
        onOpenHistory={() => openHistoryModal(record)}
        onOpenAncestorsTree={() => openGeneticTreeModal(record)}
        onOpenDescendantsTree={() => openDescendantsTreeModal(record)}
      />
    ),
    preDeleteCheck: async (id) => {
      clearAnimalDependencyCache(id);
      return await checkAnimalDependencies(id);
    },
    onAfterCreate: async (created) => {
      refreshFathers(); refreshMothers();
      if (pendingImages.length > 0 && created?.id) {
        await animalImageService.uploadImages(created.id, pendingImages, { compress: true });
        setPendingImages([]);
      }
    },
    onAfterUpdate: async () => {
      refreshFathers(); refreshMothers();
    }
  };

  return (
    <>
      <AdminCRUDPage
        config={crudConfigLocal}
        service={animalsService}
        initialFormData={initialFormData}
        mapResponseToForm={mapResponseToForm}
        validateForm={validateForm}
        customDetailContent={renderAnimalDetail}
        onFormDataChange={setFormData}
        realtime={true}
        enhancedHover={true}
        renderBatchActions={(selectedIds, clearSelection, refetch, selectedAnimals) => {
          const selectedAnimalSummaries = (selectedAnimals || []).map((animal: any) => ({
            id: Number(animal.id),
            label: getAnimalDisplayName(animal),
            status: animal.status,
            fieldName: animal.field?.name || animal.field_name,
          }));

          return (
            <>
              <BatchActionToolbar 
                selectedCount={selectedIds.length}
                selectedLabels={selectedAnimalSummaries.map((animal) => animal.label)}
                onClear={clearSelection}
                onTransfer={() => setIsBatchTransferOpen(true)}
                onWeight={() => setIsBatchWeightOpen(true)}
                onVaccinate={() => setIsBatchVaccinationOpen(true)}
              />
              <BatchFieldTransferModal
                isOpen={isBatchTransferOpen}
                onClose={() => setIsBatchTransferOpen(false)}
                selectedAnimalIds={selectedIds}
                selectedAnimals={selectedAnimalSummaries}
                onSuccess={() => { clearSelection(); refetch(); }}
              />
              <BatchWeightModal
                isOpen={isBatchWeightOpen}
                onClose={() => setIsBatchWeightOpen(false)}
                selectedAnimalIds={selectedIds}
                onSuccess={() => { clearSelection(); refetch(); }}
              />
              <BatchVaccinationModal
                isOpen={isBatchVaccinationOpen}
                onClose={() => setIsBatchVaccinationOpen(false)}
                selectedAnimalIds={selectedIds}
                onSuccess={() => { clearSelection(); refetch(); }}
              />
            </>
          );
        }}
        additionalFormContent={(data, edit) => !edit && (
          <div className="mt-4 p-4 border rounded-xl bg-card/30">
            <h3 className="text-sm font-bold mb-2">Imágenes (Opcional)</h3>
            <AnimalImagePreUpload files={pendingImages} onChange={setPendingImages} />
          </div>
        )}
      />

      {isHistoryOpen && historyAnimal && (
        <AnimalHistoryModal animal={historyAnimal} onClose={() => setIsHistoryOpen(false)} />
      )}

      <GeneticTreeModal
        isOpen={isTreeOpen}
        onClose={() => setIsTreeOpen(false)}
        animal={treeAnimal}
        levels={treeLevels}
        counts={ancestorCounts}
        summary={ancestorSummary}
        edgeExamples={ancestorEdgeExamples}
        onNavigateToAnimal={openGeneticTreeModal}
      />

      <DescendantsTreeModal
        isOpen={isDescOpen}
        onClose={() => setIsDescOpen(false)}
        animal={descAnimal}
        levels={descLevels}
        counts={descCounts}
        summary={descSummary}
        edgeExamples={descEdgeExamples}
        onNavigateToAnimal={openDescendantsTreeModal}
      />

      {/* Modal para detalle de animal (FK) */}
      {isAnimalDetailOpen && selectedAnimal && (
        <GenericModal isOpen={isAnimalDetailOpen} onOpenChange={setIsAnimalDetailOpen} title="Detalle del Animal" size="full">
          {renderAnimalDetail(selectedAnimal)}
        </GenericModal>
      )}
    </>
  );
}

export default AdminAnimalsPage;

import React from 'react';
import { useSearchParams } from 'react-router-dom';
import { AdminCRUDPage } from '@/widgets/admin-crud';
import { CRUDColumn, CRUDFormSection, CRUDConfig } from '@/shared/types/crud';
import { breedsService } from '@/entities/breed/api/breeds.service';
import type { BreedResponse, BreedInput } from '@/shared/api/generated/swaggerTypes';
import { speciesService } from '@/entities/species/api/species.service';
import { checkBreedDependencies } from '@/features/diagnostics/api/dependencyCheck.animals';
import { BreedActionsMenu } from '@/widgets/dashboard/BreedActionsMenu';
import { SpeciesLink } from '@/entities/species/ui';
import { X } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { SectionCard, InfoField, modalStyles } from '@/shared/ui/common/ModalStyles';


// Mapear respuesta a formulario
const mapResponseToForm = (item: BreedResponse & { [k: string]: any }): BreedInput => ({
  name: item.name || '',
  species_id: item.species_id,
  description: item.description || '',
  characteristics: item.characteristics || '',
});

// Validación mejorada
const validateForm = (formData: BreedInput): string | null => {
  if (!formData.name || !formData.name.trim()) {
    return '⚠️ El nombre de la raza es obligatorio.';
  }

  // Validar species_id: debe ser un número válido > 0
  const speciesId = Number(formData.species_id);
  if (!formData.species_id || Number.isNaN(speciesId) || speciesId <= 0) {
    return '⚠️ Debe seleccionar una especie válida para esta raza.';
  }

  return null;
};

// Datos iniciales - NO usar 0, usar undefined para forzar selección
const initialFormData: BreedInput = {
  name: '',
  species_id: undefined as any, // Forzar que el usuario seleccione
  description: '',
  characteristics: '',
};

// Página principal
function AdminBreedsPage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const [speciesOptions, setSpeciesOptions] = React.useState<Array<{ value: number; label: string }>>([]);

  // Obtener parámetros de filtro de la URL
  const speciesIdFilter = searchParams.get('species_id');
  const speciesNameFilter = searchParams.get('species_name');

  React.useEffect(() => {
    (async () => {
      try {
        const res = await speciesService.getSpecies({ page: 1, limit: 1000 });
        setSpeciesOptions((res?.data || []).map((s: any) => ({ value: s.id, label: s.name })));
      } catch (e) {
        // silenciar
      }
    })();
  }, []);

  // Función para limpiar el filtro
  const clearFilter = () => {
    setSearchParams({});
  };

  // Crear mapa de búsqueda optimizado
  const speciesMap = React.useMemo(() => {
    const map = new Map<number, string>();
    speciesOptions.forEach(opt => map.set(opt.value, opt.label));
    return map;
  }, [speciesOptions]);

  // Columnas de la tabla
  const columns: CRUDColumn<BreedResponse & { [k: string]: any }>[] = React.useMemo(() => [
    { key: 'name', label: 'Nombre' },
    {
      key: 'species_id',
      label: 'Especie',
      render: (v) => {
        if (!v) return '-';
        const id = Number(v);
        const label = speciesMap.get(id) || `Especie ${id}`;
        return <SpeciesLink id={id} label={label} />;
      }
    },
    { key: 'created_at', label: 'Creado', render: (v) => (v ? new Date(v as string).toLocaleDateString('es-ES') : '-') },
  ], [speciesMap]);

  const formSectionsLocal: CRUDFormSection<BreedInput>[] = [
    {
      title: 'Información Básica',
      gridCols: 2,
      fields: [
        { name: 'name', label: 'Nombre', type: 'text', required: true, placeholder: 'Ej: MixedFeline' },
        { name: 'species_id', label: 'Especie', type: 'select', required: true, options: speciesOptions, placeholder: 'Seleccionar especie...' },
      ],
    },
    {
      title: 'Detalles Adicionales',
      gridCols: 1,
      fields: [
        { name: 'description', label: 'Descripción', type: 'textarea', placeholder: 'Descripción de la raza...' },
        { name: 'characteristics', label: 'Características', type: 'textarea', placeholder: 'Características distintivas...' },
      ],
    },
  ];

  // Renderizado personalizado para la tarjeta
  const renderBreedCard = (item: BreedResponse & { [k: string]: any }) => {
    const speciesLabel = item.species_id ? speciesMap.get(item.species_id) || `Especie ${item.species_id}` : '-';

    return (
      <div className={modalStyles.spacing.section}>
        <SectionCard title="Información Básica">
          <InfoField label="Nombre" value={item.name || '-'} valueSize="large" />
          <InfoField
            label="Especie"
            value={item.species_id ? <SpeciesLink id={item.species_id} label={speciesLabel} /> : '-'}
          />
        </SectionCard>
        <SectionCard title="Fecha de Creación">
          <InfoField
            label="Creado"
            value={item.created_at ? new Date(item.created_at).toLocaleDateString('es-ES', {
              year: 'numeric',
              month: 'long',
              day: 'numeric'
            }) : '-'}
          />
        </SectionCard>
      </div>
    );
  };

  // Renderizado personalizado para el detalle
  const renderBreedDetail = (item: BreedResponse & { [k: string]: any }) => {
    const speciesLabel = item.species_id ? speciesMap.get(item.species_id) || `Especie ${item.species_id}` : '-';

    return (
      <div className={modalStyles.spacing.section}>
        {/* Menú de Acciones */}
        <div className="flex items-center justify-end gap-2 px-1 pb-3">
          <div className="text-xs text-muted-foreground font-medium">Acciones rápidas:</div>
          <BreedActionsMenu breed={item as BreedResponse} />
        </div>

        <div className={modalStyles.twoColGrid}>
          {/* Columna izquierda */}
          <div className={modalStyles.spacing.section}>
            <SectionCard title="Información Básica">
              <div className={modalStyles.spacing.sectionSmall}>
                <InfoField label="ID" value={`#${item.id}`} />
                <InfoField label="Nombre" value={item.name || '-'} valueSize="xlarge" />
              </div>
            </SectionCard>

            <SectionCard title="Especie">
              <InfoField
                label="Especie"
                value={item.species_id ? <SpeciesLink id={item.species_id} label={speciesLabel} /> : '-'}
                valueSize="large"
              />
            </SectionCard>
          </div>

          {/* Columna derecha */}
          <div className={modalStyles.spacing.section}>
            <SectionCard title="Información del Sistema">
              <div className={modalStyles.fieldsGrid}>
                <InfoField
                  label="Creado"
                  value={item.created_at ? new Date(item.created_at).toLocaleDateString('es-ES') : '-'}
                />
                <InfoField
                  label="Actualizado"
                  value={item.updated_at ? new Date(item.updated_at).toLocaleDateString('es-ES') : '-'}
                />
              </div>
            </SectionCard>
          </div>
        </div>
      </div>
    );
  };

  const crudConfigLocal: CRUDConfig<BreedResponse & { [k: string]: any }, BreedInput> = {
    title: 'Razas',
    entityName: 'Raza',
    columns,
    formSections: formSectionsLocal,
    // Limitar campos para reducir payload y acelerar render
    defaultFields: 'id,name,species_id,created_at,updated_at',
    searchPlaceholder: 'Buscar razas...',
    emptyStateMessage: 'No hay razas disponibles.',
    emptyStateDescription: 'Crea la primera para comenzar.',
    enableDetailModal: true,
    enableCreateModal: true,
    enableEditModal: true,
    enableDelete: true,
    showDetailTimestamps: false,
    showEditTimestamps: false,
    showIdInDetailTitle: false,
    // Aplicar filtro por species_id si está en la URL
    additionalFilters: speciesIdFilter ? { species_id: parseInt(speciesIdFilter) } : undefined,
    // Verificación de dependencias antes de eliminar
    preDeleteCheck: async (id: number) => {
      return await checkBreedDependencies(id);
    },
    // Agregar menú de acciones
    customActions: (record) => (
      <div className="flex items-center gap-1">
        <BreedActionsMenu breed={record as BreedResponse} />
      </div>
    ),
    // Renderizado personalizado
    renderCard: renderBreedCard,
    customDetailContent: renderBreedDetail,
    // Banner personalizado cuando hay filtro activo
    customHeader: speciesIdFilter ? (
      <div className="mb-4 p-4 bg-blue-50 dark:bg-blue-950 border border-blue-200 dark:border-blue-800 rounded-lg flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="text-sm">
            <span className="font-medium text-blue-900 dark:text-blue-100">Filtrando por especie:</span>
            <span className="ml-2 text-blue-700 dark:text-blue-300 font-semibold">
              {speciesNameFilter || `ID ${speciesIdFilter}`}
            </span>
          </div>
        </div>
        <Button
          variant="ghost"
          size="sm"
          onClick={clearFilter}
          className="text-blue-700 dark:text-blue-300 hover:text-blue-900 dark:hover:text-blue-100 hover:bg-blue-100 dark:hover:bg-blue-900"
        >
          <X className="h-4 w-4 mr-1" />
          Quitar filtro
        </Button>
      </div>
    ) : undefined,
  };

  return (
    <AdminCRUDPage
      config={crudConfigLocal}
      service={breedsService}
      initialFormData={initialFormData}
      mapResponseToForm={mapResponseToForm}
      validateForm={validateForm}
      // Activar actualización en tiempo real en la vista de razas
      realtime={true}
      pollIntervalMs={0}
      refetchOnFocus={false}
      refetchOnReconnect={true}
      cache={true}
      cacheTTL={300000}
      enhancedHover={true}
    />
  );
}

export default AdminBreedsPage;

import React, { useEffect, useState, useMemo } from 'react';
import { useGlobalViewMode } from '@/shared/hooks/useGlobalViewMode';
import { AdminCRUDPage } from '@/widgets/admin-crud';
import { CRUDColumn, CRUDFormSection, CRUDConfig } from '@/shared/types/crud';
import { controlService } from '@/entities/control/api/control.service';
import { animalsService } from '@/entities/animal/api/animal.service';
// Importar tipo ControlForm si no existe, lo definimos localmente arriba
// Ajustar el tipo importado: ya no usamos ControlInput aquí
import type { ControlResponse } from '@/shared/api/generated/swaggerTypes';
import { Button } from '@/shared/ui/button';
import { Badge } from '@/shared/ui/badge';
import { TrendingUp } from 'lucide-react';

import { getTodayColombia } from '@/shared/utils/dateUtils';
import { AnimalLink, AnimalGrowthLink } from '@/entities/animal/ui';
import { SectionCard, InfoField, modalStyles } from '@/shared/ui/common/ModalStyles';

// Tipo de formulario simplificado alineado al JSON solicitado
type ControlForm = {
  animal_id: number;
  checkup_date: string;
  weight?: number;
  height?: number;
  health_status?: string;
  description?: string;
};

// Secciones del formulario basadas en opciones dinámicas
const formSectionsLocal = (
  animalOptions: { value: number; label: string }[]
): CRUDFormSection<ControlForm>[] => [
    {
      title: 'Información Básica',
      gridCols: 2,
      fields: [
        { name: 'animal_id', label: 'Animal', type: 'select', required: true, options: animalOptions, placeholder: 'Seleccionar animal' },
        { name: 'checkup_date', label: 'Fecha de Chequeo', type: 'date', required: true, placeholder: 'YYYY-MM-DD' },
      ],
    },
    {
      title: 'Métricas Básicas',
      gridCols: 2,
      fields: [
        { name: 'weight', label: 'Peso (kg)', type: 'number', validation: { min: 0 }, placeholder: 'Peso en kg' },
        { name: 'height', label: 'Altura (m)', type: 'number', validation: { min: 0 }, placeholder: 'Altura en metros' },
        {
          name: 'health_status',
          label: 'Estado de Salud',
          type: 'select',
          required: true,
          options: [
            { value: 'Excelente', label: 'Excelente' },
            { value: 'Bueno', label: 'Bueno' },
            { value: 'Regular', label: 'Regular' },
            { value: 'Malo', label: 'Malo' },
            { value: 'Sano', label: 'Sano' }
          ],
          placeholder: 'Seleccionar estado'
        },
      ],
    },
    {
      title: 'Descripción',
      fields: [
        { name: 'description', label: 'Descripción', type: 'textarea', placeholder: 'Descripción...', colSpan: 2 },
      ],
    },
  ];

// Función para renderizar tarjetas de controles
const renderControlCard = (animalMap: Map<number, string>) => (item: ControlResponse & { [k: string]: any }) => {
  const animalLabel = animalMap.get(item.animal_id) || `Animal ${item.animal_id}`;
  const checkupDate = (item as any)?.checkup_date ?? (item as any)?.control_date;
  const formattedDate = checkupDate ? new Date(checkupDate as string).toLocaleDateString('es-ES', {
    year: 'numeric',
    month: 'short',
    day: 'numeric'
  }) : '-';
  const healthStatus = (item as any)?.health_status ?? (item as any)?.healt_status ?? '-';
  const description = (item as any)?.description ?? (item as any)?.observations;

  const getBadgeColor = (status: string) => {
    switch (status) {
      case 'Excelente': return 'bg-green-500/90 hover:bg-green-600 text-white border-transparent';
      case 'Bueno': case 'Sano': return 'bg-blue-500/90 hover:bg-blue-600 text-white border-transparent';
      case 'Regular': return 'bg-yellow-500/90 hover:bg-yellow-600 text-white border-transparent';
      case 'Malo': return 'bg-red-500/90 hover:bg-red-600 text-white border-transparent';
      default: return 'bg-gray-500/90 hover:bg-gray-600 text-white border-transparent';
    }
  };

  return (
    <div className="p-4 flex flex-col gap-4 h-full relative">
      {/* Header with Status and Date */}
      <div className="flex justify-between items-start">
        <Badge className={`text-xs px-2.5 py-0.5 shadow-sm ${getBadgeColor(healthStatus)}`}>
          {healthStatus}
        </Badge>
        <span className="text-xs text-muted-foreground font-medium bg-muted/30 px-2 py-1 rounded-md">
          {formattedDate}
        </span>
      </div>

      {/* Main Info */}
      <div className="space-y-1">
        <div className="text-xs text-muted-foreground font-medium uppercase tracking-wider">Animal</div>
