  useEffect(() => {
    const fetchAdditionalStats = async () => {
      try {
        // Obtener datos adicionales desde APIs
        const [inventorySummary, offspring] = await Promise.all([
          inventoryService.getSummary(),
          reproductionService.getOffspring(),
