            return [
              {
                date: p.date,
                hour: hour,
                value: Math.min(100, (p.liters / 25) * 100),
                type: 'milking' as const,
              },
              {
                date: p.date,
                hour: hour - 1,
                value: Math.min(100, (p.liters / 25) * 80),
                type: 'movement' as const,
              },
              {
                date: p.date,
                hour: hour + 1,
                value: Math.min(100, (p.liters / 25) * 60),
                type: 'rest' as const,
              },
