import { useEffect } from 'react';
import { useForm, FieldError } from 'react-hook-form';
import { useNavigate, useParams } from 'react-router-dom';
import { geneticImprovementsService } from '@/entities/genetic-improvement/api/geneticImprovements.service';
import { getTodayColombia } from '@/shared/utils/dateUtils';

export type GeneticImprovementFormFields = {
  animal_id: number;
  improvement_type: string;
  date: string;
  description?: string;
  expected_result?: string;
};

export default function GeneticImprovementForm() {
  const { id } = useParams<{ id?: string }>();
  const navigate = useNavigate();
  const { register, handleSubmit, setValue, formState: { errors, isSubmitting } } = useForm<GeneticImprovementFormFields>();

  useEffect(() => {
    if (id) {
      geneticImprovementsService.getGeneticImprovementById(id).then((improvement: any) => {
        setValue('animal_id', improvement.animal_id);
        setValue('improvement_type', improvement.improvement_type);
        setValue('date', improvement.date);
        setValue('description', improvement.description);
        setValue('expected_result', improvement.expected_result);
      });
    }
  }, [id, setValue]);

  const onSubmit = async (data: GeneticImprovementFormFields) => {
    try {
      if (id) {
        await geneticImprovementsService.updateGeneticImprovement(id, data);
      } else {
        await geneticImprovementsService.createGeneticImprovement(data);
      }
      navigate('/admin/genetic_improvements');
    } catch (error: any) {
      const msg = error?.response?.data?.message || error?.message || 'Error al guardar mejora genética';
      alert(msg);
    }
  };

  const renderError = (err: unknown) => {
    if (!err) return null;
    if (typeof err === 'string') return <span>{err}</span>;
    if (typeof err === 'object' && err && 'message' in err) return <span>{(err as FieldError).message}</span>;
    return null;
  };

  const today = getTodayColombia();

  return (
    <form onSubmit={handleSubmit(onSubmit)}>
      <div>
        <label>ID del animal</label>
        <input type="number" {...register('animal_id', { required: 'El ID del animal es obligatorio', valueAsNumber: true })} />
        {renderError(errors.animal_id)}
      </div>
      <div>
        <label>Tipo de mejora</label>
        <input {...register('improvement_type', { required: 'El tipo de mejora es obligatorio' })} />
        {renderError(errors.improvement_type)}
      </div>
      <div>
        <label>Fecha</label>
        <input 
          type="date" 
          max={today}
          {...register('date', { 
            required: 'La fecha es obligatoria',
            validate: value => {
              const improvementDate = new Date(value);
              const todayDate = new Date();
              todayDate.setHours(0, 0, 0, 0);
              return improvementDate <= todayDate || 'La fecha no puede ser futura';
            }
          })} 
        />
        {renderError(errors.date)}
      </div>
      <div>
        <label>Descripción</label>
        <textarea {...register('description')} />
        {renderError(errors.description)}
      </div>
      <div>
        <label>Resultado esperado</label>
        <textarea {...register('expected_result')} />
        {renderError(errors.expected_result)}
      </div>
      <button type="submit" disabled={isSubmitting}>{id ? 'Actualizar' : 'Crear'} mejora genética</button>
    </form>
  );
}

import React, { useMemo } from 'react';
import { AdminCRUDPage } from '@/widgets/admin-crud';
import { CRUDColumn, CRUDFormSection } from '@/shared/types/crud';
import { geneticImprovementsService } from '@/entities/genetic-improvement/api/geneticImprovements.service';
import { animalsService } from '@/entities/animal/api/animal.service';
import type {
  AdminGeneticImprovementResponse,
  AdminGeneticImprovementInput,
} from '@/entities/genetic-improvement/model/adminGeneticImprovements.types';
import { getTodayColombia } from '@/shared/utils/dateUtils';

// Opciones para selects

// Configuración de secciones del formulario
const formSections: CRUDFormSection<AdminGeneticImprovementInput>[] = [
  {
    title: 'Información de Mejora Genética',
    gridCols: 2,
    fields: [
      {
        name: 'date',
        label: 'Fecha',
        type: 'date' as const,
        required: true,
      },
      {
        name: 'animal_id',
        label: 'ID Animal',
        type: 'number' as const,
        required: true,
        placeholder: 'ID del animal',
      },
      {
        name: 'genetic_event_technique',
        label: 'Técnica del Evento Genético',
        type: 'text' as const,
        required: true,
        placeholder: 'Técnica utilizada',
      },
      {
        name: 'details',
        label: 'Detalles',
        type: 'textarea' as const,
        required: true,
        placeholder: 'Detalles de la mejora genética',
        colSpan: 2,
      },
      {
        name: 'results',
        label: 'Resultados',
        type: 'textarea' as const,
        required: true,
        placeholder: 'Resultados obtenidos',
        colSpan: 2,
      },
    ],
  },
];

// Configuración completa del CRUD (sin columns, se pasa dinámicamente)
const crudConfigBase = {
  title: 'Mejoras Genéticas',
  entityName: 'Mejora Genética',
  formSections,
  searchPlaceholder: 'Buscar mejoras genéticas...',
  emptyStateMessage: 'No hay mejoras genéticas disponibles.',
  emptyStateDescription: 'Crea la primera mejora genética para comenzar.',
  enableDetailModal: true,
  enableCreateModal: true,
  enableEditModal: true,
  enableDelete: true,
};

// Función para mapear respuesta de API a datos del formulario
const mapResponseToForm = (item: AdminGeneticImprovementResponse): AdminGeneticImprovementInput => ({
  animal_id: item.animal_id,
  date: item.date,
  details: item.details || '',
  results: item.results || '',
  genetic_event_technique: item.genetic_event_technique || '',
});

// Función de validación del formulario
const validateForm = (formData: AdminGeneticImprovementInput): string | null => {
  if (!formData.date?.trim()) {
    return 'La fecha es obligatoria.';
  }
  if (!formData.animal_id || formData.animal_id <= 0) {
    return 'El ID del animal es obligatorio y debe ser mayor a 0.';
  }
  if (!formData.genetic_event_technique?.trim()) {
    return 'La técnica del evento genético es obligatoria.';
  }
  if (!formData.details?.trim()) {
    return 'Los detalles son obligatorios.';
  }
  if (!formData.results?.trim()) {
    return 'Los resultados son obligatorios.';
  }
  return null;
};

// Contenido personalizado para el modal de detalle
const customDetailContent = (item: AdminGeneticImprovementResponse) => (
  <div className="space-y-6">
    {/* Información básica */}
    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
      <div>
        <h4 className="font-medium text-foreground mb-2">Información General</h4>
        <dl className="space-y-1 text-sm">
          <div className="flex justify-between">
            <dt className="text-muted-foreground">ID:</dt>
            <dd className="font-medium">{item.id}</dd>
          </div>
          <div className="flex justify-between">
            <dt className="text-muted-foreground">ID Animal:</dt>
            <dd className="font-medium">{item.animal_id}</dd>
          </div>
          <div className="flex justify-between">
            <dt className="text-muted-foreground">Técnica:</dt>
            <dd className="font-medium">{item.genetic_event_technique}</dd>
          </div>
          <div className="flex justify-between">
            <dt className="text-muted-foreground">Fecha:</dt>
            <dd className="font-medium">{new Date(item.date).toLocaleDateString('es-ES')}</dd>
          </div>
        </dl>
      </div>
    </div>

    {/* Detalles y Resultados */}
    <div className="space-y-4">
      {item.details && (
        <div>
          <h4 className="font-medium text-foreground mb-2">Detalles</h4>
          <p className="text-sm text-muted-foreground whitespace-pre-wrap">{item.details}</p>
        </div>
      )}
      {item.results && (
        <div>
          <h4 className="font-medium text-foreground mb-2">Resultados</h4>
          <p className="text-sm text-muted-foreground whitespace-pre-wrap">{item.results}</p>
        </div>
      )}
    </div>

    {/* Fechas del sistema */}
    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">
      <div>
        <dt className="text-muted-foreground">Creado:</dt>
        <dd className="font-medium">{new Date(item.created_at).toLocaleString('es-ES')}</dd>
      </div>
      <div>
        <dt className="text-muted-foreground">Actualizado:</dt>
        <dd className="font-medium">{new Date(item.updated_at).toLocaleString('es-ES')}</dd>
      </div>
    </div>
  </div>
);

// Datos iniciales del formulario
const initialFormData: AdminGeneticImprovementInput = {
  animal_id: undefined as any, // Forzar que el usuario seleccione
  date: getTodayColombia(),
  details: '',
  results: '',
  genetic_event_technique: '',
};

// Componente principal
const AdminGeneticImprovementsPage = () => {
  const [animalOptions, setAnimalOptions] = React.useState<Array<{ value: number; label: string }>>([]);
  const [loading, setLoading] = React.useState(true);

  React.useEffect(() => {
    (async () => {
      setLoading(true);
      try {
        const list: any = await animalsService.getAll?.({ page: 1, page_size: 1000 } as any);
        const arr: any[] = Array.isArray(list) ? list : (list?.items ?? list?.data ?? list?.results ?? []);
        setAnimalOptions(arr.map((a: any) => ({ value: a.id, label: a.record || `ID ${a.id}` })));
      } catch {
        setAnimalOptions([]);
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  // Crear mapa de búsqueda optimizado
  const animalMap = useMemo(() => {
    const map = new Map<number, string>();
    animalOptions.forEach(opt => map.set(opt.value, opt.label));
    return map;
  }, [animalOptions]);

  // Configuración de columnas para la tabla
  const columns: CRUDColumn<AdminGeneticImprovementResponse>[] = useMemo(() => [
    // Eliminado columna ID según requerimiento de ocultar Potreros presentes en el JSON de respuesta
    // {
    //   key: 'id',
    //   label: 'ID',
    //   width: 12,
    // },
    {
      key: 'genetic_event_technique' as any,
      label: 'Técnica',
      render: (value) => value || '-',
    },
    {
      key: 'details' as any,
      label: 'Detalles',
      render: (value) => value || '-',
    },
    {
      key: 'results' as any,
      label: 'Resultado',
      render: (value) => value || '-',
    },
    {
      key: 'date' as any,
      label: 'Fecha',
      render: (value) => (value ? new Date(value as string).toLocaleDateString('es-ES') : '-'),
    },
    {
      key: 'animal_id' as any,
      label: 'Animal',
      render: (value: any) => animalMap.get(Number(value)) || `Animal ${value}` || '-'
    },
    // Ocultamos created_at (está en el JSON de respuesta dado)
    // {
    //   key: 'created_at',
    //   label: 'Creado',
    //   render: (value) => value ? new Date(value as string).toLocaleDateString('es-ES') : '-',
    // },
  ], [animalMap]);

  const formSectionsWithAnimalSelect = React.useMemo(() => {
    return formSections.map((sec) => ({
      ...sec,
      fields: sec.fields.map((f) => (
        (f as any).name === 'animal_id'
          ? { ...(f as any), label: 'Animal (opcional)', type: 'select', options: animalOptions }
          : f
      )),
    }));
  }, [animalOptions]);

  // No renderizar hasta que las opciones estén cargadas para evitar mostrar IDs
  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto mb-4"></div>
          <p className="text-muted-foreground">Cargando mejoras genéticas...</p>
        </div>
      </div>
    );
  }

  return (
    <AdminCRUDPage
      config={{ ...crudConfigBase, columns, formSections: formSectionsWithAnimalSelect }}
      service={geneticImprovementsService}
      initialFormData={initialFormData}
      mapResponseToForm={mapResponseToForm}
      validateForm={validateForm}
      customDetailContent={customDetailContent}
      realtime={true}
      pollIntervalMs={0}
      refetchOnFocus={false}
      refetchOnReconnect={true}
      cache={true}
      cacheTTL={300000}
      enhancedHover={true}
    />
  );
};

export default AdminGeneticImprovementsPage;

import React from 'react';
import { AdminCRUDPage } from '@/widgets/admin-crud';
import { animalService } from '@/entities/animal/api/animal.service';
import { growthService } from '@/entities/growth/api/growth.service';
import type { AnimalResponse } from '@/shared/api/generated/swaggerTypes';
import type { CRUDConfig } from '@/shared/types/crud';
import { TrendingUp, Activity } from 'lucide-react';
import { Badge } from '@/shared/ui/badge';
import { 
  LineChart, 
  Line, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Legend
} from 'recharts';

const GrowthPage: React.FC = () => {
  const initialFormData: any = {};

  const GrowthDetailContent = ({ item }: { item: AnimalResponse }) => {
    const [growthData, setGrowthData] = React.useState<any>(null);
    const [loading, setLoading] = React.useState(true);

    React.useEffect(() => {
      growthService.getAnimalGrowth(item.id)
        .then(setGrowthData)
        .finally(() => setLoading(false));
    }, [item.id]);

    if (loading) return <div className="p-8 text-center">Cargando curva de crecimiento...</div>;
    if (!growthData || !growthData.data_points || growthData.data_points.length === 0) {
      return (
        <div className="p-8 text-center border-2 border-dashed rounded-xl border-border/50">
          <Activity className="h-12 w-12 mx-auto text-muted-foreground/50 mb-4" />
          <p className="text-muted-foreground">No hay suficientes registros de pesaje para este animal.</p>
          <p className="text-sm text-muted-foreground/70">Registra controles de peso en la sección de Controles Sanitarios.</p>
        </div>
      );
    }

    const { stats } = growthData;

    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <div className="bg-primary/5 p-4 rounded-xl border border-primary/10">
            <span className="text-xs text-muted-foreground block mb-1 uppercase tracking-wider font-semibold">Score de Crecimiento</span>
            <span className={`text-2xl font-black ${stats.growth_score > 70 ? 'text-green-500' : stats.growth_score > 40 ? 'text-primary' : 'text-destructive'}`}>
              {stats.growth_score}/100
            </span>
          </div>
          <div className="bg-secondary/5 p-4 rounded-xl border border-secondary/10">
            <span className="text-xs text-muted-foreground block mb-1 uppercase tracking-wider font-semibold">GMD (Promedio Diario)</span>
            <span className="text-2xl font-black text-secondary">
              {stats.avg_daily_gain_kg} <small className="text-xs font-normal">kg/día</small>
            </span>
          </div>
          <div className="bg-accent/5 p-4 rounded-xl border border-accent/10">
            <span className="text-xs text-muted-foreground block mb-1 uppercase tracking-wider font-semibold">Desviación Ref.</span>
            <span className={`text-2xl font-black ${stats.current_deviation_pct >= 0 ? 'text-green-500' : 'text-orange-500'}`}>
              {stats.current_deviation_pct > 0 ? '+' : ''}{stats.current_deviation_pct}%
            </span>
          </div>
          <div className="bg-muted/5 p-4 rounded-xl border border-muted-foreground/10">
            <span className="text-xs text-muted-foreground block mb-1 uppercase tracking-wider font-semibold">Tendencia</span>
            <Badge className={`mt-1 ${stats.trend === 'positivo' ? 'bg-green-500' : stats.trend === 'negativo' ? 'bg-destructive' : 'bg-orange-500'}`}>
              {(stats.trend || 'S/D').toUpperCase()}
            </Badge>
          </div>
        </div>

        <div className="bg-card border-2 border-border/50 rounded-2xl p-6 shadow-sm overflow-hidden h-[400px]">
          <h4 className="text-sm font-bold mb-6 flex items-center gap-2">
            <TrendingUp className="h-4 w-4 text-primary" />
            Curva de Crecimiento (Peso vs Tiempo)
          </h4>
          <ResponsiveContainer width="100%" height="90%">
            <LineChart data={growthData.data_points} margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="rgba(0,0,0,0.05)" />
              <XAxis 
                dataKey="age_months" 
                label={{ value: 'Edad (Meses)', position: 'insideBottom', offset: -5 }} 
              />
              <YAxis 
                label={{ value: 'Peso (kg)', angle: -90, position: 'insideLeft' }} 
              />
              <Tooltip 
                contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
              />
              <Legend verticalAlign="top" height={36}/>
              <Line 
                type="monotone" 
                dataKey="weight" 
                stroke="#8884d8" 
                name="Peso Real" 
                strokeWidth={3}
                dot={{ r: 6, fill: '#8884d8', strokeWidth: 2, stroke: '#fff' }}
                activeDot={{ r: 8 }}
              />
              <Line 
                type="monotone" 
                dataKey="expected_weight" 
                stroke="#10b981" 
                name="Referencia Bovina" 
                strokeDasharray="5 5"
                dot={false}
              />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>
    );
  };

  const crudConfig: CRUDConfig<AnimalResponse, any> = {
    entityName: 'Crecimiento de Animal',
    title: 'Análisis de Crecimiento',
    searchPlaceholder: 'Buscar por registro...',
    columns: [
      {
        key: 'record',
        label: 'Animal',
        render: (val: any) => <span className="font-bold text-primary">{val}</span>
      },
      {
        key: 'sex',
        label: 'Sexo',
        render: (val: any) => <Badge variant="outline">{val}</Badge>
      },
      {
        key: 'age_in_months',
        label: 'Edad',
        render: (val: any) => <span>{val} meses</span>
      },
      {
        key: 'weight',
        label: 'Peso Actual',
        render: (val: any) => <span className="font-medium">{val} kg</span>
      },
    ],
    // @ts-ignore
    formSections: [],
    enableCreateModal: false,
    enableEditModal: false,
    enableDelete: false,
    enableDetailModal: true,
    // @ts-ignore
    customDetailContent: (item: AnimalResponse) => <GrowthDetailContent item={item} />,
  };

  return (
    <AdminCRUDPage
      config={crudConfig}
      service={animalService}
      initialFormData={initialFormData}
    />
  );
};

export default GrowthPage;

import React from 'react';
import { AdminCRUDPage } from '@/widgets/admin-crud';
import { inventoryService } from '@/entities/inventory/api/inventory.service';
import { medicationsService } from '@/entities/medication/api/medications.service';
import { vaccinesService } from '@/entities/vaccine/api/vaccines.service';
import type { InventoryLotResponse, InventoryLotInput } from '@/shared/api/generated/swaggerTypes';
import type { CRUDConfig } from '@/shared/types/crud';
import { AlertTriangle } from 'lucide-react';
import { Badge } from '@/shared/ui/badge';
import { formatDateColombia } from '@/shared/utils/dateUtils';

const InventoryPage: React.FC = () => {
  const [medications, setMedications] = React.useState<{label: string, value: any}[]>([]);
  const [vaccines, setVaccines] = React.useState<{label: string, value: any}[]>([]);
  const [loading, setLoading] = React.useState(true);

  React.useEffect(() => {
    const loadCatalogs = async () => {
      try {
        const [medsData, vacsData] = await Promise.all([
          medicationsService.getAll(),
          vaccinesService.getAll()
        ]);
        setMedications(medsData.map((m: any) => ({ label: m.name, value: m.id })));
        setVaccines(vacsData.map((v: any) => ({ label: v.name, value: v.id })));
      } catch (error) {
        console.error('Error loading inventory catalogs:', error);
      } finally {
        setLoading(false);
      }
    };
    loadCatalogs();
  }, []);

  const initialFormData: InventoryLotInput = {
    product_type: 'Medicamento',
    lot_number: '',
    quantity: 0,
    unit: 'ml',
    expiry_date: new Date().toISOString().split('T')[0],
    min_stock: 5,
  };

  const crudConfig: CRUDConfig<InventoryLotResponse, InventoryLotInput> = {
    entityName: 'Lote de Inventario',
    title: 'Inventario de Medicamentos y Vacunas',
    searchPlaceholder: 'Buscar por lote o proveedor...',
    columns: [
      {
        key: 'product_name',
        label: 'Producto',
        render: (val: any, item: InventoryLotResponse) => (
          <div className="flex flex-col">
            <span className="font-medium text-foreground">{val || '---'}</span>
            <span className="text-xs text-muted-foreground">{item.product_type}</span>
          </div>
        )
      },
      {
        key: 'lot_number',
        label: 'Lote',
        render: (val: any) => <Badge variant="outline" className="font-mono">{val}</Badge>
      },
      {
        key: 'current_quantity',
        label: 'Stock',
        render: (val: any, item: InventoryLotResponse) => (
          <div className="flex items-center gap-2">
            <span className={`font-bold ${item.is_low_stock ? 'text-destructive' : 'text-primary'}`}>
              {val} {item.unit}
            </span>
            {item.is_low_stock && <AlertTriangle className="h-4 w-4 text-destructive" />}
          </div>
        )
      },
      {
        key: 'expiry_date',
        label: 'Vencimiento',
        render: (val: any, item: InventoryLotResponse) => (
          <div className="flex flex-col">
            <span className={item.is_expired ? 'text-destructive font-bold' : ''}>
              {val ? formatDateColombia(val) : '---'}
