            {item.days_to_expiry !== undefined && item.days_to_expiry > 0 && item.days_to_expiry <= 30 && (
              <span className="text-[10px] text-warning font-medium">
                Vence en {item.days_to_expiry} días
              </span>
            )}
          </div>
        )
      },
      {
        key: 'supplier',
        label: 'Proveedor',
      }
    ],
    formSections: [
      {
        title: 'Información del Producto',
        fields: [
          {
            name: 'product_type',
            label: 'Tipo de Producto',
            type: 'select',
            required: true,
            options: [
              { label: 'Medicamento', value: 'Medicamento' },
              { label: 'Vacuna', value: 'Vacuna' },
            ],
          },
          {
            name: 'medication_id',
            label: 'Medicamento',
            type: 'select',
            // @ts-ignore
            dependsOn: 'product_type',
            // @ts-ignore
            showIf: (data: InventoryLotInput) => data.product_type === 'Medicamento',
            required: true,
            options: medications,
            loading: loading
          },
          {
            name: 'vaccine_id',
            label: 'Vacuna',
            type: 'select',
            // @ts-ignore
            dependsOn: 'product_type',
            // @ts-ignore
            showIf: (data: InventoryLotInput) => data.product_type === 'Vacuna',
            required: true,
            options: vaccines,
            loading: loading
          },
        ]
      },
      {
        title: 'Detalles del Lote',
        fields: [
          {
            name: 'lot_number',
            label: 'Número de Lote',
            type: 'text',
            required: true,
            placeholder: 'Ej: AB-1234',
          },
          {
            name: 'quantity',
            label: 'Cantidad Inicial',
            type: 'number',
            required: true,
            // @ts-ignore
            min: 0,
          },
          {
            name: 'unit',
            label: 'Unidad de Medida',
            type: 'text',
            required: true,
            placeholder: 'ml, mg, dosis...',
          },
          {
            name: 'expiry_date',
            label: 'Fecha de Vencimiento',
            type: 'date',
            required: true,
          },
          {
            name: 'min_stock',
            label: 'Stock Mínimo (Alerta)',
            type: 'number',
            // @ts-ignore
            min: 0,
          },
        ]
      },
      {
        title: 'Compra y Proveedor',
        fields: [
          {
            name: 'supplier',
            label: 'Proveedor',
            type: 'text',
          },
          {
            name: 'unit_cost',
            label: 'Costo Unitario',
            type: 'number',
