import { useEffect } from 'react';
import { useForm, FieldError } from 'react-hook-form';
import { useNavigate, useParams } from 'react-router-dom';
import { treatmentMedicationService as treatmentMedicationsService } from '@/entities/treatment-medication/api/treatmentMedication.service';

export type TreatmentMedicationFormFields = {
  treatment_id: number;
  medication_id: number;
  dosage: string;
  dosage_amount?: number;
  dosage_unit?: string;
  frequency?: string;
  duration_days?: number;
  administration_route?: string;
  notes?: string;
};

export default function TreatmentMedicationForm() {
  const { id } = useParams<{ id?: string }>();
  const navigate = useNavigate();
  const { register, handleSubmit, setValue, formState: { errors, isSubmitting } } = useForm<TreatmentMedicationFormFields>();

  useEffect(() => {
    if (id) {
      treatmentMedicationsService.getTreatmentMedicationById(id).then((tm: any) => {
        setValue('treatment_id', tm.treatment_id);
        setValue('medication_id', tm.medication_id);
        setValue('dosage', tm.dosage);
        setValue('dosage_amount', tm.dosage_amount);
        setValue('dosage_unit', tm.dosage_unit);
        setValue('frequency', tm.frequency);
        setValue('duration_days', tm.duration_days);
        setValue('administration_route', tm.administration_route);
        setValue('notes', tm.notes);
      });
    }
  }, [id, setValue]);

  const onSubmit = async (data: TreatmentMedicationFormFields) => {
    try {
      if (id) {
        await treatmentMedicationsService.updateTreatmentMedication(id, data);
      } else {
        await treatmentMedicationsService.createTreatmentMedication(data);
      }
      // Redirigir a la ruta válida sin el prefijo /dashboard
      navigate('/admin/treatment_medications');
    } catch (error: any) {
      const msg = error?.response?.data?.message || error?.message || 'Error al guardar medicamento de tratamiento';
      alert(msg);
    }
  };

  const renderError = (err: unknown) => {
    if (!err) return null;
    if (typeof err === 'string') return <span>{err}</span>;
    if (typeof err === 'object' && err && 'message' in err) return <span>{(err as FieldError).message}</span>;
    return null;
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)}>
      <div>
        <label>ID del tratamiento</label>
        <input type="number" {...register('treatment_id', { required: 'El ID del tratamiento es obligatorio', valueAsNumber: true })} />
        {renderError(errors.treatment_id)}
      </div>
      <div>
        <label>ID del medicamento</label>
        <input type="number" {...register('medication_id', { required: 'El ID del medicamento es obligatorio', valueAsNumber: true })} />
        {renderError(errors.medication_id)}
      </div>
      <div>
        <label>Dosis</label>
        <input {...register('dosage', { required: 'La dosis es obligatoria' })} />
        {renderError(errors.dosage)}
      </div>
      <div>
        <label>Cantidad de dosis</label>
        <input type="number" step="0.01" {...register('dosage_amount', { valueAsNumber: true })} />
        {renderError(errors.dosage_amount)}
      </div>
      <div>
        <label>Unidad de dosis</label>
        <input {...register('dosage_unit')} />
        {renderError(errors.dosage_unit)}
      </div>
      <div>
        <label>Frecuencia</label>
        <input {...register('frequency')} />
        {renderError(errors.frequency)}
      </div>
      <div>
        <label>Días de duración</label>
        <input type="number" {...register('duration_days', { valueAsNumber: true })} />
        {renderError(errors.duration_days)}
      </div>
      <div>
        <label>Vía de administración</label>
        <input {...register('administration_route')} />
        {renderError(errors.administration_route)}
      </div>
      <div>
        <label>Notas</label>
        <textarea {...register('notes')} />
        {renderError(errors.notes)}
      </div>
      <button type="submit" disabled={isSubmitting}>{id ? 'Actualizar' : 'Crear'} medicamento de tratamiento</button>
    </form>
  );
}

import React, { useMemo } from 'react';
import { AdminCRUDPage } from '@/widgets/admin-crud';
import { CRUDColumn, CRUDFormSection, CRUDConfig } from '@/shared/types/crud';
import { treatmentMedicationService } from '@/entities/treatment-medication/api/treatmentMedication.service';
import { treatmentsService } from '@/entities/treatment/api/treatments.service';
import { medicationsService } from '@/entities/medication/api/medications.service';
import type { TreatmentMedicationResponse, TreatmentMedicationInput } from '@/shared/api/generated/swaggerTypes';
import { MedicationLink } from '@/entities/medication/ui';

function AdminTreatmentMedicationsPage() {
  const [treatmentOptions, setTreatmentOptions] = React.useState<Array<{ value: number; label: string }>>([]);
  const [medicationOptions, setMedicationOptions] = React.useState<Array<{ value: number; label: string }>>([]);
  const [loading, setLoading] = React.useState(true);

  // Carga paralela optimizada de opciones
  React.useEffect(() => {
    const loadOptions = async () => {
      setLoading(true);
      try {
        const [treatmentsResult, medicationsResult] = await Promise.all([
          treatmentsService.getTreatments?.().catch((e) => {
            console.warn('[treatment_medications] No se pudieron cargar tratamientos', e);
            return null;
          }),
          medicationsService.getMedications?.().catch((e) => {
            console.warn('[treatment_medications] No se pudieron cargar medicamentos', e);
            return null;
          })
        ]);

        // Procesar tratamientos
        if (treatmentsResult) {
          const items = (treatmentsResult as any)?.data || treatmentsResult || [];
          setTreatmentOptions((items || []).map((t: any) => ({
            value: t.id,
            label: t.diagnosis || `Tratamiento ${t.id}`
          })));
        }

        // Procesar medicamentos
        if (medicationsResult) {
          const items = (medicationsResult as any)?.data || medicationsResult || [];
          setMedicationOptions((items || []).map((m: any) => ({
            value: m.id,
            label: m.name || `Medicamento ${m.id}`
          })));
        }
      } finally {
        setLoading(false);
      }
    };

    loadOptions();
  }, []);

  // Crear mapas de búsqueda optimizados
  const treatmentMap = useMemo(() => {
    const map = new Map<number, string>();
    treatmentOptions.forEach(opt => map.set(opt.value, opt.label));
    return map;
  }, [treatmentOptions]);

  const medicationMap = useMemo(() => {
    const map = new Map<number, string>();
    medicationOptions.forEach(opt => map.set(opt.value, opt.label));
    return map;
  }, [medicationOptions]);

  // Columnas de la tabla con renderizado optimizado y Foreign Key Links
  const columns: CRUDColumn<TreatmentMedicationResponse & { [k: string]: any }>[] = useMemo(() => [
    {
      key: 'treatment_id',
      label: 'Tratamiento',
      render: (v) => {
        if (!v) return '-';
        const id = Number(v);
        const label = treatmentMap.get(id) || `Tratamiento ${id}`;
        return label;
      }
    },
    {
      key: 'medication_id',
      label: 'Medicamento',
      render: (v) => {
        if (!v) return '-';
        const id = Number(v);
        const label = medicationMap.get(id) || `Medicamento ${id}`;
        return <MedicationLink id={id} label={label} />;
      }
    },
    { key: 'created_at' as any, label: 'Creado', render: (v) => (v ? new Date(v as string).toLocaleDateString('es-ES') : '-') },
    { key: 'updated_at' as any, label: 'Actualizado', render: (v) => (v ? new Date(v as string).toLocaleDateString('es-ES') : '-') },
  ], [treatmentMap, medicationMap]);

  const formSections: CRUDFormSection<TreatmentMedicationInput & { [k: string]: any }>[] = [
    {
      title: 'Asignación de Medicamento',
      gridCols: 2,
      fields: [
        { name: 'treatment_id' as any, label: 'Tratamiento', type: 'select', required: true, options: treatmentOptions, placeholder: 'Seleccionar tratamiento' },
        { name: 'medication_id' as any, label: 'Medicamento', type: 'select', required: true, options: medicationOptions, placeholder: 'Seleccionar medicamento' },
      ],
    },
  ];

  const crudConfig: CRUDConfig<TreatmentMedicationResponse & { [k: string]: any }, TreatmentMedicationInput & { [k: string]: any }> = {
    title: 'Medicamentos de Tratamiento',
    entityName: 'Medicamento de tratamiento',
    columns,
    formSections,
    searchPlaceholder: 'Buscar medicamentos de tratamiento...',
    emptyStateMessage: 'No hay medicamentos de tratamiento registrados.',
    emptyStateDescription: 'Crea el primer registro para comenzar.',
    enableDetailModal: true,
    enableCreateModal: true,
    enableEditModal: true,
    enableDelete: true,
  };

  // No renderizar hasta que las opciones estén cargadas
  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto mb-4"></div>
          <p className="text-muted-foreground">Cargando medicamentos de tratamiento...</p>
        </div>
      </div>
    );
  }

  return (
    <AdminCRUDPage
      config={crudConfig}
      service={treatmentMedicationService}
      initialFormData={initialFormData}
      mapResponseToForm={mapResponseToForm}
      validateForm={validateForm}
      realtime={true}
      pollIntervalMs={0}
      refetchOnFocus={false}
      refetchOnReconnect={true}
      cache={true}
      cacheTTL={300000}
      enhancedHover={true}
    />
  );
}

export default AdminTreatmentMedicationsPage;

// Mapear respuesta a formulario
const mapResponseToForm = (item: TreatmentMedicationResponse & { [k: string]: any }): TreatmentMedicationInput & { [k: string]: any } => ({
  treatment_id: item.treatment_id,
  medication_id: item.medication_id,
});

// Validación
const validateForm = (formData: TreatmentMedicationInput & { [k: string]: any }): string | null => {
  if (!formData.treatment_id) return 'El tratamiento es obligatorio.';
  if (!formData.medication_id) return 'El medicamento es obligatorio.';
  return null;
};

// Datos iniciales
const initialFormData: TreatmentMedicationInput & { [k: string]: any } = {
  treatment_id: undefined as any,
  medication_id: undefined as any,
};

import { useEffect } from 'react';
import { useForm, FieldError } from 'react-hook-form';
import { useNavigate, useParams } from 'react-router-dom';
import { treatmentVaccinesService } from '@/entities/treatment-vaccine/api/treatmentVaccines.service';
import { getTodayColombia } from '@/shared/utils/dateUtils';

export type TreatmentVaccineFormFields = {
  treatment_id: number;
  vaccine_id: number;
  dose: string;
  application_site?: string;
  batch_number?: string;
  expiry_date?: string;
  scheduled_date?: string;
  administered_date?: string;
  vaccination_status?: string;
  vaccine_type?: string;
  notes?: string;
};

export default function TreatmentVaccineForm() {
  const { id } = useParams<{ id?: string }>();
  const navigate = useNavigate();
  const { register, handleSubmit, setValue, formState: { errors, isSubmitting } } = useForm<TreatmentVaccineFormFields>();

  useEffect(() => {
    if (id) {
      treatmentVaccinesService.getTreatmentVaccineById(id).then((tv: any) => {
        setValue('treatment_id', tv.treatment_id);
        setValue('vaccine_id', tv.vaccine_id);
        setValue('dose', tv.dose);
        setValue('application_site', tv.application_site);
        setValue('batch_number', tv.batch_number);
        setValue('expiry_date', tv.expiry_date);
        setValue('scheduled_date', tv.scheduled_date);
        setValue('administered_date', tv.administered_date);
        setValue('vaccination_status', tv.vaccination_status);
        setValue('vaccine_type', tv.vaccine_type);
        setValue('notes', tv.notes);
      });
    }
  }, [id, setValue]);

  const onSubmit = async (data: TreatmentVaccineFormFields) => {
    try {
      if (id) {
        await treatmentVaccinesService.updateTreatmentVaccine(id, data);
      } else {
        await treatmentVaccinesService.createTreatmentVaccine(data);
      }
      // Redirigir a la ruta válida sin el prefijo /dashboard
      navigate('/admin/treatment_vaccines');
    } catch (error: any) {
      const msg = error?.response?.data?.message || error?.message || 'Error al guardar vacuna de tratamiento';
      alert(msg);
    }
  };

  const renderError = (err: unknown) => {
    if (!err) return null;
    if (typeof err === 'string') return <span>{err}</span>;
    if (typeof err === 'object' && err && 'message' in err) return <span>{(err as FieldError).message}</span>;
    return null;
  };

  const today = getTodayColombia();

  return (
    <form onSubmit={handleSubmit(onSubmit)}>
      <div>
        <label>ID del tratamiento</label>
        <input type="number" {...register('treatment_id', { required: 'El ID del tratamiento es obligatorio', valueAsNumber: true })} />
        {renderError(errors.treatment_id)}
      </div>
      <div>
        <label>ID de la vacuna</label>
        <input type="number" {...register('vaccine_id', { required: 'El ID de la vacuna es obligatorio', valueAsNumber: true })} />
        {renderError(errors.vaccine_id)}
      </div>
      <div>
        <label>Dosis</label>
        <input {...register('dose', { required: 'La dosis es obligatoria' })} />
        {renderError(errors.dose)}
      </div>
      <div>
        <label>Sitio de aplicación</label>
        <input {...register('application_site')} />
        {renderError(errors.application_site)}
      </div>
      <div>
        <label>Lote</label>
        <input {...register('batch_number')} />
        {renderError(errors.batch_number)}
      </div>
      <div>
        <label>Fecha de expiración</label>
        <input 
          type="date" 
          {...register('expiry_date', {
            validate: value => {
              if (!value) return true; // Es opcional
              const expiryDate = new Date(value);
              const todayDate = new Date();
              todayDate.setHours(0, 0, 0, 0);
              return expiryDate >= todayDate || 'La fecha de expiración no puede ser anterior a hoy';
            }
          })} 
        />
        {renderError(errors.expiry_date)}
      </div>
      <div>
        <label>Fecha programada</label>
        <input 
          type="date" 
          {...register('scheduled_date', {
            validate: value => {
              if (!value) return true; // Es opcional
              const scheduledDate = new Date(value);
              const todayDate = new Date();
              todayDate.setHours(0, 0, 0, 0);
              return scheduledDate >= todayDate || 'La fecha programada no puede ser anterior a hoy';
            }
          })} 
        />
        {renderError(errors.scheduled_date)}
      </div>
      <div>
        <label>Fecha de administración</label>
        <input 
          type="date" 
          max={today}
          {...register('administered_date', {
            validate: value => {
              if (!value) return true; // Es opcional
              const administeredDate = new Date(value);
              const todayDate = new Date();
              todayDate.setHours(0, 0, 0, 0);
              return administeredDate <= todayDate || 'La fecha de administración no puede ser futura';
            }
          })} 
        />
        {renderError(errors.administered_date)}
      </div>
      <div>
        <label>Estado de vacunación</label>
        <input {...register('vaccination_status')} />
        {renderError(errors.vaccination_status)}
      </div>
      <div>
        <label>Tipo de vacuna</label>
        <input {...register('vaccine_type')} />
        {renderError(errors.vaccine_type)}
      </div>
      <div>
        <label>Notas</label>
        <textarea {...register('notes')} />
        {renderError(errors.notes)}
      </div>
      <button type="submit" disabled={isSubmitting}>{id ? 'Actualizar' : 'Crear'} vacuna de tratamiento</button>
    </form>
  );
}

