    const map = new Map<number, string>();
    vaccineOptions.forEach(opt => map.set(opt.value, opt.label));
    return map;
  }, [vaccineOptions]);

  // Columnas de la tabla con renderizado optimizado y Foreign Key Links
  const columns: CRUDColumn<TreatmentVaccineResponse & { [k: string]: any }>[] = useMemo(() => [
    {
      key: 'treatment_id',
      label: 'Tratamiento',
      render: (v) => {
        if (!v) return '-';
        const id = Number(v);
        const label = treatmentMap.get(id) || `Tratamiento ${id}`;
        return label;
      }
    },
    {
      key: 'vaccine_id',
      label: 'Vacuna',
      render: (v) => {
        if (!v) return '-';
        const id = Number(v);
        const label = vaccineMap.get(id) || `Vacuna ${id}`;
        return <VaccineLink id={id} label={label} />;
      }
    },
    { key: 'dose' as any, label: 'Dosis', render: (v) => v || '-' },
    { key: 'created_at' as any, label: 'Creado', render: (v) => (v ? new Date(v as string).toLocaleDateString('es-ES') : '-') },
    { key: 'updated_at' as any, label: 'Actualizado', render: (v) => (v ? new Date(v as string).toLocaleDateString('es-ES') : '-') },
  ], [treatmentMap, vaccineMap]);

  // Formulario
  const formSectionsLocal: CRUDFormSection<TreatmentVaccineInput & { [k: string]: any }>[] = [
    {
      title: 'Asignación',
      gridCols: 2,
      fields: [
        { name: 'treatment_id' as any, label: 'Tratamiento', type: 'select', required: true, options: treatmentOptions, placeholder: 'Seleccione tratamiento' },
        { name: 'vaccine_id' as any, label: 'Vacuna', type: 'select', required: true, options: vaccineOptions, placeholder: 'Seleccione vacuna' },
        { name: 'dose' as any, label: 'Dosis', type: 'text', required: true, placeholder: 'Ej: 2ml', colSpan: 2 },
      ],
    },
  ];

  const crudConfigLocal: CRUDConfig<TreatmentVaccineResponse & { [k: string]: any }, TreatmentVaccineInput & { [k: string]: any }> = {
    title: 'Vacunas de Tratamiento',
    entityName: 'Vacuna de tratamiento',
    columns,
    formSections: formSectionsLocal,
    searchPlaceholder: 'Buscar vacunas de tratamiento...',
    emptyStateMessage: 'No hay vacunas de tratamiento',
    emptyStateDescription: 'Crea el primero para comenzar.',
    enableDetailModal: true,
    enableCreateModal: true,
    enableEditModal: true,
    enableDelete: true,
  };

  // Mapeo respuesta -> formulario
  const mapResponseToForm = (item: TreatmentVaccineResponse & { [k: string]: any }): TreatmentVaccineInput & { [k: string]: any } => ({
    treatment_id: item.treatment_id,
    vaccine_id: item.vaccine_id,
    dose: (item as any).dose || '',
  });

  // Validación
  const validateForm = (formData: TreatmentVaccineInput & { [k: string]: any }): string | null => {
    if (!formData.treatment_id) return 'El tratamiento es obligatorio.';
    if (!formData.vaccine_id) return 'La vacuna es obligatoria.';
    if (!formData.dose || !String(formData.dose).trim()) return 'La dosis es obligatoria.';
    return null;
  };

  // Datos iniciales
  const initialFormData: TreatmentVaccineInput & { [k: string]: any } = {
    treatment_id: undefined as any,
    vaccine_id: undefined as any,
    dose: '',
  };

  // No renderizar hasta que las opciones estén cargadas
  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto mb-4"></div>
          <p className="text-muted-foreground">Cargando vacunas de tratamiento...</p>
        </div>
      </div>
    );
  }

  return (
    <AdminCRUDPage
      config={crudConfigLocal}
      service={treatmentVaccinesService}
      initialFormData={initialFormData}
      mapResponseToForm={mapResponseToForm}
      validateForm={validateForm}
      realtime={true}
      pollIntervalMs={0}
      refetchOnFocus={false}
      refetchOnReconnect={true}
      cache={true}
      cacheTTL={300000}
      enhancedHover={true}
    />
  );
};

export default AdminTreatmentVaccinesPage;

import { useEffect } from 'react';
import { useForm, FieldError } from 'react-hook-form';
import { useNavigate, useParams } from 'react-router-dom';
import { treatmentsService } from '@/entities/treatment/api/treatments.service';
import { getTodayColombia } from '@/shared/utils/dateUtils';

export type TreatmentFormFields = {
  animal_id: number;
  diagnosis: string;
  treatment_date: string;
  treatment_type?: string;
  // removed duplicate optional alias: treatment_date?: string;
  veterinarian?: string;
  symptoms?: string;
  treatment_plan?: string;
  follow_up_date?: string;
  cost?: number;
  notes?: string;
  status?: 'Iniciado' | 'En progreso' | 'Completado' | 'Suspendido';
};

export default function TreatmentForm() {
  const { id } = useParams<{ id?: string }>();
  const navigate = useNavigate();
  const { register, handleSubmit, setValue, formState: { errors, isSubmitting } } = useForm<TreatmentFormFields>();

  useEffect(() => {
    if (id) {
      treatmentsService.getTreatmentById(id).then((t: any) => {
        setValue('animal_id', t.animal_id);
        setValue('diagnosis', t.diagnosis);
        setValue('treatment_date', t.treatment_date);
        setValue('treatment_type', t.treatment_type);
        // removed duplicate setValue for treatment_date
        setValue('veterinarian', t.veterinarian);
        setValue('symptoms', t.symptoms);
        setValue('treatment_plan', t.treatment_plan);
        setValue('follow_up_date', t.follow_up_date);
        setValue('cost', t.cost);
        setValue('notes', t.notes);
        setValue('status', t.status);
      });
    }
  }, [id, setValue]);

  const onSubmit = async (data: TreatmentFormFields) => {
    try {
      if (id) {
        await treatmentsService.updateTreatment(id, data);
      } else {
        await treatmentsService.createTreatment(data);
      }
      // Redirigir a la ruta válida sin el prefijo /dashboard
      navigate('/admin/treatments');
    } catch (error: any) {
      const msg = error?.response?.data?.message || error?.message || 'Error al guardar tratamiento';
      alert(msg);
    }
  };

  const renderError = (err: unknown) => {
    if (!err) return null;
    if (typeof err === 'string') return <span>{err}</span>;
    if (typeof err === 'object' && err && 'message' in err) return <span>{(err as FieldError).message}</span>;
    return null;
  };

  const today = getTodayColombia();

  return (
    <form onSubmit={handleSubmit(onSubmit)}>
      <div>
        <label>ID del animal</label>
        <input type="number" {...register('animal_id', { required: 'El ID del animal es obligatorio', valueAsNumber: true })} />
        {renderError(errors.animal_id)}
      </div>
      <div>
        <label>Diagnóstico</label>
        <input {...register('diagnosis', { required: 'El diagnóstico es obligatorio' })} />
        {renderError(errors.diagnosis)}
      </div>
      <div>
        <label>Fecha de tratamiento</label>
        <input 
          type="date" 
          max={today}
          {...register('treatment_date', { 
            required: 'La fecha es obligatoria',
            validate: value => {
              const treatmentDate = new Date(value);
              const todayDate = new Date();
              todayDate.setHours(0, 0, 0, 0);
              return treatmentDate <= todayDate || 'La fecha de tratamiento no puede ser futura';
            }
          })} 
        />
        {renderError(errors.treatment_date)}
      </div>
      <div>
        <label>Tipo de tratamiento</label>
        <input {...register('treatment_type')} />
        {renderError(errors.treatment_type)}
      </div>
      {/* removed duplicate Fecha de inicio field that was bound to treatment_date again */}
      <div>
        <label>Veterinario</label>
        <input {...register('veterinarian')} />
        {renderError(errors.veterinarian)}
      </div>
      <div>
        <label>Síntomas</label>
        <input {...register('symptoms')} />
        {renderError(errors.symptoms)}
      </div>
      <div>
        <label>Plan de tratamiento</label>
        <textarea {...register('treatment_plan')} />
        {renderError(errors.treatment_plan)}
      </div>
      <div>
        <label>Fecha de seguimiento</label>
        <input 
          type="date" 
          {...register('follow_up_date', {
            validate: value => {
              if (!value) return true; // Es opcional
              const followUpDate = new Date(value);
              const treatmentDateValue = (document.querySelector('input[name="treatment_date"]') as HTMLInputElement)?.value;
              if (treatmentDateValue) {
                const treatmentDate = new Date(treatmentDateValue);
                return followUpDate >= treatmentDate || 'La fecha de seguimiento no puede ser anterior a la fecha de tratamiento';
              }
              const todayDate = new Date();
              todayDate.setHours(0, 0, 0, 0);
              return followUpDate >= todayDate || 'La fecha de seguimiento no puede ser anterior a hoy';
            }
          })} 
        />
        {renderError(errors.follow_up_date)}
      </div>
      <div>
        <label>Costo</label>
        <input type="number" step="0.01" {...register('cost', { valueAsNumber: true })} />
        {renderError(errors.cost)}
      </div>
      <div>
        <label>Notas</label>
        <textarea {...register('notes')} />
        {renderError(errors.notes)}
      </div>
      <div>
        <label>Estado</label>
        <select {...register('status')}>
          <option value="">Seleccionar</option>
          <option value="Iniciado">Iniciado</option>
          <option value="En progreso">En progreso</option>
          <option value="Completado">Completado</option>
          <option value="Suspendido">Suspendido</option>
        </select>
        {renderError(errors.status)}
      </div>
      <button type="submit" disabled={isSubmitting}>{id ? 'Actualizar' : 'Crear'} tratamiento</button>
    </form>
  );
}

import React, { useEffect, useState, useMemo, useCallback } from 'react';
import { AdminCRUDPage } from '@/widgets/admin-crud';
