type SemaforoLevel = 'rojo' | 'amarillo' | 'verde';

interface AlertaGanadera {
  id: number;
  nivel: 'Crítica' | 'Alta' | 'Media' | 'Baja';
  mensaje: string;
  recomendacion?: string;
  animal_record?: string;
  tipo: string;
}

interface DashboardState {
  loading: boolean;
