}

// ─── Helpers ─────────────────────────────────────────────────────────────────

function calcularSemaforo(
  criticas: number,
  altas: number,
): SemaforoLevel {
  if (criticas > 0) return 'rojo';
  if (altas > 0) return 'amarillo';
  return 'verde';
}

