export default function OperarioDashboard() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const { isOnline, pendingOperations } = useOnlineStatus();
  const [refrescando, setRefrescando] = useState(false);

  const [estado, setEstado] = useState<DashboardState>({
    loading: true,
    totalAnimales: 0,
    alertasCriticas: [],
    alertasAltas: [],
    alertasMedias: [],
    semaforo: 'verde',
  });

  // ── Cargar datos ───────────────────────────────────────────────────────────
  const cargarDatos = useCallback(async () => {
    try {
      const [alertasRaw, animalesStats, pendingOps] = await Promise.all([
        alertService.getAll({ limit: 50, is_read: false }).catch(() => []),
        animalsService.getAnimalStats().catch(() => ({ total: 0 })),
        offlineQueue.getPendingOperations().catch(() => []),
      ]);

      const alertas: AlertaGanadera[] = (Array.isArray(alertasRaw) ? alertasRaw : (alertasRaw as any)?.data ?? []).map(
        (a: any) => ({
          id: a.id,
          nivel: a.priority ?? 'Media',
          mensaje: a.message ?? 'Sin detalle',
          recomendacion: a.recommendation,
          animal_record: a.animal?.record ?? a.animal_record,
          tipo: a.alert_type ?? '',
        }),
      );

      // Filtrar operaciones pendientes que sean creaciones de animales
      const pAnimales = pendingOps.filter(op => 
        (op.url.includes('/animals') && op.method === 'POST') || 
        op.entity_type === 'animal'
      ).length;

      const criticas = alertas.filter((a) => a.nivel === 'Crítica');
      const altas = alertas.filter((a) => a.nivel === 'Alta');
      const medias = alertas.filter((a) => a.nivel === 'Media' || a.nivel === 'Baja');

      setEstado({
        loading: false,
        totalAnimales: ((animalesStats as any)?.total ?? 0) + pAnimales,
        alertasCriticas: criticas,
        alertasAltas: altas,
        alertasMedias: medias,
        semaforo: calcularSemaforo(criticas.length, altas.length),
      });
    } catch {
      setEstado((prev) => ({ ...prev, loading: false }));
    }
  }, []);

  useEffect(() => {
    cargarDatos();
  }, [cargarDatos]);

  const handleRefrescar = async () => {
    setRefrescando(true);
    await cargarDatos();
    setRefrescando(false);
  };

  const handleResolver = async (id: number) => {
    try {
      await alertService.resolve(id);
      await cargarDatos();
    } catch { /* continuar */ }
  };

  const totalAlertas =
    estado.alertasCriticas.length + estado.alertasAltas.length + estado.alertasMedias.length;

  // ─── Render ───────────────────────────────────────────────────────────────
  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950">
      {/* ── CABECERA PREMIUM ─────────────────────────────────────────── */}
      <header className="relative bg-slate-900 overflow-hidden pb-12 pt-8 text-white px-6">
