          <h2 className="mb-4 px-2 text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">Explorar</h2>
          <div className="grid grid-cols-2 gap-4">
            {[
              {
                icono: <QrCode className="h-6 w-6" />,
                label: 'ESCANEAR',
                ruta: '/scanner',
                bg: 'bg-slate-800 shadow-slate-900/20',
              },
              {
                icono: <Beef className="h-6 w-6" />,
                label: 'ANIMALES',
                ruta: '/operario/animals',
                bg: 'bg-emerald-800 shadow-emerald-900/20',
              },
              {
                icono: <ClipboardList className="h-6 w-6" />,
