          <Badge variant="outline" className="cursor-pointer hover:bg-emerald-50 text-sm px-4 py-1">Agricultura</Badge>
          <Badge variant="outline" className="cursor-pointer hover:bg-emerald-50 text-sm px-4 py-1">PDFs</Badge>
