      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredMaterials.map(mat => (
            <Card key={mat.id} className="group hover:shadow-2xl transition-all duration-300 border-emerald-100 flex flex-col relative overflow-hidden">
