                <div className="flex items-center gap-4 text-xs text-gray-500 font-medium">
                  <span className="flex items-center gap-1 bg-gray-100 px-2 py-1 rounded-md">Nivel: {mat.reading_level || 'General'}</span>
                  <span className="flex items-center gap-1 bg-gray-100 px-2 py-1 rounded-md">{mat.content_type}</span>
                </div>
              </CardContent>
              <CardFooter className="pt-4 border-t bg-gray-50/50 rounded-b-xl flex justify-between items-center gap-2">
                {cachedMap[mat.id] ? (
                  <Button 
                    variant="outline" 
                    className="w-full text-emerald-700 border-emerald-300 bg-emerald-50/50 hover:bg-emerald-100"
                    onClick={() => mat.local_uri && window.open(mat.local_uri, '_blank')}
