                  </Button>
                ) : (
                  <Button 
                    variant="default" 
                    className="w-full bg-emerald-600 hover:bg-emerald-700 text-white shadow-lg"
                    onClick={() => handleDownload(mat)}
                  >
                    <Download className="w-4 h-4 mr-2" />
                    Guardar para Offline
                  </Button>
                )}
              </CardFooter>
            </Card>
          ))}
        </div>
      )}

      {!isLoading && filteredMaterials.length === 0 && (
        <div className="text-center py-20 bg-emerald-50/50 rounded-2xl border-2 border-dashed border-emerald-200">
          <Book className="w-16 h-16 text-emerald-300 mx-auto mb-4" />
          <h3 className="text-xl font-bold text-emerald-800">No se encontraron materiales</h3>
          <p className="text-emerald-600 mt-2">Intenta buscar con otros términos o pide al Instructor que suba la guía.</p>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/shared/ui/dialog";
import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { Label } from "@/shared/ui/label";
import { Textarea } from "@/shared/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/ui/select";
import { offlineLearningService } from '@/entities/campesino/api/campesino.service';
import { useToast } from '@/shared/hooks/use-toast';
import { Loader2, Upload } from 'lucide-react';

interface MaterialUploadDialogProps {
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess: () => void;
}

export function MaterialUploadDialog({ isOpen, onOpenChange, onSuccess }: MaterialUploadDialogProps) {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { toast } = useToast();
  const [formData, setFormData] = useState({
    title: '',
    category: '',
    content_type: 'TEXT',
    summary: '',
    local_uri: '',
    reading_level: 'General',
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.title || !formData.category) {
      toast({
        title: "Campos incompletos",
        description: "El título y la categoría son obligatorios.",
        variant: "destructive",
      });
      return;
    }

    setIsSubmitting(true);
    try {
      await offlineLearningService.createOne(formData);
      toast({
        title: "Material subido",
        description: "El material se ha guardado correctamente en la biblioteca.",
      });
      onSuccess();
      onOpenChange(false);
      setFormData({
        title: '',
        category: '',
        content_type: 'TEXT',
        summary: '',
        local_uri: '',
        reading_level: 'General',
      });
    } catch (error) {
      console.error("Error uploading material:", error);
      toast({
        title: "Error al guardar",
        description: "No se pudo subir el material. Inténtalo de nuevo.",
        variant: "destructive",
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Upload className="w-5 h-5 text-emerald-600" />
            Subir Nuevo Material
          </DialogTitle>
          <DialogDescription>
            Agrega guías, manuales o videos para que los campesinos puedan consultarlos offline.
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4 py-4">
          <div className="space-y-2">
            <Label htmlFor="title">Título del Material</Label>
            <Input
              id="title"
              placeholder="Ej: Manual de BPG en Porcinos"
              value={formData.title}
              onChange={(e) => setFormData({ ...formData, title: e.target.value })}
              required
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="category">Categoría</Label>
              <Input
                id="category"
                placeholder="Ej: Sanidad Animal"
                value={formData.category}
                onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="content_type">Tipo de Contenido</Label>
              <Select
                value={formData.content_type}
                onValueChange={(val) => setFormData({ ...formData, content_type: val })}
              >
                <SelectTrigger id="content_type">
                  <SelectValue placeholder="Selecciona tipo" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="TEXT">Texto / Guía</SelectItem>
                  <SelectItem value="PDF">Documento PDF</SelectItem>
                  <SelectItem value="VIDEO">Video Tutorial</SelectItem>
                  <SelectItem value="AUDIO">Podcast / Audio</SelectItem>
                  <SelectItem value="IMAGE">Infografía</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="local_uri">URL del archivo o recurso</Label>
            <Input
              id="local_uri"
              placeholder="https://cdn.villaluz.com/guias/bpg.pdf"
              value={formData.local_uri}
              onChange={(e) => setFormData({ ...formData, local_uri: e.target.value })}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="reading_level">Nivel Sugerido</Label>
            <Input
              id="reading_level"
              placeholder="Ej: Técnico, General, Avanzado"
              value={formData.reading_level}
              onChange={(e) => setFormData({ ...formData, reading_level: e.target.value })}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="summary">Resumen Corto</Label>
            <Textarea
              id="summary"
              placeholder="Describe brevemente de qué trata este material..."
              className="min-h-[100px]"
              value={formData.summary}
              onChange={(e) => setFormData({ ...formData, summary: e.target.value })}
            />
          </div>

          <DialogFooter className="pt-4">
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              disabled={isSubmitting}
            >
              Cancelar
            </Button>
            <Button
              type="submit"
              className="bg-emerald-600 hover:bg-emerald-700 text-white"
              disabled={isSubmitting}
            >
              {isSubmitting ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Guardando...
                </>
              ) : (
                "Subir a Biblioteca"
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { useToast } from '@/app/providers/ToastContext';
import { useOnlineStatus } from '@/shared/hooks/useOnlineStatus';
import { offlineQueue } from '@/shared/api/offline/offlineQueue';
import { animalsService } from '@/entities/animal/api/animal.service';
import { controlService } from '@/entities/control/api/control.service';
import { getTodayColombia } from '@/shared/utils/dateUtils';
import {
  QuickFormShell,
  QCard,
  QField,
  QLabel,
  QInput,
  QSelect,
  QChipGroup,
  QSubmitButton,
} from './QuickFormShell';

// ─── Tipos ────────────────────────────────────────────────────────────────────
type EstadoSalud = 'Excelente' | 'Bueno' | 'Regular' | 'Malo';

const ESTADOS_SALUD: { label: string; value: EstadoSalud }[] = [
  { label: '😄 Excelente', value: 'Excelente' },
  { label: '🙂 Bueno', value: 'Bueno' },
  { label: '😐 Regular', value: 'Regular' },
  { label: '😟 Malo', value: 'Malo' },
];

// ─── Componente ──────────────────────────────────────────────────────────────
export default function QuickControl() {
  const navigate = useNavigate();
  const { showToast } = useToast();
  const { isOnline } = useOnlineStatus();

  const [animalId, setAnimalId] = useState('');
  const [peso, setPeso] = useState('');
  const [fecha, setFecha] = useState(getTodayColombia());
  const [salud, setSalud] = useState<EstadoSalud>('Bueno');
  const [guardando, setGuardando] = useState(false);
  const [cargandoAnimales, setCargandoAnimales] = useState(true);
  const [animales, setAnimales] = useState<{ value: string; label: string }[]>([]);

  // ── Cargar animales vivos ─────────────────────────────────────────────────
  const cargarAnimales = useCallback(async () => {
    try {
      const resp = await animalsService.getAnimals({ limit: 200, status: 'Vivo' });
      const lista = Array.isArray(resp) ? resp : (resp as any)?.data ?? [];
      setAnimales(
        lista.map((a: any) => ({
          value: String(a.id),
          label: `🐄 ${a.record}${a.breed?.name ? ` — ${a.breed.name}` : ''}`,
        })),
      );
    } catch {
      showToast('No se pudo cargar la lista de animales', 'error');
    } finally {
      setCargandoAnimales(false);
    }
  }, [showToast]);

  useEffect(() => {
    cargarAnimales();
  }, [cargarAnimales]);

  // ── Submit ────────────────────────────────────────────────────────────────
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!animalId) {
      showToast('Selecciona el animal', 'error');
      return;
    }
    if (!peso || Number(peso) <= 0) {
      showToast('Ingresa un peso válido', 'error');
      return;
    }

    setGuardando(true);

    const payload = {
      animal_id: Number(animalId),
      checkup_date: fecha,
      weight: Number(peso),
      health_status: salud,
    };

    try {
      if (!isOnline) {
        await offlineQueue.enqueue('POST', 'controls', payload);
        showToast('✅ Guardado sin señal. Se enviará cuando vuelva la conexión.', 'success');
      } else {
        await controlService.createControl(payload);
        showToast('✅ Control registrado.', 'success');
      }
      navigate('/operario/dashboard');
    } catch {
      showToast('No se pudo guardar el control. Intenta de nuevo.', 'error');
    } finally {
      setGuardando(false);
    }
  };

  // ─── Render ───────────────────────────────────────────────────────────────
  return (
    <QuickFormShell
      titulo="Pesar Animal"
      emoji="⚖️"
      colorHeader="bg-blue-700"
    >
      <form onSubmit={handleSubmit} className="space-y-4">
        {/* Animal */}
        <QCard>
          <QField>
            <QLabel htmlFor="animal">¿Cuál animal vas a pesar?</QLabel>
            <QSelect
              id="animal"
              value={animalId}
              onChange={setAnimalId}
              placeholder={cargandoAnimales ? 'Cargando animales...' : '— Selecciona —'}
              options={animales}
              disabled={cargandoAnimales}
            />
          </QField>
        </QCard>

        {/* Peso */}
        <QCard>
          <QField>
            <QLabel htmlFor="peso">Peso en kilogramos (kg)</QLabel>
            <QInput
              id="peso"
              type="number"
              inputMode="decimal"
              value={peso}
              onChange={(e) => setPeso(e.target.value)}
              placeholder="Ej: 419"
              min="1"
              max="2000"
              required
            />
          </QField>
        </QCard>

        {/* Estado de salud — chips táctiles */}
        <QCard>
          <QField>
            <QLabel>¿Cómo está el animal?</QLabel>
            <QChipGroup<EstadoSalud>
              value={salud}
              options={ESTADOS_SALUD}
              onChange={setSalud}
            />
          </QField>
        </QCard>

        {/* Fecha */}
        <QCard>
          <QField>
            <QLabel htmlFor="fecha">Fecha del pesaje</QLabel>
            <QInput
              id="fecha"
              type="date"
              value={fecha}
              onChange={(e) => setFecha(e.target.value)}
              required
            />
          </QField>
        </QCard>

        {/* Submit */}
        <QSubmitButton loading={guardando} color="bg-blue-700">
          ⚖️ Guardar Pesaje
        </QSubmitButton>
      </form>
    </QuickFormShell>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { useToast } from '@/app/providers/ToastContext';
import { useOnlineStatus } from '@/shared/hooks/useOnlineStatus';
import { offlineQueue } from '@/shared/api/offline/offlineQueue';
import { animalsService } from '@/entities/animal/api/animal.service';
import { diseaseService } from '@/entities/disease/api/disease.service';
import { animalDiseasesService } from '@/entities/animal-disease/api/animalDiseases.service';
import { getTodayColombia } from '@/shared/utils/dateUtils';
import {
  QuickFormShell,
  QCard,
  QField,
  QLabel,
  QInput,
  QSelect,
  QChipGroup,
  QSubmitButton,
} from './QuickFormShell';

type EstadoEnfermedad = 'Activo' | 'Recuperado' | 'Crónico';

const ESTADOS: { label: string; value: EstadoEnfermedad }[] = [
  { label: '🔴 Activo', value: 'Activo' },
  { label: '🟢 Recuperado', value: 'Recuperado' },
  { label: '🟡 Crónico', value: 'Crónico' },
];

export default function QuickDisease() {
  const navigate = useNavigate();
  const { showToast } = useToast();
  const { isOnline } = useOnlineStatus();

  const [animalId, setAnimalId] = useState('');
  const [enfermedadId, setEnfermedadId] = useState('');
  const [estado, setEstado] = useState<EstadoEnfermedad>('Activo');
  const [fecha, setFecha] = useState(getTodayColombia());
  const [guardando, setGuardando] = useState(false);
  const [cargando, setCargando] = useState(true);
  const [animales, setAnimales] = useState<{ value: string; label: string }[]>([]);
  const [enfermedades, setEnfermedades] = useState<{ value: string; label: string }[]>([]);

  const cargarDatos = useCallback(async () => {
    try {
      const [respAnimales, respEnfermedades] = await Promise.all([
        animalsService.getAnimals({ limit: 200, status: 'Vivo' }),
        diseaseService.getDiseases({ limit: 100 }),
      ]);

      const listaA = Array.isArray(respAnimales) ? respAnimales : (respAnimales as any)?.data ?? [];
      const listaE = Array.isArray(respEnfermedades) ? respEnfermedades : (respEnfermedades as any)?.data ?? [];

      setAnimales(listaA.map((a: any) => ({
        value: String(a.id),
        label: `🐄 ${a.record}${a.breed?.name ? ` — ${a.breed.name}` : ''}`,
      })));

      setEnfermedades(listaE.map((d: any) => ({
        value: String(d.id),
        label: `🦠 ${d.name ?? `Enfermedad ${d.id}`}`,
      })));
    } catch {
      showToast('No se pudieron cargar los datos', 'error');
    } finally {
      setCargando(false);
    }
  }, [showToast]);

  useEffect(() => { cargarDatos(); }, [cargarDatos]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!animalId) { showToast('Selecciona el animal', 'error'); return; }
    if (!enfermedadId) { showToast('Selecciona la enfermedad', 'error'); return; }

    setGuardando(true);
    const payload = {
      animal_id: Number(animalId),
      disease_id: Number(enfermedadId),
      diagnosis_date: fecha,
      status: estado,
    };

    try {
      if (!isOnline) {
        await offlineQueue.enqueue('POST', 'animal-diseases', payload);
        showToast('✅ Guardado sin señal. Se enviará cuando vuelva la conexión.', 'success');
      } else {
        await animalDiseasesService.createAnimalDisease(payload);
        showToast('✅ Enfermedad registrada.', 'success');
      }
      navigate('/operario/dashboard');
    } catch {
      showToast('No se pudo guardar. Intenta de nuevo.', 'error');
    } finally {
      setGuardando(false);
    }
  };

  return (
    <QuickFormShell titulo="Animal Enfermo" emoji="🩺" colorHeader="bg-red-700">
      <form onSubmit={handleSubmit} className="space-y-4">

        {/* Animal */}
        <QCard>
          <QField>
            <QLabel htmlFor="animal">¿Cuál animal está enfermo?</QLabel>
            <QSelect
              id="animal"
              value={animalId}
              onChange={setAnimalId}
              placeholder={cargando ? 'Cargando...' : '— Selecciona el animal —'}
              options={animales}
              disabled={cargando}
            />
          </QField>
        </QCard>

        {/* Enfermedad */}
        <QCard>
          <QField>
            <QLabel htmlFor="enfermedad">¿Qué enfermedad tiene?</QLabel>
            <QSelect
              id="enfermedad"
              value={enfermedadId}
              onChange={setEnfermedadId}
              placeholder={cargando ? 'Cargando...' : '— Selecciona la enfermedad —'}
              options={enfermedades}
              disabled={cargando}
            />
          </QField>
        </QCard>

        {/* Estado actual — chips */}
        <QCard>
          <QField>
            <QLabel>¿Cómo está ahora el animal?</QLabel>
            <QChipGroup<EstadoEnfermedad>
              value={estado}
              options={ESTADOS}
              onChange={setEstado}
            />
          </QField>
        </QCard>

        {/* Fecha */}
        <QCard>
          <QField>
            <QLabel htmlFor="fecha">Fecha en que lo notaste</QLabel>
            <QInput
              id="fecha"
              type="date"
              value={fecha}
              onChange={(e) => setFecha(e.target.value)}
              required
            />
          </QField>
        </QCard>

        <QSubmitButton loading={guardando} color="bg-red-700">
          🩺 Guardar Novedad
        </QSubmitButton>
      </form>
    </QuickFormShell>
  );
}

/**
 * QuickFormShell — Layout compartido de formularios rápidos de campo.
 * Diseñado para máxima usabilidad con manos sucias, pantallas pequeñas
 * y condiciones de baja luz o sol directo.
 */
import React from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { ArrowLeft, WifiOff } from 'lucide-react';
import { useOnlineStatus } from '@/shared/hooks/useOnlineStatus';

interface QuickFormShellProps {
  titulo: string;
  emoji: string;
  colorHeader: string;        // Tailwind bg class
  children: React.ReactNode;
  volver?: string;            // ruta de regreso (default: /operario/dashboard)
