export function QuickFormShell({
  titulo,
  emoji,
  colorHeader,
  children,
  volver = '/operario/dashboard',
}: QuickFormShellProps) {
  const navigate = useNavigate();
  const { isOnline, pendingOperations } = useOnlineStatus();

  return (
    <div className="min-h-screen bg-[#f5f0e8]">
      {/* ── CABECERA COLOREADA ───────────────────────────────────── */}
