        <button
          onClick={() => navigate(volver)}
          className="mb-3 flex items-center gap-2 rounded-2xl bg-white/20 px-3 py-2 text-sm font-black transition hover:bg-white/30"
        >
          <ArrowLeft className="h-5 w-5" />
          Volver
        </button>

        <div className="flex items-center gap-3">
          <span className="text-5xl leading-none">{emoji}</span>
          <div>
            <h1 className="text-2xl font-black leading-tight">{titulo}</h1>
            {/* Estado de red */}
            <span
              className={`mt-1 inline-flex items-center gap-1 rounded-full px-2.5 py-0.5 text-xs font-bold ${
                isOnline
                  ? 'bg-white/20 text-white'
                  : 'bg-amber-400 text-amber-900'
              }`}
            >
              {!isOnline && <WifiOff className="h-3 w-3" />}
              {isOnline ? 'Con señal' : 'Sin señal — se guardará local'}
            </span>
          </div>
        </div>

        {/* Cola offline */}
        {pendingOperations > 0 && (
          <div className="mt-3 rounded-2xl bg-white/10 px-3 py-1.5 text-xs font-bold text-white/90">
            📤 {pendingOperations} registro(s) pendiente(s) de enviar
          </div>
        )}
      </header>

      {/* ── CUERPO ──────────────────────────────────────────────── */}
      <main className="mx-auto max-w-lg px-4 py-5">
        <motion.div
          initial={{ opacity: 0, y: 16 }}
          animate={{ opacity: 1, y: 0 }}
          className="space-y-4"
        >
          {children}
        </motion.div>
      </main>
    </div>
  );
}

// ─── Primitivas de campo reutilizables ────────────────────────────────────────

/** Etiqueta grande para campo */
export function QLabel({ children, htmlFor }: { children: React.ReactNode; htmlFor?: string }) {
  return (
    <label htmlFor={htmlFor} className="mb-1.5 block text-base font-black text-gray-700">
      {children}
    </label>
  );
}

/** Input grande táctil */
export function QInput(props: React.InputHTMLAttributes<HTMLInputElement>) {
  return (
    <input
      {...props}
      className={`w-full rounded-2xl border-4 border-gray-300 bg-white px-4 py-3.5 text-xl font-bold text-gray-800 outline-none transition
        focus:border-gray-700 focus:ring-0
        disabled:opacity-50 ${props.className ?? ''}`}
    />
  );
}

/** Selector grande tipo "chip" — para opciones finitas */
export function QChipGroup<T extends string>({
  value,
  options,
  onChange,
}: {
  value: T;
  options: { label: string; value: T; color?: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap gap-2">
      {options.map((opt) => (
        <button
          key={opt.value}
          type="button"
          onClick={() => onChange(opt.value)}
          className={`rounded-2xl border-4 px-5 py-2.5 text-base font-black transition ${
            value === opt.value
              ? `border-gray-800 bg-gray-800 text-white shadow-lg`
              : 'border-gray-300 bg-white text-gray-700 hover:border-gray-500'
          } ${opt.color ?? ''}`}
        >
          {opt.label}
        </button>
      ))}
    </div>
  );
}

/** Select nativo grande (mejor que Radix en móvil) */
export function QSelect({
  id,
  value,
  onChange,
  placeholder,
  options,
  disabled,
}: {
  id?: string;
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
  options: { value: string; label: string }[];
  disabled?: boolean;
}) {
  return (
    <select
      id={id}
      value={value}
      disabled={disabled}
      onChange={(e) => onChange(e.target.value)}
      className="w-full rounded-2xl border-4 border-gray-300 bg-white px-4 py-3.5 text-xl font-bold text-gray-800 outline-none transition focus:border-gray-700 disabled:opacity-50"
    >
      {placeholder && (
        <option value="" disabled>
          {placeholder}
        </option>
      )}
      {options.map((o) => (
        <option key={o.value} value={o.value}>
          {o.label}
        </option>
      ))}
    </select>
  );
}

/** Botón de acción principal */
export function QSubmitButton({
  loading,
  children,
  color = 'bg-gray-900',
}: {
  loading?: boolean;
  children: React.ReactNode;
  color?: string;
}) {
  return (
    <button
      type="submit"
      disabled={loading}
      className={`w-full rounded-3xl ${color} py-5 text-xl font-black text-white shadow-xl transition
        hover:brightness-110 active:scale-95 disabled:opacity-60`}
    >
      {loading ? (
        <span className="flex items-center justify-center gap-3">
          <span className="h-5 w-5 animate-spin rounded-full border-4 border-white/30 border-t-white" />
          Guardando...
        </span>
      ) : (
        children
      )}
    </button>
  );
}

/** Sección de campo con espaciado */
export function QField({ children }: { children: React.ReactNode }) {
