import type { AxiosRequestConfig, AxiosResponse } from 'axios';
import api from '@/shared/api/client';
import type { ApiErrorCode, StandardApiErrorPayload } from './error-parser';
export { ApiFetchError } from './error-parser';

/**
 * apiFetch - Deprecated: Use apiClient (shared/api/client.ts) directly.
 * This remains for backward compatibility but utilizes the centralized interceptors
 * for error parsing, CSRF retries, and offline queueing.
 */
export async function apiFetch<T = any>(
  config: AxiosRequestConfig & { retryOnCsrfError?: boolean; __csrfRetried?: boolean }
): Promise<AxiosResponse<T>> {
  // api.request already handles:
  // 1. Error parsing into ApiFetchError
  // 2. Auth re-logging
  // 3. CSRF retries
  // 4. Offline queueing (non-GET)
  return api.request<T>(config);
}

export default apiFetch;

import { forceClientLogout } from './auth-utils';

export function isTokenExpired(err: any): boolean {
  const status = err?.response?.status ?? err?.status;
  const data = err?.response?.data ?? err?.data;
  const code = (data?.code || data?.error || data?.detail || data?.message || '').toString().toUpperCase();
  return status === 401 && (code.includes('TOKEN_EXPIRED') || code.includes('EXPIRED'));
}

export function extractAuthErrorDetails(err: any) {
  const payload = err?.response?.data;
  const details = payload?.error?.details ?? payload?.error?.detail ?? payload?.details ?? payload?.detail ?? {};
  const code = (payload?.error?.code || payload?.code || payload?.error || '').toString().toUpperCase();
  const exceptionClass = (details?.exception_class || details?.exceptionClass || '').toString();
  const clientAction = (details?.client_action || details?.clientAction || '').toString();
  const logoutUrl = details?.logout_url || details?.logoutUrl;
  const loginUrl = details?.login_url || details?.loginUrl;
  const traceId = payload?.error?.trace_id || payload?.error?.traceId;
  return { code, exceptionClass, clientAction, logoutUrl, loginUrl, rawDetails: details, traceId };
}

export function shouldForceLogout(err: any): {
  shouldForce: boolean;
  logoutUrl?: string;
  loginUrl?: string;
  details?: any;
  traceId?: string;
  shouldRefresh?: boolean;
} {
  const { code, clientAction, logoutUrl, loginUrl, rawDetails, traceId } = extractAuthErrorDetails(err);

  const needsClear = clientAction === 'CLEAR_AUTH_AND_RELOGIN' ||
    rawDetails?.should_clear_auth === true ||
    rawDetails?.shouldClearAuth === true;

  const needsRefresh = clientAction === 'ATTEMPT_REFRESH';

  const codeIndicatesExpiry =
    code === 'TOKEN_EXPIRED' ||
    code === 'TOKEN_EXPIRED_ERROR' ||
    code === 'JWT_ERROR' ||
    code === 'MISSING_TOKEN' ||
    code === 'UNAUTHORIZED';

  if (needsClear) {
    return { shouldForce: true, logoutUrl, loginUrl, details: rawDetails, traceId, shouldRefresh: false };
  }

  if (needsRefresh) {
    return { shouldForce: false, logoutUrl, loginUrl, details: rawDetails, traceId, shouldRefresh: true };
  }

  if (codeIndicatesExpiry) {
    return { shouldForce: false, logoutUrl, loginUrl, details: rawDetails, traceId, shouldRefresh: true };
  }

  return {
    shouldForce: false,
    logoutUrl,
    loginUrl,
    details: rawDetails,
    traceId,
    shouldRefresh: false
  };
}

export function isCsrfError(err: any): boolean {
  const status = err?.response?.status ?? err?.status;
  const data = err?.response?.data ?? err?.data;
  const text = (data?.code || data?.error || data?.detail || data?.message || '').toString();
  const upper = text.toUpperCase();
  return (status === 401 || status === 400 || status === 403) && upper.includes('CSRF');
}

export async function forceLogoutFromApiError(
  code?: string,
  details?: any
): Promise<void> {
  const clientAction = (details?.client_action || details?.clientAction || '').toString();
  const shouldClear =
    clientAction === 'CLEAR_AUTH_AND_RELOGIN' ||
    details?.should_clear_auth === true ||
    details?.shouldClearAuth === true;

  if (!shouldClear) return;

  const reason = String(code || 'expired').toLowerCase().includes('missing') ? 'missing' : 'expired';
  const logoutUrl = details?.logout_url || details?.logoutUrl;
  const loginUrl = details?.login_url || details?.loginUrl;
  await forceClientLogout(reason, { logoutUrl, loginUrl });
}

import { getCookie } from '@/shared/utils/cookieUtils';
import { toast } from "@/shared/hooks/use-toast";
import { 
  API_CONFIG, 
  AUTH_SESSION_ACTIVE_KEY, 
  SESSION_STORAGE_KEYS, 
  SESSION_COOKIE_CANDIDATES,
  AUTH_STATE_KEYS
} from './config';

const toastRecent = new Map<string, number>();

export const showToastOnce = (key: string, options: Parameters<typeof toast>[0]) => {
  const now = Date.now();
  const last = toastRecent.get(key) || 0;
  if (now - last < API_CONFIG.toastDedupMs) return;
  toastRecent.set(key, now);
  toast(options);
};

export const hasClientSession = (): boolean => {
  try {
    if (typeof sessionStorage !== 'undefined') {
      if (sessionStorage.getItem(AUTH_SESSION_ACTIVE_KEY) !== '1') return false;
    }
  } catch { /* noop */ }

  try {
    const keys = [...SESSION_STORAGE_KEYS];
    for (const key of keys) {
      if (typeof localStorage !== 'undefined' && localStorage.getItem(key)?.trim().length) return true;
      if (typeof sessionStorage !== 'undefined' && sessionStorage.getItem(key)?.trim().length) return true;
    }
  } catch { /* noop */ }

  return SESSION_COOKIE_CANDIDATES.some(name => {
    try { return !!getCookie(name); } catch { return false; }
  });
};

export const readStoredToken = (): string | null => {
  try {
    // Intentar leer de múltiples fuentes para máxima resiliencia
    return localStorage.getItem(API_CONFIG.authStorageKey) || 
           localStorage.getItem('access_token') || 
           sessionStorage.getItem(API_CONFIG.authStorageKey) ||
           sessionStorage.getItem('access_token');
  } catch {
    return null;
  }
};

export const persistStoredToken = (token: string): void => {
  try {
    if (!token) return;
    localStorage.setItem(API_CONFIG.authStorageKey, token);
    localStorage.setItem('access_token', token);
    sessionStorage.setItem(API_CONFIG.authStorageKey, token);
    sessionStorage.setItem('access_token', token);
  } catch { /* noop */ }
};

export const clearClientTokens = () => {
  const keys = new Set([...SESSION_STORAGE_KEYS, ...AUTH_STATE_KEYS]);
  keys.forEach(key => {
    try { localStorage.removeItem(key); } catch { /* noop */ }
    try { sessionStorage.removeItem(key); } catch { /* noop */ }
  });
};

export async function callBackendLogout(logoutUrl?: string) {
  const target = logoutUrl && /^https?:\/\//i.test(logoutUrl)
    ? logoutUrl
    : `${API_CONFIG.baseURL?.replace(/\/$/, '') || ''}${logoutUrl
      ? logoutUrl.startsWith('/') ? logoutUrl : `/${logoutUrl}`
      : '/auth/logout'}`;
  try {
    await fetch(target, { method: 'POST', credentials: 'include', headers: { 'Accept': 'application/json' } });
  } catch (err) {
    if (API_CONFIG.debugMode) console.warn('[api] Logout fetch falló:', err);
  }
}

let forceLogoutPromise: Promise<void> | null = null;

export async function forceClientLogout(reason = 'expired', options?: { logoutUrl?: string; loginUrl?: string }) {
  if (forceLogoutPromise) return forceLogoutPromise;
  forceLogoutPromise = (async () => {
    clearClientTokens();
    await callBackendLogout(options?.logoutUrl);
    if (typeof window !== 'undefined') {
      const loginPath = options?.loginUrl || API_CONFIG.loginPath || '/login';
      const loginUrl = new URL(loginPath, window.location.origin);
      loginUrl.searchParams.set('reason', reason);
      const target = loginUrl.toString();

      if (reason === 'expired') {
        showToastOnce('session-expired', {
          title: "Sesión expirada",
          description: "Tu sesión ha expirado. Por favor inicia sesión nuevamente.",
          variant: "destructive",
        });
      }

      if (window.location.pathname !== loginUrl.pathname) {
        window.location.assign(target);
      }
    }
  })().finally(() => { forceLogoutPromise = null; });
  return forceLogoutPromise;
}

import api from './client';
import { PageResult } from '@/shared/types/common.types';
import { extractListFromResponse } from './listExtractor';
import { normalizePagination } from './responseNormalizer';
import type { PaginatedResponse } from '@/shared/api/generated/swaggerTypes';
import { getDefaultLimitByDevice } from '@/shared/utils/viewportUtils';
import { API_CONFIG } from '@/shared/api/config';
import {
  getIndexedDBCache,
  setIndexedDBCache,
  invalidateIndexedDBCacheByPrefix
} from '@/shared/api/cache/indexedDBCache';
import { isDevMode } from '@/shared/utils/viteEnv';
import { offlineQueue } from '@/shared/api/offline/offlineQueue';

const __DEV__ = isDevMode();

interface ServiceOptions {
  enableCache?: boolean;
  cacheTimeout?: number;
  preferredListKeys?: string[];
  retryAttempts?: number;
  timeout?: number;
  persistCache?: boolean;
}

function isOfflineError(error: any): boolean {
  return !navigator.onLine || error?.code === 'ERR_NETWORK' || error?.status === 0 || error?.message?.includes('Network Error');
}

function getCurrentFincaCacheScope(): string {
  try {
    if (typeof window === 'undefined') return '';
    const raw = window.sessionStorage?.getItem('auth:user');
    const parsed = raw ? JSON.parse(raw) : null;
    const user = parsed?.user ?? parsed;
    const fincaId = user?.finca_id ?? user?.finca?.id ?? user?.active_finca_id ?? user?.current_finca_id;
    return fincaId ? `@finca:${fincaId}` : '';
  } catch {
    return '';
  }
}

// BaseService provides shared CRUD, cache, and offline-queue behavior.
export class BaseService<T> {
  protected endpoint: string;
  protected cache: Map<string, { data: any; timestamp: number }>;
  protected options: ServiceOptions;

  private static readonly OFFLINE_STALE_GRACE_MS = 24 * 60 * 60 * 1000; // 24h para reutilizar datos cuando no hay red

  constructor(endpoint: string, options: ServiceOptions = {}) {
    this.endpoint = endpoint;
    this.options = {
      enableCache: true,
      cacheTimeout: 5 * 60 * 1000, // 5 minutos
      preferredListKeys: [],
      retryAttempts: 3,
      timeout: 30000,
      persistCache: true,
      ...options,
    };
    this.cache = new Map();
  }

  protected getCacheKey(params?: Record<string, any>): string {
    const sortedParams = params ? JSON.stringify(Object.fromEntries(Object.entries(params).sort())) : '';
    return `${this.endpoint}${getCurrentFincaCacheScope()}:${sortedParams}`;
  }

  protected async getFromCache(key: string): Promise<T | T[] | PageResult<T> | PaginatedResponse<T> | null> {
    if (!this.options.enableCache) return null;

    const memCached = this.cache.get(key);
    if (memCached && (Date.now() - memCached.timestamp < this.options.cacheTimeout!)) {
      return memCached.data;
    }

    const isOnline = typeof navigator === 'undefined' || navigator.onLine !== false;
    if (isOnline && !API_CONFIG.idbReadOnline) return null;

    try {
      const idbKey = `service:${key}`;
      const idbData = await getIndexedDBCache<any>(idbKey, {
        allowStaleWhenOffline: true,
        offlineGraceMs: BaseService.OFFLINE_STALE_GRACE_MS,
      });
      if (idbData) {
        this.cache.set(key, { data: idbData, timestamp: Date.now() });
        return idbData;
      }
    } catch (error) {
      if (__DEV__) console.warn('[BaseService] Error leyendo cache IndexedDB:', error);
    }
    return null;
  }

  protected setCache(key: string, data: any): void {
    if (!this.options.enableCache) return;
    this.cache.set(key, { data, timestamp: Date.now() });
    const idbKey = `service:${key}`;
    void setIndexedDBCache(idbKey, data, this.options.cacheTimeout).catch(err => {
      if (__DEV__) console.warn('[BaseService] Error escribiendo cache IndexedDB:', err);
    });
  }

  public async clearCache(): Promise<void> {
    this.cache.clear();
    const prefix = `service:${this.endpoint}`;
    try {
      await invalidateIndexedDBCacheByPrefix(prefix);
    } catch (err) {
      if (__DEV__) console.warn('[BaseService] Error limpando cache IDB:', err);
    }
  }

  async getAll(params?: Record<string, any>): Promise<T[]> {
    const normalizedParams = BaseService.buildListParams(params || {});
    const { cancelToken, signal, ...restParams } = normalizedParams as any;

    const originalParams = (params || {}) as Record<string, any>;
    const hasExplicitLimit = Object.prototype.hasOwnProperty.call(originalParams, 'limit') || Object.prototype.hasOwnProperty.call(originalParams, 'per_page');
    const hasExplicitPage = Object.prototype.hasOwnProperty.call(originalParams, 'page');

    const sanitizedParams: Record<string, any> = { ...restParams };
    if (!hasExplicitPage) delete sanitizedParams.page;
    if (!hasExplicitLimit) delete sanitizedParams.limit;

    if (hasExplicitLimit && (sanitizedParams.limit == null) && sanitizedParams.per_page != null) {
      sanitizedParams.limit = sanitizedParams.per_page;
    }
    delete sanitizedParams.per_page;
    sanitizedParams.sort_dir = sanitizedParams.sort_dir ?? sanitizedParams.sort_order;
    sanitizedParams.q = sanitizedParams.q ?? sanitizedParams.search;

    delete sanitizedParams.sort_order;
    delete sanitizedParams.search;

    const requestParams: Record<string, any> = { ...sanitizedParams };
    const shouldBypassCache = Object.prototype.hasOwnProperty.call(requestParams, 'cache_bust') && requestParams.cache_bust != null;
    const cacheKeyParams = { ...sanitizedParams };
    if (Object.prototype.hasOwnProperty.call(cacheKeyParams, 'cache_bust')) {
      delete (cacheKeyParams as any).cache_bust;
    }
    const cacheKey = this.getCacheKey(cacheKeyParams);
    const cached = shouldBypassCache ? null : await this.getFromCache(cacheKey);
    if (cached) return cached as T[];

    try {
      const response = await api.get(this.endpoint, { params: requestParams, cancelToken, signal });
      const data = extractListFromResponse(response, this.options.preferredListKeys);
      this.setCache(cacheKey, data);
      return data;
    } catch (e: any) {
      if (isOfflineError(e) && cached) {
        if (__DEV__) console.warn('[GET all] offline fallback from cache for', this.endpoint);
        return cached as T[];
      }
      throw e;
    }
  }

  async getPaginated(params?: Record<string, any>): Promise<PaginatedResponse<T>> {
    const normalizedParams = BaseService.buildListParams(params || {});
    const { cancelToken, signal, ...normalizedWithoutToken } = normalizedParams as any;
    const requestParamsBase: Record<string, any> = { ...normalizedWithoutToken };
    const shouldBypassCache = Object.prototype.hasOwnProperty.call(requestParamsBase, 'cache_bust') && requestParamsBase.cache_bust != null;
    const cacheKeyParams = { ...normalizedWithoutToken };
    if (Object.prototype.hasOwnProperty.call(cacheKeyParams, 'cache_bust')) {
      delete (cacheKeyParams as any).cache_bust;
    }
    const cacheKey = this.getCacheKey(cacheKeyParams);
    const cached = shouldBypassCache ? null : await this.getFromCache(cacheKey);
    if (cached) return cached as unknown as PaginatedResponse<T>;

    const searchValue = normalizedWithoutToken.q ?? normalizedWithoutToken.search;
    const requestParams: Record<string, any> = {
      ...requestParamsBase,
      limit: normalizedWithoutToken.limit,
      sort_dir: normalizedWithoutToken.sort_dir ?? normalizedWithoutToken.sort_order,
      q: searchValue,
      search: searchValue,
      fields: normalizedWithoutToken.fields,
    };
    delete requestParams.per_page;
    delete requestParams.sort_order;

    try {
      const response = await api.get(this.endpoint, { params: requestParams, cancelToken, signal });
      const normalized: PageResult<T> = normalizePagination<T>(response, this.options.preferredListKeys) || {
        items: [],
        total: 0,
        page: 1,
        page_size: 10,
        pages: 0,
      };
      const paginated: PaginatedResponse<T> = {
        data: normalized.items,
        total: normalized.total,
        page: normalized.page,
        limit: normalized.page_size,
        totalPages: normalized.pages,
        hasNextPage: normalized.page < normalized.pages,
        hasPreviousPage: normalized.page > 1,
        rawMeta: { page_size: normalized.page_size, totalPages: normalized.pages }
      };
      this.setCache(cacheKey, paginated);
      return paginated;
    } catch (e: any) {
      if (isOfflineError(e) && cached) {
        if (__DEV__) console.warn('[GET paginated] offline fallback from cache for', this.endpoint);
        return cached as unknown as PaginatedResponse<T>;
      }
      throw e;
    }
  }

  async getById(id: number | string, params?: Record<string, any>): Promise<T> {
    const normalizedParams = BaseService.buildListParams(params || {});
    const { cancelToken, signal, ...normalizedWithoutToken } = normalizedParams as any;
    const requestParams: Record<string, any> = {};
    if (normalizedWithoutToken.fields) requestParams.fields = normalizedWithoutToken.fields;
    if (normalizedWithoutToken.cache_bust != null) requestParams.cache_bust = normalizedWithoutToken.cache_bust;

    const shouldBypassCache = requestParams.cache_bust != null;
    const cacheKeyParams = { id, ...requestParams } as Record<string, any>;
    if (Object.prototype.hasOwnProperty.call(cacheKeyParams, 'cache_bust')) {
      delete cacheKeyParams.cache_bust;
    }
    const cacheKey = this.getCacheKey(cacheKeyParams);
    const cached = shouldBypassCache ? null : await this.getFromCache(cacheKey);
    if (cached) return cached as T;

    try {
      const response = await api.get(`${this.endpoint}/${id}`, { params: requestParams, cancelToken, signal });
      const data = response.data?.data || response.data;
      this.setCache(cacheKey, data);
      return data;
    } catch (e: any) {
      if (isOfflineError(e) && cached) {
        if (__DEV__) console.warn('[GET byId] offline fallback from cache for', this.endpoint, id);
        return cached as T;
      }
      throw e;
    }
  }

  async create(data: Partial<T>): Promise<T> {
    try {
      const response = await api.post(this.endpoint, data);
      await this.clearCache();
      return response.data?.data || response.data;
    } catch (e: any) {
      if (isOfflineError(e)) {
        if (__DEV__) console.info('[BaseService] Offline detected, enqueuing CREATE for', this.endpoint);
        await offlineQueue.enqueue('POST', this.endpoint, data);
        return { ...data, _is_offline_pending: true } as unknown as T;
      }
      throw e;
    }
  }

  async update(id: number | string, data: Partial<T>): Promise<T> {
    try {
      const response = await api.put(`${this.endpoint}/${id}`, data);
      await this.clearCache();
      return response.data?.data || response.data;
    } catch (e: any) {
      if (isOfflineError(e)) {
        if (__DEV__) console.info('[BaseService] Offline detected, enqueuing UPDATE for', this.endpoint, id);
        await offlineQueue.enqueue('PUT', `${this.endpoint}/${id}`, data);
        return { ...data, id, _is_offline_pending: true } as unknown as T;
      }
      throw e;
    }
  }

  async patch(id: number | string, data: Partial<T>): Promise<T> {
    try {
      const response = await api.patch(`${this.endpoint}/${id}`, data);
      await this.clearCache();
      return response.data?.data || response.data;
    } catch (e: any) {
      if (isOfflineError(e)) {
        if (__DEV__) console.info('[BaseService] Offline detected, enqueuing PATCH for', this.endpoint, id);
        await offlineQueue.enqueue('PATCH', `${this.endpoint}/${id}`, data);
        return { ...data, id, _is_offline_pending: true } as unknown as T;
      }
      throw e;
    }
  }

  async delete(id: number | string): Promise<boolean> {
    try {
      await api.delete(`${this.endpoint}/${id}`);
      await this.clearCache();
      return true;
    } catch (e: any) {
      if (isOfflineError(e)) {
        if (__DEV__) console.info('[BaseService] Offline detected, enqueuing DELETE for', this.endpoint, id);
        await offlineQueue.enqueue('DELETE', `${this.endpoint}/${id}`);
        return true; // Pretender éxito para UI, se sincronizará luego
      }
      throw e;
    }
  }

  async search(query: string, params?: Record<string, any>): Promise<T[]> {
    const normalizedParams = BaseService.buildListParams(params || {});
    const searchValue = normalizedParams.search ?? query;
    const searchParams = { ...normalizedParams, q: searchValue, search: searchValue };
    const cacheKey = this.getCacheKey(searchParams);
    const cached = await this.getFromCache(cacheKey);
    if (cached) return cached as T[];

    try {
      const response = await api.get(`${this.endpoint}/search`, { params: searchParams });
      const data = extractListFromResponse(response, this.options.preferredListKeys);
      this.setCache(cacheKey, data);
      return data;
    } catch (e: any) {
      if (isOfflineError(e) && cached) {
        if (__DEV__) console.warn('[SEARCH] offline fallback from cache for', this.endpoint);
        return cached as T[];
      }
      throw e;
    }
  }

  async customRequest<R>(path: string, method: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH', payload: any = null, config: any = {}): Promise<R> {
    const url = `${this.endpoint}/${path}`;
    try {
      const response = await api.request({
        url,
        method,
        data: payload,
        ...config,
      });
      if (['POST', 'PUT', 'PATCH', 'DELETE'].includes(method)) {
        await this.clearCache();
      }
      return response.data?.data || response.data || response;
    } catch (e: any) {
      if (isOfflineError(e) && ['POST', 'PUT', 'PATCH', 'DELETE'].includes(method)) {
        if (__DEV__) console.info('[BaseService] Offline detected, enqueuing CUSTOM for', url);
        await offlineQueue.enqueue(method as any, url, payload, config?.headers);
        return { ...payload, _is_offline_pending: true } as unknown as R;
      }
      throw e;
    }
  }

  public static buildListParams(opts: Record<string, any> = {}): Record<string, any> {
    const {
      page,
      limit,
      per_page,
      search,
      q,
      sort_by,
      sortBy,
      sort_order,
      order,
      include_relations,
      cache_bust,
      fields,
      export: exportFlag,
      ...rest
    } = opts;

    let defaultLimit = 10;
    try {
      if (typeof window !== 'undefined') {
        defaultLimit = getDefaultLimitByDevice();
      }
    } catch (e) {}

    return {
      page: page ?? rest.page ?? 1,
      limit: limit ?? per_page ?? rest.limit ?? defaultLimit,
      search: search ?? q,
      sort_by: sort_by ?? sortBy,
      sort_order: sort_order ?? order,
      include_relations,
      cache_bust,
      fields,
      export: exportFlag,
      ...rest,
    };
  }

  async getMetadata(): Promise<{ resource: string; total_count: number; last_modified: string; etag: string } | null> {
    try {
      const response = await api.get(`${this.endpoint}/metadata`);
      return response.data?.data || response.data;
    } catch (error: any) {
      return null;
    }
  }

  async getSince(since: string): Promise<T[]> {
    const response = await api.get(this.endpoint, { params: { since } });
    return extractListFromResponse(response, this.options.preferredListKeys);
  }

  async getWithConditionalHeaders(
    params?: Record<string, any>,
    etag?: string,
    lastModified?: string
  ): Promise<{ data: T[]; etag?: string; lastModified?: string; status: number }> {
    const headers: Record<string, string> = {};
    if (etag) headers['If-None-Match'] = etag;
    if (lastModified) headers['If-Modified-Since'] = lastModified;

    const response = await api.get(this.endpoint, {
      params,
      headers,
      validateStatus: (status) => status === 200 || status === 304,
    });

    if (response.status === 304) {
      const cacheKey = this.getCacheKey(params);
      const cached = await this.getFromCache(cacheKey);
      return { data: (cached as T[]) || [], etag, lastModified, status: 304 };
    }

    const data = extractListFromResponse(response, this.options.preferredListKeys);
    const newETag = response.headers['etag'] || response.headers['ETag'];
    const newLastModified = response.headers['last-modified'] || response.headers['Last-Modified'];
    this.setCache(this.getCacheKey(params), data);

    return { data, etag: newETag, lastModified: newLastModified, status: 200 };
  }
}

import { getIndexedDBCache, setIndexedDBCache, startIndexedDBCacheCleanup } from '@/shared/api/cache/indexedDBCache';
import { API_CONFIG } from './config';

if (typeof window !== 'undefined') {
  startIndexedDBCacheCleanup(300000); // 5 mins
}

const memoryCache = new Map<string, { data: any; expiry: number; etag?: string; lastModified?: string }>();

export type CacheReadOptions = {
  allowIdb?: boolean;
  timeoutMs?: number;
};

const IDB_READ_TIMEOUT_SENTINEL = Symbol('IDB_READ_TIMEOUT');

export async function readCache(key: string, options?: CacheReadOptions): Promise<any | null> {
  const cacheKey = `http-cache:${key}`;

  const memEntry = memoryCache.get(cacheKey);
  if (memEntry && Date.now() <= memEntry.expiry) {
    return memEntry.data;
  }

  const isOnline = typeof navigator === 'undefined' || navigator.onLine !== false;
  const allowIdb = options?.allowIdb ?? (isOnline ? API_CONFIG.idbReadOnline : true);
  if (!allowIdb) return null;

  const timeoutMs = options?.timeoutMs ?? API_CONFIG.idbReadTimeoutMs;

  try {
    const idbPromise = getIndexedDBCache<any>(cacheKey, {
      allowStaleWhenOffline: true,
      offlineGraceMs: 10 * 60 * 1000,
    });

    const readWithTimeout = timeoutMs > 0
      ? Promise.race([
        idbPromise,
        new Promise<symbol>((resolve) => setTimeout(() => resolve(IDB_READ_TIMEOUT_SENTINEL), timeoutMs)),
      ])
      : idbPromise;

    const idbResult = await readWithTimeout;

    if (idbResult === IDB_READ_TIMEOUT_SENTINEL) {
      void idbPromise.then((data) => {
        if (!data) return;
        memoryCache.set(cacheKey, { data, expiry: Date.now() + API_CONFIG.httpCacheTTL });
      }).catch(() => { /* noop */ });
      return null;
    }

    if (idbResult) {
      memoryCache.set(cacheKey, { data: idbResult, expiry: Date.now() + API_CONFIG.httpCacheTTL });
      return idbResult;
    }
  } catch (error) {
    console.warn('[api] Error leyendo cache IndexedDB:', error);
  }

  return null;
}

export function writeCache(key: string, data: any, ttlMs: number = API_CONFIG.httpCacheTTL, meta?: { etag?: string; lastModified?: string }): void {
  const cacheKey = `http-cache:${key}`;
  const expiry = Date.now() + Math.max(1000, ttlMs);

  memoryCache.set(cacheKey, { data, expiry, etag: meta?.etag, lastModified: meta?.lastModified });

  void setIndexedDBCache(cacheKey, data, ttlMs).catch(err => {
    console.warn('[api] Error escribiendo cache IndexedDB:', err);
  });
}

export function getMemoryCacheMeta(key: string) {
  return memoryCache.get(`http-cache:${key}`);
}

/**
 * Utilidad para cache persistente en IndexedDB
 * Optimizada para PWA offline-first con sincronización precisa
 */

const DB_NAME = 'VillaLuzCache';
const DB_VERSION = 1;
const STORE_NAME = 'apiCache';
const OFFLINE_STALE_GRACE_MS = 24 * 60 * 60 * 1000; // 24h de gracia para reutilizar datos en modo offline

interface CacheEntry {
  key: string;
  data: any;
  timestamp: number;
  ttl?: number; // Time to live en milisegundos
  version?: number;
}

const isIndexedDBSupported = (): boolean => {
  try {
    return typeof window !== 'undefined' && !!window.indexedDB;
  } catch {
    return false;
  }
};

/**
 * Inicializa la base de datos IndexedDB
 */
function openDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    if (!isIndexedDBSupported()) {
      reject(new Error('IndexedDB not available'));
      return;
    }

    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result);

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;

      // Crear object store si no existe
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: 'key' });
        store.createIndex('timestamp', 'timestamp', { unique: false });
      }
    };
  });
}

/**
 * Guarda datos en IndexedDB con TTL opcional
 */
export async function setIndexedDBCache<T>(
  key: string,
  data: T,
  ttl?: number
): Promise<void> {
  try {
    const db = await openDB();
    const transaction = db.transaction(STORE_NAME, 'readwrite');
    const store = transaction.objectStore(STORE_NAME);

    const entry: CacheEntry = {
      key,
      data,
      timestamp: Date.now(),
      ttl,
      version: 1,
    };

    await new Promise<void>((resolve, reject) => {
      const request = store.put(entry);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });

    db.close();
  } catch (error) {
    console.warn('[IndexedDBCache] Error al guardar:', error);
    // No lanzar error - degradar silenciosamente a memoria
  }
}

/**
 * Obtiene datos de IndexedDB (respeta TTL)
 */
export async function getIndexedDBCache<T>(
  key: string,
  options?: { allowStaleWhenOffline?: boolean; offlineGraceMs?: number }
): Promise<T | null> {
  try {
    const db = await openDB();
    const transaction = db.transaction(STORE_NAME, 'readonly');
    const store = transaction.objectStore(STORE_NAME);

    const entry = await new Promise<CacheEntry | null>((resolve, reject) => {
      const request = store.get(key);
      request.onsuccess = () => resolve(request.result || null);
      request.onerror = () => reject(request.error);
    });

    db.close();

    if (!entry) return null;

    // Verificar TTL si está definido
    if (entry.ttl) {
      const age = Date.now() - entry.timestamp;
      const offlineGrace = options?.offlineGraceMs ?? OFFLINE_STALE_GRACE_MS;
      const allowStaleOffline = options?.allowStaleWhenOffline && typeof navigator !== 'undefined' && navigator.onLine === false;
      if (age > entry.ttl) {
        // Permitir usar datos vencidos si estamos offline y dentro de la ventana de gracia
        if (allowStaleOffline && age <= entry.ttl + offlineGrace) {
          return entry.data as T;
        }
        // Expirado: eliminar en background
        void deleteIndexedDBCache(key);
        return null;
      }
    }

    return entry.data as T;
  } catch (error) {
    console.warn('[IndexedDBCache] Error al leer:', error);
    return null;
  }
}

/**
 * Elimina una entrada del cache
 */
export async function deleteIndexedDBCache(key: string): Promise<void> {
  try {
    const db = await openDB();
    const transaction = db.transaction(STORE_NAME, 'readwrite');
    const store = transaction.objectStore(STORE_NAME);

    await new Promise<void>((resolve, reject) => {
      const request = store.delete(key);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });

    db.close();
  } catch (error) {
    console.warn('[IndexedDBCache] Error al eliminar:', error);
  }
}

/**
 * Invalida todo el cache de un endpoint específico
 */
export async function invalidateIndexedDBCacheByPrefix(
  prefix: string
): Promise<void> {
  try {
    const db = await openDB();
    const transaction = db.transaction(STORE_NAME, 'readwrite');
    const store = transaction.objectStore(STORE_NAME);

    const keys = await new Promise<string[]>((resolve, reject) => {
      const request = store.getAllKeys();
      request.onsuccess = () => resolve(request.result as string[]);
      request.onerror = () => reject(request.error);
    });

    // Eliminar todas las claves que empiecen con el prefijo
    const deletePromises = keys
      .filter(key => String(key).startsWith(prefix))
      .map(key => new Promise<void>((resolve, reject) => {
        const deleteRequest = store.delete(key);
        deleteRequest.onsuccess = () => resolve();
        deleteRequest.onerror = () => reject(deleteRequest.error);
      }));

    await Promise.all(deletePromises);
    db.close();
  } catch (error) {
    console.warn('[IndexedDBCache] Error al invalidar por prefijo:', error);
  }
}

/**
 * Limpia entradas expiradas del cache
 */
export async function clearExpiredIndexedDBCache(
  options?: { allowStaleWhenOffline?: boolean; offlineGraceMs?: number }
): Promise<number> {
  try {
    const db = await openDB();
    const transaction = db.transaction(STORE_NAME, 'readwrite');
    const store = transaction.objectStore(STORE_NAME);

    const entries = await new Promise<CacheEntry[]>((resolve, reject) => {
      const request = store.getAll();
      request.onsuccess = () => resolve(request.result || []);
      request.onerror = () => reject(request.error);
    });

    const now = Date.now();
    const offlineGrace = options?.offlineGraceMs ?? OFFLINE_STALE_GRACE_MS;
    const allowStaleOffline = options?.allowStaleWhenOffline && typeof navigator !== 'undefined' && navigator.onLine === false;
    let deletedCount = 0;

    for (const entry of entries) {
      if (entry.ttl) {
        const age = now - entry.timestamp;
        const hardExpired = age > entry.ttl;
        if (hardExpired) {
          // Si estamos offline y dentro de la ventana de gracia, conservar entrada
          if (allowStaleOffline && age <= entry.ttl + offlineGrace) {
            continue;
          }
          await new Promise<void>((resolve, reject) => {
            const deleteRequest = store.delete(entry.key);
            deleteRequest.onsuccess = () => {
              deletedCount++;
              resolve();
            };
            deleteRequest.onerror = () => reject(deleteRequest.error);
          });
        }
      }
    }

    db.close();
    return deletedCount;
  } catch (error) {
    console.warn('[IndexedDBCache] Error al limpiar expirados:', error);
    return 0;
  }
}

/**
 * Limpia TODO el cache (útil para debugging o logout)
 */
export async function clearAllIndexedDBCache(): Promise<void> {
  try {
    const db = await openDB();
    const transaction = db.transaction(STORE_NAME, 'readwrite');
    const store = transaction.objectStore(STORE_NAME);

    await new Promise<void>((resolve, reject) => {
      const request = store.clear();
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });

    db.close();
  } catch (error) {
    console.warn('[IndexedDBCache] Error al limpiar todo:', error);
  }
}

/**
 * Obtiene el tamaño estimado del cache (número de entradas)
 */
export async function getIndexedDBCacheSize(): Promise<number> {
  try {
    const db = await openDB();
    const transaction = db.transaction(STORE_NAME, 'readonly');
    const store = transaction.objectStore(STORE_NAME);

    const count = await new Promise<number>((resolve, reject) => {
      const request = store.count();
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });

    db.close();
    return count;
  } catch (error) {
    console.warn('[IndexedDBCache] Error al obtener tamaño:', error);
    return 0;
  }
}

/**
 * Ejecuta limpieza automática de cache expirado en background
 * Llamar al inicializar la app o periódicamente
 */
export function startIndexedDBCacheCleanup(intervalMs: number = 300000): void {
  if (!isIndexedDBSupported()) {
    return;
  }
  // Limpiar inmediatamente
  void clearExpiredIndexedDBCache({ allowStaleWhenOffline: true });

  // Limpiar cada X minutos (default: 5 min)
  setInterval(() => {
    void clearExpiredIndexedDBCache({ allowStaleWhenOffline: true }).then(count => {
      if (count > 0) {
        console.log(`[IndexedDBCache] Limpiados ${count} registros expirados`);
      }
    });
  }, intervalMs);
}

import { AxiosResponse } from 'axios';
import { api } from './base-client';
import { readCache, writeCache, getMemoryCacheMeta } from './cache-manager';
import { rateLimitBackoff } from './interceptors';
import { API_CONFIG } from './config';
import { normalizePath } from './base-client';
import { setupInterceptors } from './interceptors';

// Re-exports
export { api as default, api as apiClient };
export { refreshClient } from './base-client';
export { unwrapApi } from '@/shared/utils/apiUnwrap';
export { forceLogoutFromApiError } from './auth-error-handler';
export { setupInterceptors };

// Inicialización diferida opcional, pero mejor llamarla desde el entry point
setupInterceptors(api);

// COALESCING de GET global (single-flight)
const inflightGet = new Map<string, Promise<any>>();
const lastRequestAt = new Map<string, number>();

const stableStringify = (obj: any) => {
  if (!obj || typeof obj !== 'object') return '';
  const keys = Object.keys(obj).sort();
  const normalized: Record<string, any> = {};
  for (const k of keys) normalized[k] = obj[k];
  return JSON.stringify(normalized);
};

const buildGetKey = (url: string, config?: any) => {
  const base = api.defaults.baseURL || '';
  const full = url.startsWith('/') ? `${base}${url}` : `${base}/${url}`;
  const paramsStr = stableStringify(config?.params);
  return `GET ${full}?${paramsStr}`;
};

const originalGet = api.get.bind(api);

(api as any).get = async (url: string, config?: any) => {
  const hasCancel = !!(config && (config.cancelToken || config.signal));
  const key = buildGetKey(url, config);
  const path = normalizePath(url as any);

  try {
    const mem = getMemoryCacheMeta(key);
    if (mem) {
      const headers = { ...(config?.headers || {}) };
      if (mem.etag) {
        headers['If-None-Match'] = mem.etag;
      } else if (mem.lastModified) {
        headers['If-Modified-Since'] = mem.lastModified;
      }
      config = { ...(config || {}), headers };
    }
  } catch { /* noop */ }

  try {
    const until = rateLimitBackoff.get(path) || 0;
    if (until && Date.now() < until) {
      const cachedBackoff = await readCache(key, { allowIdb: true });
      if (cachedBackoff) {
        return { data: cachedBackoff, status: 200, statusText: 'OK', headers: {}, config } as AxiosResponse;
      }
    }
  } catch { /* noop */ }

  try {
    if (API_CONFIG.requestMinIntervalMs > 0 && path) {
      const last = lastRequestAt.get(path) || 0;
      const elapsed = Date.now() - last;
      if (elapsed < API_CONFIG.requestMinIntervalMs) {
        await new Promise((r) => setTimeout(r, API_CONFIG.requestMinIntervalMs - elapsed));
      }
      lastRequestAt.set(path, Date.now());
    }
  } catch { /* noop */ }

  const cached = await readCache(key);
  if (cached) {
    return { data: cached, status: 200, statusText: 'OK', headers: {}, config } as AxiosResponse;
  }

  const existing = inflightGet.get(key);
  if (existing && !hasCancel) {
    return existing;
  }

  const p = originalGet(url, config).then((resp: AxiosResponse) => {
    try {
      const etag = resp.headers?.['etag'] || resp.headers?.['ETag'];
      const lastModified = resp.headers?.['last-modified'] || resp.headers?.['Last-Modified'];
      writeCache(key, resp.data, API_CONFIG.httpCacheTTL, { etag, lastModified });
    } catch { /* noop */ }

    if (resp.status === 304) {
      try {
        const mem = getMemoryCacheMeta(key);
        if (mem && Date.now() <= mem.expiry) {
          return { data: mem.data, status: 200, statusText: 'Not Modified', headers: resp.headers, config } as AxiosResponse;
        }
      } catch { /* noop */ }
    }
    return resp;
  });

  inflightGet.set(key, p);
  const clear = () => inflightGet.delete(key);
  p.then(clear, clear);
  return p;
};

// Funciones SSE deprecadas exportadas para retrocompatibilidad
export function startServerEvents(): void {}
export function startWebSocket(): void {}
