export type ApiErrorCode =
  | 'CSRF_ERROR'
  | 'TOKEN_EXPIRED'
  | 'MISSING_TOKEN'
  | 'JWT_ERROR'
  | 'ADMIN_ROLE_REQUIRED'
  | 'VALIDATION_ERROR'
  | 'RATE_LIMIT_EXCEEDED'
  | 'CONFLICT'
  | 'APPROVAL_PENDING'
  | string;

export type StandardApiErrorPayload = {
  success?: boolean;
  message?: string;
  details?: any;
  error?: {
    code?: ApiErrorCode;
    details?: any;
    trace_id?: string;
  };
};

export class ApiFetchError extends Error {
  code?: ApiErrorCode;
  details?: any;
  traceId?: string;
  status?: number;
  original?: unknown;
  validationErrors?: Record<string, any>;

  constructor(message: string, init?: Partial<ApiFetchError>) {
    super(message);
    this.name = 'ApiFetchError';
    Object.assign(this, init);
  }
}

export function readStandardErrorPayload(err: any): {
  status?: number;
  message: string;
  code?: ApiErrorCode;
  details?: any;
  traceId?: string;
  raw?: any;
  validationErrors?: Record<string, any>;
} {
  const status: number | undefined = err?.response?.status ?? err?.status;
  const raw: StandardApiErrorPayload | any = err?.response?.data ?? err?.data ?? {};

  // ---- Mensaje principal (siempre preferir raw.message) ----
  const message =
    raw?.message ||
    raw?.error?.message ||
    (typeof raw?.error === 'string' ? raw.error : undefined) ||
    raw?.detail ||
    err?.message ||
    'Error en la solicitud';

  // ---- Código (si no existe, inferir en casos comunes) ----
  let code: ApiErrorCode | undefined = raw?.error?.code;
  if (!code) {
    // CSRF legacy (algunos retornos no usan APIResponse)
    const msg = String(message || '').toUpperCase();
    if ((status === 401 || status === 400 || status === 403) && msg.includes('CSRF')) {
      code = 'CSRF_ERROR';
    } else if (status === 429) {
      code = 'RATE_LIMIT_EXCEEDED';
    } else if (status === 409) {
      code = 'CONFLICT';
    }
  }

  // ---- Details (fallback: raw.details cuando no viene error.details) ----
  const details =
    raw?.error?.details ??
    raw?.details ??
    // caso CRUD legacy: { success:false, error:'Invalid pagination', message:'...' }
    (typeof raw?.error === 'string' ? { legacy_error: raw.error } : undefined);

  const traceId = raw?.error?.trace_id;

  // ---- Validaciones: no siempre viene VALIDATION_ERROR ni validation_errors como string[] ----
  const maybeValidation =
    raw?.error?.details?.validation_errors ??
    raw?.details?.validation_errors ??
    raw?.validation_errors ??
    raw?.errors ??
    undefined;

  const validationErrors =
    maybeValidation && typeof maybeValidation === 'object' && !Array.isArray(maybeValidation)
      ? (maybeValidation as Record<string, any>)
      : undefined;

  // Inferir VALIDATION_ERROR si es 422 y vienen validation errors (aunque no haya error.code)
  if (!raw?.error?.code && status === 422 && validationErrors) {
    code = 'VALIDATION_ERROR';
  }

  return { status, message, code, details, traceId, raw, validationErrors };
}

export function formatMessageFromCode(input: {
  message: string;
  code?: ApiErrorCode;
  details?: any;
}): string {
  const { message, code, details } = input;
  if (!code) return message;

  if (code === 'RATE_LIMIT_EXCEEDED') {
    const wait = details?.retry_after_seconds ?? details?.retry_after;
    if (typeof wait === 'number' && Number.isFinite(wait) && wait > 0) {
      return `Demasiadas solicitudes. Espere ${wait} segundos e intente de nuevo.`;
    }
    if (typeof wait === 'string' && wait.trim() !== '' && !Number.isNaN(Number(wait))) {
      return `Demasiadas solicitudes. Espere ${Number(wait)} segundos e intente de nuevo.`;
    }
    return message;
  }

  if (code === 'ADMIN_ROLE_REQUIRED') {
    return 'No tiene permisos para realizar esta accion.';
  }

  if (code === 'CSRF_ERROR') {
    return 'Falta CSRF o la sesion expiro. Recargue la pagina e intente nuevamente.';
  }

  if (code === 'CONFLICT') {
    return message && message.trim().length ? message : 'Violación de unicidad';
  }

  if (code === 'APPROVAL_PENDING') {
    return message || 'Tu cuenta está pendiente de aprobación por un administrador.';
  }

  return message;
}

import { InternalAxiosRequestConfig } from 'axios';
import { refreshClient, normalizePath, isPublicEndpoint } from './base-client';
import { API_CONFIG } from './config';

export type AuthGateState = 'unknown' | 'checking' | 'ready' | 'unauthenticated';

export let authGateState: AuthGateState = 'unknown';
let authGatePromise: Promise<void> | null = null;

export function shouldSkipGate(config: InternalAxiosRequestConfig): boolean {
  if ((config as any).__skipAuthGate) return true;
  const method = String(config.method || 'get').toLowerCase();
  if (method === 'options' || method === 'head') return true;
  if (config.url && /^(https?:)?\/\//i.test(String(config.url))) return true;
  const path = normalizePath(config.url as any);
  return isPublicEndpoint(path);
}

export async function ensureAuthReady(): Promise<void> {
  if (authGateState === 'ready' || authGateState === 'unauthenticated') return;
  if (authGatePromise) return authGatePromise;

  authGateState = 'checking';
  authGatePromise = (async () => {
    try {
      if (API_CONFIG.debugMode) console.log('[api][gate] Iniciando comprobación /auth/me ...');
      let resp: any;
      try {
        resp = await refreshClient.get('/auth/me', {
          headers: { 'Accept': 'application/json' },
        });
      } catch (e: any) {
        const st = e?.response?.status ?? 0;
        if (API_CONFIG.debugMode) console.warn('[api][gate] /auth/me error inicial:', st, e?.message);
        if (st === 401) {
          try {
            if (API_CONFIG.debugMode) console.log('[api][gate] 401 en /auth/me, intentando /auth/refresh ...');
            await refreshClient.post('/auth/refresh');
            if (API_CONFIG.debugMode) console.log('[api][gate] Refresh OK. Reintentando /auth/me ...');
            resp = await refreshClient.get('/auth/me', { headers: { 'Accept': 'application/json' } });
          } catch (e2: any) {
            const st2 = e2?.response?.status ?? 0;
            if (API_CONFIG.debugMode) console.warn('[api][gate] Refresh + /auth/me reintento falló:', st2, e2?.message);
            throw e2; 
          }
        } else {
          throw e;
        }
      }
      const st = resp?.status ?? 0;
      if (API_CONFIG.debugMode) console.log('[api][gate] /auth/me status:', st);
      if (st === 200) authGateState = 'ready';
      else if (st === 401) authGateState = 'unauthenticated';
      else authGateState = 'ready'; 
    } catch (e: any) {
      const st = e?.response?.status ?? 0;
      if (API_CONFIG.debugMode) console.warn('[api][gate] /auth/me error tras reintentos:', st, e?.message);
      if (st === 401) authGateState = 'unauthenticated';
      else authGateState = 'ready'; 
    } finally {
      if (API_CONFIG.debugMode) console.log('[api][gate] Finalizado. Estado =', authGateState);
      authGatePromise = null;
    }
  })();

  return authGatePromise;
}

