import axios, { InternalAxiosRequestConfig, AxiosResponse, AxiosError, isCancel } from 'axios';
import { getCookie } from '@/shared/utils/cookieUtils';
import { shouldRefreshToken } from '@/shared/utils/jwtUtils';
import { offlineQueue } from '@/shared/api/offline/offlineQueue';
import { ApiFetchError, readStandardErrorPayload, formatMessageFromCode } from './error-parser';
import { API_CONFIG } from './config';
import { api, refreshClient, MutableHeaders, ensureJsonHeaders, setAuthHeader, setCsrfHeaders, normalizePath, isPublicEndpoint } from './base-client';
import { readStoredToken, hasClientSession, forceClientLogout, showToastOnce } from './auth-utils';
import { shouldSkipGate, ensureAuthReady } from './gate';
import { performRefresh, refreshPromise } from './refresh';
import { isCsrfError, shouldForceLogout } from './auth-error-handler';
import { readCache } from './cache-manager';

export const rateLimitBackoff = new Map<string, number>();

export const setupInterceptors = (instance: typeof api) => {
  instance.interceptors.request.use(
  async (config: InternalAxiosRequestConfig) => {
    try {
      // Normalizar URL para evitar duplicación de /api/v1 si el baseURL ya lo incluye
      if (config.url && config.baseURL?.endsWith('/api/v1')) {
        if (config.url.startsWith('/api/v1/')) {
          config.url = config.url.replace('/api/v1/', '/');
        } else if (config.url.startsWith('api/v1/')) {
          config.url = config.url.replace('api/v1/', '');
        }
      }

      if (!shouldSkipGate(config)) {
        await ensureAuthReady();
      }

      const path = normalizePath(config.url as any);
      const isAuthLogin = path.startsWith('auth/login');
      const isAuthRefresh = path.startsWith('auth/refresh');
      const isAuthMe = path.startsWith('auth/me');

      if (refreshPromise && !isAuthRefresh) {
        await refreshPromise;
      }

      const skipAuthHeader =
        isPublicEndpoint(path) ||
        (config as any).skipAuth === true ||
        (config as any).disableAuth === true ||
        (config as any).__skipAuthHeader === true;

      if (path.startsWith('animals') && config.method?.toLowerCase() === 'post') {
        if (API_CONFIG.debugMode) console.log('[API][debug] POST /animals payload:', JSON.stringify(config.data, null, 2));
      }

      const headers = (config as any).headers as MutableHeaders | undefined;
      if (headers) {
        ensureJsonHeaders(headers, config.data);

        const shouldAttachAuth = !skipAuthHeader && !isAuthLogin && !isAuthRefresh;
        const token = readStoredToken();
        setAuthHeader(headers, shouldAttachAuth, token);

        const hasAccessCsrf = !!getCookie('csrf_access_token');
        const hasRefreshCsrf = !!getCookie('csrf_refresh_token');
        const isProtected = (!isPublicEndpoint(path) || isAuthMe) && !skipAuthHeader;

        if (!isAuthLogin && !isAuthRefresh && !isAuthMe && isProtected) {
          if (API_CONFIG.useBearerAuth && token && shouldRefreshToken(token)) {
            await performRefresh({ retryOnCsrfError: true });
          } else if (!hasAccessCsrf && hasRefreshCsrf) {
            await performRefresh({ retryOnCsrfError: true });
          }
        }

        if (isAuthRefresh) {
          const csrfRefresh = getCookie('csrf_refresh_token') ?? undefined;
          setCsrfHeaders(headers, csrfRefresh);
        } else if (isProtected) {
          const csrfAccess = getCookie('csrf_access_token') ?? undefined;
          setCsrfHeaders(headers, csrfAccess);
        }
      }
    } catch (e) {
      if (API_CONFIG.debugMode) console.warn('[api] Error en interceptor de solicitud:', e);
    }
    return config;
  },
    (error) => Promise.reject(error)
  );

  refreshClient.interceptors.request.use(
  (config: InternalAxiosRequestConfig) => {
    try {
      // Normalizar URL para evitar duplicación de /api/v1 si el baseURL ya lo incluye
      if (config.url && config.baseURL?.endsWith('/api/v1')) {
        if (config.url.startsWith('/api/v1/')) {
          config.url = config.url.replace('/api/v1/', '/');
        } else if (config.url.startsWith('api/v1/')) {
          config.url = config.url.replace('api/v1/', '');
        }
      }

      const path = normalizePath(config.url as any);
      const skipAuthHeader =
        isPublicEndpoint(path) ||
        (config as any).skipAuth === true ||
        (config as any).disableAuth === true ||
        (config as any).__skipAuthHeader === true;
      const headers = (config as any).headers as MutableHeaders | undefined;
      if (headers) {
        ensureJsonHeaders(headers, config.data);

        const token = readStoredToken();
        const shouldAttachAuth = !skipAuthHeader && !path.startsWith('auth/refresh');
        setAuthHeader(headers, shouldAttachAuth, token);
        if (path.startsWith('auth/refresh') && headers['Authorization']) {
          delete headers['Authorization'];
        }
        if (path.startsWith('auth/refresh')) {
          const csrfRefresh = getCookie('csrf_refresh_token') ?? undefined;
          setCsrfHeaders(headers, csrfRefresh);
        } else if (path.startsWith('auth/me')) {
          const csrfAccess = getCookie('csrf_access_token') ?? undefined;
          setCsrfHeaders(headers, csrfAccess);
        }
      }
    } catch (e) {
      if (API_CONFIG.debugMode) console.warn('[refreshClient] Error en interceptor de solicitud:', e);
    }
    return config;
  },
    (error) => Promise.reject(error)
  );

  instance.interceptors.response.use(
  (response: AxiosResponse) => {
    if (API_CONFIG.debugMode && response.headers) {
      const pwHeaders = {
        etag: response.headers['etag'] || response.headers['ETag'],
        lastModified: response.headers['last-modified'] || response.headers['Last-Modified'],
        cacheControl: response.headers['cache-control'] || response.headers['Cache-Control'],
      };
      const hasPWAHeaders = Object.values(pwHeaders).some(v => v !== undefined);
      if (hasPWAHeaders) {
        const path = normalizePath(response.config?.url as any);
        console.debug(`[api][PWA] ${path} headers:`, pwHeaders);
      }
    }
    return response;
  },
  async (error: any) => {
    const originalRequest = error?.config || {};
    const status = error?.response?.status;
    const path = normalizePath(originalRequest?.url as any);

    if (status === 429) {
      try {
        const delayMs = 30000; 
        rateLimitBackoff.set(path, Date.now() + delayMs);
      } catch (e) {
        if (API_CONFIG.debugMode) console.warn(e);
      }
    }

    if (!originalRequest._retry) originalRequest._retry = false;

    const isAuthLogin = path.startsWith('auth/login');
    const isAuthRefresh = path.startsWith('auth/refresh');
    if (status === 401 && (isAuthLogin || isAuthRefresh)) {
      return Promise.reject(error);
    }

    if (status === 401) {
      const tokenStatus = shouldForceLogout(error);
      const hasStoredAuth = hasClientSession();
      const isAuthMeRequest = path.startsWith('auth/me');

      if (tokenStatus.shouldForce) {
        await forceClientLogout('expired', { logoutUrl: tokenStatus.logoutUrl, loginUrl: tokenStatus.loginUrl });
        return Promise.reject(error);
      }

      if (!hasStoredAuth && !isAuthMeRequest) {
        await forceClientLogout('missing', { logoutUrl: tokenStatus.logoutUrl, loginUrl: tokenStatus.loginUrl });
        return Promise.reject(error);
      }

      if (tokenStatus.shouldRefresh) {
        try {
          if (!originalRequest._retry) {
            originalRequest._retry = true;
            await performRefresh({ retryOnCsrfError: true });
            if (originalRequest.headers) {
              delete originalRequest.headers['Authorization'];
              delete originalRequest.headers['X-CSRF-Token'];
              delete originalRequest.headers['X-CSRF-TOKEN'];
            }
            return api(originalRequest);
          } else {
            await forceClientLogout('expired');
            return Promise.reject(error);
          }
        } catch (refreshErr) {
          await forceClientLogout('expired');
          return Promise.reject(refreshErr);
        }
      }

      return Promise.reject(error);
    }

    if (isCsrfError(error) && !originalRequest._csrfRetry) {
      originalRequest._csrfRetry = true;
      const csrf = getCookie('csrf_access_token');
      if (csrf) {
        if (originalRequest.headers) {
          originalRequest.headers['X-CSRF-Token'] = csrf;
          originalRequest.headers['X-CSRF-TOKEN'] = csrf;
        }
        return api(originalRequest);
      }
    }

    const method = String(originalRequest?.method || 'get').toLowerCase();
    const codeStr = String(error?.code || '').toUpperCase();
    const msgStr = String(error?.message || '').toLowerCase();
    const isTimeoutLike = status === 408 || codeStr === 'ECONNABORTED' || codeStr === 'ETIMEDOUT' || msgStr.includes('timeout');
    const isNetworkLike = codeStr === 'ERR_NETWORK' || (!status && msgStr.includes('network'));
    const skipRetry = (originalRequest as any)?.skipTimeoutRetry === true;
    const aborted = isCancel(error) || (!!(originalRequest as any)?.signal && (originalRequest as any).signal.aborted === true);

    if (!skipRetry && !aborted && (method === 'get' || method === 'head') && (isTimeoutLike || isNetworkLike)) {
      const attempt = Number((originalRequest as any)._timeoutAttempt ?? 0) + 1;
      if (attempt <= API_CONFIG.timeoutRetryAttempts) {
        (originalRequest as any)._timeoutAttempt = attempt;
        let delay = Math.floor(API_CONFIG.timeoutRetryBaseMs * Math.pow(1.7, attempt - 1));
        if (delay > API_CONFIG.timeoutRetryMaxMs) delay = API_CONFIG.timeoutRetryMaxMs;
        delay += Math.floor(Math.random() * 100);
        await new Promise((r) => setTimeout(r, delay));
        return api(originalRequest);
      }
    }

    if (!aborted) {
      const parsed = readStandardErrorPayload(error);
      const detailMsg = formatMessageFromCode(parsed);

      const isOfflineLike = status === 0 || isNetworkLike || !status;
      const skipOffline = (originalRequest as any)?.skipOffline === true;

      if (isOfflineLike && method !== 'get' && !skipOffline) {
        const fullUrl = (originalRequest.url?.startsWith('http') 
          ? originalRequest.url 
          : `${API_CONFIG.baseURL}/${path}`).replace(/\/+/g, '/').replace(':/', '://');

        offlineQueue.enqueue(
          method.toUpperCase() as any,
          fullUrl,
          originalRequest.data,
          originalRequest.headers as Record<string, string>
        );

        showToastOnce('offline-queued', {
          title: "Modo Offline",
          description: "Sin conexión. Tu cambio se ha guardado localmente y se sincronizará automáticamente al volver el internet.",
          variant: "default",
        });

        return {
          data: { ...(originalRequest.data || {}), __offlineQueued: true },
          status: 202,
          statusText: 'Accepted (Queued)',
          headers: {},
          config: originalRequest
        } as AxiosResponse;
      }

      if (status === 403) {
        showToastOnce('forbidden', { title: "Acceso denegado", description: "No tienes permisos.", variant: "destructive" });
      } else if (status >= 500) {
        showToastOnce('server-error', { title: "Error del servidor", description: "Intenta más tarde.", variant: "destructive" });
      } else if (isOfflineLike) {
        showToastOnce('network-error', { title: "Error", description: detailMsg || "Error de red.", variant: "destructive" });
      } else if (detailMsg) {
        showToastOnce(`error-${status}`, { title: "Error", description: String(detailMsg), variant: "destructive" });
      }

      const validationErrors = parsed.validationErrors || 
        (parsed.code === 'VALIDATION_ERROR' ? (parsed.details?.validation_errors || parsed.details?.errors) : undefined);

      throw new ApiFetchError(detailMsg, {
        status,
        code: parsed.code,
        details: parsed.details,
        traceId: parsed.traceId,
        original: error,
        validationErrors,
      });
    }

    return Promise.reject(error);
  }
);
};

// Utilidad central para extraer listas desde diferentes formas de envoltura de respuestas API
// Acepta una respuesta Axios o un objeto simple con posibles estructuras:
// { data: [...] }
// { data: { items: [...] } }
// { items: [...] }
// { <key>: [...] }
// { data: { <key>: [...] } }
// También intenta buscar el primer array dentro del objeto cuando no se especifican claves.


// Busca recursivamente el primer array en cualquier nivel de un objeto
function findFirstArrayDeep(obj: any): any[] | null {
  if (!obj || typeof obj !== 'object') return null;
  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      const val = obj[key];
      if (Array.isArray(val)) return val;
      if (val && typeof val === 'object') {
        const found = findFirstArrayDeep(val);
        if (found) return found;
      }
    }
  }
  return null;
}

export function extractListFromResponse(resp: any, preferredKeys: string[] = []): any[] {
  if (!resp) return [];
  const norm = (resp as any).normalizedData;
  if (Array.isArray(norm)) return norm;

  // Resp Axios -> resp.data
  const root = resp.data !== undefined ? resp.data : resp;
  // Algunas APIs ponen la carga real dentro de root.data
  const data = root && root.data !== undefined ? root.data : root;

  // Si ya es array directo
  if (Array.isArray(data)) return data;

  // Intentar con claves preferidas en orden: primero usuario, luego genéricas
  const candidateKeys = [
    ...preferredKeys,
    'items', 'data', 'list', 'results', 'animals', 'users', 'species', 'breeds', 'medications', 'vaccines',
    'animal_diseases', 'animal_fields', 'fields',
    // Añadido para soportar respuestas con clave específica de tratamientos
    'treatments'
  ];
  for (const k of candidateKeys) {
    const segment = (data as any)?.[k];
    if (Array.isArray(segment)) return segment;
  }

  // Buscar primer array en cualquier nivel de anidación
  if (data && typeof data === 'object') {
    const deepFound = findFirstArrayDeep(data);
    if (Array.isArray(deepFound)) return deepFound;
  }

  return [];
}

// Extrae objeto paginado conservando metadatos y devolviendo lista bajo key canonical
export function extractPaginatedList(resp: any, preferredKeys: string[] = [], listKeyFallback = 'items') {
  const root = resp?.data || resp || {};
  // Si root.data es un array, los metadatos probablemente están en root.
  // Si root.data es un objeto, los metadatos podrían estar en root.data.
  const data = (root?.data && !Array.isArray(root.data)) ? root.data : root;
  const list = extractListFromResponse(resp, preferredKeys);

  // Metadatos comunes
  const metaKeys = ['total', 'page', 'per_page', 'pages', 'total_pages', 'has_next', 'has_prev', 'has_next_page', 'has_previous_page', 'pagination'];
  const metadata: Record<string, any> = {};
  for (const k of metaKeys) {
    if (data && data[k] !== undefined) {
      metadata[k] = data[k];
    }
  }

  // Si la paginación viene en un objeto anidado en data
  if (data && data.pagination && typeof data.pagination === 'object') {
    Object.assign(metadata, data.pagination);
  }

  // Si la paginación viene en root.meta (como en algunas APIs)
  if (root && root.meta && typeof root.meta === 'object') {
    if (root.meta.pagination && typeof root.meta.pagination === 'object') {
      Object.assign(metadata, root.meta.pagination);
    } else {
      // Si meta no tiene pagination, asumir que meta contiene directamente los metadatos
      Object.assign(metadata, root.meta);
    }
  }

  // Mapear nombres alternativos de Potreros de paginación
  if (metadata.has_next_page !== undefined) metadata.has_next = metadata.has_next_page;
  if (metadata.has_previous_page !== undefined) metadata.has_prev = metadata.has_previous_page;
  if (metadata.total_pages !== undefined) metadata.pages = metadata.total_pages;

  return {
    ...metadata,
    [listKeyFallback]: list,
  };
}

/**
 * MCP Resilient Client
 * 
 * Wrapper que detecta caídas de MCP (Model Context Protocol) y usa fallback automáticamente.
 * Este cliente implementa graceful degradation cuando los servicios MCP de DevBrain no están disponibles.
 * 
 * @example
 * ```typescript
 * import { mcpResilientClient } from '@/shared/api/mcpResilientClient';
 * 
 * // Usar con fallback
 * const result = await mcpResilientClient.executeWithFallback(
 *   'devbrain-universal',
 *   'dashboard_status',
 *   {},
 *   async () => {
 *     // Fallback: usar API REST directamente
 *     return await fetch('/api/health').then(r => r.json());
 *   }
 * );
 * ```
 */

import { runCommand } from '@/shared/utils/shell';
import { readFile, writeFile } from '@/shared/utils/fs';

/**
 * Estado de un MCP
 */
interface MCPStatus {
  /** Si el MCP está disponible para llamadas */
  available: boolean;
  
  /** Último error recibido */
  lastError?: string;
  
  /** Última vez que respondió exitosamente */
  lastSuccess?: Date;
  
  /** Si está usando fallback actualmente */
  fallbackActive: boolean;
  
  /** Número de intentos fallidos consecutivos */
  consecutiveFailures: number;
  
  /** Tiempo de cooldown antes de reintentar (ms) */
  cooldownUntil?: Date;
}

/**
 * Opciones para ejecutar una herramienta MCP
 */
interface MCPExecuteOptions<T> {
  /** Nombre del servidor MCP */
  mcpName: string;
  
  /** Nombre de la herramienta a ejecutar */
  toolName: string;
  
  /** Parámetros para la herramienta */
  params?: Record<string, any>;
  
  /** Función fallback a ejecutar si MCP falla */
  fallbackFn: () => Promise<T>;
  
  /** Si forzar usar fallback (ignora MCP disponible) */
  forceFallback?: boolean;
  
  /** Timeout para la llamada MCP (ms) */
  timeout?: number;
}

/**
 * Resultado de ejecución MCP
 */
interface MCPResult<T> {
  /** Datos retornados */
  data: T;
  
  /** Si vino del MCP o del fallback */
  source: 'mcp' | 'fallback';
  
  /** Tiempo de ejecución (ms) */
  duration: number;
  
  /** Error si hubo (solo si fallback también falló) */
  error?: string;
}

/**
 * Cliente resiliente para MCPs con fallback automático
 */
class MCPResilientClient {
  private status: Map<string, MCPStatus> = new Map();
  private readonly MAX_CONSECUTIVE_FAILURES = 3;
  private readonly COOLDOWN_PERIOD_MS = 60000; // 1 minuto de cooldown
  private readonly DEFAULT_TIMEOUT = 5000; // 5 segundos
  
  constructor() {
    // Inicializar estado para MCPs conocidos
    this.initStatus('devbrain-universal');
    this.initStatus('devbrain-skill-test-skill-v2');
    
    console.log('[MCP-Resilient] Cliente inicializado');
  }
  
  /**
   * Inicializa estado para un MCP
   */
  private initStatus(mcpName: string): void {
    this.status.set(mcpName, {
      available: true, // Asumir disponible hasta probar
      fallbackActive: false,
      consecutiveFailures: 0
    });
  }
  
  /**
   * Ejecuta una herramienta MCP con fallback automático
   * 
   * @template T Tipo de retorno esperado
   * @param options Opciones de ejecución
   * @returns Resultado de MCP o fallback
   */
  async executeWithFallback<T>(options: MCPExecuteOptions<T>): Promise<MCPResult<T>> {
    const { mcpName, toolName, params = {}, fallbackFn, forceFallback = false, timeout = this.DEFAULT_TIMEOUT } = options;
    
    const startTime = performance.now();
    
    // Verificar si debemos intentar MCP o ir directo a fallback
    if (forceFallback || !this.shouldTryMCP(mcpName)) {
      console.log(`[MCP-Resilient] ${mcpName}.${toolName}: Usando fallback (force=${forceFallback}, cooldown=${this.isInCooldown(mcpName)})`);
      return this.executeFallback(fallbackFn, startTime);
    }
    
    try {
      // Intentar usar el MCP
      const result = await this.executeMCPTool<T>(mcpName, toolName, params, timeout);
      
      // Éxito: actualizar estado
      this.updateStatus(mcpName, {
        available: true,
        lastSuccess: new Date(),
        fallbackActive: false,
        consecutiveFailures: 0,
        cooldownUntil: undefined
      });
      
      const duration = Math.round(performance.now() - startTime);
      console.log(`[MCP-Resilient] ${mcpName}.${toolName}: ✓ Éxito (${duration}ms)`);
      
      return {
        data: result,
        source: 'mcp',
        duration
      };
      
    } catch (error) {
      // MCP falló: registrar y usar fallback
      const errorMsg = error instanceof Error ? error.message : String(error);
      console.warn(`[MCP-Resilient] ${mcpName}.${toolName}: ✗ Falló - ${errorMsg}`);
      
      // Actualizar estado de fallo
      const currentStatus = this.status.get(mcpName)!;
      const newFailures = currentStatus.consecutiveFailures + 1;
      
      this.updateStatus(mcpName, {
        available: false,
        lastError: errorMsg,
        fallbackActive: true,
        consecutiveFailures: newFailures,
        // Activar cooldown si superamos el máximo de fallos
        cooldownUntil: newFailures >= this.MAX_CONSECUTIVE_FAILURES 
          ? new Date(Date.now() + this.COOLDOWN_PERIOD_MS) 
          : undefined
      });
      
      // Ejecutar fallback
      return this.executeFallback(fallbackFn, startTime, errorMsg);
    }
  }
  
  /**
   * Determina si debe intentar usar el MCP o ir a fallback
   */
  private shouldTryMCP(mcpName: string): boolean {
    const status = this.status.get(mcpName);
    if (!status) return true;
    
    // Si está en cooldown, no intentar
    if (this.isInCooldown(mcpName)) {
      return false;
    }
    
    // Si ha fallado muchas veces, no intentar
    if (status.consecutiveFailures >= this.MAX_CONSECUTIVE_FAILURES) {
      return false;
    }
    
    return true;
  }
  
  /**
   * Verifica si un MCP está en período de cooldown
   */
  private isInCooldown(mcpName: string): boolean {
    const status = this.status.get(mcpName);
    if (!status?.cooldownUntil) return false;
    
    return new Date() < status.cooldownUntil;
  }
  
  /**
   * Ejecuta el fallback y retorna resultado
   */
  private async executeFallback<T>(
    fallbackFn: () => Promise<T>, 
    startTime: number,
    originalError?: string
  ): Promise<MCPResult<T>> {
    try {
      const result = await fallbackFn();
      const duration = Math.round(performance.now() - startTime);
      
      console.log(`[MCP-Resilient] Fallback: ✓ Éxito (${duration}ms)`);
      
      return {
        data: result,
        source: 'fallback',
        duration,
        error: originalError // Incluir error original como contexto
      };
      
    } catch (fallbackError) {
      const duration = Math.round(performance.now() - startTime);
      const fallbackErrorMsg = fallbackError instanceof Error 
        ? fallbackError.message 
        : String(fallbackError);
      
      console.error(`[MCP-Resilient] Fallback: ✗ Falló - ${fallbackErrorMsg}`);
      
      // Ambos fallaron: propagar error
      throw new Error(
        `MCP y fallback fallaron. ` +
        `MCP error: ${originalError || 'N/A'}. ` +
        `Fallback error: ${fallbackErrorMsg}`
      );
    }
  }
  
  /**
   * Ejecuta una herramienta MCP
   * 
   * NOTA: Esta es una implementación simulada. En producción real,
   * aquí se integraría con el SDK oficial de MCP.
   */
  private async executeMCPTool<T>(
    mcpName: string,
    toolName: string,
    params: Record<string, any>,
    timeout: number
  ): Promise<T> {
    // Aquí iría la integración real con MCP SDK
    // Por ahora simula un fallo para demostrar el fallback
    
    // Simulación: siempre falla para demostrar graceful degradation
    // En implementación real, esto llamaría al transporte MCP
    throw new Error(`MCP transport closed: ${mcpName}.${toolName}`);
    
    /*
    // Implementación real sería algo como:
    const client = await this.getMCPClient(mcpName);
    const result = await Promise.race([
      client.callTool(toolName, params),
      new Promise((_, reject) => 
        setTimeout(() => reject(new Error('MCP timeout')), timeout)
      )
    ]);
    return result as T;
    */
  }
  
  /**
   * Actualiza el estado de un MCP
   */
  private updateStatus(mcpName: string, updates: Partial<MCPStatus>): void {
    const current = this.status.get(mcpName) || {
      available: true,
      fallbackActive: false,
      consecutiveFailures: 0
    };
    
    this.status.set(mcpName, { ...current, ...updates });
  }
  
  /**
   * Verifica si un MCP está marcado como disponible
   */
  isAvailable(mcpName: string): boolean {
    return this.status.get(mcpName)?.available ?? false;
  }
  
  /**
   * Obtiene el estado completo de todos los MCPs
   */
  getAllStatus(): Record<string, MCPStatus> {
    return Object.fromEntries(this.status);
  }
  
  /**
   * Obtiene estado de un MCP específico
   */
  getStatus(mcpName: string): MCPStatus | undefined {
    return this.status.get(mcpName);
  }
  
  /**
   * Fuerza un reset del estado de un MCP (útil para reintentos manuales)
   */
  resetStatus(mcpName: string): void {
    this.initStatus(mcpName);
    console.log(`[MCP-Resilient] ${mcpName}: Estado reseteado`);
  }
  
  /**
   * Intenta recuperar un MCP del cooldown
   */
  async attemptRecovery(mcpName: string): Promise<boolean> {
    const status = this.status.get(mcpName);
    if (!status) return false;
    
    console.log(`[MCP-Resilient] ${mcpName}: Intentando recuperación...`);
    
    // Resetear estado
    this.resetStatus(mcpName);
    
    // Aquí podría hacer un health check real
    // Por ahora simulamos que la recuperación fue exitosa
    this.updateStatus(mcpName, {
      available: true,
      lastSuccess: new Date()
    });
    
    return true;
  }
}

