// Exportar tipos para uso externo
export type { DiscoveredPeer, SyncState, SyncMessage };

import { getCookie } from '@/shared/utils/cookieUtils';
import { apiFetch } from '@/shared/api/apiFetch';

export interface QueuedOperation {
  id: string;
  operation_id?: string;
  entity_type?: string;
  entity_id?: string;
  operation?: string;
  base_version?: number;
  timestamp: number;
  method: 'POST' | 'PUT' | 'DELETE' | 'PATCH';
  url: string;
  data?: any;
  headers?: Record<string, string>;
  retries: number;
  maxRetries: number;
  status: 'pending' | 'syncing' | 'failed' | 'completed';
  error?: string;
  originDeviceId?: string; // ID del dispositivo que generó el cambio
  syncVersion?: number;    // Para control de conflictos (timestamp o vector)
  mesh_hops?: number;      // Cuántos saltos ha dado entre dispositivos (Mesh Relay)
  shared_with?: string[];  // Lista de IDs de dispositivos a los que ya se envió este dato
}

const DB_NAME = 'VillaLuzQueue';
const DB_VERSION = 1;
const QUEUE_STORE = 'offlineQueue';
const MAX_RETRIES = 3;

// ─────────────────────────────────────────────────────────────
// IndexedDB helpers (misma DB que el cache HTTP, store separado)
// localStorage tiene límite 5–10 MB; IndexedDB soporta ~50-500 MB
// ─────────────────────────────────────────────────────────────

function openQueueDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === 'undefined') {
      reject(new Error('IndexedDB not available'));
      return;
    }
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onerror = () => reject(req.error);
    req.onsuccess = () => resolve(req.result);
    req.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(QUEUE_STORE)) {
        const store = db.createObjectStore(QUEUE_STORE, { keyPath: 'id' });
        store.createIndex('status', 'status', { unique: false });
        store.createIndex('timestamp', 'timestamp', { unique: false });
      }
      if (!db.objectStoreNames.contains('voiceNotes')) {
        const voiceStore = db.createObjectStore('voiceNotes', { keyPath: 'id' });
        voiceStore.createIndex('status', 'status', { unique: false });
        voiceStore.createIndex('timestamp', 'timestamp', { unique: false });
      }
    };
  });
}

async function dbGetAll(): Promise<QueuedOperation[]> {
  try {
    const db = await openQueueDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(QUEUE_STORE, 'readonly');
      const req = tx.objectStore(QUEUE_STORE).getAll();
      req.onsuccess = () => resolve(req.result as QueuedOperation[]);
      req.onerror = () => reject(req.error);
    });
  } catch {
    return [];
  }
}

async function dbPut(op: QueuedOperation): Promise<void> {
  try {
    const db = await openQueueDB();
    await new Promise<void>((resolve, reject) => {
      const tx = db.transaction(QUEUE_STORE, 'readwrite');
      const req = tx.objectStore(QUEUE_STORE).put(op);
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
  } catch { /* noop */ }
}

async function dbDelete(id: string): Promise<void> {
  try {
    const db = await openQueueDB();
    await new Promise<void>((resolve, reject) => {
      const tx = db.transaction(QUEUE_STORE, 'readwrite');
      const req = tx.objectStore(QUEUE_STORE).delete(id);
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
  } catch { /* noop */ }
}

// ─────────────────────────────────────────────────────────────
// OfflineQueue
// ─────────────────────────────────────────────────────────────

const GET_DEVICE_ID = () => {
  let id = localStorage.getItem('villaruz_device_id');
  if (!id) {
    id = `dev-${Math.random().toString(36).substr(2, 9)}`;
    localStorage.setItem('villaruz_device_id', id);
  }
  return id;
};

class OfflineQueue {
  private isSyncing = false;
  private syncCallbacks: Array<(success: boolean, operation: QueuedOperation) => void> = [];

  constructor() {
    if (typeof window !== 'undefined') {
      window.addEventListener('online', () => {
        this.syncQueue().catch(() => {});
      });
    }
  }

  async enqueue(
    method: QueuedOperation['method'],
    url: string,
    data?: any,
    headers?: Record<string, string>
  ): Promise<string> {
    const operation: QueuedOperation = {
      id: `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      operation_id: `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      entity_type: 'http_request',
      operation: method,
      timestamp: Date.now(),
      method,
      url,
      data,
      headers,
      retries: 0,
      maxRetries: MAX_RETRIES,
      status: 'pending',
      originDeviceId: GET_DEVICE_ID(),
      syncVersion: Date.now(),
    };

    await dbPut(operation);

    if (typeof navigator !== 'undefined' && navigator.onLine && !this.isSyncing) {
      setTimeout(() => this.syncQueue().catch(() => {}), 100);
    }

    return operation.id;
  }

  async getPendingOperations(): Promise<QueuedOperation[]> {
    const all = await dbGetAll();
    return all.filter(op => op.status !== 'completed');
  }

  async getPendingCount(): Promise<number> {
    return (await this.getPendingOperations()).length;
  }

  async syncQueue(): Promise<void> {
    return this.syncBatch(5); // Por defecto sincroniza de a 5 para balancear carga
  }

  /**
   * Sincronización optimizada por lotes (Batch Sync)
   * Útil para grandes volúmenes de datos acumulados offline.
   */
  async syncBatch(batchSize = 10): Promise<void> {
    const isOnline = typeof navigator === 'undefined' || navigator.onLine;
    if (this.isSyncing || !isOnline) return;

    const pending = await this.getPendingOperations();
    if (pending.length === 0) return;

    this.isSyncing = true;
    console.log(`[OfflineQueue] Iniciando sincronización por lote de ${Math.min(batchSize, pending.length)} operaciones`);

    const batch = pending.slice(0, batchSize);

    // Procesar en paralelo con límite de batchSize
    await Promise.all(batch.map(async (operation) => {
      if (operation.status === 'syncing') return;

      operation.status = 'syncing';
      await dbPut(operation);

      try {
        const headers: Record<string, string> = {
          Accept: 'application/json',
          'Content-Type': 'application/json',
          ...(operation.headers || {}),
        };

        const csrfToken = getCookie('csrf_access_token') ?? undefined;
        if (csrfToken) {
          headers['X-CSRF-Token'] = headers['X-CSRF-Token'] || csrfToken;
        }

        const res = await apiFetch({
          url: operation.url,
          method: operation.method,
          data: operation.data,
          headers,
          withCredentials: true,
        } as any);

        if (res.status >= 200 && res.status < 300) {
          await dbDelete(operation.id);
          this.notifyCallbacks(true, { ...operation, status: 'completed' });
        } else {
          throw new Error(`HTTP ${res.status}`);
        }
      } catch (error: any) {
        operation.retries++;
        operation.error = error.message || 'Error desconocido';
        operation.status = operation.retries >= operation.maxRetries ? 'failed' : 'pending';
        await dbPut(operation);
        if (operation.status === 'failed') this.notifyCallbacks(false, operation);
      }
    }));

    this.isSyncing = false;

    // Si quedan más, programar el siguiente lote
    if (pending.length > batchSize) {
      setTimeout(() => this.syncBatch(batchSize).catch(() => {}), 500);
    } else {
      const remaining = await this.getPendingCount();
      if (typeof window !== 'undefined') {
        window.dispatchEvent(new CustomEvent('offline-queue-synced', { detail: { remaining } }));
      }
    }
  }

  onSyncResult(callback: (success: boolean, operation: QueuedOperation) => void): () => void {
    this.syncCallbacks.push(callback);
    return () => {
      this.syncCallbacks = this.syncCallbacks.filter(cb => cb !== callback);
    };
  }

  async clearCompleted(): Promise<void> {
    const all = await dbGetAll();
    for (const op of all) {
      if (op.status === 'completed') await dbDelete(op.id);
    }
  }

  async clearFailed(): Promise<void> {
    const all = await dbGetAll();
    for (const op of all) {
      if (op.status === 'failed') await dbDelete(op.id);
    }
  }

  async clearFailedOperations(): Promise<void> {
    return this.clearFailed();
  }

  async retryFailedOperations(): Promise<void> {
    const all = await dbGetAll();
    for (const op of all) {
      if (op.status === 'failed') {
        op.status = 'pending';
        op.retries = 0;
        op.error = undefined;
        await dbPut(op);
      }
    }
    await this.syncQueue();
  }

  async getStatusCounts(): Promise<{ pending: number; failed: number; syncing: boolean }> {
    const all = await dbGetAll();
    const pending = all.filter(op => op.status === 'pending').length;
    const failed = all.filter(op => op.status === 'failed').length;
    return { pending, failed, syncing: this.isSyncing };
  }

  /**
   * Verificar si una operación ya existe por su ID
   * Usado para sincronización Mesh/P2P
   */
  async hasOperation(id: string): Promise<boolean> {
    const all = await dbGetAll();
    return all.some(op => op.id === id);
  }

  /**
   * Agregar una operación recibida desde otro dispositivo (sincronización Mesh)
   * La operación viene con datos del dispositivo origen
   */
  async addOperation(operation: QueuedOperation & { source?: string; receivedFrom?: string; receivedAt?: string }): Promise<void> {
    // Verificar que no exista ya
    const exists = await this.hasOperation(operation.id);
    if (exists) {
      console.log(`[OfflineQueue] Operación ${operation.id} ya existe, ignorando duplicado`);
      return;
    }

    // Asegurar que la operación esté marcada como pendiente
    // Incrementar saltos (Relay)
    const currentHops = operation.mesh_hops || 0;
    if (currentHops > 10) {
      console.warn(`[OfflineQueue] Operación ${operation.id} excedió límite de saltos Mesh (10), descartando`);
      return;
    }

    const opToAdd: QueuedOperation = {
      ...operation,
      status: 'pending',
      retries: 0,
      maxRetries: MAX_RETRIES,
      mesh_hops: currentHops + 1,
      shared_with: operation.shared_with || [],
      // Preservar metadata de sincronización
      originDeviceId: operation.originDeviceId || operation.receivedFrom || 'unknown',
      syncVersion: operation.syncVersion || Date.now()
    };

    await dbPut(opToAdd);
    console.log(`[OfflineQueue] Operación agregada desde Mesh (Salto: ${opToAdd.mesh_hops}): ${operation.id}`);

    // Intentar sincronizar si estamos online
    if (typeof navigator !== 'undefined' && navigator.onLine && !this.isSyncing) {
      setTimeout(() => this.syncQueue().catch(() => {}), 100);
    }
  }

  /**
   * Marca una operación como compartida con un dispositivo específico
   */
  async markAsShared(opId: string, deviceId: string): Promise<void> {
    const all = await dbGetAll();
    const op = all.find(o => o.id === opId);
    if (op) {
      const sharedWith = op.shared_with || [];
      if (!sharedWith.includes(deviceId)) {
        op.shared_with = [...sharedWith, deviceId];
        await dbPut(op);
      }
    }
  }

  private notifyCallbacks(success: boolean, operation: QueuedOperation): void {
    this.syncCallbacks.forEach(cb => {
      try { cb(success, operation); } catch { /* noop */ }
    });
  }

  async getVoiceNotesCount(): Promise<number> {
    try {
      const db = await openQueueDB();
      return new Promise((resolve, reject) => {
        const tx = db.transaction('voiceNotes', 'readonly');
        const store = tx.objectStore('voiceNotes');
        const req = store.count();
        req.onsuccess = () => resolve(req.result);
        req.onerror = () => reject(req.error);
      });
    } catch {
      return 0;
    }
  }
}

export const offlineQueue = new OfflineQueue();
export default offlineQueue;

/**
 * PWA API Client con soporte completo para optimizaciones del backend
 * - ETags y validación condicional (304 Not Modified)
 * - Sincronización incremental (?since=timestamp)
 * - Endpoint /metadata para verificación ligera
 * - Respeto de headers X-Cache-Strategy
 */

import { BaseService } from './base-service';
import { apiFetch } from '@/shared/api/apiFetch';
import {
  getETag,
  setETag,
  clearETag,
  getLastSync,
  setLastSync,
  normalizeResourceKey
} from '@/shared/api/cache/etagStore';
import type { PaginatedResponse } from '@/shared/api/generated/swaggerTypes';

const __DEV__ = typeof process !== 'undefined' && process.env && process.env.NODE_ENV === 'development';

/**
 * Metadata de un recurso (endpoint /metadata)
 */
export interface ResourceMetadata {
  resource: string;
  total_count: number;
  last_modified: string; // ISO timestamp
  etag: string;
}

/**
 * Configuración de cache por tipo de recurso (basado en X-Cache-Strategy)
 */
export type CacheStrategy = 'cache-first' | 'network-first' | 'stale-while-revalidate';

/**
 * Configuración de recursos maestros vs transaccionales
 */
const RESOURCE_STRATEGIES: Record<string, CacheStrategy> = {
  // Datos maestros (públicos, cambian poco)
  'diseases': 'cache-first',
  'breeds': 'cache-first',
  'species': 'cache-first',
  'medications': 'cache-first',
  'vaccines': 'cache-first',
  'fields': 'cache-first',
  'food_types': 'cache-first',
  'route_administrations': 'cache-first',

  // Datos transaccionales (privados, cambian frecuentemente)
  'vaccinations': 'stale-while-revalidate',
  'treatments': 'stale-while-revalidate',
  'animal_diseases': 'stale-while-revalidate',
  'treatment_medications': 'stale-while-revalidate',
  'treatment_vaccines': 'stale-while-revalidate',
  'controls': 'stale-while-revalidate',
  'animals': 'stale-while-revalidate',
  'animal_fields': 'stale-while-revalidate',

  // Datos de usuario (privados, críticos)
  'users': 'network-first',
};

/**
 * Cliente PWA extendido con capacidades de optimización
 */
export class PWAApiClient<T = any> extends BaseService<T> {
  private resourceKey: string;

  constructor(endpoint: string, options?: any) {
    super(endpoint, options);
    this.resourceKey = normalizeResourceKey(endpoint);
  }

  /**
   * Obtiene la estrategia de caché para este recurso
   */
  public getCacheStrategy(): CacheStrategy {
    return RESOURCE_STRATEGIES[this.resourceKey] || 'network-first';
  }

  /**
   * Obtiene metadata del recurso sin descargar datos completos
   * Usa endpoint /metadata del backend
   */
  async getMetadata(): Promise<ResourceMetadata | null> {
    try {
      const response = await apiFetch({ url: `${this.endpoint}/metadata`, method: 'GET' });
      const metadata = response.data?.data || response.data;

      // Guardar ETag de metadata para futuros checks
      if (metadata?.etag) {
        await setETag(`${this.resourceKey}:metadata`, metadata.etag);
      }

      return metadata;
    } catch (error: any) {
      if (__DEV__) {
        console.warn(`[PWA] Metadata no disponible para ${this.resourceKey}:`, error?.message);
      }
      return null;
    }
  }

  /**
   * Verifica si hay cambios en el servidor comparando ETags
   * Retorna true si hay cambios, false si no
   */
  async hasChanges(): Promise<boolean> {
    const metadata = await this.getMetadata();
    if (!metadata) return true; // Asumir cambios si no hay metadata

    const storedETag = await getETag(this.resourceKey);
    if (!storedETag) return true; // No hay ETag previo

    return metadata.etag !== storedETag;
  }

  /**
   * Obtiene datos con validación condicional usando ETags
   * Si el servidor responde 304, retorna datos cacheados
   */
  async getWithETag(params?: Record<string, any>): Promise<PaginatedResponse<T>> {
    const storedETag = await getETag(this.resourceKey);
    const storedLastModified = await getETag(`${this.resourceKey}:last-modified`);

    // Agregar headers condicionales si existen
    const headers: Record<string, string> = {};
    if (storedETag) {
      headers['If-None-Match'] = storedETag;
    }
    if (storedLastModified) {
      headers['If-Modified-Since'] = storedLastModified;
    }

    try {
      const response = await apiFetch({
        url: this.endpoint,
        method: 'GET',
        params,
        headers,
        validateStatus: (status) => status === 200 || status === 304,
      });

      // 304 Not Modified - usar caché
      if (response.status === 304) {
        if (__DEV__) {
          console.log(`[PWA] 304 Not Modified para ${this.resourceKey} - usando caché`);
        }

        // Retornar desde caché en memoria o IndexedDB
        const cached = await this.getFromCache(this.getCacheKey(params));
        if (cached) {
          return cached as PaginatedResponse<T>;
        }

        // Si no hay caché, hacer request normal
        return this.getPaginated(params);
      }

      // 200 OK - datos nuevos
      const etag = response.headers['etag'] || response.headers['ETag'];
      const lastModified = response.headers['last-modified'] || response.headers['Last-Modified'];

      // Guardar ETags para próxima validación
      if (etag) {
        await setETag(this.resourceKey, etag);
      }
      if (lastModified) {
        await setETag(`${this.resourceKey}:last-modified`, undefined, lastModified);
      }

      // Procesar respuesta normalmente
      const data = response.data?.data || response.data?.items || response.data;
      return {
        data: Array.isArray(data) ? data : [],
        total: response.data?.total || 0,
        page: response.data?.page || 1,
        limit: response.data?.limit || 10,
        totalPages: response.data?.totalPages || response.data?.pages || 1,
        hasNextPage: response.data?.hasNextPage ?? false,
        hasPreviousPage: response.data?.hasPreviousPage ?? false,
      };
    } catch (error) {
      console.error(`[PWA] Error en getWithETag para ${this.resourceKey}:`, error);
      // Fallback a método normal
      return this.getPaginated(params);
    }
  }

  /**
   * Sincronización incremental - solo cambios desde última sincronización
   * Usa ?since=timestamp del backend
   */
  async syncSince(since?: string): Promise<{ data: T[]; hasMore: boolean; newSync: string }> {
    // Usar timestamp guardado si no se proporciona
    const sinceTimestamp = since || await getLastSync(this.resourceKey) || new Date(0).toISOString();

    if (__DEV__) {
      console.log(`[PWA] Sincronizando ${this.resourceKey} desde ${sinceTimestamp}`);
    }

    try {
      const response = await apiFetch({ url: this.endpoint, method: 'GET', params: { since: sinceTimestamp } });

      const data = response.data?.data || response.data?.items || [];
      const hasMore = response.data?.meta?.pagination?.has_next_page ?? false;
      const newSync = new Date().toISOString();

      // Guardar nuevo timestamp de sync
      await setLastSync(this.resourceKey, newSync);

      // Actualizar ETag si viene en headers
      const etag = response.headers['etag'] || response.headers['ETag'];
      if (etag) {
        await setETag(this.resourceKey, etag);
      }

      if (__DEV__) {
        console.log(`[PWA] ✅ ${data.length} cambios descargados para ${this.resourceKey}`);
      }

      return {
        data: Array.isArray(data) ? data : [],
        hasMore,
        newSync,
      };
    } catch (error: any) {
      console.error(`[PWA] Error en syncSince para ${this.resourceKey}:`, error?.message);
      throw error;
    }
  }

  /**
   * Sync completo: reinicia timestamp y descarga todo
   */
  async fullSync(): Promise<{ data: T[]; total: number }> {
    if (__DEV__) {
      console.log(`[PWA] Sincronización completa de ${this.resourceKey}`);
    }

    // Resetear timestamp de sync
    await setLastSync(this.resourceKey, new Date(0).toISOString());

    const response = await this.getPaginated();

    // Actualizar timestamp
    await setLastSync(this.resourceKey, new Date().toISOString());

    return {
      data: response.data || [],
      total: response.total || 0,
    };
  }

  /**
   * Invalidar caché y ETags de este recurso
   */
  async invalidate(): Promise<void> {
    this.clearCache();
    await clearETag(this.resourceKey);
    await clearETag(`${this.resourceKey}:metadata`);
    await clearETag(`${this.resourceKey}:last-modified`);
  }
}

/**
 * Factory para crear clientes PWA específicos
 */
export function createPWAClient<T>(endpoint: string): PWAApiClient<T> {
  return new PWAApiClient<T>(endpoint);
}

/**
 * Verifica cambios en múltiples recursos simultáneamente
 */
export async function checkMultipleResources(
  resources: string[]
): Promise<Record<string, boolean>> {
  const results: Record<string, boolean> = {};

  await Promise.all(
    resources.map(async (resource) => {
      const client = createPWAClient(resource);
      results[resource] = await client.hasChanges();
    })
  );

  return results;
}

/**
 * Sincroniza múltiples recursos en paralelo
 */
export async function syncMultipleResources(
  resources: string[]
): Promise<Record<string, { success: boolean; count: number; error?: string }>> {
  const results: Record<string, { success: boolean; count: number; error?: string }> = {};

  await Promise.all(
    resources.map(async (resource) => {
      const client = createPWAClient(resource);
      try {
        const { data } = await client.syncSince();
        results[resource] = {
          success: true,
          count: data.length,
        };
      } catch (error: any) {
        results[resource] = {
          success: false,
          count: 0,
          error: error?.message || 'Unknown error',
        };
      }
    })
  );

  return results;
}

import { getCookie } from '@/shared/utils/cookieUtils';
import { extractJWT } from '@/shared/utils/tokenUtils';
import { isValidTokenFormat } from '@/shared/utils/jwtUtils';
import { API_CONFIG } from './config';
import { refreshClient, setCsrfHeaders } from './base-client';
import { isCsrfError } from './auth-error-handler';
import { persistStoredToken } from './auth-utils';

export let refreshPromise: Promise<void> | null = null;

export async function performRefresh(options?: { retryOnCsrfError?: boolean }): Promise<void> {
  if (refreshPromise) return refreshPromise;
  const doRefresh = async () => {
    const csrfRefresh = getCookie('csrf_refresh_token') ?? undefined;
    const headers: Record<string, string> = { 'Accept': 'application/json', 'Content-Type': 'application/json' };
    setCsrfHeaders(headers, csrfRefresh);
    try {
      const resp = await refreshClient.post('/auth/refresh', null, { headers });
      const candidate = extractJWT(resp?.data);
      if (candidate && isValidTokenFormat(candidate)) {
        persistStoredToken(candidate);
      }
    } catch (err: any) {
      if (options?.retryOnCsrfError && isCsrfError(err)) {
        const retryCsrf = getCookie('csrf_refresh_token') ?? undefined;
        const retryHeaders: Record<string, string> = { 'Accept': 'application/json', 'Content-Type': 'application/json' };
        setCsrfHeaders(retryHeaders, retryCsrf);
        const retryResp = await refreshClient.post('/auth/refresh', null, { headers: retryHeaders });
        const retryCandidate = extractJWT(retryResp?.data);
        if (retryCandidate && isValidTokenFormat(retryCandidate)) {
          persistStoredToken(retryCandidate);
        }
      } else {
        throw err;
      }
    }
  };
  refreshPromise = doRefresh().finally(() => { refreshPromise = null; });
  return refreshPromise;
}

/**
 * Utilities to normalize API responses into a predictable shape.
 * The goal: extract the meaningful payload (array or object) from various
 * envelope formats used by different backend endpoints.
 */
export function findFirstArrayDeep(obj: any, maxDepth = 2): any[] | null {
  if (obj === null || obj === undefined) return null;
  if (Array.isArray(obj)) return obj;
  if (typeof obj !== 'object') return null;

  // Breadth-first limited search up to maxDepth
  const queue: Array<{ value: any; depth: number }> = [{ value: obj, depth: 0 }];

  while (queue.length) {
    const { value, depth } = queue.shift()!;
    if (!value || typeof value !== 'object') continue;

    // Check direct array values
    for (const v of Object.values(value)) {
      if (Array.isArray(v)) return v as any[];
    }

    if (depth < maxDepth) {
      // enqueue nested objects for further inspection
      for (const v of Object.values(value)) {
        if (v && typeof v === 'object') queue.push({ value: v, depth: depth + 1 });
      }
    }
  }

  return null;
}

export function normalizeApiResponseBody(body: any): any {
  if (body === null || body === undefined) return body;

  // If it's already an array or primitive, return as-is
  if (Array.isArray(body)) return body;
  if (typeof body !== 'object') return body;

  // Quick candidates to check first
  const candidateKeys = ['items', 'results', 'animals', 'rows', 'records', 'data', 'users', 'fields', 'controls'];
  for (const key of candidateKeys) {
    const v = body[key];
    if (Array.isArray(v)) return v;
    if (v && typeof v === 'object' && Array.isArray(v.items)) return v.items;
  }

  // If the body has a 'data' object that itself contains arrays, prefer those
  if (body.data && typeof body.data === 'object') {
    const nested = findFirstArrayDeep(body.data, 2);
    if (nested) return nested;
  }

  // Fallback: find the first array property anywhere in the object
  const firstArray = findFirstArrayDeep(body, 2);
  if (firstArray) return firstArray;

  // If no array is found, return the 'data' property if it's an object, or the body itself
  return (body.data && typeof body.data === 'object' && !Array.isArray(body.data)) ? body.data : body;
}

// Normalizador para respuestas paginadas unificadas
import { PageResult } from '@/shared/types/common.types';
import { extractPaginatedList } from './listExtractor';

export function normalizePagination<T>(response: any, preferredKeys: string[] = []): PageResult<T> | null {
  const paginated = extractPaginatedList(response, preferredKeys, 'items');
  if (!paginated || !Array.isArray(paginated.items)) return null;

  const {
    items,
    total: totalRaw,
    total_items,
    page = 1,
    per_page,
    limit,
    pages,
    total_pages,
  } = paginated as any;

  const page_size: number = Number(per_page ?? limit ?? 10);
  const total: number = Number(
    totalRaw ?? total_items ?? (Array.isArray(items) ? items.length : 0)
  );
  const totalPages: number = Number(pages ?? total_pages ?? Math.ceil(total / page_size));

  return {
    items: items as T[],
    total,
    page,
    page_size,
    pages: totalPages,
  } as PageResult<T>;
}

import { useMemo } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/shared/ui/card';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/shared/ui/tooltip';

interface ActivityData {
  date: string;
  hour: number;
  value: number; // 0-100 nivel de actividad
  type: 'feeding' | 'milking' | 'movement' | 'rest';
}

export interface ActivityHeatmapProps {
  data: ActivityData[];
  title?: string;
}

const HOURS = Array.from({ length: 24 }, (_, i) => i);
const DAYS = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];

const ACTIVITY_COLORS = {
  low: '#e5e7eb',      // gray-200
  medium: '#fbbf24',   // amber-400
  high: '#f59e0b',     // amber-500
  veryHigh: '#ef4444',  // red-500
};

const ACTIVITY_LABELS: Record<string, string> = {
  feeding: 'Alimentación',
  milking: 'Ordeño',
  movement: 'Movimiento',
  rest: 'Descanso',
};

export function ActivityHeatmap({
  data,
  title = 'Mapa de Calor de Actividad',
}: ActivityHeatmapProps) {
  const heatmapData = useMemo(() => {
    // Crear matriz de 7 días x 24 horas
    const matrix: (ActivityData | null)[][] = Array(7)
      .fill(null)
      .map(() => Array(24).fill(null));

    // Agrupar datos por día y hora
    data.forEach(item => {
      const date = new Date(item.date);
      const dayOfWeek = date.getDay(); // 0 = Domingo
      const hour = item.hour;

      if (dayOfWeek < 7 && hour < 24) {
        matrix[dayOfWeek][hour] = item;
      }
    });

    return matrix;
  }, [data]);

  const stats = useMemo(() => {
    const total = data.length;
    const byType = data.reduce((acc, item) => {
      acc[item.type] = (acc[item.type] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);

    const avgActivity = total > 0 
      ? data.reduce((sum, item) => sum + item.value, 0) / total 
      : 0;

    const peakHour = data.length > 0
      ? data.reduce((max, item) => item.value > max.value ? item : max, data[0])
      : null;

    return { total, byType, avgActivity, peakHour };
  }, [data]);

  const getColor = (value: number, type: string) => {
    if (value === 0) return ACTIVITY_COLORS.low;
    if (value < 30) return type === 'rest' ? '#dbeafe' : ACTIVITY_COLORS.low;
    if (value < 60) return ACTIVITY_COLORS.medium;
    if (value < 80) return ACTIVITY_COLORS.high;
    return ACTIVITY_COLORS.veryHigh;
  };

  const getActivityLevel = (value: number) => {
    if (value === 0) return 'Sin actividad';
    if (value < 30) return 'Baja';
    if (value < 60) return 'Moderada';
    if (value < 80) return 'Alta';
    return 'Muy alta';
  };

  if (data.length === 0) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">{title}</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-center h-[300px] text-muted-foreground">
            No hay datos de actividad disponibles
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
        <div>
          <CardTitle className="text-lg font-medium">{title}</CardTitle>
          <p className="text-sm text-muted-foreground mt-1">
            Actividad por hora durante la última semana
          </p>
        </div>
        <div className="flex items-center gap-4 text-sm">
          <div className="flex items-center gap-2">
            <div className="w-3 h-3 rounded" style={{ background: ACTIVITY_COLORS.low }} />
            <span className="text-xs">Baja</span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-3 h-3 rounded" style={{ background: ACTIVITY_COLORS.medium }} />
            <span className="text-xs">Media</span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-3 h-3 rounded" style={{ background: ACTIVITY_COLORS.high }} />
            <span className="text-xs">Alta</span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-3 h-3 rounded" style={{ background: ACTIVITY_COLORS.veryHigh }} />
            <span className="text-xs">Muy alta</span>
          </div>
        </div>
      </CardHeader>
      <CardContent>
        <TooltipProvider>
          <div className="space-y-4">
            {/* Heatmap Grid */}
            <div className="overflow-x-auto">
              <div className="inline-block min-w-full">
                {/* Header - Horas */}
                <div className="flex">
                  <div className="w-12 flex-shrink-0" /> {/* Espacio para días */}
                  {HOURS.map(hour => (
                    <div
                      key={hour}
                      className="w-8 flex-shrink-0 text-center text-xs text-muted-foreground"
                    >
                      {hour % 3 === 0 ? `${hour}h` : ''}
                    </div>
                  ))}
                </div>

                {/* Grid */}
                {DAYS.map((day, dayIndex) => (
                  <div key={day} className="flex items-center">
                    <div className="w-12 flex-shrink-0 text-xs font-medium text-muted-foreground">
                      {day}
                    </div>
                    <div className="flex gap-0.5">
                      {HOURS.map(hour => {
                        const activity = heatmapData[dayIndex][hour];
                        const value = activity?.value || 0;
                        const type = activity?.type || 'rest';

                        return (
                          <Tooltip key={hour}>
                            <TooltipTrigger asChild>
                              <div
                                className="w-7 h-7 rounded-sm cursor-pointer transition-all hover:scale-110 hover:ring-2 hover:ring-primary"
                                style={{ backgroundColor: getColor(value, type) }}
                              />
                            </TooltipTrigger>
                            <TooltipContent side="top" className="max-w-xs">
                              <div className="space-y-1">
                                <p className="font-medium">
                                  {day} {hour}:00 - {hour + 1}:00
                                </p>
                                <p className="text-sm">
                                  Actividad: {getActivityLevel(value)} ({value}%)
                                </p>
                                {activity && (
                                  <p className="text-xs text-muted-foreground">
                                    Tipo: {ACTIVITY_LABELS[type] || type}
                                  </p>
                                )}
                              </div>
                            </TooltipContent>
                          </Tooltip>
                        );
                      })}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Resumen de Actividad */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 pt-4 border-t">
              <div className="p-3 bg-muted/50 rounded-lg">
                <p className="text-xs text-muted-foreground">Total Registros</p>
                <p className="text-2xl font-bold">{stats.total}</p>
              </div>
              
              <div className="p-3 bg-muted/50 rounded-lg">
                <p className="text-xs text-muted-foreground">Actividad Promedio</p>
                <p className="text-2xl font-bold">{stats.avgActivity.toFixed(1)}%</p>
              </div>

              <div className="p-3 bg-muted/50 rounded-lg">
                <p className="text-xs text-muted-foreground">Hora Pico</p>
                <p className="text-2xl font-bold">
                  {stats.peakHour ? `${stats.peakHour.hour}:00` : 'N/A'}
                </p>
              </div>

              <div className="p-3 bg-muted/50 rounded-lg">
                <p className="text-xs text-muted-foreground">Tipo Principal</p>
                <p className="text-lg font-bold">
                  {Object.entries(stats.byType).sort((a, b) => b[1] - a[1])[0]?.[0] 
                    ? ACTIVITY_LABELS[Object.entries(stats.byType).sort((a, b) => b[1] - a[1])[0][0]] 
                    : 'N/A'}
                </p>
              </div>
            </div>

            {/* Leyenda de Tipos */}
            <div className="flex flex-wrap gap-4 pt-2">
              {Object.entries(ACTIVITY_LABELS).map(([key, label]) => (
                <div key={key} className="flex items-center gap-2">
                  <div
                    className="w-3 h-3 rounded"
                    style={{
                      backgroundColor:
                        key === 'feeding' ? '#10b981' :
                        key === 'milking' ? '#3b82f6' :
                        key === 'movement' ? '#f59e0b' :
                        '#6b7280'
                    }}
                  />
                  <span className="text-xs text-muted-foreground">{label}</span>
                </div>
              ))}
            </div>
          </div>
        </TooltipProvider>
      </CardContent>
    </Card>
  );
}

export default ActivityHeatmap;

import { useMemo } from 'react';
import {
  Radar,
  RadarChart,
  PolarGrid,
  PolarAngleAxis,
  PolarRadiusAxis,
  ResponsiveContainer,
  Tooltip,
  Legend,
} from 'recharts';
import { Card, CardContent, CardHeader, CardTitle } from '@/shared/ui/card';

interface AnimalMetric {
  name: string;
  production: number;
  health: number;
  reproduction: number;
  weight: number;
  age: number;
}

export interface AnimalMetricsRadarProps {
  data: AnimalMetric[];
  title?: string;
  height?: number;
}

export function AnimalMetricsRadar({
  data,
  title = 'Métricas de Animales',
  height = 350,
}: AnimalMetricsRadarProps) {
  const radarData = useMemo(() => {
    if (data.length === 0) return [];

    // Calcular promedios para cada métrica
    const averages = {
      name: 'Promedio',
      production: data.reduce((sum, a) => sum + a.production, 0) / data.length,
      health: data.reduce((sum, a) => sum + a.health, 0) / data.length,
      reproduction: data.reduce((sum, a) => sum + a.reproduction, 0) / data.length,
      weight: data.reduce((sum, a) => sum + a.weight, 0) / data.length,
      age: data.reduce((sum, a) => sum + a.age, 0) / data.length,
    };

    // Transformar para radar chart
    const metrics = [
      { subject: 'Producción', A: averages.production, fullMark: 100 },
      { subject: 'Salud', A: averages.health, fullMark: 100 },
      { subject: 'Reproducción', A: averages.reproduction, fullMark: 100 },
      { subject: 'Peso', A: averages.weight, fullMark: 100 },
      { subject: 'Edad', A: averages.age, fullMark: 100 },
    ];

    return metrics;
  }, [data]);

  const topPerformers = useMemo(() => {
    return [...data]
      .map(a => ({
        ...a,
        score: (a.production + a.health + a.reproduction + a.weight) / 4,
      }))
      .sort((a, b) => b.score - a.score)
      .slice(0, 3);
  }, [data]);

  if (data.length === 0) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">{title}</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-center h-[300px] text-muted-foreground">
            No hay datos de animales disponibles
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
        <CardTitle className="text-lg font-medium">{title}</CardTitle>
        <div className="text-sm text-muted-foreground">
          {data.length} animales analizados
        </div>
      </CardHeader>
      <CardContent>
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Radar Chart */}
          <div className="lg:col-span-2">
            <ResponsiveContainer width="100%" height={height}>
              <RadarChart cx="50%" cy="50%" outerRadius="80%" data={radarData}>
                <PolarGrid />
                <PolarAngleAxis dataKey="subject" className="text-xs" />
                <PolarRadiusAxis angle={30} domain={[0, 100]} className="text-xs" />
                <Radar
                  name="Promedio General"
                  dataKey="A"
                  stroke="#3b82f6"
                  strokeWidth={2}
                  fill="#3b82f6"
                  fillOpacity={0.3}
                />
                <Tooltip
                  contentStyle={{
                    backgroundColor: 'hsl(var(--card))',
                    border: '1px solid hsl(var(--border))',
                    borderRadius: '6px',
                  }}
                  formatter={(value: number) => [`${value.toFixed(1)}`, '']}
                />
                <Legend />
              </RadarChart>
            </ResponsiveContainer>
          </div>

          {/* Top Performers */}
          <div className="space-y-4">
            <h3 className="font-semibold text-sm text-muted-foreground uppercase tracking-wide">
              Top Performers
            </h3>
            {topPerformers.map((animal, index) => (
              <div
                key={animal.name}
                className="flex items-center gap-3 p-3 bg-muted/50 rounded-lg"
              >
                <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold ${
                  index === 0 ? 'bg-yellow-100 text-yellow-700' :
                  index === 1 ? 'bg-gray-100 text-gray-700' :
                  'bg-orange-100 text-orange-700'
                }`}>
                  {index + 1}
                </div>
                <div className="flex-1">
                  <p className="font-medium text-sm">{animal.name}</p>
                  <p className="text-xs text-muted-foreground">
                    Score: {animal.score.toFixed(1)}/100
                  </p>
                </div>
                <div className="text-right">
                  <p className="text-sm font-bold text-green-600">
                    {animal.production.toFixed(0)}%
                  </p>
                  <p className="text-xs text-muted-foreground">Prod.</p>
                </div>
              </div>
            ))}

            {/* Métricas Detalladas */}
            <div className="mt-4 pt-4 border-t">
              <h4 className="text-xs font-semibold text-muted-foreground uppercase mb-2">
                Promedios
              </h4>
              <div className="space-y-1 text-sm">
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Producción:</span>
                  <span className="font-medium">
                    {radarData.find(d => d.subject === 'Producción')?.A.toFixed(1)}%
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Salud:</span>
                  <span className="font-medium">
                    {radarData.find(d => d.subject === 'Salud')?.A.toFixed(1)}%
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Reproducción:</span>
                  <span className="font-medium">
                    {radarData.find(d => d.subject === 'Reproducción')?.A.toFixed(1)}%
                  </span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

