import { useMemo, useState } from 'react';
import {
  ScatterChart,
  Scatter,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  ZAxis,
  ReferenceLine,
  Label,
} from 'recharts';
import { Card, CardContent, CardHeader, CardTitle } from '@/shared/ui/card';
import { Badge } from '@/shared/ui/badge';
import { Button } from '@/shared/ui/button';

interface AnimalData {
  id: number;
  name: string;
  age: number; // meses
  weight: number; // kg
  production: number; // litros/día
  sex: 'Macho' | 'Hembra';
  breed: string;
}

export interface WeightAgeScatterProps {
  data: AnimalData[];
  title?: string;
  height?: number;
}

type FilterType = 'all' | 'male' | 'female';

export function WeightAgeScatter({
  data,
  title = 'Correlación Peso vs Edad',
  height = 400,
}: WeightAgeScatterProps) {
  const [filter, setFilter] = useState<FilterType>('all');

  const filteredData = useMemo(() => {
    if (filter === 'all') return data;
    return data.filter(a => filter === 'male' ? a.sex === 'Macho' : a.sex === 'Hembra');
  }, [data, filter]);

  const chartData = useMemo(() => {
    return filteredData.map(animal => ({
      x: animal.age,
      y: animal.weight,
      z: animal.production,
      name: animal.name,
      sex: animal.sex,
      breed: animal.breed,
    }));
  }, [filteredData]);

  const statistics = useMemo(() => {
    if (filteredData.length === 0) return null;

    const avgWeight = filteredData.reduce((sum, a) => sum + a.weight, 0) / filteredData.length;
    const avgAge = filteredData.reduce((sum, a) => sum + a.age, 0) / filteredData.length;
    const avgProduction = filteredData.reduce((sum, a) => sum + a.production, 0) / filteredData.length;

    // Calcular correlación (simplificada)
    const n = filteredData.length;
    const sumX = filteredData.reduce((sum, a) => sum + a.age, 0);
    const sumY = filteredData.reduce((sum, a) => sum + a.weight, 0);
    const sumXY = filteredData.reduce((sum, a) => sum + a.age * a.weight, 0);
    const sumX2 = filteredData.reduce((sum, a) => sum + a.age * a.age, 0);
    const sumY2 = filteredData.reduce((sum, a) => sum + a.weight * a.weight, 0);

    const correlation = (n * sumXY - sumX * sumY) / 
      Math.sqrt((n * sumX2 - sumX * sumX) * (n * sumY2 - sumY * sumY));

    return {
      avgWeight,
      avgAge,
      avgProduction,
      correlation: isNaN(correlation) ? 0 : correlation,
      count: n,
    };
  }, [filteredData]);

  const males = data.filter(a => a.sex === 'Macho').length;
  const females = data.filter(a => a.sex === 'Hembra').length;

  if (data.length === 0) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">{title}</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-center h-[300px] text-muted-foreground">
            No hay datos de animales disponibles
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
        <div>
          <CardTitle className="text-lg font-medium">{title}</CardTitle>
          <p className="text-sm text-muted-foreground mt-1">
            Tamaño del punto = Producción diaria
          </p>
        </div>
        <div className="flex items-center gap-4">
          <div className="flex gap-2">
            <Button
              variant={filter === 'all' ? 'primary' : 'outline'}
              size="sm"
              onClick={() => setFilter('all')}
            >
              Todos
            </Button>
            <Button
              variant={filter === 'male' ? 'primary' : 'outline'}
              size="sm"
              onClick={() => setFilter('male')}
            >
              Machos ({males})
            </Button>
            <Button
              variant={filter === 'female' ? 'primary' : 'outline'}
              size="sm"
              onClick={() => setFilter('female')}
            >
              Hembras ({females})
            </Button>
          </div>
        </div>
      </CardHeader>
      <CardContent>
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
          {/* Scatter Chart */}
          <div className="lg:col-span-3">
            <ResponsiveContainer width="100%" height={height}>
              <ScatterChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
                <CartesianGrid strokeDasharray="3 3" className="stroke-muted" />
                <XAxis
                  type="number"
                  dataKey="x"
                  name="Edad"
                  unit=" meses"
                  domain={[0, 'auto']}
                  className="text-xs"
                >
                  <Label value="Edad (meses)" position="bottom" offset={0} />
                </XAxis>
                <YAxis
                  type="number"
                  dataKey="y"
                  name="Peso"
                  unit=" kg"
                  domain={[0, 'auto']}
                  className="text-xs"
                >
                  <Label value="Peso (kg)" angle={-90} position="insideLeft" />
                </YAxis>
                <ZAxis type="number" dataKey="z" range={[50, 400]} name="Producción" unit=" L" />
                <Tooltip
                  cursor={{ strokeDasharray: '3 3' }}
                  content={({ active, payload }) => {
                    if (active && payload && payload.length) {
                      const data = payload[0].payload;
                      return (
                        <div className="bg-background border rounded-lg p-3 shadow-lg">
                          <p className="font-medium">{data.name}</p>
                          <p className="text-sm text-muted-foreground">{data.breed}</p>
                          <div className="mt-2 space-y-1 text-sm">
                            <p>Edad: {data.x} meses</p>
                            <p>Peso: {data.y} kg</p>
                            <p>Producción: {data.z} L/día</p>
                            <Badge variant={data.sex === 'Macho' ? 'default' : 'secondary'}>
                              {data.sex}
                            </Badge>
                          </div>
                        </div>
                      );
                    }
                    return null;
                  }}
                />
                
                {/* Línea de tendencia promedio */}
                {statistics && (
                  <ReferenceLine
                    y={statistics.avgWeight}
                    stroke="#6b7280"
                    strokeDasharray="5 5"
                    label={{ value: `Peso promedio: ${statistics.avgWeight.toFixed(1)}kg`, position: 'right' }}
                  />
                )}
                
                <Scatter
                  name="Animales"
                  data={chartData}
                  fill="#3b82f6"
                  fillOpacity={0.6}
                />
              </ScatterChart>
            </ResponsiveContainer>
          </div>

          {/* Estadísticas */}
          <div className="space-y-4">
            <h3 className="font-semibold text-sm text-muted-foreground uppercase tracking-wide">
              Estadísticas
            </h3>
            
            {statistics && (
              <>
                <div className="space-y-3">
                  <div className="p-3 bg-muted/50 rounded-lg">
                    <p className="text-xs text-muted-foreground">Promedio Peso</p>
                    <p className="text-xl font-bold">{statistics.avgWeight.toFixed(1)} kg</p>
                  </div>
                  
                  <div className="p-3 bg-muted/50 rounded-lg">
                    <p className="text-xs text-muted-foreground">Promedio Edad</p>
                    <p className="text-xl font-bold">{statistics.avgAge.toFixed(1)} meses</p>
                  </div>
                  
                  <div className="p-3 bg-muted/50 rounded-lg">
                    <p className="text-xs text-muted-foreground">Producción Media</p>
                    <p className="text-xl font-bold">{statistics.avgProduction.toFixed(1)} L</p>
                  </div>
                </div>

                <div className="pt-4 border-t">
                  <p className="text-xs text-muted-foreground mb-1">Correlación Peso-Edad</p>
                  <div className="flex items-center gap-2">
                    <div className="flex-1 h-2 bg-muted rounded-full overflow-hidden">
                      <div
                        className="h-full bg-blue-500 rounded-full"
                        style={{ width: `${Math.abs(statistics.correlation) * 100}%` }}
                      />
                    </div>
                    <span className="text-sm font-medium">
                      {statistics.correlation.toFixed(2)}
                    </span>
                  </div>
                  <p className="text-xs text-muted-foreground mt-1">
                    {Math.abs(statistics.correlation) > 0.7 
                      ? 'Fuerte correlación' 
                      : Math.abs(statistics.correlation) > 0.4 
                        ? 'Correlación moderada' 
                        : 'Correlación débil'}
                  </p>
                </div>

                <div className="pt-4 border-t">
                  <p className="text-xs text-muted-foreground">
                    Mostrando {statistics.count} de {data.length} animales
                  </p>
                </div>
              </>
            )}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

export default WeightAgeScatter;

import React from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useRealtimeNotifications } from '@/shared/hooks/useRealtimeNotifications';
import { useToast } from '@/app/providers/ToastContext';
import { MessageCircle, Bell, AlertTriangle, CircleCheck } from 'lucide-react';

/**
 * Componente invisible que escucha eventos SSE globales y dispara
 * notificaciones UI (Toasts) basadas en el contexto actual del usuario.
 */
export const GlobalRealtimeListener: React.FC = () => {
  const { showToast } = useToast();
  const location = useLocation();
  const navigate = useNavigate();

  useRealtimeNotifications({
    onEvent: (eventType, data) => {
      // 1. Mensajes de Chat
      if (eventType === 'chat_message') {
        // Solo mostrar toast si NO estamos en la página de chat
        if (!location.pathname.startsWith('/chat')) {
          const msg = data.data;
          showToast(
            `Mensaje de ${msg.sender_name || 'un usuario'}: ${msg.message.substring(0, 50)}${msg.message.length > 50 ? '...' : ''}`,
            'info'
          );
        }
      }

      // 2. Alertas de Sistema
      else if (eventType === 'system_alert') {
        const alert = data.data;
        const type = alert.type || 'info';
        showToast(
          `${alert.title}: ${alert.message}`,
          type as any
        );
      }

      // 3. Notificaciones generales (si queremos que vibren/suenen o muestren toast)
      else if (eventType === 'notification') {
        const notif = data.data;
        showToast(
          `${notif.title}: ${notif.message}`,
          'info'
        );
      }
    }
  });

  // Este componente no renderiza nada
  return null;
};

export default GlobalRealtimeListener;

import { useState, useCallback } from 'react';
import { 
  Bell, 
  Check, 
  Trash2, 
  X, 
  Info, 
  CircleCheck, 
  AlertTriangle, 
  CircleAlert,
  ExternalLink,
  Wifi, 
  WifiOff, 
  RefreshCw 
} from 'lucide-react';

import { formatDistanceToNow } from 'date-fns';
import { es } from 'date-fns/locale';
import { useRealtimeNotifications, type Notification } from '@/shared/hooks/useRealtimeNotifications';
import { Button } from '@/shared/ui/button';
import { Badge } from '@/shared/ui/badge';
import { ScrollArea } from '@/shared/ui/scroll-area';
import { 
  Popover, 
  PopoverContent, 
  PopoverTrigger 
} from '@/shared/ui/popover';
import { cn } from '@/shared/ui/cn';
import { useFieldMode } from '@/app/providers/FieldModeContext';
import { useOnlineStatus } from '@/shared/hooks/useOnlineStatus';
import { motion, AnimatePresence } from 'framer-motion';


const typeIcons = {
  info: Info,
  success: CircleCheck,
  warning: AlertTriangle,
  error: CircleAlert,
};

const typeColors = {
  info: 'bg-blue-500',
  success: 'bg-green-500',
  warning: 'bg-yellow-500',
  error: 'bg-red-500',
};

const typeBgColors = {
  info: 'bg-blue-50 border-blue-200',
  success: 'bg-green-50 border-green-200',
  warning: 'bg-yellow-50 border-yellow-200',
  error: 'bg-red-50 border-red-200',
};

interface NotificationCenterProps {
  className?: string;
}

export function NotificationCenter({ className }: NotificationCenterProps) {
  const [open, setOpen] = useState(false);
  const handleOnNotification = useCallback((notification: Notification) => {
    // Mostrar toast para notificaciones importantes
    if (notification.type === 'error' || notification.type === 'warning') {
      // Aquí podrías integrar con use-toast
      console.log('Notificación importante:', notification);
    }
  }, []);

  const {
    notifications,
    unreadCount,
    connected,
    markAsRead,
    markAllAsRead,
    removeNotification,
    clearAll,
  } = useRealtimeNotifications({
    onNotification: handleOnNotification,
  });

  const handleMarkAsRead = (id: string) => {
    markAsRead(id);
  };

  const handleRemove = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    removeNotification(id);
  };

  const handleNotificationClick = (notification: Notification) => {
    if (!notification.read) {
      markAsRead(notification.id);
    }
    
    if (notification.action?.url) {
      window.open(notification.action.url, '_blank');
    }
  };

  const { isFieldMode } = useFieldMode();
  const { isOnline, pendingOperations, syncStatus } = useOnlineStatus();

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="ghost"
          size="icon"
          className={cn(
            "relative h-10 w-10 rounded-2xl transition-all duration-500",
            unreadCount > 0 ? "bg-primary/10 text-primary" : "hover:bg-primary/10 text-muted-foreground hover:text-primary",
            className
          )}
        >
          <motion.div
            animate={unreadCount > 0 ? { 
              rotate: [0, -10, 10, -10, 10, 0],
              scale: [1, 1.1, 1] 
            } : {}}
            transition={{ duration: 0.5, repeat: unreadCount > 0 ? Infinity : 0, repeatDelay: 5 }}
          >
            <Bell className="h-5 w-5" />
          </motion.div>
          
          {/* Indicador de conexión sutil */}
          <span
            className={cn(
              "absolute top-2 right-2 w-2 h-2 rounded-full ring-2 ring-background",
              isOnline ? "bg-emerald-500" : "bg-rose-500 animate-pulse"
            )}
          />
          
          {/* Badge de no leídas */}
          <AnimatePresence>
            {unreadCount > 0 && (
              <motion.span
                initial={{ scale: 0 }}
                animate={{ scale: 1 }}
                exit={{ scale: 0 }}
                className="absolute -top-1 -right-1 h-5 w-5 flex items-center justify-center bg-primary text-primary-foreground text-[10px] font-black rounded-full border-2 border-background shadow-lg shadow-primary/30"
              >
                {unreadCount > 99 ? '99+' : unreadCount}
              </motion.span>
            )}
          </AnimatePresence>
        </Button>
      </PopoverTrigger>

      <PopoverContent className="w-[380px] p-0 bg-card/60 backdrop-blur-2xl border-border/50 rounded-3xl shadow-2xl overflow-hidden mt-2" align="end">

        {/* Header */}
        <div className="flex items-center justify-between p-5 border-b border-border/30 bg-muted/20">
          <div className="flex flex-col">
            <div className="flex items-center gap-2">
              <span className="text-sm font-black uppercase tracking-widest text-foreground">Centro de Alertas</span>
              {unreadCount > 0 && (
                <span className="px-2 py-0.5 bg-primary text-primary-foreground text-[10px] font-black rounded-full">
                  {unreadCount} NUEVAS
                </span>
              )}
            </div>
            <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-tighter mt-1 italic">Notificaciones en tiempo real</span>
          </div>
          
          <div className="flex items-center gap-1">
            {unreadCount > 0 && (
              <Button
                variant="ghost"
                size="icon"
                onClick={markAllAsRead}
                className="h-8 w-8 rounded-xl hover:bg-primary/10 text-primary"
                title="Marcar todas como leídas"
              >
                <Check className="h-4 w-4" />
              </Button>
            )}
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8 rounded-xl hover:bg-rose-500/10 text-rose-500"
              onClick={clearAll}
              title="Limpiar todo"
            >
              <Trash2 className="h-4 w-4" />
            </Button>
          </div>
        </div>

        {/* Sección de Salud del Sistema */}
        <div className="px-5 py-4 bg-muted/40 border-b border-border/30">
          <div className="flex items-center justify-between mb-3">
            <h5 className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground/70">Estado del Sistema</h5>
            <div className={cn(
              "flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[9px] font-black uppercase",
              isOnline ? "bg-emerald-500/10 text-emerald-500" : "bg-rose-500/10 text-rose-500 animate-pulse"
            )}>
              {isOnline ? <Wifi className="h-3 w-3" /> : <WifiOff className="h-3 w-3" />}
              {isOnline ? "En Línea" : "Offline"}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="p-3 rounded-2xl bg-background/50 border border-border/50 shadow-sm group">
              <div className="flex items-center gap-2 mb-1">
                <RefreshCw className={cn("h-3 w-3", syncStatus.syncing ? "text-blue-500 animate-spin" : "text-muted-foreground")} />
                <span className="text-[10px] font-black text-muted-foreground uppercase">Sincro</span>
              </div>
              <p className="text-sm font-black text-foreground">
                {pendingOperations > 0 ? pendingOperations : "Al día"}
              </p>
            </div>
            
            <div className="p-3 rounded-2xl bg-background/50 border border-border/50 shadow-sm">
              <div className="flex items-center gap-2 mb-1">
                <CircleCheck className="h-3 w-3 text-emerald-500" />
                <span className="text-[10px] font-black text-muted-foreground uppercase">Cloud</span>
              </div>
              <p className="text-sm font-black text-foreground">Estable</p>
            </div>
          </div>
        </div>


        {/* Lista de notificaciones */}
        <ScrollArea className="h-80">
          {notifications.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full text-center p-4 text-muted-foreground">
              <Bell className="h-12 w-12 mb-2 opacity-20" />
              <p className="text-sm">No hay notificaciones</p>
              <p className="text-xs">Las notificaciones aparecerán aquí</p>
            </div>
          ) : (
            <div className="divide-y">
              {notifications.map((notification) => {
                const Icon = typeIcons[notification.type];
                
                return (
                  <div
                    key={notification.id}
                    className={cn(
                      "p-4 cursor-pointer transition-colors hover:bg-accent",
                      !notification.read && typeBgColors[notification.type],
                      !notification.read && "border-l-4",
                      !notification.read && typeColors[notification.type].replace('bg-', 'border-')
                    )}
                    onClick={() => handleNotificationClick(notification)}
                  >
                    <div className="flex items-start gap-3">
                      {/* Icono */}
                      <div className={cn(
                        "flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center",
                        typeColors[notification.type]
                      )}>
                        <Icon className="h-4 w-4 text-white" />
                      </div>

                      {/* Contenido */}
                      <div className="flex-1 min-w-0">
                        <div className="flex items-start justify-between gap-2">
                          <p className={cn(
                            "text-sm font-medium",
                            !notification.read && "font-semibold"
                          )}>
                            {notification.title}
                          </p>
                          
                          <div className="flex items-center gap-1 flex-shrink-0">
                            <span className="text-xs text-muted-foreground">
                              {formatDistanceToNow(new Date(notification.timestamp), {
                                addSuffix: true,
                                locale: es,
                              })}
                            </span>
                            
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-6 w-6 opacity-0 group-hover:opacity-100"
                              onClick={(e) => handleRemove(notification.id, e)}
                            >
                              <X className="h-3 w-3" />
                            </Button>
                          </div>
                        </div>

                        <p className="text-sm text-muted-foreground mt-1 line-clamp-2">
                          {notification.message}
                        </p>

                        {/* Botón de acción */}
                        {notification.action && (
                          <div className="mt-2">
                            <Button
                              variant="outline"
                              size="sm"
                              className="h-7 text-xs"
                              onClick={(e) => {
                                e.stopPropagation();
                                window.open(notification.action!.url, '_blank');
                              }}
                            >
                              {notification.action.label}
                              <ExternalLink className="h-3 w-3 ml-1" />
                            </Button>
                          </div>
                        )}

                        {/* Marcar como leída */}
                        {!notification.read && (
                          <Button
                            variant="ghost"
                            size="sm"
                            className="mt-2 h-6 text-xs"
                            onClick={(e) => {
                              e.stopPropagation();
                              handleMarkAsRead(notification.id);
                            }}
                          >
                            <Check className="h-3 w-3 mr-1" />
                            Marcar como leída
                          </Button>
                        )}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </ScrollArea>

        {/* Footer */}
        <div className="p-3 border-t bg-muted/50">
          <div className="flex items-center justify-between text-xs text-muted-foreground">
            <span>
              {connected ? (
                <span className="flex items-center gap-1">
                  <span className="w-2 h-2 bg-green-500 rounded-full" />
                  Conectado
                </span>
              ) : (
                <span className="flex items-center gap-1">
                  <span className="w-2 h-2 bg-red-500 rounded-full" />
                  Desconectado
                </span>
              )}
            </span>
            <span>{notifications.length} notificaciones</span>
          </div>
        </div>
      </PopoverContent>
    </Popover>
  );
}

export default NotificationCenter;

import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useToast } from '@/shared/hooks/use-toast';
import { 
  X, 
  CheckCircle2, 
  AlertCircle, 
  Info, 
  AlertTriangle,
  Bell
} from 'lucide-react';
import { cn } from '@/shared/ui/cn';

const alertIcons = {
  default: Bell,
  success: CheckCircle2,
  error: AlertCircle,
  info: Info,
  warning: AlertTriangle,
};

const alertColors = {
  default: 'bg-white/80 dark:bg-slate-900/80 text-slate-900 dark:text-white border-white/20',
  success: 'bg-emerald-500/10 text-emerald-600 border-emerald-500/20 dark:text-emerald-400',
  error: 'bg-rose-500/10 text-rose-600 border-rose-500/20 dark:text-rose-400',
  info: 'bg-blue-500/10 text-blue-600 border-blue-500/20 dark:text-blue-400',
  warning: 'bg-amber-500/10 text-amber-600 border-amber-500/20 dark:text-amber-400',
};

const alertGlows = {
  default: 'shadow-slate-500/5',
  success: 'shadow-emerald-500/10',
  error: 'shadow-rose-500/10',
  info: 'shadow-blue-500/10',
  warning: 'shadow-amber-500/10',
};

export function SystemAlertsHub() {
  const { toasts, dismiss } = useToast();

  return (
    <div className="fixed top-6 left-1/2 -translate-x-1/2 z-[99999] flex flex-col items-center gap-3 w-full max-w-[420px] pointer-events-none px-4">
      <AnimatePresence mode="popLayout">
        {toasts.map((toast, index) => {
          // @ts-ignore - variant might not be on the base type but we use it
          const variant = toast.variant || 'default';
          const Icon = alertIcons[variant as keyof typeof alertIcons] || alertIcons.default;

          return (
            <motion.div
              key={toast.id}
              layout
              initial={{ opacity: 0, y: -20, scale: 0.9, filter: 'blur(10px)' }}
              animate={{ 
                opacity: 1, 
                y: 0, 
                scale: 1 - index * 0.05, 
                filter: 'blur(0px)',
                zIndex: 100 - index
              }}
              exit={{ opacity: 0, scale: 0.8, filter: 'blur(10px)', transition: { duration: 0.2 } }}
              transition={{ 
                type: 'spring', 
                stiffness: 400, 
                damping: 30,
                layout: { duration: 0.3 },
                filter: { type: 'tween', duration: 0.3 }
              }}
              className={cn(
                "pointer-events-auto relative flex items-center gap-4 w-full p-4 rounded-[2rem] border backdrop-blur-2xl shadow-2xl transition-all group",
                alertColors[variant as keyof typeof alertColors],
                alertGlows[variant as keyof typeof alertGlows],
                index > 0 && "opacity-40 scale-95" // Apple-style stacking effect
              )}
              style={{
                marginTop: index > 0 ? `-${index * 10}px` : '0px',
              }}
            >
              <div className={cn(
                "flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl shadow-inner",
                variant === 'default' ? "bg-slate-100 dark:bg-slate-800" : "bg-current opacity-20"
              )}>
                <Icon className="h-6 w-6" />
              </div>

              <div className="flex-1 space-y-1">
                {toast.title && (
                  <h4 className="text-sm font-black uppercase tracking-tight leading-none">
                    {toast.title}
                  </h4>
                )}
                {toast.description && (
                  <p className="text-xs font-medium opacity-80 leading-tight">
                    {toast.description}
                  </p>
                )}
              </div>

              <button
                onClick={() => dismiss(toast.id)}
                className="h-8 w-8 flex items-center justify-center rounded-full hover:bg-black/5 dark:hover:bg-white/5 transition-colors"
              >
                <X className="h-4 w-4" />
              </button>

              {/* Progress bar sutil */}
              <motion.div 
                initial={{ width: '100%' }}
                animate={{ width: '0%' }}
                transition={{ duration: 5, ease: 'linear' }}
                className="absolute bottom-0 left-6 right-6 h-[2px] bg-current opacity-10 rounded-full"
              />
            </motion.div>
          );
        })}
      </AnimatePresence>
    </div>
  );
}

