export interface UseResourceOptions<P extends Record<string, any> = any> {
  autoFetch?: boolean;
  initialParams?: P;
  deps?: any[];
  map?: <T>(items: T[]) => T[];
  cache?: boolean;
  cacheTTL?: number;
  cacheKeyPrefix?: string;
  enableRealtime?: boolean;
  pollIntervalMs?: number;
  refetchOnFocus?: boolean;
  refetchOnReconnect?: boolean;
}

export interface UseResourceResult<T, P extends Record<string, any>> {
  data: T[];
  loading: boolean;
  error: string | null;
  refetch: (params?: P) => Promise<T[]>;
  createItem: (payload: Partial<T>) => Promise<T | null>;
  updateItem: (id: number | string, payload: Partial<T>) => Promise<T | null>;
  deleteItem: (id: number | string) => Promise<boolean>;
  setData: React.Dispatch<React.SetStateAction<T[]>>;
  meta?: {
    page: number;
    limit: number;
    total: number;
    totalPages?: number;
    hasNextPage?: boolean;
    hasPreviousPage?: boolean;
    rawMeta?: any;
  } | null;
  setPage?: (page: number) => void;
  setLimit?: (limit: number) => void;
  setSearch?: (s: string) => void;
  setFields?: (f: string) => void;
  refreshing?: boolean;
}

import { useCallback } from 'react';
import type { BaseService } from '@/shared/api/base-service';
import { UseResourceResult } from './types';

export function useResourceCrud<T extends { id?: number | string }>(
  service: BaseService<T>,
  data: T[],
  setData: React.Dispatch<React.SetStateAction<T[]>>,
  safeExecuteMutation: <R>(fn: () => Promise<R>) => Promise<R | undefined>,
  invalidateByEndpoint: (prefix: string) => void,
  prefix: string,
  crudInProgressRef: React.MutableRefObject<boolean>,
  skipCacheUntilRef: React.MutableRefObject<number>,
  refetch: () => Promise<any>,
  tracker: ReturnType<typeof import('./useResourceTracker').useResourceTracker>
) {
  const {
    recentlyCreatedIds, recentlyCreatedTimestamps, recentlyCreatedItems,
    recentlyUpdatedIds, recentlyUpdatedTimestamps, recentlyUpdatedItems,
    recentlyDeletedIds, recentlyDeletedTimestamps
  } = tracker as any;

  const createItem = useCallback(async (payload: Partial<T>) => {
    crudInProgressRef.current = true;
    try {
      const result = await safeExecuteMutation(async () => {
        const created = await service.create(payload);
        const createdId = String((created as any)?.id);
        if (createdId && createdId !== 'undefined') {
          recentlyCreatedIds.current.add(createdId);
          recentlyCreatedTimestamps.current.set(createdId, Date.now());
          recentlyCreatedItems.current.set(createdId, created);

          const now = Date.now();
          for (const [id, timestamp] of Array.from(recentlyCreatedTimestamps.current.entries())) {
            if (now - timestamp > 120000) {
              recentlyCreatedIds.current.delete(id);
              recentlyCreatedTimestamps.current.delete(id);
              recentlyCreatedItems.current.delete(id);
            }
          }
        }

        invalidateByEndpoint(prefix);
        if (typeof (service as any).clearCache === 'function') {
          (service as any).clearCache();
        }
        skipCacheUntilRef.current = Date.now() + 30000;

        setData((prev: T[]) => {
          const arr = Array.isArray(prev) ? prev : [];
          const createdIdRaw = (created as any)?.id;
          const createdIdKey = createdIdRaw != null ? String(createdIdRaw) : null;
          const dedup = createdIdKey != null ? arr.filter((x: any) => String(x?.id) !== createdIdKey) : arr;
          return [created as any, ...dedup];
        });

        return created;
      });
      return result === undefined ? null : result;
    } catch (error) {
      throw error;
    } finally {
      crudInProgressRef.current = false;
    }
  }, [service, safeExecuteMutation, invalidateByEndpoint, prefix, setData, recentlyCreatedIds, recentlyCreatedTimestamps, recentlyCreatedItems, skipCacheUntilRef, crudInProgressRef]);

  const updateItem = useCallback(async (id: number | string, payload: Partial<T>) => {
    crudInProgressRef.current = true;
    try {
      const result = await safeExecuteMutation(async () => {
        const updatedRaw = await service.update(id, payload);
        const updated = (updatedRaw && typeof updatedRaw === 'object')
          ? { ...(payload as any), ...(updatedRaw as any) }
          : { ...(payload as any), id };

        const updatedId = String(id);
        if (updatedId && updatedId !== 'undefined') {
          recentlyUpdatedIds.current.add(updatedId);
          recentlyUpdatedTimestamps.current.set(updatedId, Date.now());
          recentlyUpdatedItems.current.set(updatedId, updated);
        }

        invalidateByEndpoint(prefix);
        if (typeof (service as any).clearCache === 'function') {
          (service as any).clearCache();
        }
        skipCacheUntilRef.current = Date.now() + 30000;

        const applyAliasSync = (prevItem: any, nextItem: any) => {
          const hasKey = (obj: any, key: string) => obj && Object.prototype.hasOwnProperty.call(obj, key);
          const mirrorIfNeeded = (a: string, b: string) => {
            const aExists = hasKey(prevItem, a) || hasKey(nextItem, a);
            const bExists = hasKey(prevItem, b) || hasKey(nextItem, b);
            if (!aExists && !bExists) return;
            const aVal = (nextItem as any)[a];
            const bVal = (nextItem as any)[b];
            if (aVal !== undefined && bVal === undefined && bExists) (nextItem as any)[b] = aVal;
            if (bVal !== undefined && aVal === undefined && aExists) (nextItem as any)[a] = bVal;
          };
          mirrorIfNeeded('diagnosis', 'description');
          mirrorIfNeeded('dosis', 'dose');
          mirrorIfNeeded('frequency', 'frecuencia');
          mirrorIfNeeded('observations', 'notes');
          mirrorIfNeeded('status', 'estado');
          return nextItem;
        };

        setData((prev: T[]) => prev.map((i: any) => {
          if (String(i?.id) !== String(id)) return i;
          const next = { ...i, ...updated };
          return applyAliasSync(i, next);
        }));

        if (typeof navigator === 'undefined' || navigator.onLine !== false) {
          void refetch();
        }

        return updated;
      });
      return result === undefined ? null : result;
    } catch (error) {
      throw error;
    } finally {
      crudInProgressRef.current = false;
    }
  }, [service, safeExecuteMutation, invalidateByEndpoint, prefix, setData, refetch, recentlyUpdatedIds, recentlyUpdatedTimestamps, recentlyUpdatedItems, skipCacheUntilRef, crudInProgressRef]);

  const deleteItem = useCallback(async (id: number | string) => {
    crudInProgressRef.current = true;
    try {
      const result = await safeExecuteMutation(async () => {
        try {
          const ok = await service.delete(id);
          if (ok) {
            const deletedId = String(id);
            recentlyCreatedIds.current.delete(deletedId);
            recentlyCreatedTimestamps.current.delete(deletedId);
            recentlyCreatedItems.current.delete(deletedId);

            recentlyDeletedIds.current.add(deletedId);
            recentlyDeletedTimestamps.current.set(deletedId, Date.now());

            const now = Date.now();
            for (const [delId, timestamp] of Array.from(recentlyDeletedTimestamps.current.entries())) {
              if (now - timestamp > 10000) {
                recentlyDeletedIds.current.delete(delId);
                recentlyDeletedTimestamps.current.delete(delId);
              }
            }

            invalidateByEndpoint(prefix);
            if (typeof (service as any).clearCache === 'function') {
              (service as any).clearCache();
            }
            skipCacheUntilRef.current = Date.now() + 15000;
            setData((prev: T[]) => prev.filter((i: any) => String(i?.id) !== String(id)));
          }
          return ok;
        } catch (err: any) {
          if (err?.response?.status === 404) {
            const deletedId = String(id);
            recentlyCreatedIds.current.delete(deletedId);
            recentlyCreatedTimestamps.current.delete(deletedId);
            recentlyCreatedItems.current.delete(deletedId);

            recentlyDeletedIds.current.add(deletedId);
            recentlyDeletedTimestamps.current.set(deletedId, Date.now());

            invalidateByEndpoint(prefix);
            if (typeof (service as any).clearCache === 'function') {
              (service as any).clearCache();
            }
            skipCacheUntilRef.current = Date.now() + 15000;
            setData((prev: T[]) => prev.filter((i: any) => String(i?.id) !== String(id)));
          }
          throw err;
        }
      });
      return result === undefined ? false : result;
    } catch (err) {
      throw err;
    } finally {
      crudInProgressRef.current = false;
    }
  }, [service, safeExecuteMutation, invalidateByEndpoint, prefix, setData, recentlyCreatedIds, recentlyCreatedTimestamps, recentlyCreatedItems, recentlyDeletedIds, recentlyDeletedTimestamps, skipCacheUntilRef, crudInProgressRef]);

  return { createItem, updateItem, deleteItem };
}

import { useCallback } from 'react';
import { useSearchParams } from 'react-router-dom';

export function useResourceParams<P extends Record<string, any>>(
  initialParams?: P,
  lastParamsRef?: React.MutableRefObject<P | undefined>
) {
  const [searchParams, setSearchParams] = useSearchParams();

  const pageQP = Number(searchParams.get('page') || '') || undefined;
  const limitQP = Number(searchParams.get('limit') || '') || undefined;
  const searchQP = searchParams.get('search') || undefined;
  const fieldsQP = searchParams.get('fields') || undefined;
  const orderingQP = searchParams.get('ordering') || undefined;
  const sortByQP = searchParams.get('sort_by') || undefined;
  const sortOrderQP = (searchParams.get('sort_order') as 'asc' | 'desc' | undefined) || undefined;

  const setPage = useCallback((page: number) => {
    const sp = new URLSearchParams(searchParams);
    sp.set('page', String(page));
    setSearchParams(sp, { replace: true });
  }, [searchParams, setSearchParams]);

  const setLimit = useCallback((limit: number) => {
    const sp = new URLSearchParams(searchParams);
    sp.set('limit', String(limit));
    sp.set('page', '1');
    setSearchParams(sp, { replace: true });
  }, [searchParams, setSearchParams]);

  const setSearch = useCallback((s: string) => {
    const sp = new URLSearchParams(searchParams);
    if (s) sp.set('search', s); else sp.delete('search');
    sp.set('page', '1');
    setSearchParams(sp, { replace: true });
  }, [searchParams, setSearchParams]);

  const setFields = useCallback((f: string) => {
    const sp = new URLSearchParams(searchParams);
    if (f) sp.set('fields', f); else sp.delete('fields');
    setSearchParams(sp, { replace: true });
  }, [searchParams, setSearchParams]);

  const buildEffectiveParams = useCallback((): Record<string, any> | undefined => {
    const base = { ...(initialParams as any) };
    const last = { ...(lastParamsRef?.current as any) };
    const fromURL: Record<string, any> = {};
    if (pageQP !== undefined) fromURL.page = pageQP;
    if (limitQP !== undefined) fromURL.limit = limitQP;
    if (searchQP !== undefined) fromURL.search = searchQP;
    if (fieldsQP !== undefined) fromURL.fields = fieldsQP;
    if (sortByQP !== undefined) fromURL.sort_by = sortByQP;
    if (sortOrderQP !== undefined) fromURL.sort_order = sortOrderQP;
    if (orderingQP !== undefined && fromURL.sort_by === undefined) {
      fromURL.ordering = orderingQP;
    }
    return { ...base, ...last, ...fromURL };
  }, [fieldsQP, initialParams, limitQP, pageQP, searchQP, orderingQP, sortByQP, sortOrderQP, lastParamsRef]);

  return {
    pageQP, limitQP, searchQP, fieldsQP,
    setPage, setLimit, setSearch, setFields,
    buildEffectiveParams
  };
}

import { useEffect, useRef } from 'react';
import { UseResourceOptions } from './types';

export function useResourceRealtime(
  options: UseResourceOptions,
  refetch: () => Promise<any>,
  crudInProgressRef: React.MutableRefObject<boolean>,
  skipCacheUntilRef: React.MutableRefObject<number>,
  endpointPrefix: string
) {
  const realtimeEnabled = options.enableRealtime === true;
  const pollInterval = typeof options.pollIntervalMs === 'number'
    ? (options.pollIntervalMs > 0 ? Math.max(2000, options.pollIntervalMs) : 0)
    : 0;
  const refetchOnFocus = options.refetchOnFocus !== false;
  const refetchOnReconnect = options.refetchOnReconnect !== false;
  const pollTimerRef = useRef<any>(null);

  useEffect(() => {
    if (!realtimeEnabled || !pollInterval) return;
    if (pollTimerRef.current) {
      try { clearInterval(pollTimerRef.current); } catch { /* noop */ }
      pollTimerRef.current = null;
    }
    pollTimerRef.current = setInterval(() => {
      if (crudInProgressRef.current) return;
      skipCacheUntilRef.current = Date.now() + 5000;
      void refetch().catch(() => {});
    }, pollInterval);
    return () => {
      if (pollTimerRef.current) {
        try { clearInterval(pollTimerRef.current); } catch { /* noop */ }
        pollTimerRef.current = null;
      }
    };
  }, [realtimeEnabled, pollInterval, refetch, crudInProgressRef, skipCacheUntilRef]);

  useEffect(() => {
    const onFocus = () => {
      if (!realtimeEnabled || !refetchOnFocus) return;
      if (crudInProgressRef.current) return;
      skipCacheUntilRef.current = Date.now() + 5000;
      void refetch().catch(() => {});
    };
    const onOnline = () => {
      if (!realtimeEnabled || !refetchOnReconnect) return;
      if (crudInProgressRef.current) return;
      skipCacheUntilRef.current = Date.now() + 5000;
      void refetch().catch(() => {});
    };
    if (realtimeEnabled) {
      window.addEventListener('focus', onFocus);
      const onVisibility = () => { if (document.visibilityState === 'visible') onFocus(); };
      window.addEventListener('visibilitychange', onVisibility);
      window.addEventListener('online', onOnline);
      return () => {
        window.removeEventListener('focus', onFocus);
        window.removeEventListener('visibilitychange', onVisibility);
        window.removeEventListener('online', onOnline);
      };
    }
    return () => {};
  }, [realtimeEnabled, refetchOnFocus, refetchOnReconnect, refetch, crudInProgressRef, skipCacheUntilRef]);

  useEffect(() => {
    if (!realtimeEnabled) return;
    const endpointSlug = (() => {
      const parts = String(endpointPrefix || '').split('/').filter(Boolean);
      return parts.length ? parts[parts.length - 1] : endpointPrefix;
    })();
    const onResourceChanged = (e: Event) => {
      const detail = (e as CustomEvent).detail || {};
      const slug = String(detail?.endpoint || '');
      if (!slug || slug !== endpointSlug) return;
      if (crudInProgressRef.current) return;
      skipCacheUntilRef.current = Date.now() + 5000;
      void refetch().catch(() => {});
    };
    const onGlobalChange = () => {
      if (crudInProgressRef.current) return;
      skipCacheUntilRef.current = Date.now() + 5000;
      void refetch().catch(() => {});
    };
    window.addEventListener('server-resource-changed', onResourceChanged as EventListener);
    window.addEventListener('server-global-change', onGlobalChange as EventListener);
    return () => {
      window.removeEventListener('server-resource-changed', onResourceChanged as EventListener);
      window.removeEventListener('server-global-change', onGlobalChange as EventListener);
    };
  }, [realtimeEnabled, refetch, crudInProgressRef, skipCacheUntilRef, endpointPrefix]);

}

import { useCallback } from 'react';
import axios from 'axios';
import type { BaseService } from '@/shared/api/base-service';
import { UseResourceResult } from './types';

// Global registries
export const __resourceRefetchers = new Set<() => Promise<any>>();
export const __resourceInflight = new Map<string, Promise<any>>();
export const __resourceLastFetchAt = new Map<string, number>();
export const __endpointBackoffUntil = new Map<string, number>();

export async function refetchAllResources(): Promise<void> {
  const fns = Array.from(__resourceRefetchers);
  await Promise.allSettled(
    fns.map((fn) => {
      try { return fn(); } catch { return Promise.resolve(); }
    })
  );
}

export function registerResourceRefetch(fn: () => Promise<any>): () => void {
  __resourceRefetchers.add(fn);
  return () => {
    __resourceRefetchers.delete(fn);
  };
}

function buildPaginatedResponse<T>(items: T[], params?: Record<string, any>) {
  const limit = Number(params?.limit ?? items.length ?? 10);
  const page = Number(params?.page ?? 1);
  return {
    data: items,
    total: items.length,
    page,
    limit,
    totalPages: Math.max(1, Math.ceil(items.length / Math.max(1, limit))),
    hasNextPage: false,
    hasPreviousPage: page > 1,
    rawMeta: { page_size: limit, totalPages: Math.max(1, Math.ceil(items.length / Math.max(1, limit))) }
  };
}

async function fetchServicePage<T>(service: BaseService<T>, params?: Record<string, any>) {
  const paginatedFn = (service as any)?.getPaginated;
  if (typeof paginatedFn === 'function') {
    return paginatedFn.call(service, params);
  }
  const allFn = (service as any)?.getAll;
  if (typeof allFn === 'function') {
    const items = await allFn.call(service, params);
    return buildPaginatedResponse<T>(Array.isArray(items) ? items : [], params);
  }
  throw new Error(`El servicio ${String((service as any)?.endpoint || service.constructor?.name || 'desconocido')} no expone getPaginated ni getAll`);
}

export function useResourceRefetch<T extends { id?: number | string }, P extends Record<string, any>>(
  service: BaseService<T>,
  data: T[],
  setData: React.Dispatch<React.SetStateAction<T[]>>,
  setMeta: React.Dispatch<React.SetStateAction<UseResourceResult<T, P>["meta"]>>,
  setRefreshing: React.Dispatch<React.SetStateAction<boolean>>,
  safeExecute: <R>(fn: () => Promise<R>) => Promise<R | undefined>,
  buildEffectiveParams: () => Record<string, any> | undefined,
  prefix: string,
  generateKey: (prefix: string, params: any) => string,
  getCache: (key: string) => any,
  setCache: (key: string, data: any, ttl: number) => void,
  cacheTTL: number | undefined,
  cache: boolean,
