import { useRef, useCallback } from 'react';

export function useResourceTracker<T>() {
  const recentlyCreatedIds = useRef<Set<string>>(new Set());
  const recentlyCreatedTimestamps = useRef<Map<string, number>>(new Map());
  const recentlyCreatedItems = useRef<Map<string, T>>(new Map());

  const recentlyUpdatedIds = useRef<Set<string>>(new Set());
  const recentlyUpdatedTimestamps = useRef<Map<string, number>>(new Map());
  const recentlyUpdatedItems = useRef<Map<string, T>>(new Map());

  const recentlyDeletedIds = useRef<Set<string>>(new Set());
  const recentlyDeletedTimestamps = useRef<Map<string, number>>(new Map());

  const applyStableOrder = useCallback((list: T[], currentData: T[]): T[] => {
    if (!Array.isArray(list) || list.length === 0) return list;
    if (!Array.isArray(currentData) || currentData.length === 0) return list;

    const now = Date.now();
    for (const [id, ts] of Array.from(recentlyUpdatedTimestamps.current.entries())) {
      if (now - ts > 120000) {
        recentlyUpdatedIds.current.delete(id);
        recentlyUpdatedTimestamps.current.delete(id);
        recentlyUpdatedItems.current.delete(id);
      }
    }

    if (recentlyUpdatedIds.current.size === 0) return list;

    const nextMap = new Map<string, T>();
    list.forEach((item) => {
      const id = String((item as any)?.id);
      if (id && id !== 'undefined') nextMap.set(id, item);
    });

    const ordered: T[] = [];
    const used = new Set<string>();
    currentData.forEach((prevItem) => {
      const id = String((prevItem as any)?.id);
      if (!id || id === 'undefined') return;
      const nextItem = nextMap.get(id);
      if (nextItem) {
        ordered.push(nextItem);
        used.add(id);
      }
    });

    list.forEach((item) => {
      const id = String((item as any)?.id);
      if (!id || id === 'undefined' || used.has(id)) return;
      ordered.push(item);
    });

    return ordered.length > 0 ? ordered : list;
  }, []);

  return {
    recentlyCreatedIds,
    recentlyCreatedTimestamps,
    recentlyCreatedItems,
    recentlyUpdatedIds,
    recentlyUpdatedTimestamps,
    recentlyUpdatedItems,
    recentlyDeletedIds,
    recentlyDeletedTimestamps,
    applyStableOrder
  };
}

import { useState, useCallback, useRef, useEffect } from 'react';
// Definición local de ApiError (el backend no expone un tipo formal)
export interface ApiError {
  message: string;
  status?: number;
  code?: string;
  details?: any;
}

/**
 * Interfaz para el estado de una operación API
 */
interface ApiState<T = any> {
  data: T | null;
  loading: boolean;
  error: ApiError | null;
  success: boolean;
}

/**
 * Interfaz para opciones de configuración del hook
 */
interface UseApiStateOptions {
  initialData?: any;
  resetOnNewRequest?: boolean;
  debounceMs?: number;
  retryAttempts?: number;
  retryDelay?: number;
}

/**
 * Interfaz para el resultado del hook
 */
interface UseApiStateResult<T> extends ApiState<T> {
  execute: (apiCall: () => Promise<T>) => Promise<T | null>;
  reset: () => void;
  setData: (data: T | null) => void;
  setError: (error: ApiError | null) => void;
  retry: () => Promise<T | null>;
  isIdle: boolean;
}

/**
 * Hook personalizado para manejar estados de carga, errores y datos de APIs
 * Implementa las mejores prácticas para el manejo de estados asincrónicos
 */
export function useApiState<T = any>(options: UseApiStateOptions = {}): UseApiStateResult<T> {
  const {
    initialData = null,
    resetOnNewRequest = true,
    debounceMs = 0,
    retryAttempts = 0,
    retryDelay = 1000
  } = options;

  // Estado principal
  const [state, setState] = useState<ApiState<T>>({
    data: initialData,
    loading: false,
    error: null,
    success: false
  });

  // Referencias para control de ejecución
  const abortControllerRef = useRef<AbortController | null>(null);
  const lastApiCallRef = useRef<(() => Promise<T>) | null>(null);
  const debounceTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const mountedRef = useRef(true);

  // Cleanup al desmontar el componente
  useEffect(() => {
    return () => {
      mountedRef.current = false;
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
      if (debounceTimeoutRef.current) {
        clearTimeout(debounceTimeoutRef.current);
      }
    };
  }, []);

  /**
   * Actualizar estado de forma segura (solo si el componente está montado)
   */
  const safeSetState = useCallback((newState: Partial<ApiState<T>>) => {
    if (mountedRef.current) {
      setState((prevState: ApiState<T>) => ({ ...prevState, ...newState }));
    }
  }, []);

  /**
   * Ejecutar llamada a la API con manejo de errores y reintentos
   */
  const executeApiCall = useCallback(async (apiCall: () => Promise<T>, attempt = 1): Promise<T | null> => {
    try {
      // Cancelar petición anterior si existe
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }

      // Crear nuevo AbortController
      abortControllerRef.current = new AbortController();

      // Resetear estado si es necesario
      if (resetOnNewRequest && attempt === 1) {
        safeSetState({
          data: null,
          error: null,
          success: false
        });
      }

      // Establecer estado de carga
      safeSetState({ loading: true });

      // Ejecutar la llamada a la API
      const result = await apiCall();

      // Verificar si el componente sigue montado
      if (!mountedRef.current) {
        return null;
      }

      // Actualizar estado con éxito
      safeSetState({
        data: result,
        loading: false,
        error: null,
        success: true
      });

      return result;
    } catch (error: any) {
      // Verificar si el componente sigue montado
      if (!mountedRef.current) {
        return null;
      }

      // Ignorar errores de cancelación
      if (error.name === 'AbortError' || error.message?.includes('canceled')) {
        return null;
      }

      // Convertir error al formato estándar
      const apiError: ApiError = {
        message: error.message || 'Error desconocido',
        status: error.status || 0,
        code: error.code || 'UNKNOWN_ERROR',
        details: error.details || error
      };

      // Intentar reintento si está configurado
      if (attempt <= retryAttempts && apiError.status && apiError.status >= 500) {
        console.warn(`Reintentando petición (intento ${attempt}/${retryAttempts})...`);
        
        // Esperar antes del reintento
        await new Promise(resolve => setTimeout(resolve, retryDelay * attempt));
        
        return executeApiCall(apiCall, attempt + 1);
      }

      // Actualizar estado con error
      safeSetState({
        loading: false,
        error: apiError,
        success: false
      });

      console.error('Error en llamada API:', apiError);
      return null;
    }
  }, [resetOnNewRequest, retryAttempts, retryDelay, safeSetState]);

  /**
   * Función principal para ejecutar llamadas API con debounce opcional
   */
  const execute = useCallback((apiCall: () => Promise<T>): Promise<T | null> => {
    // Guardar referencia para retry
    lastApiCallRef.current = apiCall;

    return new Promise((resolve) => {
      // Limpiar timeout anterior si existe
      if (debounceTimeoutRef.current) {
        clearTimeout(debounceTimeoutRef.current);
      }

      // Aplicar debounce si está configurado
      if (debounceMs > 0) {
        debounceTimeoutRef.current = setTimeout(async () => {
          const result = await executeApiCall(apiCall);
          resolve(result);
        }, debounceMs);
      } else {
        executeApiCall(apiCall).then(resolve);
      }
    });
  }, [debounceMs, executeApiCall]);

  /**
   * Reintentar la última llamada API
   */
  const retry = useCallback((): Promise<T | null> => {
    if (lastApiCallRef.current) {
      return execute(lastApiCallRef.current);
    }
    console.warn('No hay llamada API previa para reintentar');
    return Promise.resolve(null);
  }, [execute]);

  /**
   * Resetear el estado a valores iniciales
   */
  const reset = useCallback(() => {
    // Cancelar petición en curso
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }

    // Limpiar timeout de debounce
    if (debounceTimeoutRef.current) {
      clearTimeout(debounceTimeoutRef.current);
    }

    // Resetear estado
    safeSetState({
      data: initialData,
      loading: false,
      error: null,
      success: false
    });

    // Limpiar referencia de última llamada
    lastApiCallRef.current = null;
  }, [initialData, safeSetState]);

  /**
   * Establecer datos manualmente
   */
  const setData = useCallback((data: T | null) => {
    safeSetState({
      data,
      error: null,
      success: data !== null
    });
  }, [safeSetState]);

  /**
   * Establecer error manualmente
   */
  const setError = useCallback((error: ApiError | null) => {
    safeSetState({
      error,
      loading: false,
      success: false
    });
  }, [safeSetState]);

  return {
    ...state,
    execute,
    reset,
    setData,
    setError,
    retry,
    isIdle: !state.loading && !state.error && !state.success
  };
}

/**
 * Hook simplificado para operaciones CRUD comunes
 */
export function useCrudState<T = any>(options: UseApiStateOptions = {}) {
  const createState = useApiState<T>(options);
  const updateState = useApiState<T>(options);
  const deleteState = useApiState<boolean>(options);
  const fetchState = useApiState<T[]>({ ...options, initialData: [] });

  const reset = useCallback(() => {
    createState.reset();
    updateState.reset();
    deleteState.reset();
    fetchState.reset();
  }, [createState, updateState, deleteState, fetchState]);

  return {
    create: createState,
    update: updateState,
    delete: deleteState,
    fetch: fetchState,
    reset,
    isLoading: createState.loading || updateState.loading || deleteState.loading || fetchState.loading,
    hasError: !!(createState.error || updateState.error || deleteState.error || fetchState.error)
  };
}

export default useApiState;

import * as React from 'react';
import { unwrapArray } from '@/shared/utils/apiUnwrap';

export interface FKOption {
  value: number | string;
  label: string;
}

type FetchFn = (params?: Record<string, any>) => Promise<any>;

/**
 * Hook minimalista para selectors de llaves foráneas con búsqueda.
 * - Recibe un `fetchFn` (servicio) y un mapper a opción.
 * - Soporta filtro opcional.
 * - Maneja loading y protección contra respuestas fuera de orden.
 */
export function useForeignKeySelect(
  fetchFn: FetchFn,
  mapToOption: (item: any) => FKOption,
  filterFn?: (item: any) => boolean,
  initialLimit: number = 1000,
  searchLimit: number = 50
) {
  const [options, setOptions] = React.useState<FKOption[]>([]);
  const [loading, setLoading] = React.useState<boolean>(false);
  const tokenRef = React.useRef<{ token: number }>({ token: 0 });
  const fetchFnRef = React.useRef<FetchFn>(fetchFn);
  const mapToOptionRef = React.useRef<(item: any) => FKOption>(mapToOption);
  const filterFnRef = React.useRef<typeof filterFn>(filterFn);
  const queryCacheRef = React.useRef<Map<string, { ts: number; options: FKOption[] }>>(new Map());
  const searchDebounceRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);
  const CACHE_TTL_MS = 60_000; // 60s por defecto para caché de búsquedas

  // Mantener refs actualizados sin re-crear callbacks
  React.useEffect(() => { fetchFnRef.current = fetchFn; }, [fetchFn]);
  React.useEffect(() => { mapToOptionRef.current = mapToOption; }, [mapToOption]);
  React.useEffect(() => { filterFnRef.current = filterFn; }, [filterFn]);

  const toList = React.useCallback((response: any) => {
    // Si es una respuesta paginada con data
    if (response && typeof response === 'object' && 'data' in response && Array.isArray(response.data)) {
      return response.data;
    }
    // Si es un array directo
    if (Array.isArray(response)) {
      return response;
    }
    // Usar unwrapArray como fallback
    const unwrapped = unwrapArray(response);
    return unwrapped;
  }, []);

  const loadOptions = React.useCallback(async (params: Record<string, any> = {}) => {
    setLoading(true);
    const token = ++tokenRef.current.token;
    try {
      const resp = await fetchFnRef.current({ page: 1, limit: initialLimit, ...params });
      const list = toList(resp);
      if (tokenRef.current.token === token) {
        const filtered = filterFnRef.current ? list.filter(filterFnRef.current) : list;
        setOptions(filtered.map(mapToOptionRef.current));
      }
    } catch (error) {
      console.error('[useForeignKeySelect] Error loading options:', error);
      if (tokenRef.current.token === token) {
        setOptions([]);
      }
    } finally {
      if (tokenRef.current.token === token) {
        setLoading(false);
      }
    }
  }, [initialLimit, toList]);

  // Carga inicial
  React.useEffect(() => {
    loadOptions();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleSearch = React.useCallback((q: string) => {
    if (searchDebounceRef.current) clearTimeout(searchDebounceRef.current);
    searchDebounceRef.current = setTimeout(async () => {
      const query = (q || '').trim();
      if (!query) {
        await loadOptions({ limit: initialLimit });
        return;
      }
      const key = `q:${query.toLowerCase()}|limit:${searchLimit}`;
      const cached = queryCacheRef.current.get(key);
      if (cached && (Date.now() - cached.ts) <= CACHE_TTL_MS) {
        setOptions(cached.options);
        setLoading(false);
        return;
      }
      setLoading(true);
      const token = ++tokenRef.current.token;
      try {
        const resp = await fetchFnRef.current({ page: 1, limit: searchLimit, search: query, q: query });
        const list = toList(resp);
        if (tokenRef.current.token === token) {
          const filtered = filterFnRef.current ? list.filter(filterFnRef.current) : list;
          const mapped = filtered.map(mapToOptionRef.current);
          setOptions(mapped);
          queryCacheRef.current.set(key, { ts: Date.now(), options: mapped });
        }
      } catch (error) {
        console.error('[useForeignKeySelect] Error searching options:', error);
        if (tokenRef.current.token === token) {
          setOptions([]);
        }
      } finally {
        if (tokenRef.current.token === token) {
          setLoading(false);
        }
      }
    }, 250);
  }, [initialLimit, searchLimit, toList, loadOptions]);

  // Cleanup de debounce al desmontar
  React.useEffect(() => {
    return () => {
      if (searchDebounceRef.current) {
        clearTimeout(searchDebounceRef.current);
        searchDebounceRef.current = null;
      }
    };
  }, []);

  const refresh = React.useCallback(() => {
    loadOptions();
  }, [loadOptions]);

  return { options, loading, handleSearch, refresh };
}

export default useForeignKeySelect;

import React from 'react';
import { useState, useEffect, useCallback, useRef } from 'react';
import { BaseService } from '@/shared/api/base-service';
import { useCache, useCacheKey } from '@/app/providers/CacheContext';
import axios from 'axios';

import { useSearchParams } from 'react-router-dom';

// Tipos públicos de la API del hook
export type UseGenericCRUDOptions = {
  cacheTTL?: number;
  enableCache?: boolean;
  autoRefresh?: boolean;
};

export type FetchByIdParams = { fields?: string };

export type UseGenericCRUDResult<T extends { id?: number }> = {
  items: T[];
  loading: boolean;
  error: string | null;
  page: number;
  setPage: (p: number) => void;
  limit: number;
  setLimit: (l: number) => void;
  search?: string;
  setSearch: (s: string) => void;
  fields?: string;
  setFields: (f: string) => void;
  total: number;
  totalPages: number;
  hasNextPage: boolean;
  hasPreviousPage: boolean;
  fetchItems: (forceRefresh?: boolean) => Promise<T[]>;
  refreshItems: () => void;
  clearError: () => void;
  addItem: (itemData: Partial<T>) => Promise<T | null>;
  updateItem: (id: number, itemData: Partial<T>) => Promise<T | null>;
  deleteItem: (id: number) => Promise<boolean>;
  fetchItemById: (id: number, params?: FetchByIdParams, forceRefresh?: boolean) => Promise<T | null>;
  // Compat names
  data: T[];
  setData: React.Dispatch<React.SetStateAction<T[]>>;
  // Nuevo: estado de refresco suave para evitar parpadeos en UI
  refreshing?: boolean;
};

export type SpecificCRUDHook<T extends { id?: number }> = () => UseGenericCRUDResult<T>;

/**
 * Hook genérico para operaciones CRUD con caché inteligente
 * Elimina la redundancia de código y peticiones innecesarias
 */
export function useGenericCRUD<T extends { id?: number }>(
  service: BaseService<T>,
  entityName: string,
  options: UseGenericCRUDOptions = {}
): UseGenericCRUDResult<T> {
  const { cacheTTL = 15 * 60 * 1000, enableCache = true, autoRefresh = true } = options;
  
  const [items, setItems] = useState<T[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [reload, setReload] = useState<boolean>(false);
  const listCancelTokenSourceRef = useRef<ReturnType<typeof axios.CancelToken.source> | null>(axios.CancelToken.source());
  const itemCancelTokenSourceRef = useRef<ReturnType<typeof axios.CancelToken.source> | null>(axios.CancelToken.source());
  // Nuevo estado: refresco en segundo plano (no bloquea tabla)
  const [refreshing, setRefreshing] = useState<boolean>(false);
  
  // Estado de listado unificado: page, limit, search, fields
  const [pageState, setPageState] = useState<number>(1);
  const [limitState, setLimitState] = useState<number>(10);
  const [searchState, setSearchState] = useState<string | undefined>(undefined);
  const [fieldsState, setFieldsState] = useState<string | undefined>(undefined);
  
  // Sincronización con URL (?page, ?limit, ?search, ?fields)
  const [searchParams, setSearchParams] = useSearchParams();
  
  // Meta de paginación unificada
  const [total, setTotal] = useState<number>(0);
  const [totalPages, setTotalPages] = useState<number>(0);
  const [hasNextPage, setHasNextPage] = useState<boolean>(false);
  const [hasPreviousPage, setHasPreviousPage] = useState<boolean>(false);
  
  const { getCache, setCache, invalidateByEndpoint } = useCache();
  const { generateKey } = useCacheKey();
  
  // Helper para construir mensajes de error más útiles
  const extractErrorMessage = (err: any, fallback: string): string => {
    // Cancelación controlada por axios
    if (axios.isCancel(err)) {
      return 'Operación cancelada';
    }
  
    // Errores de red (certificado, CORS, servidor caído)
    if (err?.code === 'ERR_NETWORK') {
      return 'No se pudo conectar con el servidor. Verifica el certificado HTTPS y que la API esté disponible.';
    }
  
    // AxiosError con respuesta del servidor
    if (axios.isAxiosError(err)) {
      const status = err.response?.status;
      const data = err.response?.data as any;
      const serverMsg = (data?.message || data?.error || (Array.isArray(data?.errors) ? data.errors.map((e: any) => e.message || e).join(', ') : data?.errors)) as string | undefined;
  
      if (status === 401) return serverMsg || 'No autorizado. Inicia sesión para continuar.';
      if (status === 403) return serverMsg || 'Acceso denegado. Requiere permisos de Administrador.';
      if (status === 404) return serverMsg || 'Recurso no encontrado.';
      if (status === 422) return serverMsg || 'Datos inválidos. Revisa los Potreros e intenta nuevamente.';
      if (status === 429) return serverMsg || 'Demasiadas solicitudes. Intenta nuevamente más tarde.';
      if (status && status >= 500) {
        // Mensaje amistoso para errores del servidor
        return serverMsg || 'Error del servidor. Intenta nuevamente más tarde o contacta al administrador.';
      }
  
      // Fallback genérico de Axios
      return serverMsg || err.message || fallback;
    }
  
    // Fallback genérico
    return (err instanceof Error ? err.message : undefined) || fallback;
  };
  
  // Leer cambios de query params y sincronizar al estado
  useEffect(() => {
    try {
      const qp = Number(searchParams.get('page') || '') || 1;
      const ql = Number(searchParams.get('limit') || '') || 10;
      const qs = searchParams.get('search') || undefined;
      const qf = searchParams.get('fields') || undefined;
  
      // Solo actualizar si realmente cambian, para evitar bucles
      setPageState(prev => (prev !== qp ? qp : prev));
      setLimitState(prev => (prev !== ql ? ql : prev));
      setSearchState(prev => (prev !== qs ? qs : prev));
      setFieldsState(prev => (prev !== qf ? qf : prev));
    } catch (e) {
      // Ignorar errores de parseo/lectura de query params en entornos de desarrollo
      if (process.env.NODE_ENV !== 'production') {
         
        console.debug('[useGenericCRUD] searchParams parse error', e);
      }
    }
  }, [searchParams]);
  
  // Setters que también actualizan la URL
  const setPage = useCallback((p: number) => {
    setPageState(p);
    const sp = new URLSearchParams(searchParams);
    sp.set('page', String(p));
    setSearchParams(sp, { replace: true });
  }, [searchParams, setSearchParams]);
  
  const setLimit = useCallback((l: number) => {
    setLimitState(l);
    const sp = new URLSearchParams(searchParams);
    sp.set('limit', String(l));
    sp.set('page', '1');
    setSearchParams(sp, { replace: true });
  }, [searchParams, setSearchParams]);
  
  const setSearch = useCallback((s: string) => {
    setSearchState(s || undefined);
    const sp = new URLSearchParams(searchParams);
    if (s) sp.set('search', s); else sp.delete('search');
    sp.set('page', '1');
    setSearchParams(sp, { replace: true });
  }, [searchParams, setSearchParams]);
  
  const setFields = useCallback((f: string) => {
    setFieldsState(f || undefined);
    const sp = new URLSearchParams(searchParams);
    if (f) sp.set('fields', f); else sp.delete('fields');
    setSearchParams(sp, { replace: true });
  }, [searchParams, setSearchParams]);
  
  // Obtener todos los elementos (paginated) con caché
  const fetchItems = useCallback(async (forceRefresh: boolean = false) => {
    const cacheKey = generateKey(entityName, { page: pageState, limit: limitState, search: searchState, fields: fieldsState });
    const hadDataAtStart = Array.isArray(items) && items.length > 0;
    
    // Intentar obtener del caché primero
     if (enableCache && !forceRefresh) {
       const cachedData = getCache<{ items: T[]; meta: any }>(cacheKey);
       if (cachedData && Array.isArray(cachedData.items)) {
         setItems(cachedData.items);
         setTotal(cachedData.meta?.total ?? 0);
         setTotalPages(cachedData.meta?.totalPages ?? 0);
         setHasNextPage(cachedData.meta?.hasNextPage ?? false);
         setHasPreviousPage(cachedData.meta?.hasPreviousPage ?? false);
         setError(null);
         // Log cache hit para monitoreo
         service.logCacheHit();
         return cachedData.items;
       }
     }
    
    // Loading inicial sólo si no hay datos; si ya hay, usar "refreshing" para evitar parpadeo
    if (!hadDataAtStart) {
      setLoading(true);
    } else {
      setRefreshing(true);
    }
    setError(null);
    // Cancelar cualquier solicitud de lista en curso y crear un nuevo token
    if (listCancelTokenSourceRef.current) {
      try { listCancelTokenSourceRef.current.cancel('Nueva carga de lista, se cancela la anterior'); } catch { /* noop */ }
    }
    listCancelTokenSourceRef.current = axios.CancelToken.source();
    try {
      const resp = await service.getPaginated({ page: pageState, limit: limitState, search: searchState, fields: fieldsState, cancelToken: listCancelTokenSourceRef.current?.token });
      const arrayData = Array.isArray((resp as any).data) ? (resp as any).data : [];
      setItems(arrayData);
      setTotal((resp as any).total || 0);
      setTotalPages((resp as any).totalPages || 0);
      // Usar has_next/has_prev de la respuesta si están disponibles, sino calcular
      setHasNextPage((resp as any).has_next !== undefined ? (resp as any).has_next : ((resp as any).page < ((resp as any).totalPages || 0)));
      setHasPreviousPage((resp as any).has_prev !== undefined ? (resp as any).has_prev : ((resp as any).page > 1));

      // Guardar en caché
      if (enableCache) {
        setCache(
          cacheKey,
          {
            items: arrayData,
            meta: {
              total: (resp as any).total,
              totalPages: (resp as any).totalPages,
              hasNextPage: (resp as any).has_next ?? ((resp as any).page < ((resp as any).totalPages || 0)),
              hasPreviousPage: (resp as any).has_prev ?? ((resp as any).page > 1),
            },
          },
          cacheTTL
        );
      }
      
      return arrayData;
    } catch (err) {
      if (!axios.isCancel(err)) {
        setError(extractErrorMessage(err, 'Error al cargar los datos'));
      }
      // Evitar vaciar la tabla si ya había datos (refetch suave)
      if (!hadDataAtStart) {
        setItems([]);
      }
      if (!axios.isCancel(err)) throw err;
      return Array.isArray(items) ? items : [];
    } finally {
      if (!hadDataAtStart) {
        setLoading(false);
      }
      setRefreshing(false);
    }
  }, [enableCache, cacheTTL, entityName, pageState, limitState, searchState, fieldsState, generateKey, getCache, setCache, service, items]);

  // Obtener un elemento por ID con Potreros opcionales
  const fetchItemById = useCallback(async (id: number, params?: FetchByIdParams, forceRefresh: boolean = false): Promise<T | null> => {
    const cacheKey = generateKey(entityName, { id, ...(params?.fields ? { fields: params.fields } : {}) });
    
    // Intentar obtener del caché primero
     if (enableCache && !forceRefresh) {
       const cachedData = getCache<T>(cacheKey);
       if (cachedData) {
         // Log cache hit para monitoreo
         service.logCacheHit(`${id}`);
         return cachedData;
       }
     }
    
    setLoading(true);
    setError(null);
    // Cancelar cualquier solicitud de item en curso y crear un nuevo token
    if (itemCancelTokenSourceRef.current) {
      try { itemCancelTokenSourceRef.current.cancel('Nueva carga de elemento, se cancela la anterior'); } catch { /* noop */ }
    }
    itemCancelTokenSourceRef.current = axios.CancelToken.source();
    try {
      const data = await service.getById(id, { ...(params || {}), cancelToken: itemCancelTokenSourceRef.current?.token });
      
      // Guardar en caché
      if (enableCache) {
        setCache(cacheKey, data, cacheTTL);
      }
      
      return data;
    } catch (err) {
      if (!axios.isCancel(err)) {
        setError(extractErrorMessage(err, 'Error al cargar el elemento'));
      }
      return null;
    } finally {
      setLoading(false);
    }
  }, [service, entityName, enableCache, getCache, setCache, generateKey, cacheTTL]);

  // Crear un nuevo elemento e invalidar caché
  const addItem = useCallback(async (itemData: Partial<T>): Promise<T | null> => {
    setLoading(true);
    setError(null);
    try {
      const newItem = await service.create(itemData);
      
      // Actualizar estado local (en primera página visiblemente)
      setItems(prev => [...prev, newItem]);
      
      // Invalidar caché del endpoint y limpiar caché interno del servicio
      if (enableCache) {
        const endpoint = (service as any)?.endpoint || entityName;
        invalidateByEndpoint(endpoint);
        if (typeof (service as any).clearCache === 'function') {
          (service as any).clearCache();
        }
      }
      
      return newItem;
    } catch (err) {
      setError(extractErrorMessage(err, 'Error al crear el elemento'));
      return null;
    } finally {
      setLoading(false);
    }
  }, [service, entityName, enableCache, invalidateByEndpoint]);

  // Actualizar un elemento existente e invalidar caché
  const updateItem = useCallback(async (id: number, itemData: Partial<T>): Promise<T | null> => {
    setLoading(true);
    setError(null);
    try {
      const updatedItem = await service.update(id, itemData);
      
      // Actualizar estado local
      setItems(prev => prev.map(item => 
        item.id === id ? { ...item, ...updatedItem } : item
      ));
      
      // Invalidar caché del endpoint y limpiar caché interno del servicio
      if (enableCache) {
        const endpoint = (service as any)?.endpoint || entityName;
        invalidateByEndpoint(endpoint);
        if (typeof (service as any).clearCache === 'function') {
          (service as any).clearCache();
        }
      }
      
      return updatedItem;
    } catch (err) {
      setError(extractErrorMessage(err, 'Error al actualizar el elemento'));
      return null;
    } finally {
      setLoading(false);
    }
  }, [service, entityName, enableCache, invalidateByEndpoint]);

  // Eliminar un elemento e invalidar caché
  const deleteItem = useCallback(async (id: number): Promise<boolean> => {
    setLoading(true);
    setError(null);
    try {
      await service.delete(id);
      
      // Actualizar estado local
      setItems(prev => prev.filter(item => item.id !== id));
      
      // Invalidar caché del endpoint y limpiar caché interno del servicio
      if (enableCache) {
        const endpoint = (service as any)?.endpoint || entityName;
        invalidateByEndpoint(endpoint);
        if (typeof (service as any).clearCache === 'function') {
          (service as any).clearCache();
        }
      }
      
      return true;
    } catch (err) {
      setError(extractErrorMessage(err, 'Error al eliminar el elemento'));
      return false;
    } finally {
      setLoading(false);
    }
  }, [service, entityName, enableCache, invalidateByEndpoint]);

  // Recargar datos forzando refresh
  const refreshItems = useCallback(() => {
    fetchItems(true);
  }, [fetchItems]);

  // Limpiar errores
  const clearError = useCallback(() => {
    setError(null);
  }, []);

  // Debounce para evitar llamadas excesivas durante cambios rápidos de parámetros
  const debouncedFetchRef = useRef<number | null>(null);
  const lastFetchParamsRef = useRef<string>('');

  // Efecto UNIFICADO: evita múltiples llamadas redundantes con debouncing
  useEffect(() => {
    // Limpiar timeout anterior
    if (debouncedFetchRef.current) {
      clearTimeout(debouncedFetchRef.current);
    }

    // Crear hash de parámetros para detectar cambios reales
    const currentParams = JSON.stringify({ pageState, limitState, searchState, fieldsState });
    const paramsChanged = lastFetchParamsRef.current !== currentParams;

    if (reload) {
      fetchItems(true);
      setReload(false);
      lastFetchParamsRef.current = currentParams;
    } else if (autoRefresh && paramsChanged) {
      // Debounce de 300ms para evitar llamadas excesivas (aumentado de 150ms)
      debouncedFetchRef.current = window.setTimeout(() => {
        fetchItems();
        lastFetchParamsRef.current = currentParams;
      }, 300);
    }

    return () => {
      // Limpiar debounce timeout
      if (debouncedFetchRef.current) {
        clearTimeout(debouncedFetchRef.current);
        debouncedFetchRef.current = null;
      }
      // Cancelar solicitudes pendientes al desmontar
      if (listCancelTokenSourceRef.current) {
        try { listCancelTokenSourceRef.current.cancel('Componente desmontado: lista'); } catch { /* noop */ }
        listCancelTokenSourceRef.current = null;
      }
      if (itemCancelTokenSourceRef.current) {
        try { itemCancelTokenSourceRef.current.cancel('Componente desmontado: item'); } catch { /* noop */ }
        itemCancelTokenSourceRef.current = null;
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pageState, limitState, searchState, fieldsState, reload]);

  return {
    items,
    loading,
    error,
    page: pageState, setPage,
    limit: limitState, setLimit,
    search: searchState, setSearch,
    fields: fieldsState, setFields,
    total, totalPages, hasNextPage, hasPreviousPage,
    fetchItems,
    refreshItems,
    clearError,
    addItem,
    updateItem,
    deleteItem,
    fetchItemById,
    // Compat names
    data: items,
    setData: setItems,
    // Nuevo estado de refresco
    refreshing,
  };
}

export function createCRUDHook<T extends { id?: number }>(
  service: BaseService<T>, 
  entityName: string,
  options?: UseGenericCRUDOptions
): SpecificCRUDHook<T> {
  return function useSpecificCRUD(): UseGenericCRUDResult<T> {
    return useGenericCRUD<T>(service, entityName, options);
  };
}

