/**
 * Hook useMCPResilient
 * 
 * Hook React para integrar MCP Resilient Client de forma sencilla
 * en componentes del dashboard.
 * 
 * @example
 * ```tsx
 * const HealthStatusWidget = () => {
 *   const { execute, isAvailable, status, isLoading } = useMCPResilient({
 *     mcpName: 'devbrain-universal',
 *     toolName: 'dashboard_status',
 *     fallbackFn: async () => {
 *       const res = await fetch('/api/v1/health');
 *       return await res.json();
 *     }
 *   });
 * 
 *   useEffect(() => {
 *     execute({ verbose: true });
 *   }, []);
 * 
 *   if (isLoading) return <Spinner />;
 *   if (!isAvailable) return <Badge>Usando Fallback</Badge>;
 *   return <StatusDisplay data={data} />;
 * };
 * ```
 */

import { useState, useCallback, useEffect, useRef } from 'react';
import { mcpResilientClient, type MCPResult } from '@/shared/api/mcpResilientClient';

interface UseMCPResilientOptions<T, P = Record<string, any>> {
  /** Nombre del servidor MCP */
  mcpName: string;
  
  /** Nombre de la herramienta MCP */
  toolName: string;
  
  /** Función fallback cuando MCP falla */
  fallbackFn: (params?: P) => Promise<T>;
  
  /** Parámetros iniciales (opcional) */
  initialParams?: P;
  
  /** Si ejecutar automáticamente al montar */
  autoExecute?: boolean;
  
  /** Timeout para la llamada */
  timeout?: number;
}

interface UseMCPResilientReturn<T, P = Record<string, any>> {
  /** Datos obtenidos (de MCP o fallback) */
  data: T | null;
  
  /** Si está cargando */
  isLoading: boolean;
  
  /** Error si ambos MCP y fallback fallaron */
  error: string | null;
  
  /** Fuente de los datos: 'mcp' | 'fallback' | null */
  source: 'mcp' | 'fallback' | null;
  
  /** Si el MCP está disponible */
  isAvailable: boolean;
  
  /** Si está usando fallback actualmente */
  isFallback: boolean;
  
  /** Estado completo del MCP */
  status: ReturnType<typeof mcpResilientClient.getStatus>;
  
  /** Ejecutar la llamada con parámetros opcionales */
  execute: (params?: P) => Promise<MCPResult<T>>;
  
  /** Reintentar la última llamada */
  retry: () => Promise<MCPResult<T>>;
  
  /** Intentar recuperar el MCP del cooldown */
  attemptRecovery: () => Promise<boolean>;
  
  /** Tiempo de ejecución de la última llamada (ms) */
  lastDuration: number | null;
}

export function useMCPResilient<T, P extends Record<string, any> = Record<string, any>>(
  options: UseMCPResilientOptions<T, P>
): UseMCPResilientReturn<T, P> {
  const {
    mcpName,
    toolName,
    fallbackFn,
    initialParams,
    autoExecute = false,
    timeout = 5000
  } = options;

  const [data, setData] = useState<T | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [source, setSource] = useState<'mcp' | 'fallback' | null>(null);
  const [lastDuration, setLastDuration] = useState<number | null>(null);
  const [lastParams, setLastParams] = useState<P | undefined>(initialParams);

  // Usar ref para mantener referencia actualizada de lastParams
  const lastParamsRef = useRef(lastParams);
  lastParamsRef.current = lastParams;

  const status = mcpResilientClient.getStatus(mcpName);
  const isAvailable = mcpResilientClient.isAvailable(mcpName);
  const isFallback = status?.fallbackActive ?? false;

  const execute = useCallback(async (params?: P): Promise<MCPResult<T>> => {
    setIsLoading(true);
    setError(null);
    
    // Guardar parámetros para retry
    if (params) {
      setLastParams(params);
    }

    try {
      const result = await mcpResilientClient.executeWithFallback<T>({
        mcpName,
        toolName,
        params: params || lastParamsRef.current,
        fallbackFn,
        timeout
      });

      setData(result.data);
      setSource(result.source);
      setLastDuration(result.duration);
      
      return result;
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : String(err);
      setError(errorMsg);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, [mcpName, toolName, fallbackFn, timeout]);

  const retry = useCallback(() => {
    // Resetear estado del MCP para permitir reintento
    mcpResilientClient.resetStatus(mcpName);
    return execute(lastParamsRef.current);
  }, [execute, mcpName]);

  const attemptRecovery = useCallback(async () => {
    return await mcpResilientClient.attemptRecovery(mcpName);
  }, [mcpName]);

  // Auto-ejecutar al montar si está habilitado
  useEffect(() => {
    if (autoExecute && initialParams !== undefined) {
      execute(initialParams).catch(() => {
        // Error ya está en estado, no necesitamos hacer nada más
      });
    }
  }, [autoExecute, execute, initialParams]);

  return {
    data,
    isLoading,
    error,
    source,
    isAvailable,
    isFallback,
    status,
    execute,
    retry,
    attemptRecovery,
    lastDuration
  };
}

/**
 * Hook useMCPHealth - Monitorear salud de MCPs del sistema
 * 
 * @example
 * ```tsx
 * const SystemHealth = () => {
 *   const { status, allStatus } = useMCPHealth();
 *   
 *   return (
 *     <div>
 *       {Object.entries(allStatus).map(([name, s]) => (
 *         <Badge key={name} color={s.available ? 'green' : 'red'}>
 *           {name}: {s.available ? 'OK' : 'Fallback'}
 *         </Badge>
 *       ))}
 *     </div>
 *   );
 * };
 * ```
 */
export function useMCPHealth() {
  const [allStatus, setAllStatus] = useState(() => 
    mcpResilientClient.getAllStatus()
  );
  
  const [refreshKey, setRefreshKey] = useState(0);

  // Refrescar estado periódicamente
  useEffect(() => {
    const interval = setInterval(() => {
      setAllStatus(mcpResilientClient.getAllStatus());
    }, 5000);

    return () => clearInterval(interval);
  }, []);

  // Refrescar manualmente
  const refresh = useCallback(() => {
    setAllStatus(mcpResilientClient.getAllStatus());
    setRefreshKey(k => k + 1);
  }, []);

  const universalStatus = allStatus['devbrain-universal'];
  const skillTestStatus = allStatus['devbrain-skill-test-skill-v2'];
  
  const anyAvailable = Object.values(allStatus).some(s => s.available);
  const allInFallback = Object.values(allStatus).every(s => s.fallbackActive);

  return {
    allStatus,
    universalStatus,
    skillTestStatus,
    anyAvailable,
    allInFallback,
    refresh,
    refreshKey
  };
}

/**
 * Hook para verificación ligera de cambios usando endpoint /metadata
 * Permite verificar si hay cambios sin descargar datos completos
 */

import { useState, useCallback, useEffect } from 'react';
import { PWAApiClient, ResourceMetadata } from '@/shared/api/pwa-client';
import { getETag, setETag } from '@/shared/api/cache/etagStore';

interface MetadataState {
  metadata: ResourceMetadata | null;
  isLoading: boolean;
  error: string | null;
  hasChanges: boolean;
}

interface UseMetadataOptions {
  /**
   * Auto-verificar al montar el componente
   */
  autoCheck?: boolean;

  /**
   * Intervalo de verificación automática en milisegundos
   */
  checkInterval?: number;

  /**
   * Callback cuando se detectan cambios
   */
  onChangesDetected?: (metadata: ResourceMetadata) => void;

  /**
   * Callback cuando NO hay cambios
   */
  onNoChanges?: () => void;
}

/**
 * Hook para verificar cambios usando metadata endpoint
 *
 * @param resource - Nombre del recurso (ej: 'users', 'diseases')
 * @param options - Opciones de configuración
 *
 * @example
 * ```tsx
 * function UserList() {
 *   const { metadata, hasChanges, check } = useMetadata('users', {
 *     autoCheck: true,
 *     checkInterval: 30000, // Verificar cada 30 segundos
 *     onChangesDetected: (meta) => {
 *       console.log(`Hay ${meta.total_count} usuarios, última modificación: ${meta.last_modified}`);
 *       // Recargar datos completos
 *     },
 *   });
 *
 *   return (
 *     <div>
 *       {hasChanges && <Badge>Hay cambios disponibles</Badge>}
 *       <button onClick={check}>Verificar cambios</button>
 *     </div>
 *   );
 * }
 * ```
 */
export function useMetadata(
  resource: string,
  options: UseMetadataOptions = {}
) {
  const {
    autoCheck = false,
    checkInterval,
    onChangesDetected,
    onNoChanges,
  } = options;

  const [state, setState] = useState<MetadataState>({
    metadata: null,
    isLoading: false,
    error: null,
    hasChanges: false,
  });

  const [client] = useState(() => new PWAApiClient(resource));

  /**
   * Verifica si hay cambios comparando ETags
   */
  const check = useCallback(async () => {
    setState(prev => ({ ...prev, isLoading: true, error: null }));

    try {
      // Obtener metadata del servidor
      const metadata = await client.getMetadata();

      if (!metadata) {
        setState(prev => ({
          ...prev,
          isLoading: false,
          error: 'Metadata no disponible',
          hasChanges: false,
        }));
        return false;
      }

      // Obtener ETag almacenado
      const storedETag = await getETag(resource);

      // Comparar ETags
      const hasChanges = !storedETag || storedETag !== metadata.etag;

      setState(prev => ({
        ...prev,
        metadata,
        isLoading: false,
        hasChanges,
        error: null,
      }));

      // Actualizar ETag almacenado
      if (metadata.etag) {
        await setETag(resource, metadata.etag);
      }

      // Callbacks
      if (hasChanges && onChangesDetected) {
        onChangesDetected(metadata);
      } else if (!hasChanges && onNoChanges) {
        onNoChanges();
      }

      return hasChanges;
    } catch (error: any) {
      const errorMsg = error?.message || 'Error al verificar metadata';

      setState(prev => ({
        ...prev,
        isLoading: false,
        error: errorMsg,
        hasChanges: false,
      }));

      return false;
    }
  }, [client, resource, onChangesDetected, onNoChanges]);

  /**
   * Resetea el estado de metadata
   */
  const reset = useCallback(() => {
    setState({
      metadata: null,
      isLoading: false,
      error: null,
      hasChanges: false,
    });
  }, []);

  // Auto-check al montar
  useEffect(() => {
    if (autoCheck) {
      check();
    }
  }, [autoCheck, check]); // Solo al montar

  // Intervalo de verificación
  useEffect(() => {
    if (checkInterval && checkInterval > 0) {
      const intervalId = setInterval(() => {
        check();
      }, checkInterval);

      return () => clearInterval(intervalId);
    }
  }, [checkInterval, check]);

  return {
    /**
     * Verifica si hay cambios
     */
    check,

    /**
     * Resetea el estado
     */
    reset,

    /**
     * Metadata del recurso
     */
    metadata: state.metadata,

    /**
     * True si está cargando
     */
    isLoading: state.isLoading,

    /**
     * Error de verificación (si hubo)
     */
    error: state.error,

    /**
     * True si hay cambios detectados
     */
    hasChanges: state.hasChanges,

    /**
     * Total de registros según metadata
     */
    totalCount: state.metadata?.total_count ?? 0,

    /**
     * Timestamp de última modificación
     */
    lastModified: state.metadata?.last_modified ?? null,

    /**
     * ETag actual
     */
    etag: state.metadata?.etag ?? null,

    /**
     * Cliente PWA subyacente
     */
    client,
  };
}

/**
 * Hook para verificar cambios en múltiples recursos
 *
 * @example
 * ```tsx
 * function Dashboard() {
 *   const { checkAll, results, isChecking } = useMultiResourceMetadata([
 *     'users',
 *     'diseases',
 *     'breeds',
 *   ]);
 *
 *   useEffect(() => {
 *     checkAll();
 *   }, []);
 *
 *   return (
 *     <div>
 *       {Object.entries(results).map(([resource, result]) => (
 *         <div key={resource}>
 *           {resource}: {result.hasChanges ? 'Hay cambios' : 'Sin cambios'}
 *         </div>
 *       ))}
 *     </div>
 *   );
 * }
 * ```
 */
export function useMultiResourceMetadata(resources: string[]) {
  const [isChecking, setIsChecking] = useState(false);
  const [results, setResults] = useState<Record<string, {
    hasChanges: boolean;
    metadata?: ResourceMetadata;
    error?: string;
  }>>({});

  const checkAll = useCallback(async () => {
    setIsChecking(true);

    const checkResults: typeof results = {};

    await Promise.all(
      resources.map(async (resource) => {
        const client = new PWAApiClient(resource);

        try {
          const hasChanges = await client.hasChanges();
          const metadata = await client.getMetadata();

          checkResults[resource] = {
            hasChanges,
            metadata: metadata || undefined,
          };
        } catch (error: any) {
          checkResults[resource] = {
            hasChanges: false,
            error: error?.message || 'Error desconocido',
          };
        }
      })
    );

    setResults(checkResults);
    setIsChecking(false);

    return checkResults;
  }, [resources]);

  return {
    checkAll,
    isChecking,
    results,
    /**
     * True si algún recurso tiene cambios
     */
    hasAnyChanges: Object.values(results).some(r => r.hasChanges),
    /**
     * Recursos que tienen cambios
     */
    changedResources: Object.entries(results)
      .filter(([_, r]) => r.hasChanges)
      .map(([resource, _]) => resource),
  };
}

/**
 * Hook combinado que verifica metadata y sincroniza si hay cambios
 *
 * @example
 * ```tsx
 * function SmartUserList() {
 *   const { data, sync, hasChanges, isLoading } = useSmartSync('users', {
 *     checkInterval: 30000,
 *     autoSyncOnChanges: true,
 *   });
 *
 *   return (
 *     <div>
 *       {hasChanges && <Badge>Sincronizando cambios...</Badge>}
 *       <UserTable data={data} />
 *     </div>
 *   );
 * }
 * ```
 */
export function useSmartSync<T = any>(
  resource: string,
  options: {
    checkInterval?: number;
    autoSyncOnChanges?: boolean;
    onSyncComplete?: (count: number) => void;
  } = {}
) {
  const { checkInterval, autoSyncOnChanges = false, onSyncComplete } = options;

  const [data, setData] = useState<T[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  const { check, hasChanges, metadata } = useMetadata(resource, {
    autoCheck: true,
    checkInterval,
  });

  const [client] = useState(() => new PWAApiClient<T>(resource));

  const sync = useCallback(async () => {
    setIsLoading(true);

    try {
      const { data: syncedData } = await client.syncSince();
      setData(syncedData);

      if (onSyncComplete) {
        onSyncComplete(syncedData.length);
      }

      // Re-verificar metadata
      await check();
    } catch (error) {
      console.error(`Error sincronizando ${resource}:`, error);
    } finally {
      setIsLoading(false);
    }
  }, [client, resource, check, onSyncComplete]);

  // Auto-sync cuando se detectan cambios
  useEffect(() => {
    if (autoSyncOnChanges && hasChanges) {
      sync();
    }
  }, [autoSyncOnChanges, hasChanges, sync]);

  return {
    data,
    sync,
    check,
    hasChanges,
    isLoading,
    metadata,
    totalCount: metadata?.total_count ?? 0,
    lastModified: metadata?.last_modified ?? null,
  };
}

import { useState, useEffect, useCallback } from 'react';
import { offlineQueue } from '@/shared/api/offline/offlineQueue';

export interface SyncStatus {
  pending: number;
  failed: number;
  syncing: boolean;
}

export interface OfflineSyncResult {
  pendingCount: number;
  isSyncing: boolean;
  isOnline: boolean;
  syncStatus: SyncStatus;
  syncNow: () => Promise<void>;
}

export function useOfflineSync(): OfflineSyncResult {
  const [pendingCount, setPendingCount] = useState(0);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isOnline, setIsOnline] = useState(
    typeof navigator !== 'undefined' ? navigator.onLine : true
  );
  const [syncStatus, setSyncStatus] = useState<SyncStatus>({
    pending: 0,
    failed: 0,
    syncing: false,
  });

  const refresh = useCallback(async () => {
    const [count, status] = await Promise.all([
      offlineQueue.getPendingCount(),
      offlineQueue.getStatusCounts(),
    ]);
    setPendingCount(count);
    setIsSyncing(status.syncing);
    setSyncStatus(status);
  }, []);

  const syncNow = useCallback(async () => {
    setIsSyncing(true);
    try {
      await offlineQueue.syncQueue();
    } finally {
      await refresh();
      setIsSyncing(false);
    }
  }, [refresh]);

  useEffect(() => {
    refresh();

    const handleOnline = () => {
      setIsOnline(true);
      refresh();
    };
    const handleOffline = () => setIsOnline(false);
    const handleSynced = () => refresh();

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    window.addEventListener('offline-queue-synced', handleSynced);

    const interval = setInterval(refresh, 3000);
    const unsub = offlineQueue.onSyncResult(() => refresh());

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      window.removeEventListener('offline-queue-synced', handleSynced);
      clearInterval(interval);
      unsub();
    };
  }, [refresh]);

  return { pendingCount, isSyncing, isOnline, syncStatus, syncNow };
}

/**
 * Hook optimizado que aprovecha las mejoras del backend:
 * - Endpoint /metadata para verificación rápida (5ms vs 200ms)
 * - Sincronización incremental con ?since= (50x más rápido)
 * - Cache invalidation automática del backend
 * - 100% precisión de datos
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { createPWAClient } from '@/shared/api/pwa-client';
import { useMetadata } from './useMetadata';
import { usePWASync } from './usePWASync';

interface UseOptimizedDataOptions {
  /**
   * Nombre del recurso (ej: 'users', 'animals')
   */
  resource: string;

  /**
   * Intervalo de verificación con /metadata (ms)
   * Default: 30000 (30 segundos)
   */
  checkInterval?: number;

  /**
   * Auto-sincronizar cuando se detectan cambios
   * Default: true
   */
  autoSync?: boolean;

  /**
   * Callback cuando hay datos nuevos disponibles
   */
  onDataUpdated?: (data: any[]) => void;

  /**
   * Habilitar modo agresivo (polling más frecuente)
   * Útil para datos críticos que cambian frecuentemente
   */
  aggressive?: boolean;
}

interface OptimizedDataState<T = any> {
  /**
   * Datos actuales
   */
  data: T[];

  /**
   * True si está cargando datos completos
   */
  isLoading: boolean;

  /**
   * True si está verificando metadata
   */
  isChecking: boolean;

  /**
   * True si está sincronizando cambios
   */
  isSyncing: boolean;

  /**
   * True si hay cambios disponibles pero no sincronizados
   */
  hasChanges: boolean;

  /**
   * Error si hubo alguno
   */
  error: string | null;

  /**
   * Timestamp de última sincronización
   */
  lastSync: string | null;

  /**
   * Número de cambios en última sync
   */
  changesCount: number;

  /**
   * Metadata del recurso
   */
  metadata: {
    total: number;
    lastModified: string | null;
  } | null;

  /**
   * Forzar sincronización manual
   */
  sync: () => Promise<void>;

  /**
   * Verificar cambios manualmente
   */
  check: () => Promise<boolean>;

  /**
   * Recargar datos completos (bypass caché)
   */
  reload: () => Promise<void>;
}

/**
 * Hook optimizado que combina metadata checking + sync incremental
 *
 * @example
 * ```tsx
 * function UserList() {
 *   const {
 *     data,
 *     isLoading,
 *     hasChanges,
 *     changesCount,
 *     lastSync,
 *     sync,
 *   } = useOptimizedData({
 *     resource: 'users',
 *     checkInterval: 30000,
 *     autoSync: true,
 *   });
 *
 *   return (
 *     <div>
 *       <DataSyncIndicator
 *         status={isLoading ? 'syncing' : 'success'}
 *         lastSync={lastSync}
 *         changesCount={changesCount}
 *         onSync={sync}
 *       />
 *       <UserTable data={data} />
 *     </div>
 *   );
 * }
 * ```
 */
export function useOptimizedData<T = any>(
  options: UseOptimizedDataOptions
): OptimizedDataState<T> {
  const {
    resource,
    checkInterval: customCheckInterval,
    autoSync = true,
    onDataUpdated,
    aggressive = false,
  } = options;

  // Intervalo adaptativo según modo
  const checkInterval = customCheckInterval || (aggressive ? 10000 : 30000);

  const [data, setData] = useState<T[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const initialLoadDone = useRef(false);

  // Hook de metadata (verificación ligera 5ms)
  const {
    check,
    hasChanges,
    metadata,
    isLoading: isChecking,
    totalCount,
    lastModified,
  } = useMetadata(resource, {
    autoCheck: true,
    checkInterval,
  });

  // Hook de sincronización incremental (50x más rápido)
  const {
    sync: syncIncremental,
    isSyncing,
    changesCount,
    lastSync,
  } = usePWASync<T>(resource, {
    autoSync: false, // Controlado manualmente
    onSyncComplete: (count) => {
      if (count > 0 && onDataUpdated) {
        // Recargar datos completos cuando hay cambios
        loadFullData();
      }
    },
  });

  /**
   * Carga inicial de datos completos
   */
  const loadFullData = useCallback(async () => {
    setIsLoading(true);
    setError(null);

    try {
      const client = createPWAClient<T>(resource);
      const response = await client.getPaginated({ limit: 1000 });
      setData(response.data);

      if (onDataUpdated) {
        onDataUpdated(response.data);
      }
    } catch (err: any) {
      setError(err?.message || 'Error al cargar datos');
      console.error(`[OptimizedData] Error cargando ${resource}:`, err);
    } finally {
      setIsLoading(false);
      initialLoadDone.current = true;
    }
  }, [resource, onDataUpdated]);

  /**
   * Sincronización inteligente:
   * 1. Si no hay carga inicial → carga completa
   * 2. Si hay cambios → sync incremental
   * 3. Si no hay cambios → no hace nada
   */
  const sync = useCallback(async () => {
    // Primera carga siempre es completa
    if (!initialLoadDone.current) {
      await loadFullData();
      return;
    }

    // Si hay cambios, sincronizar incrementalmente
    if (hasChanges || aggressive) {
      setError(null);

      try {
        const newData = await syncIncremental();

        if (newData.length > 0) {
          // Merge inteligente por ID
          setData(prevData => {
            const dataMap = new Map(prevData.map((item: any) => [item.id, item]));
            newData.forEach((newItem: any) => {
              if (newItem._deleted) {
                dataMap.delete(newItem.id);
              } else {
                dataMap.set(newItem.id, newItem);
              }
            });
            const merged = Array.from(dataMap.values());
            
            // Avisar si hay callback
            if (onDataUpdated) {
              onDataUpdated(merged);
            }
            
            return merged;
          });
        }
      } catch (err: any) {
        setError(err?.message || 'Error al sincronizar');
        console.error(`[OptimizedData] Error sincronizando ${resource}:`, err);
      }
    }
  }, [hasChanges, aggressive, syncIncremental, loadFullData, resource]);

  /**
   * Recarga completa (bypass caché)
   */
  const reload = useCallback(async () => {
    initialLoadDone.current = false;
    await loadFullData();
  }, [loadFullData]);

  // Carga inicial
  useEffect(() => {
    if (!initialLoadDone.current) {
      loadFullData();
    }
  }, [loadFullData]);

  // Auto-sync cuando hay cambios
  useEffect(() => {
    if (autoSync && hasChanges && initialLoadDone.current) {
      sync();
    }
  }, [autoSync, hasChanges, sync]);

  return {
    data,
    isLoading,
    isChecking,
    isSyncing,
    hasChanges,
    error,
    lastSync,
    changesCount,
    metadata: metadata
      ? {
          total: totalCount,
          lastModified,
        }
      : null,
    sync,
    check,
    reload,
  };
}

/**
 * Hook simplificado para listas de solo lectura
 * Aprovecha caché del backend (100% precisión garantizada)
 */
export function useOptimizedList<T = any>(resource: string) {
  const {
    data,
    isLoading,
    hasChanges,
    metadata,
    sync,
  } = useOptimizedData<T>({
    resource,
    checkInterval: 60000, // 1 minuto (datos de solo lectura)
    autoSync: true,
  });

  return {
    data,
    isLoading,
    hasChanges,
    total: metadata?.total || 0,
    refresh: sync,
  };
}

/**
 * Hook para datos críticos que cambian frecuentemente
 * Polling agresivo cada 10 segundos
 */
export function useCriticalData<T = any>(resource: string) {
  return useOptimizedData<T>({
    resource,
    checkInterval: 10000, // 10 segundos
    autoSync: true,
    aggressive: true,
  });
}

/**
 * Hook para sincronización incremental PWA
 * Permite sincronizar recursos solo descargando cambios desde última sincronización
 */

import { useState, useCallback, useEffect } from 'react';
import { PWAApiClient } from '@/shared/api/pwa-client';
import { getLastSync, setLastSync } from '@/shared/api/cache/etagStore';

interface SyncState {
  isSyncing: boolean;
  lastSync: string | null;
  error: string | null;
  changesCount: number;
}

interface UsePWASyncOptions {
  /**
   * Auto-sincronizar al montar el componente
   */
  autoSync?: boolean;

  /**
   * Intervalo de auto-sincronización en milisegundos (default: 5 minutos)
   */
  syncInterval?: number;

  /**
   * Callback cuando la sincronización completa
   */
  onSyncComplete?: (count: number) => void;

  /**
   * Callback cuando la sincronización falla
   */
  onSyncError?: (error: Error) => void;
}

/**
 * Hook para sincronización incremental de un recurso
 *
 * @param resource - Nombre del recurso (ej: 'users', 'diseases', etc.)
 * @param options - Opciones de configuración
 *
 * @example
 * ```tsx
 * function MyComponent() {
 *   const { sync, isSyncing, changesCount, lastSync } = usePWASync('users', {
 *     autoSync: true,
 *     syncInterval: 5 * 60 * 1000, // 5 minutos
 *     onSyncComplete: (count) => console.log(`${count} cambios descargados`),
 *   });
 *
 *   return (
 *     <div>
 *       <button onClick={sync} disabled={isSyncing}>
 *         Sincronizar
 *       </button>
 *       {lastSync && <p>Última sincronización: {new Date(lastSync).toLocaleString()}</p>}
 *     </div>
 *   );
 * }
 * ```
 */
export function usePWASync<T = any>(
  resource: string,
  options: UsePWASyncOptions = {}
) {
  const {
    autoSync = false,
    syncInterval,
    onSyncComplete,
    onSyncError,
  } = options;

  const [state, setState] = useState<SyncState>({
    isSyncing: false,
    lastSync: null,
    error: null,
    changesCount: 0,
  });

  const [client] = useState(() => new PWAApiClient<T>(resource));

  /**
   * Carga el timestamp de última sincronización
   */
  const loadLastSync = useCallback(async () => {
    const lastSyncTime = await getLastSync(resource);
    setState(prev => ({ ...prev, lastSync: lastSyncTime }));
  }, [resource]);

  /**
   * Sincroniza cambios desde última sincronización
   */
  const sync = useCallback(async (force: boolean = false) => {
    setState(prev => ({ ...prev, isSyncing: true, error: null }));

    try {
      // Si force, resetear timestamp
      const since = force ? new Date(0).toISOString() : state.lastSync || undefined;

      const { data, newSync } = await client.syncSince(since);

      setState(prev => ({
        ...prev,
        isSyncing: false,
        lastSync: newSync,
        changesCount: data.length,
        error: null,
      }));

      // Actualizar timestamp local
      await setLastSync(resource, newSync);

      // Callback de éxito
      if (onSyncComplete) {
        onSyncComplete(data.length);
      }

      return data;
    } catch (error: any) {
      const errorMsg = error?.message || 'Error desconocido en sincronización';

      setState(prev => ({
        ...prev,
        isSyncing: false,
        error: errorMsg,
      }));

      // Callback de error
      if (onSyncError) {
        onSyncError(error);
      }

      throw error;
    }
  }, [client, resource, state.lastSync, onSyncComplete, onSyncError]);

  /**
   * Sincronización completa (resetea timestamp)
   */
  const fullSync = useCallback(async () => {
    return sync(true);
  }, [sync]);

  /**
   * Limpia el estado de sincronización
   */
  const reset = useCallback(async () => {
    await setLastSync(resource, new Date(0).toISOString());
    setState({
      isSyncing: false,
      lastSync: null,
      error: null,
      changesCount: 0,
    });
  }, [resource]);

  // Cargar timestamp inicial
  useEffect(() => {
    loadLastSync();
  }, [loadLastSync]);

  // Auto-sync al montar
  useEffect(() => {
    if (autoSync) {
      sync();
    }
  }, [autoSync, sync]); // Solo ejecutar una vez al montar

  // Intervalo de auto-sync
  useEffect(() => {
    if (syncInterval && syncInterval > 0) {
      const intervalId = setInterval(() => {
        sync();
      }, syncInterval);

      return () => clearInterval(intervalId);
    }
  }, [syncInterval, sync]);

  return {
    /**
     * Sincroniza cambios incremental
     */
    sync,

    /**
     * Sincronización completa (descarga todo)
     */
    fullSync,

    /**
     * Resetea el estado de sincronización
     */
    reset,

    /**
     * True si está sincronizando
     */
    isSyncing: state.isSyncing,

    /**
     * Timestamp ISO de última sincronización
     */
    lastSync: state.lastSync,

    /**
     * Error de última sincronización (si hubo)
     */
    error: state.error,

    /**
     * Número de cambios en última sincronización
     */
    changesCount: state.changesCount,

    /**
     * Cliente PWA subyacente (para uso avanzado)
     */
    client,
  };
}

/**
 * Hook para sincronizar múltiples recursos en paralelo
 *
 * @example
 * ```tsx
 * function Dashboard() {
 *   const { syncAll, isSyncing, results } = useMultiResourceSync([
 *     'users',
 *     'diseases',
 *     'breeds',
 *   ]);
 *
 *   return (
 *     <button onClick={syncAll} disabled={isSyncing}>
 *       Sincronizar Todo
 *     </button>
 *   );
 * }
 * ```
 */
export function useMultiResourceSync(resources: string[]) {
  const [isSyncing, setIsSyncing] = useState(false);
  const [results, setResults] = useState<Record<string, { success: boolean; count: number; error?: string }>>({});

  const syncAll = useCallback(async () => {
    setIsSyncing(true);

    const syncResults: Record<string, { success: boolean; count: number; error?: string }> = {};

    await Promise.all(
      resources.map(async (resource) => {
        const client = new PWAApiClient(resource);

        try {
          const { data } = await client.syncSince();
          syncResults[resource] = {
            success: true,
            count: data.length,
          };
        } catch (error: any) {
          syncResults[resource] = {
            success: false,
            count: 0,
            error: error?.message || 'Error desconocido',
          };
        }
      })
    );

    setResults(syncResults);
    setIsSyncing(false);

    return syncResults;
  }, [resources]);

  return {
    syncAll,
    isSyncing,
    results,
  };
}

/**
 * Hooks de React para optimizaciones de performance
 */

import { useEffect, useRef, useCallback, useMemo, DependencyList } from 'react';
import { debounce, throttle, memoryCache, prefetchData, onScrollEnd } from '@/shared/utils/performance';

// ============================================================================
// useDebounce - Hook para valores debounced
// ============================================================================

export function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = React.useState<T>(value);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(handler);
    };
  }, [value, delay]);

  return debouncedValue;
}

// ============================================================================
// useDebouncedCallback - Hook para callbacks debounced
// ============================================================================

export function useDebouncedCallback<T extends (...args: any[]) => any>(
  callback: T,
  delay: number,
  deps: DependencyList = []
): T {
  const callbackRef = useRef(callback);
  const depsKey = useMemo(() => JSON.stringify(deps), [deps]);

  useEffect(() => {
    callbackRef.current = callback;
  }, [callback]);

  return useMemo(() => {
    void depsKey;
    return debounce((...args: Parameters<T>) => {
      return callbackRef.current(...args);
    }, delay) as T;
  }, [delay, depsKey]);
}

// ============================================================================
// useThrottle - Hook para valores throttled
// ============================================================================

export function useThrottle<T>(value: T, delay: number): T {
  const [throttledValue, setThrottledValue] = React.useState<T>(value);
  const lastExecuted = useRef<number>(Date.now());

  useEffect(() => {
    const now = Date.now();
    const timeSinceLastExecution = now - lastExecuted.current;

    if (timeSinceLastExecution >= delay) {
      lastExecuted.current = now;
      setThrottledValue(value);
    } else {
      const timer = setTimeout(() => {
        lastExecuted.current = Date.now();
        setThrottledValue(value);
      }, delay - timeSinceLastExecution);

      return () => clearTimeout(timer);
    }
  }, [value, delay]);

  return throttledValue;
}

// ============================================================================
// useThrottledCallback - Hook para callbacks throttled
// ============================================================================

export function useThrottledCallback<T extends (...args: any[]) => any>(
  callback: T,
  delay: number,
  deps: DependencyList = []
): T {
  const callbackRef = useRef(callback);
  const depsKey = useMemo(() => JSON.stringify(deps), [deps]);

  useEffect(() => {
    callbackRef.current = callback;
  }, [callback]);

  return useMemo(() => {
    void depsKey;
    return throttle((...args: Parameters<T>) => {
      return callbackRef.current(...args);
    }, delay) as T;
  }, [delay, depsKey]);
}

// ============================================================================
// useMemoryCache - Hook para usar el caché en memoria
// ============================================================================

export function useMemoryCache<T>(
  key: string,
  fetchFn: () => Promise<T> | T,
  ttl?: number
): {
  data: T | null;
  loading: boolean;
  error: Error | null;
  refetch: () => Promise<void>;
  invalidate: () => void;
} {
  const [data, setData] = React.useState<T | null>(() => memoryCache.get<T>(key));
  const [loading, setLoading] = React.useState<boolean>(!memoryCache.has(key));
  const [error, setError] = React.useState<Error | null>(null);
  const isMounted = useRef(true);

  const fetch = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const result = await fetchFn();

      if (isMounted.current) {
        setData(result);
        memoryCache.set(key, result, ttl);
      }
    } catch (err) {
      if (isMounted.current) {
        setError(err as Error);
      }
    } finally {
      if (isMounted.current) {
        setLoading(false);
      }
    }
  }, [key, fetchFn, ttl]);

  const invalidate = useCallback(() => {
    memoryCache.invalidate(key);
    setData(null);
  }, [key]);

  useEffect(() => {
    isMounted.current = true;

    // Si no hay datos en caché, hacer fetch
    if (!memoryCache.has(key)) {
      fetch();
    }

    return () => {
      isMounted.current = false;
    };
  }, [key, fetch]);

  return {
    data,
    loading,
    error,
    refetch: fetch,
    invalidate,
  };
}

// ============================================================================
// usePrefetch - Hook para prefetch de datos
// ============================================================================

export function usePrefetch(): {
  prefetch: (url: string, fetchFn: () => Promise<any>, priority?: 'high' | 'normal' | 'low') => void;
} {
  const prefetch = useCallback(
    (url: string, fetchFn: () => Promise<any>, priority: 'high' | 'normal' | 'low' = 'normal') => {
      prefetchData(url, fetchFn, { priority });
    },
    []
  );

  return { prefetch };
}

// ============================================================================
// useScrollEnd - Hook para detectar fin de scroll
// ============================================================================

export function useScrollEnd(callback: () => void, delay: number = 150): void {
  const callbackRef = useRef(callback);

  useEffect(() => {
    callbackRef.current = callback;
  }, [callback]);

  useEffect(() => {
    return onScrollEnd(() => callbackRef.current(), delay);
  }, [delay]);
}

// ============================================================================
// useIntersectionObserver - Hook para detectar elementos en viewport
// ============================================================================

export function useIntersectionObserver(
  elementRef: React.RefObject<Element>,
  options: IntersectionObserverInit = {}
): { isIntersecting: boolean; entry: IntersectionObserverEntry | null } {
  const [isIntersecting, setIsIntersecting] = React.useState(false);
  const [entry, setEntry] = React.useState<IntersectionObserverEntry | null>(null);

  useEffect(() => {
    const element = elementRef.current;
    if (!element) return;

    const observer = new IntersectionObserver(([entry]) => {
      setIsIntersecting(entry.isIntersecting);
      setEntry(entry);
    }, options);

    observer.observe(element);

    return () => {
      observer.disconnect();
    };
  }, [elementRef, options]);

  return { isIntersecting, entry };
}

// ============================================================================
// useIdleCallback - Hook para ejecutar callbacks en tiempo idle
// ============================================================================

export function useIdleCallback(
  callback: () => void,
  options?: IdleRequestOptions
): void {
  const callbackRef = useRef(callback);

  useEffect(() => {
    callbackRef.current = callback;
  }, [callback]);

  useEffect(() => {
    let idleCallbackId: number | null = null;

    if ('requestIdleCallback' in window) {
      idleCallbackId = window.requestIdleCallback(() => {
        callbackRef.current();
      }, options);
    } else {
      // Fallback para navegadores sin soporte
      idleCallbackId = setTimeout(() => {
        callbackRef.current();
      }, 1) as unknown as number;
    }

    return () => {
      if (idleCallbackId !== null) {
        if ('cancelIdleCallback' in window) {
          window.cancelIdleCallback(idleCallbackId);
        } else {
          clearTimeout(idleCallbackId);
        }
      }
    };
  }, [options]);
}

// ============================================================================
// useOptimisticUpdate - Hook para actualizaciones optimistas
// ============================================================================

export function useOptimisticUpdate<T>(
  initialData: T,
  updateFn: (data: T, update: Partial<T>) => T = (data, update) => ({ ...data, ...update })
): {
  data: T;
  optimisticUpdate: (update: Partial<T>) => void;
  commitUpdate: (finalData: T) => void;
  rollback: () => void;
} {
  const [data, setData] = React.useState<T>(initialData);
  const [savedData, setSavedData] = React.useState<T>(initialData);

  const optimisticUpdate = useCallback(
    (update: Partial<T>) => {
      setSavedData(data); // Guardar estado actual para posible rollback
      setData((prevData) => updateFn(prevData, update));
    },
    [data, updateFn]
  );

  const commitUpdate = useCallback((finalData: T) => {
    setData(finalData);
    setSavedData(finalData);
  }, []);

  const rollback = useCallback(() => {
    setData(savedData);
  }, [savedData]);

  return {
    data,
    optimisticUpdate,
    commitUpdate,
    rollback,
  };
}

// ============================================================================
// useLazyLoad - Hook para lazy loading de componentes pesados
// ============================================================================

export function useLazyLoad<T>(
  loader: () => Promise<T>,
  placeholder?: T
): { data: T | undefined; loading: boolean; error: Error | null } {
  const [data, setData] = React.useState<T | undefined>(placeholder);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState<Error | null>(null);
  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    setLoading(true);

    loader()
      .then((result) => {
        if (isMounted.current) {
          setData(result);
          setLoading(false);
        }
      })
      .catch((err) => {
        if (isMounted.current) {
          setError(err);
          setLoading(false);
        }
      });

    return () => {
      isMounted.current = false;
    };
  }, [loader]);

  return { data, loading, error };
}

// ============================================================================
// useMediaQuery - Hook para detectar media queries
// ============================================================================

export function useMediaQuery(query: string): boolean {
  const [matches, setMatches] = React.useState(() => {
    if (typeof window !== 'undefined') {
      return window.matchMedia(query).matches;
    }
    return false;
  });

  useEffect(() => {
    const mediaQuery = window.matchMedia(query);
    const handler = (event: MediaQueryListEvent) => setMatches(event.matches);

    // Modern browsers
    if (mediaQuery.addEventListener) {
      mediaQuery.addEventListener('change', handler);
      return () => mediaQuery.removeEventListener('change', handler);
    }
    // Legacy browsers
    else {
      mediaQuery.addListener(handler);
      return () => mediaQuery.removeListener(handler);
    }
  }, [query]);

  return matches;
}

// ============================================================================
// usePreferredMotion - Hook para detectar preferencia de movimiento
// ============================================================================

export function usePreferredMotion(): 'reduce' | 'no-preference' {
  const prefersReducedMotion = useMediaQuery('(prefers-reduced-motion: reduce)');
  return prefersReducedMotion ? 'reduce' : 'no-preference';
}

// ============================================================================
// useNetworkStatus - Hook para detectar estado de la red
// ============================================================================

export function useNetworkStatus(): {
  online: boolean;
  effectiveType: string | null;
  saveData: boolean;
} {
  const [online, setOnline] = React.useState(navigator.onLine);
  const [effectiveType, setEffectiveType] = React.useState<string | null>(
    (navigator as any).connection?.effectiveType || null
  );
  const [saveData, setSaveData] = React.useState(
    (navigator as any).connection?.saveData || false
  );

  useEffect(() => {
    const handleOnline = () => setOnline(true);
    const handleOffline = () => setOnline(false);

    const connection = (navigator as any).connection;
    const handleConnectionChange = () => {
      if (connection) {
        setEffectiveType(connection.effectiveType);
        setSaveData(connection.saveData);
      }
    };

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    if (connection) {
      connection.addEventListener('change', handleConnectionChange);
    }

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      if (connection) {
        connection.removeEventListener('change', handleConnectionChange);
      }
    };
  }, []);

  return { online, effectiveType, saveData };
}

