import { useCallback, useEffect, useRef, useState } from 'react';
import axios, { isCancel, CancelToken } from 'axios';
import type { BaseService } from '@/shared/api/base-service';
import { useCache, useCacheKey } from '@/app/providers/CacheContext';
import { UseResourceOptions, UseResourceResult } from './resource/types';
import { useResourceParams } from './resource/useResourceParams';
import { useResourceRealtime } from './resource/useResourceRealtime';
import { useResourceTracker } from './resource/useResourceTracker';
import { useResourceCrud } from './resource/useResourceCrud';
import { useResourceRefetch, refetchAllResources, __endpointBackoffUntil } from './resource/useResourceRefetch';

export { refetchAllResources };
export type { UseResourceOptions, UseResourceResult };

export function useResource<T extends { id?: number | string }, P extends Record<string, any> = Record<string, any>>(
  service: BaseService<T>,
  options: UseResourceOptions<P> = {}
): UseResourceResult<T, P> {
  const { autoFetch = true, initialParams, deps = [], map, cache = true, cacheTTL, cacheKeyPrefix } = options;
  const [data, setData] = useState<T[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [meta, setMeta] = useState<UseResourceResult<T, P>["meta"]>(null);
  const [refreshing, setRefreshing] = useState(false);

  const lastParams = useRef<P | undefined>(initialParams);
  const abortController = useRef(new AbortController());
  const skipCacheUntil = useRef<number>(0);
  const crudInProgress = useRef<boolean>(false);

  const { getCache, setCache, invalidateByEndpoint } = useCache();
  const { generateKey } = useCacheKey();
  const entityKeyRef = useRef<string>((service as any)?.endpoint || service.constructor?.name || 'resource');
  const prefix = cacheKeyPrefix || entityKeyRef.current;

  const {
    pageQP, limitQP, searchQP, fieldsQP,
    setPage, setLimit, setSearch, setFields,
    buildEffectiveParams
  } = useResourceParams(initialParams, lastParams);

  const tracker = useResourceTracker<T>();

  const safeExecute = useCallback(async <R,>(fn: (signal: AbortSignal) => Promise<R>): Promise<R | undefined> => {
    try {
      setLoading(true);
      setError(null);
      return await fn(abortController.current.signal);
    } catch (e: any) {
      if (isCancel(e) || (e instanceof Error && e.name === 'AbortError')) return undefined;
      setError(e?.message || 'Error inesperado');
      throw e;
    } finally {
      setLoading(false);
    }
  }, []);

  const safeExecuteMutation = useCallback(async <R,>(fn: () => Promise<R>): Promise<R | undefined> => {
    try {
      setLoading(true);
      return await fn();
    } catch (e: any) {
      if (isCancel(e) || (e instanceof Error && e.name === 'AbortError')) return undefined;
      throw e;
    } finally {
      setLoading(false);
    }
  }, []);

  const { refetch } = useResourceRefetch<T, P>(
    service, data, setData, setMeta, setRefreshing, safeExecute, buildEffectiveParams,
    prefix, generateKey, getCache, setCache, cacheTTL, cache, map, lastParams, abortController as any, skipCacheUntil, tracker
  );

  const { createItem, updateItem, deleteItem } = useResourceCrud<T>(
    service, data, setData, safeExecuteMutation, invalidateByEndpoint, prefix, crudInProgress, skipCacheUntil, refetch, tracker
  );

  useEffect(() => {
    if (autoFetch) {
      refetch(initialParams as P | undefined);
    }
    return () => {
      abortController.current.abort('Component Unmounted');
      abortController.current = new AbortController();
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoFetch, service, cache, pageQP, limitQP, searchQP, fieldsQP, ...deps]);

  useResourceRealtime(options, refetch, crudInProgress, skipCacheUntil, prefix);

  useEffect(() => {
    const handler = (evt: any) => {
      try {
        const detail = evt?.detail || {};
        const endpointPath: string = String(detail.endpoint || '');
        const parts = endpointPath.split('/').filter(Boolean);
        const slug = parts.length ? parts[parts.length - 1] : endpointPath;
        const waitSeconds = typeof detail.waitSeconds === 'number' && detail.waitSeconds > 0 ? detail.waitSeconds : undefined;
        const until = Date.now() + (waitSeconds ? waitSeconds * 1000 : 30000);
        __endpointBackoffUntil.set(slug, until);
      } catch { /* noop */ }
    };
    if (typeof window !== 'undefined') {
      window.addEventListener('rate-limit-exceeded', handler as any);
      return () => window.removeEventListener('rate-limit-exceeded', handler as any);
    }
    return () => {};
  }, []);

  return {
    data, loading, error, refetch,
    createItem, updateItem, deleteItem,
    setData, meta,
    setPage, setLimit, setSearch, setFields,
    refreshing
  };
}

