/*
 * CRUDPagination
 * 
 * Componente optimizado para la paginación de tablas.
 * Implementa navegación eficiente y accesible.
 */

import React, { memo, useCallback } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { cn } from '@/shared/ui/cn';
import { useT } from '@/shared/i18n';

interface CRUDPaginationProps {
  currentPage: number;
  totalPages: number;
  totalItems: number;
  onPageChange: (page: number) => void;
  loading?: boolean;
}

export const CRUDPagination = memo<CRUDPaginationProps>(({
  currentPage,
  totalPages,
  totalItems,
  onPageChange,
  loading = false,
}) => {
  const t = useT();
  
  // Manejar cambio de página
  const handlePageChange = useCallback((page: number) => {
    if (page >= 1 && page <= totalPages && page !== currentPage && !loading) {
      onPageChange(page);
    }
  }, [currentPage, totalPages, loading, onPageChange]);
  
  // Generar array de páginas a mostrar
  const getVisiblePages = useCallback(() => {
    const delta = 2; // Número de páginas a mostrar antes y después de la actual
    
    // Caso especial: menos de 7 páginas totales
    if (totalPages <= 7) {
      return Array.from({ length: totalPages }, (_, i) => i + 1);
    }
    
    // Caso normal: mostrar páginas alrededor de la actual
    const range = [];
    const rangeWithDots = [];
    let l;

    for (let i = 1; i <= totalPages; i++) {
      if (
        i === 1 || // Primera página
        i === totalPages || // Última página
        (i >= currentPage - delta && i <= currentPage + delta) // Páginas alrededor de la actual
      ) {
        range.push(i);
      }
    }

    // Agregar puntos suspensivos donde haya saltos
    range.forEach((i) => {
      if (l) {
        if (i - l === 2) {
          rangeWithDots.push(l + 1);
        } else if (i - l !== 1) {
          rangeWithDots.push('...');
        }
      }
      rangeWithDots.push(i);
      l = i;
    });

    return rangeWithDots;
  }, [currentPage, totalPages]);
  
  const visiblePages = getVisiblePages();
  
  return (
    <div className="sticky bottom-0 z-10 bg-card/95 border-t backdrop-blur-sm shadow-sm flex-shrink-0">
      <div className="px-2 py-1.5 sm:py-2">
        <div className="flex justify-between items-center text-[11px] sm:text-[12px] md:text-sm gap-2">
          {/* Información de paginación */}
          <div className="text-muted-foreground">
            <span className="hidden sm:inline">{t('common.page', 'Página')} </span>
            <span className="sm:hidden">Pág. </span>
            {currentPage} <span className="hidden sm:inline">{t('common.of', 'de')}</span><span className="sm:hidden">/</span> {Math.max(totalPages, 1)}
            <span className="ml-2 hidden sm:inline">
              ({totalItems} {totalItems === 1 ? 'registro' : 'registros'})
            </span>
          </div>
          
          {/* Controles de paginación */}
          <div className="flex items-center gap-1 sm:gap-2">
            {/* Botón anterior */}
            <Button
              variant="outline"
              size="sm"
              onClick={() => handlePageChange(currentPage - 1)}
              disabled={loading || currentPage <= 1}
              aria-label={t('common.previous', 'Anterior')}
              className="inline-flex items-center justify-center h-7 w-7 sm:h-9 sm:w-9 text-sm font-medium ring-offset-background transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50"
            >
              <ChevronLeft className="h-3.5 w-3.5 sm:h-4 sm:w-4" aria-hidden />
            </Button>
            
            {/* Números de página */}
            <div className="hidden sm:flex items-center gap-1">
              {visiblePages.map((page, index) => (
                <React.Fragment key={index}>
                  {page === '...' ? (
                    <span className="px-2 py-1 text-muted-foreground">...</span>
                  ) : (
                    <Button
                      variant={currentPage === page ? "default" : "outline"}
                      size="sm"
                      onClick={() => handlePageChange(page as number)}
                      disabled={loading}
                      className={cn(
                        "h-7 w-7 sm:h-9 sm:w-9 text-sm font-medium",
                        currentPage === page && "bg-primary text-primary-foreground"
                      )}
                    >
                      {page}
                    </Button>
                  )}
                </React.Fragment>
              ))}
            </div>
            
            {/* Paginación simplificada para móviles */}
            <div className="sm:hidden text-xs text-muted-foreground">
              {currentPage} / {totalPages}
            </div>
            
            {/* Botón siguiente */}
            <Button
              variant="outline"
              size="sm"
              onClick={() => handlePageChange(currentPage + 1)}
              disabled={loading || currentPage >= totalPages}
              aria-label={t('common.next', 'Siguiente')}
              className="inline-flex items-center justify-center h-7 w-7 sm:h-9 sm:w-9 text-sm font-medium ring-offset-background transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50"
            >
              <ChevronRight className="h-3.5 w-3.5 sm:h-4 sm:w-4" aria-hidden />
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
});

CRUDPagination.displayName = 'CRUDPagination';

export default CRUDPagination;

/*
 * CRUDTable
 * 
 * Componente optimizado para renderizar tablas con gran volumen de datos.
 * Implementa virtualización, memoización y animaciones simplificadas.
 */

import React, { memo, useMemo, useCallback } from 'react';
import { FixedSizeList as List } from 'react-window';
import { Eye, Edit, Trash2, Loader2 } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { cn } from '@/shared/ui/cn';
import { useT } from '@/shared/i18n';

// Interfaces
import { CRUDColumn, CRUDConfig } from '../AdminCRUDPage';

interface CRUDTableProps<T extends { id: number }> {
  items: T[];
  columns: CRUDColumn<T>[];
  config: CRUDConfig<T, any>;
  onOpenDetail?: (item: T) => void;
  onOpenEdit?: (item: T) => void;
  onOpenDelete?: (id: number) => void;
  enhancedHover?: boolean;
  refreshing?: boolean;
}

// Componente memoizado para cada fila
const TableRow = memo(<T extends { id: number }>({
  item,
  index,
  columns,
  config,
  onOpenDetail,
  onOpenEdit,
  onOpenDelete,
  enhancedHover,
  fkLabelMap,
  deletingItems,
}: {
  item: T;
  index: number;
  columns: CRUDColumn<T>[];
  config: CRUDConfig<T, any>;
  onOpenDetail?: (item: T) => void;
  onOpenEdit?: (item: T) => void;
  onOpenDelete?: (id: number) => void;
  enhancedHover?: boolean;
  fkLabelMap: Record<string, Map<string, string>>;
  deletingItems: Set<string>;
}) => {
  const t = useT();
  
  const isDeleting = deletingItems.has(String(item.id));
  
  const handleClick = useCallback(() => {
    if (onOpenDetail) {
      onOpenDetail(item);
    }
  }, [onOpenDetail, item]);
  
  const handleEdit = useCallback((e: React.MouseEvent) => {
    e.stopPropagation();
    if (onOpenEdit) {
      onOpenEdit(item);
    }
  }, [onOpenEdit, item]);
  
  const handleDelete = useCallback((e: React.MouseEvent) => {
    e.stopPropagation();
    if (onOpenDelete) {
      onOpenDelete(item.id);
    }
  }, [onOpenDelete, item]);
  
  return (
    <tr
      className={cn(
        "h-10 md:h-12 cursor-pointer focus:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:bg-muted/50",
        "transition-all duration-300 relative overflow-visible",
        enhancedHover ? "hover:bg-muted/40" : "hover:bg-muted/40",
        isDeleting && "opacity-50 bg-red-50 dark:bg-red-950/20"
      )}
      onClick={handleClick}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        const target = e.target as HTMLElement | null;
        const isTypingTarget = !!target?.closest(
          'input, textarea, select, [contenteditable="true"]'
        );
        if (isTypingTarget) {
          return;
        }
        if (e.key === 'Enter' || e.key === ' ' || (e as any).keyCode === 13) {
          e.preventDefault();
          if (onOpenDetail) {
            onOpenDetail(item);
          }
        }
      }}
      data-item-id={item.id}
    >
      {columns.map((col) => (
        <td
          key={String(col.key)}
          className={cn(
            "px-2 sm:px-3 py-2 whitespace-nowrap text-[11px] md:text-sm",
            col.width ? `w-${col.width}` : '',
            "truncate max-w-[120px] sm:max-w-[180px] md:max-w-[240px]"
          )}
          title={col.render ? undefined : (fkLabelMap[String(col.key)]?.get(String((item as any)[col.key])) ?? String((item as any)[col.key] ?? ''))}
        >
          {col.render
            ? col.render((item as any)[col.key], item, index)
            : (() => {
                const raw = (item as any)[col.key];
                const mapped = fkLabelMap[String(col.key)]?.get(String(raw));
                return mapped ?? String(raw ?? '-');
              })()}
        </td>
      ))}
      
      {(config.enableDetailModal !== false || config.enableEditModal !== false || config.enableDelete || config.customActions) && (
        <td className="px-2 sm:px-3 py-2 whitespace-nowrap text-[11px] md:text-xs font-medium" 
            onClick={(e) => e.stopPropagation()} 
            onContextMenu={(e) => { e.preventDefault(); e.stopPropagation(); }}>
          <div className="flex items-center gap-1.5 sm:gap-2 flex-nowrap">
            {config.enableDetailModal !== false && (
              <Button
                variant="ghost"
                size="sm"
                className="h-9 w-9 sm:h-9 sm:w-9 p-0 border border-blue-200 dark:border-blue-800 hover:border-blue-400 dark:hover:border-blue-600 hover:bg-blue-50 dark:hover:bg-blue-950/50 hover:text-blue-700 dark:hover:text-blue-300 transition-all duration-200 rounded-lg"
                onClick={handleClick}
                aria-label={`${t('common.view', 'Ver')} ${config.entityName.toLowerCase()} ${item.id}`}
              >
                <Eye className="h-4 w-4" />
              </Button>
            )}
            {config.enableEditModal !== false && (
              <Button
                variant="ghost"
                size="sm"
                className="h-9 w-9 sm:h-9 sm:w-9 p-0 border border-amber-200 dark:border-amber-800 hover:border-amber-400 dark:hover:border-amber-600 hover:bg-amber-50 dark:hover:bg-amber-950/50 hover:text-amber-700 dark:hover:text-amber-300 transition-all duration-200 rounded-lg"
                onClick={handleEdit}
                aria-label={`${t('common.edit', 'Editar')} ${config.entityName.toLowerCase()} ${item.id}`}
              >
                <Edit className="h-4 w-4" />
              </Button>
            )}
            {config.enableDelete && (
              <Button
                variant="ghost"
                size="sm"
                className="h-9 w-9 sm:h-9 sm:w-9 p-0 border border-red-200 dark:border-red-800 hover:border-red-400 dark:hover:border-red-600 hover:bg-red-50 dark:hover:bg-red-950/50 hover:text-red-700 dark:hover:text-red-300 transition-all duration-200 rounded-lg"
                onClick={handleDelete}
                disabled={isDeleting}
                aria-label={`${t('common.delete', 'Eliminar')} ${config.entityName.toLowerCase()} ${item.id}`}
              >
                {isDeleting ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <Trash2 className="h-4 w-4" />
                )}
              </Button>
            )}
            {config.customActions && config.customActions(item)}
          </div>
        </td>
      )}
    </tr>
  );
});

// Componente para renderizar la tabla virtualizada
const VirtualizedTable = memo(<T extends { id: number }>({
  items,
  columns,
  config,
  onOpenDetail,
  onOpenEdit,
  onOpenDelete,
  enhancedHover,
  fkLabelMap,
  deletingItems,
}: {
  items: T[];
  columns: CRUDColumn<T>[];
  config: CRUDConfig<T, any>;
  onOpenDetail?: (item: T) => void;
  onOpenEdit?: (item: T) => void;
  onOpenDelete?: (id: number) => void;
  enhancedHover?: boolean;
  fkLabelMap: Record<string, Map<string, string>>;
  deletingItems: Set<string>;
}) => {
  const Row = useCallback(({ index, style }: { index: number; style: React.CSSProperties }) => {
    const item = items[index];
    
    return (
      <div style={style}>
        <table className="min-w-full divide-y divide-border/70 text-[12px] md:text-sm shadow-sm rounded-lg overflow-hidden">
          <tbody className="divide-y divide-border/60 bg-card">
            <TableRow
              item={item}
              index={index}
              columns={columns}
              config={config}
              onOpenDetail={onOpenDetail}
              onOpenEdit={onOpenEdit}
              onOpenDelete={onOpenDelete}
              enhancedHover={enhancedHover}
              fkLabelMap={fkLabelMap}
              deletingItems={deletingItems}
            />
          </tbody>
        </table>
      </div>
    );
  }, [items, columns, config, onOpenDetail, onOpenEdit, onOpenDelete, enhancedHover, fkLabelMap, deletingItems]);
  
  return (
    <List
      height={400}
      itemCount={items.length}
      itemSize={48}
      overscanCount={5}
    >
      {Row}
    </List>
  );
});

// Componente para renderizar la tabla tradicional
const TraditionalTable = memo(<T extends { id: number }>({
  items,
  columns,
  config,
  onOpenDetail,
  onOpenEdit,
  onOpenDelete,
  enhancedHover,
  fkLabelMap,
  deletingItems,
}: {
  items: T[];
  columns: CRUDColumn<T>[];
  config: CRUDConfig<T, any>;
  onOpenDetail?: (item: T) => void;
  onOpenEdit?: (item: T) => void;
  onOpenDelete?: (id: number) => void;
  enhancedHover?: boolean;
  fkLabelMap: Record<string, Map<string, string>>;
  deletingItems: Set<string>;
}) => {
  return (
    <table className="min-w-full divide-y divide-border/70 text-[12px] md:text-sm shadow-sm rounded-lg overflow-hidden">
      <thead className="sticky top-0 z-10 bg-muted/80 backdrop-blur-sm supports-[backdrop-filter]:bg-muted/60 border-b border-border/50">
        <tr className="h-10">
          {columns.map((col) => (
            <th
              key={String(col.key)}
              className={cn(
                "px-2 sm:px-3 py-2 text-left text-[10px] sm:text-[11px] md:text-xs font-semibold text-muted-foreground uppercase tracking-wider",
                col.width ? `w-${col.width}` : '',
                "truncate"
              )}
            >
              {col.label}
            </th>
          ))}
          {(config.enableDelete || config.customActions) && (
            <th className="px-1 sm:px-2 py-1 text-left text-[10px] sm:text-[11px] md:text-xs font-medium text-muted-foreground uppercase tracking-wider">
              <span className="hidden sm:inline">Acciones</span>
              <span className="sm:hidden">Acc.</span>
            </th>
          )}
        </tr>
      </thead>
      <tbody className="divide-y divide-border/60 bg-card">
        {items.map((item, index) => (
          <TableRow
            key={item.id}
            item={item}
            index={index}
            columns={columns}
            config={config}
            onOpenDetail={onOpenDetail}
            onOpenEdit={onOpenEdit}
            onOpenDelete={onOpenDelete}
            enhancedHover={enhancedHover}
            fkLabelMap={fkLabelMap}
            deletingItems={deletingItems}
          />
        ))}
      </tbody>
    </table>
  );
});

export function CRUDTable<T extends { id: number }>({
  items,
  columns,
  config,
  onOpenDetail,
  onOpenEdit,
  onOpenDelete,
  enhancedHover = false,
  refreshing = false,
}: CRUDTableProps<T>) {
  // Mapa de etiquetas para llaves foráneas
  const fkLabelMap = useMemo(() => {
    const map: Record<string, Map<string, string>> = {};
    try {
      (config.formSections || []).forEach((section) => {
        (section.fields || []).forEach((field) => {
          if ((field.type === 'select' || field.type === 'searchable-select') && field.options && field.options.length) {
            const m = new Map<string, string>();
            field.options.forEach((opt) => {
              m.set(String(opt.value), opt.label);
            });
            map[String(field.name)] = m;
          }
        });
      });
    } catch (e) {
      console.warn('[CRUDTable] Error construyendo mapa de etiquetas', e);
    }
    return map;
  }, [config.formSections]);
  
  // Items en proceso de eliminación
  const deletingItems = useMemo(() => new Set<string>(), []);
  
  // Determinar si usar virtualización
  const useVirtualization = items.length > 100;
  
  return (
    <div className={cn(
      "overflow-x-auto overflow-y-auto flex-1 bg-muted/40",
      refreshing && "opacity-70"
    )}>
      {config.viewMode === 'cards' ? (
        <div className="p-4 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
          {items.map((item) => {
            const firstCol = columns[0];
            const rawTitle = (item as any)[firstCol?.key];
            const mappedTitle = fkLabelMap[String(firstCol?.key)]?.get(String(rawTitle));
            const titleText = mappedTitle ?? String(rawTitle ?? `${config.entityName} #${item.id}`);
            
            return (
              <div
                key={item.id}
                className="bg-card border border-border rounded-lg p-4 shadow-sm hover:shadow-md transition-shadow duration-200 cursor-pointer"
                onClick={() => onOpenDetail?.(item)}
              >
                <h3 className="font-medium text-sm mb-2 truncate">{titleText}</h3>
                <div className="text-xs text-muted-foreground space-y-1">
                  {columns.slice(1, 3).map((col) => {
                    const raw = (item as any)[col.key];
                    const mapped = fkLabelMap[String(col.key)]?.get(String(raw));
                    return (
                      <div key={String(col.key)}>
                        <span className="font-medium">{col.label}:</span>{' '}
                        <span>{mapped ?? String(raw ?? '-')}</span>
                      </div>
                    );
                  })}
                </div>
                <div className="flex justify-end gap-2 mt-3">
                  {config.enableDetailModal !== false && (
                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-8 w-8 p-0"
                      onClick={(e) => {
                        e.stopPropagation();
                        onOpenDetail?.(item);
                      }}
                    >
                      <Eye className="h-4 w-4" />
                    </Button>
                  )}
                  {config.enableEditModal !== false && (
                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-8 w-8 p-0"
                      onClick={(e) => {
                        e.stopPropagation();
                        onOpenEdit?.(item);
                      }}
                    >
                      <Edit className="h-4 w-4" />
                    </Button>
                  )}
                  {config.enableDelete && (
                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-8 w-8 p-0 text-red-600 hover:text-red-700"
                      onClick={(e) => {
                        e.stopPropagation();
                        onOpenDelete?.(item.id);
                      }}
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      ) : useVirtualization ? (
        <VirtualizedTable
          items={items}
          columns={columns}
          config={config}
          onOpenDetail={onOpenDetail}
          onOpenEdit={onOpenEdit}
          onOpenDelete={onOpenDelete}
          enhancedHover={enhancedHover}
          fkLabelMap={fkLabelMap}
          deletingItems={deletingItems}
        />
      ) : (
        <TraditionalTable
          items={items}
          columns={columns}
          config={config}
          onOpenDetail={onOpenDetail}
          onOpenEdit={onOpenEdit}
          onOpenDelete={onOpenDelete}
          enhancedHover={enhancedHover}
          fkLabelMap={fkLabelMap}
          deletingItems={deletingItems}
        />
      )}
    </div>
  );
}

export default CRUDTable;

/*
 * OptimizedAdminCRUDPage
 * 
 * Versión optimizada y refactorizada del componente AdminCRUDPage original.
 * 
 * Mejoras implementadas:
 * - División en componentes más pequeños y especializados
 * - Optimización del rendimiento con memoización y virtualización
 * - Simplificación del manejo de estado
 * - Mejora de la experiencia de usuario con animaciones más sutiles
 * - Mejor accesibilidad y diseño responsivo
 * 
 * @example
 * ```tsx
 * <OptimizedAdminCRUDPage
 *   config={crudConfig}
 *   service={animalService}
 *   initialFormData={initialData}
 * />
 * ```
 */

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { useLocation, useNavigate, useSearchParams } from 'react-router-dom';
import { useResource } from '@/shared/hooks/useResource';
import { useToast } from '@/app/providers/ToastContext';
import { useT } from '@/shared/i18n';

// Componentes especializados
import { CRUDTable } from './CRUDTable';
import { CRUDForm } from './CRUDForm';
import { CRUDPagination } from './CRUDPagination';
import { DetailModal, ConfirmDeleteDialog } from './CRUDModals';
import { CRUDToolbar } from './CRUDToolbar';

// Componentes de UI
import { AppLayout } from '@/widgets/layout/AppLayout';
import { PageHeader } from '@/widgets/layout/PageHeader';
import { EmptyState } from '@/widgets/feedback/EmptyState';
import { ErrorState } from '@/widgets/feedback/ErrorState';
import { SkeletonTable } from '@/widgets/feedback/SkeletonTable';
import { Plus } from 'lucide-react';

// Utilidades
import { addTombstone, getTombstoneIds, clearExpired } from '@/shared/api/cache/tombstones';
import { validateFormSections, type FieldErrors } from '@/shared/utils/formValidation';
import { formatValidationToastMessage, mapBackendFieldErrorsToLabels, buildConflictMessage } from '@/shared/utils/validationMessages';

// Interfaces
import { CRUDConfig, type CRUDFormField } from '../AdminCRUDPage';

interface OptimizedAdminCRUDPageProps<T extends { id: number }, TInput extends Record<string, any>> {
  config: CRUDConfig<T, TInput>;
  service: any; // BaseService instance
  initialFormData: TInput;
  mapResponseToForm?: (item: T) => TInput;
  validateForm?: (formData: TInput) => string | null;
  customDetailContent?: (item: T, navigateToItem?: (item: T) => void) => React.ReactNode;
  onFormDataChange?: (formData: TInput) => void;
  // Opciones de tiempo real
  realtime?: boolean;
  pollIntervalMs?: number;
  refetchOnFocus?: boolean;
  refetchOnReconnect?: boolean;
  // Opciones de estilo hover personalizado
  enhancedHover?: boolean;
}

export function OptimizedAdminCRUDPage<T extends { id: number }, TInput extends Record<string, any>>({
  config,
  service,
  initialFormData,
  mapResponseToForm,
  validateForm,
  customDetailContent,
  onFormDataChange: _onFormDataChange,
  realtime,
  pollIntervalMs,
  refetchOnFocus,
  refetchOnReconnect,
  enhancedHover = false,
}: OptimizedAdminCRUDPageProps<T, TInput>) {
  // Estados simplificados
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<T | null>(null);
  const [saving, setSaving] = useState(false);
  const [formData, setFormData] = useState<TInput>(initialFormData);
  const [formErrors, setFormErrors] = useState<FieldErrors>({});
  const [formErrorMessages, setFormErrorMessages] = useState<string[]>([]);
  const [searchQuery, setSearchQuery] = useState('');

    const updateFieldValue = useCallback((field: CRUDFormField<TInput>, value: any) => {
    const key = String(field.name);
    const nextData = { ...(formData as any), [key]: value } as TInput;
    const validation = validateFormSections(config.formSections || [], nextData as any);
    setFormErrors(validation.errors);
    setFormErrorMessages(validation.messages);
    setFormData(nextData);
  }, [formData, config.formSections]);
  
  // Estados para modales
  const [isDetailOpen, setIsDetailOpen] = useState(false);
  const [detailItem, setDetailItem] = useState<T | null>(null);
  const [detailIndex, setDetailIndex] = useState<number | null>(null);
  const editRequestSeqRef = useRef(0);
  const suppressEditAutoOpenRef = useRef(false);
  const lastClosedEditIdRef = useRef<number | null>(null);
  
  // Estados para confirmación
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [targetId, setTargetId] = useState<number | null>(null);
  
  // Hooks y utilidades
  const { showToast } = useToast();
  const t = useT();
  const location = useLocation();
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  
  // Clave de entidad para tombstones persistentes
  const entityKey = useMemo(() => (config.entityName || 'entity').toLowerCase(), [config.entityName]);
  
  // Limpiar tombstones expirados al montar
  useEffect(() => {
    clearExpired(entityKey);
  }, [entityKey]);
  
  // Configuración de recursos
  const {
    data: items,
    loading,
    error,
    meta,
    setPage,
    setLimit: _setLimit,
    setSearch,
    createItem,
    updateItem,
    deleteItem,
    refetch,
    refreshing,
  } = useResource<T, any>(service as any, {
    autoFetch: true,
    initialParams: {
      page: 1,
      limit: 10,
      fields: config.defaultFields,
      ...(config.additionalFilters || {})
    },
    enableRealtime: realtime === true,
    pollIntervalMs: typeof pollIntervalMs === 'number' ? pollIntervalMs : undefined,
    refetchOnFocus,
    refetchOnReconnect,
  });
  
  // Paginación
  const pageFromURL = parseInt((searchParams.get('page') || '').toString(), 10);
  const currentPage = Number.isFinite(pageFromURL) && pageFromURL > 0 ? pageFromURL : (meta?.page || 1);
  const pageSize = meta?.limit || 10;
  const totalItems = meta?.total || 0;
  const totalPages = meta?.totalPages || Math.ceil(totalItems / pageSize);
  
  // Filtrar items para excluir tombstones
  const filteredItems = useMemo(() => {
    const tombstoneIds = getTombstoneIds(entityKey);
    return (items || []).filter((i: T) => {
      const idStr = String((i as any).id);
      return !tombstoneIds.has(idStr);
    });
  }, [items, entityKey]);
  
  // Handlers
  const openCreate = useCallback(() => {
    setEditingItem(null);
    setFormData(JSON.parse(JSON.stringify(initialFormData)));
    setFormErrors({});
    setFormErrorMessages([]);
    setIsModalOpen(true);
  }, [initialFormData]);
  
  const openEdit = useCallback((item: T) => {
    setEditingItem(item);
    const formValues = mapResponseToForm ? mapResponseToForm(item) : (item as unknown as TInput);
    setFormData(formValues);
    setFormErrors({});
    setFormErrorMessages([]);
    setIsModalOpen(true);
  }, [mapResponseToForm]);
  
  const openDetail = useCallback((item: T) => {
    const idx = filteredItems.findIndex((i) => i.id === item.id);
    const safeIndex = idx >= 0 ? idx : 0;
    setDetailIndex(safeIndex);
    setDetailItem(filteredItems[safeIndex] || item);
    setIsDetailOpen(true);
  }, [filteredItems]);
  
  const openDeleteConfirm = useCallback((id: number) => {
    setTargetId(id);
    setConfirmOpen(true);
  }, []);
  
  const handleModalClose = useCallback(() => {
    if (editingItem?.id) {
      editRequestSeqRef.current += 1;
      suppressEditAutoOpenRef.current = true;
      lastClosedEditIdRef.current = editingItem.id;
    } else {
      suppressEditAutoOpenRef.current = false;
      lastClosedEditIdRef.current = null;
    }
    setIsModalOpen(false);
    setFormData(JSON.parse(JSON.stringify(initialFormData)));
    setFormErrors({});
    setFormErrorMessages([]);
    setEditingItem(null);
    
    const sp = new URLSearchParams(searchParams);
    let changed = false;
    if (sp.has('create')) { sp.delete('create'); changed = true; }
    if (sp.has('edit')) { sp.delete('edit'); changed = true; }
    if (changed) {
      setSearchParams(sp, { replace: true });
    } else if (location.pathname.includes('form')) {
      navigate(-1);
    }
  }, [initialFormData, searchParams, setSearchParams, navigate, location.pathname, editingItem]);
  
  const handleSubmit = useCallback(async (e: React.FormEvent) => {
    e.preventDefault();

    const validation = validateFormSections(config.formSections || [], formData as any);
    if (validation.messages.length > 0) {
      setFormErrors(validation.errors);
      setFormErrorMessages(validation.messages);
      showToast(formatValidationToastMessage(validation.messages), 'error');
      const firstKey = Object.keys(validation.errors)[0];
      if (firstKey && typeof window !== 'undefined') {
        setTimeout(() => {
          const el = document.getElementById(firstKey);
          if (el && 'focus' in el) {
            el.scrollIntoView({ behavior: 'smooth', block: 'center' });
            (el as HTMLElement).focus();
          }
        }, 0);
      }
      return;
    }
    
    if (validateForm) {
      const validationError = validateForm(formData);
      if (validationError) {
        showToast(validationError, 'warning');
        return;
      }
    }
    
    setSaving(true);
    
    try {
      if (editingItem?.id) {
        await updateItem(editingItem.id, formData as any);
        showToast(`✅ ${config.entityName} actualizado correctamente`, 'success');
      } else {
        await createItem(formData as any);
        showToast(`✅ ${config.entityName} creado correctamente`, 'success');
        
        // Volver a la página 1 después de crear
        if (setPage && meta?.page && meta.page > 1) {
          setPage(1);
        }
      }
      
      handleModalClose();
      
      // Refrescar datos después de un breve delay
      setTimeout(async () => {
        try {
          await refetch();
        } catch (error) {
          console.error('Error al refrescar datos:', error);
        }
      }, 300);
    } catch (error: any) {
      let errorMessage = `${t('crud.save_error', 'Error al guardar')} ${config.entityName.toLowerCase()}`;
      
      if (error?.response?.data?.message) {
        errorMessage = error.response.data.message;
      } else if (error?.response?.data?.detail) {
        errorMessage = error.response.data.detail;
      } else if (error?.message) {
        errorMessage = error.message;
      }
      
      const validationErrors =
        (error as any)?.validationErrors ||
        (error as any)?.details?.validation_errors ||
        (error as any)?.details?.errors ||
        error?.response?.data?.errors;

      if (validationErrors && typeof validationErrors === 'object') {
        try {
          const mapped: Record<string, string> = {};
          const msgs: string[] = [];
          Object.entries(validationErrors).forEach(([field, msgsRaw]) => {
            const msg = Array.isArray(msgsRaw) ? msgsRaw.join(', ') : String(msgsRaw);
            mapped[String(field)] = msg;
            msgs.push(`${String(field)}: ${msg}`);
          });
          if (Object.keys(mapped).length > 0) {
            setFormErrors(mapped);
            setFormErrorMessages(msgs);
          }
        } catch {
          // ignore
        }
      }

      if (validationErrors && typeof validationErrors === 'object') {
        const mapped = mapBackendFieldErrorsToLabels(validationErrors, config.formSections || []);
        if (Object.keys(mapped.errors).length > 0) {
          setFormErrors(mapped.errors);
          setFormErrorMessages(mapped.messages);
          errorMessage = formatValidationToastMessage(mapped.messages);
        }
      } else if (
        typeof errorMessage === 'string' &&
        errorMessage.toLowerCase().includes('validaci') &&
        formErrorMessages.length > 0
      ) {
        errorMessage = formatValidationToastMessage(formErrorMessages);
      }

      const status = (error as any)?.status ?? error?.response?.status;
      if (status === 409) {
        const traceId =
          (error as any)?.traceId ||
          error?.response?.data?.error?.trace_id ||
          error?.response?.data?.error?.traceId ||
          error?.response?.data?.trace_id ||
          error?.response?.data?.traceId;
        const details =
          (error as any)?.details ??
          error?.response?.data?.error?.details ??
          error?.response?.data?.details;
        const conflict = buildConflictMessage(details, config.formSections || []);
        const suffix = traceId ? ` (Trace ID: ${traceId})` : '';
        errorMessage = `${conflict.message}${suffix}`;
        if (conflict.field) {
          try {
            setFormErrors(prev => ({ ...(prev || {}), [String(conflict.field)]: conflict.message }));
            setFormErrorMessages(prev => [conflict.message, ...(Array.isArray(prev) ? prev : [])]);
          } catch { /* noop */ }
        }
      }

      showToast(errorMessage, 'error');
    } finally {
      setSaving(false);
    }
  }, [formData, validateForm, editingItem, updateItem, createItem, setPage, meta, handleModalClose, refetch, config.entityName, config.formSections, t, showToast, setFormErrors, setFormErrorMessages, formErrorMessages]);
  
  const handleConfirmDelete = useCallback(async () => {
    if (targetId == null) return;
    
    const idToDelete = targetId;
    setConfirmOpen(false);
    setTargetId(null);
    
    try {
      const success = await deleteItem(idToDelete);
      
      if (success) {
        showToast(`🗑️ ${config.entityName} eliminado correctamente`, 'success');
        
        // Registrar tombstone para ocultar temporalmente si el backend aún lo devuelve
        addTombstone(entityKey, String(idToDelete), 120000);
        
        // Cerrar modales si el item eliminado estaba abierto
        if (isDetailOpen && detailItem?.id === idToDelete) {
          setIsDetailOpen(false);
          setDetailIndex(null);
        }
        if (isModalOpen && editingItem?.id === idToDelete) {
          setIsModalOpen(false);
          setEditingItem(null);
        }
        
        // Verificar si después de eliminar, la página actual quedará vacía
        const currentPageItems = filteredItems.length - 1;
        const willBeEmpty = currentPageItems === 0;
        
        if (willBeEmpty && currentPage > 1 && setPage) {
          setPage(currentPage - 1);
        }
        
        // Refrescar después de un breve delay
        setTimeout(async () => {
          try {
            await refetch();
          } catch (error) {
            console.error('Error al refrescar datos después de eliminar:', error);
          }
        }, 300);
      }
    } catch (error: any) {
      let errorMessage = `Error al eliminar ${config.entityName.toLowerCase()}`;
      
      if (error?.response?.data?.message) {
        errorMessage = error.response.data.message;
      } else if (error?.response?.data?.detail) {
        errorMessage = error.response.data.detail;
      } else if (error?.message) {
        errorMessage = error.message;
      }
      
      showToast(errorMessage, 'error');
    }
  }, [targetId, deleteItem, entityKey, isDetailOpen, detailItem, isModalOpen, editingItem, filteredItems, currentPage, setPage, refetch, config.entityName, showToast]);
  
  // Sincronizar búsqueda con URL
  useEffect(() => {
    const handle = setTimeout(() => {
      const sp = new URLSearchParams(searchParams);
      if (searchQuery) sp.set('search', searchQuery);
      else sp.delete('search');
      sp.set('page', '1');
      setSearchParams(sp, { replace: true });
      setSearch?.(searchQuery);
    }, 500);
    
    return () => clearTimeout(handle);
  }, [searchQuery, searchParams, setSearchParams, setSearch]);
  
  // Sincronizar estado con URL
  useEffect(() => {
    const search = (searchParams.get('search') || '').toString();
    if (search !== searchQuery) {
      setSearchQuery(search);
    }
  }, [searchParams, searchQuery]);
  
  // Auto-open create modal via ?create=1
  useEffect(() => {
    if (config.enableCreateModal !== false) {
      const c = searchParams.get('create');
      if (c && !isModalOpen) {
        openCreate();
      }
    }
  }, [searchParams, config.enableCreateModal, isModalOpen, openCreate]);
  
  // Auto-open edit modal via ?edit=ID
  useEffect(() => {
    if (config.enableEditModal !== false) {
      const e = searchParams.get('edit');
      if (!e) {
        suppressEditAutoOpenRef.current = false;
        lastClosedEditIdRef.current = null;
        return;
      }
      if (suppressEditAutoOpenRef.current && e === String(lastClosedEditIdRef.current ?? '')) {
        return;
      }
      if (e) {
        const id = Number(e);
        if (!Number.isNaN(id) && (!isModalOpen || !editingItem || editingItem.id !== id)) {
          const requestSeq = editRequestSeqRef.current + 1;
          editRequestSeqRef.current = requestSeq;
          (async () => {
            try {
              const item = await service.getById(id);
              if (editRequestSeqRef.current !== requestSeq) {
                return;
              }
              const currentEdit = new URLSearchParams(window.location.search).get('edit');
              if (currentEdit !== String(id)) {
                return;
              }
              openEdit(item);
            } catch (err) {
              showToast(t('common.errorLoading', 'No se pudo cargar el registro para edición'), 'error');
              const sp = new URLSearchParams(searchParams);
              sp.delete('edit');
              setSearchParams(sp, { replace: true });
            }
          })();
        }
      }
    }
  }, [searchParams, config.enableEditModal, isModalOpen, editingItem, service, openEdit, showToast, t, setSearchParams]);
  
  // Header con búsqueda y botones
  const header = (
    <PageHeader
      title={config.title}
      dense
      className="mb-0 sm:mb-0 p-0 sm:p-1"
      titleClassName="text-lg sm:text-xl"
      actions={
        <CRUDToolbar
          searchQuery={searchQuery}
          setSearchQuery={setSearchQuery}
          searchPlaceholder={config.searchPlaceholder}
          onOpenCreate={config.enableCreateModal !== false ? openCreate : undefined}
          customToolbar={config.customToolbar}
        />
      }
    />
  );
  
  // Loading state
  if (loading && !items) {
    return (
      <AppLayout
        header={header}
        className="px-2 sm:px-3 pt-0 sm:pt-1 pb-0 max-w-full min-h-0"
        contentClassName="space-y-0"
      >
        <div className="bg-card/95 backdrop-blur-sm border-2 border-border/50 rounded-xl shadow-2xl shadow-primary/10 overflow-hidden">
          <SkeletonTable
            columnLabels={config.columns.map((c) => c.label)}
            columnWidths={config.columns.map((c) => c.width)}
            rows={8}
          />
        </div>
      </AppLayout>
    );
  }
  
  // Error state
  if (error) {
    return (
      <AppLayout
        header={header}
        className="px-2 sm:px-3 pt-1 sm:pt-2 pb-0 sm:pb-0 md:pb-0 lg:pb-0 max-w-full min-h-0"
        contentClassName="space-y-0"
      >
        <ErrorState
          message={String(error)}
          onRetry={() => window.location.reload()}
        />
      </AppLayout>
    );
  }
  
  // Empty state
  const empty = (filteredItems?.length || 0) === 0;
  
  return (
    <AppLayout
      header={header}
      className="px-2 sm:px-3 pt-0 sm:pt-0 pb-0 sm:pb-0 md:pb-0 lg:pb-0 max-w-full min-h-0 flex flex-col h-full"
      contentClassName="space-y-0 flex-1 flex flex-col min-h-0"
    >
      {config.customHeader && (
        <div className="flex-shrink-0">
          {config.customHeader}
        </div>
      )}
      
      {empty ? (
        <EmptyState
          title={config.emptyStateMessage || `${t('state.empty.title', 'Sin datos')}: ${config.entityName}`}
          description={config.emptyStateDescription || t('state.empty.description', 'Crea el primer registro para comenzar.')}
          action={config.enableCreateModal !== false && (
            <button onClick={openCreate} aria-label={`${t('common.create', 'Crear')} ${config.entityName.toLowerCase()}`}>
              <Plus className="h-4 w-4 mr-2" />
              {t('common.create', 'Crear')} {config.entityName.toLowerCase()}
            </button>
          )}
        />
      ) : (
        <div className="bg-card/95 backdrop-blur-sm border-2 border-border/50 rounded-xl shadow-2xl shadow-primary/10 overflow-hidden flex-1 flex flex-col min-h-0 mt-1">
          <CRUDTable
            items={filteredItems}
            columns={config.columns}
            config={config}
            onOpenDetail={config.enableDetailModal !== false ? openDetail : undefined}
            onOpenEdit={config.enableEditModal !== false ? openEdit : undefined}
            onOpenDelete={config.enableDelete ? openDeleteConfirm : undefined}
            enhancedHover={enhancedHover}
            refreshing={refreshing}
          />
          
          <CRUDPagination
            currentPage={currentPage}
            totalPages={totalPages}
            totalItems={totalItems}
            onPageChange={setPage || ((_page: number) => {})}
            loading={loading}
          />
        </div>
      )}
      
      {/* Create/Edit Modal */}
      {(config.enableCreateModal !== false || config.enableEditModal !== false) && (
        <CRUDForm
          isOpen={isModalOpen}
          onOpenChange={handleModalClose}
          title={editingItem ? `${t('common.edit', 'Editar')} ${config.entityName}: ${editingItem.id}` : `${t('common.create', 'Crear')} ${config.entityName}`}
          formData={formData}
          setFormData={setFormData as unknown as React.Dispatch<React.SetStateAction<Record<string, any>>>}
          formSections={config.formSections}
          fieldErrors={formErrors}
          errorMessages={formErrorMessages}
          onFieldValueChange={updateFieldValue}
          onSubmit={handleSubmit}
          saving={saving}
          editingItem={editingItem}
          showEditTimestamps={config.showEditTimestamps}
        />
      )}
      
      {/* Detail Modal */}
      {config.enableDetailModal !== false && (
        <DetailModal
          isOpen={isDetailOpen}
          onOpenChange={setIsDetailOpen}
          title={detailItem ? `Detalle del ${config.entityName}${config.showIdInDetailTitle === false ? '' : `: ${detailItem.id}`}` : `Detalle del ${config.entityName}`}
          item={detailItem}
          config={config}
          onEdit={config.enableEditModal !== false ? openEdit : undefined}
          customDetailContent={customDetailContent}
          showDetailTimestamps={config.showDetailTimestamps}
          showIdInDetailTitle={config.showIdInDetailTitle}
          detailIndex={detailIndex}
          setDetailIndex={setDetailIndex}
          items={filteredItems}
          setDetailItem={setDetailItem}
        />
      )}
      
      {/* Confirm Delete Dialog */}
      <ConfirmDeleteDialog
        open={confirmOpen}
        onOpenChange={setConfirmOpen}
        title={config.confirmDeleteTitle || '⚠️ Confirmar eliminación'}
        description={config.confirmDeleteDescription || `¿Está seguro que desea eliminar este ${config.entityName.toLowerCase()}? Esta acción no se puede deshacer.`}
        onConfirm={handleConfirmDelete}
        confirmLabel={t('common.delete', 'Eliminar')}
        cancelLabel={t('common.cancel', 'Cancelar')}
        entityName={config.entityName}
      />
    </AppLayout>
  );
}

