import React, { useState, useEffect } from 'react';
import { Alert, AlertDescription } from '@/shared/ui/alert';
import { Badge } from '@/shared/ui/badge';
import { Button } from '@/shared/ui/button';
import { 
  AlertTriangle, 
  CircleCheck, 
  RefreshCw, 
  Server,
  Database,
  Wifi,
  WifiOff
} from 'lucide-react';
import analyticsService from '@/features/reporting/api/analytics.service';

interface BackendStatusProps {
  className?: string;
  showDetails?: boolean;
}

interface HealthStatus {
  status: 'healthy' | 'unhealthy' | 'unknown';
  services?: {
    database?: string;
    cache?: {
      status: string;
      entries: number;
      hit_rate: number;
    };
  };
  version?: string;
  uptime_seconds?: number;
  timestamp?: string;
}

const BackendStatus: React.FC<BackendStatusProps> = ({ 
  className = "", 
  showDetails = false 
}) => {
  const [status, setStatus] = useState<HealthStatus>({ status: 'unknown', timestamp: undefined });
  const [loading, setLoading] = useState(false);
  const [lastCheck, setLastCheck] = useState<Date | null>(null);

  const checkBackendHealth = async () => {
    setLoading(true);
    try {
      // Attempt to call a backend health endpoint. If not available, approximate using health statistics.
      // Attempt health-specific endpoint first
      let health: any = null;
      try {
        health = await analyticsService.getHealthCheck();
      } catch {
        // fallback to statistics as probe
        await analyticsService.getHealthStatistics();
        health = { status: 'healthy' };
      }
      if (health && (health.status === 'healthy' || health.status === 'ok')) {
        setStatus({ status: 'healthy', timestamp: new Date().toISOString() } as any);
      } else {
        setStatus({ status: 'unhealthy', timestamp: new Date().toISOString() } as any);
      }
      setLastCheck(new Date());
    } catch (error) {
      console.error('Error checking backend health:', error);
      setStatus({ status: 'unhealthy' });
      setLastCheck(new Date());
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    checkBackendHealth();
    // Check every 30 seconds
    const interval = setInterval(checkBackendHealth, 30000);
    return () => clearInterval(interval);
  }, []);

  const getStatusColor = () => {
    switch (status.status) {
      case 'healthy':
        return 'text-green-600 bg-green-50 border-green-200';
      case 'unhealthy':
        return 'text-red-600 bg-red-50 border-red-200';
      default:
        return 'text-gray-600 bg-gray-50 border-gray-200';
    }
  };

  const getStatusIcon = () => {
    switch (status.status) {
      case 'healthy':
        return <CircleCheck className="h-4 w-4 text-green-600" />;
      case 'unhealthy':
        return <AlertTriangle className="h-4 w-4 text-red-600" />;
      default:
        return <Server className="h-4 w-4 text-gray-600" />;
    }
  };

  const getStatusText = () => {
    switch (status.status) {
      case 'healthy':
        return 'Backend Connected';
      case 'unhealthy':
        return 'Backend with Problems';
      default:
        return 'Unknown Status';
    }
  };

  const formatUptime = (seconds?: number) => {
    if (!seconds) return 'N/A';
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    return `${hours}h ${minutes}m`;
  };

  if (!showDetails && status.status === 'healthy') {
    return null; // No mostrar nada si está todo bien y no se requieren detalles
  }

  return (
    <div className={`space-y-2 ${className}`}>
      <Alert className={getStatusColor()}>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            {getStatusIcon()}
            <span className="font-medium">{getStatusText()}</span>
            {status.status === 'healthy' ? (
              <Wifi className="h-4 w-4 text-green-600" />
            ) : (
              <WifiOff className="h-4 w-4 text-red-600" />
            )}
          </div>
          <div className="flex items-center gap-2">
            {lastCheck && (
              <span className="text-xs text-muted-foreground">
                {lastCheck.toLocaleTimeString()}
              </span>
            )}
            <Button
              variant="ghost"
              size="sm"
              onClick={checkBackendHealth}
              disabled={loading}
              className="h-6 w-6 p-0"
            >
              <RefreshCw className={`h-3 w-3 ${loading ? 'animate-spin' : ''}`} />
            </Button>
          </div>
        </div>
        
        {showDetails && (
          <AlertDescription className="mt-2">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-2 text-sm">
              {status.version && (
                <div className="flex items-center gap-1">
                  <Server className="h-3 w-3" />
                  <span>Version: {status.version}</span>
                </div>
              )}
              
              {status.uptime_seconds && (
                <div className="flex items-center gap-1">
                  <CircleCheck className="h-3 w-3" />
                  <span>Uptime: {formatUptime(status.uptime_seconds)}</span>
                </div>
              )}
              
              {status.services?.database && (
                <div className="flex items-center gap-1">
                  <Database className="h-3 w-3" />
                  <span>Database: </span>
                  <Badge 
                    variant={status.services.database.includes('unhealthy') ? 'destructive' : 'default'}
                    className="text-xs"
                  >
                    {status.services.database.includes('unhealthy') ? 'Error' : 'OK'}
                  </Badge>
                </div>
              )}
              
              {status.services?.cache && (
                <div className="flex items-center gap-1">
                  <span>Cache: {status.services.cache.entries} entries</span>
                  <Badge variant="secondary" className="text-xs">
                    {Math.round(status.services.cache.hit_rate * 100)}% hit rate
                  </Badge>
                </div>
              )}
            </div>
            
            {status.status === 'unhealthy' && (
              <div className="mt-2 p-2 bg-red-100 rounded text-red-800 text-xs">
                <strong>Problems detected:</strong>
                <ul className="mt-1 list-disc list-inside">
                  {status.services?.database?.includes('unhealthy') && (
                    <li>Database connection error</li>
                  )}
                  <li>Some services may not work correctly</li>
                  <li>Contact the system administrator if the problem persists</li>
                </ul>
              </div>
            )}
          </AlertDescription>
        )}
      </Alert>
    </div>
  );
};

export default BackendStatus;

import React, { useState, useEffect } from 'react';
import { Alert, AlertDescription } from '@/shared/ui/alert';
import { Button } from '@/shared/ui/button';
import { RefreshCw, CircleCheck, CircleX } from 'lucide-react';
import { apiFetch } from '@/shared/api/apiFetch';

interface BackendStatus {
  isOnline: boolean;
  loading: boolean;
  lastChecked: Date | null;
  error?: string;
}

export const BackendStatusIndicator: React.FC = () => {
  const [status, setStatus] = useState<BackendStatus>({
    isOnline: false,
    loading: true,
    lastChecked: null
  });

  const checkBackendStatus = async () => {
    setStatus(prev => ({ ...prev, loading: true, error: undefined }));
    
    try {
      // Intentar hacer un HEAD request para verificar conectividad
      await apiFetch({ url: '/', method: 'HEAD' });
      setStatus({
        isOnline: true,
        loading: false,
        lastChecked: new Date(),
        error: undefined
      });
    } catch (error: any) {
      setStatus({
        isOnline: false,
        loading: false,
        lastChecked: new Date(),
        error: error.code === 'ERR_NETWORK' 
          ? 'No se puede conectar al servidor backend'
          : error.message || 'Error desconocido'
      });
    }
  };

  useEffect(() => {
    checkBackendStatus();
    // Verificar cada 30 segundos
    const interval = setInterval(checkBackendStatus, 30000);
    return () => clearInterval(interval);
  }, []);

  if (status.loading && !status.lastChecked) {
    return (
      <Alert className="border-blue-200 bg-blue-50">
        <RefreshCw className="h-4 w-4 animate-spin" />
        <AlertDescription>
          Verificando conexión con el servidor...
        </AlertDescription>
      </Alert>
    );
  }

  if (!status.isOnline) {
    return (
      <Alert variant="destructive" className="mb-4">
        <CircleX className="h-4 w-4" />
        <AlertDescription>
          <div className="flex items-center justify-between">
            <div>
              <strong>Servidor no disponible</strong>
              <br />
              {status.error || 'No se puede conectar al backend'}
              <br />
              <small className="text-sm opacity-75">
                Última verificación: {status.lastChecked?.toLocaleTimeString()}
              </small>
            </div>
            <Button
              size="sm"
              variant="outline"
              onClick={checkBackendStatus}
              disabled={status.loading}
              className="ml-4"
            >
              {status.loading ? (
                <RefreshCw className="h-3 w-3 animate-spin" />
              ) : (
                'Reintentar'
              )}
            </Button>
          </div>
        </AlertDescription>
      </Alert>
    );
  }

  return (
    <Alert className="border-green-200 bg-green-50 mb-4">
      <CircleCheck className="h-4 w-4 text-green-600" />
      <AlertDescription className="text-green-800">
        <div className="flex items-center justify-between">
          <div>
            <strong>Servidor conectado</strong>
            <br />
            <small className="text-sm opacity-75">
              Última verificación: {status.lastChecked?.toLocaleTimeString()}
            </small>
          </div>
          <Button
            size="sm"
            variant="outline"
            onClick={checkBackendStatus}
            disabled={status.loading}
            className="ml-4 border-green-300 text-green-700 hover:bg-green-100"
          >
            {status.loading ? (
              <RefreshCw className="h-3 w-3 animate-spin" />
            ) : (
              'Verificar'
            )}
          </Button>
        </div>
      </AlertDescription>
    </Alert>
  );
};

export default BackendStatusIndicator;

import React, { useState } from 'react';
import { ChevronDown, ChevronUp } from 'lucide-react';
import { cn } from '@/shared/ui/cn';
import { Button } from '@/shared/ui/button';

interface CollapsibleCardProps {
    title: string;
    children: React.ReactNode;
    defaultCollapsed?: boolean;
    className?: string;
    accent?: 'blue' | 'cyan' | 'teal' | 'emerald' | 'purple' | 'indigo' | 'red' | 'amber' | 'slate';
}

export function CollapsibleCard({
    title,
    children,
    defaultCollapsed = false,
    className,
    accent = 'slate'
}: CollapsibleCardProps) {
    const [isCollapsed, setIsCollapsed] = useState(defaultCollapsed);

    const accentClasses: Record<string, string> = {
        blue: "text-blue-700 dark:text-blue-300 before:bg-blue-500 shadow-blue-500/10",
        cyan: "text-cyan-700 dark:text-cyan-300 before:bg-cyan-500 shadow-cyan-500/10",
        teal: "text-teal-700 dark:text-teal-300 before:bg-teal-500 shadow-teal-500/10",
        emerald: "text-emerald-700 dark:text-emerald-300 before:bg-emerald-500 shadow-emerald-500/10",
        purple: "text-purple-700 dark:text-purple-300 before:bg-purple-500 shadow-purple-500/10",
        indigo: "text-indigo-700 dark:text-indigo-300 before:bg-indigo-500 shadow-indigo-500/10",
        red: "text-red-700 dark:text-red-300 before:bg-red-500 shadow-red-500/10",
        amber: "text-amber-700 dark:text-amber-300 before:bg-amber-500 shadow-amber-500/10",
        slate: "text-slate-700 dark:text-slate-300 before:bg-slate-500 shadow-slate-500/10",
    };

    const textClasses = accentClasses[accent] || accentClasses.slate;

    return (
        <div className={cn(
            "rounded-xl shadow-lg border overflow-hidden transition-all duration-300 bg-card",
            className || "border-border/60"
        )}>
            <div
                className={cn(
                    "flex items-center justify-between p-4 cursor-pointer transition-colors border-b border-border/40",
                    // Subtle gradient background for header based on accent could be nice, but keeping it clean for now
                    "hover:bg-accent/5",
                    isCollapsed ? "bg-card" : "bg-card/50"
                )}
                onClick={() => setIsCollapsed(!isCollapsed)}
            >
                <div className="flex items-center gap-3">
                    <div className={cn("w-1 h-5 rounded-full shadow-sm", textClasses.split(' before:')[1])} />
                    <h3 className={cn(
                        "text-xs font-bold uppercase tracking-wider",
                        textClasses.split(' before:')[0]
                    )}>
                        {title}
                    </h3>
                </div>
                <Button
                    variant="ghost"
                    size="sm"
                    className="h-8 w-8 p-0 rounded-full hover:bg-black/5 dark:hover:bg-white/10"
                >
                    {isCollapsed ? <ChevronDown className="h-5 w-5 opacity-70" /> : <ChevronUp className="h-5 w-5 opacity-70" />}
                </Button>
            </div>
            <div className={cn(
                "transition-all duration-300 ease-in-out",
                isCollapsed ? 'max-h-0 opacity-0 overflow-hidden' : 'max-h-[2000px] opacity-100 overflow-visible'
            )}>
                <div className="p-5">
                    {children}
                </div>
            </div>
        </div>
    );
}

import React from "react";
import { GenericModal } from "@/shared/ui/common/GenericModal";
import { Button } from "@/shared/ui/button";
import { AlertTriangle } from "lucide-react";
import { cn } from "@/shared/ui/cn";

/**
 * ConfirmDialog: diálogo de confirmación accesible basado en GenericModal.
 *
 * Provee estructura estándar para confirmar acciones destructivas o relevantes.
 *
 * @example
 * ```tsx
 * import { ConfirmDialog } from "@/shared/ui/common/ConfirmDialog";
 *
 * function Example() {
 *   const [open, setOpen] = React.useState(false);
 *   return (
 *     <>
 *       <button onClick={() => setOpen(true)}>Eliminar</button>
 *       <ConfirmDialog
 *         open={open}
 *         onOpenChange={setOpen}
 *         title="¿Estás seguro?"
 *         description="Esta acción no se puede deshacer."
 *         confirmLabel="Confirmar"
 *         cancelLabel="Cancelar"
 *         onConfirm={() => { console.log("confirmado"); }}
 *       />
 *     </>
 *   );
 * }
 * ```
 */
export interface ConfirmDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: React.ReactNode;
  description?: string;
  confirmLabel?: string;
  cancelLabel?: string;
  onConfirm?: () => void;
  confirmVariant?: React.ComponentProps<typeof Button>["variant"];
  cancelVariant?: React.ComponentProps<typeof Button>["variant"];
  size?: React.ComponentProps<typeof GenericModal>["size"];
  className?: string;
  draggable?: boolean;
  disabled?: boolean; // Deshabilitar botón de confirmación
  // Nuevas props para advertencias detalladas
  detailedMessage?: string; // Mensaje largo con formato markdown/líneas
  showWarningIcon?: boolean; // Mostrar ícono de advertencia
  dependencies?: Array<{
    entity: string;
    count: number;
    samples?: string[];
  }>; // Lista estructurada de dependencias
  zIndex?: number;
}

export function ConfirmDialog({
  open,
  onOpenChange,
  title,
  description,
  confirmLabel = "Confirmar",
  cancelLabel = "Cancelar",
  onConfirm,
  confirmVariant = "destructive",
  cancelVariant = "outline",
  size = "sm",
  className,
  draggable = true,
  disabled = false,
  detailedMessage,
  showWarningIcon = false,
  dependencies,
  zIndex,
}: ConfirmDialogProps) {
  // Si hay mensaje detallado o dependencias, usar tamaño más grande
  const effectiveSize = detailedMessage || dependencies ? "md" : size;
  const isDestructive = confirmVariant === "destructive";
  const modalClassName = cn(
    className,
    isDestructive ? "" : ""
  );

  return (
    <GenericModal
      isOpen={open}
      onOpenChange={onOpenChange}
      title={title}
      description={description}
      size={effectiveSize}
      className={modalClassName}
      draggable={draggable}
      zIndex={zIndex}
    >
      {/* Contenido adicional con advertencias detalladas */}
      {(showWarningIcon || detailedMessage || dependencies) && (
        <div className="mb-4 space-y-3">
          {/* Ícono de advertencia */}
          {showWarningIcon && (
            <div className="flex items-start gap-2 text-amber-700 dark:text-amber-400">
              <AlertTriangle className="h-5 w-5 flex-shrink-0 mt-0.5" />
              <div className="space-y-1">
                <div className="font-semibold text-sm">Integridad referencial: eliminacion bloqueada</div>
                <div className="text-xs text-amber-800/90 dark:text-amber-300/90">
                  Hay registros relacionados. Elimine o reasigne esos registros antes de intentar de nuevo.
                </div>
              </div>
            </div>
          )}

          {/* Mensaje detallado con formato preservado */}
          {detailedMessage && (
            <div className="bg-amber-50 dark:bg-amber-950/20 border border-amber-200 dark:border-amber-800 rounded-md p-3 max-h-[400px] overflow-y-auto">
              <div className="text-sm text-gray-700 dark:text-gray-300 whitespace-pre-wrap font-mono leading-relaxed">
                {detailedMessage.split('\n').map((line, idx) => {
                  // Detectar si es título (empieza con ** o contiene **)
                  const isBold = line.includes('**');
                  if (isBold) {
                    const parts = line.split('**');
                    return (
                      <div key={idx} className="my-1">
                        {parts.map((part, i) =>
                          i % 2 === 1 ? <strong key={i} className="font-bold text-gray-900 dark:text-gray-100">{part}</strong> : part
                        )}
                      </div>
                    );
                  }
                  // Líneas vacías
                  if (!line.trim()) return <div key={idx} className="h-2" />;
                  // Líneas normales
                  return <div key={idx}>{line}</div>;
                })}
              </div>
            </div>
          )}

          {/* Lista estructurada de dependencias */}
          {dependencies && dependencies.length > 0 && (
            <div className="bg-blue-50 dark:bg-blue-950/20 border border-blue-200 dark:border-blue-800 rounded-md p-3">
              <h4 className="text-sm font-semibold text-blue-900 dark:text-blue-100 mb-2">
                Registros Relacionados ({dependencies.reduce((sum, d) => sum + d.count, 0)} total)
              </h4>
              <ul className="space-y-2 text-sm">
                {dependencies.map((dep, idx) => (
                  <li key={idx} className="flex flex-col gap-1">
                    <div className="flex items-center gap-2">
                      <span className="flex-shrink-0 w-2 h-2 bg-blue-500 rounded-full" />
                      <span className="font-medium text-blue-900 dark:text-blue-100">
                        {dep.entity}: {dep.count}
                      </span>
                    </div>
                    {dep.samples && dep.samples.length > 0 && (
                      <ul className="ml-6 text-gray-600 dark:text-gray-400 text-xs space-y-0.5">
                        {dep.samples.map((sample, sIdx) => (
                          <li key={sIdx}>• {sample}</li>
                        ))}
                      </ul>
                    )}
                  </li>
                ))}
              </ul>
            </div>
          )}
        </div>
      )}

      <div className="flex justify-end gap-2">
        <Button
          variant={cancelVariant}
          onClick={() => onOpenChange(false)}
          aria-label={cancelLabel}
        >
          {cancelLabel}
        </Button>
        <Button
          variant={confirmVariant}
          onClick={() => {
            onConfirm?.();
            onOpenChange(false);
          }}
          aria-label={confirmLabel}
          disabled={disabled}
          className={cn("transition-colors duration-300", isDestructive ? "focus-visible:ring-red-500" : "")}
        >
          {isDestructive && <AlertTriangle className="mr-1.5 h-4 w-4" aria-hidden />}
          {confirmLabel}
        </Button>
      </div>
    </GenericModal>
  );
}

export default ConfirmDialog;

/**
 * Indicador visual de sincronización de datos
 * Muestra el estado de sync y última actualización
 */

import React, { memo } from 'react';
import { RefreshCw, CircleCheck, CircleAlert, Clock } from 'lucide-react';
import { Badge } from '@/shared/ui/badge';
import { Button } from '@/shared/ui/button';
import { cn } from '@/shared/ui/cn';

interface DataSyncIndicatorProps {
  /**
   * Estado de sincronización
   */
  status: 'idle' | 'syncing' | 'success' | 'error';

  /**
   * Timestamp de última sincronización (ISO string)
   */
  lastSync?: string | null;

  /**
   * Número de cambios en última sincronización
   */
  changesCount?: number;

  /**
   * Callback para sincronizar manualmente
   */
  onSync?: () => void;

  /**
   * Mostrar en formato compacto
   */
  compact?: boolean;

  /**
   * Clase CSS adicional
   */
  className?: string;
}

/**
 * Formatea tiempo relativo (ej: "hace 2 minutos")
 */
function formatRelativeTime(isoString: string): string {
  const date = new Date(isoString);
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffSec = Math.floor(diffMs / 1000);
  const diffMin = Math.floor(diffSec / 60);
  const diffHour = Math.floor(diffMin / 60);
  const diffDay = Math.floor(diffHour / 24);

  if (diffSec < 10) return 'ahora mismo';
  if (diffSec < 60) return `hace ${diffSec}s`;
  if (diffMin < 60) return `hace ${diffMin} min`;
  if (diffHour < 24) return `hace ${diffHour}h`;
  if (diffDay === 1) return 'ayer';
  return `hace ${diffDay} días`;
}

export const DataSyncIndicator = memo<DataSyncIndicatorProps>(({
  status,
  lastSync,
  changesCount = 0,
  onSync,
  compact = false,
  className,
}) => {
  // Renderizado compacto (solo icono)
  if (compact) {
    return (
      <div className={cn('flex items-center gap-2', className)}>
        {status === 'syncing' && (
          <RefreshCw className="h-4 w-4 animate-spin text-blue-500" />
        )}
        {status === 'success' && (
          <CircleCheck className="h-4 w-4 text-green-500" />
        )}
        {status === 'error' && (
          <CircleAlert className="h-4 w-4 text-red-500" />
        )}
        {status === 'idle' && lastSync && (
          <Clock className="h-4 w-4 text-gray-400" />
        )}
      </div>
    );
  }

  // Renderizado completo
  return (
    <div className={cn('flex items-center gap-3', className)}>
      {/* Estado */}
      <div className="flex items-center gap-2">
        {status === 'syncing' && (
          <>
            <RefreshCw className="h-4 w-4 animate-spin text-blue-500" />
            <span className="text-sm text-muted-foreground">Sincronizando...</span>
          </>
        )}

        {status === 'success' && (
          <>
            <CircleCheck className="h-4 w-4 text-green-500" />
            <span className="text-sm text-muted-foreground">
              Sincronizado
              {changesCount > 0 && ` (${changesCount} cambios)`}
            </span>
          </>
        )}

        {status === 'error' && (
          <>
            <CircleAlert className="h-4 w-4 text-red-500" />
            <span className="text-sm text-destructive">Error al sincronizar</span>
          </>
        )}

        {status === 'idle' && lastSync && (
          <>
            <Clock className="h-4 w-4 text-gray-400" />
            <span className="text-sm text-muted-foreground">
              {formatRelativeTime(lastSync)}
            </span>
          </>
        )}
      </div>

      {/* Badge con contador de cambios */}
      {changesCount > 0 && status === 'success' && (
        <Badge variant="secondary" className="text-xs">
          +{changesCount}
        </Badge>
      )}

      {/* Botón de sync manual */}
      {onSync && status !== 'syncing' && (
        <Button
          variant="ghost"
          size="sm"
          onClick={onSync}
          className="h-7 px-2"
          title="Sincronizar ahora"
        >
          <RefreshCw className="h-3 w-3" />
        </Button>
      )}
    </div>
  );
});

DataSyncIndicator.displayName = 'DataSyncIndicator';

/**
 * Variante minimalista (solo badge)
 */
export const SyncBadge = memo<Pick<DataSyncIndicatorProps, 'status' | 'changesCount'>>(({
  status,
  changesCount = 0,
}) => {
  if (status === 'idle' && changesCount === 0) return null;

  return (
    <Badge
      variant={status === 'error' ? 'destructive' : status === 'syncing' ? 'default' : 'secondary'}
      className="flex items-center gap-1 text-xs"
    >
      {status === 'syncing' && <RefreshCw className="h-3 w-3 animate-spin" />}
      {status === 'success' && <CircleCheck className="h-3 w-3" />}
      {status === 'error' && <CircleAlert className="h-3 w-3" />}

      {status === 'syncing' && 'Sincronizando'}
      {status === 'success' && changesCount > 0 && `${changesCount} nuevos`}
      {status === 'success' && changesCount === 0 && 'Al día'}
      {status === 'error' && 'Error'}
    </Badge>
  );
});

SyncBadge.displayName = 'SyncBadge';

import React from 'react';
import { TrendingUp } from 'lucide-react';
import { ForeignKeyLink } from './ForeignKeyLink';
import { animalsService } from '@/entities/animal/api/animal.service';
import { breedsService } from '@/entities/breed/api/breeds.service';
import { speciesService } from '@/entities/species/api/species.service';
import { fieldService } from '@/entities/field/api/field.service';
import { foodTypesService } from '@/entities/food-type/api/foodTypes.service';
import { vaccinesService } from '@/entities/vaccine/api/vaccines.service';
import { medicationsService } from '@/entities/medication/api/medications.service';
import { diseaseService } from '@/entities/disease/api/disease.service';
import { usersService } from '@/entities/user/api/user.service';
import { Badge } from '@/shared/ui/badge';
import { SectionCard, InfoField, modalStyles } from '@/shared/ui/common/ModalStyles';
import { AnimalModalContent } from '@/widgets/dashboard/animals/AnimalModalContent';
import { useAuth } from '@/features/auth/model/useAuth';
import { AnimalHistoryModal } from '@/widgets/dashboard/AnimalHistoryModal';
import GeneticTreeModal from '@/widgets/dashboard/GeneticTreeModal';
import DescendantsTreeModal from '@/widgets/dashboard/DescendantsTreeModal';
import { useAnimalTreeApi, graphToAncestorLevels, graphToDescendantLevels } from '@/entities/animal/model/useAnimalTreeApi';
import { Button } from '@/shared/ui/button';

// Helper para Animal con renderizado personalizado
export const AnimalLink: React.FC<{ id: number | string; label: string; children?: React.ReactNode }> = ({ id, label, children }) => {
  const renderAnimalContent = (initialAnimal: any) => {
    const Wrapper: React.FC<{ initial: any }> = ({ initial }) => {
      const [animal, setAnimal] = React.useState<any>(initial);
      const { user } = useAuth();

      // Modales auxiliares (historial y árboles) para replicar el detalle completo
      const [isHistoryOpen, setIsHistoryOpen] = React.useState(false);
      const [historyAnimal, setHistoryAnimal] = React.useState<any | null>(null);

      const ancestorsApi = useAnimalTreeApi();
      const descendantsApi = useAnimalTreeApi();
      const [isTreeOpen, setIsTreeOpen] = React.useState(false);
      const [treeAnimal, setTreeAnimal] = React.useState<any | null>(null);
      const [treeLevels, setTreeLevels] = React.useState<any[][]>([]);
      const [ancestorCounts, setAncestorCounts] = React.useState<any>();
      const [ancestorSummary, setAncestorSummary] = React.useState<any>();
      const [ancestorEdgeExamples, setAncestorEdgeExamples] = React.useState<any>();
      const [treeRootId, setTreeRootId] = React.useState<number | null>(null);

      const [isDescOpen, setIsDescOpen] = React.useState(false);
      const [descAnimal, setDescAnimal] = React.useState<any | null>(null);
      const [descLevels, setDescLevels] = React.useState<any[][]>([]);
      const [descCounts, setDescCounts] = React.useState<any>();
      const [descSummary, setDescSummary] = React.useState<any>();
      const [descEdgeExamples, setDescEdgeExamples] = React.useState<any>();
      const [descRootId, setDescRootId] = React.useState<number | null>(null);

      const loadAnimal = async (animalId: number) => {
        const next = await animalsService.getById(animalId);
        setAnimal(next);
      };

      const computeBreedLabel = (a: any) =>
        a?.breed?.name || (a?.breeds_id || a?.breed_id ? `ID ${a.breeds_id ?? a.breed_id}` : '-');
      const computeParentLabel = (parentId?: number | null) => (parentId ? `ID ${parentId}` : '-');

      const breedLabel = computeBreedLabel(animal);
      const fatherId = animal?.idFather || animal?.father_id;
      const motherId = animal?.idMother || animal?.mother_id;
      const fatherLabel = computeParentLabel(fatherId ?? null);
      const motherLabel = computeParentLabel(motherId ?? null);

      const openHistory = (record: any) => {
        const payload = {
          idAnimal: Number(record?.id ?? 0),
          record: record?.record || '',
          breed: record?.breed,
          birth_date: record?.birth_date,
          sex: record?.sex || record?.gender,
          status: record?.status,
        };
        setHistoryAnimal(payload);
        setIsHistoryOpen(true);
      };

      const openAncestorsTree = async (record: any) => {
        const idNum = Number(record?.id ?? 0);
        if (!idNum) return;
        const resp = await ancestorsApi.fetchAncestors(idNum, 3, 'id,record,sex,breeds_id,idFather,idMother');
        if (!resp) {
          setTreeAnimal(record);
          setTreeLevels([]);
          setAncestorCounts(undefined);
          setAncestorSummary(undefined);
          setAncestorEdgeExamples(undefined);
          setTreeRootId(idNum);
          setIsTreeOpen(true);
          return;
        }
        setTreeRootId(resp.rootId);
        setTreeAnimal(resp.nodes[resp.rootId]);
        setTreeLevels(graphToAncestorLevels(resp));
        setAncestorCounts(resp.counts);
        setAncestorSummary(resp.summary);
        setAncestorEdgeExamples(resp.edge_examples);
        setIsTreeOpen(true);
      };

      const openDescendantsTree = async (record: any) => {
        const idNum = Number(record?.id ?? 0);
        if (!idNum) return;
        const resp = await descendantsApi.fetchDescendants(idNum, 3, 'id,record,sex,breeds_id,idFather,idMother');
        if (!resp) {
          setDescAnimal(record);
          setDescLevels([]);
          setDescCounts(undefined);
          setDescSummary(undefined);
          setDescEdgeExamples(undefined);
          setDescRootId(idNum);
          setIsDescOpen(true);
          return;
        }
        setDescRootId(resp.rootId);
        setDescAnimal(resp.nodes[resp.rootId]);
        setDescLevels(graphToDescendantLevels(resp));
        setDescCounts(resp.counts);
        setDescSummary(resp.summary);
        setDescEdgeExamples(resp.edge_examples);
        setIsDescOpen(true);
      };

      return (
        <>
          <AnimalModalContent
            animal={animal}
            breedLabel={breedLabel}
            fatherLabel={fatherLabel}
            motherLabel={motherLabel}
            onFatherClick={fatherId ? (id: number) => loadAnimal(id) : undefined}
            onMotherClick={motherId ? (id: number) => loadAnimal(id) : undefined}
            currentUserId={user?.id}
            onOpenHistory={() => openHistory(animal)}
            onOpenAncestorsTree={() => openAncestorsTree(animal)}
            onOpenDescendantsTree={() => openDescendantsTree(animal)}
          />

          {isHistoryOpen && historyAnimal && (
            <AnimalHistoryModal
              animal={historyAnimal}
              onClose={() => {
                setIsHistoryOpen(false);
                setHistoryAnimal(null);
              }}
            />
          )}

          <GeneticTreeModal
            isOpen={isTreeOpen}
            onClose={() => {
              setIsTreeOpen(false);
              setTreeAnimal(null);
              setTreeLevels([]);
              ancestorsApi.clearError();
            }}
            animal={treeAnimal}
            levels={treeLevels}
            counts={ancestorCounts}
            summary={ancestorSummary}
            edgeExamples={ancestorEdgeExamples}
            dependencyInfo={ancestorsApi.dependencyInfo}
            treeError={ancestorsApi.error}
            loadingMore={ancestorsApi.loading}
            onNavigateToAnimal={openAncestorsTree}
            onOpenDescendantsTreeForAnimal={openDescendantsTree}
            onLoadMore={async () => {
              if (!treeRootId || !ancestorsApi.graph) return;
              const merged = await ancestorsApi.loadMore('ancestors', treeRootId, ancestorsApi.graph, {
                increment: 2,
                fields: 'id,record,sex,breeds_id,idFather,idMother',
              });
              setTreeAnimal(merged.nodes[merged.rootId]);
              setTreeLevels(graphToAncestorLevels(merged));
              setAncestorCounts(merged.counts);
              setAncestorSummary(merged.summary);
              setAncestorEdgeExamples(merged.edge_examples);
            }}
          />

          <DescendantsTreeModal
            isOpen={isDescOpen}
            onClose={() => {
              setIsDescOpen(false);
              setDescAnimal(null);
              setDescLevels([]);
              descendantsApi.clearError();
            }}
            animal={descAnimal}
            levels={descLevels}
            counts={descCounts}
            summary={descSummary}
            edgeExamples={descEdgeExamples}
            dependencyInfo={descendantsApi.dependencyInfo}
            treeError={descendantsApi.error}
            loadingMore={descendantsApi.loading}
            onNavigateToAnimal={openDescendantsTree}
            onOpenAncestorsTreeForAnimal={openAncestorsTree}
            onLoadMore={async () => {
              if (!descRootId || !descendantsApi.graph) return;
              const merged = await descendantsApi.loadMore('descendants', descRootId, descendantsApi.graph, {
                increment: 2,
                fields: 'id,record,sex,breeds_id,idFather,idMother',
              });
              setDescAnimal(merged.nodes[merged.rootId]);
              setDescLevels(graphToDescendantLevels(merged));
              setDescCounts(merged.counts);
              setDescSummary(merged.summary);
              setDescEdgeExamples(merged.edge_examples);
            }}
          />
        </>
      );
    };

    return <Wrapper initial={initialAnimal} />;
  };

  return (
    <ForeignKeyLink
      id={id}
      label={label}
      service={animalsService}
      modalTitle="Detalle del Animal"
      renderContent={renderAnimalContent}
      size="full"
      enableFullScreenToggle
    >
      {children}
    </ForeignKeyLink>
  );
};

