// eslint-disable-next-line react-refresh/only-export-components
export const useForeignKeyColumn = (
  type: 'animal' | 'breed' | 'species' | 'field' | 'foodType' | 'vaccine' | 'medication' | 'disease' | 'user',
  labelMap: Map<number, string>
) => {
  return (value: any) => {
    if (!value) return '-';

    const id = Number(value);
    const label = labelMap.get(id) || `ID ${id}`;

    const componentMap = {
      animal: AnimalLink,
      breed: BreedLink,
      species: SpeciesLink,
      field: FieldLink,
      foodType: FoodTypeLink,
      vaccine: VaccineLink,
      medication: MedicationLink,
      disease: DiseaseLink,
      user: UserLink,
    };

    const Component = componentMap[type];
    return <Component id={id} label={label} />;
  };
};

import React, { useState } from 'react';
import { ExternalLink } from 'lucide-react';
import { GenericModal } from './GenericModal';
import { Card, CardHeader, CardTitle, CardContent } from '@/shared/ui/card';
import { Button } from '@/shared/ui/button';

export interface ForeignKeyLinkHelpers {
  closeModal: () => void;
  reload: () => Promise<void>;
  setData: (data: any) => void;
}


interface ForeignKeyLinkProps {
  /**
   * ID de la entidad referenciada
   */
  id: number | string;

  /**
   * Etiqueta a mostrar (ej: "Animal 123", "Holstein", etc.)
   */
  label: string;

  /**
   * Servicio para obtener los detalles de la entidad
   */
  service: {
    getById: (id: number | string) => Promise<any>;
  };

  /**
   * Título del modal (ej: "Detalle del Animal")
   */
  modalTitle: string;

  /**
   * Función para renderizar el contenido del modal
   * Si no se proporciona, se usa un renderizado genérico
   */
  renderContent?: (data: any, helpers?: ForeignKeyLinkHelpers) => React.ReactNode;

  /**
   * Campos a mostrar en el renderizado genérico
   * Solo se usa si no se proporciona renderContent
   */
  fields?: Array<{
    key: string;
    label: string;
    render?: (value: any, item: any) => React.ReactNode;
  }>;

  /**
   * Clase CSS adicional para el link
   */
  className?: string;

  /**
   * Si debe mostrar el icono de enlace externo
   */
  showIcon?: boolean;

  /**
   * Tamaño del modal
   */
  size?: 'sm' | 'md' | 'lg' | 'xl' | '2xl' | '3xl' | '4xl' | '5xl' | '6xl' | '7xl' | 'full';

  /**
   * Habilitar botón de pantalla completa
   */
  enableFullScreenToggle?: boolean;

  /**
   * Gatillo personalizado para abrir el modal. Si se proporciona, ignora label/showIcon.
   */
  children?: React.ReactNode;
}

/**
 * Componente genérico para renderizar campos foráneos con un link clickeable
 * que abre un modal con los detalles de la entidad relacionada
 */
export const ForeignKeyLink: React.FC<ForeignKeyLinkProps> = ({
  id,
  label,
  service,
  modalTitle,
  renderContent,
  fields,
  className = '',
  showIcon = true,
  size = 'lg',
  enableFullScreenToggle = false,
  children
}) => {
  const [showModal, setShowModal] = useState(false);
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const loadData = async () => {
    setLoading(true);
    setError(null);
    try {
      const result = await service.getById(id);
      setData(result);
    } catch (err: any) {
      console.error('Error loading entity details:', err);
      setError(err?.message || 'Error al cargar los detalles');
    } finally {
      setLoading(false);
    }
  };

  const handleClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    setShowModal(true);
    if (!data) {
      loadData();
    }
  };

  const defaultRenderContent = (item: any) => {
    if (!fields || fields.length === 0) {
      // Renderizado muy básico si no hay fields definidos
      return (
        <div className="space-y-2">
          {Object.entries(item).map(([key, value]) => (
            <div key={key} className="flex justify-between border-b pb-2">
              <span className="font-medium text-muted-foreground capitalize">
                {key.replace(/_/g, ' ')}:
              </span>
              <span className="text-foreground">{String(value)}</span>
            </div>
          ))}
        </div>
      );
    }

    return (
      <Card className="shadow-sm">
        <CardHeader>
          <CardTitle>Información Detallada</CardTitle>
        </CardHeader>
        <CardContent>
          <dl className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">
            {fields.map((field) => {
              const value = item[field.key];
              const displayValue = field.render
                ? field.render(value, item)
                : value !== null && value !== undefined
                  ? String(value)
                  : '-';

              return (
                <div key={field.key}>
                  <dt className="text-muted-foreground">{field.label}</dt>
                  <dd className="font-medium">{displayValue}</dd>
                </div>
              );
            })}
          </dl>
        </CardContent>
      </Card>
    );
  };

  const renderModalContent = () => {
    const helpers: ForeignKeyLinkHelpers = {
      closeModal: () => setShowModal(false),
      reload: async () => { await loadData(); },
      setData: (value: any) => setData(value),
    };

    if (loading) {
      return (
        <div className="py-10 text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto mb-4"></div>
          <p className="text-muted-foreground">Cargando detalles...</p>
        </div>
      );
    }

    if (error) {
      return (
        <div className="py-10 text-center">
          <p className="text-destructive mb-4">{error}</p>
          <Button onClick={loadData} variant="outline" size="sm">
            Reintentar
          </Button>
        </div>
      );
    }

    if (!data) {
      return (
        <div className="py-10 text-center">
          <p className="text-muted-foreground">No se encontraron datos</p>
        </div>
      );
    }

    if (renderContent) {
      return renderContent(data, helpers);
    }

    return defaultRenderContent(data);
  };

  return (
    <>
      {children ? (
        <div onClick={handleClick} className={className}>
          {children}
        </div>
      ) : (
        <button
          onClick={handleClick}
          className={`inline-flex items-center gap-0.5 text-primary hover:text-primary/80 hover:underline transition-colors cursor-pointer font-medium text-[9px] ${className}`}
          title={`Click para ver detalles de ${label}`}
        >
          <span className="truncate">{label}</span>
          {showIcon && <ExternalLink className="h-2.5 w-2.5 flex-shrink-0" />}
        </button>
      )}

      <GenericModal
        isOpen={showModal}
        onOpenChange={setShowModal}
        title={modalTitle}
        description={`Información detallada de ${label}`}
        size={size}
        enableBackdropBlur
        allowFullScreenToggle={enableFullScreenToggle}
        className="bg-card/95 backdrop-blur-md text-card-foreground border-border/50"
      >
        {renderModalContent()}
      </GenericModal>
    </>
  );
};

/* eslint-disable react-refresh/only-export-components */
import React from 'react';
import { Alert, AlertDescription } from '@/shared/ui/alert';
import { Badge } from '@/shared/ui/badge';
import { AlertTriangle, CircleCheck, Info } from 'lucide-react';
import { cn } from '@/shared/ui/cn';

export interface ValidationRule {
  required?: boolean;
  minLength?: number;
  maxLength?: number;
  pattern?: RegExp;
  custom?: (value: any) => string | null;
  email?: boolean;
  phone?: boolean;
  numeric?: boolean;
  min?: number;
  max?: number;
}

export interface ValidationError {
  field: string;
  message: string;
  type: 'error' | 'warning' | 'info';
}

export interface FormValidationProps {
  errors: ValidationError[];
  className?: string;
  showSummary?: boolean;
}

// Utilidades de validación
export class FormValidator {
  static validateField(value: any, rules: ValidationRule, fieldName: string): ValidationError[] {
    const errors: ValidationError[] = [];
    
    // Validación requerido
    if (rules.required && (!value || value.toString().trim() === '')) {
      errors.push({
        field: fieldName,
        message: `${fieldName} es requerido`,
        type: 'error'
      });
      return errors; // Si es requerido y está vacío, no validar otras reglas
    }
    
    // Si el valor está vacío y no es requerido, no validar otras reglas
    if (!value || value.toString().trim() === '') {
      return errors;
    }
    
    const stringValue = value.toString();
    
    // Validación de longitud mínima
    if (rules.minLength && stringValue.length < rules.minLength) {
      errors.push({
        field: fieldName,
        message: `${fieldName} debe tener al menos ${rules.minLength} caracteres`,
        type: 'error'
      });
    }
    
    // Validación de longitud máxima
    if (rules.maxLength && stringValue.length > rules.maxLength) {
      errors.push({
        field: fieldName,
        message: `${fieldName} no puede tener más de ${rules.maxLength} caracteres`,
        type: 'error'
      });
    }
    
    // Validación de email
    if (rules.email) {
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(stringValue)) {
        errors.push({
          field: fieldName,
          message: `${fieldName} debe ser un email válido`,
          type: 'error'
        });
      }
    }
    
    // Validación de teléfono
    if (rules.phone) {
      const phoneRegex = /^[+]?[0-9\s\-(]{7,15}$/;
      if (!phoneRegex.test(stringValue)) {
        errors.push({
          field: fieldName,
          message: `${fieldName} debe ser un número de teléfono válido`,
          type: 'error'
        });
      }
    }
    
    // Validación numérica
    if (rules.numeric) {
      const numericValue = parseFloat(stringValue);
      if (isNaN(numericValue)) {
        errors.push({
          field: fieldName,
          message: `${fieldName} debe ser un número válido`,
          type: 'error'
        });
      } else {
        // Validación de valor mínimo
        if (rules.min !== undefined && numericValue < rules.min) {
          errors.push({
            field: fieldName,
            message: `${fieldName} debe ser mayor o igual a ${rules.min}`,
            type: 'error'
          });
        }
        
        // Validación de valor máximo
        if (rules.max !== undefined && numericValue > rules.max) {
          errors.push({
            field: fieldName,
            message: `${fieldName} debe ser menor o igual a ${rules.max}`,
            type: 'error'
          });
        }
      }
    }
    
    // Validación con patrón personalizado
    if (rules.pattern && !rules.pattern.test(stringValue)) {
      errors.push({
        field: fieldName,
        message: `${fieldName} no tiene el formato correcto`,
        type: 'error'
      });
    }
    
    // Validación personalizada
    if (rules.custom) {
      const customError = rules.custom(value);
      if (customError) {
        errors.push({
          field: fieldName,
          message: customError,
          type: 'error'
        });
      }
    }
    
    return errors;
  }
  
  static validateForm(data: { [key: string]: any }, rules: { [key: string]: ValidationRule }): ValidationError[] {
    const allErrors: ValidationError[] = [];
    
    Object.entries(rules).forEach(([fieldName, fieldRules]) => {
      const fieldValue = data[fieldName];
      const fieldErrors = this.validateField(fieldValue, fieldRules, fieldName);
      allErrors.push(...fieldErrors);
    });
    
    return allErrors;
  }
  
  static hasErrors(errors: ValidationError[]): boolean {
    return errors.some(error => error.type === 'error');
  }
  
  static getFieldErrors(errors: ValidationError[], fieldName: string): ValidationError[] {
    return errors.filter(error => error.field === fieldName);
  }
  
  static getErrorsByType(errors: ValidationError[], type: 'error' | 'warning' | 'info'): ValidationError[] {
    return errors.filter(error => error.type === type);
  }
}

// Componente para mostrar errores de validación
const FormValidation: React.FC<FormValidationProps> = ({ 
  errors, 
  className = "", 
  showSummary = true 
}) => {
  const errorsByType = {
    error: FormValidator.getErrorsByType(errors, 'error'),
    warning: FormValidator.getErrorsByType(errors, 'warning'),
    info: FormValidator.getErrorsByType(errors, 'info')
  };
  
  const getIcon = (type: 'error' | 'warning' | 'info') => {
    switch (type) {
      case 'error':
        return <AlertTriangle className="h-4 w-4" />;
      case 'warning':
        return <Info className="h-4 w-4" />;
      case 'info':
        return <CircleCheck className="h-4 w-4" />;
      default:
        return <AlertTriangle className="h-4 w-4" />;
    }
  };
  
  const getVariant = (type: 'error' | 'warning' | 'info') => {
    switch (type) {
      case 'error':
        return 'destructive';
      case 'warning':
        return 'default';
      case 'info':
        return 'default';
      default:
        return 'destructive';
    }
  };
  
  if (errors.length === 0) {
    return null;
  }
  
  return (
    <div className={cn("space-y-2", className)}>
      {showSummary && (
        <div className="flex items-center gap-2 mb-3">
          <span className="text-sm font-medium text-muted-foreground">
            Errores de validación:
          </span>
          {errorsByType.error.length > 0 && (
            <Badge variant="destructive" className="text-xs">
              {errorsByType.error.length} errores
            </Badge>
          )}
          {errorsByType.warning.length > 0 && (
            <Badge variant="secondary" className="text-xs">
              {errorsByType.warning.length} advertencias
            </Badge>
          )}
        </div>
      )}
      
      {Object.entries(errorsByType).map(([type, typeErrors]) => 
        typeErrors.map((error, index) => (
          <Alert key={`${type}-${index}`} variant={getVariant(error.type as any)}>
            {getIcon(error.type)}
            <AlertDescription className="ml-2">
              <span className="font-medium">{error.field}:</span> {error.message}
            </AlertDescription>
          </Alert>
        ))
      )}
    </div>
  );
};

// Hook personalizado para validación de formularios
export const useFormValidation = (initialData: any, rules: { [key: string]: ValidationRule }) => {
  const [data, setData] = React.useState(initialData);
  const [errors, setErrors] = React.useState<ValidationError[]>([]);
  const [touched, setTouched] = React.useState<{ [key: string]: boolean }>({});
  
  const validateField = React.useCallback((fieldName: string, value: any) => {
    const fieldRules = rules[fieldName];
    if (!fieldRules) return [];
    
    return FormValidator.validateField(value, fieldRules, fieldName);
  }, [rules]);
  
  const validateForm = React.useCallback(() => {
    const allErrors = FormValidator.validateForm(data, rules);
    setErrors(allErrors);
    return allErrors;
  }, [data, rules]);
  
  const updateField = React.useCallback((fieldName: string, value: any) => {
    setData((prev: any) => ({ ...prev, [fieldName]: value }));
    
    // Validar el campo si ya ha sido tocado
    if (touched[fieldName]) {
      const fieldErrors = validateField(fieldName, value);
      setErrors(prev => [
        ...prev.filter(error => error.field !== fieldName),
        ...fieldErrors
      ]);
    }
  }, [touched, validateField]);
  
  const touchField = React.useCallback((fieldName: string) => {
    setTouched(prev => ({ ...prev, [fieldName]: true }));
    
    // Validar el campo cuando se toca
    const fieldErrors = validateField(fieldName, data[fieldName]);
    setErrors(prev => [
      ...prev.filter(error => error.field !== fieldName),
      ...fieldErrors
    ]);
  }, [data, validateField]);
  
  const getFieldErrors = React.useCallback((fieldName: string) => {
    return FormValidator.getFieldErrors(errors, fieldName);
  }, [errors]);
  
  const hasFieldErrors = React.useCallback((fieldName: string) => {
    return getFieldErrors(fieldName).some(error => error.type === 'error');
  }, [getFieldErrors]);
  
  const isValid = React.useMemo(() => {
    return !FormValidator.hasErrors(errors);
  }, [errors]);
  
  const reset = React.useCallback(() => {
    setData(initialData);
    setErrors([]);
    setTouched({});
  }, [initialData]);
  
  return {
    data,
    errors,
    touched,
    isValid,
    updateField,
    touchField,
    validateForm,
    getFieldErrors,
    hasFieldErrors,
    reset
  };
};

export default FormValidation;

// Componente para mostrar errores de campo específico
export const FieldError: React.FC<{ 
  errors: ValidationError[]; 
  fieldName: string; 
  className?: string; 
}> = ({ errors, fieldName, className = "" }) => {
  const fieldErrors = FormValidator.getFieldErrors(errors, fieldName);
  
  if (fieldErrors.length === 0) {
    return null;
  }
  
  return (
    <div className={cn("mt-1 space-y-1", className)}>
      {fieldErrors.map((error, index) => (
        <p 
          key={index} 
          className={cn(
            "text-xs",
            error.type === 'error' ? 'text-destructive' : 
            error.type === 'warning' ? 'text-yellow-600' : 
            'text-blue-600'
          )}
        >
          {error.message}
        </p>
      ))}
    </div>
  );
};

// Reglas de validación predefinidas
export const ValidationRules = {
  required: { required: true },
  email: { required: true, email: true },
  phone: { required: true, phone: true },
  password: { required: true, minLength: 8 },
  identification: { required: true, numeric: true, minLength: 6 },
  name: { required: true, minLength: 2, maxLength: 100 },
  address: { required: true, minLength: 5, maxLength: 200 },
  weight: { required: true, numeric: true, min: 0 },
  capacity: { required: true, numeric: true, min: 1 },
  area: { required: true, numeric: true, min: 0.1 }
};

/* eslint-disable react-refresh/only-export-components */
import React from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/shared/ui/dialog';
import { VisuallyHidden } from '@radix-ui/react-visually-hidden';
import { cn } from '@/shared/ui/cn';
import { ChevronLeft, ChevronRight, X } from 'lucide-react';

// Interfaces y tipos
export type ModalSize = 'sm' | 'md' | 'lg' | 'xl' | '2xl' | '3xl' | '4xl' | '5xl' | '6xl' | '7xl' | 'full';

interface GenericModalProps {
  isOpen: boolean;
  onOpenChange?: (isOpen: boolean) => void;
  onClose?: () => void;
  title: React.ReactNode;
  children: React.ReactNode;
  className?: string;
  size?: ModalSize;
  enableBackdropBlur?: boolean;
  description?: string;
  disableAnimations?: boolean;
  draggable?: boolean;
  variant?: 'default' | 'compact';
  fullScreen?: boolean;
  allowFullScreenToggle?: boolean;
  onFullScreenChange?: (next: boolean) => void;
  footer?: React.ReactNode;
  // Navegación entre items
  enableNavigation?: boolean;
  onNavigatePrevious?: () => void;
  onNavigateNext?: () => void;
  hasPrevious?: boolean;
  hasNext?: boolean;
  zIndex?: number;
}

// Mapeo de tamaños a clases Tailwind
const sizeClasses: Record<ModalSize, string> = {
  sm: 'sm:max-w-sm',
  md: 'sm:max-w-md',
  lg: 'sm:max-w-lg',
  xl: 'sm:max-w-xl',
  '2xl': 'sm:max-w-3xl',
  '3xl': 'sm:max-w-4xl',
  '4xl': 'sm:max-w-5xl',
  '5xl': 'sm:max-w-6xl',
  '6xl': 'sm:max-w-7xl',
  '7xl': 'sm:max-w-[90vw]',
  full: 'sm:max-w-[95vw]',
};

/**
 * Componente GenericModal optimizado para rendimiento y accesibilidad.
 */
export const GenericModal: React.FC<GenericModalProps> = ({
  isOpen,
  onOpenChange,
  onClose,
  title,
  children,
  className,
  size = 'full',
  description,
  disableAnimations = false,
  draggable = false,
  variant = 'default',
  fullScreen = false,
  allowFullScreenToggle = false,
  onFullScreenChange,
  footer,
  enableNavigation = false,
  onNavigatePrevious,
  onNavigateNext,
  hasPrevious = false,
  hasNext = false,
  zIndex,
}) => {
  const overlayClasses = cn(
    'fixed inset-0 flex items-start justify-center px-4 py-6',
    'sm:px-6 sm:pt-8 lg:px-8',
    'bg-black/70 dark:bg-black/80',
    'backdrop-blur-[18px] motion-safe:transition-opacity motion-safe:duration-300 motion-safe:ease-out motion-reduce:transition-none'
  );

  // IDs estables para accesibilidad
  const titleId = React.useId();
  const descriptionId = React.useId();

  // Estados para drag & drop
  const [position, setPosition] = React.useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = React.useState(false);
  const [dragOffset, setDragOffset] = React.useState({ x: 0, y: 0 });
  const dialogRef = React.useRef<HTMLDivElement>(null);

  // Reset position when modal opens
  React.useEffect(() => {
    if (isOpen) {
      setPosition({ x: 0, y: 0 });
    }
  }, [isOpen]);

  const handleMouseDown = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!draggable || !dialogRef.current) return;

    const rect = dialogRef.current.getBoundingClientRect();
    setDragOffset({
      x: e.clientX - rect.left - position.x,
      y: e.clientY - rect.top - position.y,
    });
    setIsDragging(true);
  };

  React.useEffect(() => {
    if (!isDragging || !draggable) return;

    const handleMouseMove = (e: MouseEvent) => {
      if (!dialogRef.current) return;

      const rect = dialogRef.current.getBoundingClientRect();
      const newX = e.clientX - rect.left - dragOffset.x;
      const newY = e.clientY - rect.top - dragOffset.y;

      setPosition({ x: newX, y: newY });
    };

    const handleMouseUp = () => {
      setIsDragging(false);
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, dragOffset, draggable]);

  // Manejador de navegación por teclado
  React.useEffect(() => {
    if (!isOpen || !enableNavigation) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      // Solo manejar si el foco está dentro del modal o no hay input activo
      if (
        document.activeElement?.tagName === 'INPUT' ||
        document.activeElement?.tagName === 'TEXTAREA' ||
        document.activeElement?.tagName === 'SELECT' ||
        document.activeElement?.getAttribute('contenteditable') === 'true'
      ) return;

      if (e.key === 'ArrowLeft' && hasPrevious && onNavigatePrevious) {
        e.preventDefault();
        onNavigatePrevious();
      } else if (e.key === 'ArrowRight' && hasNext && onNavigateNext) {
        e.preventDefault();
        onNavigateNext();
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, enableNavigation, hasPrevious, hasNext, onNavigatePrevious, onNavigateNext]);

  const [fsInternal, setFsInternal] = React.useState<boolean>(fullScreen);
  React.useEffect(() => {
    setFsInternal(fullScreen);
  }, [fullScreen]);

  const computedFullScreen = allowFullScreenToggle ? fsInternal : fullScreen;

  const modalClasses = cn(
    'w-[95vw] sm:w-[90vw] md:w-[85vw] lg:w-[80vw] xl:w-[75vw]',
    'max-w-[500px] sm:max-w-[600px] md:max-w-[800px] lg:max-w-[1000px] xl:max-w-[1200px]',
    'h-auto',
    'max-h-[96vh] sm:max-h-[92vh]',
    'min-h-[200px]',
    '!flex !flex-col',
    'bg-white dark:bg-slate-900',
    'shadow-2xl shadow-black/20 dark:shadow-black/40',
    'rounded-t-2xl sm:rounded-2xl',
    'border border-border/50 dark:border-white/10',
    'backdrop-blur-sm',
    computedFullScreen && '!w-screen !max-w-none !h-dvh !max-h-none !min-h-0 !rounded-none !border-0',
    'vl-modal-surface text-foreground',
    '!p-0 !gap-0',
    !computedFullScreen && size !== 'full' && sizeClasses[size],
    !disableAnimations && 'transition-all duration-300 ease-out',
    variant === 'compact' && 'max-[360px]:text-xs',
    'max-sm:fixed max-sm:bottom-0 max-sm:rounded-b-none',
    className
  );

  return (
    <Dialog open={isOpen} onOpenChange={(open) => {
      if (onOpenChange) onOpenChange(open);
      if (!open && onClose) onClose();
    }}>
      <DialogContent
        zIndex={zIndex}
        ref={dialogRef}
        hideCloseButton
        className={cn(modalClasses)}
        overlayClassName={overlayClasses}
        style={{
          cursor: isDragging ? 'grabbing' : 'default',
          ...(draggable && { transform: `translate(${position.x}px, ${position.y}px)` }),
        }}
      >
        <DialogHeader
          className={cn(
            "relative bg-surface-secondary/70 backdrop-blur-lg border-b border-white/40 dark:border-white/10 shadow-sm",
            variant === 'compact'
              ? allowFullScreenToggle ? "px-4 sm:px-5 py-1.5 pr-16 sm:pr-20" : "px-4 sm:px-5 py-1.5 pr-10 sm:pr-11"
              : allowFullScreenToggle ? "px-5 sm:px-6 py-2 pr-16 sm:pr-20" : "px-5 sm:px-6 py-2 pr-10 sm:pr-11",
            draggable && "cursor-grab active:cursor-grabbing select-none"
          )}
          onMouseDown={handleMouseDown}
        >
          <div className="flex items-center gap-2 min-w-0">
            <DialogTitle
              id={titleId}
              className={cn(
                "text-sm sm:text-base font-semibold leading-none text-left text-foreground flex items-center gap-2 flex-1 min-w-0",
                !title && "sr-only"
              )}
            >
              {title ? (
                <>
                  <div className="flex-shrink-0 w-1 h-4 rounded-full bg-primary" />
                  <span className="flex-1 min-w-0 truncate">{title}</span>
                </>
              ) : (
                "Formulario"
              )}
            </DialogTitle>

            <DialogDescription
              id={descriptionId}
              className={cn(
                "sr-only",
                description && "not-sr-only text-[11px] sm:text-xs text-muted-foreground/90 leading-snug mt-1 ml-8 sm:ml-9"
              )}
            >
              {description || "Contenido del diálogo"}
            </DialogDescription>

            <div className="flex-shrink-0 flex items-center gap-1.5">
              {allowFullScreenToggle && (
                <button
                  type="button"
                  aria-label={fsInternal ? 'Salir de pantalla completa' : 'Pantalla completa'}
                  className="inline-flex items-center justify-center h-8 w-8 rounded-xl border border-border/40 bg-surface-tertiary text-text-secondary hover:text-primary hover:bg-state-hover shadow-sm transition-all duration-200 hover:scale-105 active:scale-95"
                  onClick={(e) => {
                    e.stopPropagation();
                    const next = !fsInternal;
                    setFsInternal(next);
                    onFullScreenChange?.(next);
                  }}
                >
                  {fsInternal ? (
                    <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M8 3H5a2 2 0 0 0-2 2v3" /><path d="M16 3h3a2 2 0 0 1 2 2v3" /><path d="M21 16v3a2 2 0 0 1-2 2h-3" /><path d="M3 16v3a2 2 0 0 0 2 2h3" /></svg>
                  ) : (
                    <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M3 3h7v7H3z" /><path d="M14 3h7v7h-7z" /><path d="M3 14h7v7H3z" /><path d="M14 14h7v7h-7z" /></svg>
                  )}
                </button>
              )}

              {/* Manual Close Button - High visibility for mobile and premium UX */}
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  if (onClose) onClose();
                  if (onOpenChange) onOpenChange(false);
                }}
                className="inline-flex items-center justify-center h-8 w-8 rounded-xl bg-destructive/10 text-destructive hover:bg-destructive hover:text-white shadow-sm transition-all duration-200 hover:scale-105 active:scale-95"
                aria-label="Cerrar modal"
              >
                <X className="h-5 w-5" />
              </button>
            </div>
          </div>

        </DialogHeader>

        <div
          tabIndex={0}
          className={cn(
            "overflow-x-hidden overflow-y-auto overscroll-contain focus:outline-none focus-visible:ring-2 focus-visible:ring-primary/20 flex-1 min-h-0",
            variant === 'compact' ? "px-3 sm:px-4 py-2" : "px-4 sm:px-5 py-3",
            variant === 'compact' && 'max-[360px]:text-xs'
          )}>
          {children}
        </div>

        {footer && (
          <div className="flex-shrink-0">
            {footer}
          </div>
        )}

        {enableNavigation && (
          <>
            {hasPrevious && onNavigatePrevious && (
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  onNavigatePrevious();
                }}
                aria-label="Anterior"
                className={cn(
                  "absolute left-2 sm:left-3 top-1/2 -translate-y-1/2 h-8 w-8 sm:h-9 sm:w-9 flex items-center justify-center rounded-full bg-background/[0.03] backdrop-blur-sm border border-primary/[0.05] text-foreground/10 hover:bg-background/80 hover:backdrop-blur-md hover:border-primary/30 hover:text-foreground hover:shadow-lg hover:scale-105 active:scale-95 transition-all duration-300 ease-in-out focus:outline-none focus:bg-background/80 focus:text-foreground focus:border-primary/30 z-10"
                )}
              >
                <ChevronLeft className="h-4 w-4 sm:h-5 sm:w-5" />
              </button>
            )}

            {hasNext && onNavigateNext && (
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  onNavigateNext();
                }}
                aria-label="Siguiente"
                className={cn(
                  "absolute right-2 sm:right-3 top-1/2 -translate-y-1/2 h-8 w-8 sm:h-9 sm:w-9 flex items-center justify-center rounded-full bg-background/[0.03] backdrop-blur-sm border border-primary/[0.05] text-foreground/10 hover:bg-background/80 hover:backdrop-blur-md hover:border-primary/30 hover:text-foreground hover:shadow-lg hover:scale-105 active:scale-95 transition-all duration-300 ease-in-out focus:outline-none focus:bg-background/80 focus:text-foreground focus:border-primary/30 z-10"
                )}
              >
                <ChevronRight className="h-4 w-4 sm:h-5 sm:w-5" />
              </button>
            )}
          </>
        )}
      </DialogContent>
    </Dialog>
  );
};

export const useUnifiedDisclosure = () => {
  const [isOpen, setIsOpen] = React.useState(false);
  return {
    isOpen,
    onOpen: () => setIsOpen(true),
    onClose: () => setIsOpen(false),
    onOpenChange: (open: boolean) => setIsOpen(open),
  } as const;
};

import React from 'react';
import { useOnlineStatus } from '@/shared/hooks/useOnlineStatus';
import { motion, AnimatePresence } from 'framer-motion';
import { WifiOff, RefreshCw, CircleAlert, CircleCheck, X } from 'lucide-react';
import { cn } from '@/shared/lib/utils';
import { offlineQueue } from '@/shared/api/offline/offlineQueue';

export const GlobalAlertBanner: React.FC = () => {
  const { isOnline, pendingOperations, syncStatus } = useOnlineStatus();
  const [isVisible, setIsVisible] = React.useState(true);

  // Determinar la alerta más importante
  const getAlert = () => {
    if (!isOnline) {
      return {
        id: 'offline',
        type: 'warning',
        icon: WifiOff,
        title: 'Modo Offline Activo',
        message: pendingOperations > 0 
          ? `Tienes ${pendingOperations} cambios guardados localmente. Se sincronizarán al recuperar conexión.`
          : 'Estás trabajando sin internet. Los cambios se guardarán en tu dispositivo.',
        color: 'bg-amber-500',
        textColor: 'text-amber-950',
        lightColor: 'bg-amber-50'
      };
    }

    if (syncStatus.failed > 0) {
      return {
        id: 'sync-failed',
        type: 'error',
        icon: CircleAlert,
        title: 'Error de Sincronización',
        message: `${syncStatus.failed} operaciones no se pudieron completar. Revisa tu conexión.`,
        color: 'bg-rose-500',
        textColor: 'text-rose-950',
        lightColor: 'bg-rose-50',
        action: {
          label: 'Reintentar',
          onClick: () => offlineQueue.retryFailedOperations()
        }
      };
    }

    if (syncStatus.syncing) {
      return {
        id: 'syncing',
        type: 'info',
        icon: RefreshCw,
        title: 'Sincronizando Datos',
        message: `Subiendo ${syncStatus.pending} cambios al servidor...`,
        color: 'bg-blue-500',
        textColor: 'text-blue-950',
        lightColor: 'bg-blue-50',
        isAnimating: true
      };
    }

    return null;
  };

  const alert = getAlert();

  if (!alert || !isVisible) return null;

  return (
    <AnimatePresence>
      <motion.div
        initial={{ height: 0, opacity: 0 }}
        animate={{ height: 'auto', opacity: 1 }}
        exit={{ height: 0, opacity: 0 }}
        className={cn(
          "relative overflow-hidden border-b transition-colors duration-500",
          alert.lightColor,
          "border-black/5 dark:border-white/5"
        )}
      >
        <div className="max-w-7xl mx-auto px-4 py-2.5 flex items-center gap-4">
          <div className={cn(
            "flex-shrink-0 p-2 rounded-xl text-white shadow-sm",
            alert.color
          )}>
            <alert.icon className={cn("h-4 w-4", alert.isAnimating && "animate-spin")} />
          </div>

          <div className="flex-1 min-w-0">
            <h4 className={cn("text-xs font-black uppercase tracking-widest", alert.textColor)}>
              {alert.title}
            </h4>
            <p className={cn("text-sm font-medium opacity-80 truncate", alert.textColor)}>
              {alert.message}
            </p>
          </div>

          <div className="flex items-center gap-2">
            {alert.action && (
              <button
                onClick={alert.action.onClick}
                className={cn(
                  "px-3 py-1 rounded-lg text-xs font-black uppercase tracking-tighter transition-all",
                  "bg-black/10 hover:bg-black/20",
                  alert.textColor
                )}
              >
                {alert.action.label}
              </button>
            )}

            <button
              onClick={() => setIsVisible(false)}
              className={cn(
                "p-1.5 rounded-lg transition-colors",
                "hover:bg-black/10",
                alert.textColor
              )}
            >
              <X className="h-4 w-4" />
            </button>
          </div>
        </div>

        {/* Barra de progreso sutil si está sincronizando */}
        {alert.isAnimating && (
          <motion.div 
            initial={{ scaleX: 0 }}
            animate={{ scaleX: 1 }}
            transition={{ duration: 2, repeat: Infinity }}
            className="absolute bottom-0 left-0 h-0.5 w-full bg-blue-600 origin-left opacity-30"
          />
        )}
      </motion.div>
    </AnimatePresence>
  );
};

import React, { useState, useCallback, useEffect } from 'react';
