  animalImageService,
  type AnimalImage,
} from '@/entities/animal/api/animalImage.service';
import { useToast } from '@/app/providers/ToastContext';
import {
  formatAnimalImageName,
  getAnimalImageId,
} from '@/entities/animal/lib/animalImageUtils';

const ALLOWED_IMAGE_EXTENSIONS = ['jpg', 'jpeg', 'png', 'webp', 'gif'];
const ALLOWED_IMAGE_MIME_TYPES = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];

interface ImageManagerProps {
  /** ID del animal asociado */
  animalId: number;
  /** Título para mostrar en el header */
  title?: string;
  /** Callback cuando se actualiza la galería */
  onGalleryUpdate?: () => void;
  /** Mostrar controles de edición */
  showControls?: boolean;
  /** Trigger externo para recargar las imágenes */
  refreshTrigger?: number;
  /** Altura del banner de imágenes */
  bannerHeight?: string;
  /** Modo compacto para integrar en modales */
  compact?: boolean;
  /** Permitir selección múltiple de imágenes */
  allowMultipleSelection?: boolean;
  /** Callback cuando se seleccionan imágenes */
  onSelectionChange?: (selectedImages: AnimalImage[]) => void;
  /** Imágenes iniciales para evitar fetch redundante */
  initialImages?: AnimalImage[];
}

interface FilePreview {
  file: File;
  preview: string;
  id: string;
}

export function ImageManager({
  animalId,
  title = 'Galería de Imágenes',
  onGalleryUpdate,
  showControls = true,
  refreshTrigger = 0,
  bannerHeight: _bannerHeight = "300px",
  compact = false,
  allowMultipleSelection = false,
  onSelectionChange,
  initialImages,
}: ImageManagerProps) {
  const { showToast } = useToast();
  const [images, setImages] = useState<AnimalImage[]>(initialImages || []);
  const [loading, setLoading] = useState(!initialImages);
  const [error, setError] = useState<string | null>(null);
  const [selectedImage, setSelectedImage] = useState<AnimalImage | null>(null);
  const [deletingId, setDeletingId] = useState<number | null>(null);
  const [settingPrimaryId, setSettingPrimaryId] = useState<number | null>(null);
  const [imageErrors, setImageErrors] = useState<Set<number>>(new Set());
  const selectedImageId = selectedImage ? getAnimalImageId(selectedImage) : null;
  const selectedImageHasError =
    selectedImageId !== null && imageErrors.has(selectedImageId);

  // Estados para la subida de imágenes
  const [showUpload, setShowUpload] = useState(false);
  const [files, setFiles] = useState<FilePreview[]>([]);
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [dragActive, setDragActive] = useState(false);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [uploadSuccess, setUploadSuccess] = useState<string | null>(null);

  // Estados para selección múltiple
  const [selectedImages, setSelectedImages] = useState<Set<number>>(new Set());

  const isImageFile = useCallback(
    (file: File) => {
      if (file.type) return ALLOWED_IMAGE_MIME_TYPES.includes(file.type);
      const ext = file.name.split('.').pop()?.toLowerCase();
      return ext ? ALLOWED_IMAGE_EXTENSIONS.includes(ext) : false;
    },
    []
  );
  const maxFileSize = 5 * 1024 * 1024; // 5MB
  const maxFiles = 10;

  // Cargar imágenes
  const fetchImages = useCallback(async () => {
    if (!animalId || animalId <= 0) {
      setError('ID de animal inválido');
      setLoading(false);
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const response = await animalImageService.getAnimalImages(animalId);

      if (response.success) {
        setImages(response.data.images || []);
      } else {
        setImages([]);
        if (response.errorCode !== 'NOT_FOUND') {
          setError(response.message || 'Error al cargar imágenes');
        }
      }
    } catch (err: any) {
      const status = err.response?.status;

      if (status === 404) {
        setImages([]);
        setError(null);
      } else {
        const errorMessage =
          err.response?.data?.message ||
          err.message ||
          'Error al cargar imágenes';
        setError(errorMessage);
      }
    } finally {
      setLoading(false);
    }
  }, [animalId]);

  // Cargar imágenes al montar y cuando cambie el trigger
  useEffect(() => {
    // Si ya tenemos imágenes iniciales, evitamos el primer fetch
    if (initialImages && refreshTrigger === 0) {
      setLoading(false);
      return;
    }
    fetchImages();
  }, [fetchImages, refreshTrigger, initialImages]);

  // Sync initialImages when they change
  useEffect(() => {
    if (initialImages) {
      setImages(initialImages);
      setLoading(false);
    }
  }, [initialImages]);

  // Escuchar evento global de actualización de imágenes
  useEffect(() => {
    const handler = (e: Event) => {
      const detail = (e as CustomEvent).detail as { animalId?: number; uploaded?: any[] } | undefined;
      if (!detail || detail.animalId === animalId) {
        setTimeout(fetchImages, 0);
        if (detail?.uploaded?.length) {
          setTimeout(fetchImages, 800);
          setTimeout(fetchImages, 1600);
        }
      }
    };
    window.addEventListener('animal-images:updated', handler as EventListener);
    return () => {
      window.removeEventListener('animal-images:updated', handler as EventListener);
    };
  }, [animalId, fetchImages]);

  // Validar archivo
  const validateFile = useCallback(
    (file: File): string | null => {
      if (!isImageFile(file)) {
        return `${file.name}: Solo se permiten JPG, JPEG, PNG, WEBP o GIF`;
      }

      if (file.size > maxFileSize) {
        return `${file.name}: El archivo excede el tamaño máximo de 5MB`;
      }

      return null;
    },
    [isImageFile, maxFileSize]
  );

  // Procesar archivos seleccionados
  const processFiles = useCallback(
    (selectedFiles: FileList | File[]) => {
      const fileArray = Array.from(selectedFiles);
      const validFiles: FilePreview[] = [];
      const errors: string[] = [];

      for (const file of fileArray) {
        const validationError = validateFile(file);
        if (validationError) {
          errors.push(validationError);
          continue;
        }

        // Verificar que no exceda el límite
        if (files.length + validFiles.length >= maxFiles) {
          errors.push(`Máximo ${maxFiles} imágenes permitidas`);
          break;
        }

        // Crear preview
        const preview = URL.createObjectURL(file);
        validFiles.push({
          file,
          preview,
          id: `${Date.now()}-${Math.random()}`,
        });
      }

      if (errors.length > 0) {
        setUploadError(errors.join('. '));
      } else {
        setUploadError(null);
      }

      if (validFiles.length > 0) {
        setFiles((prev) => [...prev, ...validFiles]);
        setUploadSuccess(null);
      }
    },
    [files.length, maxFiles, validateFile]
  );

  // Manejar drop
  const handleDrop = useCallback(
    (e: React.DragEvent<HTMLDivElement>) => {
      e.preventDefault();
      e.stopPropagation();
      setDragActive(false);

      if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
        processFiles(e.dataTransfer.files);
      }
    },
    [processFiles]
  );

  // Manejar drag over
  const handleDragOver = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(true);
  }, []);

  // Manejar drag leave
  const handleDragLeave = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
  }, []);

  // Manejar cambio de input
  const handleFileChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files.length > 0) {
        processFiles(e.target.files);
      }
    },
    [processFiles]
  );

  // Remover archivo
  const removeFile = useCallback((id: string) => {
    setFiles((prev) => {
      const fileToRemove = prev.find((f) => f.id === id);
      if (fileToRemove) {
        URL.revokeObjectURL(fileToRemove.preview);
      }
      return prev.filter((f) => f.id !== id);
    });
    setUploadError(null);
    setUploadSuccess(null);
  }, []);

  // Limpiar previews al desmontar
  useEffect(() => {
    return () => {
      files.forEach((f) => URL.revokeObjectURL(f.preview));
    };
  }, [files]);

  // Establecer imagen principal
  const handleSetPrimary = useCallback(
    async (imageId: number) => {
      setSettingPrimaryId(imageId);
      setError(null);

      try {
        await animalImageService.setPrimaryImage(imageId);

        // Actualizar estado local
        setImages((prev) =>
          prev.map((img) => ({
            ...img,
            is_primary: img.id === imageId,
          }))
        );

        if (onGalleryUpdate) {
          onGalleryUpdate();
        }

        showToast('Imagen principal establecida correctamente', 'success');
      } catch (err: any) {
        const errorMessage =
          err.response?.data?.message ||
          err.message ||
          'Error al establecer imagen principal';
        setError(errorMessage);
        showToast(errorMessage, 'error');
      } finally {
        setSettingPrimaryId(null);
      }
    },
    [onGalleryUpdate, showToast]
  );

  // Eliminar imagen
  const handleDelete = useCallback(
    async (image: AnimalImage) => {
      const imageId = getAnimalImageId(image);
      if (imageId === null) {
        const fallbackMessage = 'No se encontró un identificador válido para esta imagen.';
        setError(fallbackMessage);
        showToast(fallbackMessage, 'error');
        return;
      }

      const label = formatAnimalImageName(image);
      if (!confirm(`¿Está seguro de eliminar ${label}?`)) {
        return;
      }

      setDeletingId(imageId);
      setError(null);

      try {
        await animalImageService.deleteImage(imageId);

        // Actualizar estado local (aunque el backend ya no tenga la imagen)
        setImages((prev) =>
          prev.filter((img) => getAnimalImageId(img) !== imageId)
        );

        if (onGalleryUpdate) {
          onGalleryUpdate();
        }

        showToast('Imagen eliminada correctamente', 'success');

        setTimeout(() => {
          window.dispatchEvent(
            new CustomEvent('animal-images:updated', { detail: { animalId } })
          );
        }, 0);
      } catch (err: any) {
        const status = err?.response?.status;
        const defaultMessage = 'No se pudo eliminar la imagen. Intenta nuevamente.';
        const errorMessage = err?.message || err?.response?.data?.message || defaultMessage;

        if (err?.code === 'AUTH_REQUIRED') {
          const authMessage =
            errorMessage ||
            'Tu sesión expiró. Vuelve a iniciar sesión para administrar las imágenes.';
          setError(authMessage);
          showToast(authMessage, 'error');
        } else {
          setError(errorMessage);
          // Si el backend respondió con 5xx o 401 (sin código custom), mostrar mensaje amigable
          if (status && status >= 500) {
            showToast('El servidor no pudo eliminar la imagen en este momento.', 'error');
          } else {
            showToast(errorMessage, 'error');
          }
        }
      } finally {
        setDeletingId(null);
      }
    },
    [animalId, onGalleryUpdate, showToast]
  );

  // Descargar imagen
  const handleDownload = useCallback((image: AnimalImage) => {
    const link = document.createElement('a');
    link.href = image.url;
    link.download = image.filename;
    link.target = '_blank';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }, []);

  // Subir imágenes
  const handleUpload = useCallback(async () => {
    if (files.length === 0) {
      setUploadError('Debe seleccionar al menos una imagen');
      return;
    }

    setUploading(true);
    setUploadProgress(0);
    setUploadError(null);
    setUploadSuccess(null);

    try {
      // Optimizar imágenes antes de subir (Reducción de ancho de banda)
      const { optimizeImage } = await import('@/shared/lib/imageOptimizer');
      
      const optimizedFiles = await Promise.all(
        files.map(async (f) => {
          try {
            return await optimizeImage(f.file);
          } catch (e) {
            console.warn('Error optimizando imagen, usando original:', e);
            return f.file;
          }
        })
      );

      const response = await animalImageService.uploadImages(
        animalId,
        optimizedFiles,
        {
          onProgress: (progress) => {
            setUploadProgress(progress);
          },
        }
      );

      if (response.success) {
        setUploadSuccess(
          `${response.data.total_uploaded} imagen(es) subida(s) exitosamente`
        );

        // Limpiar archivos
        files.forEach((f) => URL.revokeObjectURL(f.preview));
        setFiles([]);
        setUploadProgress(0);

        // Callback de éxito
        if (onGalleryUpdate) {
          onGalleryUpdate();
        }

        // Mostrar toast de confirmación
        showToast(
          `✅ ${response.data.total_uploaded} imagen(es) subida(s) correctamente`,
          'success'
        );
        // Despachar evento global para que cualquier galer¡a o banner se refresque
        try {
          const detail = { animalId, uploaded: response.data.uploaded };
          window.dispatchEvent(new CustomEvent('animal-images:updated', { detail }));
          setTimeout(() => {
            window.dispatchEvent(new CustomEvent('animal-images:updated', { detail }));
          }, 800);
        } catch (error) {
          if (process.env.NODE_ENV !== 'production') {
            console.warn('[ImageManager] Error emitiendo evento de actualizaci¢n', error);
          }
        }
      } else {
        throw new Error(response.message || 'Error al subir imágenes');
      }
    } catch (err: any) {
      const errorMessage = err.message || 'Error al subir imágenes';
      setUploadError(errorMessage);

      // Mostrar toast de error
      showToast(`❌ ${errorMessage}`, 'error');
    } finally {
      setUploading(false);
    }
  }, [files, animalId, onGalleryUpdate, showToast]);

  // Manejar selección de imágenes
  const handleImageSelect = useCallback((image: AnimalImage, isSelected: boolean) => {
    if (!allowMultipleSelection) return;
    const imageId = getAnimalImageId(image);
    if (imageId === null) return;

    setSelectedImages((prev) => {
      const newSet = new Set(prev);
      if (isSelected) {
        newSet.add(imageId);
      } else {
        newSet.delete(imageId);
      }
      return newSet;
    });
  }, [allowMultipleSelection]);

  // Notificar cambios en la selección
  useEffect(() => {
    if (onSelectionChange && allowMultipleSelection) {
      const selectedImagesList = images.filter((img) => {
        const imgId = getAnimalImageId(img);
        return imgId !== null && selectedImages.has(imgId);
      });
      onSelectionChange(selectedImagesList);
    }
  }, [selectedImages, images, onSelectionChange, allowMultipleSelection]);

  // Loading state
  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="text-center space-y-3">
          <Loader2 className="w-8 h-8 animate-spin mx-auto text-primary" />
          <p className="text-sm text-muted-foreground">Cargando imágenes...</p>
        </div>
      </div>
    );
  }

  // Error state
  if (error && images.length === 0) {
    return (
      <Alert variant="destructive">
        <CircleAlert className="h-4 w-4" />
        <AlertDescription>{error}</AlertDescription>
      </Alert>
    );
  }

  return (
    <div className={`space-y-4 ${compact ? 'space-y-3' : ''}`}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-semibold">{title}</h3>
        <div className="flex items-center gap-2">
          <Badge variant="secondary" className="text-xs">
            {images.length} imagen(es)
          </Badge>
          {showControls && (
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={() => setShowUpload(!showUpload)}
              className="flex items-center gap-2"
            >
              <Upload className="w-4 h-4" />
              {showUpload ? 'Cancelar' : 'Subir'}
            </Button>
          )}
        </div>
      </div>

      {/* Sistema de carga de imágenes */}
      {showUpload && (
        <div className="bg-card rounded-lg p-4 border shadow-sm">
          <div className="flex items-center justify-between mb-3">
            <h4 className="text-sm font-bold">Cargar imágenes</h4>
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={() => setShowUpload(false)}
            >
              <X className="w-4 h-4" />
            </Button>
          </div>

          {/* Zona de drop */}
          <div
            className={`relative border-2 border-dashed rounded-xl p-8 transition-all ${dragActive
              ? 'border-primary bg-primary/5 scale-[1.02]'
              : 'border-border hover:border-primary/50 hover:bg-accent/5'
              } ${uploading ? 'opacity-50 pointer-events-none' : ''}`}
            onDrop={handleDrop}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
          >
            <input
              type="file"
              multiple
              accept=".jpg,.jpeg,.png,.webp,.gif"
              onChange={handleFileChange}
              className="hidden"
              disabled={uploading}
            />

            <div className="flex flex-col items-center justify-center gap-4 text-center">
              <div
                className={`p-4 rounded-full transition-colors ${dragActive ? 'bg-primary text-primary-foreground' : 'bg-accent'
                  }`}
              >
                <Upload className="w-8 h-8" />
              </div>

              <div>
                <p className="text-lg font-medium mb-1">
                  {dragActive
                    ? 'Suelta las imágenes aquí'
                    : 'Arrastra y suelta imágenes aquí'}
                </p>
                <p className="text-sm text-muted-foreground mb-4">
                  o haz clic para seleccionar archivos
                </p>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => (document.querySelector('input[type="file"]') as HTMLElement)?.click()}
                  disabled={uploading}
                >
                  <ImageIcon className="w-4 h-4 mr-2" />
                  Seleccionar Imágenes
                </Button>
              </div>

              <p className="text-xs text-muted-foreground">
                JPG, PNG, WEBP, GIF - Máximo 5MB por archivo - Hasta {maxFiles}{' '}
                imágenes
              </p>
            </div>
          </div>

          {/* Preview de archivos seleccionados */}
          {files.length > 0 && (
            <div className="mt-4 space-y-3">
              <div className="flex items-center justify-between">
                <p className="text-sm font-medium">
                  {files.length} imagen(es) seleccionada(s)
                </p>
                {!uploading && (
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={() => {
                      files.forEach((f) => URL.revokeObjectURL(f.preview));
                      setFiles([]);
                      setUploadError(null);
                    }}
                  >
                    Limpiar todo
                  </Button>
                )}
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
                {files.map((filePreview) => (
                  <div
                    key={filePreview.id}
                    className="relative group aspect-square rounded-lg overflow-hidden border bg-accent/5"
                  >
                    <img
                      src={filePreview.preview}
                      alt={filePreview.file.name}
                      className="w-full h-full object-cover"
                    />
                    <div className="absolute inset-0 bg-black/0 group-hover:bg-black/60 transition-colors flex items-center justify-center">
                      {!uploading && (
                        <Button
                          type="button"
                          variant="destructive"
                          size="icon"
                          className="opacity-0 group-hover:opacity-100 transition-opacity"
                          onClick={() => removeFile(filePreview.id)}
                        >
                          <X className="w-4 h-4" />
                        </Button>
                      )}
                    </div>
                    <div className="absolute bottom-0 left-0 right-0 p-2 bg-gradient-to-t from-black/80 to-transparent">
                      <p className="text-xs text-white truncate">
                        {filePreview.file.name}
                      </p>
                      <p className="text-xs text-white/70">
                        {(filePreview.file.size / 1024).toFixed(0)} KB
                      </p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Progreso de subida */}
          {uploading && (
            <div className="mt-4 space-y-2">
              <div className="flex items-center justify-between text-sm">
                <span>Subiendo imágenes...</span>
                <span className="font-medium">{uploadProgress}%</span>
              </div>
              <Progress value={uploadProgress} className="h-2" />
            </div>
          )}

          {/* Mensajes de error */}
          {uploadError && (
            <Alert variant="destructive">
              <CircleAlert className="h-4 w-4" />
              <AlertDescription>{uploadError}</AlertDescription>
            </Alert>
          )}

          {/* Mensajes de éxito */}
          {uploadSuccess && (
            <Alert className="border-green-500 bg-green-500/10">
              <CircleAlert className="h-4 w-4 text-green-500" />
              <AlertDescription className="text-green-700 dark:text-green-400">
                {uploadSuccess}
              </AlertDescription>
            </Alert>
          )}

          {/* Botón de subida */}
          {files.length > 0 && !uploading && (
            <div className="flex justify-end gap-2 mt-4">
              <Button
                type="button"
                variant="outline"
                onClick={() => {
                  files.forEach((f) => URL.revokeObjectURL(f.preview));
                  setFiles([]);
                  setUploadError(null);
                  setUploadSuccess(null);
                }}
              >
                Cancelar
              </Button>
              <Button type="button" onClick={handleUpload}>
                <Upload className="w-4 h-4 mr-2" />
                Subir {files.length} Imagen(es)
              </Button>
            </div>
          )}
        </div>
      )}

      {/* Galería de imágenes */}
      {images.length === 0 && !showUpload ? (
        <div className="flex justify-center py-8">
          <Button
            type="button"
            variant="outline"
            size="lg"
            onClick={() => setShowUpload(true)}
            className="flex items-center gap-2 px-6 py-3 border-2 border-dashed hover:border-primary hover:bg-primary/5 transition-all rounded-lg"
          >
            <ImageIcon className="w-5 h-5" />
            Cargar nuevas imágenes
          </Button>
        </div>
      ) : (
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
          {images.map((image, index) => {
            const numericId = getAnimalImageId(image);
            const key =
              numericId !== null ? `manager-image-${numericId}` : `manager-image-${index}`;
            const isSelected =
              allowMultipleSelection && numericId !== null && selectedImages.has(numericId);
            const hasError = numericId !== null && imageErrors.has(numericId);
            const isDeleting = numericId !== null && deletingId === numericId;
            const isSettingPrimary = numericId !== null && settingPrimaryId === numericId;

            return (
              <div
                key={key}
                className={`relative group aspect-square rounded-lg overflow-hidden border bg-accent/5 hover:shadow-lg transition-all ${isSelected ? 'ring-2 ring-primary' : ''
                  }`}
              >
                {/* Checkbox para selección múltiple */}
                {allowMultipleSelection && (
                  <div className="absolute top-2 left-2 z-10">
                    <input
                      type="checkbox"
                      checked={isSelected}
                      onChange={(e) => handleImageSelect(image, e.target.checked)}
                      className="w-4 h-4 rounded border-2 border-primary/50"
                      disabled={numericId === null}
                    />
                  </div>
                )}

                {/* Imagen */}
                {hasError ? (
                  <div className="w-full h-full flex items-center justify-center bg-muted/20 cursor-pointer" onClick={() => setSelectedImage(image)}>
                    <div className="text-center">
                      <ImageIcon className="w-8 h-8 mx-auto text-muted-foreground mb-1" />
                      <p className="text-xs text-muted-foreground">Error</p>
                    </div>
                  </div>
                ) : (
                  <img
                    src={image.url}
                    alt={image.filename}
                    className="w-full h-full object-cover cursor-pointer transition-transform duration-300 hover:scale-110"
                    onClick={() => setSelectedImage(image)}
                    loading="lazy"
                    style={{
                      imageRendering: 'auto',
                    }}
                    onError={() => {
                      if (numericId !== null) {
                        setImageErrors((prev) => {
                          const next = new Set(prev);
                          next.add(numericId);
                          return next;
                        });
                      }
                    }}
                  />
                )}

                {/* Badge de imagen principal */}
                {image.is_primary && (
                  <div className="absolute top-2 right-2">
                    <Badge className="bg-yellow-500 hover:bg-yellow-600 text-white">
                      <Star className="w-3 h-3 mr-1 fill-current" />
                      Principal
                    </Badge>
                  </div>
                )}

                {/* Botón de ver imagen */}
                <div
                  className="absolute inset-0 bg-black/0 group-hover:bg-black/40 transition-colors flex items-center justify-center cursor-pointer"
                  onClick={() => setSelectedImage(image)}
                >
                  <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                    <Button
                      type="button"
                      variant="secondary"
                      size="icon"
                      className="h-9 w-9 bg-white/90 hover:bg-white text-black rounded-full shadow-lg"
                      title="Ver en grande"
                      onClick={(e) => {
                        e.stopPropagation();
                        setSelectedImage(image);
                      }}
                    >
                      <ZoomIn className="w-5 h-5" />
                    </Button>

                    {showControls && (
                      <Button
                        type="button"
                        variant="destructive"
                        size="icon"
                        className="h-9 w-9 bg-red-500/90 hover:bg-red-600 text-white rounded-full shadow-lg"
                        title="Eliminar imagen"
                        disabled={isDeleting}
                        onClick={(e) => {
                          e.stopPropagation();
                          handleDelete(image);
                        }}
                      >
                        {isDeleting ? (
                          <Loader2 className="w-4 h-4 animate-spin" />
                        ) : (
                          <Trash2 className="w-5 h-5" />
                        )}
                      </Button>
                    )}
                  </div>
                </div>

                {/* Menú desplegable de acciones */}
                {showControls && (
                  <div className="absolute top-2 right-2 z-10">
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button
                          type="button"
                          variant="secondary"
                          size="icon"
                          className="h-8 w-8 opacity-0 group-hover:opacity-100 transition-opacity shadow-lg"
                          onClick={(e) => e.stopPropagation()}
                        >
                          <MoreVertical className="w-4 h-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end" className="w-48">
                        <DropdownMenuItem
                          onClick={(e) => {
                            e.stopPropagation();
                            setSelectedImage(image);
                          }}
                        >
                          <ZoomIn className="w-4 h-4 mr-2" />
                          Ver en grande
                        </DropdownMenuItem>

                        <DropdownMenuItem
                          onClick={(e) => {
                            e.stopPropagation();
                            handleDownload(image);
                          }}
                        >
                          <Download className="w-4 h-4 mr-2" />
                          Descargar
                        </DropdownMenuItem>

                        {!image.is_primary && (
                          <>
                            <DropdownMenuSeparator />
                            <DropdownMenuItem
                              onClick={(e) => {
                                e.stopPropagation();
                                if (numericId !== null) {
                                  handleSetPrimary(numericId);
                                }
                              }}
                              disabled={isSettingPrimary}
                            >
                              {isSettingPrimary ? (
                                <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                              ) : (
                                <Star className="w-4 h-4 mr-2" />
                              )}
                              Establecer como principal
                            </DropdownMenuItem>
                          </>
                        )}

                        <DropdownMenuSeparator />
                        <DropdownMenuItem
                          onClick={(e) => {
                            e.stopPropagation();
                            handleDelete(image);
                          }}
                          disabled={isDeleting}
                          className="text-destructive focus:text-destructive"
                        >
                          {isDeleting ? (
                            <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                          ) : (
                            <Trash2 className="w-4 h-4 mr-2" />
                          )}
                          Eliminar
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </div>
                )}

                {/* Info del archivo */}
                <div className="absolute bottom-0 left-0 right-0 p-2 bg-gradient-to-t from-black/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity">
                  <p className="text-xs text-white truncate" title={image.filename}>
                    {image.filename}
                  </p>
                  <p className="text-xs text-white/70">
                    {(image.file_size / 1024).toFixed(0)} KB
                  </p>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Modal de vista previa - pantalla completa */}
      <Dialog
        open={selectedImage !== null}
        onOpenChange={(open) => !open && setSelectedImage(null)}
      >
        <DialogContent className="max-w-[100vw] max-h-[100vh] w-screen h-screen p-0 bg-black border-none overflow-hidden rounded-none m-0 fixed inset-0">
          <DialogHeader className="sr-only">
            <DialogTitle className="flex items-center gap-2">
              {selectedImage?.is_primary && (
                <Star className="w-5 h-5 text-yellow-500 fill-current" />
              )}
              {selectedImage?.filename}
            </DialogTitle>
            <DialogDescription>
              {selectedImage &&
                `${(selectedImage.file_size / 1024).toFixed(2)} KB - ${selectedImage.mime_type
                } - Subida el ${new Date(
                  selectedImage.created_at
                ).toLocaleDateString('es-ES')}`}
            </DialogDescription>
          </DialogHeader>

          {selectedImage && (
            <div className="absolute inset-0 w-full h-full flex items-center justify-center overflow-hidden bg-black group">
              {/* Imagen a pantalla completa */}
              {selectedImageHasError ? (
                <div className="w-full h-full flex items-center justify-center">
                  <div className="text-center">
                    <ImageIcon className="w-16 h-16 mx-auto text-muted-foreground mb-2" />
                    <p className="text-sm text-muted-foreground">No se pudo cargar la imagen</p>
                  </div>
                </div>
              ) : (
                <img
                  src={selectedImage.url}
                  alt={selectedImage.filename}
                  className="w-full h-full"
                  style={{
                    objectFit: 'contain',
                    objectPosition: 'center',
                    imageRendering: '-webkit-optimize-contrast',
                    WebkitFontSmoothing: 'antialiased',
                    MozOsxFontSmoothing: 'grayscale',
                    backfaceVisibility: 'hidden',
                    transform: 'translateZ(0)',
                    willChange: 'transform',
                    maxWidth: '100%',
                    maxHeight: '100%',
                    width: 'auto',
                    height: 'auto',
                  }}
                  decoding="async"
                  fetchPriority="high"
                  onError={() => {
                    if (selectedImageId !== null) {
                      setImageErrors((prev) => {
                        const next = new Set(prev);
                        next.add(selectedImageId);
                        return next;
                      });
                    }
                  }}
                />
              )}

              {/* Información de la imagen - aparece solo en hover */}
              <div className="absolute bottom-4 left-0 right-0 flex justify-center z-10 opacity-0 group-hover:opacity-100 transition-opacity duration-300 group-hover:opacity-100">
                <div className="bg-black/80 backdrop-blur-md text-white px-6 py-3 rounded-full text-sm font-medium shadow-2xl border border-white/10">
                  {selectedImage.filename} • {(selectedImage.file_size / 1024).toFixed(0)} KB • {selectedImage.mime_type}
                  {selectedImage.is_primary && (
                    <span className="ml-2 text-yellow-400">⭐ Principal</span>
                  )}
                </div>
              </div>

              {/* Controles de acción - barra inferior */}
              <div className="absolute bottom-4 left-0 right-0 flex justify-center z-20 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                <div className="flex items-center gap-2 bg-black/80 backdrop-blur-md px-4 py-2 rounded-full shadow-2xl border border-white/10">
                  <Button
                    variant="ghost"
                    size="icon"
                    className="h-10 w-10 text-white hover:bg-white/20 hover:text-white rounded-full"
                    onClick={() => handleDownload(selectedImage)}
                    title="Descargar"
                  >
                    <Download className="h-5 w-5" />
                  </Button>

                  {showControls && !selectedImage.is_primary && (
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-10 w-10 text-white hover:bg-white/20 hover:text-yellow-400 rounded-full"
                      onClick={() => {
                        if (selectedImageId !== null) {
                          handleSetPrimary(selectedImageId);
                        }
                      }}
                      disabled={selectedImageId !== null && settingPrimaryId === selectedImageId}
                      title="Establecer como principal"
                    >
                      {selectedImageId !== null && settingPrimaryId === selectedImageId ? (
                        <Loader2 className="h-5 w-5 animate-spin" />
                      ) : (
                        <Star className="h-5 w-5" />
                      )}
                    </Button>
                  )}

                  {showControls && <div className="w-px h-6 bg-white/20 mx-1" />}

                  {showControls && (
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-10 w-10 text-white hover:bg-red-500/20 hover:text-red-400 rounded-full"
                      onClick={() => {
                        // Confirmación adicional para seguridad en pantalla completa
                        handleDelete(selectedImage);
                        // Cerrar modal si se elimina (esto ocurrirá automáticamnete si la imagen desaparece de la lista, pero por UX es mejor cerrarlo explícitamente o manejarlo)
                        // Nota: handleDelete actualiza el estado 'images' filtrando la eliminada. 
                        // Si la imagen seleccionada ya no está en 'images', el modal debería cerrarse o mostrar error.
                        // Vamos a dejar que el effect o la UI reactiva maneje el cierre, o forzarlo si es necesario.
                        // Dado que 'selectedImage' es un objeto independiente, si la eliminamos de 'images', 
                        // 'selectedImage' seguiría existiendo en el estado local del modal a menos que lo limpiemos.
                        // Sin embargo, handleDelete es async.
                      }}
                      disabled={selectedImageId !== null && deletingId === selectedImageId}
                      title="Eliminar imagen"
                    >
                      {selectedImageId !== null && deletingId === selectedImageId ? (
                        <Loader2 className="h-5 w-5 animate-spin" />
                      ) : (
                        <Trash2 className="h-5 w-5" />
                      )}
                    </Button>
                  )}
                </div>
              </div>

              {/* Botón Cerrar (X) - Superior derecha */}
              <div className="absolute top-4 right-4 z-20 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-10 w-10 rounded-full bg-black/50 text-white hover:bg-red-500 hover:text-white backdrop-blur-sm border border-white/10"
                  onClick={() => setSelectedImage(null)}
                  title="Cerrar (ESC)"
                >
                  <X className="h-5 w-5" />
                </Button>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React from 'react';
import { useOnlineStatus } from '@/shared/hooks/useOnlineStatus';
import { cn } from '@/shared/ui/cn';
import { Wifi, WifiOff, RefreshCw, AlertTriangle, CircleCheck, Cloud } from 'lucide-react';
import { offlineQueue } from '@/shared/api/offline/offlineQueue';

export const OnlineStatusIndicator: React.FC = () => {
  const { isOnline, wasOffline, pendingOperations, syncStatus } = useOnlineStatus();
  const [isExpanded, setIsExpanded] = React.useState(false);

  // Mostrar automáticamente cuando hay cambios importantes
  React.useEffect(() => {
    if (!isOnline || pendingOperations > 0 || syncStatus.failed > 0) {
      setIsExpanded(true);
      // Auto-colapsar después de 10 segundos si está todo bien
      if (isOnline && pendingOperations === 0 && syncStatus.failed === 0) {
        const timer = setTimeout(() => setIsExpanded(false), 10000);
        return () => clearTimeout(timer);
      }
    }
  }, [isOnline, pendingOperations, syncStatus.failed]);

  const handleRetryFailed = async () => {
    await offlineQueue.retryFailedOperations();
  };

  const handleClearFailed = () => {
    offlineQueue.clearFailedOperations();
  };

  // Estado principal del indicador
  const getStatus = () => {
    if (!isOnline) {
      return {
        icon: WifiOff,
        color: 'text-orange-600 dark:text-orange-400',
        bgColor: 'bg-orange-100 dark:bg-orange-900/30',
        borderColor: 'border-orange-300 dark:border-orange-700',
        label: 'Sin conexión',
        description: pendingOperations > 0
          ? `${pendingOperations} operación(es) pendiente(s) de sincronizar`
          : 'Trabajando offline - Los cambios se sincronizarán automáticamente'
      };
    }

    if (syncStatus.syncing) {
      return {
        icon: RefreshCw,
        color: 'text-blue-600 dark:text-blue-400',
        bgColor: 'bg-blue-100 dark:bg-blue-900/30',
        borderColor: 'border-blue-300 dark:border-blue-700',
        label: 'Sincronizando...',
        description: `Sincronizando ${syncStatus.pending} operación(es)`
      };
    }

    if (syncStatus.failed > 0) {
      return {
        icon: AlertTriangle,
        color: 'text-red-600 dark:text-red-400',
        bgColor: 'bg-red-100 dark:bg-red-900/30',
        borderColor: 'border-red-300 dark:border-red-700',
        label: 'Error de sincronización',
        description: `${syncStatus.failed} operación(es) fallida(s)`
      };
    }

    if (wasOffline && pendingOperations === 0) {
      return {
        icon: CircleCheck,
        color: 'text-green-600 dark:text-green-400',
        bgColor: 'bg-green-100 dark:bg-green-900/30',
        borderColor: 'border-green-300 dark:border-green-700',
        label: 'Sincronizado',
        description: 'Todas las operaciones pendientes se sincronizaron correctamente'
      };
    }

    if (pendingOperations > 0) {
      return {
        icon: Cloud,
        color: 'text-blue-600 dark:text-blue-400',
        bgColor: 'bg-blue-100 dark:bg-blue-900/30',
        borderColor: 'border-blue-300 dark:border-blue-700',
        label: 'Pendiente',
        description: `${pendingOperations} operación(es) esperando sincronización`
      };
    }

    // Todo bien, online sin operaciones pendientes
    return {
      icon: Wifi,
      color: 'text-green-600 dark:text-green-400',
      bgColor: 'bg-green-100 dark:bg-green-900/30',
      borderColor: 'border-green-300 dark:border-green-700',
      label: 'En línea',
      description: 'Conectado y sincronizado'
    };
  };

  const status = getStatus();
  const StatusIcon = status.icon;

  // No mostrar si está todo perfecto y colapsado
  if (isOnline && pendingOperations === 0 && syncStatus.failed === 0 && !wasOffline && !isExpanded) {
    return null;
  }

  return (
    <div className="fixed bottom-4 right-4 z-50 max-w-sm">
      <div
        className={cn(
          "rounded-lg border-2 shadow-lg backdrop-blur-sm transition-all duration-300",
          status.bgColor,
          status.borderColor,
          isExpanded ? "p-4" : "p-2"
        )}
      >
        {/* Header - siempre visible */}
        <button
          onClick={() => setIsExpanded(!isExpanded)}
          className="flex items-center gap-2 w-full text-left"
        >
          <StatusIcon
            className={cn(
              "h-5 w-5 flex-shrink-0",
              status.color,
              syncStatus.syncing && "animate-spin"
            )}
          />
          <div className="flex-1 min-w-0">
            <p className={cn("text-sm font-semibold truncate", status.color)}>
              {status.label}
            </p>
          </div>
          {pendingOperations > 0 && (
            <span className={cn(
              "px-2 py-0.5 rounded-full text-xs font-bold",
              "bg-white/50 dark:bg-black/20",
              status.color
            )}>
              {pendingOperations}
            </span>
          )}
        </button>

        {/* Contenido expandido */}
        {isExpanded && (
          <div className="mt-3 space-y-3">
            <p className="text-xs text-muted-foreground">
              {status.description}
            </p>

            {/* Detalles de sincronización */}
            {(syncStatus.pending > 0 || syncStatus.failed > 0) && (
              <div className="space-y-1.5 text-xs">
                {syncStatus.pending > 0 && (
                  <div className="flex items-center justify-between">
                    <span className="text-muted-foreground">Pendientes:</span>
                    <span className="font-semibold">{syncStatus.pending}</span>
                  </div>
                )}
                {syncStatus.failed > 0 && (
                  <div className="flex items-center justify-between">
                    <span className="text-red-600 dark:text-red-400">Fallidas:</span>
                    <span className="font-semibold text-red-600 dark:text-red-400">
                      {syncStatus.failed}
                    </span>
                  </div>
                )}
              </div>
            )}

            {/* Acciones */}
            {syncStatus.failed > 0 && (
              <div className="flex gap-2">
                <button
                  onClick={handleRetryFailed}
                  className={cn(
                    "flex-1 px-3 py-1.5 rounded-md text-xs font-medium",
                    "bg-primary text-primary-foreground",
                    "hover:bg-primary/90 transition-colors"
                  )}
                >
                  <RefreshCw className="h-3 w-3 inline mr-1" />
                  Reintentar
                </button>
                <button
                  onClick={handleClearFailed}
                  className={cn(
                    "px-3 py-1.5 rounded-md text-xs font-medium",
                    "bg-muted text-muted-foreground",
                    "hover:bg-muted/80 transition-colors"
                  )}
                >
                  Limpiar
                </button>
              </div>
            )}

            {/* Mensaje especial para modo offline */}
            {!isOnline && (
              <div className="pt-2 border-t border-current/20">
                <p className="text-[10px] text-muted-foreground italic">
                  💡 Puedes seguir trabajando. Los cambios se guardarán localmente
                  y se sincronizarán cuando recuperes la conexión.
                </p>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useEffect, useState, useCallback, useMemo } from 'react';
import { useFormDataEntities, useCacheDebug } from '@/shared/hooks/useOptimizedFormData';
import { useAnimals } from '@/entities/animal/model/useAnimals';
import { useUsers } from '@/entities/user/model/useUser';
import { useDiseases } from '@/entities/disease/model/useDisease';
import { useSpecies } from '@/entities/species/model/useSpecies';
import { useFields } from '@/entities/field/model/useField';
import { useMedications } from '@/entities/medication/model/useMedication';
import { useVaccines } from '@/entities/vaccine/model/useVaccine';

interface OptimizedFormWrapperProps {
  children: React.ReactNode;
  requiredEntities: string[];
  onDataReady?: (data: Record<string, any[]>) => void;
  enableDebug?: boolean;
}

/**
 * Componente wrapper que optimiza la carga de datos para formularios
 * Evita peticiones redundantes al backend usando caché inteligente
 */
export const OptimizedFormWrapper: React.FC<OptimizedFormWrapperProps> = ({
  children,
  requiredEntities,
  onDataReady,
  enableDebug = false
}) => {
  const [isDataReady, setIsDataReady] = useState(false);
  const [loadedData, setLoadedData] = useState<Record<string, any[]>>({});
  
  const { checkSpecificEntities } = useFormDataEntities();
  const { logCacheStats } = useCacheDebug();
  
  // Hooks condicionales basados en entidades requeridas
  const animalsHook = useAnimals();
  const usersHook = useUsers();
  const diseasesHook = useDiseases();
  const speciesHook = useSpecies();
  const fieldsHook = useFields();
  const medicationsHook = useMedications();
  const vaccinesHook = useVaccines();
  
  // Mapeo de entidades a hooks - Memoizado para evitar re-renders
  const entityHookMap = useMemo(() => ({
    animals: animalsHook,
    users: usersHook,
    diseases: diseasesHook,
    species: speciesHook,
    fields: fieldsHook,
    medications: medicationsHook,
    vaccines: vaccinesHook
  }), [animalsHook, usersHook, diseasesHook, speciesHook, fieldsHook, medicationsHook, vaccinesHook]);
  
  // Función para verificar si todos los datos están listos
  const checkDataReadiness = useCallback(() => {
    const { allCached, cachedData, missingEntities } = checkSpecificEntities(requiredEntities);
    
    if (enableDebug) {
      console.group('🔍 OptimizedFormWrapper - Data Check');
      console.log('Required entities:', requiredEntities);
      console.log('All cached:', allCached);
      console.log('Missing entities:', missingEntities);
      logCacheStats(requiredEntities);
      console.groupEnd();
    }
    
    // Si todos los datos están en caché, usar esos datos
    if (allCached) {
      setLoadedData(cachedData);
      setIsDataReady(true);
      onDataReady?.(cachedData);
      return;
    }
    
    // Si faltan datos, verificar si los hooks han terminado de cargar
    const allHooksReady = requiredEntities.every(entity => {
      const hook = entityHookMap[entity as keyof typeof entityHookMap];
      return hook && !hook.loading;
    });
    
    if (allHooksReady) {
      // Recopilar datos de los hooks
      const hookData: Record<string, any[]> = {};
      requiredEntities.forEach(entity => {
        const hook = entityHookMap[entity as keyof typeof entityHookMap];
        if (hook) {
          switch (entity) {
            case 'animals':
              hookData[entity] = (hook as any).animals || [];
              break;
            case 'users':
              hookData[entity] = (hook as any).users || [];
              break;
            case 'diseases':
              hookData[entity] = (hook as any).diseases || [];
              break;
            case 'species':
              hookData[entity] = (hook as any).species || [];
              break;
            case 'fields':
              hookData[entity] = (hook as any).fields || [];
              break;
            case 'medications':
              hookData[entity] = (hook as any).medications || [];
              break;
            case 'vaccines':
              hookData[entity] = (hook as any).vaccines || [];
              break;
          }
        }
      });
      
      setLoadedData(hookData);
      setIsDataReady(true);
      onDataReady?.(hookData);
    }
  }, [requiredEntities, checkSpecificEntities, onDataReady, enableDebug, logCacheStats, entityHookMap]);
  
  // Efecto para verificar la disponibilidad de datos
  useEffect(() => {
    checkDataReadiness();
  }, [
    checkDataReadiness,
    animalsHook.loading,
    usersHook.loading,
    diseasesHook.loading,
    speciesHook.loading,
    fieldsHook.loading,
    medicationsHook.loading,
    vaccinesHook.loading
  ]);
  
  // Mostrar loading si los datos no están listos
  if (!isDataReady) {
    const loadingEntities = requiredEntities.filter(entity => {
      const hook = entityHookMap[entity as keyof typeof entityHookMap];
      return hook?.loading;
    });
    
    return (
      <div className="flex items-center justify-center p-8">
        <div className="text-center">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mx-auto mb-4"></div>
          <p className="text-muted-foreground">
            Cargando datos{loadingEntities.length > 0 && ` (${loadingEntities.join(', ')})`}...
          </p>
          {enableDebug && (
            <p className="text-xs text-muted-foreground mt-2">
              Entidades requeridas: {requiredEntities.join(', ')}
            </p>
          )}
        </div>
      </div>
    );
  }
  
  // Clonar children y pasar los datos como props
  const childrenWithProps = React.Children.map(children, child => {
    if (React.isValidElement(child)) {
        const childProps = {
          ...(child.props as any),
          optimizedData: loadedData,
          isOptimized: true
        };
        return React.cloneElement(child, childProps);
      }
    return child;
  });
  
  return (
    <>
      {enableDebug && (
        <div className="mb-4 p-2 bg-muted rounded text-xs">
          <strong>🚀 OptimizedFormWrapper Debug:</strong>
          <br />Entidades: {requiredEntities.join(', ')}
          <br />Datos listos: {isDataReady ? '✅' : '❌'}
          <br />Elementos cargados: {Object.keys(loadedData).map(key => `${key}(${loadedData[key]?.length || 0})`).join(', ')}
        </div>
      )}
      {childrenWithProps}
    </>
  );
};

export default OptimizedFormWrapper;

import React, { useState, useEffect } from 'react';
import { Button } from '@/shared/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/shared/ui/card';
import { useToast } from '@/app/providers/ToastContext';
import { WifiOff, RefreshCw, Download } from 'lucide-react';

export function PWAUpdateHandler() {
  const [updateAvailable, setUpdateAvailable] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isUpdating, setIsUpdating] = useState(false);
  const { showToast } = useToast();

  useEffect(() => {
    // Escuchar actualizaciones PWA
    const handleUpdateAvailable = () => {
      setUpdateAvailable(true);
      showToast('Nueva versión disponible', 'info');
    };

    window.addEventListener('pwa-update-available', handleUpdateAvailable);

    // Manejar estado de conexión
    const handleOnline = () => {
      setIsOnline(true);
      showToast('Conexión restablecida', 'success');
    };

    const handleOffline = () => {
      setIsOnline(false);
      showToast('Modo offline activado', 'warning');
    };

    const handleSyncSuccess = (e: Event) => {
      // @ts-ignore
      const url = (e as CustomEvent).detail?.url || '';
      showToast(`¡Sincronización en segundo plano completada!`, 'success');
    };

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    window.addEventListener('pwa-offline-sync-success', handleSyncSuccess);

    return () => {
      window.removeEventListener('pwa-update-available', handleUpdateAvailable);
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      window.removeEventListener('pwa-offline-sync-success', handleSyncSuccess);
    };
  }, [showToast]);

  const handleUpdate = async () => {
    setIsUpdating(true);
    try {
      // Registrar el Service Worker nuevamente para forzar la actualización
      if ('serviceWorker' in navigator) {
        const registrations = await navigator.serviceWorker.getRegistrations();
        for (const registration of registrations) {
          await registration.update();
        }
        
        // Esperar un momento y recargar
        setTimeout(() => {
          window.location.reload();
        }, 1000);
      }
    } catch (error) {
      console.error('Error al actualizar PWA:', error);
      showToast('Error al actualizar. Recarga la página manualmente.', 'error');
      setIsUpdating(false);
    }
  };

  const handleSkipUpdate = () => {
    setUpdateAvailable(false);
    showToast('Puedes actualizar más tarde desde el menú', 'info');
  };

  if (!updateAvailable) {
    // Indicador de estado de conexión SOLO en modo offline
    if (!isOnline) {
      return (
        <div className="fixed bottom-4 right-4 z-50 animate-fade-in">
          <Card className="w-64 shadow-lg border-orange-200 bg-orange-50">
            <CardContent className="p-3 flex items-center space-x-2">
              <WifiOff className="h-4 w-4 text-orange-600" />
              <div className="flex-1">
                <p className="text-sm font-medium text-orange-800">Modo Offline</p>
                <p className="text-xs text-orange-600">Trabajando con datos cacheados</p>
              </div>
            </CardContent>
          </Card>
        </div>
      );
    }

    // No mostrar nada cuando está online (mensaje eliminado)
    return null;
  }

  return (
    <div className="fixed bottom-4 right-4 z-50 animate-slide-up">
      <Card className="w-80 shadow-xl border-blue-200 bg-blue-50">
        <CardHeader className="pb-3">
          <CardTitle className="text-sm flex items-center space-x-2 text-blue-800">
            <Download className="h-4 w-4" />
            <span>Actualización Disponible</span>
          </CardTitle>
          <CardDescription className="text-xs text-blue-600">
            Hay una nueva versión de la aplicación con mejoras y correcciones.
          </CardDescription>
        </CardHeader>
        <CardContent className="pt-0">
          <div className="flex space-x-2">
            <Button 
              onClick={handleUpdate}
              disabled={isUpdating}
              size="sm"
              className="flex-1 bg-blue-600 hover:bg-blue-700"
            >
              {isUpdating ? (
                <RefreshCw className="h-3 w-3 animate-spin mr-1" />
              ) : (
                <Download className="h-3 w-3 mr-1" />
              )}
              {isUpdating ? 'Actualizando...' : 'Actualizar Ahora'}
            </Button>
            <Button 
              onClick={handleSkipUpdate}
              variant="outline"
              size="sm"
              className="flex-1"
            >
              Después
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

export default PWAUpdateHandler;

import React from 'react';
import { cn } from '@/shared/ui/cn';

export interface PaginationBarProps {
  page: number;
  pages: number;
  onPageChange: (page: number) => void;
  // Compatibilidad retro: algunas páginas pasan estos props aunque no son necesarios para el render
  pageSize?: number;
  total?: number;
  showNumbers?: boolean;
  boundaryCount?: number;
  siblingCount?: number;
  fixedBottom?: boolean; // fijo en escritorio para que siempre sea visible
  containerClassName?: string;
  innerClassName?: string;
}

export const PaginationBar: React.FC<PaginationBarProps> = ({
  page,
  pages,
  onPageChange,
  pageSize: _pageSize, // no usado, mantenido por compatibilidad
  total: _total, // no usado, mantenido por compatibilidad
  showNumbers = true,
  boundaryCount = 1,
  siblingCount = 1,
  fixedBottom = true,
  containerClassName,
  innerClassName,
}) => {
  const canPrev = page > 1;
  const canNext = page < pages;

  const goTo = (p: number) => {
    if (p >= 1 && p <= pages && p !== page) onPageChange(p);
  };

  // Render de números de página
  const makePageNumbers = () => {
    if (!showNumbers) return null;

    const start = Math.max(1, page - siblingCount);
    const end = Math.min(pages, page + siblingCount);

    const numbers: React.ReactNode[] = [];

    // Primeros límites
    for (let i = 1; i <= Math.min(boundaryCount, pages); i++) {
      if (i < start) {
        numbers.push(
          <button
            key={i}
            onClick={() => goTo(i)}
            className="px-3 py-2 min-w-[40px] border border-border text-sm text-foreground rounded-md hover:bg-muted focus:outline-none focus:ring-2 focus:ring-ring transition-colors"
            aria-label={`Ir a la página ${i}`}
          >
            {i}
          </button>
        );
      }
    }

    if (start > boundaryCount + 1) {
      numbers.push(
        <span key="start-ellipsis" aria-hidden className="px-2 py-2 text-sm text-muted-foreground">
          ...
        </span>
      );
    }

    for (let i = start; i <= end; i++) {
      numbers.push(
        <button
          key={i}
          onClick={() => goTo(i)}
          className={cn(
            'px-3 py-2 min-w-[40px] border rounded-md text-sm transition-colors focus:outline-none focus:ring-2 focus:ring-ring',
            i === page
              ? 'bg-background text-foreground border-transparent ring-2 ring-[#3b82f6] shadow-sm'
              : 'border-border text-foreground hover:bg-muted'
          )}
          aria-current={i === page ? 'page' : undefined}
          aria-label={`Ir a la página ${i}`}
        >
          {i}
        </button>
      );
    }

    if (end < pages - boundaryCount) {
      numbers.push(
        <span key="end-ellipsis" aria-hidden className="px-2 py-2 text-sm text-muted-foreground">
          ...
        </span>
      );
    }

    for (let i = Math.max(pages - boundaryCount + 1, end + 1); i <= pages; i++) {
      numbers.push(
        <button
          key={i}
          onClick={() => goTo(i)}
          className="px-3 py-2 min-w-[40px] border border-border text-sm text-foreground rounded-md hover:bg-muted focus:outline-none focus:ring-2 focus:ring-ring transition-colors"
          aria-label={`Ir a la página ${i}`}
        >
          {i}
        </button>
      );
    }

    return <div className="flex items-center gap-1">{numbers}</div>;
  };

  const content = (
    <div className="bg-card shadow-lg rounded-lg border border-border p-4">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex items-center gap-2">
          <button
            onClick={() => goTo(page - 1)}
            disabled={!canPrev}
            className="px-3 py-2 border border-border text-foreground rounded-md hover:bg-muted disabled:opacity-50 disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-ring transition-colors"
            aria-label="Página anterior"
          >
            ← Anterior
          </button>

          {makePageNumbers()}

          <button
            onClick={() => goTo(page + 1)}
            disabled={!canNext}
            className="px-3 py-2 border border-border text-foreground rounded-md hover:bg-muted disabled:opacity-50 disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-ring transition-colors"
            aria-label="Página siguiente"
          >
            Siguiente →
          </button>
        </div>

        <div className="text-sm text-muted-foreground">Página {page} de {Math.max(pages, 1)}</div>
      </div>
    </div>
  );

  if (!fixedBottom) return content;

  return (
    <>
      {/* Spacer interno para reservar el alto de la barra fija en sm+ sin tocar el body */}
      <div className="hidden sm:block h-20" aria-hidden="true" />

      <div
        className={cn(
          'sm:fixed sm:bottom-0 sm:left-[var(--sidebar-width,0px)] sm:right-0 z-[9999] bg-background/95 backdrop-blur-sm border-t border-border shadow-lg',
          containerClassName
        )}
      >
        <div className={cn('max-w-7xl mx-auto px-3 py-3 sm:px-6 sm:py-4', innerClassName)}>{content}</div>
      </div>
    </>
  );
};

/**
 * PrefetchManager
 * Sistema inteligente de prefetching para rutas y datos comunes
 * Mejora drásticamente la percepción de velocidad de la aplicación
 */

import { useCallback, useEffect, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import { useQueryClient } from '@tanstack/react-query';
import { useAuth } from '@/features/auth/model/useAuth';
import { useIdleCallback, useNetworkStatus } from '@/shared/hooks/usePerformance';
import { isLowEndDevice } from '@/shared/utils/performance';
import { hasSessionCookies } from '@/shared/utils/cookieUtils';
import { animalService } from '@/entities/animal/api/animal.service';
import { fieldService } from '@/entities/field/api/field.service';
import { breedsService } from '@/entities/breed/api/breeds.service';
import { speciesService } from '@/entities/species/api/species.service';

interface PrefetchConfig {
  route: string;
  queryKey: string[];
  fetchFn: () => Promise<any>;
  priority: 'high' | 'normal' | 'low';
  dependencies?: string[]; // Rutas que deben prefetchearse antes
}

/**
 * Configuración de prefetch por ruta
 */
const PREFETCH_CONFIG: PrefetchConfig[] = [
  // Datos maestros - Alta prioridad, usados en todas partes
  {
    route: '/dashboard',
    queryKey: ['species'],
    fetchFn: () => speciesService.getPaginated({ limit: 100 }),
    priority: 'high',
  },
  {
    route: '/dashboard',
    queryKey: ['breeds'],
    fetchFn: () => breedsService.getPaginated({ limit: 200 }),
    priority: 'high',
  },

  // Animales - Prioridad normal, datasets grandes
  {
    route: '/admin/animals',
    queryKey: ['animals', 'list'],
    fetchFn: () => animalService.getPaginated({ page: 1, limit: 20 }),
    priority: 'normal',
    dependencies: ['species', 'breeds'],
  },

  // Campos - Prioridad normal
  {
    route: '/admin/fields',
    queryKey: ['fields', 'list'],
    fetchFn: () => fieldService.getPaginated({ limit: 50 }),
    priority: 'normal',
  },

  // Analytics - Baja prioridad, datos pesados
  {
    route: '/admin/analytics',
    queryKey: ['analytics', 'dashboard'],
    fetchFn: async () => {
      // Simular carga de analytics
      return { loaded: true };
    },
    priority: 'low',
  },
];

export const PrefetchManager: React.FC = () => {
  const location = useLocation();
  const queryClient = useQueryClient();
  const { isAuthenticated, user } = useAuth();
  const { online, saveData } = useNetworkStatus();
  const prefetchedRoutes = useRef<Set<string>>(new Set());
  const prefetchedQueries = useRef<Set<string>>(new Set());
  const isPrefetching = useRef(false);

  const markQueryPrefetched = (config: PrefetchConfig) => {
    const key = config.queryKey[0] ?? config.queryKey.join('|');
    prefetchedQueries.current.add(key);
  };

  /**
   * Prefetch de datos para una ruta específica
   */
  const prefetchRoute = useCallback(async (route: string) => {
    // Solo si está autenticado y online
    if (!isAuthenticated || !online) return;
    // Requiere cookies de sesión visibles para evitar 401 masivos
    if (!hasSessionCookies()) return;

    // No prefetch en modo ahorro de datos
    if (saveData) return;

    // No prefetch en dispositivos de gama baja
    if (isLowEndDevice()) return;

    // Evitar prefetch duplicado
    if (prefetchedRoutes.current.has(route) || isPrefetching.current) return;

    isPrefetching.current = true;

    try {
      // Obtener configuraciones para esta ruta
      const configs = PREFETCH_CONFIG.filter((config) =>
        route.startsWith(config.route)
      );

      // Ordenar por prioridad
      const sortedConfigs = configs.sort((a, b) => {
        const priorityOrder = { high: 3, normal: 2, low: 1 };
        return priorityOrder[b.priority] - priorityOrder[a.priority];
      });

      // Prefetch en orden
      for (const config of sortedConfigs) {
        // Verificar dependencias
        if (config.dependencies) {
          const hasAllDeps = config.dependencies.every((dep) =>
            prefetchedQueries.current.has(dep)
          );
          if (!hasAllDeps) continue;
        }

        // Verificar si ya está en caché de React Query
        const cached = queryClient.getQueryData(config.queryKey);
        if (cached) {
          markQueryPrefetched(config);
          continue;
        }

        // Hacer prefetch
        await queryClient.prefetchQuery({
          queryKey: config.queryKey,
          queryFn: config.fetchFn,
          staleTime: 5 * 60 * 1000, // 5 minutos
        });

        markQueryPrefetched(config);

        // Pequeño delay entre prefetches para no saturar
        await new Promise((resolve) => setTimeout(resolve, 100));
      }

      prefetchedRoutes.current.add(route);
    } catch (error) {
      console.warn(`[Prefetch] Error prefetching route ${route}:`, error);
    } finally {
      isPrefetching.current = false;
    }
  }, [isAuthenticated, online, saveData, queryClient]);

  /**
   * Prefetch inteligente basado en la ruta actual
   */
  useEffect(() => {
    if (!isAuthenticated || !online || !hasSessionCookies()) return;

    // Prefetch datos para la ruta actual
    prefetchRoute(location.pathname);

    // Predecir y prefetch rutas probables basándose en la ruta actual
    const predictNextRoutes = () => {
      const currentPath = location.pathname;

      // Si está en dashboard, prefetch rutas comunes según rol
      if (currentPath === '/dashboard') {
        if (user?.role === 'Administrador') {
          prefetchRoute('/admin/animals');
          prefetchRoute('/admin/fields');
        } else if (user?.role === 'Instructor') {
          prefetchRoute('/instructor/animals');
        } else if (user?.role === 'Aprendiz') {
          prefetchRoute('/apprentice/animals');
        }
      }

      // Si está en la lista de animales, prefetch campos y razas
      if (currentPath.includes('/animals')) {
        prefetchRoute('/admin/fields');
        prefetchRoute('/admin/breeds');
      }

      // Si está en cualquier página admin, prefetch otras páginas admin
      if (currentPath.startsWith('/admin/')) {
        const adminRoutes = [
          '/admin/animals',
          '/admin/fields',
          '/admin/breeds',
          '/admin/species',
        ];

        adminRoutes.forEach((route) => {
          if (route !== currentPath) {
            // Prefetch con baja prioridad en idle time
            requestIdleCallback(() => {
              prefetchRoute(route);
            });
          }
        });
      }
    };

    // Ejecutar predicción en idle time
    requestIdleCallback(predictNextRoutes, { timeout: 2000 });
  }, [location.pathname, isAuthenticated, online, user?.role, prefetchRoute]);

  /**
   * Prefetch al hacer hover sobre links
   */
  useEffect(() => {
    if (!isAuthenticated || !online) return;

    const handleMouseEnter = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      const link = target.closest('a[href]') as HTMLAnchorElement;

      if (link && link.href) {
        try {
          const url = new URL(link.href);
          // Solo prefetch rutas internas
          if (url.origin === window.location.origin) {
            // Usar requestIdleCallback para no bloquear interacciones
            if ('requestIdleCallback' in window) {
              window.requestIdleCallback(() => {
                prefetchRoute(url.pathname);
              }, { timeout: 500 });
            } else {
              setTimeout(() => prefetchRoute(url.pathname), 50);
            }
          }
        } catch (err) {
          // URL inválida, ignorar
        }
      }
    };

    // Agregar listeners con capture para capturar antes de que llegue al elemento
    document.addEventListener('mouseover', handleMouseEnter, { capture: true, passive: true });

    return () => {
      document.removeEventListener('mouseover', handleMouseEnter, { capture: true });
    };
  }, [isAuthenticated, online, prefetchRoute]);

  /**
   * Limpiar caché antigua periódicamente
   */
  useEffect(() => {
    const cleanup = () => {
      // Limpiar queries inactivas más antiguas de 30 minutos
      // La limpieza de queries inactivas la gestiona React Query vía gcTime (30m)
      // queryClient.clear() eliminado por ser demasiado agresivo (limpia datos activos)
      prefetchedRoutes.current.clear();
      prefetchedQueries.current.clear();
    };

    // Limpiar cada 30 minutos
    const interval = setInterval(cleanup, 30 * 60 * 1000);

    return () => clearInterval(interval);
  }, [queryClient]);

  /**
   * Prefetch de datos críticos al iniciar sesión
   */
  useIdleCallback(() => {
    if (!isAuthenticated || !online || !hasSessionCookies()) return;

    // Prefetch datos maestros inmediatamente
    const criticalData = ['species', 'breeds'];

    criticalData.forEach((key) => {
      const config = PREFETCH_CONFIG.find((c) => c.queryKey[0] === key);
      if (!config) return;

      const cached = queryClient.getQueryData(config.queryKey);
      if (cached) {
        markQueryPrefetched(config);
        return;
      }

      void queryClient.prefetchQuery({
        queryKey: config.queryKey,
        queryFn: config.fetchFn,
        staleTime: 10 * 60 * 1000, // 10 minutos para datos críticos
      }).then(() => markQueryPrefetched(config));
    });
  }, { timeout: 1000 });

  // Este componente no renderiza nada
  return null;
};

export default PrefetchManager;

import React, { useEffect, useRef, useState } from "react";
import { Input } from "@/shared/ui/input";

/**
 * Toolbar: barra de herramientas reutilizable para listas y tablas.
 *
 * Características:
 * - Campo de búsqueda opcional a la izquierda.
 * - Slot de contenido intermedio (children) para filtros u otros controles.
 * - Slot de acciones a la derecha (right).
 * - Diseño responsive (stack en móvil, distribución en fila en pantallas medianas+).
 *
 * @example
 * ```tsx
 * import { Toolbar } from "@/shared/ui/common/Toolbar";
 * import { Button } from "@/shared/ui/button";
 *
 * <Toolbar
 *   searchPlaceholder="Buscar por nombre..."
 *   searchValue={search}
 *   onSearchChange={setSearch}
 *   right={<Button onClick={onAdd} aria-label="Nuevo registro">Nuevo</Button>}
 * >
 *   <Select>...</Select>
 * </Toolbar>
 * ```
 */
export interface ToolbarProps {
  searchPlaceholder?: string;
  searchValue?: string;
  onSearchChange?: (v: string) => void;
  children?: React.ReactNode;
  right?: React.ReactNode;
  className?: string;
  searchDebounceMs?: number;
}

export function Toolbar({
  searchPlaceholder = "Buscar...",
  searchValue,
  onSearchChange,
  children,
  right,
  className,
  searchDebounceMs = 300,
}: ToolbarProps) {
  const [internalValue, setInternalValue] = useState<string>(searchValue ?? "");
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Sincronizar cuando cambia el valor controlado externamente
  useEffect(() => {
    setInternalValue(searchValue ?? "");
  }, [searchValue]);

  // Limpiar timer al desmontar
  useEffect(() => {
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
    };
  }, []);

  const handleChange = (v: string) => {
    setInternalValue(v);
    if (typeof onSearchChange === "function") {
      if (debounceRef.current) clearTimeout(debounceRef.current);
      debounceRef.current = setTimeout(() => {
        onSearchChange(v);
      }, Math.max(0, searchDebounceMs));
    }
  };

  return (
    <div
      className={[
        "w-full flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between",
        className,
      ]
        .filter(Boolean)
        .join(" ")}
      role="region"
      aria-label="Barra de herramientas"
    >
      {/* Buscador ocupa toda la fila en móvil */}
      {typeof onSearchChange === "function" ? (
        <div className="w-full sm:flex-1 sm:min-w-0 order-1 sm:order-none">
          <Input
            value={internalValue}
            onChange={(e) => handleChange(e.target.value)}
            placeholder={searchPlaceholder}
            aria-label={searchPlaceholder}
            className="w-full sm:max-w-sm h-10 text-base sm:text-sm"
          />
        </div>
      ) : null}

      {/* Filtros y controles adicionales */}
      <div className="flex flex-col sm:flex-row sm:flex-wrap gap-2 sm:gap-3 order-2 sm:order-none">
        {children ? (
          <div className="flex flex-wrap items-center gap-2 min-w-0">{children}</div>
        ) : (
          <span className="sr-only">Sin filtros adicionales</span>
        )}

        <div className="flex flex-wrap items-center gap-2 sm:gap-3">{right}</div>
      </div>
    </div>
  );
}

export default Toolbar;

import * as React from "react"
import * as DialogPrimitive from "@radix-ui/react-dialog"
import { VisuallyHidden } from "@radix-ui/react-visually-hidden"
import { X } from "lucide-react"

import { cn } from "@/shared/ui/cn"

function recoverStuckDocumentLocks() {
  if (typeof document === 'undefined') return
  // Verificar si hay algún diálogo o menú abierto reportado por el DOM
  const hasOpenDialog = Boolean(document.querySelector('[role="dialog"][data-state="open"], [role="menu"][data-state="open"], [data-radix-menu-content], [data-radix-select-viewport]'))
  if (hasOpenDialog) return

  const body = document.body
  const html = document.documentElement

  // Limpiar estilos de bloqueo de Radix y otros
  if (body?.style?.pointerEvents === 'none') body.style.pointerEvents = ''
  if (html?.style?.pointerEvents === 'none') html.style.pointerEvents = ''

  if (body?.style?.overflow === 'hidden') body.style.overflow = ''
  if (html?.style?.overflow === 'hidden') html.style.overflow = ''

  if (body?.style?.paddingRight) body.style.paddingRight = ''
  if (body?.style?.touchAction) body.style.touchAction = ''
  
  // Limpiar atributos específicos de Radix si quedaron pegados
  if (body?.hasAttribute('data-radix-scroll-lock')) {
    body.removeAttribute('data-radix-scroll-lock')
  }
}

const DIALOG_GUARD_KEY = '__vl_dialog_lock_guard__'
const DIALOG_ACTIVE_KEY = '__vl_dialog_active_id__'
function ensureDialogLockGuard() {
  if (typeof window === 'undefined' || typeof document === 'undefined') return
  const w = window as any
  if (w[DIALOG_GUARD_KEY]) return
  w[DIALOG_GUARD_KEY] = true

  const body = document.body
  if (!body) return

  const observer = new MutationObserver(() => {
    // Si el body se bloquea pero no detectamos modales abiertos, forzar recuperación
    if (document.body?.style?.pointerEvents === 'none' || document.body?.hasAttribute('data-radix-scroll-lock')) {
      // Pequeño delay para dejar que Radix termine su transición
      setTimeout(recoverStuckDocumentLocks, 100)
    }
  })
  observer.observe(body, { attributes: true, attributeFilter: ['style', 'class', 'data-radix-scroll-lock'] })

  window.addEventListener('pageshow', recoverStuckDocumentLocks)
  window.addEventListener('focus', recoverStuckDocumentLocks)
  // Al cambiar de ruta, asegurar que no queden locks
  window.addEventListener('popstate', () => setTimeout(recoverStuckDocumentLocks, 100))
}

function recoverDocumentInteractivityIfNoDialogsOpen(attempt = 0) {
  if (typeof document === "undefined") return

  const hasOpenDialog = Boolean(document.querySelector('[role="dialog"][data-state="open"], [role="menu"][data-state="open"], [data-radix-menu-content]'))
  if (hasOpenDialog) {
    if (attempt < 15) { // Aumentado reintentos
      setTimeout(() => recoverDocumentInteractivityIfNoDialogsOpen(attempt + 1), 100)
      return
    }
  }

  recoverStuckDocumentLocks()
}

type DialogProps = React.ComponentPropsWithoutRef<typeof DialogPrimitive.Root>

const Dialog: React.FC<DialogProps> = ({ open, defaultOpen, onOpenChange, modal, ...props }) => {
  const isControlled = typeof open === "boolean"
  const [internalOpen, setInternalOpen] = React.useState<boolean>(Boolean(defaultOpen))
  const isOpen = isControlled ? Boolean(open) : internalOpen
  const wasOpenRef = React.useRef(false)
  const instanceId = React.useId()

  const handleOpenChange = React.useCallback(
    (next: boolean) => {
      if (!isControlled) setInternalOpen(next)
      onOpenChange?.(next)
    },
    [isControlled, onOpenChange]
  )

  React.useEffect(() => {
    ensureDialogLockGuard()
    // Previously, this effect closed other open dialogs when a new one opened.
    // We removed this behavior to allow stacked/nested modals.
    //
    // const handler = (evt: Event) => {
    //   const e = evt as CustomEvent<{ id?: string }>
    //   if (!isOpen) return
    //   if (!e?.detail?.id) return
    //   if (e.detail.id === instanceId) return
    //   onOpenChange?.(false)
    // }
    // window.addEventListener('vl:dialog-open', handler as any)
    // return () => window.removeEventListener('vl:dialog-open', handler as any)
  }, [instanceId, isOpen, onOpenChange])

  React.useEffect(() => {
    if (!isOpen) return
    try {
      ; (window as any)[DIALOG_ACTIVE_KEY] = instanceId
      window.dispatchEvent(new CustomEvent('vl:dialog-open', { detail: { id: instanceId } }))
    } catch {
      // ignore
    }
  }, [instanceId, isOpen])

  React.useEffect(() => {
    ensureDialogLockGuard()
    if (isOpen) {
      wasOpenRef.current = true
      return
    }

    if (!isOpen && wasOpenRef.current) {
      wasOpenRef.current = false
      setTimeout(recoverDocumentInteractivityIfNoDialogsOpen, 0)
      setTimeout(recoverDocumentInteractivityIfNoDialogsOpen, 60)
      setTimeout(recoverDocumentInteractivityIfNoDialogsOpen, 120)
      setTimeout(recoverStuckDocumentLocks, 200)
    }
  }, [isOpen])

  React.useEffect(() => {
    return () => {
      setTimeout(recoverDocumentInteractivityIfNoDialogsOpen, 0)
      setTimeout(recoverStuckDocumentLocks, 120)
    }
  }, [])

  return (
    <DialogPrimitive.Root
      open={isOpen}
      onOpenChange={handleOpenChange}
      // modal=false evita que Radix aplique disableOutsidePointerEvents al body.
      // El overlay cubre y bloquea clicks al fondo.
      modal={typeof modal === "boolean" ? modal : true}
      {...props}
    />
  )
}

