const DialogContent = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Content>,
  Omit<React.ComponentPropsWithoutRef<typeof DialogPrimitive.Content>, "aria-labelledby" | "aria-describedby"> & {
    overlayClassName?: string
    zIndex?: number
    hideCloseButton?: boolean
    ["aria-labelledby"]?: string
    ["aria-describedby"]?: string
  }
>(({ className, children, overlayClassName, zIndex, hideCloseButton = false, ["aria-labelledby"]: ariaLabelledByProp, ["aria-describedby"]: ariaDescribedByProp, style: propsStyle, ...props }, ref) => {
  const [registeredTitleId, setRegisteredTitleId] = React.useState<string | undefined>(undefined)
  const [registeredDescriptionId, setRegisteredDescriptionId] = React.useState<string | undefined>(undefined)
  
  const a11yValue = React.useMemo(() => ({
    titleId: registeredTitleId,
    descriptionId: registeredDescriptionId,
    registerTitleId: (id: string) => setRegisteredTitleId(id),
    registerDescriptionId: (id: string) => setRegisteredDescriptionId(id),
  }), [registeredTitleId, registeredDescriptionId])

  const internalTitleId = React.useId()
  const internalDescriptionId = React.useId()

  // Prioritize props > registered (via context) > internal
  const finalAriaLabelledBy = ariaLabelledByProp || registeredTitleId || internalTitleId
  const finalAriaDescribedBy = ariaDescribedByProp || registeredDescriptionId || internalDescriptionId

  return (
    <DialogPortal>
      <DialogOverlay
        className={overlayClassName}
        style={zIndex ? { zIndex: zIndex - 1 } : undefined}
      />
      <DialogPrimitive.Content
        ref={ref}
        className={cn(
          "fixed left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2",
          !zIndex && "z-[1000]",
          "w-[95vw] sm:w-auto",
          "min-w-[300px] sm:min-w-[400px]",
          "max-w-[95vw] sm:max-w-lg md:max-w-xl lg:max-w-2xl",
          "h-auto",
          "max-h-[90vh] sm:max-h-[92vh]",
          "grid gap-4 p-6",
          "isolate",
          "vl-modal-surface",
          "ring-1 ring-black/5 dark:ring-white/10",
          "rounded-2xl",
          "shadow-2xl shadow-black/20 dark:shadow-black/40",
          "data-[state=closed]:pointer-events-none",
          "overflow-hidden",
          "motion-safe:duration-300 motion-safe:ease-out motion-reduce:duration-0",
          "data-[state=open]:animate-in data-[state=closed]:animate-out motion-reduce:animate-none",
          "data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0",
          "data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-100",
          "data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-1/2",
          "data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-1/2",
          className
        )}
        aria-labelledby={finalAriaLabelledBy}
        aria-describedby={finalAriaDescribedBy}
        style={zIndex ? { ...propsStyle, zIndex } : propsStyle}
        {...props}
      >
        <DialogA11yContext.Provider value={a11yValue}>
          {/* 
            Radix requiere un DialogTitle y DialogDescription. 
            Renderizamos fallbacks con VisuallyHidden que usan los IDs internos.
            Si el usuario provee sus propios componentes DialogTitle/Description,
            estos registrarán sus IDs y el aria-labelledby del contenedor se actualizará.
          */}
          <DialogPrimitive.Title id={internalTitleId} className="sr-only">
            Diálogo de Villa Luz
          </DialogPrimitive.Title>
          <DialogPrimitive.Description id={internalDescriptionId} className="sr-only">
            Contenido del diálogo interactivo.
          </DialogPrimitive.Description>

          {children}
        </DialogA11yContext.Provider>

        {!hideCloseButton && (
          <DialogPrimitive.Close className={cn(
            "absolute right-2 top-2 sm:right-3 sm:top-2",
            "rounded-xl p-1.5 sm:p-2 z-[60]",
            "bg-muted/40 opacity-70 hover:opacity-100",
            "ring-offset-background transition-all duration-300",
            "hover:bg-destructive hover:text-white hover:scale-110 active:scale-95",
            "focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2",
            "disabled:pointer-events-none",
            "data-[state=open]:bg-accent/30 data-[state=open]:text-muted-foreground shadow-sm"
          )}>
            <X className="h-5 w-5" />
            <span className="sr-only">Cerrar</span>
          </DialogPrimitive.Close>
        )}
      </DialogPrimitive.Content>
    </DialogPortal>
  )
})
