import { cn } from "@/shared/ui/cn";

export type PageSize = 5 | 10 | 25 | 50;

export type PaginationBarProps = {
  page: number;
  totalPages: number;
  pageSize: number;
  totalItems?: number;
  onPageChange: (page: number) => void;
  onPageSizeChange?: (size: PageSize) => void;
  className?: string;
  pageWindow?: number; // how many page numbers to show
  // Nuevo: barra fija inferior para que siempre sea visible
  fixedBottom?: boolean; // por defecto true (especialmente útil en PC)
  containerClassName?: string;
  innerClassName?: string;
};

export function ResultInfo({
  page,
  pageSize,
  totalItems,
  className,
}: {
  page: number;
  pageSize: number;
  totalItems?: number;
  className?: string;
}) {
  if (!totalItems || totalItems <= 0) return null;
  const start = (page - 1) * pageSize + 1;
  const end = Math.min(page * pageSize, totalItems);
  return (
    <div className={cn("text-sm text-muted-foreground", className)}>
      Mostrando {start} a {end} de {totalItems.toLocaleString()} resultados
    </div>
  );
}

export function PageSizeSelect({
  value,
  onChange,
  className,
  options = [5, 10, 25, 50] as PageSize[],
}: {
  value: number;
  onChange?: (size: PageSize) => void;
  className?: string;
  options?: PageSize[];
}) {
  if (!onChange) return null;
  return (
    <div className={cn("flex items-center gap-2 text-sm text-foreground", className)}>
      <span>Mostrar:</span>
      <select
        value={value}
        onChange={(e) => onChange(Number(e.target.value) as PageSize)}
        className="border border-input rounded-md px-2 py-1 bg-background text-foreground focus:outline-none focus:ring-2 focus:ring-ring focus:border-transparent"
        aria-label="Seleccionar número de elementos por página"
      >
        {options.map((opt) => (
          <option key={opt} value={opt}>
            {opt}
          </option>
        ))}
      </select>
      <span>por página</span>
    </div>
  );
}

export function PaginationBar({
  page,
  totalPages,
  pageSize,
  totalItems,
  onPageChange,
  onPageSizeChange,
  className,
  pageWindow = 5,
  fixedBottom = true,
  containerClassName,
  innerClassName,
}: PaginationBarProps) {
  const canPrev = page > 1;
  const canNext = page < totalPages;

  const startPage = Math.max(1, page - Math.floor(pageWindow / 2));
  const endPage = Math.min(totalPages, startPage + pageWindow - 1);

  const goTo = (p: number) => {
    if (p >= 1 && p <= totalPages && p !== page) onPageChange(p);
  };

  const content = (
    <div className={cn("bg-card shadow-lg rounded-lg border border-border p-4", className)}>
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <PageSizeSelect value={pageSize} onChange={onPageSizeChange} />

        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() => goTo(page - 1)}
            disabled={!canPrev}
            className="px-3 py-2 border border-border text-foreground rounded-md hover:bg-muted disabled:opacity-50 disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-ring transition-colors"
            aria-label="Página anterior"
          >
            ← Anterior
          </button>

          <div className="flex items-center gap-1">
            {startPage > 1 && (
              <>
                <button
                  type="button"
                  onClick={() => goTo(1)}
                  className="px-3 py-2 min-w-[40px] border border-border text-sm text-foreground rounded-md hover:bg-muted focus:outline-none focus:ring-2 focus:ring-ring transition-colors"
                  aria-label="Primera página"
                >
                  1
                </button>
                {startPage > 2 && (
                  <span aria-hidden className="px-2 py-2 text-sm text-muted-foreground">
                    ...
                  </span>
                )}
              </>
            )}

            {Array.from({ length: endPage - startPage + 1 }, (_, i) => startPage + i).map((p) => (
              <button
                type="button"
                key={p}
                onClick={() => goTo(p)}
                className={cn(
                  "px-3 py-2 min-w-[40px] border rounded-md text-sm transition-colors focus:outline-none focus:ring-2 focus:ring-ring",
                  p === page
                    ? "bg-background text-foreground border-transparent ring-2 ring-[#3b82f6] shadow-sm"
                    : "border-border text-foreground hover:bg-muted"
                )}
                aria-label={`Ir a la página ${p}`}
                aria-current={p === page ? "page" : undefined}
              >
                {p}
              </button>
            ))}

            {endPage < totalPages && (
              <>
                {endPage < totalPages - 1 && (
                  <span aria-hidden className="px-2 py-2 text-sm text-muted-foreground">
                    ...
                  </span>
                )}
                <button
                  type="button"
                  onClick={() => goTo(totalPages)}
                  className="px-3 py-2 min-w-[40px] border border-border text-sm text-foreground rounded-md hover:bg-muted focus:outline-none focus:ring-2 focus:ring-ring transition-colors"
                  aria-label="Última página"
                >
                  {totalPages}
                </button>
              </>
            )}
          </div>

          <button
            type="button"
            onClick={() => goTo(page + 1)}
            disabled={!canNext}
            className="px-3 py-2 border border-border text-foreground rounded-md hover:bg-muted disabled:opacity-50 disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-ring transition-colors"
            aria-label="Página siguiente"
          >
            Siguiente →
          </button>
        </div>

        <div className="text-sm text-muted-foreground">
          Página {page} de {Math.max(totalPages, 1)}
          {typeof totalItems === "number" && totalItems >= 0 ? (
            <span className="ml-2 text-muted-foreground">({totalItems.toLocaleString()} totales)</span>
          ) : null}
        </div>
      </div>
    </div>
  );

  if (!fixedBottom) return content;

  return (
    <>
      {/* Espaciador fantasma solo en sm+ para que el contenido no quede tapado */}
      <div className="hidden sm:block sm:h-20" aria-hidden />
      <div
        className={cn(
          "sm:fixed sm:bottom-0 sm:left-0 sm:right-0 z-50 bg-background/95 backdrop-blur-sm border-t border-border shadow-lg",
          containerClassName
        )}
      >
        <div className={cn("max-w-7xl mx-auto px-3 py-3 sm:px-6 sm:py-4", innerClassName)}>
          {content}
        </div>
      </div>
    </>
  );
}

export default PaginationBar;

// Utilidad central para normalizar respuestas API { success, message, data }
// Acepta AxiosResponse o dato crudo.
export function unwrapApi<T = any>(resp: any): T {
  if (!resp) return resp as T;
  // Axios response shape
  if (resp.data !== undefined) {
    const d = resp.data;
    if (d && typeof d === 'object') {
      if (d.data !== undefined) return d.data as T; // APIResponse wrapper
      return d as T;
    }
  }
  // Direct object already normalized
  if (resp.data === undefined && resp.success === true && resp.data !== undefined) {
    return resp.data as T;
  }
  return resp as T;
}

export const unwrapArray = <T=any>(resp: any): T[] => {
  const r = unwrapApi<T[] | any>(resp);
  if (Array.isArray(r)) return r as T[];
  const obj = r as any;
  if (obj && typeof obj === 'object') {
    // Direct common keys
    if (Array.isArray(obj.items)) return obj.items as T[];
    if (Array.isArray(obj.data)) return obj.data as T[];
    if (Array.isArray(obj.results)) return obj.results as T[];
    if (Array.isArray(obj.list)) return obj.list as T[];
    if (Array.isArray(obj.animals)) return obj.animals as T[];
    if (Array.isArray(obj.breeds)) return obj.breeds as T[];
    // Nested typical wrapper { data: { items: [...] } }
    if (obj.data && typeof obj.data === 'object' && Array.isArray(obj.data.items)) {
      return obj.data.items as T[];
    }
  }
  return [] as T[];
};

/**
 * Utilidad para evaluar condiciones dinámicas definidas como strings (ej: "< 400", "== 'Malo'")
 */
export const evaluateCondition = (value: any, condition: string): boolean => {
  if (!condition) return false;

  // Limpiar espacios
  const cleanCondition = condition.trim();

  // Caso 1: Comparaciones numéricas (<, >, <=, >=, ==, !=)
  const numericMatch = cleanCondition.match(/^([<>!=]=?)\s*(.+)$/);
  if (numericMatch) {
    const operator = numericMatch[1];
    const thresholdStr = numericMatch[2].replace(/'|"/g, '');
    const threshold = parseFloat(thresholdStr);
    const numericValue = parseFloat(value);

    if (isNaN(numericValue) || isNaN(threshold)) {
      // Si no son números, intentamos comparación de strings si el operador es == o !=
      if (operator === '==' || operator === '===') return String(value) === thresholdStr;
      if (operator === '!=' || operator === '!==') return String(value) !== thresholdStr;
      return false;
    }

    switch (operator) {
      case '<': return numericValue < threshold;
      case '>': return numericValue > threshold;
      case '<=': return numericValue <= threshold;
      case '>=': return numericValue >= threshold;
      case '==':
      case '===': return numericValue === threshold;
      case '!=':
      case '!==': return numericValue !== threshold;
      default: return false;
    }
  }

  // Caso 2: Igualdad simple (si no hay operador)
  return String(value).toLowerCase() === cleanCondition.toLowerCase().replace(/'|"/g, '');
};

/**
 * Mapea una dimensión (string) a un valor real del objeto animal/control
 */
export const getValueByDimension = (
  animal: any, 
  latestControl: any, 
  dimension: string,
  extraData?: {
    milkHistory?: any[],
    fieldAssignments?: any[],
    vaccinations?: any[]
  }
): any => {
  const d = dimension.toLowerCase();

  // Atributos del Animal
  if (d === 'peso') return latestControl?.weight ?? animal.weight;
  if (d === 'altura') return latestControl?.height ?? animal.height;
  if (d === 'salud' || d === 'estado_salud') return latestControl?.health_status ?? latestControl?.healt_status ?? 'Sano';

  // Atributos calculados
  if (d === 'dias_sin_control') {
    const lastDate = latestControl?.checkup_date ?? latestControl?.control_date ?? animal.created_at;
    if (!lastDate) return 0;
    const diff = Date.now() - new Date(lastDate).getTime();
    return Math.floor(diff / (1000 * 60 * 60 * 24));
  }

  if (d === 'edad_meses') return animal.age_in_months;

  // Rotación de Potreros
  if (d === 'dias_en_potrero') {
    const assignments = (extraData?.fieldAssignments || [])
      .filter(a => a.animal_id === animal.id)
      .sort((a, b) => new Date(b.created_at || b.assignment_date).getTime() - new Date(a.created_at || a.assignment_date).getTime());

    const latest = assignments[0];
    if (!latest) return 0;
    const diff = Date.now() - new Date(latest.created_at || latest.assignment_date).getTime();
    return Math.floor(diff / (1000 * 60 * 60 * 24));
  }

  // Producción de Leche (Caída de rendimiento)
  if (d === 'rendimiento_leche_diario') {
    const history = (extraData?.milkHistory || [])
      .filter(m => m.animal_id === animal.id)
      .sort((a, b) => new Date(b.created_at || b.date).getTime() - new Date(a.created_at || a.date).getTime());

    if (history.length < 1) return 0;
    return history[0].liters || history[0].quantity || 0;
  }

  // Reproducción (Días desde último evento)
  if (d === 'dias_desde_parto' || d === 'dias_posparto') {
    return animal.days_since_last_calving || 0;
  }

  // Propiedad directa
  return animal[dimension] ?? latestControl?.[dimension];
};

// Utilidades para manejo optimizado de JSON y transformación de datos
import { 
  ChartDataItem, 
  StatisticsToChartOptions, 
  UserStatistics, 
  CHART_COLORS, 
  STATUS_LABELS 
} from '@/shared/types/common.types';

/**
 * Convierte respuesta de estadísticas de objeto a formato de array para gráficos
 */
export function statisticsToChartData(
  stats: Record<string, any>, 
  options: StatisticsToChartOptions = {}
): ChartDataItem[] {
  const {
    activeKey = 'active_users',
    inactiveKey = 'inactive_users',
    totalKey = 'total_users',
    activeLabel = STATUS_LABELS.active,
    inactiveLabel = STATUS_LABELS.inactive,
    colors = CHART_COLORS
  } = options;

  const total = stats[totalKey] || 0;
  const active = stats[activeKey] || 0;
  const inactive = stats[inactiveKey] || 0;

  const result: ChartDataItem[] = [];

  if (active > 0) {
    result.push({
      status: activeLabel,
      count: active,
      percentage: total > 0 ? parseFloat(((active / total) * 100).toFixed(2)) : 0,
      color: colors.active || CHART_COLORS.active
    });
  }

  if (inactive > 0) {
    result.push({
      status: inactiveLabel,
      count: inactive,
      percentage: total > 0 ? parseFloat(((inactive / total) * 100).toFixed(2)) : 0,
      color: colors.inactive || CHART_COLORS.inactive
    });
  }

  return result;
}

/**
 * Convierte específicamente datos de usuario a formato de gráfico
 */
export function userStatsToChartData(userStats: UserStatistics): ChartDataItem[] {
  return statisticsToChartData(userStats, {
    activeKey: 'active_users',
    inactiveKey: 'inactive_users',
    totalKey: 'total_users',
    activeLabel: 'Activos',
    inactiveLabel: 'Inactivos'
  });
}

/**
 * Convierte datos de animal status a formato de gráfico
 */
export function animalStatsToChartData(animalStats: Record<string, any>): ChartDataItem[] {
  const statusMapping: Record<string, string> = {
    'Activo': 'Activos',
    'Vendido': 'Vendidos',
    'Enfermo': 'Enfermos',
    'Muerto': 'Muertos'
  };

  return Object.entries(animalStats.by_status || {}).map(([status, count]) => ({
    status: statusMapping[status] || status,
    count: count as number,
    percentage: animalStats.total_animals > 0 
      ? parseFloat(((count as number / animalStats.total_animals) * 100).toFixed(2)) 
      : 0,
    color: getStatusColor(status)
  }));
}

/**
 * Convierte datos de Potreros a formato de gráfico
 */
export function fieldStatsToChartData(fieldStats: Record<string, any>): ChartDataItem[] {
  const states = ['available', 'occupied', 'maintenance', 'restricted'];
  const total = fieldStats.total_fields || 0;

  return states
    .filter(state => fieldStats[state] > 0)
    .map(state => ({
      status: STATUS_LABELS[state as keyof typeof STATUS_LABELS] || state,
      count: fieldStats[state],
      percentage: total > 0 
        ? parseFloat(((fieldStats[state] / total) * 100).toFixed(2)) 
        : 0,
      color: getFieldStateColor(state)
    }));
}

/**
