    'restricted': CHART_COLORS.inactive
  };
  return colorMap[state] || CHART_COLORS.neutral;
}

/**
 * Normaliza respuesta de API extrayendo datos principales
 */
export function extractApiData<T>(response: any): T {
  // Casos comunes de estructura de respuesta
  if (response?.data?.data) return response.data.data;
  if (response?.data) return response.data;
  return response;
}

/**
 * Normaliza array de respuesta de API
 */
export function extractApiArray<T>(response: any, preferredKeys: string[] = []): T[] {
  const data = extractApiData(response);
  
  // Si ya es array, retornarlo
  if (Array.isArray(data)) return data as T[];
  
  // Si data no es objeto, retornar array vacío
  if (!data || typeof data !== 'object') return [];
  
  const dataObj = data as Record<string, any>;
  
  // Buscar en keys preferidas
  for (const key of preferredKeys) {
    if (dataObj[key] && Array.isArray(dataObj[key])) {
      return dataObj[key] as T[];
    }
  }
  
  // Keys comunes para arrays
  const commonArrayKeys = ['items', 'results', 'list', 'data'];
  for (const key of commonArrayKeys) {
    if (dataObj[key] && Array.isArray(dataObj[key])) {
      return dataObj[key] as T[];
    }
  }
  
  // Si no es array, envolver en array
  return data ? [data as T] : [];
}

/**
 * Valida y normaliza datos JSON
 */
export function normalizeJsonData<T>(data: any): T | null {
  try {
    // Si es string, intentar parsear
    if (typeof data === 'string') {
      return JSON.parse(data);
    }
    
    // Si es objeto válido, retornarlo
    if (data && typeof data === 'object') {
      return data;
    }
    
    return null;
  } catch (error) {
    console.warn('[JSON] Error parsing data:', error);
    return null;
  }
}

/**
 * Sanitiza parámetros de consulta removiendo valores undefined/null
 */
export function sanitizeQueryParams(params: Record<string, any>): Record<string, any> {
  const sanitized: Record<string, any> = {};
  
  Object.entries(params).forEach(([key, value]) => {
    if (value !== undefined && value !== null && value !== '') {
      sanitized[key] = value;
    }
  });
  
  return sanitized;
}

/**
 * Convierte datos a formato CSV para exportación
 */
export function dataToCSV<T extends Record<string, any>>(
  data: T[], 
  headers?: Record<keyof T, string>
): string {
  if (!data.length) return '';
  
  const keys = Object.keys(data[0]) as (keyof T)[];
  const headerRow = headers 
    ? keys.map(key => headers[key] || String(key)).join(',')
    : keys.join(',');
  
  const dataRows = data.map(item => 
    keys.map(key => {
      const value = item[key];
      // Escapar comillas y envolver en comillas si contiene comas
      const stringValue = String(value || '');
      return stringValue.includes(',') || stringValue.includes('"') 
        ? `"${stringValue.replace(/"/g, '""')}"` 
        : stringValue;
    }).join(',')
  );
  
  return [headerRow, ...dataRows].join('\n');
}

/**
 * Descarga datos como archivo JSON
 */
export function downloadAsJSON(data: any, filename: string): void {
  const jsonString = JSON.stringify(data, null, 2);
  const blob = new Blob([jsonString], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  
  const link = document.createElement('a');
  link.href = url;
  link.download = filename.endsWith('.json') ? filename : `${filename}.json`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}

/**
 * Descarga datos como archivo CSV
 */
export function downloadAsCSV<T extends Record<string, any>>(
  data: T[], 
  filename: string,
  headers?: Record<keyof T, string>
): void {
  const csvContent = dataToCSV(data, headers);
  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  
  const link = document.createElement('a');
  link.href = url;
  link.download = filename.endsWith('.csv') ? filename : `${filename}.csv`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}

/**
 * Debounce function para optimizar llamadas a API
 */
export function debounce<T extends (...args: any[]) => any>(
  func: T,
  wait: number
): (...args: Parameters<T>) => void {
  let timeout: ReturnType<typeof setTimeout>;
  return (...args: Parameters<T>) => {
    clearTimeout(timeout);
    timeout = setTimeout(() => func(...args), wait);
  };
}

/**
 * Retry function para llamadas a API con fallos
 */
export async function withRetry<T>(
  fn: () => Promise<T>,
  maxAttempts: number = 3,
  delay: number = 1000
): Promise<T> {
  let lastError: Error;
  
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error as Error;
      
      if (attempt === maxAttempts) {
        throw lastError;
      }
      
      // Exponential backoff
      await new Promise(resolve => setTimeout(resolve, delay * Math.pow(2, attempt - 1)));
    }
  }
  
  throw lastError!;
}

/**
 * Funciones de utilidad para manejo de fechas con zona horaria de Colombia
 */

/**
 * Obtiene la fecha actual en formato YYYY-MM-DD para la zona horaria de Colombia (America/Bogota)
 * @returns {string} Fecha actual en formato YYYY-MM-DD
 */
export const getTodayColombia = (): string => {
  const now = new Date();
  
  // Opción 1: Usar toLocaleString con zona horaria específica
  const colombiaDate = new Date(now.toLocaleString("en-US", { timeZone: "America/Bogota" }));
  
  // Formatear a YYYY-MM-DD
  const year = colombiaDate.getFullYear();
  const month = String(colombiaDate.getMonth() + 1).padStart(2, '0');
  const day = String(colombiaDate.getDate()).padStart(2, '0');
  
  return `${year}-${month}-${day}`;
};

/**
 * Obtiene la fecha y hora actual en formato ISO para la zona horaria de Colombia
 * @returns {string} Fecha y hora actual en formato ISO con zona horaria de Colombia
 */
export const getNowColombiaISO = (): string => {
  const now = new Date();
  
  // Usar toLocaleString con zona horaria específica y luego formatear
  const colombiaDate = new Date(now.toLocaleString("en-US", { timeZone: "America/Bogota" }));
  
  const year = colombiaDate.getFullYear();
  const month = String(colombiaDate.getMonth() + 1).padStart(2, '0');
  const day = String(colombiaDate.getDate()).padStart(2, '0');
  const hours = String(colombiaDate.getHours()).padStart(2, '0');
  const minutes = String(colombiaDate.getMinutes()).padStart(2, '0');
  const seconds = String(colombiaDate.getSeconds()).padStart(2, '0');
  
  return `${year}-${month}-${day}T${hours}:${minutes}:${seconds}`;
};

/**
 * Convierte una fecha a formato YYYY-MM-DD en la zona horaria de Colombia
 * @param {Date | string} date - Fecha a convertir
 * @returns {string} Fecha en formato YYYY-MM-DD
 */
export const formatDateColombia = (date: Date | string): string => {
  const dateObj = typeof date === 'string' ? new Date(date) : date;
  
  // Usar toLocaleString con zona horaria específica
  const colombiaDate = new Date(dateObj.toLocaleString("en-US", { timeZone: "America/Bogota" }));
  
  const year = colombiaDate.getFullYear();
  const month = String(colombiaDate.getMonth() + 1).padStart(2, '0');
  const day = String(colombiaDate.getDate()).padStart(2, '0');
  
  return `${year}-${month}-${day}`;
};

/**
 * Verifica si una fecha es hoy en la zona horaria de Colombia
 * @param {Date | string} date - Fecha a verificar
 * @returns {boolean} True si la fecha es hoy
 */
export const isTodayColombia = (date: Date | string): boolean => {
  const today = getTodayColombia();
  const dateToCheck = formatDateColombia(date);
  return today === dateToCheck;
};

/**
 * Calcula la edad en años, meses y días a partir de una fecha de nacimiento
 * @param {string} birthDate - Fecha de nacimiento en formato YYYY-MM-DD
 * @returns {string} Edad formateada (ej: "2 años, 3 meses")
 */
export const calculateAge = (birthDate: string): string => {
  if (!birthDate) return '';
  
  const birth = new Date(birthDate);
  const now = new Date();
  
  let years = now.getFullYear() - birth.getFullYear();
  let months = now.getMonth() - birth.getMonth();
  let days = now.getDate() - birth.getDate();
  
  if (days < 0) {
    months -= 1;
    const lastMonth = new Date(now.getFullYear(), now.getMonth(), 0);
    days += lastMonth.getDate();
  }
  
  if (months < 0) {
    years -= 1;
    months += 12;
  }
  
  const parts = [];
  if (years > 0) parts.push(`${years} ${years === 1 ? 'año' : 'años'}`);
  if (months > 0) parts.push(`${months} ${months === 1 ? 'mes' : 'meses'}`);
  if (years === 0 && months === 0 && days >= 0) parts.push(`${days} ${days === 1 ? 'día' : 'días'}`);
  
  return parts.length > 0 ? parts.join(', ') : '0 días';
};

