import type { FieldErrors } from '@/shared/utils/formValidation';
import type { CRUDFormField, CRUDFormSection } from '@/widgets/admin-crud';

export function buildFieldLabelMap(sections: CRUDFormSection<any>[]): Record<string, string> {
  const map: Record<string, string> = {};
  (sections || []).forEach((section) => {
    (section.fields || []).forEach((field) => {
      map[String(field.name)] = field.label || String(field.name);
    });
  });
  return map;
}

export function mapBackendFieldErrorsToLabels(
  fieldErrors: Record<string, any> | any[],
  sections: CRUDFormSection<any>[]
): { errors: FieldErrors; messages: string[] } {
  const labelMap = buildFieldLabelMap(sections);
  const errors: FieldErrors = {};
  const messages: string[] = [];

  // Convert empty/null to empty object
  const rawErrors = fieldErrors || {};

  // Case 1: Array of errors (e.g., duplicated unique constraint)
  if (Array.isArray(rawErrors)) {
    rawErrors.forEach((errorObj, index) => {
      // If it's a string, try to map it by content
      if (typeof errorObj === 'string') {
        const mapped = attemptToMapMessageToField(errorObj, labelMap);
        if (mapped.field) {
          errors[mapped.field] = errorObj;
          messages.push(mapped.label ? `${mapped.label}: ${errorObj}` : errorObj);
        } else {
          messages.push(errorObj);
        }
      }
      // If it's an object, check for field/msg pattern
      else if (typeof errorObj === 'object' && errorObj !== null) {
        const field = errorObj.field || errorObj.attr || errorObj.name || String(index);
        const msg = errorObj.message || errorObj.msg || JSON.stringify(errorObj);
        const label = labelMap[String(field)] || String(field);

        errors[String(field)] = msg;
        messages.push(`${label}: ${msg}`);
      }
    });
  }
  // Case 2: Object with field keys
  else {
    Object.entries(rawErrors).forEach(([field, raw]) => {
      const label = labelMap[String(field)] || String(field);
      const msg = Array.isArray(raw) ? raw.join(', ') : String(raw);

      // Special check: If field is numeric string (like "0"), it usually means an array index was wrongly mapped
      // Attempt to map by message content in this case
      if (/^\d+$/.test(field)) {
        const mapped = attemptToMapMessageToField(msg, labelMap);
        if (mapped.field) {
          errors[mapped.field] = msg;
          messages.push(`${mapped.label}: ${msg}`);
          return;
        }
      }

      errors[String(field)] = msg;
      messages.push(`${label}: ${msg}`);
    });
  }

  return { errors, messages };
}

/**
 * Helper to attempt mapping an error message to a field by looking for field names in quotes
 * e.g., "El valor 'Bovino' ya existe para el campo 'name'" -> maps to field 'name'
 */
function attemptToMapMessageToField(
  message: string,
  labelMap: Record<string, string>
): { field?: string; label?: string } {
  // Pattern to look for 'field' or 'campo' followed by the name in quotes or backticks
  // Also looks for just the name in quotes/backticks
  const fieldNames = Object.keys(labelMap);

  for (const name of fieldNames) {
    // Exact match in quotes/backticks
    const regex = new RegExp(`['"\`]${name}['"\`]`, 'i');
    if (regex.test(message)) {
      return { field: name, label: labelMap[name] };
    }

    // Try mapping by label too
    const label = labelMap[name];
    if (label && label.length > 2) {
      const labelRegex = new RegExp(`['"\`]${label}['"\`]`, 'i');
      if (labelRegex.test(message)) {
        return { field: name, label };
      }
    }
  }

  return {};
}

export function formatValidationToastMessage(messages: string[], maxItems = 3): string {
  if (!Array.isArray(messages) || messages.length === 0) return 'Errores de validacion. Revisa los campos.';
  const preview = messages.slice(0, maxItems).join(' | ');
  const suffix = messages.length > maxItems ? ` y ${messages.length - maxItems} mas` : '';
  return `Faltan datos o hay errores. Corrija: ${preview}${suffix}`;
}

export function formatRequiredHint(field: CRUDFormField<any>): string {
  if (!field.required) return '';
  if (field.type === 'select' || field.type === 'searchable-select') {
    return `Debe seleccionar ${String(field.label || field.name).toLowerCase()}.`;
  }
  return 'Este campo es obligatorio.';
}

export function buildConflictMessage(
  details: any,
  sections: CRUDFormSection<any>[]
): { message: string; field?: string } {
  const labelMap = buildFieldLabelMap(sections);
  const valErrors =
    details?.validation_errors ||
    details?.errors ||
    undefined;
  if (valErrors && typeof valErrors === 'object') {
    const entries = Object.entries(valErrors);
    if (entries.length > 0) {
      const [firstField, raw] = entries[0];
      const label = labelMap[String(firstField)] || String(firstField);
      const msg = Array.isArray(raw) ? raw.join(', ') : String(raw);
      const message = `${label}: ${msg}. Cambie el valor o seleccione otro.`;
      return { message, field: String(firstField) };
    }
  }
  const errStr: string | undefined =
    typeof details?.error === 'string' ? details.error :
      typeof details === 'string' ? details :
        undefined;
  if (errStr) {
    const m = /Duplicate entry '([^']+)' for key '([^']+)'/i.exec(errStr);
    if (m) {
      const value = m[1];
      const key = m[2];
      const field = key.includes('.') ? key.split('.').pop() : key;
      const label = labelMap[String(field || '')] || String(field || 'campo');
      const message = `El ${label} "${value}" ya existe. Cambie el valor o seleccione otro.`;
      return { message, field: field ? String(field) : undefined };
    }
  }
  const fallback = typeof details?.error === 'string' ? details.error : '';
  const message = fallback && fallback.trim().length
    ? `${fallback}. Cambie el valor o seleccione otro.`
    : 'Violación de unicidad. Cambie el valor o seleccione otro.';
  return { message };
}

/// <reference lib="webworker" />
import { precacheAndRoute, matchPrecache } from 'workbox-precaching';
import { registerRoute, setCatchHandler } from 'workbox-routing';
import { CacheFirst, StaleWhileRevalidate, NetworkFirst } from 'workbox-strategies';
import { ExpirationPlugin } from 'workbox-expiration';
import { BackgroundSyncPlugin, Queue } from 'workbox-background-sync';

declare const self: ServiceWorkerGlobalScope;

// Precache de assets generados en el build
precacheAndRoute(self.__WB_MANIFEST);

// ─────────────────────────────────────────────────────────────
// BackgroundSync — cola de escrituras para modo sin señal
// Las operaciones POST/PUT/PATCH/DELETE quedan encoladas y se
// reenvían automáticamente cuando vuelve la conexión.
// ─────────────────────────────────────────────────────────────
const offlineQueue = new Queue('finca-offline-writes', {
  maxRetentionTime: 7 * 24 * 60, // 7 días en minutos
  onSync: async ({ queue }) => {
    let entry: { request: Request } | undefined;
    while ((entry = await queue.shiftRequest())) {
      try {
        await fetch(entry.request.clone());
        // Notificar al cliente que la sincronización fue exitosa
        const clients = await self.clients.matchAll();
        clients.forEach(c => c.postMessage({ type: 'OFFLINE_SYNC_SUCCESS', url: entry!.request.url }));
      } catch (err) {
        await queue.unshiftRequest(entry);
        throw err; // Fuerza reintento posterior
      }
    }
  },
});

// Interceptar mutaciones a la API para BackgroundSync
registerRoute(
  ({ url, request }) =>
    url.pathname.startsWith('/api/v1/') &&
    ['POST', 'PUT', 'PATCH', 'DELETE'].includes(request.method),
  async ({ event }) => {
    const fetchEvent = event as FetchEvent;
    try {
      return await fetch(fetchEvent.request.clone());
    } catch {
      await offlineQueue.pushRequest(fetchEvent);
      return new Response(
        JSON.stringify({ queued: true, message: 'Operación guardada. Se enviará cuando haya señal.' }),
        { status: 202, headers: { 'Content-Type': 'application/json' } }
      );
    }
  },
  'POST'
);

// ─────────────────────────────────────────────────────────────
// Caché de imágenes (30 días, CacheFirst)
// ─────────────────────────────────────────────────────────────
registerRoute(
  ({ request }) => request.destination === 'image',
  new CacheFirst({
    cacheName: 'images',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 60,
        maxAgeSeconds: 30 * 24 * 60 * 60,
      }),
    ],
  })
);

// ─────────────────────────────────────────────────────────────
// Caché de fuentes (1 año)
// ─────────────────────────────────────────────────────────────
registerRoute(
  ({ request }) => request.destination === 'font',
  new CacheFirst({
    cacheName: 'fonts',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 10,
        maxAgeSeconds: 365 * 24 * 60 * 60,
      }),
    ],
  })
);

// ─────────────────────────────────────────────────────────────
// Caché de Mapas (Tiles) - Crítico para navegación en potreros
// ─────────────────────────────────────────────────────────────
registerRoute(
  ({ url }) => 
    url.hostname.includes('tile.openstreetmap.org') || 
    url.hostname.includes('basemaps.cartocdn.com') ||
    url.hostname.includes('tile.thunderforest.com'),
  new CacheFirst({
    cacheName: 'map-tiles',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 500, // Suficiente para cubrir una finca grande en varios niveles de zoom
        maxAgeSeconds: 30 * 24 * 60 * 60, // 30 días
      }),
    ],
  })
);

// ─────────────────────────────────────────────────────────────
// Caché de Documentos (Biblioteca Rural)
// ─────────────────────────────────────────────────────────────
registerRoute(
  ({ request, url }) => 
    request.destination === 'document' || 
    url.pathname.match(/\.(pdf|docx?|xlsx?|pptx?)$/),
  new CacheFirst({
    cacheName: 'documents',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 100,
        maxAgeSeconds: 60 * 24 * 60 * 60, // 60 días
      }),
    ],
  })
);

// ─────────────────────────────────────────────────────────────
// Datos maestros (catálogos globales que cambian poco)
// StaleWhileRevalidate: sirve de caché inmediatamente, revalida en background
// ─────────────────────────────────────────────────────────────
registerRoute(
  ({ url }) =>
    url.pathname.includes('/api/v1/breeds') ||
    url.pathname.includes('/api/v1/species') ||
    url.pathname.includes('/api/v1/food_types') ||
    url.pathname.includes('/api/v1/food-types') ||
    url.pathname.includes('/api/v1/vaccines') ||
    url.pathname.includes('/api/v1/medications') ||
    url.pathname.includes('/api/v1/route-administrations') ||
    url.pathname.includes('/api/v1/diseases') ||
    url.pathname.includes('/api/v1/fincas') ||
    url.pathname.includes('/api/v1/auth/me') ||
    // Base de Conocimiento Agropecuario (Recomendaciones + Calendario ICA)
    url.pathname.includes('/api/v1/knowledge_base'),
  new StaleWhileRevalidate({
    cacheName: 'master-data-cache',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 150,
        maxAgeSeconds: 24 * 60 * 60,
      }),
    ],
  })
);

// ─────────────────────────────────────────────────────────────
// Datos de campo (lo que el campesino consulta en el potrero)
// NetworkFirst con fallback a caché — hasta 12h de antigüedad
// ─────────────────────────────────────────────────────────────
registerRoute(
  ({ url }) =>
    url.pathname.includes('/api/v1/animals') ||
    url.pathname.includes('/api/v1/animal_fields') ||
    url.pathname.includes('/api/v1/animal-diseases') ||
    url.pathname.includes('/api/v1/treatments') ||
    url.pathname.includes('/api/v1/vaccinations') ||
    url.pathname.includes('/api/v1/control') ||
    url.pathname.includes('/api/v1/fields'),
  new NetworkFirst({
    cacheName: 'field-data-cache',
    networkTimeoutSeconds: 4,
    plugins: [
      new ExpirationPlugin({
        maxEntries: 300,
        maxAgeSeconds: 12 * 60 * 60,
      }),
    ],
  })
);

// ─────────────────────────────────────────────────────────────
// Analytics y reportes (StaleWhileRevalidate, 1 hora)
// ─────────────────────────────────────────────────────────────
registerRoute(
  ({ url }) =>
    url.pathname.includes('/api/v1/analytics') ||
    url.pathname.includes('/api/v1/reports'),
  new StaleWhileRevalidate({
    cacheName: 'analytics-cache',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 30,
        maxAgeSeconds: 60 * 60,
      }),
    ],
  })
);

// ─────────────────────────────────────────────────────────────
// Navegación SPA (NetworkFirst con fallback al shell)
// ─────────────────────────────────────────────────────────────
registerRoute(
  ({ request }) => request.mode === 'navigate',
  new NetworkFirst({
    cacheName: 'pages',
    networkTimeoutSeconds: 3,
    plugins: [
      new ExpirationPlugin({
        maxEntries: 10,
        maxAgeSeconds: 24 * 60 * 60,
      }),
    ],
  })
);

// ─────────────────────────────────────────────────────────────
// Fallback offline: cuando navegación falla sin caché → offline.html
// ─────────────────────────────────────────────────────────────
setCatchHandler(async ({ event }) => {
  const req = (event as FetchEvent).request;
  if (req.mode === 'navigate') {
    // Intentar el shell SPA primero (precacheado)
    const shell = await matchPrecache('/index.html');
    if (shell) return shell;
    // Último recurso: offline.html estático en public/
    const offlinePage = await caches.match('/offline.html');
    if (offlinePage) return offlinePage;
  }
  return Response.error();
});

// ─────────────────────────────────────────────────────────────
// Notificaciones Push
// ─────────────────────────────────────────────────────────────
self.addEventListener('push', (event) => {
  if (event.data) {
    try {
      const data = event.data.json();
      const title = data.title || 'Finca Villa Luz';
      const options = {
        body: data.body || 'Tienes una nueva notificación',
        icon: '/pwa-192x192.png',
        badge: '/pwa-192x192.png',
        data: { url: data.url || '/' },
        actions: [{ action: 'open', title: 'Ver detalle' }],
      };
      event.waitUntil(self.registration.showNotification(title, options));
    } catch (err) {
      console.error('Error al recibir notificación push:', err);
    }
  }
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const url = event.notification.data?.url || '/';

  event.waitUntil(
    self.clients.matchAll({ type: 'window' }).then((clientList) => {
      for (const client of clientList) {
        if (client.url === url && 'focus' in client) return client.focus();
      }
      if (self.clients.openWindow) return self.clients.openWindow(url);
    })
  );
});

// ─────────────────────────────────────────────────────────────
// Notificar al cliente cuando BackgroundSync completa
// ─────────────────────────────────────────────────────────────
self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') self.skipWaiting();
});

