import { useLocation, useNavigate, useSearchParams } from 'react-router-dom';
import { useResource } from '@/shared/hooks/useResource';
import { useToast } from '@/app/providers/ToastContext';
import { useT } from '@/shared/i18n';

// Componentes especializados
import { CRUDTable } from './CRUDTable';
import { CRUDForm } from './CRUDForm';
import { CRUDPagination } from './CRUDPagination';
import { DetailModal, ConfirmDeleteDialog } from './CRUDModals';
import { CRUDToolbar } from './CRUDToolbar';
import { FKDetailModal } from './FKDetailModal';

// Componentes de UI
import { AppLayout } from '@/widgets/layout/AppLayout';
import { PageHeader } from '@/widgets/layout/PageHeader';
import { EmptyState } from '@/widgets/feedback/EmptyState';
import { ErrorState } from '@/widgets/feedback/ErrorState';
import { SkeletonTable } from '@/widgets/feedback/SkeletonTable';
import { Card, CardContent } from '@/shared/ui/card';
import { Button } from '@/shared/ui/button';
import { Plus } from 'lucide-react';

// Utilidades
import { addTombstone, getTombstoneIds, clearExpired } from '@/shared/api/cache/tombstones';
import { validateFormSections, type FieldErrors } from '@/shared/utils/formValidation';
import { formatValidationToastMessage, mapBackendFieldErrorsToLabels, buildConflictMessage } from '@/shared/utils/validationMessages';

// Interfaces
import type { CRUDConfig, CRUDFormField } from '../../../shared/types/crud';

interface AdminCRUDPageProps<T extends { id: number }, TInput extends Record<string, any>> {
  config: CRUDConfig<T, TInput>;
  service: any; // BaseService instance
  initialFormData: TInput;
  mapResponseToForm?: (item: T) => TInput;
  validateForm?: (formData: TInput) => string | null;
  customDetailContent?: (item: T, navigateToItem?: (item: T) => void) => React.ReactNode;
  onFormDataChange?: (formData: TInput) => void;
  // Opciones de tiempo real
  realtime?: boolean;
  pollIntervalMs?: number;
  refetchOnFocus?: boolean;
  refetchOnReconnect?: boolean;
  // Opciones de estilo hover personalizado
  enhancedHover?: boolean;
  // Contenido adicional para el formulario
  additionalFormContent?: (formData: TInput, editingItem: T | null) => React.ReactNode;
  // Acciones por lotes (Batch Actions)
  renderBatchActions?: (
    selectedIds: number[],
    clearSelection: () => void,
    refetch: () => Promise<void>,
    selectedItems: T[]
  ) => React.ReactNode;
}

export function AdminCRUDPage<T extends { id: number }, TInput extends Record<string, any>>({
  config,
  service,
  initialFormData,
  mapResponseToForm,
  validateForm,
  customDetailContent,
  onFormDataChange: _onFormDataChange,
  realtime,
  pollIntervalMs,
  refetchOnFocus,
  refetchOnReconnect,
  enhancedHover = false,
  additionalFormContent,
  renderBatchActions,
}: AdminCRUDPageProps<T, TInput>) {
  // Estados simplificados
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<T | null>(null);
  const [saving, setSaving] = useState(false);
  const [formData, setFormData] = useState<TInput>(initialFormData);
  const [formErrors, setFormErrors] = useState<FieldErrors>({});
  const [formErrorMessages, setFormErrorMessages] = useState<string[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [isMobile, setIsMobile] = useState(() => typeof window !== 'undefined' ? window.innerWidth < 768 : false);
  const [deletingItems, setDeletingItems] = useState<Set<string>>(new Set());
  const [selectedIds, setSelectedIds] = useState<number[]>([]);

  const toggleSelect = useCallback((id: number) => {
    setSelectedIds(prev => 
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  }, []);

  const clearSelection = useCallback(() => setSelectedIds([]), []);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const effectiveViewMode = config.viewMode || (isMobile ? 'cards' : 'table');

  const updateFieldValue = useCallback((field: CRUDFormField<TInput>, value: any) => {
    const key = String(field.name);
    const nextData = { ...(formData as any), [key]: value } as TInput;
    const validation = validateFormSections(config.formSections || [], nextData as any);
    setFormErrors(validation.errors);
    setFormErrorMessages(validation.messages);
    setFormData(nextData);
  }, [formData, config.formSections]);

  // Estados para modales
  const [isDetailOpen, setIsDetailOpen] = useState(false);
  const [detailItem, setDetailItem] = useState<T | null>(null);
  const [detailIndex, setDetailIndex] = useState<number | null>(null);
  const editRequestSeqRef = useRef(0);
  const suppressEditAutoOpenRef = useRef(false);
  const lastClosedEditIdRef = useRef<number | null>(null);

  // Estados para confirmación
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [targetId, setTargetId] = useState<number | null>(null);

  // Estados para FK Detail
  const [fkDetail, setFkDetail] = useState<{ entity: string; id: number } | null>(null);
  const [isFKDetailOpen, setIsFKDetailOpen] = useState(false);

  // Hooks y utilidades
  const { showToast } = useToast();
  const t = useT();
  const location = useLocation();
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();

  // Clave de entidad para tombstones persistentes
  const entityKey = useMemo(() => (config.entityName || 'entity').toLowerCase(), [config.entityName]);

  // Limpiar tombstones expirados al montar
  useEffect(() => {
    clearExpired(entityKey);
  }, [entityKey]);

  // Configuración de recursos
  const {
    data: items,
    loading,
    error,
    meta,
    setPage,
    setLimit: _setLimit,
    setSearch,
    createItem,
    updateItem,
    deleteItem,
    refetch,
    refreshing,
  } = useResource<T, any>(service as any, {
    autoFetch: true,
    initialParams: {
      page: 1,
      limit: 10,
      fields: config.defaultFields,
      ...(config.additionalFilters || {})
    },
    enableRealtime: realtime === true,
    pollIntervalMs: typeof pollIntervalMs === 'number' ? pollIntervalMs : undefined,
    refetchOnFocus,
    refetchOnReconnect,
  });

  // Paginación
  const pageFromURL = parseInt((searchParams.get('page') || '').toString(), 10);
  const currentPage = Number.isFinite(pageFromURL) && pageFromURL > 0 ? pageFromURL : (meta?.page || 1);
  const pageSize = meta?.limit || 10;
  const totalItems = meta?.total || 0;
  const totalPages = meta?.totalPages || Math.ceil(totalItems / pageSize);

  // Filtrar items para excluir tombstones
  const filteredItems = useMemo(() => {
    const tombstoneIds = getTombstoneIds(entityKey);
    return (items || []).filter((i: T) => {
      const idStr = String((i as any).id);
      return !tombstoneIds.has(idStr);
    });
  }, [items, entityKey]);

  const handleOpenFKDetail = useCallback((entity: string, id: number) => {
    setFkDetail({ entity, id });
    setIsFKDetailOpen(true);
  }, []);

  // Handlers
  const openCreate = useCallback(() => {
    setEditingItem(null);
    setFormData(JSON.parse(JSON.stringify(initialFormData)));
    setFormErrors({});
    setFormErrorMessages([]);
    setIsModalOpen(true);
  }, [initialFormData]);

  const openEdit = useCallback((item: T) => {
    setEditingItem(item);
    const formValues = mapResponseToForm ? mapResponseToForm(item) : (item as unknown as TInput);
    setFormData(formValues);
    setFormErrors({});
    setFormErrorMessages([]);
    setIsModalOpen(true);
  }, [mapResponseToForm]);

  const openDetail = useCallback((item: T) => {
    const idx = filteredItems.findIndex((i) => i.id === item.id);
    const safeIndex = idx >= 0 ? idx : 0;
    setDetailIndex(safeIndex);
    setDetailItem(filteredItems[safeIndex] || item);
    setIsDetailOpen(true);
  }, [filteredItems]);

  const openDeleteConfirm = useCallback((id: number) => {
    setTargetId(id);
    setConfirmOpen(true);
  }, []);

  const handleModalClose = useCallback(() => {
    if (editingItem?.id) {
      editRequestSeqRef.current += 1;
      suppressEditAutoOpenRef.current = true;
      lastClosedEditIdRef.current = editingItem.id;
    } else {
      suppressEditAutoOpenRef.current = false;
      lastClosedEditIdRef.current = null;
    }
    setIsModalOpen(false);
    setFormData(JSON.parse(JSON.stringify(initialFormData)));
    setFormErrors({});
    setFormErrorMessages([]);
    setEditingItem(null);

    const sp = new URLSearchParams(searchParams);
    let changed = false;
    if (sp.has('create')) { sp.delete('create'); changed = true; }
    if (sp.has('edit')) { sp.delete('edit'); changed = true; }
    if (changed) {
      setSearchParams(sp, { replace: true });
    } else if (location.pathname.includes('form')) {
      navigate(-1);
    }
  }, [initialFormData, searchParams, setSearchParams, navigate, location.pathname, editingItem]);

  const handleSubmit = useCallback(async (e: React.FormEvent) => {
    e.preventDefault();

    const validation = validateFormSections(config.formSections || [], formData as any);
    if (validation.messages.length > 0) {
      setFormErrors(validation.errors);
      setFormErrorMessages(validation.messages);
      showToast(formatValidationToastMessage(validation.messages), 'error');
      const firstKey = Object.keys(validation.errors)[0];
      if (firstKey && typeof window !== 'undefined') {
        setTimeout(() => {
          const el = document.getElementById(firstKey);
          if (el && 'focus' in el) {
            el.scrollIntoView({ behavior: 'smooth', block: 'center' });
            (el as HTMLElement).focus();
          }
        }, 0);
      }
      return;
    }

    if (validateForm) {
      const validationError = validateForm(formData);
      if (validationError) {
        showToast(validationError, 'warning');
        return;
      }
    }

    setSaving(true);

    try {
      if (editingItem?.id) {
        const result = await updateItem(editingItem.id, formData as any);
        showToast(`✅ ${config.entityName} actualizado correctamente`, 'success');
        if (config.onAfterUpdate) {
          try {
            await config.onAfterUpdate(result);
          } catch (err) {
            console.error('Error in onAfterUpdate hook:', err);
          }
        }
      } else {
        const result = await createItem(formData as any);
        showToast(`✅ ${config.entityName} creado correctamente`, 'success');

        if (config.onAfterCreate) {
          try {
            await config.onAfterCreate(result);
          } catch (err) {
            console.error('Error in onAfterCreate hook:', err);
          }
        }

        // Volver a la página 1 después de crear
        if (setPage && meta?.page && meta.page > 1) {
          setPage(1);
        }
      }

      handleModalClose();

      // Refrescar datos después de un breve delay
      setTimeout(async () => {
        try {
          await refetch();
        } catch (error) {
          console.error('Error al refrescar datos:', error);
        }
      }, 300);
    } catch (error: any) {
      let errorMessage = `${t('crud.save_error', 'Error al guardar')} ${config.entityName.toLowerCase()}`;

      if (error?.response?.data?.message) {
        errorMessage = error.response.data.message;
      } else if (error?.response?.data?.detail) {
        errorMessage = error.response.data.detail;
      } else if (error?.message) {
        errorMessage = error.message;
      }

      const validationErrors =
        (error as any)?.validationErrors ||
        (error as any)?.details?.validation_errors ||
        (error as any)?.details?.errors ||
        error?.response?.data?.errors;

      if (validationErrors && typeof validationErrors === 'object') {
        const mapped = mapBackendFieldErrorsToLabels(validationErrors, config.formSections || []);
        if (Object.keys(mapped.errors).length > 0) {
          setFormErrors(mapped.errors);
          setFormErrorMessages(mapped.messages);
          errorMessage = formatValidationToastMessage(mapped.messages);
        }
      } else if (
        typeof errorMessage === 'string' &&
        errorMessage.toLowerCase().includes('validaci') &&
        formErrorMessages.length > 0
      ) {
        errorMessage = formatValidationToastMessage(formErrorMessages);
      }

      const status = (error as any)?.status ?? error?.response?.status;
      if (status === 409) {
        const traceId =
          (error as any)?.traceId ||
          error?.response?.data?.error?.trace_id ||
          error?.response?.data?.error?.traceId ||
          error?.response?.data?.trace_id ||
          error?.response?.data?.traceId;
        const details =
          (error as any)?.details ??
          error?.response?.data?.error?.details ??
          error?.response?.data?.details;
        const conflict = buildConflictMessage(details, config.formSections || []);
        const suffix = traceId ? ` (Trace ID: ${traceId})` : '';
        errorMessage = `${conflict.message}${suffix}`;
        if (conflict.field) {
          try {
            setFormErrors(prev => ({ ...(prev || {}), [String(conflict.field)]: conflict.message }));
            setFormErrorMessages(prev => [conflict.message, ...(Array.isArray(prev) ? prev : [])]);
          } catch { /* noop */ }
        }
      }

      showToast(errorMessage, 'error');
    } finally {
      setSaving(false);
    }
  }, [formData, validateForm, editingItem, updateItem, createItem, setPage, meta, handleModalClose, refetch, config.entityName, config.formSections, t, showToast, setFormErrors, setFormErrorMessages, formErrorMessages]);

  const handleConfirmDelete = useCallback(async () => {
    if (targetId == null) return;

    const idToDelete = targetId;
    setConfirmOpen(false);
    setTargetId(null);

    try {
      setDeletingItems(prev => new Set(prev).add(String(idToDelete)));
      const success = await deleteItem(idToDelete);

      if (success) {
        showToast(`🗑️ ${config.entityName} eliminado correctamente`, 'success');

        // Registrar tombstone para ocultar temporalmente si el backend aún lo devuelve
        addTombstone(entityKey, String(idToDelete), 120000);

        // Cerrar modales si el item eliminado estaba abierto
        if (isDetailOpen && detailItem?.id === idToDelete) {
          setIsDetailOpen(false);
          setDetailIndex(null);
        }
        if (isModalOpen && editingItem?.id === idToDelete) {
          setIsModalOpen(false);
          setEditingItem(null);
        }

        // Verificar si después de eliminar, la página actual quedará vacía
        const currentPageItems = filteredItems.length - 1;
        const willBeEmpty = currentPageItems === 0;

        if (willBeEmpty && currentPage > 1 && setPage) {
          setPage(currentPage - 1);
        }

        // Refrescar después de un breve delay
        setTimeout(async () => {
          try {
            await refetch();
          } catch (error) {
            console.error('Error al refrescar datos después de eliminar:', error);
          }
        }, 300);
      }
    } catch (error: any) {
      let errorMessage = `Error al eliminar ${config.entityName.toLowerCase()}`;

      if (error?.response?.data?.message) {
        errorMessage = error.response.data.message;
      } else if (error?.response?.data?.detail) {
        errorMessage = error.response.data.detail;
      } else if (error?.message) {
        errorMessage = error.message;
      }

      showToast(errorMessage, 'error');
    } finally {
      setDeletingItems(prev => {
        const next = new Set(prev);
        next.delete(String(idToDelete));
        return next;
      });
    }
  }, [targetId, deleteItem, entityKey, isDetailOpen, detailItem, isModalOpen, editingItem, filteredItems, currentPage, setPage, refetch, config.entityName, showToast]);

  // Sincronizar búsqueda con URL
  useEffect(() => {
    const handle = setTimeout(() => {
      setSearchParams(prev => {
        const sp = new URLSearchParams(prev);
        if (searchQuery) sp.set('search', searchQuery);
        else sp.delete('search');
        sp.set('page', '1');
        return sp;
      }, { replace: true });

      if (setSearch) setSearch(searchQuery);
    }, 500);

    return () => clearTimeout(handle);
  }, [searchQuery, setSearchParams, setSearch]);

  // Sincronizar estado con URL
  useEffect(() => {
    const search = (searchParams.get('search') || '').toString();
    if (search !== searchQuery) {
      setSearchQuery(search);
    }
  }, [searchParams, searchQuery]);

  // Auto-open create modal via ?create=1
  useEffect(() => {
    if (config.enableCreateModal !== false) {
      const c = searchParams.get('create');
      if (c && !isModalOpen) {
        openCreate();
      }
    }
  }, [searchParams, config.enableCreateModal, isModalOpen, openCreate]);

  // Auto-open edit modal via ?edit=ID
  useEffect(() => {
    if (config.enableEditModal !== false) {
      const e = searchParams.get('edit');
      if (!e) {
        suppressEditAutoOpenRef.current = false;
        lastClosedEditIdRef.current = null;
        return;
      }
      if (suppressEditAutoOpenRef.current && e === String(lastClosedEditIdRef.current ?? '')) {
        return;
      }
      if (e) {
        const id = Number(e);
        if (!Number.isNaN(id) && (!isModalOpen || !editingItem || editingItem.id !== id)) {
          const requestSeq = editRequestSeqRef.current + 1;
          editRequestSeqRef.current = requestSeq;
          (async () => {
            try {
              const item = await service.getById(id);
              if (editRequestSeqRef.current !== requestSeq) {
                return;
              }
              const currentEdit = new URLSearchParams(window.location.search).get('edit');
              if (currentEdit !== String(id)) {
                return;
              }
              openEdit(item);
            } catch (err) {
              showToast(t('common.errorLoading', 'No se pudo cargar el registro para edición'), 'error');
              const sp = new URLSearchParams(searchParams);
              sp.delete('edit');
              setSearchParams(sp, { replace: true });
            }
          })();
        }
      }
    }
  }, [searchParams, config.enableEditModal, isModalOpen, editingItem, service, openEdit, showToast, t, setSearchParams]);

  // Header con búsqueda y botones
  const header = (
    <PageHeader
      title={config.title}
      dense
      className="mb-0 sm:mb-0 p-0 sm:p-1"
      titleClassName="text-lg sm:text-xl"
      actions={
        <CRUDToolbar
          searchQuery={searchQuery}
          setSearchQuery={setSearchQuery}
          searchPlaceholder={config.searchPlaceholder}
          onOpenCreate={config.enableCreateModal !== false ? openCreate : undefined}
          customToolbar={config.customToolbar}
        />
      }
    />
  );

  // Loading state
  if (loading && filteredItems.length === 0) {
    return (
      <AppLayout
        header={header}
        className="px-2 sm:px-3 pt-0 sm:pt-1 pb-0 max-w-full min-h-0"
        contentClassName="space-y-0"
      >
        <div className="bg-card/95 backdrop-blur-sm border-2 border-border/50 rounded-xl shadow-2xl shadow-primary/10 overflow-hidden">
          <SkeletonTable
            columnLabels={config.columns.map((c: any) => c.label)}
            columnWidths={config.columns.map((c: any) => c.width)}
            rows={8}
          />
        </div>
      </AppLayout>
    );
  }

  // Error state
  if (error) {
    return (
      <AppLayout
        header={header}
        className="px-2 sm:px-3 pt-1 sm:pt-2 pb-0 sm:pb-0 md:pb-0 lg:pb-0 max-w-full min-h-0"
        contentClassName="space-y-0"
      >
        <ErrorState
          message={String(error)}
          onRetry={() => window.location.reload()}
        />
      </AppLayout>
    );
  }

  // Empty state
  const empty = !loading && (filteredItems?.length || 0) === 0;

  return (
    <AppLayout
      header={header}
      className="px-2 sm:px-3 pt-0 sm:pt-1 pb-0 max-w-full min-h-0"
      contentClassName="space-y-2 flex-1 flex flex-col min-h-0 overflow-hidden"
    >
      <Card className="flex-1 flex flex-col min-h-0 border-2 border-border/50 bg-card/95 backdrop-blur-sm shadow-2xl shadow-primary/5 rounded-2xl overflow-hidden mb-2">
        <CardContent className="flex-1 flex flex-col p-0 min-h-0 overflow-hidden relative">
          {empty ? (
            <div className="flex-1 flex items-center justify-center p-8">
              <EmptyState
                title={`${t('common.noData', 'No hay')} ${config.title.toLowerCase()}`}
                description={t('common.noDataDescription', 'Comience agregando uno nuevo.')}
                action={
                  config.enableCreateModal !== false ? (
                    <Button onClick={openCreate} className="gap-2">
                      <Plus className="h-4 w-4" />
                      {t('common.add', 'Agregar')}
                    </Button>
                  ) : undefined
                }
              />
            </div>
          ) : (
            <>
              <div className="flex-1 min-h-0 overflow-hidden relative">
                <CRUDTable
                  items={filteredItems}
                  columns={config.columns}
                  config={config}
                  loading={loading || refreshing}
                  onEdit={config.enableEditModal !== false ? openEdit : undefined}
                  onDelete={config.enableDelete !== false ? openDeleteConfirm : undefined}
                  onDetail={config.enableDetailModal !== false ? openDetail : undefined}
                  enhancedHover={enhancedHover}
                  onOpenFKDetail={handleOpenFKDetail}
                  selectedIds={selectedIds}
                  onToggleSelect={toggleSelect}
                  deletingIds={deletingItems}
                />
              </div>

              {totalPages > 1 && (
                <div className="p-4 border-t bg-muted/30">
                  <CRUDPagination
                    currentPage={currentPage}
                    totalPages={totalPages}
                    onPageChange={setPage || (() => {})}
                    loading={loading}
                  />
                </div>
              )}
            </>
          )}
        </CardContent>
      </Card>

      {/* Batch Actions Toolbar */}
      {renderBatchActions && renderBatchActions(
        selectedIds,
        clearSelection,
        refetch,
        filteredItems.filter((item) => selectedIds.includes(item.id))
      )}

      {/* Modals */}
      {isModalOpen && (
        <CRUDForm<T, TInput>
          isOpen={isModalOpen}
          onClose={handleModalClose}
          title={editingItem ? `${t('common.edit', 'Editar')} ${config.entityName}: ${editingItem.id}` : `${t('common.create', 'Crear')} ${config.entityName}`}
          formData={formData}
          setFormData={setFormData as unknown as React.Dispatch<React.SetStateAction<Record<string, any>>>}
          formSections={config.formSections || []}
          fieldErrors={formErrors}
          errorMessages={formErrorMessages}
          onFieldValueChange={updateFieldValue}
          onSubmit={handleSubmit}
          saving={saving}
          editingItem={editingItem}
          showEditTimestamps={config.showEditTimestamps}
          additionalFormContent={additionalFormContent as any}
        />
      )}

      {/* Detail Modal */}
      {config.enableDetailModal !== false && (
        <DetailModal
          isOpen={isDetailOpen}
          onOpenChange={setIsDetailOpen}
          title={detailItem ? `Detalle del ${config.entityName}${config.showIdInDetailTitle === false ? '' : `: ${detailItem.id}`}` : `Detalle del ${config.entityName}`}
          item={detailItem}
          config={config}
          onEdit={config.enableEditModal !== false ? openEdit : undefined}
          customDetailContent={customDetailContent}
          showDetailTimestamps={config.showDetailTimestamps}
          showIdInDetailTitle={config.showIdInDetailTitle}
          detailIndex={detailIndex}
          setDetailIndex={setDetailIndex}
          items={filteredItems}
          setDetailItem={setDetailItem}
        />
      )}

      {/* Confirm Delete Dialog */}
      <ConfirmDeleteDialog
        open={confirmOpen}
        onOpenChange={setConfirmOpen}
        title={config.confirmDeleteTitle || '⚠️ Confirmar eliminación'}
        description={config.confirmDeleteDescription || `¿Está seguro que desea eliminar este ${config.entityName.toLowerCase()}? Esta acción no se puede deshacer.`}
        onConfirm={handleConfirmDelete}
        confirmLabel={t('common.delete', 'Eliminar')}
        cancelLabel={t('common.cancel', 'Cancelar')}
        entityName={config.entityName}
      />

      {/* FK Detail Modal */}
      {fkDetail && (
        <FKDetailModal
          isOpen={isFKDetailOpen}
          onOpenChange={setIsFKDetailOpen}
          entity={fkDetail.entity}
          id={fkDetail.id}
        />
      )}
    </AppLayout>
  );
}

export default AdminCRUDPage;

/*
 * CRUDForm
 * 
 * Componente optimizado para formularios de creación/edición.
 * Implementa validación eficiente y mejor experiencia de usuario.
 */

import React, { memo, useCallback, useMemo, useEffect } from 'react';
import { GenericModal } from '@/shared/ui/common/GenericModal';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Textarea } from '@/shared/ui/textarea';
import { Combobox } from '@/shared/ui/combobox';
import { cn } from '@/shared/ui/cn';
import { Loader2, ChevronRight } from 'lucide-react';
import { useT } from '@/shared/i18n';
import { getTodayColombia, calculateAge } from '@/shared/utils/dateUtils';
import type { FieldErrors } from '@/shared/utils/formValidation';

// Interfaces
import type { CRUDFormField, CRUDFormSection } from '../../../shared/types/crud';

interface CRUDFormProps<T extends { id?: number }> {
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  formData: Record<string, any>;
  setFormData: React.Dispatch<React.SetStateAction<Record<string, any>>>;
  formSections: CRUDFormSection<any>[];
  fieldErrors?: FieldErrors;
  errorMessages?: string[];
  onFieldValueChange?: (field: CRUDFormField<any>, value: any) => void;
  onSubmit: (e: React.FormEvent) => void;
  saving: boolean;
  editingItem?: T | null;
  showEditTimestamps?: boolean;
  additionalFormContent?: (formData: Record<string, any>, editingItem: T | null) => React.ReactNode;
}

// Componente memoizado para cada campo del formulario
const FormField = memo<{
  field: CRUDFormField<any>;
  value: any;
  onChange: (value: any) => void;
  error?: string;
  saving: boolean;
  editingItem?: any;
  dynamicOptions?: any[];
  isLoadingDynamic?: boolean;
}>(({ field, value, onChange, error, saving, editingItem, dynamicOptions, isLoadingDynamic }) => {
  const t = useT();

  // Variables derivadas frecuentes usadas en diferentes ramas
  const isBirthDateField = String(field.name) === 'birth_date';
  const today = getTodayColombia();

  // Determinar si el campo es obligatorio y está vacío
  const isRequired = field.required === true;
  const isEmpty = value == null || value === '';
  const showWarning = Boolean(error) || (isRequired && isEmpty);

  // Manejar cambio de valor
  const handleChange = useCallback((newValue: any) => {
    onChange(newValue);
  }, [onChange]);

  // Renderizar campo según tipo
  const renderField = () => {
    switch (field.type) {
      case 'textarea':
        return (
          <Textarea
            id={String(field.name)}
            value={value || ''}
            onChange={(e) => handleChange(e.target.value)}
            placeholder={field.placeholder}
            rows={3}
            disabled={saving}
            aria-invalid={showWarning}
            aria-required={isRequired}
            className={cn(
              "w-full min-h-[80px] resize-none text-sm",
              showWarning
                ? "border-amber-500 focus:border-amber-600 ring-1 ring-amber-500"
                : "border-border/50 focus:border-primary/50",
              isRequired && "border-l-4 border-l-red-500/40 dark:border-l-red-400/40",
              "bg-background/50 focus:bg-background/80",
              "transition-all duration-300",
              "backdrop-blur-sm"
            )}
          />
        );

      case 'select':
        if (isLoadingDynamic) {
          return (
            <div className="flex items-center gap-2 text-xs text-muted-foreground animate-pulse">
              <Loader2 className="h-3 w-3 animate-spin" />
              Cargando opciones...
            </div>
          );
        }

        {
          const opts = dynamicOptions || field.options || [];
          if (opts.length === 0) {
            return (
              <div className="text-sm text-muted-foreground italic">
                No hay opciones disponibles
              </div>
            );
          }
          const isNumeric = opts.length > 0 && opts.every((o: any) => typeof o.value === 'number');

          return (
            <select
              id={String(field.name)}
              value={String(value ?? '')}
              onChange={(e) => {
                const val = e.target.value;
                handleChange(
                  isNumeric ? (val === '' ? undefined : Number(val)) : val
                );
              }}
              disabled={saving}
              aria-required={isRequired}
              className={cn(
                "w-full px-3 py-2.5 border rounded-lg min-h-[44px] text-sm",
                "bg-background/50 focus:bg-background/80",
                "transition-all duration-200",
                "backdrop-blur-sm",
                "cursor-pointer",
                showWarning
                  ? "border-amber-400/70 focus:border-amber-500 hover:border-amber-500/50 text-amber-900 dark:text-amber-200"
                  : "border-border/50 focus:border-primary/50 text-foreground hover:border-primary/30",
                isRequired && "border-l-4 border-l-red-500/40 dark:border-l-red-400/40"
              )}
            >
              <option value="" className="text-muted-foreground">
                {field.placeholder || 'Seleccionar...'}
              </option>
              {opts.map((option: any) => (
                <option key={String(option.value)} value={String(option.value)} className="text-foreground">
                  {option.label}
                </option>
              ))}
            </select>
          );
        }

      case 'searchable-select':
        if (isLoadingDynamic) {
          return (
             <div className="flex items-center gap-2 text-xs text-muted-foreground animate-pulse py-2">
              <Loader2 className="h-3 w-3 animate-spin" />
              Cargando catálogo...
            </div>
          );
        }

        {
          let opts = dynamicOptions || field.options || [];
          const isNumeric = opts.length > 0 && opts.every((o: any) => typeof o.value === 'number');

          // Excluir el propio registro si se solicita
          if (field.excludeSelf && editingItem?.id != null) {
            opts = opts.filter((o: any) => o.value !== editingItem.id);
          }

          return (
            <div className={cn(
              isRequired && "border-l-4 border-l-red-500/40 dark:border-l-red-400/40 rounded-l-sm"
            )}>
              <Combobox
                options={opts.map((o: any) => ({ value: String(o.value), label: o.label }))}
                value={value == null ? '' : String(value)}
                onValueChange={(val) =>
                  handleChange(
                    isNumeric ? (val === '' ? undefined : Number(val)) : val
                  )
                }
                placeholder={field.placeholder || t('common.search', 'Buscar...')}
                searchPlaceholder={t('common.search', 'Buscar...')}
                emptyMessage={field.emptyMessage || t('state.empty.title', 'Sin resultados')}
                disabled={saving}
                loading={field.loading}
                searchDebounceMs={field.searchDebounceMs || 300}
                onSearchChange={field.onSearchChange}
                className={cn(
                  "transition-all duration-200",
                  field.loading && "opacity-80",
                  !opts.length && !field.loading && "opacity-60"
                )}
              />
            </div>
          );
        }

      case 'checkbox':
        return (
          <div className="flex items-start space-x-2 mt-1">
            <input
              id={String(field.name)}
              type="checkbox"
              checked={Boolean(value)}
              onChange={(e) => handleChange(e.target.checked)}
              disabled={saving}
              className="h-4 w-4 text-primary focus:ring-primary border-gray-300 rounded mt-0.5 flex-shrink-0"
            />
            <label htmlFor={String(field.name)} className="text-sm font-medium text-foreground leading-relaxed">
              {field.label}
            </label>
          </div>
        );

      case 'number':
        return (
          <Input
            id={String(field.name)}
            type="number"
            value={value || ''}
            onChange={(e) => handleChange(e.target.value ? Number(e.target.value) : undefined)}
            placeholder={field.placeholder}
            min={field.validation?.min}
            max={field.validation?.max}
            disabled={saving}
            aria-invalid={showWarning}
            aria-required={isRequired}
            className={cn(
              "w-full min-h-[44px] text-sm",
              showWarning
                ? "border-amber-500 focus:border-amber-600 ring-1 ring-amber-500"
                : "border-border/50 focus:border-primary/50",
              isRequired && "border-l-4 border-l-red-500/40 dark:border-l-red-400/40",
              "bg-background/50 focus:bg-background/80",
              "transition-all duration-300 backdrop-blur-sm"
            )}
          />
        );

      case 'date':
        {
          const maxDate = isBirthDateField ? today : undefined;
          const calculatedAge = isBirthDateField && value ? calculateAge(value) : null;

          return (
            <div className="space-y-2">
              <Input
                id={String(field.name)}
                type="date"
                max={maxDate}
                value={value || ''}
                onChange={(e) => handleChange(e.target.value)}
                disabled={saving}
                aria-invalid={showWarning}
                aria-required={isRequired}
                className={cn(
                  "w-full min-h-[44px] text-sm",
                  showWarning
                    ? "border-amber-500 focus:border-amber-600 ring-1 ring-amber-500"
                    : "border-border/50 focus:border-primary/50",
                  isRequired && "border-l-4 border-l-red-500/40 dark:border-l-red-400/40",
                  "bg-background/50 focus:bg-background/80",
                  "transition-all duration-300 backdrop-blur-sm"
                )}
              />
              {calculatedAge && (
                <div className="flex items-center gap-2 px-3 py-1.5 bg-primary/5 rounded-lg border border-primary/10 animate-in fade-in slide-in-from-top-1 duration-300">
                  <span className="text-[10px] font-black uppercase tracking-widest text-primary/70">Edad:</span>
                  <span className="text-xs font-bold text-primary">{calculatedAge}</span>
                </div>
              )}
            </div>
          );
        }

      case 'text':
      case 'multiselect':
      default:
        return (
          <Input
            id={String(field.name)}
            value={value || ''}
            onChange={(e) => handleChange(e.target.value)}
            placeholder={field.placeholder}
            disabled={saving}
            aria-invalid={showWarning}
            aria-required={isRequired}
            className={cn(
              "w-full min-h-[44px] text-sm",
              showWarning
                ? "border-amber-500 focus:border-amber-600 ring-1 ring-amber-500"
                : "border-border/50 focus:border-primary/50",
              isRequired && "border-l-4 border-l-red-500/40 dark:border-l-red-400/40",
              "bg-background/50 focus:bg-background/80",
              "transition-all duration-300 backdrop-blur-sm"
            )}
          />
        );
    }
  };

  return (
    <div className={cn(
      'w-full space-y-2 group/field relative', 
      field.colSpan && field.colSpan > 1 && 'sm:col-span-2'
    )}>
      <label htmlFor={String(field.name)} className={cn(
        "block text-xs sm:text-sm font-bold tracking-tight",
        "text-muted-foreground/80 group-focus-within/field:text-primary transition-colors duration-300",
        "flex items-center gap-1.5"
      )}>
        <span>{field.label}</span>
        {isRequired && (
          <span className="text-primary font-black animate-pulse">*</span>
        )}
      </label>

      <div className="relative group/input">
        {renderField()}
        
        {/* Decorative focus ring/border effect */}
        <div className="absolute inset-0 rounded-xl border-2 border-primary/0 pointer-events-none group-focus-within/input:border-primary/20 transition-all duration-300 -m-[1px]" />
      </div>

      <div className="min-h-[16px] flex flex-col gap-1 overflow-hidden">
        {showWarning && field.type !== 'checkbox' && (
          <p className="text-[11px] font-bold text-rose-500 animate-in slide-in-from-top-1 duration-300">
            {error || 'Este campo es obligatorio.'}
          </p>
        )}
        
        {field.helperText && !error && (
          <p className="text-[10px] sm:text-[11px] text-muted-foreground/50 italic leading-tight group-focus-within/field:text-muted-foreground/80 transition-colors duration-300">
            {field.helperText}
          </p>
        )}

        {field.type === 'date' && isBirthDateField && value && value > today && (
          <p className="text-[11px] font-bold text-rose-500 animate-in slide-in-from-top-1 duration-300">
            La fecha de nacimiento no puede ser futura.
          </p>
        )}
      </div>
    </div>
  );
});

export function CRUDForm<T extends { id?: number }>({
  isOpen,
  onOpenChange,
  title,
  formData,
  setFormData,
  formSections,
  fieldErrors,
  errorMessages,
  onFieldValueChange,
  onSubmit,
  saving,
  editingItem,
  showEditTimestamps = true,
  additionalFormContent,
}: CRUDFormProps<T>) {
  const t = useT();

  // Estado para opciones cargadas dinámicamente
  const [dynamicOptions, setDynamicOptions] = React.useState<Record<string, any[]>>({});
  const [loadingOptions, setLoadingOptions] = React.useState<Record<string, boolean>>({});

  // Cargar opciones dinámicas cuando el modal se abre
  useEffect(() => {
    if (!isOpen) return;

    formSections.forEach(section => {
      section.fields.forEach(async (field) => {
        const fieldName = String(field.name);
        if (field.loadOptions && !dynamicOptions[fieldName] && !loadingOptions[fieldName]) {
          setLoadingOptions(prev => ({ ...prev, [fieldName]: true }));
          try {
            const opts = await field.loadOptions();
            setDynamicOptions(prev => ({ ...prev, [fieldName]: opts }));
          } catch (error) {
            console.error(`Error al cargar opciones para el campo ${fieldName}:`, error);
          } finally {
            setLoadingOptions(prev => ({ ...prev, [fieldName]: false }));
          }
        }
      });
    });
  }, [isOpen, formSections]);
  useEffect(() => {
    if (!isOpen || !fieldErrors) return;
    const firstKey = Object.keys(fieldErrors)[0];
    if (!firstKey || typeof window === 'undefined') return;
    const el = document.getElementById(firstKey);
    if (el && 'focus' in el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      (el as HTMLElement).focus();
    }
  }, [fieldErrors, isOpen]);

  // Manejar cambio de un campo específico
  const handleFieldChange = useCallback((fieldName: string, value: any) => {
    if (onFieldValueChange) {
      const field = formSections.flatMap((section) => section.fields).find((item) => String(item.name) === fieldName);
      if (field) {
        onFieldValueChange(field, value);
        return;
      }
    }
    setFormData((prev) => ({
      ...prev,
      [fieldName]: value,
    }));
  }, [setFormData, onFieldValueChange, formSections]);

  // Renderizar secciones del formulario
  const renderFormSections = useMemo(() => {
    return formSections.map((section, sectionIndex) => {
      if (section.showIf && !section.showIf(formData)) return null;
      const gridCols = section.gridCols ?? 3;
      const gridClass = `grid grid-cols-1 ${gridCols >= 2 ? 'sm:grid-cols-2' : ''} ${gridCols >= 3 ? 'lg:grid-cols-3' : ''} gap-3 sm:gap-4 lg:gap-5`;

      return (
        <div key={section.title || sectionIndex} className={cn(
          "relative rounded-[2rem] p-5 sm:p-6",
          "border border-border/40",
          "bg-gradient-to-br from-card/40 via-card/20 to-transparent",
          "shadow-xl shadow-primary/5 backdrop-blur-xl",
          "transition-all duration-500 hover:shadow-2xl hover:shadow-primary/10 group/section"
        )}>
          {section.title && (
            <div className="mb-6 flex items-center justify-between">
              <h3 className={cn(
                "text-sm sm:text-base font-black tracking-widest uppercase",
                "text-muted-foreground/60 group-focus-within/section:text-primary transition-colors duration-500",
                "flex items-center gap-3"
              )}>
                <div className="h-8 w-8 rounded-xl bg-primary/10 flex items-center justify-center group-focus-within/section:bg-primary transition-colors duration-500">
                  <div className="h-1.5 w-1.5 rounded-full bg-primary group-focus-within/section:bg-white animate-pulse" />
                </div>
                {section.title}
              </h3>
            </div>
          )}

          <div className={gridClass}>
            {section.fields.map((field: any) => {
              // Soporte para renderizado condicional basado en showIf
              if (field.showIf && typeof field.showIf === 'function') {
                if (!field.showIf(formData)) {
                  return null;
                }
              }

              return (
                <FormField
                  key={String(field.name)}
                  field={field}
                  value={formData[field.name as string]}
                  onChange={(value) => handleFieldChange(String(field.name), value)}
                  error={fieldErrors?.[String(field.name)]}
                  saving={saving}
                  editingItem={editingItem}
                  dynamicOptions={dynamicOptions[String(field.name)]}
                  isLoadingDynamic={loadingOptions[String(field.name)]}
                />
              );
            })}
          </div>
        </div>
      );
    });
  }, [formSections, formData, saving, editingItem, handleFieldChange, fieldErrors]);

  return (
    <GenericModal
      isOpen={isOpen}
      onOpenChange={onOpenChange}
      title={title}
      size="5xl"
      variant="compact"
      allowFullScreenToggle
      enableBackdropBlur
      className="bg-card text-card-foreground border-border shadow-lg transition-all duration-200 ease-out max-h-[90vh]"
    >
      <form onSubmit={onSubmit} className="space-y-3 sm:space-y-4 h-full flex flex-col text-[13px] sm:text-sm">
        {fieldErrors && Object.keys(fieldErrors).length > 0 && (
          <div className="rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-700">
            <div className="font-semibold">Faltan datos obligatorios</div>
            <div>Revise los campos marcados en rojo y corrija lo siguiente:</div>
            {errorMessages && errorMessages.length > 0 && (
              <ul className="mt-1 list-disc pl-4">
                {errorMessages.slice(0, 5).map((msg) => (
                  <li key={msg}>{msg}</li>
                ))}
                {errorMessages.length > 5 && (
                  <li>y {errorMessages.length - 5} mas...</li>
                )}
              </ul>
            )}
          </div>
        )}
        {renderFormSections}
        {additionalFormContent && additionalFormContent(formData, editingItem || null)}

        {editingItem && showEditTimestamps && (
          <div className={cn(
            "mt-2 p-3 sm:p-4 rounded-lg",
            "bg-muted/30 border border-border/40",
            "text-xs sm:text-sm text-muted-foreground",
            "backdrop-blur-sm"
          )}>
            <div className="flex flex-wrap gap-x-4 gap-y-1">
              <span><strong className="text-foreground/80">ID:</strong> {editingItem.id}</span>
              {(editingItem as any).created_at && (
                <span><strong className="text-foreground/80">Creado:</strong> {new Date((editingItem as any).created_at).toLocaleDateString('es-ES')}</span>
              )}
              {(editingItem as any).updated_at && (
                <span><strong className="text-foreground/80">Actualizado:</strong> {new Date((editingItem as any).updated_at).toLocaleDateString('es-ES')}</span>
              )}
            </div>
          </div>
        )}
               <div className={cn(
          "flex flex-col sm:flex-row gap-4 pt-8 mt-10",
          "sticky bottom-0 -mx-6 -mb-6 p-6 sm:p-8",
          "bg-gradient-to-t from-card via-card/95 to-transparent",
          "backdrop-blur-2xl border-t border-border/30 z-20"
        )}>
          <Button
            type="button"
            variant="ghost"
            onClick={() => onOpenChange(false)}
            disabled={saving}
            className={cn(
              "w-full sm:flex-[0.5]",
              "h-12 sm:h-14 rounded-2xl font-black uppercase tracking-widest text-[10px]",
              "hover:bg-muted/50 transition-all duration-300"
            )}
          >
            {t('common.cancel', 'Cancelar')}
          </Button>
          <Button
            type="submit"
            disabled={saving}
            className={cn(
              "w-full sm:flex-1",
              "h-12 sm:h-14 rounded-2xl font-black uppercase tracking-widest text-[10px]",
              "bg-primary hover:bg-primary/90 text-primary-foreground",
              "shadow-2xl shadow-primary/20 hover:shadow-primary/40",
              "transition-all duration-500 hover:scale-[1.02] active:scale-[0.98]",
              saving && "opacity-80 cursor-not-allowed"
            )}
          >
            {saving ? (
              <span className="flex items-center gap-2">
                <Loader2 className="h-4 w-4 animate-spin" />
                {t('common.saving', 'Procesando...')}
              </span>
            ) : (
              <span className="flex items-center gap-2">
                {editingItem ? t('common.update', 'Guardar Cambios') : t('common.create', 'Crear Registro')}
                <ChevronRight className="h-4 w-4" />
              </span>
            )}
          </Button>
        </div>
      </form>
    </GenericModal>
  );
}

export default CRUDForm;

/*
 * CRUDModals
 * 
 * Componentes optimizados para los modales de CRUD.
 * Implementa modales de detalle y confirmación con mejor UX.
 */

import React, { memo, useCallback } from 'react';
import { GenericModal } from '@/shared/ui/common/GenericModal';
import { ConfirmDialog } from '@/shared/ui/common/ConfirmDialog';
import { Button } from '@/shared/ui/button';
import { Card, CardHeader, CardTitle, CardContent } from '@/shared/ui/card';
import { ChevronLeft, ChevronRight, Edit } from 'lucide-react';
import { useT } from '@/shared/i18n';

// Interfaces
import { CRUDConfig } from '@/shared/types/crud';

// Subcomponente para el modal de detalle
function DetailModalComponent<T extends { id: number }>({
  isOpen,
  onOpenChange,
  title,
  item,
  config,
  onEdit,
  customDetailContent,
  showDetailTimestamps: _showDetailTimestamps = true,
  detailIndex,
  setDetailIndex,
  items,
  setDetailItem,
}: {
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  item: T | null;
  config: CRUDConfig<T, any>;
  onEdit?: (item: T) => void;
  customDetailContent?: (item: T, navigateToItem?: (item: T) => void) => React.ReactNode;
  showDetailTimestamps?: boolean;
  showIdInDetailTitle?: boolean;
  detailIndex: number | null;
  setDetailIndex: (index: number | null) => void;
  items: T[];
  setDetailItem: (item: T | null) => void;
}) {
  const t = useT();
  
  // Manejar navegación entre elementos
  const handleNextDetail = useCallback(() => {
    if (!items?.length || detailIndex === null) return;
    const nextIndex = (detailIndex + 1) % items.length;
    setDetailIndex(nextIndex);
    setDetailItem(items[nextIndex]);
  }, [items, detailIndex, setDetailIndex, setDetailItem]);
  
  const handlePrevDetail = useCallback(() => {
    if (!items?.length || detailIndex === null) return;
    const prevIndex = (detailIndex - 1 + items.length) % items.length;
    setDetailIndex(prevIndex);
    setDetailItem(items[prevIndex]);
  }, [items, detailIndex, setDetailIndex, setDetailItem]);
  
  // Mapa de etiquetas para llaves foráneas
  const fkLabelMap = React.useMemo(() => {
    const map: Record<string, Map<string, string>> = {};
    try {
      (config.formSections || []).forEach((section) => {
        (section.fields || []).forEach((field) => {
          if ((field.type === 'select' || field.type === 'searchable-select') && field.options && field.options.length) {
            const m = new Map<string, string>();
            field.options.forEach((opt) => {
              m.set(String(opt.value), opt.label);
            });
            map[String(field.name)] = m;
          }
        });
      });
    } catch (e) {
      console.warn('[DetailModal] Error construyendo mapa de etiquetas', e);
    }
    return map;
  }, [config.formSections]);
  
  // Footer con navegación y acciones
  const footer = (
    <div className="relative border-t border-border bg-surface-secondary px-5 sm:px-6 py-2.5 sm:py-3">
      <div className="flex flex-col sm:flex-row gap-2 sm:gap-3">
        <div className="flex gap-2 sm:flex-1">
          <Button
            variant="outline"
            size="sm"
            type="button"
            onClick={handlePrevDetail}
            disabled={!items || items.length <= 1}
            className="flex-1 sm:flex-initial transition-all duration-150 font-semibold border-border hover:border-ghost-primary-strong hover:bg-ghost-primary"
          >
            <ChevronLeft className="h-4 w-4 sm:mr-1.5" />
            <span className="hidden sm:inline">Anterior</span>
          </Button>
          <Button
            variant="outline"
            size="sm"
            type="button"
            onClick={handleNextDetail}
            disabled={!items || items.length <= 1}
            className="flex-1 sm:flex-initial transition-all duration-150 font-semibold border-border hover:border-ghost-primary-strong hover:bg-ghost-primary"
          >
            <span className="hidden sm:inline">Siguiente</span>
            <ChevronRight className="h-4 w-4 sm:ml-1.5" />
          </Button>
        </div>
        <div className="flex gap-2 sm:justify-end">
          <Button
            variant="outline"
            size="sm"
            type="button"
            onClick={() => { onOpenChange(false); setDetailIndex(null); }}
            className="flex-1 sm:flex-initial transition-all duration-150 font-semibold border-border hover:border-ghost-primary-strong hover:bg-ghost-primary"
          >
            {t('modal.close', 'Cerrar')}
          </Button>
          {item && onEdit && (
            <Button
              size="sm"
              type="button"
              onClick={() => { onEdit(item); onOpenChange(false); setDetailIndex(null); }}
              className="flex-1 sm:flex-initial font-semibold bg-primary text-primary-foreground hover:bg-primary/90 transition-colors duration-150"
            >
              <Edit className="h-4 w-4 sm:mr-1.5" />
              <span className="hidden sm:inline">{t('common.edit', 'Editar')}</span>
            </Button>
          )}
        </div>
      </div>
    </div>
  );
  
  return (
    <GenericModal
      isOpen={isOpen}
      onOpenChange={onOpenChange}
      title={title}
      size="4xl"
      variant="compact"
      allowFullScreenToggle
      enableBackdropBlur
      className="bg-card text-card-foreground border-border shadow-lg transition-all duration-200 ease-out max-h-[90vh]"
      footer={footer}
    >
      {item && (
        customDetailContent ? (
          customDetailContent(item, (newItem) => {
            const idx = items.findIndex((i) => i.id === newItem.id);
            if (idx >= 0) {
              setDetailIndex(idx);
              setDetailItem(newItem);
            }
          })
        ) : (
          <div className="grid grid-cols-1 gap-4">
            <div className="space-y-4">
              <Card className="shadow-sm hover:shadow-md transition-shadow duration-200 border border-border rounded-xl overflow-hidden">
                <CardHeader className="pb-3">
                  <CardTitle className="text-base">Información general</CardTitle>
                </CardHeader>
                <CardContent className="min-w-0">
                  <dl className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-sm min-w-0">
                    {config.columns.map((col, _colIndex) => (
                      <div key={String(col.key)} className="space-y-1 min-w-0">
                        <dt className="text-xs text-muted-foreground font-medium">{col.label}</dt>
                        <dd className="text-sm font-medium text-foreground break-words whitespace-normal leading-snug min-w-0">
                          {col.render
                            ? col.render((item as any)[col.key], item, 0)
                            : (() => {
                                const raw = (item as any)[col.key];
                                const mapped = fkLabelMap[String(col.key)]?.get(String(raw));
                                return mapped ?? String(raw ?? '-');
                              })()}
                        </dd>
                      </div>
                    ))}
                  </dl>
                </CardContent>
              </Card>
            </div>
            
            <Card className="shadow-sm border border-border rounded-xl overflow-hidden">
              <CardHeader className="pb-3">
                <CardTitle className="text-base">Fecha y hora</CardTitle>
              </CardHeader>
              <CardContent className="min-w-0">
                <dl className="grid grid-cols-1 gap-3 text-sm">
                  {(item as any).created_at && (
                    <div className="space-y-1 min-w-0">
                      <dt className="text-xs text-muted-foreground font-medium">Creado</dt>
                      <dd className="text-sm font-medium break-words whitespace-normal leading-snug">
                        {new Date((item as any).created_at).toLocaleString('es-ES')}
                      </dd>
                    </div>
                  )}
                  {(item as any).updated_at && (
                    <div className="space-y-1 min-w-0">
                      <dt className="text-xs text-muted-foreground font-medium">Actualizado</dt>
                      <dd className="text-sm font-medium break-words whitespace-normal leading-snug">
                        {new Date((item as any).updated_at).toLocaleString('es-ES')}
                      </dd>
                    </div>
                  )}
                </dl>
              </CardContent>
            </Card>
          </div>
        )
      )}
    </GenericModal>
  );
}

