/*
 * CRUDPagination
 * 
 * Componente optimizado para la paginación de tablas.
 * Implementa navegación eficiente y accesible.
 */

import React, { memo, useCallback } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { cn } from '@/shared/ui/cn';
import { useT } from '@/shared/i18n';

interface CRUDPaginationProps {
  currentPage: number;
  totalPages: number;
  totalItems: number;
  onPageChange: (page: number) => void;
  loading?: boolean;
}

export const CRUDPagination = memo<CRUDPaginationProps>(({
  currentPage,
  totalPages,
  totalItems,
  onPageChange,
  loading = false,
}) => {
  const t = useT();
  
  // Manejar cambio de página
  const handlePageChange = useCallback((page: number) => {
    if (page >= 1 && page <= totalPages && page !== currentPage && !loading) {
      onPageChange(page);
    }
  }, [currentPage, totalPages, loading, onPageChange]);
  
  // Generar array de páginas a mostrar
  const getVisiblePages = useCallback(() => {
    const delta = 2; // Número de páginas a mostrar antes y después de la actual
    
    // Caso especial: menos de 7 páginas totales
    if (totalPages <= 7) {
      return Array.from({ length: totalPages }, (_, i) => i + 1);
    }
    
    // Caso normal: mostrar páginas alrededor de la actual
    const range = [];
    const rangeWithDots = [];
    let l;

    for (let i = 1; i <= totalPages; i++) {
      if (
        i === 1 || // Primera página
        i === totalPages || // Última página
        (i >= currentPage - delta && i <= currentPage + delta) // Páginas alrededor de la actual
      ) {
        range.push(i);
      }
    }

    // Agregar puntos suspensivos donde haya saltos
    range.forEach((i) => {
      if (l) {
        if (i - l === 2) {
          rangeWithDots.push(l + 1);
        } else if (i - l !== 1) {
          rangeWithDots.push('...');
        }
      }
      rangeWithDots.push(i);
      l = i;
    });

    return rangeWithDots;
  }, [currentPage, totalPages]);
  
  const visiblePages = getVisiblePages();
  
  return (
    <div className="sticky bottom-0 z-10 bg-card/95 border-t backdrop-blur-sm shadow-sm flex-shrink-0">
      <div className="px-2 py-1.5 sm:py-2">
        <div className="flex justify-between items-center text-[11px] sm:text-[12px] md:text-sm gap-2">
          {/* Información de paginación */}
          <div className="text-muted-foreground">
            <span className="hidden sm:inline">{t('common.page', 'Página')} </span>
            <span className="sm:hidden">Pág. </span>
            {currentPage} <span className="hidden sm:inline">{t('common.of', 'de')}</span><span className="sm:hidden">/</span> {Math.max(totalPages, 1)}
            <span className="ml-2 hidden sm:inline">
              ({totalItems} {totalItems === 1 ? 'registro' : 'registros'})
            </span>
          </div>
          
          {/* Controles de paginación */}
          <div className="flex items-center gap-1 sm:gap-2">
            {/* Botón anterior */}
            <Button
              variant="outline"
              size="sm"
              onClick={() => handlePageChange(currentPage - 1)}
              disabled={loading || currentPage <= 1}
              aria-label={t('common.previous', 'Anterior')}
              className="inline-flex items-center justify-center h-7 w-7 sm:h-9 sm:w-9 text-sm font-medium ring-offset-background transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50"
            >
              <ChevronLeft className="h-3.5 w-3.5 sm:h-4 sm:w-4" aria-hidden />
            </Button>
            
            {/* Números de página */}
            <div className="hidden sm:flex items-center gap-1">
              {visiblePages.map((page, index) => (
                <React.Fragment key={index}>
                  {page === '...' ? (
                    <span className="px-2 py-1 text-muted-foreground">...</span>
                  ) : (
                    <Button
                      variant={currentPage === page ? "default" : "outline"}
                      size="sm"
                      onClick={() => handlePageChange(page as number)}
                      disabled={loading}
                      className={cn(
                        "h-7 w-7 sm:h-9 sm:w-9 text-sm font-medium",
                        currentPage === page && "bg-primary text-primary-foreground"
                      )}
                    >
                      {page}
                    </Button>
                  )}
                </React.Fragment>
              ))}
            </div>
            
            {/* Paginación simplificada para móviles */}
            <div className="sm:hidden text-xs text-muted-foreground">
              {currentPage} / {totalPages}
            </div>
            
            {/* Botón siguiente */}
            <Button
              variant="outline"
              size="sm"
              onClick={() => handlePageChange(currentPage + 1)}
              disabled={loading || currentPage >= totalPages}
              aria-label={t('common.next', 'Siguiente')}
              className="inline-flex items-center justify-center h-7 w-7 sm:h-9 sm:w-9 text-sm font-medium ring-offset-background transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50"
            >
              <ChevronRight className="h-3.5 w-3.5 sm:h-4 sm:w-4" aria-hidden />
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
});

CRUDPagination.displayName = 'CRUDPagination';

export default CRUDPagination;

/*
 * CRUDTable
 * 
 * Componente optimizado para renderizar tablas con gran volumen de datos.
 * Implementa virtualización, memoización y animaciones simplificadas.
 */

import React, { memo, useMemo, useCallback, useRef } from 'react';
import { CheckSquare2, Edit, Eye, Loader2, Square, Trash2, X } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Badge } from '@/shared/ui/badge';
import { cn } from '@/shared/ui/cn';
import { useT } from '@/shared/i18n';

// Interfaces
import { CRUDColumn, CRUDConfig } from '@/shared/types/crud';

interface CRUDTableProps<T extends { id: number }> {
  items: T[];
  columns: CRUDColumn<T>[];
  config: CRUDConfig<T, any>;
  onDetail?: (item: T) => void;
  onEdit?: (item: T) => void;
  onDelete?: (id: number) => void;
  enhancedHover?: boolean;
  loading?: boolean;
  deletingIds: Set<string>;
  onOpenFKDetail?: (entity: string, id: number) => void;
  selectedIds?: number[];
  onToggleSelect?: (id: number) => void;
}

interface InternalTableProps<T extends { id: number }> {
  items: T[];
  columns: CRUDColumn<T>[];
  config: CRUDConfig<T, any>;
  onDetail?: (item: T) => void;
  onEdit?: (item: T) => void;
  onDelete?: (id: number) => void;
  enhancedHover?: boolean;
  fkLabelMap: Record<string, Map<string, string>>;
  deletingIds: Set<string>;
  onOpenFKDetail?: (entity: string, id: number) => void;
  selectedIds?: number[];
  onToggleSelect?: (id: number) => void;
}

interface TableRowProps<T extends { id: number }> {
  item: T;
  index: number;
  columns: CRUDColumn<T>[];
  config: CRUDConfig<T, any>;
  onDetail?: (item: T) => void;
  onEdit?: (item: T) => void;
  onDelete?: (id: number) => void;
  enhancedHover?: boolean;
  fkLabelMap: Record<string, Map<string, string>>;
  deletingIds: Set<string>;
  onOpenFKDetail?: (entity: string, id: number) => void;
  isSelected?: boolean;
  onToggleSelect?: (id: number) => void;
}

// Componente memoizado para cada fila
function TableRowComponent<T extends { id: number }>(props: TableRowProps<T>) {
  const {
    item,
    index,
    columns,
    config,
    onDetail,
    onEdit,
    onDelete,
    enhancedHover,
    fkLabelMap,
    deletingIds,
    onOpenFKDetail,
    isSelected,
    onToggleSelect,
  } = props;

  const t = useT();
  const isDeleting = deletingIds.has(String(item.id));
  const prefetchTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const handleClick = useCallback(() => {
    if (onDetail) {
      onDetail(item);
    }
  }, [onDetail, item]);

  const handleEdit = useCallback((e: React.MouseEvent) => {
    e.stopPropagation();
    if (onEdit) {
      onEdit(item);
    }
  }, [onEdit, item]);

  const handleDelete = useCallback((e: React.MouseEvent) => {
    e.stopPropagation();
    if (onDelete) {
      onDelete(item.id);
    }
  }, [onDelete, item]);

  const handleMouseEnter = useCallback(() => {
    if (config.enableDetailModal === false && config.enableEditModal === false) return;

    prefetchTimerRef.current = setTimeout(() => {
      try {
        // Prefetching logic could go here if service was available
      } catch (e) {
        // Silencioso
      }
    }, 120);
  }, [config]);

  const handleMouseLeave = useCallback(() => {
    if (prefetchTimerRef.current) {
      clearTimeout(prefetchTimerRef.current);
      prefetchTimerRef.current = null;
    }
  }, []);

  return (
    <tr
      className={cn(
        "h-10 md:h-12 cursor-pointer focus:outline-none",
        "transition-all duration-300 relative overflow-visible border-b border-border/40",
        enhancedHover ? "hover:bg-primary/5" : "hover:bg-muted/40",
        isSelected && "bg-primary/5",
        isDeleting && "opacity-50 bg-rose-500/10"
      )}
      onClick={handleClick}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      role="button"
      tabIndex={0}
    >
      <td className="w-10 px-4" onClick={(e) => e.stopPropagation()}>
        <input 
          type="checkbox" 
          checked={isSelected}
          onChange={() => onToggleSelect?.(item.id)}
          className="h-4 w-4 rounded border-border/50 text-primary focus:ring-primary bg-card transition-all cursor-pointer"
        />
      </td>
      {columns.map((col) => (
        <td
          key={String(col.key)}
          className={cn(
            "px-4 py-2 whitespace-nowrap text-[11px] md:text-sm font-medium text-foreground/80",
            col.width ? `w-${col.width}` : '',
            "truncate max-w-[200px]",
            col.hiddenOnMobile && "hidden md:table-cell"
          )}
          title={col.render ? undefined : (fkLabelMap[String(col.key)]?.get(String((item as any)[col.key])) ?? String((item as any)[col.key] ?? ''))}
        >
          {(() => {
            const rawValue = (item as any)[col.key];
            const content = col.render 
              ? col.render(rawValue, item, index)
              : (fkLabelMap[String(col.key)]?.get(String(rawValue)) ?? String(rawValue ?? '-'));

            if (col.fkEntity && rawValue && (typeof rawValue === 'number' || !isNaN(Number(rawValue)))) {
              return (
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    onOpenFKDetail?.(col.fkEntity!, Number(rawValue));
                  }}
                  className="text-primary hover:underline font-bold focus:outline-none rounded px-0.5 text-left"
                >
                  {content}
                </button>
              );
            }

            return content;
          })()}
        </td>
      ))}

      {(config.enableDetailModal !== false || config.enableEditModal !== false || config.enableDelete || config.customActions) && (
        <td className="px-4 py-2 whitespace-nowrap text-right" onClick={(e) => e.stopPropagation()}>
          <div className="flex items-center justify-end gap-1 flex-nowrap">
            {config.enableDetailModal !== false && (
              <Button
                variant="ghost"
                size="icon"
                className="h-8 w-8 rounded-lg text-blue-500 hover:bg-blue-500 hover:text-white transition-all"
                onClick={handleClick}
              >
                <Eye className="h-4 w-4" />
              </Button>
            )}
            {config.enableEditModal !== false && (
              <Button
                variant="ghost"
                size="icon"
                className="h-8 w-8 rounded-lg text-amber-500 hover:bg-amber-500 hover:text-white transition-all"
                onClick={handleEdit}
              >
                <Edit className="h-4 w-4" />
              </Button>
            )}
            {config.enableDelete && (
              <Button
                variant="ghost"
                size="icon"
                className="h-8 w-8 rounded-lg text-rose-500 hover:bg-rose-500 hover:text-white transition-all"
                onClick={handleDelete}
                disabled={isDeleting}
              >
                {isDeleting ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <Trash2 className="h-4 w-4" />
                )}
              </Button>
            )}
            {config.customActions && config.customActions(item)}
          </div>
        </td>
      )}
    </tr>
  );
}

const TableRow = memo(TableRowComponent) as typeof TableRowComponent;

// Componente para renderizar la tabla tradicional
function TraditionalTableComponent<T extends { id: number }>(props: InternalTableProps<T>) {
  const {
    items,
    columns,
    config,
    onDetail,
    onEdit,
    onDelete,
    enhancedHover,
    fkLabelMap,
    deletingIds,
    onOpenFKDetail,
    selectedIds = [],
    onToggleSelect,
  } = props;

  const allSelected = items.length > 0 && items.every(i => selectedIds.includes(i.id));

  const handleSelectAll = useCallback(() => {
    if (allSelected) {
      // Unselect all in current page
      items.forEach(i => {
        if (selectedIds.includes(i.id)) onToggleSelect?.(i.id);
      });
    } else {
      // Select all in current page
      items.forEach(i => {
        if (!selectedIds.includes(i.id)) onToggleSelect?.(i.id);
      });
    }
  }, [allSelected, items, selectedIds, onToggleSelect]);

  return (
    <div className="flex-1 overflow-auto">
      <table className="min-w-full border-separate border-spacing-0">
        <thead className="sticky top-0 z-10 bg-muted/80 backdrop-blur-md">
          <tr className="h-10">
            <th className="w-10 px-4 border-b border-border/50 text-left">
              <input 
                type="checkbox" 
                checked={allSelected}
                onChange={handleSelectAll}
                className="h-4 w-4 rounded border-border/50 text-primary focus:ring-primary bg-card transition-all cursor-pointer"
              />
            </th>
            {columns.map((col) => (
              <th
                key={String(col.key)}
                className={cn(
                  "px-4 py-2 text-left text-[10px] md:text-xs font-black text-muted-foreground uppercase tracking-[0.15em] border-b border-border/50",
                  col.width ? `w-${col.width}` : '',
                  "truncate",
                  col.hiddenOnMobile && "hidden md:table-cell"
                )}
              >
                {col.label}
              </th>
            ))}
            {(config.enableDetailModal !== false || config.enableEditModal !== false || config.enableDelete || config.customActions) && (
              <th className="px-4 py-2 text-right text-[10px] md:text-xs font-black text-muted-foreground uppercase tracking-[0.15em] border-b border-border/50">
                Acciones
              </th>
            )}
          </tr>
        </thead>
        <tbody className="divide-y divide-border/20">
          {items.map((item, index) => (
            <TableRow
              key={item.id}
              item={item}
              index={index}
              columns={columns}
              config={config}
              onDetail={onDetail}
              onEdit={onEdit}
              onDelete={onDelete}
              enhancedHover={enhancedHover}
              fkLabelMap={fkLabelMap}
              deletingIds={deletingIds}
              onOpenFKDetail={onOpenFKDetail}
              isSelected={selectedIds.includes(item.id)}
              onToggleSelect={onToggleSelect}
            />
          ))}
        </tbody>
      </table>
    </div>
  );
}

const TraditionalTable = memo(TraditionalTableComponent) as typeof TraditionalTableComponent;

export function CRUDTable<T extends { id: number }>({
  items,
  columns,
  config,
  onDetail,
  onEdit,
  onDelete,
  enhancedHover = false,
  loading = false,
  deletingIds,
  onOpenFKDetail,
  selectedIds = [],
  onToggleSelect,
}: CRUDTableProps<T>) {
  const selectedCount = selectedIds.length;
  const selectionActive = selectedCount > 0;

  const allVisibleSelected = items.length > 0 && items.every((item) => selectedIds.includes(item.id));

  const handleToggleVisibleSelection = useCallback(() => {
    if (!onToggleSelect) return;

    if (allVisibleSelected) {
      items.forEach((item) => {
        if (selectedIds.includes(item.id)) onToggleSelect(item.id);
      });
      return;
    }

    items.forEach((item) => {
      if (!selectedIds.includes(item.id)) onToggleSelect(item.id);
    });
  }, [allVisibleSelected, items, onToggleSelect, selectedIds]);

  const handleClearVisibleSelection = useCallback(() => {
    if (!onToggleSelect) return;
    items.forEach((item) => {
      if (selectedIds.includes(item.id)) onToggleSelect(item.id);
    });
  }, [items, onToggleSelect, selectedIds]);

  // Mapa de etiquetas para llaves foráneas
  const fkLabelMap = useMemo(() => {
    const map: Record<string, Map<string, string>> = {};
    try {
      (config.formSections || []).forEach((section) => {
        (section.fields || []).forEach((field) => {
          if ((field.type === 'select' || field.type === 'searchable-select') && field.options && field.options.length) {
            const m = new Map<string, string>();
            field.options.forEach((opt) => {
              m.set(String(opt.value), opt.label);
            });
            map[String(field.name)] = m;
          }
        });
      });
    } catch (e) {
      console.warn('[CRUDTable] Error construyendo mapa de etiquetas', e);
    }
    return map;
  }, [config.formSections]);

  if (loading && items.length === 0) {
    return (
      <div className="flex-1 flex items-center justify-center p-12">
        <Loader2 className="h-8 w-8 animate-spin text-primary opacity-50" />
      </div>
    );
  }

  return (
    <div className="relative flex-1 min-h-0 flex flex-col overflow-hidden">
      {config.viewMode === 'cards' ? (
        <div className="flex-1 min-h-0 overflow-auto">
          {onToggleSelect && (
            <div className={cn(
              "sticky top-0 z-20 mx-4 mt-4 sm:mx-5 sm:mt-5 rounded-xl border px-4 py-3 shadow-sm backdrop-blur-md",
              selectionActive
                ? "border-emerald-200 bg-emerald-50/95 text-emerald-950"
                : "border-border/70 bg-card/95 text-foreground"
            )}>
              <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
                <div className="min-w-0">
                  <p className="text-sm font-black leading-tight">
                    {selectionActive
                      ? `${selectedCount} ${selectedCount === 1 ? 'animal seleccionado' : 'animales seleccionados'}`
                      : 'Selecciona los animales para trabajar en lote'}
                  </p>
                  <p className="mt-1 text-xs font-medium text-muted-foreground">
                    {selectionActive
                      ? 'Elige abajo si los vas a trasladar, pesar o vacunar.'
                      : 'Marca varios y muévelos juntos al potrero que corresponda.'}
                  </p>
                </div>
                <div className="flex flex-wrap items-center gap-2">
                  <Button
                    type="button"
                    variant={selectionActive ? "secondary" : "outline"}
                    size="sm"
                    onClick={handleToggleVisibleSelection}
                    className="rounded-lg"
                  >
                    {allVisibleSelected ? 'Quitar visibles' : 'Seleccionar visibles'}
                  </Button>
                  {selectionActive && (
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={handleClearVisibleSelection}
                      className="rounded-lg gap-1"
                    >
                      <X className="h-4 w-4" />
                      Limpiar vista
                    </Button>
                  )}
                </div>
              </div>
            </div>
          )}

          <div className={cn(
            "p-4 sm:p-5 grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-5",
