            aria-label={isSidebarOpen ? "Cerrar menú" : "Abrir menú"}
          >
            <Menu className="h-5 w-5" />
          </Button>

          <div className={cn("flex items-center gap-2 px-1 sm:px-2 group cursor-default transition-all duration-500", isSidebarOpen && "lg:opacity-0 lg:pointer-events-none lg:w-0 lg:overflow-hidden")}>
            <div className="hidden xs:flex flex-col flex-shrink-0">
              <span className="text-[10px] font-black tracking-[0.25em] text-primary/70 uppercase leading-none mb-0.5 group-hover:text-primary transition-colors">
                Software Ganadero
              </span>
              <span className="text-sm sm:text-lg font-black tracking-tighter text-foreground uppercase leading-tight whitespace-nowrap bg-gradient-to-r from-foreground to-foreground/70 bg-clip-text text-transparent group-hover:from-primary group-hover:to-primary-dark transition-all duration-500">
                Villa Luz
              </span>
            </div>
            <div className="hidden md:block h-8 w-[1px] bg-border/40 mx-1 sm:mx-2 rotate-12" />
          </div>
        </div>

        {/* Sección Central: Selector y Sync */}
        <div className="flex-1 flex items-center justify-start px-2 sm:px-4 min-w-0 overflow-hidden gap-2">
          <div className="flex-shrink-1 min-w-0">
            <FincaSelector />
          </div>
          <div className="hidden lg:block h-6 w-[1px] bg-border/40 flex-shrink-0" />
          <div className="hidden xs:block flex-shrink-0">
            <SyncStatus />
          </div>
        </div>

        {/* Sección Derecha: Acciones */}
        <div className="flex items-center gap-1 sm:gap-3 flex-shrink-0 ml-auto">
          {/* Icono de búsqueda sólo en móvil/tablet (<md) */}
          <button
            type="button"
            onClick={() => setMobileSearchOpen(!mobileSearchOpen)}
            className={cn(
              "md:hidden flex h-10 w-10 items-center justify-center rounded-2xl transition-all shadow-sm",
              mobileSearchOpen ? "bg-primary text-white" : "hover:bg-primary/10 text-text-secondary hover:text-primary bg-muted/40 border border-transparent"
            )}
          >
            <Search className="h-4 w-4" />
          </button>

          {/* Controles secundarios */}
          <div className="hidden sm:flex items-center gap-1.5 sm:gap-2 px-1.5 py-1 rounded-2xl bg-muted/30 border border-border/40">
            <button
              onClick={toggleFieldMode}
              className={cn(
                "flex h-9 w-9 items-center justify-center rounded-xl transition-all relative overflow-hidden group shadow-sm",
                isFieldMode 
                  ? "bg-green-600 text-white shadow-green-500/30" 
                  : "hover:bg-primary/10 text-text-secondary hover:text-primary bg-background/50"
              )}
            >
              <Mountain className={cn("h-4 w-4 relative z-10", isFieldMode && "animate-pulse")} />
            </button>

            <ThemeToggle />
            <NotificationCenter />

            <button
              onClick={() => navigate('/chat')}
              className="relative flex h-9 w-9 items-center justify-center rounded-xl hover:bg-primary/10 text-text-secondary hover:text-primary transition-all bg-background/50 shadow-sm"
            >
              <MessageCircle className="h-4 w-4" />
              {unreadCount > 0 && (
                <span className="absolute -top-1 -right-1 h-4 w-4 flex items-center justify-center bg-primary text-primary-foreground text-[9px] font-black rounded-full border-2 border-background">
                  {unreadCount}
                </span>
              )}
            </button>
          </div>

          {/* Avatar / menú de perfil */}
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <button className="flex items-center gap-2.5 pl-1.5 pr-2 sm:pr-3 py-1.5 rounded-2xl hover:bg-state-hover border border-transparent hover:border-border/60 hover:shadow-lg transition-all group bg-background/40 backdrop-blur-sm">
                <div className="w-9 h-9 sm:w-10 sm:h-10 rounded-2xl bg-gradient-to-br from-primary via-primary to-primary-light flex items-center justify-center text-white font-black shadow-lg shadow-primary/20 ring-2 ring-background ring-offset-2 ring-offset-primary/5 group-hover:scale-105 group-hover:rotate-3 transition-all duration-300 relative overflow-hidden">
                  <div className="absolute inset-0 bg-[radial-gradient(circle_at_top_right,_var(--tw-gradient-from)_0%,_transparent_60%)] opacity-50" />
                  <span className="relative z-10">{user?.fullname?.[0] || <User className="h-5 w-5" />}</span>
                </div>
                <div className="hidden sm:flex flex-col items-start mr-1">
                  <span className="text-sm font-black text-text-primary leading-none truncate max-w-[120px] group-hover:text-primary transition-colors">{user?.fullname?.split(' ')[0]}</span>
                  <span className="text-[10px] font-bold text-text-muted uppercase tracking-wider leading-none mt-1.5 flex items-center gap-1">
                    <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                    {user?.role}
                  </span>
                </div>
                <ChevronDown className="h-4 w-4 text-text-muted group-hover:text-primary group-hover:translate-y-0.5 transition-all hidden sm:block" />
              </button>
            </DropdownMenuTrigger>
            <DropdownMenuContent
              align="end"
              className="w-[min(22rem,calc(100vw-1rem))] sm:w-80 max-h-[calc(100vh-5rem)] overflow-y-auto mt-2 rounded-2xl border-border shadow-2xl p-2 animate-in fade-in slide-in-from-top-2 duration-300"
            >
              <DropdownMenuLabel className="px-3 py-2">
                <div className="flex flex-col">
                  <p className="text-sm font-bold text-text-primary">{user?.fullname}</p>
                  <p className="text-xs text-text-muted truncate">{user?.email}</p>
                </div>
              </DropdownMenuLabel>
              <DropdownMenuSeparator />

              {/* Accesos rápidos para móvil (<sm) */}
              <div className="sm:hidden grid grid-cols-3 gap-2 mb-2">
                <DropdownMenuItem onClick={() => navigate('/dashboard')} className="h-16 rounded-xl bg-surface p-0">
                  <div className="flex h-full w-full flex-col items-center justify-center gap-1 px-2 text-center">
                    <Search className="h-4 w-4 text-primary" />
                    <span className="text-[10px] font-bold uppercase tracking-tight text-text-primary">Inicio</span>
                  </div>
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => navigate('/admin/animals')} className="h-16 rounded-xl bg-surface p-0">
                  <div className="flex h-full w-full flex-col items-center justify-center gap-1 px-2 text-center">
                    <PawPrint className="h-4 w-4 text-primary" />
                    <span className="text-[10px] font-bold uppercase tracking-tight text-text-primary">Animales</span>
                  </div>
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => navigate('/chat')} className="h-16 rounded-xl bg-surface p-0 relative">
                  <div className="flex h-full w-full flex-col items-center justify-center gap-1 px-2 text-center">
                    <MessageCircle className="h-4 w-4 text-primary" />
                    <span className="text-[10px] font-bold uppercase tracking-tight text-text-primary">Mensajes</span>
                  </div>
                  {unreadCount > 0 && <span className="absolute right-2 top-2 h-2.5 w-2.5 rounded-full bg-primary" />}
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => navigate('/scanner')} className="h-16 rounded-xl bg-surface p-0">
                  <div className="flex h-full w-full flex-col items-center justify-center gap-1 px-2 text-center">
                    <QrCode className="h-4 w-4 text-primary" />
                    <span className="text-[10px] font-bold uppercase tracking-tight text-text-primary">Escáner</span>
                  </div>
                </DropdownMenuItem>
                <DropdownMenuItem onClick={toggleFieldMode} className={cn("h-16 rounded-xl p-0", isFieldMode ? "bg-green-600 text-white" : "bg-surface")}>
                  <div className="flex h-full w-full flex-col items-center justify-center gap-1 px-2 text-center">
                    <Mountain className={cn("h-4 w-4", isFieldMode && "animate-pulse")} />
                    <span className="text-[10px] font-bold uppercase tracking-tight">Campo</span>
                  </div>
                </DropdownMenuItem>
                <DropdownMenuItem
                  onClick={async () => {
                    if (!isOnline) return;
                    await syncNow();
                  }}
                  className={cn("h-16 rounded-xl p-0", pendingCount > 0 || isSyncing ? "bg-green-600 text-white" : "bg-surface")}
                >
                  <div className="flex h-full w-full flex-col items-center justify-center gap-1 px-2 text-center">
                    <Wifi className={cn("h-4 w-4", (pendingCount > 0 || isSyncing) && "animate-pulse")} />
                    <span className="text-[10px] font-bold uppercase tracking-tight">
                      {pendingCount > 0 ? 'Sync' : 'Al día'}
                    </span>
                  </div>
                </DropdownMenuItem>
              </div>

              <DropdownMenuItem
                onClick={async () => {
                  if (!isOnline) return;
                  await syncNow();
                }}
                className={cn(
                  "rounded-xl cursor-pointer py-2.5",
                  pendingCount > 0 || isSyncing ? "bg-green-50 text-green-800" : ""
                )}
              >
                <RefreshCw className={cn("mr-2 h-4 w-4", isSyncing && "animate-spin")} />
                <span>
                  {pendingCount > 0
                    ? `Sincronizar ${pendingCount}`
                    : isOnline
                    ? 'Sincronización al día'
                    : 'Modo campo sin red'}
                </span>
              </DropdownMenuItem>
              <DropdownMenuSeparator />

              <DropdownMenuItem onClick={() => navigate('/profile')} className="rounded-xl cursor-pointer py-2.5">
                <User className="mr-2 h-4 w-4 text-primary" />
                <span>Mi Perfil</span>
              </DropdownMenuItem>
              <DropdownMenuItem onClick={() => navigate('/chat')} className="rounded-xl cursor-pointer py-2.5">
                <MessageCircle className="mr-2 h-4 w-4 text-primary" />
                <span>Mensajes</span>
              </DropdownMenuItem>
              <DropdownMenuItem onClick={() => navigate('/dashboard')} className="rounded-xl cursor-pointer py-2.5">
                <Search className="mr-2 h-4 w-4 text-primary" />
                <span>Inicio</span>
              </DropdownMenuItem>
              <DropdownMenuItem onClick={() => {}} className="rounded-xl cursor-pointer py-2.5">
                <CreditCard className="mr-2 h-4 w-4 text-primary" />
                <span>Suscripción</span>
              </DropdownMenuItem>
              <DropdownMenuItem onClick={() => {}} className="rounded-xl cursor-pointer py-2.5">
                <Settings className="mr-2 h-4 w-4 text-primary" />
                <span>Configuración</span>
              </DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuItem onClick={() => {}} className="rounded-xl cursor-pointer py-2.5">
                <LifeBuoy className="mr-2 h-4 w-4 text-primary" />
                <span>Ayuda Técnica</span>
              </DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuItem onClick={logout} className="rounded-xl cursor-pointer py-2.5 text-destructive focus:bg-destructive focus:text-white">
                <LogOut className="mr-2 h-4 w-4" />
                <span>Cerrar Sesión</span>
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>

      {/* ── Fila de búsqueda expandible en móvil (<md) ── */}
      {mobileSearchOpen && (
        <div className="md:hidden px-3 pb-3 animate-in slide-in-from-top-2 duration-200">
          <GlobalSearchBar fullWidth />
        </div>
      )}
    </header>
  );
};

export default Header;

import React, { useState } from 'react';
import { NavLink, useLocation } from 'react-router-dom';
import { useAuth } from '@/features/auth/model/useAuth';
import { 
  LayoutDashboard, 
  BarChart3, 
  Users, 
  PawPrint, 
  Map as MapIcon, 
  Leaf, 
  Zap, 
  Dna, 
  Syringe, 
  Stethoscope, 
  ClipboardList, 
  Milk, 
  TrendingUp, 
  Calendar, 
  Package, 
  Settings, 
  FileText,
  ChevronDown,
  ChevronRight,
  LogOut,
  BellRing,
  AlertTriangle,
  BookOpen
} from 'lucide-react';
import { cn } from '@/shared/ui/cn';
import { motion, AnimatePresence } from 'framer-motion';

interface SidebarItem {
  name: string;
  path: string;
  icon: React.ElementType;
  roles?: string[];
}

interface SidebarGroup {
  label: string;
  items: SidebarItem[];
}

const Sidebar = () => {
  const { user, logout } = useAuth();
  const location = useLocation();
  const [expandedGroups, setExpandedGroups] = useState<Record<string, boolean>>({
    'Operación': true,
    'Sanidad': true,
    'Administración': false
  });

  const toggleGroup = (label: string) => {
    setExpandedGroups(prev => ({ ...prev, [label]: !prev[label] }));
  };

  const groups: SidebarGroup[] = [
    {
      label: 'Resumen',
      items: [
        { name: 'Dashboard', path: `/${user?.role?.toLowerCase()}/dashboard`, icon: LayoutDashboard },
        { name: 'Analíticas', path: `/${user?.role?.toLowerCase()}/analytics/executive`, icon: BarChart3 },
        { name: 'Biblioteca Rural', path: `/${user?.role?.toLowerCase()}/biblioteca`, icon: BookOpen },
      ]
      ]
    },
    {
      label: 'Operación',
      items: [
        { name: 'Animales', path: `/${user?.role?.toLowerCase()}/animals`, icon: PawPrint },
        { name: 'Potreros', path: `/${user?.role?.toLowerCase()}/fields`, icon: MapIcon },
        { name: 'Ubicación', path: `/${user?.role?.toLowerCase()}/animal-fields`, icon: ChevronRight },
      ]
    },
    {
      label: 'Sanidad',
      items: [
        { name: 'Controles', path: `/${user?.role?.toLowerCase()}/controls`, icon: ClipboardList },
        { name: 'Tratamientos', path: `/${user?.role?.toLowerCase()}/treatments`, icon: Stethoscope },
        { name: 'Vacunaciones', path: `/${user?.role?.toLowerCase()}/vaccinations`, icon: Syringe },
        { name: 'Enfermedades', path: `/${user?.role?.toLowerCase()}/diseases`, icon: AlertTriangle as any || FileText },
      ]
    },
    {
      label: 'Producción',
      items: [
        { name: 'Leche', path: `/${user?.role?.toLowerCase()}/milk-production`, icon: Milk },
        { name: 'Reproducción', path: `/${user?.role?.toLowerCase()}/reproduction`, icon: Dna },
        { name: 'Crecimiento', path: `/${user?.role?.toLowerCase()}/growth`, icon: TrendingUp },
      ]
    },
    {
      label: 'Administración',
      items: [
        { name: 'Usuarios', path: '/admin/users', icon: Users, roles: ['Administrador'] },
        { name: 'Inventario', path: `/${user?.role?.toLowerCase()}/inventory`, icon: Package },
        { name: 'Tareas', path: `/${user?.role?.toLowerCase()}/tasks`, icon: Calendar },
        { name: 'Gastos', path: `/${user?.role?.toLowerCase()}/operational`, icon: TrendingUp },
        { name: 'Reportes ICA', path: `/${user?.role?.toLowerCase()}/regulatory-reports`, icon: FileText },
      ]
    },
    {
      label: 'Configuración',
      items: [
        { name: 'Especies', path: `/${user?.role?.toLowerCase()}/species`, icon: Zap },
        { name: 'Razas', path: `/${user?.role?.toLowerCase()}/breeds`, icon: Dna },
        { name: 'Alimentos', path: `/${user?.role?.toLowerCase()}/food-types`, icon: Leaf },
        { name: 'Reglas de Alerta', path: '/admin/alerts', icon: BellRing, roles: ['Administrador'] },
      ]
    }
  ];

  // Helper para filtrar items por rol
  const filterItems = (items: SidebarItem[]) => {
    return items.filter(item => {
      if (!item.roles) return true;
      return item.roles.includes(user?.role || '');
    });
  };

  return (
    <aside className="w-72 h-screen bg-[#0f172a] text-slate-300 flex flex-col border-r border-white/5 shadow-2xl z-40 overflow-hidden">
      {/* Branding */}
      <div className="p-8 flex flex-col items-center gap-4 relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-b from-primary/10 to-transparent opacity-50" />

        <div className="w-16 h-16 rounded-3xl bg-gradient-to-br from-primary via-primary/80 to-primary-dark flex items-center justify-center text-white font-black text-2xl shadow-2xl shadow-primary/40 rotate-3 ring-4 ring-white/5 relative z-10">
          VL
        </div>

        <div className="text-center relative z-10">
          <h2 className="text-lg font-black text-white tracking-tighter uppercase leading-none mb-1">
            Villa Luz
          </h2>
          <span className="text-[10px] font-bold text-primary tracking-[0.3em] uppercase opacity-70">
            Ecosystem v2.5
          </span>
        </div>
      </div>

      {/* Navigation */}
      <nav className="flex-1 overflow-y-auto px-4 py-4 scrollbar-thin scrollbar-thumb-white/10 hover:scrollbar-thumb-white/20">
        {groups.map((group) => {
          const visibleItems = filterItems(group.items);
          if (visibleItems.length === 0) return null;

          const isExpanded = expandedGroups[group.label] !== false;

          return (
            <div key={group.label} className="mb-6">
              <button 
                onClick={() => toggleGroup(group.label)}
                className="w-full flex items-center justify-between px-4 py-2 mb-1 text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] hover:text-slate-300 transition-colors group"
              >
                <span>{group.label}</span>
                {isExpanded ? <ChevronDown className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
              </button>

              <AnimatePresence initial={false}>
                {isExpanded && (
                  <motion.div
                    initial={{ height: 0, opacity: 0 }}
                    animate={{ height: 'auto', opacity: 1 }}
                    exit={{ height: 0, opacity: 0 }}
                    transition={{ duration: 0.3, ease: 'easeInOut' }}
                    className="space-y-1 overflow-hidden"
                  >
                    {visibleItems.map((item) => (
                      <NavLink
                        key={item.name}
                        to={item.path}
                        className={({ isActive }) =>
                          cn(
                            "flex items-center gap-3 px-4 py-2.5 rounded-2xl text-sm font-bold transition-all duration-300 relative group",
                            isActive 
                              ? "bg-primary text-white shadow-lg shadow-primary/30 scale-[1.02]" 
                              : "hover:bg-white/5 hover:text-white"
                          )
                        }
                      >
                        <item.icon className={cn("w-4 h-4 transition-transform group-hover:scale-110", location.pathname === item.path ? "text-white" : "text-slate-400 group-hover:text-primary")} />
                        <span>{item.name}</span>

                        {location.pathname === item.path && (
                          <motion.div 
                            layoutId="active-pill"
                            className="absolute right-2 w-1.5 h-1.5 rounded-full bg-white shadow-[0_0_8px_rgba(255,255,255,0.8)]"
                          />
                        )}
                      </NavLink>
                    ))}
