export const AnimalHistoryModal = ({ animal, onClose, refreshTrigger }: AnimalHistoryModalProps) => {
  const { data: animalDiseases, refetch: refetchDiseases } = useAnimalDiseases();
  const { data: animalFields, refetch: refetchFields } = useAnimalFields();
  const { data: treatments, refetch: refetchTreatments } = useTreatment();
  const { data: controls, refetch: refetchControls } = useControls();
  const { productions: milkProductions, refetch: refetchMilk } = useMilkProduction({ animalId: animal.idAnimal });

  const [historyLoading, setHistoryLoading] = useState(false);
  const [historyError, setHistoryError] = useState<string | null>(null);
  const [remoteHistory, setRemoteHistory] = useState<any | null>(null);

  const [previewOpen, setPreviewOpen] = useState(false);
  const [previewType, setPreviewType] = useState<'treatment' | 'field' | 'disease' | 'control' | 'milk' | null>(null);
  const [previewData, setPreviewData] = useState<any>(null);

  // Cargar historial médico consolidado
  useEffect(() => {
    const controller = new AbortController();
    const load = async () => {
      setHistoryLoading(true);
      setHistoryError(null);
      try {
        const { analyticsService } = await import('@/features/reporting/api/analytics.service');
        const data = await analyticsService.getAnimalMedicalHistory(animal.idAnimal, { signal: controller.signal }).catch(() => null);
        setRemoteHistory(data);
      } catch (e: any) {
        if (e.name !== 'AbortError') {
          setHistoryError(e?.message || 'Could not load remote history');
        }
      } finally {
        setHistoryLoading(false);
      }
    };
    load();
    return () => controller.abort();
  }, [animal.idAnimal, refreshTrigger]);

  // Refrescar todos los datos al montar
  useEffect(() => {
    const refreshAllData = async () => {
      try {
        await Promise.all([
          refetchDiseases?.(),
          refetchFields?.(),
          refetchTreatments?.(),
          refetchControls?.(),
          refetchMilk?.()
        ]);
      } catch (e) {}
    };
    refreshAllData();
  }, [refetchDiseases, refetchFields, refetchTreatments, refetchControls, refetchMilk]);

  // Helper para determinar si un registro pertenece al animal actual
  const belongsToAnimal = (item: any) => {
    const ids = [
      item?.animal_id,
      item?.animals?.id,
      item?.animal?.id,
      item?.animal?.idAnimal,
      item?.animals?.idAnimal,
    ].filter((v) => v !== undefined && v !== null);
    return ids.some((id) => Number(id) === Number(animal.idAnimal));
  };

  const animalDiseasesData = safeArray(animalDiseases).filter(belongsToAnimal);
  const animalFieldsData = safeArray(animalFields).filter(belongsToAnimal);
  const animalTreatmentsData = safeArray(treatments).filter(belongsToAnimal);
  const animalControlsData = safeArray(controls).filter(belongsToAnimal);

  // Crear eventos del cronograma
  const timelineEvents = useMemo(() => {
    const events: TimelineEvent[] = [];

    // Enfermedades
    animalDiseasesData.forEach((d: any) => {
      events.push({
        id: `disease-${d.id}`,
        date: d.treatment_date,
        type: 'disease',
        title: `Patología: ${d.disease?.name || 'Desconocida'}`,
        description: `Tratamiento: ${d.treatment || 'En observación'}`,
        status: d.status,
        icon: <Stethoscope className="w-5 h-5" />,
        previewType: 'disease',
        previewData: d
      });
    });

    // Tratamientos
    animalTreatmentsData.forEach((t: any) => {
      events.push({
        id: `treatment-${t.id}`,
        date: t.treatment_date,
        type: 'treatment',
        title: `Tratamiento: ${t.description}`,
        description: `Dosis: ${t.dosis} - Frecuencia: ${t.frequency}`,
        status: 'active',
        icon: <Syringe className="w-5 h-5" />,
        previewType: 'treatment',
        previewData: t
      });
    });

    // Controles
    animalControlsData.forEach((c: any) => {
      events.push({
        id: `control-${c.id}`,
        date: c.checkup_date,
        type: 'control',
        title: 'Control de Salud',
        description: `${c.health_status || 'Revisión general'} - ${c.weight ? c.weight + 'kg' : ''}`,
        status: c.health_status,
        icon: <Activity className="w-5 h-5" />,
        previewType: 'control',
        previewData: c
      });
    });

    // Movimientos
    animalFieldsData.forEach(f => {
      events.push({
        id: `movement-${f.id}`,
        date: f.assignment_date,
        type: 'movement',
        title: `Asignación: ${f.field?.name}`,
        description: `Motivo: ${f.reason || 'Rotación técnica'}`,
        status: f.removal_date ? 'completed' : 'active',
        icon: <MapPin className="w-5 h-5" />,
        previewType: 'field',
        previewData: f
      });
    });

    // Ordeño
    safeArray(milkProductions).forEach((m: any) => {
      events.push({
        id: `milk-${m.id}`,
        date: m.date,
        type: 'milk',
        title: `Producción: ${m.liters}L`,
        description: `Sesión: ${m.session} - ${m.notes || 'Normal'}`,
        icon: <Milk className="w-5 h-5" />,
        previewType: 'milk',
        previewData: m
      });
    });

    return events.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [animalDiseasesData, animalTreatmentsData, animalControlsData, animalFieldsData, milkProductions]);

  const openPreview = (type: any, data: any) => {
    setPreviewType(type);
    setPreviewData(data);
    setPreviewOpen(true);
  };

  const closePreview = () => {
    setPreviewOpen(false);
    setPreviewData(null);
    setPreviewType(null);
  };

  return (
    <>
      <Modal isOpen={true} onClose={onClose} size="6xl" className="p-0 overflow-hidden">
        <ModalHeader className="bg-slate-900 text-white p-8 relative overflow-hidden border-0">
          <div className="absolute top-0 right-0 w-1/2 h-full bg-gradient-to-l from-primary/20 to-transparent blur-3xl opacity-50" />
          <div className="relative z-10 flex items-center justify-between gap-6">
            <div className="flex items-center gap-6">
              <div className="flex h-16 w-16 items-center justify-center rounded-[1.5rem] bg-white/10 backdrop-blur-xl border border-white/20 text-white shadow-2xl">
                <HistoryIcon className="h-8 w-8" />
              </div>
              <div>
                <h2 className="text-3xl font-black tracking-tighter uppercase leading-tight">
                  Historial <span className="text-primary">Específico</span>
                </h2>
                <div className="flex items-center gap-2 text-slate-400 font-bold text-[10px] uppercase tracking-[0.2em] mt-1">
                  <span>{animal.breed?.name || 'Mestizo'}</span>
                  <span className="h-1 w-1 rounded-full bg-slate-600" />
                  <span>ID: {animal.record}</span>
                  <ICAComplianceBadge animalId={animal.idAnimal} />
                </div>
              </div>
            </div>

            <div className="hidden md:flex items-center gap-4">
               <div className="bg-white/5 backdrop-blur-md border border-white/10 rounded-2xl p-4 flex items-center gap-4">
                  <div className="text-right">
                    <p className="text-[9px] font-black uppercase tracking-widest text-slate-500">Estado Vital</p>
                    <p className="text-sm font-bold text-emerald-400 uppercase tracking-tighter">Sincronizado</p>
                  </div>
                  <div className="h-10 w-10 rounded-full bg-emerald-500/20 border border-emerald-500/30 flex items-center justify-center">
                    <div className="h-3 w-3 rounded-full bg-emerald-500 animate-pulse" />
                  </div>
               </div>
            </div>
          </div>
        </ModalHeader>

        <ModalContent className="p-0 bg-slate-50/50 dark:bg-black/20">
          <ModalBody className="p-0 h-[700px] flex flex-col">
            {historyLoading ? (
               <div className="flex-1 flex flex-col items-center justify-center space-y-4">
                 <div className="h-12 w-12 border-4 border-primary border-t-transparent rounded-full animate-spin" />
                 <p className="text-xs font-black uppercase tracking-widest text-slate-400">Consultando registros...</p>
               </div>
            ) : (
              <Tabs defaultValue="timeline" className="flex flex-col h-full">
                <div className="px-8 py-4 border-b border-white/20 bg-white/40 dark:bg-slate-900/40 backdrop-blur-md sticky top-0 z-10">
                  <TabsList className="h-12 p-1.5 bg-slate-200/50 dark:bg-slate-800/50 backdrop-blur-sm rounded-xl w-fit mx-auto overflow-x-auto flex-nowrap [scrollbar-width:none]">
                    <TabsTrigger value="timeline" className="rounded-lg font-black text-[10px] uppercase tracking-widest data-[state=active]:bg-primary data-[state=active]:text-white transition-all px-6">Cronograma</TabsTrigger>
                    <TabsTrigger value="health" className="rounded-lg font-black text-[10px] uppercase tracking-widest data-[state=active]:bg-primary data-[state=active]:text-white transition-all px-6">Salud</TabsTrigger>
                    <TabsTrigger value="production" className="rounded-lg font-black text-[10px] uppercase tracking-widest data-[state=active]:bg-primary data-[state=active]:text-white transition-all px-6">Producción</TabsTrigger>
                    <TabsTrigger value="management" className="rounded-lg font-black text-[10px] uppercase tracking-widest data-[state=active]:bg-primary data-[state=active]:text-white transition-all px-6">Manejo</TabsTrigger>
