import React, { useState } from 'react';
import { MoreVertical, PawPrint } from 'lucide-react';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/shared/ui/dropdown-menu';
import { GenericModal } from '@/shared/ui/common/GenericModal';
import { BreedResponse } from '@/shared/api/generated/swaggerTypes';
import { Badge } from '@/shared/ui/badge';

// Importar servicios
import { animalsService } from '@/entities/animal/api/animal.service';

interface BreedActionsMenuProps {
  breed: BreedResponse;
}

export const BreedActionsMenu: React.FC<BreedActionsMenuProps> = ({ breed }) => {
  const [showAnimalsModal, setShowAnimalsModal] = useState(false);
  const [animals, setAnimals] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);

  const loadAnimals = async () => {
    setLoading(true);
    try {
      const result = await animalsService.getAnimals({ page: 1, limit: 1000 });
      const animalsData = Array.isArray(result) ? result : (result?.data || result?.items || []);

      // Filtrar animales por breed_id
      const filteredAnimals = animalsData.filter((animal: any) => animal.breed_id === breed.id);
      setAnimals(filteredAnimals);
    } catch (err) {
      console.error('Error loading animals:', err);
      setAnimals([]);
    } finally {
      setLoading(false);
    }
  };

  const handleOpenAnimalsModal = () => {
    setShowAnimalsModal(true);
    loadAnimals();
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Sano':
        return 'bg-green-100 text-green-800';
      case 'Enfermo':
        return 'bg-red-100 text-red-800';
      case 'En tratamiento':
        return 'bg-yellow-100 text-yellow-800';
      case 'En observación':
        return 'bg-blue-100 text-blue-800';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };

  const renderAnimalsList = () => {
    if (loading) {
      return (
        <div className="py-10 text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto mb-4"></div>
          <p className="text-muted-foreground">Cargando animales...</p>
        </div>
      );
    }

    if (animals.length === 0) {
      return (
        <div className="py-10 text-center">
          <p className="text-muted-foreground">No hay animales registrados para esta raza</p>
        </div>
      );
    }

    return (
      <div className="space-y-3 max-h-[500px] overflow-y-auto">
        {animals.map((animal, index) => (
          <div
            key={animal.id || index}
            className="border border-border rounded-lg p-4 bg-card hover:bg-accent/50 transition-colors"
          >
            <div className="space-y-2 text-sm">
              <div className="flex justify-between items-center">
                <span className="font-medium text-foreground">Registro:</span>
                <span className="text-muted-foreground font-semibold">{animal.record || '-'}</span>
              </div>

              {animal.name && (
                <div className="flex justify-between">
                  <span className="font-medium text-foreground">Nombre:</span>
                  <span className="text-muted-foreground">{animal.name}</span>
                </div>
              )}

              <div className="flex justify-between items-center">
                <span className="font-medium text-foreground">Estado:</span>
                <Badge className={`text-xs ${getStatusColor(animal.status)}`}>
                  {animal.status || 'Sin estado'}
                </Badge>
              </div>

              <div className="flex justify-between">
                <span className="font-medium text-foreground">Género:</span>
                <span className="text-muted-foreground">{animal.gender || '-'}</span>
              </div>

              <div className="flex justify-between">
                <span className="font-medium text-foreground">Fecha de Nacimiento:</span>
                <span className="text-muted-foreground">
                  {animal.birth_date ? new Date(animal.birth_date).toLocaleDateString('es-ES') : '-'}
                </span>
              </div>

              {animal.weight && (
                <div className="flex justify-between">
                  <span className="font-medium text-foreground">Peso:</span>
                  <span className="text-muted-foreground">{animal.weight} kg</span>
                </div>
              )}

              {animal.notes && (
                <div>
                  <span className="font-medium text-foreground">Notas:</span>
                  <p className="text-muted-foreground mt-1">{animal.notes}</p>
                </div>
              )}

              <div className="flex justify-between">
                <span className="font-medium text-foreground">Creado:</span>
                <span className="text-muted-foreground">
                  {animal.created_at ? new Date(animal.created_at).toLocaleDateString('es-ES') : '-'}
                </span>
              </div>
            </div>
          </div>
        ))}
      </div>
    );
  };

  return (
    <>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <button
            className="icon-btn p-1.5 hover:bg-accent rounded-md transition-colors"
            onClick={(e) => e.stopPropagation()}
            title="Más acciones"
            aria-label="Más acciones"
          >
            <MoreVertical className="h-4 w-4" />
          </button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end" className="w-56">
          <DropdownMenuItem
            onClick={(e) => {
              e.stopPropagation();
              handleOpenAnimalsModal();
            }}
            className="cursor-pointer"
          >
            <PawPrint className="mr-2 h-4 w-4" />
            Ver Animales
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>

      <GenericModal
        isOpen={showAnimalsModal}
        onOpenChange={setShowAnimalsModal}
        title={`Animales de la raza ${breed.name || 'Raza'}`}
        description={`Listado de animales registrados`}
        size="2xl"
        enableBackdropBlur
        className="bg-card/95 backdrop-blur-md text-card-foreground border-border/50"
      >
        <div className="space-y-4">
          {renderAnimalsList()}
        </div>
      </GenericModal>
    </>
  );
};

import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import { CalendarDays, CircleAlert, CircleCheck, RefreshCw, Syringe, Stethoscope, Package } from 'lucide-react';
import { api } from '@/shared/api/base-client';

interface CalendarioEvento {
  codigo: string;
  nombre: string;
  descripcion: string;
  tipo: string;
  obligatorio_ica: boolean;
  producto_sugerido?: string;
  dosis_referencia?: string;
  fuente?: string;
  animal_id?: number;
  animal_record?: string;
  edad_actual_dias?: number;
}

interface Props {
  /** Si se pasa animalId, muestra solo ese animal. Sin él, muestra el hato completo. */
  animalId?: number;
  maxItems?: number;
}

const TIPO_ICON: Record<string, React.ReactNode> = {
  'Vacunación':      <Syringe className="h-4 w-4" />,
  'Desparasitación': <Package className="h-4 w-4" />,
  'Reproducción':    <Stethoscope className="h-4 w-4" />,
  'Nutrición':       <Package className="h-4 w-4" />,
  'Manejo':          <Stethoscope className="h-4 w-4" />,
};

export const CalendarioSanitarioWidget: React.FC<Props> = ({ animalId, maxItems = 10 }) => {
  const [eventos, setEventos] = useState<CalendarioEvento[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState(false);

  const cargar = async () => {
    setLoading(true); setError(false);
    try {
      const t = new Date().getTime();
      const url = animalId
        ? `/knowledge_base/calendario/animal/${animalId}?_t=${t}`
        : `/knowledge_base/calendario/hato?_t=${t}`;
      const res = await api.get(url);
      const data = res.data?.data || res.data || [];
      setEventos(Array.isArray(data) ? data.slice(0, maxItems) : []);
    } catch {
      setError(true);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { cargar(); }, [animalId]);

  if (loading) return (
    <div className="flex items-center justify-center gap-2 py-6 text-sm text-muted-foreground">
      <RefreshCw className="h-4 w-4 animate-spin" />
      Cargando calendario sanitario...
    </div>
  );

  if (error) return (
    <div className="flex items-center gap-2 p-4 bg-red-50 dark:bg-red-950/30 rounded-xl text-red-700 dark:text-red-300 text-sm">
      <CircleAlert className="h-4 w-4 shrink-0" />
      No se pudo cargar el calendario. Revisa la conexión.
    </div>
  );

  if (eventos.length === 0) return (
    <div className="flex items-center gap-3 p-4 bg-emerald-50 dark:bg-emerald-950/20 rounded-xl">
      <CircleCheck className="h-6 w-6 text-emerald-600 shrink-0" />
      <div>
        <p className="font-semibold text-emerald-800 dark:text-emerald-300 text-sm">
          {animalId ? 'Este animal está al día' : '¡El hato está al día!'}
        </p>
        <p className="text-xs text-emerald-600 dark:text-emerald-400">
          No hay eventos sanitarios pendientes.
        </p>
      </div>
    </div>
  );

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2 text-sm font-semibold text-foreground">
          <CalendarDays className="h-4 w-4 text-amber-500" />
          {eventos.length} evento{eventos.length !== 1 ? 's' : ''} pendiente{eventos.length !== 1 ? 's' : ''}
        </div>
        <button
          onClick={cargar}
          className="text-xs text-muted-foreground hover:text-foreground transition-colors flex items-center gap-1"
        >
          <RefreshCw className="h-3 w-3" /> Actualizar
        </button>
      </div>

      {eventos.map((ev, i) => (
        <motion.div
          key={`${ev.codigo}-${ev.animal_id ?? i}`}
          initial={{ opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: i * 0.05 }}
          className={[
            'flex items-start gap-3 p-3 rounded-xl border text-sm',
            ev.obligatorio_ica
              ? 'bg-red-50 dark:bg-red-950/20 border-red-200 dark:border-red-800'
              : 'bg-amber-50 dark:bg-amber-950/20 border-amber-200 dark:border-amber-800'
          ].join(' ')}
        >
          <div className={[
            'p-1.5 rounded-lg shrink-0 mt-0.5',
            ev.obligatorio_ica ? 'bg-red-100 text-red-600' : 'bg-amber-100 text-amber-700'
          ].join(' ')}>
            {TIPO_ICON[ev.tipo] ?? <CalendarDays className="h-4 w-4" />}
          </div>

          <div className="flex-1 min-w-0">
            <div className="flex items-start justify-between gap-2">
              <p className="font-semibold text-foreground leading-snug">{ev.nombre}</p>
              {ev.obligatorio_ica && (
                <span className="text-[10px] bg-red-600 text-white px-2 py-0.5 rounded-full font-bold shrink-0">
                  ICA
                </span>
              )}
            </div>
            <p className="text-xs text-muted-foreground mt-0.5 line-clamp-2">{ev.descripcion}</p>
            {ev.producto_sugerido && (
              <p className="text-[11px] font-medium text-foreground/70 mt-1">
                💊 {ev.producto_sugerido} {ev.dosis_referencia ? `· ${ev.dosis_referencia}` : ''}
              </p>
            )}
            {!animalId && ev.animal_record && (
              <p className="text-[11px] text-primary font-semibold mt-1">🐄 {ev.animal_record}</p>
            )}
          </div>
        </motion.div>
      ))}
    </div>
  );
};

import { Card, CardHeader, CardContent as CardBody } from "@/shared/ui/card";
import { useState } from "react";
import { lazy, Suspense } from 'react';
const GeneticTreeModal = lazy(() => import('./GeneticTreeModal'));
import { useAnimals } from "@/entities/animal/model/useAnimals";
import { useAnimalTreeApi, graphToAncestorLevels } from "@/entities/animal/model/useAnimalTreeApi";
import type { AnimalTreeSummary, AnimalTreeEdgeExamples } from "@/entities/animal/model/tree.types";

interface StatisticsCardProps {
    title: string
    description?: string
    value: number | string
    color?: string
    showGeneticTree?: boolean
    icon?: React.ReactNode
    className?: string
}

const StatisticsCard = ({title, value, description, color, showGeneticTree = false, icon, className = ""}: StatisticsCardProps) => {
    const [isModalOpen, setIsModalOpen] = useState(false);
    const { animals } = useAnimals();
    const { fetchAncestors, loadMore, graph, loading } = useAnimalTreeApi();
    const [selectedAnimalId, setSelectedAnimalId] = useState<number | null>(null);
    const [treeData, setTreeData] = useState<{ animal: any | null; levels: any[]; counts?: { nodes: number; edges: number }; summary?: AnimalTreeSummary; edgeExamples?: AnimalTreeEdgeExamples } | null>(null);
    const [loadingMore, setLoadingMore] = useState(false);

    // ...existing code...

    // Select first animal by default if another is not passed
    const getInitialAnimalId = () => animals && animals.length > 0 ? animals[0].id ?? null : null;

    const [, setTreeLoading] = useState(false);

    return (
        <>
            <Card 
                className={`group relative overflow-hidden h-auto p-6 transition-all duration-300 hover-lift border-border bg-surface shadow-sm ${showGeneticTree ? 'cursor-pointer' : ''} ${className}`} 
                onClick={async () => {
                    if (showGeneticTree) {
                        const id = getInitialAnimalId();
                        if (!id) return;
                        setTreeLoading(true);
                        const resp = await fetchAncestors(id, 3, 'id,record,sex');
                        setTreeLoading(false);
                        if (!resp) return;
                        setSelectedAnimalId(id);
                        setTreeData({
                            animal: resp.nodes?.[resp.rootId] ?? null,
                            levels: graphToAncestorLevels(resp),
                            counts: resp.counts,
                            summary: resp.summary,
                            edgeExamples: resp.edge_examples,
                        });
                        setIsModalOpen(true);
                    }
                }}
            >
                <div className="flex items-start justify-between">
                    <div className="space-y-2">
                        <p className="text-[10px] font-black uppercase tracking-widest text-text-secondary opacity-60">
                            {title}
                        </p>
                        <h3 className={`text-3xl font-black tracking-tighter text-text-primary ${color || ''}`}>
                            {value}
                        </h3>
                        {description && (
                            <p className="text-xs text-text-secondary opacity-80 leading-snug max-w-[150px]">
                                {description}
                            </p>
                        )}
                    </div>
                    
                    {icon && (
                        <div className={`p-3 rounded-2xl bg-primary/5 text-primary group-hover:bg-primary/10 transition-colors`}>
                            {icon}
                        </div>
                    )}
                </div>
                
                {/* Decorative background element */}
                <div className="absolute -bottom-4 -right-4 w-24 h-24 bg-primary/5 rounded-full blur-2xl group-hover:bg-primary/10 transition-all" />
            </Card>

            {showGeneticTree && selectedAnimalId !== null && treeData && (
                <Suspense fallback={<div className="flex justify-center items-center p-4"><span className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></span> Cargando árbol genético...</div>}>
                    <GeneticTreeModal
                        isOpen={isModalOpen}
                        onClose={() => {
                            setIsModalOpen(false);
                            setTreeData(null);
                            setSelectedAnimalId(null);
                        }}
                        animal={treeData.animal}
                        levels={treeData.levels}
                        counts={treeData.counts}
                        summary={treeData.summary}
                        edgeExamples={treeData.edgeExamples}
                        loadingMore={loading || loadingMore}
                        onLoadMore={async () => {
                            if (!graph || !selectedAnimalId || !treeData?.levels) return;
                            setLoadingMore(true);
                            const next = await loadMore('ancestors', selectedAnimalId, graph, { increment: 2, fields: 'id,record,sex' });
                            setLoadingMore(false);
                            if (next) {
                                setTreeData({
                                    animal: next.nodes?.[next.rootId] ?? treeData.animal,
                                    levels: graphToAncestorLevels(next),
                                    counts: next.counts,
                                    summary: next.summary,
                                    edgeExamples: next.edge_examples,
                                });
                            }
                        }}
                    />
                </Suspense>
            )}
        </>
    );
};

export default StatisticsCard;

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { AlertTriangle, CircleCheck, History, ArrowRight, ShieldCheck, RefreshCw } from 'lucide-react';
import { ConflictResolver, ConflictLog } from '@/shared/api/offline/ConflictResolver';
