                </p>
              </div>
 
              <div className="grid grid-cols-[1fr,24px,1fr] items-center gap-2">
                <div className={`p-2 rounded-xl border opacity-50 line-through ${
                  isFieldMode ? 'bg-black border-gray-700' : 'bg-white border-red-50'
                }`}>
                  <p className="text-[9px] font-bold text-gray-400">DATO ANTERIOR</p>
                  <p className="text-xs font-black text-gray-500">
                    {typeof log.loser.data === 'object' ? 'Ver Detalles' : String(log.loser.data).slice(0, 15)}
                  </p>
                </div>
                
                <ArrowRight size={14} className={isFieldMode ? 'text-white' : 'text-amber-500'} />
 
                <div className={`p-2 rounded-xl border ${
                  isFieldMode ? 'bg-green-900 border-green-500' : 'bg-green-50 border-green-100'
                }`}>
                  <p className={`text-[9px] font-bold ${isFieldMode ? 'text-white' : 'text-green-600'}`}>DATO NUEVO</p>
                  <p className={`text-xs font-black ${isFieldMode ? 'text-white' : 'text-gray-900'}`}>
                    {typeof log.winner.data === 'object' ? 'Actualizado ✅' : String(log.winner.data).slice(0, 15)}
                  </p>
                </div>
              </div>
 
              <p className={`flex items-center gap-1 ${isFieldMode ? 'text-xs text-gray-300' : 'text-[9px] text-gray-500'}`}>
                <CircleCheck size={10} className="text-green-500" />
                Sincronización automática: prevalece el cambio más reciente.
              </p>
            </motion.div>
          ))}
        </AnimatePresence>
      </div>

      <button 
        onClick={() => { ConflictResolver.clearLogs(); setLogs([]); }}
        className="mt-4 text-[10px] font-bold text-gray-400 hover:text-red-500 transition-colors uppercase text-center"
      >
        Limpiar historial de conflictos
      </button>
    </div>
  );
