import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useAnalytics } from '@/features/reporting/model/useAnalytics';
import {
  CheckCircleIcon,
  ExclamationTriangleIcon,
  XCircleIcon,
  ArrowRightIcon,
  WifiIcon,
  SignalIcon,
  ArrowPathIcon
} from '@heroicons/react/24/outline';
import { useFieldMode } from '@/app/providers/FieldModeContext';
import { proximitySync } from '@/shared/api/offline/ProximitySyncService';
import { offlineQueue } from '@/shared/api/offline/offlineQueue';

/**
 * Guía del Día — muestra las acciones prioritarias de hoy basadas en alertas reales.
 * Diseñado para que el campesino sepa exactamente qué hacer al empezar la jornada.
 */

const actionRoutes: Record<string, string> = {
  Salud:         '/admin/controls',
  Reproducción:  '/admin/reproduction',
  Crecimiento:   '/admin/growth',
  Estado:        '/admin/animal-fields',
  Personalizada: '/admin/animals',
  Predictiva:    '/admin/analytics/executive',
};

function getPriorityIcon(priority: string) {
  const p = priority?.toLowerCase();
  if (p === 'crítica') return <XCircleIcon className="w-5 h-5 text-red-500 flex-shrink-0" />;
  if (p === 'alta')    return <ExclamationTriangleIcon className="w-5 h-5 text-orange-500 flex-shrink-0" />;
  return <CheckCircleIcon className="w-5 h-5 text-yellow-500 flex-shrink-0" />;
}

function getPriorityBg(priority: string): string {
  const p = priority?.toLowerCase();
  if (p === 'crítica') return 'border-l-red-500 bg-red-50 dark:bg-red-950/20';
  if (p === 'alta')    return 'border-l-orange-500 bg-orange-50 dark:bg-orange-950/20';
  if (p === 'media')   return 'border-l-yellow-500 bg-yellow-50 dark:bg-yellow-950/20';
  return 'border-l-blue-400 bg-blue-50 dark:bg-blue-950/20';
}

const DailyFarmGuide: React.FC = () => {
  const navigate = useNavigate();
  const { useAlerts } = useAnalytics();
  const { isFieldMode } = useFieldMode();
  const [meshNodes, setMeshNodes] = React.useState(0);
  const [pendingOps, setPendingOps] = React.useState(0);

  React.useEffect(() => {
    const update = async () => {
      setPendingOps(await offlineQueue.getPendingCount());
      setMeshNodes(proximitySync.getDiscoveredPeers().length);
    };
    const interval = setInterval(update, 5000);
    update();
    return () => clearInterval(interval);
  }, []);

  // Obtener las alertas más urgentes del día (críticas y altas, máx 7)
  const { data: criticalData, isLoading: l1 } = useAlerts({ priority: 'Crítica', limit: 4 });
  const { data: highData,     isLoading: l2 } = useAlerts({ priority: 'Alta',    limit: 5 });

  const isLoading = l1 || l2;

  const topAlerts = [
    ...(criticalData?.alerts || []),
    ...(highData?.alerts    || []),
  ].slice(0, 7);

  const criticalCount = criticalData?.statistics?.total || 0;
  const highCount     = highData?.statistics?.total     || 0;
  const totalUrgent   = criticalCount + highCount;

  return (
    <div className={`rounded-3xl overflow-hidden shadow-sm border ${
      isFieldMode ? 'bg-black border-4 border-white' : 'bg-surface border-border'
    }`}>
      {/* Header */}
      <div className={`px-6 py-5 border-b ${
        isFieldMode ? 'bg-zinc-900 border-white' : 'bg-gradient-to-r from-amber-500/10 via-orange-500/5 to-transparent border-border'
      }`}>
        <div className="flex items-center justify-between">
          <div>
            <h2 className={`font-black tracking-tight ${isFieldMode ? 'text-3xl text-white uppercase' : 'text-xl text-text-primary'}`}>
              🌅 Guía del Día
            </h2>
            <p className={`mt-0.5 ${isFieldMode ? 'text-lg text-gray-300' : 'text-sm text-text-secondary'}`}>
              Acciones prioritarias para hoy en la finca
            </p>
          </div>
          {!isLoading && totalUrgent > 0 && (
            <div className="flex gap-2">
              {criticalCount > 0 && (
                <span className="px-3 py-1 bg-red-100 text-red-700 text-xs font-bold rounded-full">
                  {criticalCount} Críticas
                </span>
              )}
              {highCount > 0 && (
                <span className="px-3 py-1 bg-orange-100 text-orange-700 text-xs font-bold rounded-full">
                  {highCount} Altas
                </span>
              )}
            </div>
          )}
          {/* Indicador Mesh en Header */}
          <div className="flex items-center gap-2">
            {pendingOps > 0 && (
              <div className={`flex items-center gap-1 px-2 py-1 rounded-md animate-pulse ${isFieldMode ? 'bg-red-600' : 'bg-red-100 text-red-600'}`}>
                <ArrowPathIcon className="w-3 h-3" />
                <span className="text-[10px] font-black">{pendingOps}</span>
              </div>
            )}
            <div className={`flex items-center gap-1 px-2 py-1 rounded-md ${
              meshNodes > 0 
                ? (isFieldMode ? 'bg-green-600' : 'bg-green-100 text-green-600') 
                : (isFieldMode ? 'bg-zinc-800' : 'bg-gray-100 text-gray-400')
            }`}>
              <SignalIcon className="w-3 h-3" />
              <span className="text-[10px] font-black">{meshNodes} MESH</span>
            </div>
          </div>
        </div>
      </div>

      {/* Contenido */}
      <div className="p-4 space-y-2">
        {isLoading ? (
          <div className="space-y-2">
            {[1, 2, 3].map(i => (
              <div key={i} className="h-14 bg-border/30 rounded-xl animate-pulse" />
            ))}
          </div>
        ) : topAlerts.length === 0 ? (
          <div className="text-center py-10">
            <p className="text-4xl mb-2">✅</p>
            <p className="font-bold text-text-primary">¡Todo en orden hoy!</p>
            <p className="text-sm text-text-secondary mt-1">No hay acciones urgentes pendientes.</p>
          </div>
        ) : (
          <>
            {topAlerts.map((alert: any, idx: number) => (
              <button
                key={alert.id || idx}
                onClick={() => navigate(actionRoutes[alert.type] || '/admin/analytics/executive')}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl border-l-4 text-left transition-all hover:shadow-md hover:-translate-y-0.5 ${
                  isFieldMode 
                    ? 'bg-zinc-900 border-white text-white mb-2' 
                    : getPriorityBg(alert.priority)
                }`}
              >
                {getPriorityIcon(alert.priority)}
                <div className="flex-1 min-w-0">
                  <p className={`font-bold uppercase tracking-wider ${isFieldMode ? 'text-sm text-green-500' : 'text-xs text-text-secondary'}`}>
                    {alert.type} · {alert.animal_record || 'Finca'}
                  </p>
                  <p className={`font-medium truncate mt-0.5 ${isFieldMode ? 'text-lg' : 'text-sm text-text-primary'}`}>
                    {alert.message}
                  </p>
                </div>
                <ArrowRightIcon className={`flex-shrink-0 opacity-60 ${isFieldMode ? 'w-6 h-6 text-white' : 'w-4 h-4 text-text-secondary'}`} />
              </button>
            ))}

            {totalUrgent > 7 && (
              <button
                onClick={() => navigate('/admin/analytics/executive')}
                className="w-full text-center text-sm font-semibold text-primary py-2 hover:underline"
              >
                Ver {totalUrgent - 7} alertas más →
              </button>
            )}
          </>
        )}
      </div>

      {/* Footer - accesos rápidos */}
      <div className={`px-6 py-4 border-t ${isFieldMode ? 'bg-zinc-900 border-white' : 'bg-background/50 border-border'}`}>
        <div className="flex flex-wrap gap-2">
          {[
            { label: '💉 Vacunaciones',    path: '/admin/vaccinations' },
            { label: '⚕️ Controles',       path: '/admin/controls'      },
            { label: '🐄 Reproducción',    path: '/admin/reproduction' },
            { label: '💊 Tratamientos',    path: '/admin/treatments'   },
            { label: '📦 Inventario',      path: '/admin/inventory'    },
          ].map(link => (
            <button
              key={link.path}
              onClick={() => navigate(link.path)}
              className={`px-3 py-1.5 font-medium border rounded-lg transition-colors ${
                isFieldMode 
                  ? 'bg-black border-white text-white text-sm hover:bg-zinc-800' 
                  : 'bg-surface border-border text-text-secondary text-xs hover:bg-state-hover'
              }`}
            >
              {link.label}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

export default DailyFarmGuide;

import { useState, useEffect, lazy, Suspense } from 'react';
import { useAuth } from '@/features/auth/model/useAuth';
import { ToastProvider } from '@/app/providers/ToastContext';
import { ToastContainer } from '@/shared/ui/ToastContainer';
import { useSidebar } from '@/app/providers/SidebarContext';
import { cn } from '@/shared/ui/cn';
import RoleBasedSideBar from "./RoleBasedSideBar";
import Footer from '../landing/Footer';
import LoadingScreen from '@/shared/ui/common/LoadingScreen';
const PerformanceMonitor = lazy(() => import('./PerformanceMonitor'));

// Safe accessor for Vite env that works under Jest (no ESM import.meta parsing)
const viteEnv: Record<string, any> = ((globalThis as any)?.['import']?.['meta']?.['env'])
  || ((typeof (globalThis as any).process !== 'undefined' ? ((globalThis as any).process as any).env : undefined) as any)
  || {};

interface DashboardLayoutProps {
  children: React.ReactNode;
}

const DashboardLayout = ({ children }: DashboardLayoutProps) => {
  const { loading } = useAuth();
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDesktop, setIsDesktop] = useState(false);
  const { sidebarWidth } = useSidebar();

  const sidebarProps = { isSidebarOpen, setIsSidebarOpen };

  // Detectar si estamos en desktop
  useEffect(() => {
    const checkIsDesktop = () => {
      const isLarge = window.innerWidth >= 1024;
      setIsDesktop(isLarge);
      // Auto-collapse sidebar on resize to prevent overlay issues when switching modes
      // or to ensure it starts closed on mobile resize.
      if (!isLarge) {
        setIsSidebarOpen(false);
      }
    };

    checkIsDesktop();
    window.addEventListener('resize', checkIsDesktop);

    return () => {
      window.removeEventListener('resize', checkIsDesktop);
    };
  }, []);

  // Mostrar loading hasta que el auth esté listo
  if (loading) {
    return <LoadingScreen />;
  }

  return (
    <ToastProvider>
      <div className="flex flex-col h-[100dvh] w-full overflow-hidden bg-gray-100">
        <div className="flex flex-1 min-h-0">
          <RoleBasedSideBar {...sidebarProps} />

          <main
            className={cn(
              "flex-1 min-h-0 overflow-auto scrollbar-hide transition-all duration-300 ease-in-out flex flex-col",
              isDesktop ? "" : "ml-0"
            )}
            style={{ marginLeft: isDesktop ? `${sidebarWidth}px` : '0px' }}
          >
            {/* Contenido principal con gradiente */}
            <div className="flex-1 min-h-full bg-gradient-to-b from-gray-300">
              {children}
            </div>

            {/* Footer pegado al final sin espacios ni margen */}
            <Footer />
          </main>

          {isSidebarOpen && !isDesktop && (
            <div
              className="fixed inset-0 z-[40] bg-black/60 backdrop-blur-sm lg:hidden transition-opacity duration-300"
              onClick={() => setIsSidebarOpen(false)}
            ></div>
          )}

          {/* Monitor de rendimiento solo en desarrollo */}
          {viteEnv.DEV && viteEnv.VITE_ENABLE_PERFORMANCE_MONITORING === 'true' && (
            <Suspense fallback={<div className="flex justify-center items-center p-4"><span className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></span> Cargando monitor...</div>}>
              <PerformanceMonitor />
            </Suspense>
          )}
        </div>
        <ToastContainer />
      </div>
    </ToastProvider>
  );
};

export default DashboardLayout;

