import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { BrainCircuit, Activity, Map as MapIcon, Cpu, Network, Zap } from 'lucide-react';
import { useAnalytics } from '@/features/reporting/model/useAnalytics';
import { proximitySync } from '@/shared/api/offline/ProximitySyncService';
import { analyticsService } from '@/features/reporting/api/analytics.service';

export const ExecutiveIntelligence: React.FC = () => {
  const { useDashboard } = useAnalytics();
  const { data: dashboardStats } = useDashboard();
  const [meshSyncs, setMeshSyncs] = useState(0);
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  useEffect(() => {
    // Cargar insight previo si existe
    const loadInsight = async () => {
      try {
        const insightRes = await analyticsService.getPredictiveInsights();
        setAiInsight(insightRes.insight);
      } catch (err) {
        console.warn('Usando datos cacheados para panel ejecutivo');
      }
    };
    loadInsight();

    // Obtener estadísticas reales de sincronización Mesh
    if (proximitySync && typeof proximitySync.getSyncState === 'function') {
      const syncState = proximitySync.getSyncState();
      setMeshSyncs(syncState.messagesReceived + syncState.messagesSent);
    }
  }, []);

  const handleRunAnalysis = async () => {
    setIsAnalyzing(true);
    setAiInsight("Iniciando escaneo inteligente del hato... Esto puede tomar unos minutos.");
    try {
      const res = await analyticsService.runPredictiveAnalysis();
      setAiInsight(res.message || "Análisis en ejecución...");
      
      // En lugar de un timeout arbitrario, refrescamos directamente si el servicio lo permite
      const updated = await analyticsService.getPredictiveInsights();
      setAiInsight(updated.insight);
      
    } catch (err) {
      console.error('Error al ejecutar análisis de IA:', err);
      setAiInsight("Hubo un error al conectar con el motor predictivo.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  // --- Búsqueda Semántica (P3.5) ---
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<any[]>([]);
  const [isSearching, setIsSearching] = useState(false);

  const handleSemanticSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery.trim()) return;

    setIsSearching(true);
    try {
      const response = await fetch(`${import.meta.env.VITE_API_BASE_URL}/analytics/ai-insights/search?q=${encodeURIComponent(searchQuery)}`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });
      const data = await response.json();
      if (data.status === 'success') {
        setSearchResults(data.data.results.animals || []);
      }
    } catch (err) {
      console.error('Error en búsqueda semántica:', err);
    } finally {
      setIsSearching(false);
    }
  };

  const activeAnimals = dashboardStats?.animales_activos?.valor || 0;
  const sickAnimals = dashboardStats?.animales_enfermos?.valor || 0;
  const healthScore = activeAnimals > 0 
    ? Math.floor(((activeAnimals - sickAnimals) / activeAnimals) * 100) 
    : 100;

  return (
    <div className="bg-gradient-to-br from-slate-900 to-slate-800 rounded-[2rem] p-8 text-white shadow-2xl relative overflow-hidden">
      {/* Efectos de fondo */}
      <div className="absolute top-0 right-0 w-64 h-64 bg-green-500/10 rounded-full blur-3xl -mr-20 -mt-20" />
      <div className="absolute bottom-0 left-0 w-48 h-48 bg-blue-500/10 rounded-full blur-3xl -ml-20 -mb-20" />

      <div className="relative z-10">
        <div className="flex items-center justify-between mb-10">
          <div className="flex items-center gap-4">
            <div className="p-3 bg-white/10 backdrop-blur-md rounded-2xl border border-white/10">
              <BrainCircuit className="text-green-400" size={28} />
            </div>
            <div>
              <h3 className="text-2xl font-black tracking-tight">Asistente Villa Luz</h3>
              <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Ayuda para tus decisiones</p>
            </div>
          </div>
          <div className="flex items-center gap-2 px-4 py-2 bg-green-500/20 text-green-400 rounded-full text-xs font-black border border-green-500/30">
            <Zap size={14} className="animate-pulse" />
            ACTIVO AHORA
          </div>
        </div>

        {/* Búsqueda Semántica Unificada */}
        <div className="mb-10">
          <form onSubmit={handleSemanticSearch} className="relative group">
            <div className="absolute inset-y-0 left-5 flex items-center pointer-events-none">
              <Search className={`h-5 w-5 transition-colors ${isSearching ? 'text-green-400 animate-pulse' : 'text-slate-500 group-focus-within:text-green-400'}`} />
            </div>
            <input 
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              aria-label="Buscar en el hato mediante inteligencia artificial"
              placeholder="Pregunta a la IA: '¿Qué vacas necesitan desparasitación?' o 'Busca toros enfermos'"
              className="w-full bg-white/5 border border-white/10 rounded-[1.5rem] py-5 pl-14 pr-6 text-sm focus:outline-none focus:ring-2 focus:ring-green-500/50 focus:bg-white/10 transition-all placeholder:text-slate-600"
            />
            <button 
              type="submit"
              className="absolute right-3 top-1/2 -translate-y-1/2 bg-green-600 hover:bg-green-500 text-white px-5 py-2 rounded-xl text-xs font-black uppercase tracking-tighter transition-all"
            >
              {isSearching ? 'Buscando...' : 'Preguntar'}
            </button>
          </form>

          {/* Resultados de Búsqueda Semántica */}
          <AnimatePresence>
            {searchResults.length > 0 && (
              <motion.div 
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                aria-live="polite"
                className="mt-4 grid grid-cols-1 sm:grid-cols-2 gap-3"
              >
                {searchResults.map((animal) => (
                  <div 
                    key={animal.id}
                    className="flex items-center justify-between p-4 bg-white/5 border border-white/5 rounded-2xl hover:bg-white/10 transition-colors cursor-pointer"
                    onClick={() => window.location.href = animal.url}
                  >
                    <div className="flex items-center gap-3">
                      <div className="h-8 w-8 bg-green-500/20 rounded-lg flex items-center justify-center text-[10px] font-black text-green-400">
                        {animal.internal_id}
                      </div>
                      <div>
                        <p className="text-xs font-bold text-white leading-none">{animal.name || 'Sin nombre'}</p>
                        <p className="text-[9px] text-slate-500 uppercase font-black mt-1">{animal.breed || animal.species}</p>
                      </div>
                    </div>
                    <div className="text-[10px] font-black text-green-500 bg-green-500/10 px-2 py-1 rounded-md">
                      {Math.round(animal.score * 100)}% Match
                    </div>
                  </div>
                ))}
                <button 
                  onClick={() => setSearchResults([])}
                  className="sm:col-span-2 text-[10px] font-black text-slate-500 hover:text-slate-300 transition-colors uppercase tracking-widest pt-2"
                >
                  Limpiar Resultados
                </button>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {/* Salud General */}
          <div className="bg-white/5 backdrop-blur-sm p-6 rounded-3xl border border-white/5">
            <div className="flex items-center justify-between mb-4">
              <Activity className="text-blue-400" size={20} />
              <span className="text-[10px] font-black text-slate-500 uppercase">Salud de los Animales</span>
            </div>
            <div className="text-4xl font-black mb-1">{healthScore}%</div>
            <div className="text-xs text-slate-400">Bienestar general de tus vacas</div>
            <div className="mt-4 h-1.5 bg-slate-700 rounded-full overflow-hidden">
              <motion.div 
                initial={{ width: 0 }}
                animate={{ width: `${healthScore}%` }}
                className="h-full bg-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.5)]"
              />
            </div>
          </div>

          {/* Red Mesh */}
          <div className="bg-white/5 backdrop-blur-sm p-6 rounded-3xl border border-white/5">
            <div className="flex items-center justify-between mb-4">
              <Network className="text-green-400" size={20} />
              <span className="text-[10px] font-black text-slate-500 uppercase">Paso de Información</span>
            </div>
            <div className="text-4xl font-black mb-1">{meshSyncs}</div>
            <div className="text-xs text-slate-400">Veces que se pasaron datos hoy</div>
            <div className="mt-4 flex gap-1">
              {[...Array(5)].map((_, i) => (
                <div 
                  key={i} 
                  className={`h-1 flex-1 rounded-full ${i < Math.min(meshSyncs, 5) ? 'bg-green-500 shadow-[0_0_5px_rgba(34,197,94,0.5)]' : 'bg-slate-700'}`} 
                />
              ))}
            </div>
          </div>

          {/* Potreros Registrados */}
          <div className="bg-white/5 backdrop-blur-sm p-6 rounded-3xl border border-white/5">
            <div className="flex items-center justify-between mb-4">
              <MapIcon className="text-amber-400" size={20} />
              <span className="text-[10px] font-black text-slate-500 uppercase">Gestión de Campos</span>
            </div>
            <div className="text-4xl font-black mb-1">
              {dashboardStats?.campos_registrados?.valor || 0}
            </div>
            <div className="text-xs text-slate-400">Potreros configurados en la finca</div>
            <div className="mt-4 flex items-center gap-2 text-[10px] font-bold text-green-400">
              <CircleCheck size={12} />
              DISPONIBLES PARA ROTACIÓN
            </div>
          </div>
        </div>

        {/* Sección de IA Predictive (F7) */}
        <div className="mt-8 p-6 bg-gradient-to-r from-blue-600/20 to-purple-600/20 rounded-[2.5rem] border border-blue-500/20 backdrop-blur-md">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3">
              <Cpu className="text-blue-400" size={24} />
              <h4 className="text-lg font-bold">Recomendaciones de la App</h4>
            </div>
            <button 
              onClick={handleRunAnalysis}
              disabled={isAnalyzing}
              className={`px-6 py-2 rounded-full text-xs font-black uppercase tracking-tighter transition-all ${
                isAnalyzing 
                ? 'bg-slate-700 text-slate-500 cursor-not-allowed' 
                : 'bg-white text-slate-900 hover:scale-105 active:scale-95 shadow-[0_0_20px_rgba(255,255,255,0.2)]'
              }`}
            >
              {isAnalyzing ? 'Pensando...' : 'Pedir Consejo'}
            </button>
          </div>
          
          <div className="bg-slate-950/40 p-5 rounded-2xl border border-white/5 min-h-[80px] flex items-center justify-center text-center">
            {aiInsight ? (
              <p className="text-sm text-slate-200 leading-relaxed italic">
                "{aiInsight}"
              </p>
            ) : (
              <p className="text-xs text-slate-500 font-medium">
                Inicia un escaneo para obtener recomendaciones predictivas basadas en datos reales.
              </p>
            )}
          </div>
        </div>

        <div className="mt-8 flex items-center justify-between p-4 bg-white/5 rounded-2xl border border-white/5">
          <div className="flex items-center gap-3">
            <Cpu className="text-slate-400" size={18} />
            <p className="text-[10px] font-bold text-slate-300">
              Última vez que se actualizó: <span className="text-white">{new Date().toLocaleTimeString()}</span>
            </p>
          </div>
          <button className="text-[10px] font-black text-blue-400 hover:text-blue-300 transition-colors uppercase tracking-widest">
            Ver Reporte Detallado
          </button>
        </div>
      </div>
    </div>
  );
};

const CircleCheck = ({ size }: { size: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
    <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14" />
    <polyline points="22 4 12 14.01 9 11.01" />
  </svg>
);

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/shared/ui/card';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/shared/ui/tabs';
import StatisticsCard from './StatisticsCard';
import { useAnimals } from '@/entities/animal/model/useAnimals';
import { useUsers } from '@/entities/user/model/useUser';
import { useFields } from '@/entities/field/model/useField';
import { useControls } from '@/entities/control/model/useControl';
import { useTreatment } from '@/entities/treatment/model/useTreatment';
import { useVaccinations } from '@/entities/vaccination/model/useVaccination';
import { 
  Users, 
  Heart, 
  MapPin, 
  Activity, 
  Syringe, 
  PillBottle,
  TrendingUp,
  AlertTriangle,
  CircleCheck
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';

interface AnimalStats {
  total: number;
  alive: number;
  sold: number;
  dead: number;
  bySpecies: { [key: string]: number };
  byStatus: { name: string; value: number; color: string }[];
}

interface FieldStats {
  total: number;
  available: number;
  occupied: number;
  maintenance: number;
  capacity: number;
}

interface HealthStats {
  totalControls: number;
  recentControls: number;
  treatments: number;
  vaccinations: number;
  healthDistribution: { name: string; value: number; color: string }[];
}

const FarmStatistics: React.FC = () => {
  const { animals, loading: animalsLoading } = useAnimals();
  const { data: users, loading: usersLoading } = useUsers();
  const { fields, loading: fieldsLoading } = useFields();
  const { controls, loading: controlsLoading } = useControls();
  const { treatments, loading: treatmentsLoading } = useTreatment();
  const { vaccinations, loading: vaccinationsLoading } = useVaccinations();

  const [animalStats, setAnimalStats] = useState<AnimalStats>({
    total: 0,
    alive: 0,
    sold: 0,
    dead: 0,
    bySpecies: {},
    byStatus: []
  });

  const [fieldStats, setFieldStats] = useState<FieldStats>({
    total: 0,
    available: 0,
    occupied: 0,
    maintenance: 0,
    capacity: 0
  });

  const [healthStats, setHealthStats] = useState<HealthStats>({
    totalControls: 0,
    recentControls: 0,
    treatments: 0,
    vaccinations: 0,
    healthDistribution: []
  });

  // Calcular estadísticas de animales
  useEffect(() => {
    if (animals && animals.length > 0) {
      const alive = animals.filter(a => a.status === 'Sano' || a.status === 'Enfermo' || a.status === 'En tratamiento' || a.status === 'En observación' || a.status === 'Cuarentena').length;
      const sold = animals.filter(a => a.status === 'Vendido').length;
      const dead = animals.filter(a => a.status === 'Fallecido').length;

      const byStatus = [
        { name: 'Vivos', value: alive, color: '#22c55e' },
        { name: 'Vendidos', value: sold, color: '#3b82f6' },
        { name: 'Fallecidos', value: dead, color: '#ef4444' }
      ];

      setAnimalStats({
        total: animals.length,
        alive,
        sold,
        dead,
        bySpecies: {},
        byStatus
      });
    }
  }, [animals]);

  // Calcular estadísticas de Potreros
  useEffect(() => {
    if (fields && fields.length > 0) {
      const available = fields.filter(f => f.state === 'Disponible').length;
      const occupied = fields.filter(f => f.state === 'Ocupado').length;
      const maintenance = fields.filter(f => f.state === 'Mantenimiento').length;
      const totalCapacity = fields.reduce((sum, field) => {
        const capacity = parseInt(field.capacity.split(' ')[0]) || 0;
        return sum + capacity;
      }, 0);

      setFieldStats({
        total: fields.length,
        available,
        occupied,
        maintenance,
        capacity: totalCapacity
      });
    }
  }, [fields]);

  // Calcular estadísticas de salud
  useEffect(() => {
    if (controls && treatments && vaccinations) {
      const now = new Date();
      const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
      
      const recentControls = controls.filter(c => {
  const controlDate = c.checkup_date ? new Date(c.checkup_date) : null;
  return controlDate ? (controlDate >= thirtyDaysAgo) : false;
      }).length;

      // Distribución de estados de salud
      const healthCounts = controls.reduce((acc, control) => {
        // Verificar que healt_status existe antes de usarlo como índice
        if (control.healt_status) {
          acc[control.healt_status] = (acc[control.healt_status] || 0) + 1;
        }
        return acc;
      }, {} as { [key: string]: number });

      const healthDistribution = Object.entries(healthCounts).map(([status, count]) => ({
        name: status,
        value: count,
        color: status === 'Excelente' ? '#22c55e' : 
               status === 'Bueno' ? '#3b82f6' :
               status === 'Regular' ? '#f59e0b' : '#ef4444'
      }));

      setHealthStats({
        totalControls: controls.length,
        recentControls,
        treatments: treatments.length,
        vaccinations: vaccinations.length,
        healthDistribution
      });
    }
  }, [controls, treatments, vaccinations]);

  const isLoading = animalsLoading || usersLoading || fieldsLoading || controlsLoading || treatmentsLoading || vaccinationsLoading;

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
        <StatisticsCard
          title="Total Animales"
          value={animalStats.total}
          description="Animales registrados"
          icon={<Heart />}
          variant="default"
        />
        
        <StatisticsCard
          title="Animales Vivos"
          value={animalStats.alive}
          description={`${((animalStats.alive / animalStats.total) * 100).toFixed(1)}% del total`}
          icon={<CircleCheck />}
          variant="success"
        />
        
        <StatisticsCard
          title="Potreros Totales"
          value={fieldStats.total}
          description={`Capacidad: ${fieldStats.capacity} animales`}
          progress={{
            value: fieldStats.occupied,
            max: fieldStats.total,
            label: "Potreros ocupados"
          }}
          icon={<MapPin />}
        />
        
        <StatisticsCard
          title="Controles Recientes"
          value={healthStats.recentControls}
          description="Últimos 30 días"
          icon={<Activity />}
          variant={healthStats.recentControls > 0 ? 'success' : 'warning'}
        />
      </div>

      <Tabs defaultValue="animals" className="space-y-4">
        <TabsList>
          <TabsTrigger value="animals">Animales</TabsTrigger>
          <TabsTrigger value="fields">Potreros</TabsTrigger>
          <TabsTrigger value="health">Salud</TabsTrigger>
          <TabsTrigger value="users">Usuarios</TabsTrigger>
        </TabsList>

        <TabsContent value="animals" className="space-y-4">
          <div className="grid gap-4 md:grid-cols-2">
            <Card>
              <CardHeader>
                <CardTitle>Distribución por Estado</CardTitle>
              </CardHeader>
              <CardContent>
                <ResponsiveContainer width="100%" height={300}>
                  <PieChart>
                    <Pie
                      data={animalStats.byStatus}
                      cx="50%"
                      cy="50%"
                      labelLine={false}
                      label={({ name, percent }: import('@/shared/types/rechartsLabel.types').RechartsLabelProps) => `${name} ${percent ? (percent * 100).toFixed(0) : 0}%`}
                      outerRadius={80}
                      fill="#8884d8"
                      dataKey="value"
                    >
                      {animalStats.byStatus.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} />
                      ))}
                    </Pie>
                    <Tooltip />
                  </PieChart>
                </ResponsiveContainer>
              </CardContent>
            </Card>

            <div className="space-y-4">
              <StatisticsCard
                title="Animales Vendidos"
                value={animalStats.sold}
                description="Total de ventas"
                icon={<TrendingUp />}
                variant="default"
              />
              
              <StatisticsCard
                title="Mortalidad"
                value={animalStats.dead}
                description={`${((animalStats.dead / animalStats.total) * 100).toFixed(1)}% del total`}
                icon={<AlertTriangle />}
                variant={animalStats.dead > 0 ? 'destructive' : 'success'}
              />
            </div>
          </div>
        </TabsContent>

        <TabsContent value="fields" className="space-y-4">
          <div className="grid gap-4 md:grid-cols-3">
            <StatisticsCard
              title="Potreros Disponibles"
              value={fieldStats.available}
              description="Listos para uso"
              icon={<CircleCheck />}
              variant="success"
            />
            
            <StatisticsCard
              title="Potreros Ocupados"
              value={fieldStats.occupied}
              description="En uso actualmente"
              icon={<Users />}
              variant="default"
            />
            
            <StatisticsCard
              title="En Mantenimiento"
              value={fieldStats.maintenance}
              description="Requieren atención"
              icon={<AlertTriangle />}
              variant="warning"
            />
          </div>
        </TabsContent>

        <TabsContent value="health" className="space-y-4">
          <div className="grid gap-4 md:grid-cols-2">
            <Card>
              <CardHeader>
                <CardTitle>Estado de Salud General</CardTitle>
              </CardHeader>
              <CardContent>
                <ResponsiveContainer width="100%" height={300}>
                  <BarChart data={healthStats.healthDistribution}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="name" />
                    <YAxis />
                    <Tooltip />
                    <Bar dataKey="value" fill="#8884d8" />
                  </BarChart>
                </ResponsiveContainer>
              </CardContent>
            </Card>

            <div className="space-y-4">
              <StatisticsCard
                title="Tratamientos Activos"
                value={healthStats.treatments}
                description="En curso"
                icon={<PillBottle />}
                variant="default"
              />
              
              <StatisticsCard
                title="Vacunaciones"
                value={healthStats.vaccinations}
                description="Aplicadas"
                icon={<Syringe />}
                variant="success"
              />
            </div>
          </div>
        </TabsContent>

        <TabsContent value="users" className="space-y-4">
          <div className="grid gap-4 md:grid-cols-3">
            <StatisticsCard
              title="Total Usuarios"
              value={users?.length || 0}
              description="Registrados en el sistema"
              icon={<Users />}
              variant="default"
            />
            
            <StatisticsCard
              title="Usuarios Activos"
              value={users?.filter((u: any) => (typeof u.status === 'boolean' ? u.status === true : String(u.status) === '1' || String(u.status).toLowerCase() === 'true' || String(u.status).toLowerCase() === 'activo')).length || 0}
              description="Con acceso al sistema"
              icon={<CircleCheck />}
              variant="success"
            />
            
            <StatisticsCard
              title="Usuarios Inactivos"
              value={users?.filter((u: any) => (typeof u.status === 'boolean' ? u.status === false : String(u.status) === '0' || String(u.status).toLowerCase() === 'false' || String(u.status).toLowerCase() === 'inactivo')).length || 0}
              description="Sin acceso al sistema"
              icon={<AlertTriangle />}
              variant="warning"
            />
          </div>
        </TabsContent>
      </Tabs>
    </div>
  );
};

export default FarmStatistics;

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Package, Plus, Minus, Check, AlertTriangle } from 'lucide-react';
import { inventoryService } from '@/entities/inventory/api/inventory.service';
import { useInventory } from '@/app/providers/InventoryContext';
import { InventoryLotResponse } from '@/shared/api/generated/swaggerTypes';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';

export const FastInventoryAction: React.FC = () => {
  const { recordMovement, getProjectedQuantity } = useInventory();
  const [lots, setLots] = useState<InventoryLotResponse[]>([]);
  const [selectedLot, setSelectedLot] = useState<InventoryLotResponse | null>(null);
  const [quantity, setQuantity] = useState(1);
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    const fetchLots = async () => {
      try {
        const data = await inventoryService.getLots({ limit: 10 });
        setLots(data);
      } catch (error) {
        console.error('Error al cargar lotes:', error);
      }
    };
    fetchLots();
  }, []);

  const handleConfirm = async () => {
    if (!selectedLot) return;
    setLoading(true);
    
    try {
      // 1. Registrar localmente para actualización instantánea de UI
      recordMovement(selectedLot.id, quantity, 'Salida');

      // 2. Enviar al backend (se encola si está offline)
      await inventoryService.createMovement({
        lot_id: selectedLot.id,
        quantity: quantity,
        type: 'Salida' as any,
        notes: 'Registro rápido desde campo (PWA Offline)'
      });

      setSuccess(true);
      setTimeout(() => {
        setSuccess(false);
        setSelectedLot(null);
        setQuantity(1);
      }, 2000);
    } catch (error) {
      console.error('Error en el movimiento:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-3xl p-6 border border-gray-100 shadow-sm">
      <div className="flex items-center gap-3 mb-6">
        <div className="p-2 bg-amber-100 text-amber-600 rounded-xl">
          <Package size={20} />
        </div>
        <h3 className="text-lg font-bold text-gray-900">Uso Rápido de Insumos</h3>
      </div>

      <div className="space-y-4">
        {/* Selector de Lotes */}
        <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
          {lots.map(lot => {
            const projected = getProjectedQuantity(lot);
            const isSelected = selectedLot?.id === lot.id;
            return (
              <button
                key={lot.id}
                onClick={() => setSelectedLot(lot)}
                className={`p-3 rounded-2xl border text-left transition-all ${
                  isSelected 
                    ? 'border-amber-500 bg-amber-50 ring-2 ring-amber-200' 
                    : 'border-gray-100 hover:border-amber-200 bg-gray-50'
                }`}
              >
                <p className="text-[10px] font-bold uppercase text-gray-400 truncate">{lot.medication?.name || lot.vaccine?.name || 'Insumo'}</p>
                <p className="text-sm font-black text-gray-900 truncate">Lote: {lot.lot_number}</p>
                <p className={`text-xs font-bold mt-1 ${projected < 10 ? 'text-red-500' : 'text-green-600'}`}>
                  Stock: {projected} {lot.presentation || 'und'}
                </p>
              </button>
            );
          })}
        </div>

        <AnimatePresence>
          {selectedLot && (
            <motion.div 
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              exit={{ opacity: 0, height: 0 }}
              className="pt-4 border-t border-dashed border-gray-200 space-y-4"
            >
              <div className="flex items-center justify-between bg-gray-50 p-4 rounded-2xl">
                <div className="flex items-center gap-4">
                  <button 
                    onClick={() => setQuantity(Math.max(1, quantity - 1))}
                    className="p-2 bg-white rounded-lg border border-gray-200 hover:bg-gray-100"
                  >
                    <Minus size={16} />
                  </button>
                  <div className="text-center w-12">
                    <span className="text-xl font-black">{quantity}</span>
                  </div>
                  <button 
                    onClick={() => setQuantity(quantity + 1)}
                    className="p-2 bg-white rounded-lg border border-gray-200 hover:bg-gray-100"
                  >
                    <Plus size={16} />
                  </button>
                </div>
                
                <Button 
                  onClick={handleConfirm}
                  disabled={loading || success}
                  className={`rounded-2xl px-8 ${success ? 'bg-green-600 hover:bg-green-700' : 'bg-amber-600 hover:bg-amber-700'}`}
                >
                  {loading ? 'Procesando...' : success ? <Check /> : 'Confirmar Uso'}
                </Button>
              </div>

              {getProjectedQuantity(selectedLot) < quantity && (
                <div className="flex items-center gap-2 text-xs text-red-600 font-bold bg-red-50 p-2 rounded-lg">
                  <AlertTriangle size={14} />
                  Stock insuficiente proyectado.
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Scale, Search, Check, CircleAlert, TrendingUp } from 'lucide-react';
import { controlService } from '@/entities/control/api/control.service';
import { animalService } from '@/entities/animal/api/animal.service';
import { HealthAnalyzer, HealthInsight } from '@/entities/animal/api/HealthAnalyzer';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';

export const FastWeightEntry: React.FC = () => {
  const [search, setSearch] = useState('');
  const [animals, setAnimals] = useState<any[]>([]);
  const [selectedAnimal, setSelectedAnimal] = useState<any | null>(null);
  const [weight, setWeight] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [insight, setInsight] = useState<HealthInsight | null>(null);

  // Cargar insight cuando se selecciona un animal
  useEffect(() => {
    if (!selectedAnimal) {
      setInsight(null);
      return;
    }

    const loadInsight = async () => {
      try {
        const res = await controlService.getControls({ animal_id: selectedAnimal.id, limit: 5 });
        const analysis = HealthAnalyzer.analyze(selectedAnimal, res.items || []);
        setInsight(analysis);
      } catch (err) {
        console.warn('No se pudo cargar el historial para IA local');
      }
    };
    loadInsight();
  }, [selectedAnimal]);
  useEffect(() => {
    const fetchAnimals = async () => {
      try {
        const res = await animalService.getAnimals({ limit: 5 });
        setAnimals(res.items || []);
      } catch (err) {
        console.error('Error al cargar animales:', err);
      }
    };
    fetchAnimals();
  }, []);

  const handleSave = async () => {
    if (!selectedAnimal || !weight) return;
    setLoading(true);

    try {
      await controlService.createControl({
        animal_id: selectedAnimal.id,
        checkup_date: new Date().toISOString().split('T')[0],
        health_status: 'Bueno' as any,
        weight: parseInt(weight),
        description: 'Pesaje rápido en campo'
      });

      setSuccess(true);
      setTimeout(() => {
        setSuccess(false);
        setSelectedAnimal(null);
        setWeight('');
        setSearch('');
      }, 2000);
    } catch (error) {
      console.error('Error al guardar pesaje:', error);
    } finally {
      setLoading(false);
    }
  };

  const filteredAnimals = animals.filter(a => 
    a.record?.toLowerCase().includes(search.toLowerCase()) ||
    a.name?.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="bg-white rounded-3xl p-6 border border-gray-100 shadow-sm">
      <div className="flex items-center gap-3 mb-6">
        <div className="p-2 bg-blue-100 text-blue-600 rounded-xl">
          <Scale size={20} />
        </div>
        <h3 className="text-lg font-bold text-gray-900">Pesaje Rápido</h3>
      </div>

      <div className="space-y-4">
        {!selectedAnimal ? (
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
            <Input 
              placeholder="Buscar por placa o nombre..." 
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-9 rounded-2xl border-gray-100"
            />
            {search && (
              <div className="absolute z-10 w-full mt-2 bg-white border border-gray-100 rounded-2xl shadow-xl overflow-hidden">
                {filteredAnimals.map(animal => (
                  <button
                    key={animal.id}
                    onClick={() => setSelectedAnimal(animal)}
                    className="w-full p-4 text-left hover:bg-blue-50 transition-colors flex items-center justify-between border-b border-gray-50 last:border-0"
                  >
                    <div>
                      <p className="font-bold text-gray-900">#{animal.record}</p>
                      <p className="text-xs text-gray-500">{animal.breed?.name || 'Sin raza'}</p>
                    </div>
                    <div className="text-right">
                      <p className="text-xs font-bold text-blue-600">{animal.weight || '?'} kg</p>
                      <p className="text-[10px] text-gray-400">Último peso</p>
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>
        ) : (
          <motion.div 
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className="space-y-4"
          >
            <div className="flex items-center justify-between p-4 bg-blue-50 rounded-2xl border border-blue-100">
              <div className="flex items-center gap-3">
                <div className="h-10 w-10 bg-white rounded-xl flex items-center justify-center text-blue-600 font-bold shadow-sm">
                  {selectedAnimal.record.slice(-2)}
                </div>
                <div>
                  <p className="text-sm font-black text-gray-900">Animal #{selectedAnimal.record}</p>
                  <p className="text-xs text-gray-600">Actual: {selectedAnimal.weight || 0} kg</p>
                </div>
              </div>
              <button onClick={() => setSelectedAnimal(null)} className="text-xs text-blue-600 font-bold hover:underline">
                Cambiar
              </button>
            </div>

            {/* Local Health Insight (IA en el Borde) */}
            <AnimatePresence>
              {insight && (
                <motion.div 
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: 'auto' }}
                  className={`p-3 rounded-2xl flex items-start gap-3 border ${
                    insight.status === 'critical' ? 'bg-red-50 border-red-100 text-red-700' :
                    insight.status === 'warning' ? 'bg-amber-50 border-amber-100 text-amber-700' :
                    'bg-green-50 border-green-100 text-green-700'
                  }`}
                >
                  <CircleAlert size={16} className="mt-0.5 shrink-0" />
                  <div>
                    <p className="text-[10px] font-black uppercase tracking-wider mb-1 flex items-center gap-2">
                      Diagnóstico Local IA 
                      <span className="opacity-40">•</span> 
                      Score: {insight.score}/100
                    </p>
                    <p className="text-xs font-bold leading-tight">{insight.message}</p>
                  </div>
                </motion.div>
              )}
            </AnimatePresence>

            <div className="flex gap-4">
              <div className="flex-1 relative">
                <Input 
                  type="number"
                  placeholder="Nuevo peso (kg)"
                  value={weight}
                  onChange={(e) => setWeight(e.target.value)}
                  className="text-xl font-black h-14 rounded-2xl border-gray-200 focus:ring-blue-500"
                />
                <div className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 font-bold">kg</div>
              </div>
              <Button 
                onClick={handleSave}
                disabled={loading || !weight || success}
                className={`h-14 rounded-2xl px-8 transition-all ${success ? 'bg-green-600' : 'bg-blue-600 hover:bg-blue-700'}`}
              >
                {loading ? 'Cargando...' : success ? <Check /> : <TrendingUp />}
              </Button>
            </div>
            
            {weight && selectedAnimal.weight && (
              <p className={`text-xs font-bold text-center ${parseInt(weight) >= selectedAnimal.weight ? 'text-green-600' : 'text-red-500'}`}>
                {parseInt(weight) >= selectedAnimal.weight ? '+' : ''}
                {parseInt(weight) - selectedAnimal.weight} kg respecto al anterior
              </p>
            )}
          </motion.div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { MoreVertical, Beef, Plus, Eye } from 'lucide-react';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
  DropdownMenuSub,
  DropdownMenuSubTrigger,
  DropdownMenuSubContent,
} from '@/shared/ui/dropdown-menu';
import { GenericModal } from '@/shared/ui/common/GenericModal';
import { FieldResponse } from '@/shared/api/generated/swaggerTypes';
import { getTodayColombia } from '@/shared/utils/dateUtils';
import { Button } from '@/shared/ui/button';
import { FieldAnimalsModal } from '@/widgets/dashboard/fields/FieldAnimalsModal';

// Importar servicios
import { animalFieldsService } from '@/entities/animal-field/api/animalFields.service';
import { animalsService } from '@/entities/animal/api/animal.service';
import { fieldService } from '@/entities/field/api/field.service';

interface FieldActionsMenuProps {
  field: FieldResponse;
}

type ModalType = 'animals' | 'view_animals' | null;
type ModalMode = 'create' | 'list';

export const FieldActionsMenu: React.FC<FieldActionsMenuProps> = ({ field }) => {
  const [openModal, setOpenModal] = useState<ModalType>(null);
  const [modalMode, setModalMode] = useState<ModalMode>('create');
  const [formData, setFormData] = useState<any>({});
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Estados para acciones de animales
  const [selectedAnimalField, setSelectedAnimalField] = useState<any>(null);
  const [showRemoveConfirm, setShowRemoveConfirm] = useState(false);
  const [showMoveModal, setShowMoveModal] = useState(false);
  const [targetFieldId, setTargetFieldId] = useState<number | undefined>(undefined);

  // Opciones para los selects
  const [animalOptions, setAnimalOptions] = useState<Array<{ value: number; label: string }>>([]);
  const [fieldOptions, setFieldOptions] = useState<Array<{ value: number; label: string }>>([]);

  // Cargar opciones
  const loadOptions = useCallback(async () => {
    try {
      const animals = await animalsService.getAnimals({ page: 1, limit: 1000 }).catch(() => []);
      const animalsData = animals || [];
      setAnimalOptions(animalsData.map((a: any) => ({
        value: a.id,
        label: a.record || `Animal ${a.id}`
      })));

      // Cargar potreros para la funcionalidad de mover
      const fields = await fieldService.getFields({ page: 1, limit: 1000 }).catch(() => ({ data: [] }));
      const fieldsData = Array.isArray(fields) ? fields : (fields?.data || []);
      setFieldOptions(fieldsData
        .filter((f: any) => f.id !== field.id) // Excluir el potrero actual
        .map((f: any) => ({
          value: f.id,
          label: f.name || `Potrero ${f.id}`
        }))
      );
    } catch (err) {
      console.error('Error loading options:', err);
    }
  }, [field.id]);

  // Cargar opciones cuando se abre un modal de creación
  useEffect(() => {
    if (openModal === 'animals' && modalMode === 'create') {
      loadOptions();
    }
  }, [openModal, modalMode, loadOptions]);

  const handleOpenModal = (type: ModalType, mode: ModalMode) => {
    setOpenModal(type);
    setModalMode(mode);
    setError(null);

    if (mode === 'create') {
      setFormData({
        animal_id: undefined,
        field_id: field.id,
        assignment_date: getTodayColombia(),
        removal_date: undefined,
        notes: '',
      });
    }
  };

  const handleCloseModal = () => {
    setOpenModal(null);
    setFormData({});
    setError(null);
  };

  const handleSubmit = async () => {
    setLoading(true);
    setError(null);

    try {
      if (!formData.animal_id || !formData.field_id) {
        throw new Error('Animal y campo son obligatorios');
      }
      await animalFieldsService.createAnimalField(formData);
      handleCloseModal();
    } catch (err: any) {
      setError(err?.response?.data?.message || err.message || 'Error al guardar');
    } finally {
      setLoading(false);
    }
  };

  const handleRemoveAnimal = async () => {
    if (!selectedAnimalField) return;

    setLoading(true);
    try {
      // Actualizar el registro con la fecha de retiro
      await animalFieldsService.updateAnimalField(selectedAnimalField.id, {
        ...selectedAnimalField,
        removal_date: getTodayColombia()
      });

      alert('Animal retirado del potrero exitosamente');
      setShowRemoveConfirm(false);
      setSelectedAnimalField(null);
    } catch (err: any) {
      alert(err?.response?.data?.message || err.message || 'Error al retirar el animal');
    } finally {
      setLoading(false);
    }
  };

  const handleMoveAnimal = async () => {
    if (!selectedAnimalField || !targetFieldId) {
      alert('Debe seleccionar un potrero de destino');
      return;
    }

    setLoading(true);
    try {
      // 1. Marcar como retirado del potrero actual
      await animalFieldsService.updateAnimalField(selectedAnimalField.id, {
        ...selectedAnimalField,
        removal_date: getTodayColombia()
      });

      // 2. Crear nuevo registro en el potrero destino
      await animalFieldsService.createAnimalField({
        animal_id: selectedAnimalField.animal_id,
        field_id: targetFieldId,
        assignment_date: getTodayColombia(),
        notes: `Movido desde ${field.name || `Potrero ${field.id}`}`
      });

      alert('Animal movido exitosamente');
      setShowMoveModal(false);
      setSelectedAnimalField(null);
      setTargetFieldId(undefined);
    } catch (err: any) {
      alert(err?.response?.data?.message || err.message || 'Error al mover el animal');
    } finally {
      setLoading(false);
    }
  };

  const renderFormContent = () => {
    const inputClass = "w-full px-3 py-2 text-sm rounded-md border border-input bg-background ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 transition-colors";
    const labelClass = "block text-sm font-medium mb-1.5 text-foreground";
    const selectClass = "w-full px-3 py-2 text-sm rounded-md border border-input bg-background ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 transition-colors";

    return (
      <div className="space-y-4">
        <div>
          <label className={labelClass}>Potrero</label>
          <input
            type="text"
            value={field.name || `ID ${field.id}`}
            disabled
            className={`${inputClass} bg-muted/50`}
          />
        </div>
        <div>
          <label className={labelClass}>Animal *</label>
          <select
            value={formData.animal_id || ''}
            onChange={(e) => setFormData({ ...formData, animal_id: parseInt(e.target.value) })}
            className={selectClass}
          >
            <option value="">Seleccionar animal</option>
            {animalOptions.map((opt) => (
              <option key={opt.value} value={opt.value}>{opt.label}</option>
            ))}
          </select>
        </div>
        <div>
          <label className={labelClass}>Fecha de Asignación *</label>
          <input
            type="date"
            value={formData.assignment_date || ''}
            onChange={(e) => setFormData({ ...formData, assignment_date: e.target.value })}
            className={inputClass}
          />
        </div>
        <div>
          <label className={labelClass}>Fecha de Retiro</label>
          <input
            type="date"
            value={formData.removal_date || ''}
            onChange={(e) => setFormData({ ...formData, removal_date: e.target.value })}
            className={inputClass}
          />
        </div>
        <div>
          <label className={labelClass}>Notas</label>
          <textarea
            value={formData.notes || ''}
            onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
            placeholder="Observaciones adicionales"
            rows={3}
            className={inputClass}
          />
        </div>
      </div>
    );
  };

  const getModalTitle = () => {
    return 'Asignar Animal al Potrero';
  };

  return (
    <>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <button
            className="icon-btn p-1.5 hover:bg-accent rounded-md transition-colors"
            onClick={(e) => e.stopPropagation()}
            title="Más acciones"
            aria-label="Más acciones"
          >
            <MoreVertical className="h-4 w-4" />
          </button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end" className="w-56">
          <DropdownMenuSub>
            <DropdownMenuSubTrigger>
              <Beef className="mr-2 h-4 w-4" />
              Animales
            </DropdownMenuSubTrigger>
            <DropdownMenuSubContent>
              <DropdownMenuItem
                onClick={(e) => {
                  e.stopPropagation();
                  handleOpenModal('animals', 'create');
                }}
                className="cursor-pointer"
              >
                <Plus className="mr-2 h-4 w-4" />
                Asignar Animal
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={(e) => {
                  e.stopPropagation();
                  setOpenModal('view_animals');
                }}
                className="cursor-pointer"
              >
                <Eye className="mr-2 h-4 w-4" />
                Ver Animales
              </DropdownMenuItem>
            </DropdownMenuSubContent>
          </DropdownMenuSub>
        </DropdownMenuContent>
      </DropdownMenu>

      <GenericModal
        isOpen={openModal === 'animals'}
        onOpenChange={(open) => !open && handleCloseModal()}
        title={getModalTitle()}
        size="2xl"
        enableBackdropBlur
        className="bg-card/95 backdrop-blur-md text-card-foreground border-border/50"
      >
        <div className="space-y-4">
          {renderFormContent()}
          {error && (
            <div className="p-3 bg-destructive/10 border border-destructive/30 rounded-md text-sm text-destructive">
              {error}
            </div>
          )}

          <div className="flex justify-end gap-2 pt-4 border-t border-border">
            <button
              onClick={handleCloseModal}
              className="px-4 py-2 text-sm rounded-md border border-input bg-background hover:bg-accent hover:text-accent-foreground transition-colors"
              disabled={loading}
            >
              Cancelar
            </button>
            <button
              onClick={handleSubmit}
              className="px-4 py-2 text-sm rounded-md bg-primary text-primary-foreground hover:bg-primary/90 transition-colors shadow-sm"
              disabled={loading}
            >
              {loading ? 'Guardando...' : 'Guardar'}
            </button>
          </div>
        </div>
      </GenericModal>

      {/* Modal para ver animales */}
      <FieldAnimalsModal
        field={field}
        isOpen={openModal === 'view_animals'}
        onClose={() => setOpenModal(null)}
      />

      {/* Modal de confirmación para retirar animal */}
      <GenericModal
        isOpen={showRemoveConfirm}
        onOpenChange={setShowRemoveConfirm}
        title="Retirar Animal del Potrero"
        description="¿Está seguro que desea retirar este animal del potrero?"
        size="md"
        enableBackdropBlur
        className="bg-card/95 backdrop-blur-md text-card-foreground border-border/50"
      >
        <div className="space-y-4">
          <div className="p-4 bg-muted/50 rounded-lg border border-border">
            <p className="text-sm text-muted-foreground">
              Esta acción marcará el animal como retirado del potrero con la fecha de hoy.
              El animal ya no contará en la ocupación del potrero.
            </p>
          </div>

          <div className="flex justify-end gap-2 pt-4 border-t border-border">
            <Button
              variant="outline"
              onClick={() => {
                setShowRemoveConfirm(false);
                setSelectedAnimalField(null);
              }}
              disabled={loading}
            >
              Cancelar
            </Button>
            <Button
              variant="destructive"
              onClick={handleRemoveAnimal}
              disabled={loading}
            >
              {loading ? 'Retirando...' : 'Retirar Animal'}
            </Button>
          </div>
        </div>
      </GenericModal>

      {/* Modal para mover animal a otro potrero */}
      <GenericModal
        isOpen={showMoveModal}
        onOpenChange={setShowMoveModal}
        title="Mover Animal a Otro Potrero"
        description="Seleccione el potrero de destino"
        size="md"
        enableBackdropBlur
        className="bg-card/95 backdrop-blur-md text-card-foreground border-border/50"
      >
        <div className="space-y-4">
          <div className="space-y-2">
            <label className="block text-sm font-medium text-foreground">
              Potrero de Destino *
            </label>
            <select
              value={targetFieldId || ''}
              onChange={(e) => setTargetFieldId(parseInt(e.target.value))}
              className="w-full px-3 py-2 text-sm rounded-md border border-input bg-background ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
            >
              <option value="">Seleccionar potrero</option>
              {fieldOptions.map((opt) => (
                <option key={opt.value} value={opt.value}>{opt.label}</option>
              ))}
            </select>
          </div>

          <div className="p-4 bg-muted/50 rounded-lg border border-border">
            <p className="text-sm text-muted-foreground">
              Esta acción retirará el animal del potrero actual y lo asignará automáticamente
              al potrero seleccionado con la fecha de hoy.
            </p>
          </div>

          <div className="flex justify-end gap-2 pt-4 border-t border-border">
            <Button
              variant="outline"
              onClick={() => {
                setShowMoveModal(false);
                setSelectedAnimalField(null);
                setTargetFieldId(undefined);
              }}
              disabled={loading}
            >
              Cancelar
            </Button>
            <Button
              onClick={handleMoveAnimal}
              disabled={loading || !targetFieldId}
            >
              {loading ? 'Moviendo...' : 'Mover Animal'}
            </Button>
          </div>
        </div>
      </GenericModal>
    </>
  );
};

import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Download, CircleCheck, WifiOff, RefreshCw, Trash2,
  Zap, Package, Clock, CloudOff, CloudDownload,
} from 'lucide-react';
import { useFieldReady } from '@/shared/hooks/useFieldReady';
import { useOnlineStatus } from '@/shared/hooks/useOnlineStatus';

// ─── Helpers ─────────────────────────────────────────────────────────────────

function formatTime(epoch: number | null): string {
  if (!epoch) return 'Nunca';
  const diff = Date.now() - epoch;
  const h = Math.floor(diff / 3_600_000);
  const m = Math.floor((diff % 3_600_000) / 60_000);
  if (h > 0) return `hace ${h}h ${m}m`;
  if (m > 0) return `hace ${m}m`;
  return 'Justo ahora';
}

// ─── Componente ──────────────────────────────────────────────────────────────

export const FieldReadyWidget: React.FC = () => {
  const { isOnline } = useOnlineStatus();
  const { status, progress, isPrefetching, startPrefetch, clearCache } = useFieldReady();

  const canDownload  = isOnline && !isPrefetching;
  const pct          = progress
    ? Math.round((progress.current / Math.max(progress.total, 1)) * 100)
    : 0;

  return (
    <div
      className="rounded-2xl border-2 overflow-hidden shadow-lg"
      style={{
        borderColor: status.isReady ? '#10b981' : isOnline ? '#3b82f6' : '#f59e0b',
        background: status.isReady
          ? 'linear-gradient(135deg,#ecfdf5,#d1fae5)'
          : isOnline
          ? 'linear-gradient(135deg,#eff6ff,#dbeafe)'
          : 'linear-gradient(135deg,#fffbeb,#fef3c7)',
      }}
    >
      {/* ── Header ── */}
      <div
        className="px-5 py-4 flex items-center justify-between"
        style={{ background: status.isReady ? '#059669' : isOnline ? '#2563eb' : '#d97706' }}
      >
        <div className="flex items-center gap-3 text-white">
          {status.isReady ? (
            <CircleCheck className="h-7 w-7" />
          ) : isOnline ? (
            <CloudDownload className="h-7 w-7" />
          ) : (
            <CloudOff className="h-7 w-7" />
          )}
          <div>
            <p className="font-bold text-lg leading-none">
              {status.isReady ? '¡Listo para el campo!' : 'Modo Campo'}
            </p>
            <p className="text-xs opacity-80 mt-0.5">
              {status.isReady
                ? 'Datos disponibles sin internet'
                : isOnline
                ? 'Descarga los datos antes de salir'
                : 'Sin WiFi — datos del campo necesarios'}
            </p>
          </div>
        </div>
        {status.isReady && (
          <span className="bg-white/20 text-white text-xs font-bold px-3 py-1 rounded-full">
            Actualizado {formatTime(status.cachedAt)}
          </span>
        )}
      </div>

      {/* ── Cuerpo ── */}
      <div className="px-5 py-4 space-y-4">

        {/* Estado KPIs */}
        <div className="grid grid-cols-3 gap-3">
          {[
            {
              icon: Package,
              label: 'Registros',
              value: status.itemsCached > 0 ? String(status.itemsCached) : '—',
              color: status.itemsCached > 0 ? 'text-emerald-700' : 'text-gray-400',
            },
            {
              icon: WifiOff,
              label: 'Pendientes',
              value: String(status.pendingSync),
              color: status.pendingSync > 0 ? 'text-amber-600' : 'text-gray-400',
            },
            {
              icon: Clock,
              label: 'Vigencia',
              value: status.cachedAt ? '8h' : '—',
              color: status.isReady ? 'text-emerald-700' : 'text-gray-400',
            },
          ].map(({ icon: Icon, label, value, color }) => (
            <div key={label} className="bg-white/60 rounded-xl p-3 text-center shadow-sm">
              <Icon className={`h-5 w-5 mx-auto mb-1 ${color}`} />
              <p className={`text-xl font-black ${color}`}>{value}</p>
              <p className="text-[11px] text-gray-500 font-medium">{label}</p>
            </div>
          ))}
        </div>

        {/* Barra de progreso durante descarga */}
        <AnimatePresence>
          {isPrefetching && progress && (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              exit={{ opacity: 0, height: 0 }}
              className="space-y-2"
            >
              <div className="flex justify-between items-center text-sm font-medium text-gray-700">
                <span className="flex items-center gap-1.5">
                  <RefreshCw className="h-4 w-4 animate-spin text-blue-600" />
                  {progress.step}
                </span>
                <span className="text-blue-600 font-bold">{pct}%</span>
              </div>
              <div className="w-full bg-gray-200 rounded-full h-3 overflow-hidden">
                <motion.div
                  className="h-3 rounded-full bg-gradient-to-r from-blue-500 to-emerald-500"
                  initial={{ width: 0 }}
                  animate={{ width: `${pct}%` }}
                  transition={{ duration: 0.4 }}
                />
              </div>
              <p className="text-xs text-gray-500 text-center">
                Descargando recursos {progress.current}/{progress.total}...
              </p>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Mensaje offline sin caché */}
        {!isOnline && !status.isReady && (
          <div className="bg-amber-100 border border-amber-300 rounded-xl p-3 flex items-start gap-3">
            <WifiOff className="h-5 w-5 text-amber-600 shrink-0 mt-0.5" />
            <div className="text-sm text-amber-800">
              <strong>Sin datos descargados.</strong> Conéctate a WiFi antes de ir al potrero para guardar los datos del hato.
            </div>
          </div>
        )}

        {/* Acciones */}
        <div className="flex gap-3">
          <button
            onClick={startPrefetch}
            disabled={!canDownload}
            className={[
              'flex-1 flex items-center justify-center gap-2 py-3.5 rounded-xl font-bold text-sm transition-all active:scale-95',
              canDownload
                ? 'bg-blue-600 text-white shadow-lg shadow-blue-200 hover:bg-blue-700'
                : 'bg-gray-200 text-gray-400 cursor-not-allowed',
            ].join(' ')}
          >
            {isPrefetching ? (
              <RefreshCw className="h-5 w-5 animate-spin" />
            ) : (
              <Download className="h-5 w-5" />
            )}
            {isPrefetching
              ? 'Descargando...'
              : status.isReady
              ? 'Actualizar datos'
              : 'Preparar para el campo'}
          </button>

          {status.isReady && (
            <button
              onClick={clearCache}
              className="px-4 py-3.5 rounded-xl bg-gray-100 text-gray-600 hover:bg-gray-200 transition-all active:scale-95 font-medium"
              title="Limpiar caché de campo"
            >
              <Trash2 className="h-5 w-5" />
            </button>
          )}
        </div>

        {/* Tip final */}
        <div className="flex items-start gap-2 bg-white/50 rounded-xl p-3 border border-white/80">
          <Zap className="h-4 w-4 text-amber-500 shrink-0 mt-0.5" />
          <p className="text-[11px] text-gray-600 leading-relaxed">
            <strong>Consejo:</strong> Descarga los datos en casa o en el casco urbano. Los formularios de campo seguirán guardando tus registros aunque pierdas señal y se sincronizarán automáticamente al volver.
          </p>
        </div>
      </div>
    </div>
  );
};

