  const [isOpen, setIsOpen] = useState(false);
  const navigate = useNavigate();

  const actions = [
    {
      id: 'weight',
      icon: <Scale className="h-5 w-5" />,
      label: 'PESO',
      path: '/quick/control',
      color: 'bg-blue-600',
    },
    {
      id: 'milk',
