                  "h-12 w-12 rounded-2xl flex items-center justify-center text-white shadow-2xl transition-transform hover:scale-110 active:scale-95",
                  action.color
                )}
              >
                {action.icon}
              </button>
            </motion.div>
          ))}
        </AnimatePresence>
      </div>

      {/* Botón Principal (FAB) */}
      <motion.button
        whileHover={{ scale: 1.05 }}
        whileTap={{ scale: 0.95 }}
        onClick={() => setIsOpen(!isOpen)}
        className={cn(
          "h-14 w-14 rounded-[2rem] flex items-center justify-center text-white shadow-2xl transition-all duration-500 relative overflow-hidden group",
          isOpen ? "bg-slate-900 rotate-90" : "bg-primary"
