import React, { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Wifi, 
  WifiOff, 
  Bluetooth, 
  RefreshCw, 
  Users, 
  Radio,
  Activity,
  Zap,
  Smartphone,
  CircleCheck,
  CircleAlert,
  RotateCw,
  Mic,
  BatteryMedium,
  Lock,
  Eye,
  EyeOff
} from 'lucide-react';
import { offlineQueue } from '@/shared/api/offline/offlineQueue';
import { proximitySync, type DiscoveredPeer, type SyncState } from '@/shared/api/offline/ProximitySyncService';
import { useFieldMode } from '@/app/providers/FieldModeContext';

// Web Bluetooth solo disponible en Chrome/Edge con HTTPS
const BLUETOOTH_AVAILABLE = typeof navigator !== 'undefined' && 'bluetooth' in navigator;
const WIFI_AVAILABLE = typeof navigator !== 'undefined' && 'onLine' in navigator;

export const MeshMonitor: React.FC = () => {
  // Ocultar completamente en browsers sin Web Bluetooth (Firefox, Safari)
  if (!BLUETOOTH_AVAILABLE) return null;

  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [pendingCount, setPendingCount] = useState(0);
  const [voiceNotesCount, setVoiceNotesCount] = useState(0);
  const [nearbyNodes, setNearbyNodes] = useState<DiscoveredPeer[]>([]);
  const [isScanning, setIsScanning] = useState(false);
  const [isAdvertising, setIsAdvertising] = useState(false);
  const [syncState, setSyncState] = useState<SyncState | null>(null);
  const [lastSyncMessage, setLastSyncMessage] = useState<string | null>(null);
  const [isAutoSyncEnabled, setIsAutoSyncEnabled] = useState(proximitySync.isAutoSyncEnabled);
  const [isBatterySaver, setIsBatterySaver] = useState(proximitySync.batterySaverMode);
  const [meshPin, setMeshPin] = useState(proximitySync.getMeshPin());
  const [isPinVisible, setIsPinVisible] = useState(false);
  const [showHelp, setShowHelp] = useState(false);
  const { isFieldMode } = useFieldMode();

  // Actualizar estado de sincronización
  const updateSyncState = useCallback(() => {
    setSyncState(proximitySync.getSyncState());
  }, []);

  // Manejar descubrimiento de peer
  const handlePeerDiscovered = useCallback((peer: DiscoveredPeer) => {
    setNearbyNodes(prev => {
      const filtered = prev.filter(p => p.id !== peer.id);
      return [...filtered, peer];
    });
  }, []);

  // Manejar pérdida de peer
  const handlePeerLost = useCallback((peerId: string) => {
    setNearbyNodes(prev => prev.filter(p => p.id !== peerId));
  }, []);

  // Manejar sincronización completada
  const handleSyncComplete = useCallback((result: { peerId: string; opsSynced: number }) => {
    const peer = nearbyNodes.find(p => p.id === result.peerId);
    setLastSyncMessage(`Sincronizado con ${peer?.name || 'dispositivo'}: ${result.opsSynced} operaciones`);
    updateSyncState();
    setTimeout(() => setLastSyncMessage(null), 3000);
  }, [nearbyNodes, updateSyncState]);

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);

    const updateQueue = async () => {
      const count = await offlineQueue.getPendingCount();
      setPendingCount(count);
      const vCount = await offlineQueue.getVoiceNotesCount();
      setVoiceNotesCount(vCount);
    };

    const interval = setInterval(updateQueue, 3000);
    updateQueue();
    updateSyncState();

    // Suscribirse a eventos de sincronización
    const unsubDiscovered = proximitySync.onPeerDiscovered(handlePeerDiscovered);
    const unsubLost = proximitySync.onPeerLost(handlePeerLost);
    const unsubSync = proximitySync.onSyncComplete(handleSyncComplete);

    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
      clearInterval(interval);
      unsubDiscovered();
      unsubLost();
      unsubSync();
    };
  }, [handlePeerDiscovered, handlePeerLost, handleSyncComplete, updateSyncState]);

  const handleScan = async () => {
    setIsScanning(true);
    try {
      const peer = await proximitySync.discoverPeers();
      if (peer) {
        handlePeerDiscovered(peer);
      }
    } catch (error) {
      console.error('[MeshMonitor] Error escaneando:', error);
    } finally {
      setIsScanning(false);
    }
  };

  const handleSyncWithPeer = async (peerId: string) => {
    const success = await proximitySync.syncWithPeer(peerId);
    if (!success) {
      console.error('[MeshMonitor] Error sincronizando con peer:', peerId);
    }
  };

  const handleToggleAdvertising = async () => {
    if (isAdvertising) {
      await proximitySync.stopAdvertising();
      setIsAdvertising(false);
    } else {
      await proximitySync.startAdvertising();
      setIsAdvertising(true);
    }
  };

  const handleToggleAutoSync = () => {
    const newState = !isAutoSyncEnabled;
    setIsAutoSyncEnabled(newState);
    proximitySync.setAutoSync(newState);
  };

  const handleToggleBatterySaver = () => {
    const newState = !isBatterySaver;
    setIsBatterySaver(newState);
    proximitySync.setBatterySaverMode(newState);
  };

  const handleUpdatePin = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newPin = e.target.value.replace(/\D/g, '').slice(0, 8); // Solo números, max 8
    setMeshPin(newPin);
    if (newPin.length >= 4) {
      proximitySync.setMeshPin(newPin);
    }
  };

  return (
    <div className={`rounded-3xl p-6 border shadow-sm ${
      isFieldMode ? 'bg-black border-4 border-white text-white' : 'bg-white border-gray-100'
    }`}>
      <div className="flex items-center justify-between mb-6">
        <div>
          <h3 className={`font-black ${isFieldMode ? 'text-3xl uppercase tracking-tighter' : 'text-lg text-gray-900'}`}>
            Sincronización Mesh
          </h3>
          <p className={`mt-1 ${isFieldMode ? 'text-lg text-green-500 font-bold uppercase' : 'text-sm text-gray-500'}`}>
            4VillaLuz: Trabajo en el Campo
          </p>
        </div>
        <div className={`px-4 py-2 rounded-full font-black flex items-center gap-2 whitespace-nowrap ${
          isOnline 
            ? (isFieldMode ? 'bg-white text-black text-xs' : 'bg-green-100 text-green-700 text-xs')
            : (isFieldMode ? 'bg-red-600 text-white text-xs ring-4 ring-white' : 'bg-amber-100 text-amber-700 text-xs')
        }`}>
          {isOnline ? <Wifi size={16} className="flex-shrink-0" /> : <WifiOff size={16} className="flex-shrink-0" />}
          <span className="whitespace-nowrap">{isOnline ? 'EN LÍNEA' : 'MODO OFFLINE'}</span>
        </div>
      </div>

      {/* Checklist de Preparación para el Campesino */}
      {!isAdvertising && !isScanning && (
        <div className={`mb-6 p-4 rounded-2xl border-2 border-dashed ${
          isFieldMode ? 'bg-zinc-900 border-white/30' : 'bg-blue-50 border-blue-100'
        }`}>
          <h4 className="text-xs font-black uppercase tracking-widest mb-3 flex items-center gap-2">
            <Smartphone size={14} /> Checklist para el Potrero
          </h4>
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <div className={`w-2 h-2 rounded-full ${BLUETOOTH_AVAILABLE ? 'bg-green-500' : 'bg-red-500'}`} />
                <span className="text-xs font-bold">Bluetooth activado</span>
              </div>
              {!BLUETOOTH_AVAILABLE && <span className="text-[10px] bg-red-100 text-red-600 px-2 py-0.5 rounded font-black">¡ACTÍVALO!</span>}
            </div>
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <div className="w-2 h-2 rounded-full bg-green-500" />
                <span className="text-xs font-bold">Ubicación (GPS) activa</span>
              </div>
            </div>
            <div className="pt-2">
              <button 
                onClick={() => {
                  handleToggleAdvertising();
                  handleScan();
                }}
                className={`w-full py-3 rounded-xl font-black uppercase tracking-tighter shadow-lg active:scale-95 transition-all ${
                  isFieldMode ? 'bg-white text-black' : 'bg-blue-600 text-white'
                }`}
              >
                ¡LISTO! EMPEZAR A SINCRONIZAR
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Mensaje de última sincronización */}
      <AnimatePresence>
        {lastSyncMessage && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0 }}
            className="mb-4 p-3 bg-green-50 border border-green-200 rounded-lg flex items-center gap-2"
          >
            <CircleCheck size={16} className="text-green-600" />
            <span className="text-sm text-green-700">{lastSyncMessage}</span>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Controles principales */}
      <div className="flex gap-2 mb-6">
        <button
          onClick={handleScan}
          disabled={isScanning}
          className="flex-1 flex items-center justify-center gap-2 px-6 py-4 bg-purple-600 text-white rounded-xl hover:bg-purple-700 disabled:bg-gray-300 disabled:cursor-not-allowed transition-all shadow-md active:scale-95 font-bold"
        >
          <RefreshCw size={20} className={isScanning ? 'animate-spin' : ''} />
          {isScanning ? 'Buscando...' : 'Buscar Compañeros Cerca'}
        </button>
        <button
          onClick={handleToggleAdvertising}
          className={`flex-1 flex items-center justify-center gap-2 px-6 py-4 rounded-xl transition-all shadow-md active:scale-95 font-bold ${
            isAdvertising 
              ? 'bg-red-100 text-red-700 hover:bg-red-200 border border-red-200' 
              : 'bg-blue-100 text-blue-700 hover:bg-blue-200 border border-blue-200'
          }`}
        >
          <Radio size={20} className={isAdvertising ? 'animate-pulse' : ''} />
          {isAdvertising ? 'Ocultar mi Celular' : 'Hacer mi Celular Visible'}
        </button>
      </div>

      {/* Toggles de Configuración */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
        {/* Toggle de Auto-Sync */}
        <div className={`flex items-center justify-between p-4 rounded-xl border ${
          isFieldMode ? 'bg-zinc-900 border-white' : 'bg-purple-50 border-purple-100'
        }`}>
          <div className="flex items-center gap-3">
            <div className={`p-2 rounded-full ${
              isAutoSyncEnabled 
                ? (isFieldMode ? 'bg-green-500 text-black' : 'bg-purple-600 text-white') 
                : 'bg-gray-200 text-gray-500'
            }`}>
              <Zap size={18} className={isAutoSyncEnabled ? 'animate-pulse' : ''} />
            </div>
            <div>
              <p className={`font-bold ${isFieldMode ? 'text-lg text-white uppercase' : 'text-sm text-purple-900'}`}>Sincronización Auto</p>
              <p className={`text-[10px] ${isFieldMode ? 'text-gray-400 uppercase' : 'text-purple-700'}`}>Pasar datos sin tocar nada</p>
            </div>
          </div>
          <button
            onClick={handleToggleAutoSync}
            className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
              isAutoSyncEnabled ? (isFieldMode ? 'bg-green-500' : 'bg-purple-600') : 'bg-gray-400'
            }`}
          >
            <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${isAutoSyncEnabled ? 'translate-x-6' : 'translate-x-1'}`} />
          </button>
        </div>

        {/* Toggle de Battery Saver */}
        <div className={`flex items-center justify-between p-4 rounded-xl border ${
          isFieldMode ? 'bg-zinc-900 border-white' : 'bg-amber-50 border-amber-100'
        }`}>
          <div className="flex items-center gap-3">
            <div className={`p-2 rounded-full ${
              isBatterySaver 
                ? (isFieldMode ? 'bg-yellow-500 text-black' : 'bg-amber-600 text-white') 
                : 'bg-gray-200 text-gray-500'
            }`}>
              <BatteryMedium size={18} />
            </div>
            <div>
              <p className={`font-bold ${isFieldMode ? 'text-lg text-white uppercase' : 'text-sm text-amber-900'}`}>Ahorro Batería</p>
              <p className={`text-[10px] ${isFieldMode ? 'text-gray-400 uppercase' : 'text-amber-700'}`}>Ideal para jornadas largas</p>
            </div>
          </div>
          <button
            onClick={handleToggleBatterySaver}
            className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
              isBatterySaver ? (isFieldMode ? 'bg-yellow-500' : 'bg-amber-600') : 'bg-gray-400'
            }`}
          >
            <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${isBatterySaver ? 'translate-x-6' : 'translate-x-1'}`} />
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
        {/* Card: Cola Offline */}
        <div className={`rounded-xl p-4 border ${isFieldMode ? 'bg-zinc-900 border-white' : 'bg-gray-50 border-gray-100'}`}>
          <div className="flex items-center gap-3 mb-2">
            <RotateCw className={`${isFieldMode ? 'text-white' : 'text-blue-500'} ${pendingCount > 0 ? 'animate-spin' : ''}`} size={20} />
            <span className={`font-bold ${isFieldMode ? 'text-sm uppercase' : 'text-sm'}`}>Datos por Enviar</span>
          </div>
          <p className={`font-black ${isFieldMode ? 'text-4xl text-green-500' : 'text-2xl text-gray-900'}`}>{pendingCount}</p>
          <p className={`text-[10px] mt-1 ${isFieldMode ? 'text-gray-400 uppercase' : 'text-gray-400'}`}>Cambios en la finca</p>
        </div>

        {/* Card: Notas de Voz */}
        <div className={`rounded-xl p-4 border ${isFieldMode ? 'bg-zinc-900 border-white' : 'bg-gray-50 border-gray-100'}`}>
          <div className="flex items-center gap-3 mb-2">
            <Mic className={`${isFieldMode ? 'text-white' : 'text-red-500'}`} size={20} />
            <span className={`font-bold ${isFieldMode ? 'text-sm uppercase' : 'text-sm'}`}>Reportes de Voz</span>
          </div>
          <p className={`font-black ${isFieldMode ? 'text-4xl text-green-500' : 'text-2xl text-gray-900'}`}>{voiceNotesCount}</p>
          <p className={`text-[10px] mt-1 ${isFieldMode ? 'text-gray-400 uppercase' : 'text-gray-400'}`}>Audios guardados</p>
        </div>

        {/* Card: Nodos Cercanos */}
        <div className={`rounded-xl p-4 border ${isFieldMode ? 'bg-zinc-900 border-white' : 'bg-gray-50 border-gray-100'}`}>
          <div className="flex items-center gap-3 mb-2">
            <Users className={`${isFieldMode ? 'text-white' : 'text-purple-500'}`} size={20} />
            <span className={`font-bold ${isFieldMode ? 'text-sm uppercase' : 'text-sm'}`}>Compañeros</span>
          </div>
          <p className={`font-black ${isFieldMode ? 'text-4xl text-green-500' : 'text-2xl text-gray-900'}`}>{nearbyNodes.length}</p>
          <p className={`text-[10px] mt-1 ${isFieldMode ? 'text-gray-400 uppercase' : 'text-gray-400'}`}>
            {nearbyNodes.filter(n => n.isConnected).length} vinculados
          </p>
        </div>
      </div>

      {/* Lista de Nodos */}
      <div className="mt-6">
        <h4 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-3">
          Compañeros Encontrados ({nearbyNodes.length})
        </h4>
        <div className="space-y-2 max-h-48 overflow-y-auto">
          {nearbyNodes.length === 0 ? (
            <div className="flex items-center gap-3 text-sm text-gray-500 py-4 italic bg-gray-50 rounded-lg px-4">
              <Activity size={16} strokeWidth={1} />
              No veo a nadie cerca. Presiona el botón morado para buscar a tus compañeros.
            </div>
          ) : (
            nearbyNodes.map(node => (
              <motion.div 
                key={node.id}
                initial={{ opacity: 0, x: -10 }}
                animate={{ opacity: 1, x: 0 }}
                className="flex items-center justify-between p-3 bg-gray-50 rounded-lg border border-gray-100 hover:bg-gray-100 transition-colors"
              >
                <div className="flex items-center gap-3">
                  {node.connectionType === 'bluetooth' ? (
                    <Bluetooth size={16} className="text-blue-500" />
                  ) : (
                    <Wifi size={16} className="text-green-500" />
                  )}
                  <div>
                    <p className="text-sm font-medium">{node.name}</p>
                    <p className="text-[10px] text-gray-400">
                      {node.connectionType === 'bluetooth' ? 'Bluetooth' : 'WiFi (WebRTC)'}
                      {' • '}
                      Hace {Math.floor((new Date().getTime() - node.lastSeen.getTime()) / 60000)} min
                    </p>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  {node.isConnected ? (
                    <span className="flex items-center gap-1 text-xs text-green-600 font-bold">
                      <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
                      Conectado
                    </span>
                  ) : (
                    <button
                      onClick={() => handleSyncWithPeer(node.id)}
                      disabled={node.isConnected || syncState?.isSyncing}
                      className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white text-xs rounded-lg hover:bg-green-700 disabled:bg-gray-300 transition-all font-bold shadow-sm"
                    >
                      <RefreshCw size={14} />
                      Pasar Datos
                    </button>
                  )}
                </div>
              </motion.div>
            ))
          )}
        </div>
      </div>

      {/* Indicador de estado de sincronización */}
      {syncState?.isSyncing && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="mt-4 p-3 bg-blue-50 border border-blue-200 rounded-lg flex items-center gap-3"
        >
          <RefreshCw size={18} className="text-blue-600 animate-spin" />
          <span className="text-sm text-blue-700 font-medium">Pasando información... por favor espera.</span>
        </motion.div>
      )}

      {/* Configuración de Seguridad (PIN) */}
      <div className={`mt-6 pt-6 border-t ${isFieldMode ? 'border-white/20' : 'border-gray-100'}`}>
        <div className="flex items-center gap-3 mb-4">
          <div className={`p-2 rounded-lg ${isFieldMode ? 'bg-zinc-800' : 'bg-gray-100'}`}>
            <Lock size={18} className={isFieldMode ? 'text-white' : 'text-gray-600'} />
          </div>
          <div>
            <h4 className={`font-bold ${isFieldMode ? 'text-sm uppercase' : 'text-sm text-gray-900'}`}>
              Seguridad de la Finca (PIN Mesh)
            </h4>
            <p className={`text-[10px] ${isFieldMode ? 'text-gray-400 uppercase' : 'text-gray-500'}`}>
              Este código protege tus datos en la red Bluetooth
            </p>
          </div>
        </div>
        <div className="flex gap-2">
          <div className="relative flex-1">
            <input
              type={isPinVisible ? 'text' : 'password'}
              value={meshPin}
              onChange={handleUpdatePin}
              placeholder="Ej: 1234"
              className={`w-full px-4 py-3 rounded-xl border font-mono tracking-widest ${
                isFieldMode 
                  ? 'bg-black border-white text-white focus:ring-green-500' 
                  : 'bg-gray-50 border-gray-200 focus:ring-purple-500'
              } ${meshPin.length < 4 ? 'border-red-500' : ''}`}
            />
            <button
              type="button"
              onClick={() => setIsPinVisible(!isPinVisible)}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
            >
              {isPinVisible ? <EyeOff size={18} /> : <Eye size={18} />}
            </button>
          </div>
          <div className={`px-4 py-2 flex items-center gap-2 rounded-xl border text-[10px] font-bold ${
            meshPin.length < 4 
              ? 'bg-red-500/10 border-red-500 text-red-500' 
              : 'bg-green-500/10 border-green-500 text-green-500'
          }`}>
            {meshPin.length < 4 ? (
              <><CircleAlert size={14} /> PIN MUY CORTO</>
            ) : (
              <><CircleCheck size={14} /> PIN SEGURO</>
            )}
          </div>
        </div>
        <p className="mt-2 text-[9px] text-gray-400 italic">
          * Todos los celulares de tu finca deben tener el mismo PIN para sincronizar.
        </p>
      </div>

      {/* Botón de Ayuda Transparente */}
      <button
        onClick={() => setShowHelp(!showHelp)}
        className={`mt-4 w-full p-4 rounded-xl flex items-center justify-center gap-3 font-bold transition-all ${
          isFieldMode ? 'bg-zinc-900 border border-white text-white' : 'bg-gray-100 text-gray-600'
        }`}
      >
        <Activity size={18} />
        {showHelp ? 'Ocultar Ayuda' : '¿Cómo funciona esto? (Ayuda)'}
      </button>

      <AnimatePresence>
        {showHelp && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            className="overflow-hidden"
          >
            <div className={`mt-4 p-5 rounded-2xl border ${isFieldMode ? 'bg-zinc-900 border-white' : 'bg-purple-50 border-purple-100'} space-y-4`}>
              <div className="flex items-start gap-4">
                <div className="p-3 bg-white rounded-full text-purple-600 shadow-sm">
                  <RefreshCw size={24} />
                </div>
                <div>
                  <p className={`font-black ${isFieldMode ? 'text-white uppercase' : 'text-purple-900'}`}>Sincronización Transparente</p>
                  <p className="text-xs text-purple-700">No necesitas hacer nada. Tu celular busca otros dispositivos de 4VillaLuz y les pasa la información automáticamente.</p>
                </div>
              </div>

              <div className="flex items-start gap-4">
                <div className="p-3 bg-white rounded-full text-blue-600 shadow-sm">
                  <Smartphone size={24} />
                </div>
                <div>
                  <p className={`font-black ${isFieldMode ? 'text-white uppercase' : 'text-blue-900'}`}>Efecto Multi-Salto (Mesh)</p>
                  <p className="text-xs text-blue-700">Si tu compañero tiene señal y tú no, tu celular le pasará los datos a él para que él los suba por ti cuando tenga internet.</p>
                </div>
              </div>

              <div className="flex items-start gap-4">
                <div className="p-3 bg-white rounded-full text-green-600 shadow-sm">
                  <Zap size={24} />
                </div>
                <div>
                  <p className={`font-black ${isFieldMode ? 'text-white uppercase' : 'text-green-900'}`}>Ahorro de Batería Inteligente</p>
                  <p className="text-xs text-green-700">La app sabe cuánta carga te queda. Si te queda poca, buscará a otros dispositivos con menos frecuencia para que no te quedes sin celular.</p>
                </div>
              </div>

              <div className="p-3 bg-white/20 rounded-xl text-[10px] text-center font-bold">
                ⚠️ RECUERDA: Mantén el Bluetooth y el WiFi encendidos aunque no tengas señal.
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Send, 
  AlertTriangle, 
  MessageSquare, 
  User, 
  Radio, 
  Signal,
  Bell,
  CircleCheck,
  X
} from 'lucide-react';
import { proximitySync, type DiscoveredPeer } from '@/shared/api/offline/ProximitySyncService';
import { useFieldMode } from '@/app/providers/FieldModeContext';
import { nodeMessagesService } from '@/shared/api/offline/nodeMessages.service';
import { ruralSyncService } from '@/shared/api/offline/ruralSync.service';

interface Message {
  id: string;
  from: string;
  content: string;
  type: 'alert' | 'chat';
  timestamp: Date;
}

export const NodeCommunicationWidget: React.FC = () => {
  const { isFieldMode } = useFieldMode();
  const [nodes, setNodes] = useState<DiscoveredPeer[]>([]);
  const [messages, setMessages] = useState<Message[]>([]);
  const [selectedNode, setSelectedNode] = useState<string | null>(null);
  const [inputText, setInputText] = useState('');
  const [isSending, setIsSending] = useState(false);
  const [showNotification, setShowNotification] = useState<Message | null>(null);

  // Cargar nodos iniciales
  useEffect(() => {
    setNodes(proximitySync.getDiscoveredPeers());
    nodeMessagesService.list({ limit: 50 }).then((items) => {
      if (!Array.isArray(items)) return;
      setMessages(items.map((item: any) => ({
        id: item.message_id || String(item.id),
        from: item.sender_device_id || item.sender_user_id || 'Nodo',
        content: item.content,
        type: item.message_type === 'alert' ? 'alert' : 'chat',
        timestamp: item.created_at ? new Date(item.created_at) : new Date()
      })));
    }).catch(() => {});

    const unsubDiscovered = proximitySync.onPeerDiscovered((peer) => {
      setNodes(prev => {
        const filtered = prev.filter(p => p.id !== peer.id);
        return [...filtered, peer];
      });
    });

    const unsubLost = proximitySync.onPeerLost((peerId) => {
      setNodes(prev => prev.filter(p => p.id !== peerId));
      if (selectedNode === peerId) setSelectedNode(null);
    });

    const unsubMsg = proximitySync.onMessageReceived((msg) => {
      const newMsg: Message = {
        id: `msg-${Date.now()}`,
        from: msg.from,
        content: msg.content,
        type: msg.type,
        timestamp: new Date()
      };
      setMessages(prev => [newMsg, ...prev].slice(0, 50));
      setShowNotification(newMsg);
      nodeMessagesService.send({
        content: msg.content,
        message_type: msg.type,
        sender_device_id: msg.from,
        recipient_node_id: ruralSyncService.getDeviceId(),
        priority: msg.type === 'alert' ? 10 : 100
      }).catch(() => {});

      // Auto-ocultar notificación después de 5 segundos
      setTimeout(() => setShowNotification(null), 5000);
    });

    return () => {
      unsubDiscovered();
      unsubLost();
      unsubMsg();
    };
  }, [selectedNode]);

  const handleSendMessage = async (type: 'alert' | 'chat') => {
    if (!selectedNode || (!inputText && type === 'chat')) return;

    setIsSending(true);
    const content = type === 'alert' ? '🚨 ¡ATENCIÓN! Revisa el canal de radio.' : inputText;

    const success = await proximitySync.sendMessageToPeer(selectedNode, content, type);

    if (success) {
      await nodeMessagesService.send({
        content,
        message_type: type,
        sender_device_id: ruralSyncService.getDeviceId(),
        recipient_node_id: selectedNode,
        priority: type === 'alert' ? 10 : 100
      }).catch(() => {});
      setInputText('');
      if (type === 'alert') setSelectedNode(null);
    }
    setIsSending(false);
  };

  const getStatusColor = (peer: DiscoveredPeer) => {
    if (peer.isConnected) return 'bg-green-500';
    return 'bg-blue-500';
  };

  return (
    <div className={`rounded-3xl p-6 border shadow-xl overflow-hidden relative ${
      isFieldMode ? 'bg-black border-white text-white' : 'bg-white border-slate-100'
    }`}>
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <div className={`p-3 rounded-2xl ${isFieldMode ? 'bg-zinc-800' : 'bg-indigo-50 text-indigo-600'}`}>
            <Radio size={24} className={nodes.length > 0 ? 'animate-pulse' : ''} />
          </div>
          <div>
            <h3 className={`font-black uppercase tracking-tighter ${isFieldMode ? 'text-2xl' : 'text-lg text-slate-800'}`}>
              Radio Enlace Mesh
            </h3>
            <p className={`text-[10px] font-bold uppercase tracking-widest ${isFieldMode ? 'text-indigo-400' : 'text-slate-500'}`}>
              {nodes.length} Nodos en Alcance
            </p>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 h-[400px]">
        {/* Node List */}
        <div className="flex flex-col h-full">
          <h4 className="text-[10px] font-black uppercase tracking-widest mb-3 opacity-50">Compañeros Cercanos</h4>
          <div className="flex-1 overflow-y-auto space-y-2 pr-2 custom-scrollbar">
            {nodes.length === 0 ? (
              <div className={`h-full flex flex-col items-center justify-center rounded-2xl border-2 border-dashed ${
                isFieldMode ? 'bg-zinc-900 border-zinc-800 text-zinc-600' : 'bg-slate-50 border-slate-100 text-slate-400'
              }`}>
                <Signal size={32} strokeWidth={1} className="mb-2 opacity-20" />
                <p className="text-xs font-bold uppercase tracking-tighter">Buscando señales...</p>
              </div>
            ) : (
              nodes.map(node => (
                <button
                  key={node.id}
                  onClick={() => setSelectedNode(node.id)}
                  className={`w-full flex items-center justify-between p-4 rounded-2xl transition-all border-2 ${
                    selectedNode === node.id
                      ? (isFieldMode ? 'bg-white border-white text-black' : 'bg-indigo-600 border-indigo-600 text-white shadow-lg scale-[1.02]')
                      : (isFieldMode ? 'bg-zinc-900 border-zinc-800 hover:border-zinc-700' : 'bg-slate-50 border-slate-50 hover:border-slate-200')
                  }`}
                >
                  <div className="flex items-center gap-3">
                    <div className="relative">
                      <div className={`w-10 h-10 rounded-full flex items-center justify-center ${
                        selectedNode === node.id ? 'bg-black/10' : (isFieldMode ? 'bg-black' : 'bg-white')
                      }`}>
                        <User size={20} />
                      </div>
                      <span className={`absolute -bottom-0.5 -right-0.5 w-3 h-3 rounded-full border-2 ${
                        selectedNode === node.id ? 'border-indigo-600' : (isFieldMode ? 'border-black' : 'border-slate-50')
                      } ${getStatusColor(node)}`} />
                    </div>
                    <div className="text-left">
                      <p className="font-black text-sm uppercase tracking-tighter leading-none mb-1">{node.name}</p>
                      <p className={`text-[9px] font-bold uppercase opacity-60`}>
                        {node.connectionType === 'bluetooth' ? 'Bluetooth' : 'Wi-Fi Direct'}
                      </p>
                    </div>
                  </div>
                  {node.signalStrength !== undefined && (
                    <div className="flex gap-0.5 items-end h-3">
                      {[1,2,3,4].map(i => (
                        <div 
                          key={i} 
                          className={`w-0.5 rounded-full ${i <= (node.signalStrength || 0) ? 'bg-current' : 'opacity-20'}`}
                          style={{ height: `${i * 25}%` }}
                        />
                      ))}
                    </div>
                  )}
                </button>
              ))
            )}
          </div>
        </div>

        {/* Messaging Interface */}
        <div className="flex flex-col h-full">
          <h4 className="text-[10px] font-black uppercase tracking-widest mb-3 opacity-50">Consola de Comunicación</h4>
          <div className={`flex-1 rounded-2xl p-4 mb-4 flex flex-col ${
            isFieldMode ? 'bg-zinc-900' : 'bg-slate-50'
          }`}>
            <div className="flex-1 overflow-y-auto space-y-3 pr-2 custom-scrollbar flex flex-col-reverse">
              {messages.length === 0 ? (
                <div className="h-full flex flex-col items-center justify-center opacity-30">
                  <MessageSquare size={24} className="mb-2" />
                  <p className="text-[10px] font-bold uppercase tracking-widest text-center">Sin mensajes recientes en la red</p>
                </div>
              ) : (
                messages.map(msg => (
                  <motion.div
                    key={msg.id}
                    initial={{ opacity: 0, x: 10 }}
                    animate={{ opacity: 1, x: 0 }}
                    className={`p-3 rounded-xl ${
                      msg.type === 'alert' 
                        ? (isFieldMode ? 'bg-red-600 text-white' : 'bg-red-50 text-red-700 border border-red-100')
                        : (isFieldMode ? 'bg-zinc-800 text-white' : 'bg-white text-slate-700 border border-slate-100 shadow-sm')
                    }`}
                  >
                    <div className="flex items-center justify-between mb-1">
                      <span className="text-[9px] font-black uppercase tracking-widest opacity-60">{msg.from}</span>
                      <span className="text-[8px] opacity-40">{msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                    </div>
                    <p className="text-xs font-bold">{msg.content}</p>
                  </motion.div>
                ))
              )}
            </div>
          </div>

          {/* Controls */}
          <div className="space-y-2">
            <div className="flex gap-2">
              <button
                disabled={!selectedNode || isSending}
                onClick={() => handleSendMessage('alert')}
                className={`flex-1 py-3 rounded-xl flex items-center justify-center gap-2 transition-all font-black text-xs uppercase tracking-tighter ${
                  selectedNode 
                    ? 'bg-red-600 text-white hover:bg-red-700 shadow-lg shadow-red-600/20 active:scale-95' 
                    : 'bg-zinc-800 text-zinc-600 cursor-not-allowed opacity-50'
                }`}
              >
                <AlertTriangle size={16} />
                ALERTA NODO
              </button>
              <div className="flex-[2] relative">
                <input
                  type="text"
                  value={inputText}
                  onChange={(e) => setInputText(e.target.value)}
                  disabled={!selectedNode || isSending}
                  placeholder={selectedNode ? "Escribir mensaje..." : "Selecciona un nodo"}
                  className={`w-full h-full pl-4 pr-12 rounded-xl border-2 transition-all text-sm font-bold ${
                    isFieldMode 
                      ? 'bg-black border-zinc-800 focus:border-white text-white' 
