                  className={`absolute right-2 top-1/2 -translate-y-1/2 p-2 rounded-lg transition-all ${
                    inputText && selectedNode
                      ? (isFieldMode ? 'bg-white text-black' : 'bg-indigo-600 text-white shadow-md')
                      : 'bg-zinc-800 text-zinc-600 opacity-20'
                  }`}
                >
                  <Send size={14} />
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Floating Notification */}
      <AnimatePresence>
        {showNotification && (
          <motion.div
            initial={{ opacity: 0, y: 50, scale: 0.9 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, scale: 0.9 }}
            className={`absolute bottom-6 left-6 right-6 p-4 rounded-2xl shadow-2xl z-50 border-2 flex items-center gap-4 ${
              showNotification.type === 'alert'
                ? 'bg-red-600 border-white text-white'
                : (isFieldMode ? 'bg-zinc-900 border-indigo-500 text-white' : 'bg-white border-indigo-100 text-slate-800')
