import React, { useEffect, useState } from 'react';
import { useAppState, AppStateProvider } from '@/app/providers/AppStateContext';
import { useAuth } from '@/features/auth/model/useAuth';
import { 
  DashboardSkeleton, 
  InitialLoadingSkeleton 
} from './DashboardSkeleton';
import { 
  PreloadErrorHandler, 
  NonCriticalErrorBanner,
  CriticalErrorDisplay 
} from './PreloadErrorHandler';
import { AppStateStatus } from '@/app/providers/AppStateContext';

/**
 * Props para el componente OptimizedDashboard
 */
interface OptimizedDashboardProps {
  /**
   * Componente a renderizar cuando los datos del dashboard están listos
   */
  children: React.ReactNode;
  /**
   * Mensaje personalizado para la pantalla de carga inicial
   */
  loadingMessage?: string;
  /**
   * Si es true, muestra errores no críticos en un banner
   */
  showNonCriticalErrors?: boolean;
}

/**
 * Componente optimizado para el dashboard con estrategia de precarga integrada
 * 
 * Características principales:
 * - Prioridad absoluta a los datos críticos del dashboard
 * - Muestra skeleton screens específicos durante la carga
 * - Manejo granular de errores según criticidad
 * - Precarga no bloqueante de módulos secundarios
 * - Indicadores de estado específicos para cada etapa
 */
export const OptimizedDashboard: React.FC<OptimizedDashboardProps> = ({
  children,
  loadingMessage = 'Cargando datos del dashboard...',
  showNonCriticalErrors = true
}) => {
  const { 
    state, 
    retryPreload, 
    clearErrors, 
    clearNonCriticalErrors,
    refreshDashboard,
    isDataFresh
  } = useAppState();
  const { user: _user, isAuthenticated } = useAuth();
  const [showNonCriticalBanner, setShowNonCriticalBanner] = useState(true);

  // Efecto para manejar errores no críticos
  useEffect(() => {
    const hasNonCriticalErrors = state.errors.some(error => !error.critical);
    
    if (hasNonCriticalErrors && showNonCriticalErrors) {
      // Auto-ocultar banner después de 10 segundos
      const timer = setTimeout(() => {
        setShowNonCriticalBanner(false);
      }, 10000);
      
      return () => clearTimeout(timer);
    }
  }, [state.errors, showNonCriticalErrors]);

  // Si el usuario no está autenticado, no mostrar nada (el AuthProvider se encargará de la redirección)
  if (!isAuthenticated) {
    return null;
  }

  // ESTADO 1: Inicializando - Mostrar pantalla de carga inicial
  if (state.status === AppStateStatus.INITIALIZING) {
    return <InitialLoadingSkeleton message={loadingMessage} />;
  }

  // ESTADO 2: Cargando datos críticos del dashboard - Mostrar skeleton específico
  if (state.status === AppStateStatus.LOADING_DASHBOARD) {
    return (
      <div className="w-full h-full">
        <DashboardSkeleton />
      </div>
    );
  }

  // ESTADO 3: Error crítico - Mostrar pantalla de error con opción de reintentar
  if (state.status === AppStateStatus.ERROR && state.hasCriticalErrors) {
    return (
      <div className="w-full h-full flex items-center justify-center p-8">
        <CriticalErrorDisplay
          errors={state.errors}
          onRetry={retryPreload}
        />
      </div>
    );
  }

  // ESTADO 4: Offline - Mostrar mensaje de conexión perdida
  if (state.status === AppStateStatus.OFFLINE) {
    return (
      <div className="w-full h-full flex items-center justify-center p-8">
        <div className="text-center max-w-md">
          <div className="w-16 h-16 bg-gray-200 rounded-full flex items-center justify-center mx-auto mb-4">
            <svg className="w-8 h-8 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M18.364 5.636l-3.536 3.536m0 5.656l3.536 3.536M9.172 9.172L5.636 5.636m3.536 9.192l-3.536 3.536M21 12a9 9 0 11-18 0 9 9 0 0118 0zm-5 0a4 4 0 11-8 0 4 4 0 018 0z" />
            </svg>
          </div>
          <h1 className="text-xl font-semibold text-gray-800 mb-2">
            Sin conexión a internet
          </h1>
          <p className="text-gray-600 mb-4">
            Verifica tu conexión y los datos se recargarán automáticamente.
          </p>
          <button
            onClick={retryPreload}
            className="bg-blue-600 hover:bg-blue-700 text-white font-medium py-2 px-4 rounded-lg transition-colors"
          >
            Reintentar
          </button>
        </div>
      </div>
    );
  }

  // ESTADO 5: Dashboard listo con datos críticos - Renderizar contenido principal
  return (
    <div className="w-full h-full">
      {/* Banner para errores no críticos */}
      {showNonCriticalErrors && 
       state.errors.some(error => !error.critical) && 
       showNonCriticalBanner && (
        <NonCriticalErrorBanner
          errors={state.errors}
          onRetry={retryPreload}
          onDismiss={() => {
            setShowNonCriticalBanner(false);
            clearNonCriticalErrors();
          }}
        />
      )}

      {/* Indicador de estado de carga de módulos secundarios */}
      {state.status === AppStateStatus.LOADING_MODULES && (
        <div className="bg-blue-50 border-l-4 border-blue-400 p-4 mb-4">
          <div className="flex items-center">
            <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-blue-600 mr-2"></div>
            <div className="flex-1">
              <p className="text-sm text-blue-700">
                Cargando módulos adicionales...
              </p>
              <div className="flex items-center space-x-4 mt-1">
                <span className={`text-xs ${state.animalModuleLoaded ? 'text-green-600' : 'text-gray-500'}`}>
                  {state.animalModuleLoaded ? '✓ Animales' : '○ Animales'}
                </span>
                <span className={`text-xs ${state.userModuleLoaded ? 'text-green-600' : 'text-gray-500'}`}>
                  {state.userModuleLoaded ? '✓ Usuarios' : '○ Usuarios'}
                </span>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Indicador de datos desactualizados */}
      {state.status === AppStateStatus.READY && !isDataFresh() && (
        <div className="bg-yellow-50 border-l-4 border-yellow-400 p-4 mb-4">
          <div className="flex items-center">
            <div className="flex-1">
              <p className="text-sm text-yellow-700">
                Los datos pueden estar desactualizados.
              </p>
            </div>
            <button
              onClick={refreshDashboard}
              className="text-yellow-700 hover:text-yellow-900 text-sm underline ml-4"
            >
              Actualizar
            </button>
          </div>
        </div>
      )}

      {/* Contenido principal del dashboard */}
      <div className="relative">
        {/* Overlay de carga para módulos secundarios (no bloqueante) */}
        {state.status === AppStateStatus.LOADING_MODULES && (
          <div className="absolute inset-0 bg-white bg-opacity-50 z-10 flex items-center justify-center">
            <div className="text-center">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto mb-2"></div>
              <p className="text-sm text-gray-600">
                Cargando módulos adicionales...
              </p>
            </div>
          </div>
        )}
        
        {/* Renderizar children solo cuando los datos críticos están listos */}
        {state.dashboardLoaded && children}
      </div>

      {/* Panel de errores detallado (colapsable) */}
      {state.errors.length > 0 && (
        <div className="fixed bottom-4 right-4 z-50 max-w-md">
          <div className="bg-white rounded-lg shadow-lg border border-gray-200 p-4">
            <div className="flex items-center justify-between mb-2">
              <h3 className="text-sm font-medium text-gray-900">
                Problemas detectados ({state.errors.length})
              </h3>
              <button
                onClick={clearErrors}
                className="text-gray-400 hover:text-gray-600"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
            <PreloadErrorHandler
              errors={state.errors}
              onRetry={retryPreload}
              onClearErrors={clearErrors}
              className="max-h-60 overflow-y-auto"
            />
          </div>
        </div>
      )}
    </div>
  );
};

/**
 * Componente wrapper que integra el OptimizedDashboard con el AppStateProvider
 * Útil para envolver toda la aplicación o secciones específicas
 */
export const OptimizedDashboardProvider: React.FC<{
  children: React.ReactNode;
  autoStart?: boolean;
}> = ({ 
  children, 
  autoStart = true
}) => {
  return (
    <AppStateProvider autoStart={autoStart}>
      <OptimizedDashboard>
        {children}
      </OptimizedDashboard>
    </AppStateProvider>
  );
};

/**
 * Hook personalizado para facilitar el uso del OptimizedDashboard
 * Proporciona acceso al estado y acciones comunes
 */
// eslint-disable-next-line react-refresh/only-export-components
export const useOptimizedDashboard = () => {
  const appState = useAppState();
  const _auth = useAuth();
  
  return {
    // Estado
    isLoading: appState.state.isLoading,
    isReady: appState.state.status === AppStateStatus.READY,
    hasErrors: appState.state.errors.length > 0,
    hasCriticalErrors: appState.state.hasCriticalErrors,
    dashboardData: appState.state.dashboardData,
    
    // Acciones
    refresh: appState.refreshDashboard,
    retry: appState.retryPreload,
    clearErrors: appState.clearErrors,
    
    // Utilidades
    isDataFresh: appState.isDataFresh,
    getTimeSinceLastUpdate: () => 
      appState.state.lastUpdate ? Date.now() - appState.state.lastUpdate : null
  };
};

export default OptimizedDashboard;

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from "@/shared/ui/card";
import { Badge } from "@/shared/ui/badge";
import { ScrollArea } from "@/shared/ui/scroll-area";
import { FileText, Clock, Send, Trash2, Database } from 'lucide-react';
import { offlineQueue } from '@/shared/api/offline/offlineQueue';
import { Button } from '@/shared/ui/button';

export const PendingSyncList: React.FC = () => {
  const [pendingItems, setPendingItems] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const refreshList = async () => {
    try {
      setIsLoading(true);
      const operations = await offlineQueue.getPendingOperations();

      const items = operations.map(op => ({
        id: op.id,
        type: op.method,
        title: op.data?.name || op.data?.record || op.data?.product_name || `Operación ${op.method}`,
        url: op.url,
        timestamp: new Date(op.timestamp).toISOString(),
        status: op.status,
        error: op.error
      }));

      setPendingItems(items);
    } catch (error) {
      console.error('[PendingSyncList] Error refreshing list:', error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    refreshList();
    const interval = setInterval(refreshList, 5000);
    return () => clearInterval(interval);
  }, []);

  if (pendingItems.length === 0) return null;

  return (
    <Card className="rounded-[2rem] border-0 bg-white/50 backdrop-blur-sm shadow-xl overflow-hidden border-2 border-emerald-100">
      <CardHeader className="bg-emerald-900 text-white p-5">
        <CardTitle className="text-xl font-black flex items-center gap-2">
          <Database className="w-5 h-5 text-emerald-300" />
          Cola de Sincronización
        </CardTitle>
      </CardHeader>
      <CardContent className="p-0">
        <ScrollArea className="h-[250px]">
          <div className="divide-y divide-emerald-100">
            {pendingItems.map((item) => (
              <div key={item.id} className="p-4 flex items-center justify-between hover:bg-emerald-50/50 transition-colors">
                <div className="flex items-center gap-3">
                  <div className="bg-emerald-100 p-2 rounded-xl">
                    <FileText className="w-5 h-5 text-emerald-700" />
                  </div>
                  <div>
                    <div className="flex items-center gap-2">
                      <p className="font-bold text-sm text-emerald-900">{item.title}</p>
                      <Badge variant="secondary" className="text-[8px] h-3 px-1">{item.type}</Badge>
                    </div>
                    <div className="flex items-center gap-2 text-[10px] text-emerald-600 font-medium">
                      <Clock className="w-3 h-3" />
                      {new Date(item.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      {item.error && <span className="text-red-500 ml-1">• Error detectado</span>}
                    </div>
                  </div>
                </div>
                <Badge variant="outline" className="bg-amber-50 text-amber-700 border-amber-200 text-[10px] font-black uppercase">
                  Pendiente
                </Badge>
              </div>
            ))}
          </div>
        </ScrollArea>
        <div className="p-4 bg-emerald-50 border-t border-emerald-100">
          <p className="text-[10px] font-bold text-emerald-800 text-center uppercase tracking-widest">
            Se enviará automáticamente al detectar señal
          </p>
        </div>
      </CardContent>
    </Card>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Card, CardHeader, CardContent } from '@/shared/ui/card';
import { Button } from '@/shared/ui/button';
import { useRequestMonitor } from '@/shared/utils/requestMonitor';
import { useCacheDebug } from '@/shared/hooks/useOptimizedFormData';
import { Badge } from '@/shared/ui/badge';
import { Progress } from '@/shared/ui/progress';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/shared/ui/tabs';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';

// Module-level constant so it doesn't affect hook dependencies
const commonEntities = ['animals', 'users', 'diseases', 'species', 'breeds', 'fields', 'medications', 'vaccines'];

interface PerformanceMonitorProps {
  autoRefresh?: boolean;
  refreshInterval?: number;
}

export const PerformanceMonitor: React.FC<PerformanceMonitorProps> = ({
  autoRefresh = true,
  refreshInterval = 5000
}) => {
  const [stats, setStats] = useState<any>(null);
  const [isVisible, setIsVisible] = useState(false);
  const { getStats, printStats, getRedundantRequests, clear } = useRequestMonitor();
  const { getCacheStats, logCacheStats } = useCacheDebug();

  const updateStats = useCallback(() => {
    const requestStats = getStats(60000); // Últimos 60 segundos
    const redundantRequests = getRedundantRequests(30000); // Últimos 30 segundos
    const cacheStats = getCacheStats(commonEntities);
    
    setStats({
      ...requestStats,
      redundantRequests,
      cacheStats
    });
  }, [getStats, getRedundantRequests, getCacheStats]);

  useEffect(() => {
    updateStats();
  }, [updateStats]);

  useEffect(() => {
    if (autoRefresh && isVisible) {
      const interval = setInterval(updateStats, refreshInterval);
      return () => clearInterval(interval);
    }
  }, [autoRefresh, refreshInterval, isVisible, updateStats]);

  if (!isVisible) {
    return (
      <div className="fixed bottom-4 right-4 z-50">
        <Button
          onClick={() => setIsVisible(true)}
          variant="outline"
          size="sm"
          className="bg-background"
        >
          📊 Performance
        </Button>
      </div>
    );
  }

  const chartData = stats?.endpointStats ? Object.entries(stats.endpointStats).map(([endpoint, data]: [string, any]) => ({
    endpoint: endpoint.split('/').pop() || endpoint,
    api: data.api,
    cached: data.cached,
    total: data.total
  })) : [];

  const pieData = [
    { name: 'Cache Hits', value: stats?.cacheHits || 0, color: '#10b981' },
    { name: 'API Calls', value: stats?.apiCalls || 0, color: '#f59e0b' }
  ];

  return (
    <div className="fixed bottom-4 right-4 z-50 w-96 max-h-[80vh] overflow-hidden">
      <Card className="bg-background border shadow-lg">
        <CardHeader className="pb-2">
          <div className="flex items-center justify-between">
            <h3 className="text-sm font-semibold">📊 Performance Monitor</h3>
            <div className="flex gap-1">
              <Button
                onClick={updateStats}
                variant="ghost"
                size="sm"
                className="h-6 px-2 text-xs"
              >
                🔄
              </Button>
              <Button
                onClick={() => {
                  printStats();
                  logCacheStats(commonEntities);
                }}
                variant="ghost"
                size="sm"
                className="h-6 px-2 text-xs"
              >
                📋
              </Button>
              <Button
                onClick={clear}
                variant="ghost"
                size="sm"
                className="h-6 px-2 text-xs"
              >
                🗑️
              </Button>
              <Button
                onClick={() => setIsVisible(false)}
                variant="ghost"
                size="sm"
                className="h-6 px-2 text-xs"
              >
                ✕
              </Button>
            </div>
          </div>
        </CardHeader>
        
        <CardContent className="pt-0 max-h-[60vh] overflow-y-auto">
          <Tabs defaultValue="overview" className="w-full">
            <TabsList className="grid w-full grid-cols-3 h-8">
              <TabsTrigger value="overview" className="text-xs">Overview</TabsTrigger>
              <TabsTrigger value="cache" className="text-xs">Cache</TabsTrigger>
              <TabsTrigger value="endpoints" className="text-xs">Endpoints</TabsTrigger>
            </TabsList>
            
            <TabsContent value="overview" className="space-y-3 mt-3">
              <div className="grid grid-cols-2 gap-2 text-xs">
                <div className="space-y-1">
                  <div className="flex justify-between">
                    <span>Total Requests:</span>
                    <Badge variant="secondary">{stats?.totalRequests || 0}</Badge>
                  </div>
                  <div className="flex justify-between">
                    <span>API Calls:</span>
                    <Badge variant="destructive">{stats?.apiCalls || 0}</Badge>
                  </div>
                  <div className="flex justify-between">
                    <span>Cache Hits:</span>
                    <Badge variant="default">{stats?.cacheHits || 0}</Badge>
                  </div>
                </div>
                <div className="space-y-1">
                  <div className="flex justify-between">
                    <span>Hit Rate:</span>
                    <Badge variant={stats?.cacheHitRate > 50 ? "default" : "secondary"}>
                      {stats?.cacheHitRate?.toFixed(1) || 0}%
                    </Badge>
                  </div>
                  <div className="flex justify-between">
                    <span>Avg Time:</span>
                    <Badge variant="outline">{stats?.averageResponseTime?.toFixed(0) || 0}ms</Badge>
                  </div>
                  <div className="flex justify-between">
                    <span>Redundant:</span>
                    <Badge variant={stats?.redundantEndpoints?.length > 0 ? "destructive" : "default"}>
                      {stats?.redundantEndpoints?.length || 0}
                    </Badge>
                  </div>
                </div>
              </div>
              
              <div className="space-y-2">
                <div className="text-xs font-medium">Cache Hit Rate</div>
                <Progress value={stats?.cacheHitRate || 0} className="h-2" />
              </div>
              
              {stats?.totalRequests > 0 && (
                <div className="h-32">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie
                        data={pieData}
                        cx="50%"
                        cy="50%"
                        innerRadius={30}
                        outerRadius={50}
                        dataKey="value"
                      >
                        {pieData.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={entry.color} />
                        ))}
                      </Pie>
                      <Tooltip />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
              )}
            </TabsContent>
            
            <TabsContent value="cache" className="space-y-3 mt-3">
              <div className="space-y-2">
                <div className="text-xs font-medium">Cache Status by Entity</div>
                {stats?.cacheStats?.map((stat: any, index: number) => (
                  <div key={index} className="flex items-center justify-between text-xs">
                    <span className="capitalize">{stat.entity}</span>
                    <div className="flex items-center gap-2">
                      <Badge variant={stat.cached ? "default" : "secondary"}>
                        {stat.cached ? '✅' : '❌'}
                      </Badge>
                      <span className="text-muted-foreground">
                        {stat.itemCount} items
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            </TabsContent>
            
            <TabsContent value="endpoints" className="space-y-3 mt-3">
              {chartData.length > 0 && (
                <div className="h-40">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={chartData}>
                      <CartesianGrid strokeDasharray="3 3" />
                      <XAxis 
                        dataKey="endpoint" 
                        tick={{ fontSize: 10 }}
                        angle={-45}
                        textAnchor="end"
                        height={60}
                      />
                      <YAxis tick={{ fontSize: 10 }} />
                      <Tooltip />
                      <Bar dataKey="api" fill="#f59e0b" name="API Calls" />
                      <Bar dataKey="cached" fill="#10b981" name="Cache Hits" />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              )}
              
              {stats?.redundantRequests?.length > 0 && (
                <div className="space-y-2">
                  <div className="text-xs font-medium text-destructive">⚠️ Redundant Requests</div>
                  {stats.redundantRequests.slice(0, 3).map((req: any, index: number) => (
                    <div key={index} className="text-xs p-2 bg-destructive text-destructive-foreground rounded">
                      <div className="font-mono text-[10px] truncate">{req.url}</div>
                      <div className="text-destructive-foreground">{req.count} calls in 30s</div>
                    </div>
                  ))}
                </div>
              )}
            </TabsContent>
          </Tabs>
        </CardContent>
      </Card>
    </div>
  );
};

export default PerformanceMonitor;

import React, { useState } from 'react';
import { AlertTriangle, RefreshCw, WifiOff, Shield, Database, Info } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Alert, AlertDescription, AlertTitle } from '@/shared/ui/alert';
import { Badge } from '@/shared/ui/badge';
import { Collapsible, CollapsibleContent } from '@/shared/ui/collapsible';
import { PreloadError, PreloadErrorType } from '@/features/dashboard/api/dataPreload.service';

/**
 * Props para el componente de manejo de errores de precarga
 */
interface PreloadErrorHandlerProps {
  /**
   * Lista de errores a mostrar
   */
  errors: PreloadError[];
  /**
   * Función para reintentar la precarga
   */
  onRetry?: () => void;
  /**
   * Función para limpiar errores
   */
  onClearErrors?: () => void;
  /**
   * Si es true, muestra solo errores críticos
   */
  showOnlyCritical?: boolean;
  /**
   * Clases CSS adicionales
   */
  className?: string;
}

/**
 * Componente para manejar errores de precarga de forma granular
 * 
 * Características:
 * - Diferencia entre errores críticos y no críticos
 * - Proporciona acciones específicas según el tipo de error
 * - Muestra información detallada del error
 * - Permite reintentar operaciones específicas
 */
export const PreloadErrorHandler: React.FC<PreloadErrorHandlerProps> = ({
  errors,
  onRetry,
  onClearErrors,
  showOnlyCritical = false,
  className = ''
}) => {
  const [expandedErrors, setExpandedErrors] = useState<Set<string>>(new Set());

  // Filtrar errores según la configuración
  const filteredErrors = showOnlyCritical 
    ? errors.filter(error => error.critical)
    : errors;

  // Si no hay errores que mostrar, no renderizar nada
  if (filteredErrors.length === 0) {
    return null;
  }

  // Agrupar errores por tipo
  const errorsByType = filteredErrors.reduce((acc, error) => {
    if (!acc[error.type]) {
      acc[error.type] = [];
    }
    acc[error.type].push(error);
    return acc;
  }, {} as Record<PreloadErrorType, PreloadError[]>);

  // Obtener información específica del tipo de error
  const getErrorTypeInfo = (type: PreloadErrorType) => {
    switch (type) {
      case PreloadErrorType.DASHBOARD_CRITICAL:
        return {
          title: 'Error crítico del dashboard',
          description: 'No se pudieron cargar los datos esenciales del dashboard. La aplicación puede no funcionar correctamente.',
          icon: AlertTriangle,
          color: 'destructive',
          critical: true,
          actions: ['retry', 'details']
        };
      case PreloadErrorType.ANIMAL_MODULE:
        return {
          title: 'Error en módulo Animal',
          description: 'No se pudieron cargar los datos del módulo Animal. Algunas funciones pueden no estar disponibles.',
          icon: Database,
          color: 'default',
          critical: false,
          actions: ['retry-module', 'details']
        };
      case PreloadErrorType.USER_MODULE:
        return {
          title: 'Error en módulo Usuario',
          description: 'No se pudieron cargar los datos del módulo Usuario. Algunas funciones pueden no estar disponibles.',
          icon: Database,
          color: 'default',
          critical: false,
          actions: ['retry-module', 'details']
        };
      case PreloadErrorType.NETWORK_ERROR:
        return {
          title: 'Error de red',
          description: 'Problemas de conectividad al intentar cargar los datos. Verifica tu conexión a internet.',
          icon: WifiOff,
          color: 'default',
          critical: false,
          actions: ['retry', 'details']
        };
      case PreloadErrorType.AUTHENTICATION_ERROR:
        return {
          title: 'Error de autenticación',
          description: 'Problemas con la sesión de usuario. Es posible que necesites iniciar sesión nuevamente.',
          icon: Shield,
          color: 'destructive',
          critical: true,
          actions: ['retry', 'details']
        };
      default:
        return {
          title: 'Error desconocido',
          description: 'Ocurrió un error inesperado al cargar los datos.',
          icon: AlertTriangle,
          color: 'default',
          critical: false,
          actions: ['retry', 'details']
        };
    }
  };

  // Formatear timestamp para mostrarlo de forma legible
  const formatTimestamp = (timestamp: number) => {
    const date = new Date(timestamp);
    return date.toLocaleTimeString('es-ES', {
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
  };

  // Toggle expansión de detalles de error
  const toggleErrorExpansion = (errorId: string) => {
    const newExpanded = new Set(expandedErrors);
    if (newExpanded.has(errorId)) {
      newExpanded.delete(errorId);
    } else {
      newExpanded.add(errorId);
    }
    setExpandedErrors(newExpanded);
  };

  // Renderizar acciones específicas para un tipo de error
  const renderErrorActions = (type: PreloadErrorType, error: PreloadError) => {
    const typeInfo = getErrorTypeInfo(type);
    
    return (
      <div className="flex flex-wrap gap-2 mt-3">
        {typeInfo.actions.includes('retry') && onRetry && (
          <Button
            variant="outline"
            size="sm"
            onClick={onRetry}
            className="flex items-center gap-1"
          >
            <RefreshCw className="w-3 h-3" />
            Reintentar todo
          </Button>
        )}
        
        {typeInfo.actions.includes('retry-module') && onRetry && (
          <Button
            variant="outline"
            size="sm"
            onClick={() => {
              // Aquí podríamos implementar un reintento específico del módulo
              // Por ahora, usamos el reintento general
              onRetry();
            }}
            className="flex items-center gap-1"
          >
            <RefreshCw className="w-3 h-3" />
            Reintentar módulo
          </Button>
        )}
        
        {typeInfo.actions.includes('details') && (
          <Button
            variant="ghost"
            size="sm"
            onClick={() => toggleErrorExpansion(`${type}-${error.timestamp}`)}
            className="flex items-center gap-1"
          >
            <Info className="w-3 h-3" />
            Detalles
          </Button>
        )}
      </div>
    );
  };

  // Renderizar contenido expandido con detalles del error
  const renderErrorDetails = (error: PreloadError) => {
    const errorId = `${error.type}-${error.timestamp}`;
    const isExpanded = expandedErrors.has(errorId);
    
    return (
      <Collapsible open={isExpanded} onOpenChange={() => toggleErrorExpansion(errorId)}>
        <CollapsibleContent className="mt-3">
          <div className="bg-gray-50 dark:bg-gray-800 p-3 rounded-md text-sm">
            <div className="space-y-2">
              <div className="flex justify-between">
                <span className="font-medium">Tipo:</span>
                <Badge variant={error.critical ? 'destructive' : 'secondary'}>
                  {error.type}
                </Badge>
              </div>
              
              <div className="flex justify-between">
                <span className="font-medium">Hora:</span>
                <span>{formatTimestamp(error.timestamp)}</span>
              </div>
              
              <div>
                <span className="font-medium">Mensaje:</span>
                <p className="mt-1 text-gray-600 dark:text-gray-400">
                  {error.message}
                </p>
              </div>
              
              {error.context && (
                <div>
                  <span className="font-medium">Contexto:</span>
                  <pre className="mt-1 text-xs bg-gray-100 dark:bg-gray-900 p-2 rounded overflow-auto max-h-32">
                    {JSON.stringify(error.context, null, 2)}
                  </pre>
                </div>
              )}
            </div>
          </div>
        </CollapsibleContent>
      </Collapsible>
    );
  };

  return (
    <div className={`space-y-4 ${className}`}>
      {/* Contador de errores */}
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-medium">
          {showOnlyCritical ? 'Errores críticos' : 'Errores detectados'}
        </h3>
        <div className="flex items-center gap-2">
          <Badge variant={showOnlyCritical ? 'destructive' : 'secondary'}>
            {filteredErrors.length} {filteredErrors.length === 1 ? 'error' : 'errores'}
          </Badge>
          
          {onClearErrors && (
            <Button
              variant="ghost"
              size="sm"
              onClick={onClearErrors}
              className="text-gray-500 hover:text-gray-700"
            >
              Limpiar
            </Button>
          )}
        </div>
      </div>

      {/* Lista de errores agrupados por tipo */}
      {Object.entries(errorsByType).map(([type, typeErrors]) => {
        const typeInfo = getErrorTypeInfo(type as PreloadErrorType);
        const Icon = typeInfo.icon;
        
        return (
          <Alert key={type} variant={typeInfo.color as any}>
            <Icon className="h-4 w-4" />
            <AlertTitle className="flex items-center gap-2">
              {typeInfo.title}
              {typeInfo.critical && (
                <Badge variant="destructive" className="text-xs">
                  Crítico
                </Badge>
              )}
            </AlertTitle>
            <AlertDescription>
              {typeInfo.description}
              
              {/* Mostrar el error más reciente de este tipo */}
              {typeErrors.length > 0 && (
                <div className="mt-2">
                  <p className="text-sm font-medium">
                    Error más reciente: {typeErrors[0].message}
                  </p>
                  
                  {/* Renderizar acciones para el error más reciente */}
                  {renderErrorActions(type as PreloadErrorType, typeErrors[0])}
                  
                  {/* Renderizar detalles del error más reciente */}
                  {renderErrorDetails(typeErrors[0])}
                  
                  {/* Si hay múltiples errores del mismo tipo, mostrar contador */}
                  {typeErrors.length > 1 && (
                    <div className="mt-2 text-xs text-gray-500">
                      {typeErrors.length - 1} error(es) adicional(es) de este tipo
                    </div>
                  )}
                </div>
              )}
            </AlertDescription>
          </Alert>
        );
      })}
      
      {/* Acciones globales */}
      {onRetry && (
        <div className="flex justify-center pt-4">
          <Button onClick={onRetry} className="flex items-center gap-2">
            <RefreshCw className="w-4 h-4" />
            Reintentar carga completa
          </Button>
        </div>
      )}
    </div>
  );
};

/**
 * Componente simplificado para mostrar solo errores críticos
 * Útil para la pantalla de error completo
 */
export const CriticalErrorDisplay: React.FC<{
  errors: PreloadError[];
  onRetry?: () => void;
}> = ({ errors, onRetry }) => {
  const criticalErrors = errors.filter(error => error.critical);
  
  if (criticalErrors.length === 0) {
    return null;
  }

  return (
    <div className="w-full max-w-md mx-auto p-6 bg-white rounded-lg shadow-lg">
      <div className="text-center mb-6">
        <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
          <AlertTriangle className="w-8 h-8 text-red-600" />
        </div>
        <h1 className="text-2xl font-bold text-gray-900 mb-2">
          Error crítico
        </h1>
        <p className="text-gray-600">
          No se pudo cargar información esencial para el funcionamiento de la aplicación.
        </p>
      </div>

      <PreloadErrorHandler
        errors={criticalErrors}
        onRetry={onRetry}
        showOnlyCritical={true}
      />
    </div>
  );
};

/**
 * Componente para mostrar errores no críticos en un banner discreto
 */
export const NonCriticalErrorBanner: React.FC<{
  errors: PreloadError[];
  onRetry?: () => void;
  onDismiss?: () => void;
}> = ({ errors, onRetry, onDismiss }) => {
  const nonCriticalErrors = errors.filter(error => !error.critical);
  
  if (nonCriticalErrors.length === 0) {
    return null;
  }

  return (
    <div className="w-full bg-yellow-50 border-l-4 border-yellow-400 p-4 mb-4">
      <div className="flex items-center">
        <AlertTriangle className="h-5 w-5 text-yellow-400 mr-2" />
        <div className="flex-1">
          <p className="text-sm text-yellow-700">
            Algunos datos no pudieron cargarse. La aplicación seguirá funcionando, 
            pero algunas características pueden no estar disponibles.
          </p>
        </div>
        <div className="flex space-x-2 ml-4">
          {onRetry && (
            <button
              onClick={onRetry}
              className="text-yellow-700 hover:text-yellow-900 text-sm underline"
            >
              Reintentar
            </button>
          )}
          {onDismiss && (
            <button
              onClick={onDismiss}
              className="text-yellow-700 hover:text-yellow-900 text-sm underline"
            >
              Ocultar
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default PreloadErrorHandler;

import React from 'react';
import { Loader2, CircleCheck, CircleAlert, Wifi, WifiOff, Database, Users, PawPrint } from 'lucide-react';
import { Progress } from '@/shared/ui/progress';
import { Badge } from '@/shared/ui/badge';
import { Card, CardContent } from '@/shared/ui/card';
import { AppStateStatus } from '@/app/providers/AppStateContext';

/**
 * Props para los indicadores de precarga
 */
interface PreloadIndicatorsProps {
  /**
   * Estado actual de la aplicación
   */
  status: AppStateStatus;
  /**
   * Indicadores de progreso de cada módulo
   */
  moduleProgress: {
    dashboard: boolean;
    animal: boolean;
    user: boolean;
  };
  /**
   * Si la conexión está activa
   */
  isOnline: boolean;
  /**
   * Timestamp de la última actualización
   */
  lastUpdate?: number | null;
  /**
   * Estilo del indicador (compacto, completo, minimalista)
   */
  variant?: 'compact' | 'full' | 'minimal';
  /**
   * Clases CSS adicionales
   */
  className?: string;
}

/**
 * Componente para mostrar indicadores de carga específicos para cada etapa
 * 
 * Características:
 * - Indicadores visuales para cada fase del proceso de precarga
 * - Información de estado de conexión
 * - Progreso de carga por módulo
 * - Diferentes estilos según el contexto de uso
 */
export const PreloadIndicators: React.FC<PreloadIndicatorsProps> = ({
  status,
  moduleProgress,
  isOnline,
  lastUpdate,
  variant = 'compact',
  className = ''
}) => {
  // Obtener información específica del estado
  const getStatusInfo = () => {
    switch (status) {
      case AppStateStatus.INITIALIZING:
        return {
          icon: Loader2,
          color: 'text-blue-600',
          bgColor: 'bg-blue-50',
          message: 'Inicializando aplicación...',
          description: 'Preparando componentes y verificando estado'
        };
      case AppStateStatus.LOADING_DASHBOARD:
        return {
          icon: Loader2,
          color: 'text-blue-600',
          bgColor: 'bg-blue-50',
          message: 'Cargando dashboard...',
          description: 'Obteniendo datos críticos para el dashboard'
        };
      case AppStateStatus.DASHBOARD_READY:
        return {
          icon: CircleCheck,
          color: 'text-green-600',
          bgColor: 'bg-green-50',
          message: 'Dashboard listo',
          description: 'Datos críticos cargados correctamente'
        };
      case AppStateStatus.LOADING_MODULES:
        return {
          icon: Loader2,
          color: 'text-blue-600',
          bgColor: 'bg-blue-50',
          message: 'Cargando módulos...',
          description: 'Cargando datos adicionales en segundo plano'
        };
      case AppStateStatus.READY:
        return {
          icon: CircleCheck,
          color: 'text-green-600',
          bgColor: 'bg-green-50',
          message: 'Aplicación lista',
          description: 'Todos los datos han sido cargados'
        };
      case AppStateStatus.ERROR:
        return {
          icon: CircleAlert,
          color: 'text-red-600',
          bgColor: 'bg-red-50',
          message: 'Error encontrado',
          description: 'Se han detectado problemas durante la carga'
        };
      case AppStateStatus.OFFLINE:
        return {
          icon: WifiOff,
          color: 'text-gray-600',
          bgColor: 'bg-gray-50',
          message: 'Sin conexión',
          description: 'Modo offline activado'
        };
      default:
        return {
          icon: Loader2,
          color: 'text-gray-600',
          bgColor: 'bg-gray-50',
          message: 'Estado desconocido',
          description: 'Verificando estado de la aplicación'
        };
    }
  };

  const statusInfo = getStatusInfo();
  const StatusIcon = statusInfo.icon;

  // Calcular progreso general
  const calculateProgress = () => {
    const modules = ['dashboard', 'animal', 'user'] as const;
    const completed = modules.filter(module => moduleProgress[module]).length;
    return Math.round((completed / modules.length) * 100);
  };

  const progress = calculateProgress();

  // Formatear tiempo desde la última actualización
  const formatTimeSinceUpdate = () => {
    if (!lastUpdate) return 'Nunca';
    
    const seconds = Math.floor((Date.now() - lastUpdate) / 1000);
    
    if (seconds < 60) return `Hace ${seconds}s`;
    if (seconds < 3600) return `Hace ${Math.floor(seconds / 60)}min`;
    if (seconds < 86400) return `Hace ${Math.floor(seconds / 3600)}h`;
    return `Hace ${Math.floor(seconds / 86400)}d`;
  };

  // Variante compacta: barra de progreso horizontal con iconos
  if (variant === 'compact') {
    return (
      <Card className={`w-full ${className}`}>
        <CardContent className="p-4">
          <div className="flex items-center space-x-4">
            {/* Icono de estado */}
            <div className={`flex-shrink-0 w-10 h-10 rounded-full ${statusInfo.bgColor} flex items-center justify-center`}>
              <StatusIcon className={`w-5 h-5 ${statusInfo.color} ${status === AppStateStatus.LOADING_DASHBOARD || status === AppStateStatus.LOADING_MODULES ? 'animate-spin' : ''}`} />
            </div>
            
            {/* Información de estado */}
            <div className="flex-1 min-w-0">
              <div className="flex items-center justify-between">
                <p className="text-sm font-medium text-gray-900 truncate">
                  {statusInfo.message}
                </p>
                <div className="flex items-center space-x-2 ml-2">
                  {/* Indicador de conexión */}
                  <div className="flex items-center">
                    {isOnline ? (
                      <Wifi className="w-4 h-4 text-green-500" />
                    ) : (
                      <WifiOff className="w-4 h-4 text-gray-400" />
                    )}
                  </div>
                  
                  {/* Badge de progreso */}
                  <Badge variant={status === AppStateStatus.READY ? 'default' : 'secondary'}>
                    {progress}%
                  </Badge>
                </div>
              </div>
              
              {/* Barra de progreso */}
              <Progress value={progress} className="mt-2 h-2" />
              
              {/* Indicadores de módulos */}
              <div className="flex items-center space-x-4 mt-2">
                <div className="flex items-center text-xs text-gray-500">
                  <Database className="w-3 h-3 mr-1" />
                  Dashboard: {moduleProgress.dashboard ? '✓' : '○'}
                </div>
                <div className="flex items-center text-xs text-gray-500">
                  <PawPrint className="w-3 h-3 mr-1" />
                  Animales: {moduleProgress.animal ? '✓' : '○'}
                </div>
                <div className="flex items-center text-xs text-gray-500">
                  <Users className="w-3 h-3 mr-1" />
                  Usuarios: {moduleProgress.user ? '✓' : '○'}
                </div>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  // Variante completa: tarjeta detallada con toda la información
  if (variant === 'full') {
    return (
      <Card className={`w-full ${className}`}>
        <CardContent className="p-6">
          <div className="flex items-start space-x-4">
            {/* Icono de estado grande */}
            <div className={`flex-shrink-0 w-16 h-16 rounded-full ${statusInfo.bgColor} flex items-center justify-center`}>
              <StatusIcon className={`w-8 h-8 ${statusInfo.color} ${status === AppStateStatus.LOADING_DASHBOARD || status === AppStateStatus.LOADING_MODULES ? 'animate-spin' : ''}`} />
            </div>
            
            {/* Información detallada */}
            <div className="flex-1">
              <h3 className="text-lg font-medium text-gray-900">
                {statusInfo.message}
              </h3>
              <p className="text-sm text-gray-600 mt-1">
                {statusInfo.description}
              </p>
              
              {/* Progreso general */}
              <div className="mt-4">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-sm font-medium text-gray-700">Progreso general</span>
                  <span className="text-sm text-gray-500">{progress}%</span>
                </div>
                <Progress value={progress} className="h-3" />
              </div>
              
              {/* Estado de módulos */}
              <div className="mt-4 grid grid-cols-3 gap-4">
                <div className={`text-center p-3 rounded-lg ${moduleProgress.dashboard ? 'bg-green-50' : 'bg-gray-50'}`}>
                  <Database className={`w-6 h-6 mx-auto mb-1 ${moduleProgress.dashboard ? 'text-green-600' : 'text-gray-400'}`} />
                  <p className="text-xs font-medium">Dashboard</p>
                  <p className="text-xs text-gray-500">
                    {moduleProgress.dashboard ? 'Completado' : 'Cargando...'}
                  </p>
                </div>
                
                <div className={`text-center p-3 rounded-lg ${moduleProgress.animal ? 'bg-green-50' : 'bg-gray-50'}`}>
                  <PawPrint className={`w-6 h-6 mx-auto mb-1 ${moduleProgress.animal ? 'text-green-600' : 'text-gray-400'}`} />
                  <p className="text-xs font-medium">Animales</p>
                  <p className="text-xs text-gray-500">
                    {moduleProgress.animal ? 'Completado' : 'Cargando...'}
                  </p>
                </div>
                
                <div className={`text-center p-3 rounded-lg ${moduleProgress.user ? 'bg-green-50' : 'bg-gray-50'}`}>
                  <Users className={`w-6 h-6 mx-auto mb-1 ${moduleProgress.user ? 'text-green-600' : 'text-gray-400'}`} />
                  <p className="text-xs font-medium">Usuarios</p>
                  <p className="text-xs text-gray-500">
                    {moduleProgress.user ? 'Completado' : 'Cargando...'}
                  </p>
                </div>
              </div>
              
              {/* Información adicional */}
              <div className="mt-4 flex items-center justify-between text-xs text-gray-500">
                <div className="flex items-center space-x-4">
                  <span className="flex items-center">
                    {isOnline ? (
                      <>
                        <Wifi className="w-3 h-3 mr-1 text-green-500" />
                        Conectado
                      </>
                    ) : (
                      <>
                        <WifiOff className="w-3 h-3 mr-1 text-gray-400" />
                        Sin conexión
                      </>
                    )}
                  </span>
                  <span>
                    Última actualización: {formatTimeSinceUpdate()}
                  </span>
                </div>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  // Variante minimalista: solo iconos y estado básico
  return (
    <div className={`flex items-center space-x-3 ${className}`}>
      {/* Icono de estado */}
      <div className={`flex-shrink-0 w-8 h-8 rounded-full ${statusInfo.bgColor} flex items-center justify-center`}>
        <StatusIcon className={`w-4 h-4 ${statusInfo.color} ${status === AppStateStatus.LOADING_DASHBOARD || status === AppStateStatus.LOADING_MODULES ? 'animate-spin' : ''}`} />
      </div>
      
      {/* Mensaje de estado */}
      <div className="flex-1 min-w-0">
        <p className="text-sm font-medium text-gray-900 truncate">
          {statusInfo.message}
        </p>
        <p className="text-xs text-gray-500">
          {progress}% completado
        </p>
      </div>
      
      {/* Indicador de conexión */}
      <div className="flex-shrink-0">
        {isOnline ? (
          <Wifi className="w-4 h-4 text-green-500" />
        ) : (
          <WifiOff className="w-4 h-4 text-gray-400" />
        )}
      </div>
    </div>
  );
};

/**
 * Componente para indicador flotante de estado
 * Ideal para mostrar en la esquina inferior derecha de la pantalla
 */
export const FloatingStatusIndicator: React.FC<{
  status: AppStateStatus;
  moduleProgress: {
    dashboard: boolean;
    animal: boolean;
    user: boolean;
  };
  isOnline: boolean;
  onClick?: () => void;
}> = ({ status, moduleProgress, onClick }) => {
  const getStatusColor = () => {
    switch (status) {
      case AppStateStatus.READY:
        return 'bg-green-500';
      case AppStateStatus.ERROR:
        return 'bg-red-500';
      case AppStateStatus.OFFLINE:
        return 'bg-gray-500';
      default:
        return 'bg-blue-500';
    }
  };

  const calculateProgress = () => {
    const modules = ['dashboard', 'animal', 'user'] as const;
    const completed = modules.filter(module => moduleProgress[module]).length;
    return Math.round((completed / modules.length) * 100);
  };

  const progress = calculateProgress();

  return (
    <div
      className={`fixed bottom-4 right-4 w-12 h-12 rounded-full ${getStatusColor()} text-white flex items-center justify-center cursor-pointer shadow-lg hover:shadow-xl transition-shadow z-50`}
      onClick={onClick}
    >
      {status === AppStateStatus.LOADING_DASHBOARD || status === AppStateStatus.LOADING_MODULES ? (
        <Loader2 className="w-6 h-6 animate-spin" />
      ) : (
        <span className="text-sm font-bold">{progress}%</span>
      )}
    </div>
  );
};

