export default PreloadIndicators;

import React, { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { controlService } from '@/entities/control/api/control.service';
import { treatmentsService } from '@/entities/treatment/api/treatments.service';
import { Modal, ModalContent, ModalHeader, ModalBody } from '@/shared/ui/common/UnifiedModal';
import { CheckCircleIcon, XMarkIcon } from '@heroicons/react/24/outline';

/**
 * Modal de acción rápida: detecta el tipo de alerta y muestra el formulario mínimo
 * para resolverla sin salir de la pantalla actual.
 */

export interface QuickActionAlert {
  db_id?: number;
  animal_id?: number;
  animal_record?: string;
  type?: string;   // Salud | Reproducción | Crecimiento | Estado
  message?: string;
  priority?: string;
}

interface Props {
  alert: QuickActionAlert | null;
  onClose: () => void;
  onSuccess?: () => void;
}

// ─── Detección de acción recomendada ─────────────────────────────────────────

type ActionType = 'control' | 'treatment' | 'none';

function detectAction(alert: QuickActionAlert): { action: ActionType; suggestion: string } {
  const msg = (alert.message ?? '').toLowerCase();
  const type = (alert.type ?? '').toLowerCase();

  if (
    msg.includes('control sanitario') ||
    msg.includes('control veterinario') ||
    msg.includes('sin control') ||
    msg.includes('control de salud') ||
    msg.includes('control de 1er') ||
    msg.includes('control de 2do') ||
    msg.includes('control de 3er') ||
    msg.includes('peso')
  ) {
    return { action: 'control', suggestion: 'Registrar control veterinario' };
  }
  if (
    msg.includes('vacunación') ||
    msg.includes('vacuna') ||
    msg.includes('ica') ||
    msg.includes('aftosa') ||
    msg.includes('desparasit') ||
    msg.includes('antiparasit') ||
    msg.includes('tratamiento') ||
    msg.includes('medicament') ||
    msg.includes('mineral') ||
    msg.includes('vitamina') ||
    type === 'salud'
  ) {
    return { action: 'treatment', suggestion: 'Registrar tratamiento / vacunación' };
  }
  return { action: 'none', suggestion: '' };
}

function suggestDescription(alert: QuickActionAlert): string {
  const msg = (alert.message ?? '').toLowerCase();
  if (msg.includes('aftosa') || msg.includes('brucelosis') || msg.includes('ica')) return 'Vacunación Aftosa y Brucelosis ICA';
  if (msg.includes('desparasit') || msg.includes('ivermectin')) return 'Desparasitación con Ivermectina 1%';
  if (msg.includes('mineral') || msg.includes('vitamina') || msg.includes('calcio')) return 'Suplementación mineral y vitamínica';
  if (msg.includes('ibr') || msg.includes('dvb')) return 'Vacunación IBR/DVB';
  if (msg.includes('clostridial')) return 'Vacunación Clostridial 8 vías';
  if (msg.includes('rabia')) return 'Vacunación antirrábica bovina';
  if (msg.includes('antibiótico') || msg.includes('florfenicol') || msg.includes('oxitetraciclina')) return 'Tratamiento antibiótico';
  return '';
}

// ─── Formulario de Control rápido ────────────────────────────────────────────

const HEALTH_OPTIONS = ['Excelente', 'Bueno', 'Regular', 'Malo', 'Sano'] as const;

function QuickControlForm({
  animalId,
  animalRecord,
  onSuccess,
}: {
  animalId: number;
  animalRecord: string;
  onSuccess: () => void;
}) {
  const [healthStatus, setHealthStatus] = useState<string>('Bueno');
  const [weight, setWeight] = useState('');
  const [description, setDescription] = useState('');
  const [done, setDone] = useState(false);
  const qc = useQueryClient();

  const mutation = useMutation({
    mutationFn: () =>
      controlService.createControl({
        animal_id: animalId,
        checkup_date: new Date().toISOString().split('T')[0],
        health_status: healthStatus,
        weight: weight ? Number(weight) : undefined,
        description: description || `Control veterinario rutinario`,
      } as any),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['controls'] });
      qc.invalidateQueries({ queryKey: ['upcoming-events'] });
      qc.invalidateQueries({ queryKey: ['alerts'] });
      setDone(true);
      setTimeout(onSuccess, 1200);
    },
  });

  if (done) {
    return (
      <div className="flex flex-col items-center py-8 gap-3">
        <CheckCircleIcon className="w-12 h-12 text-green-500" />
        <p className="font-bold text-green-700">¡Control registrado para {animalRecord}!</p>
      </div>
    );
  }

  return (
    <div className="space-y-4 p-1">
      <div>
        <label className="text-xs font-semibold text-text-secondary uppercase tracking-wide">Estado de Salud *</label>
        <div className="flex flex-wrap gap-2 mt-1.5">
          {HEALTH_OPTIONS.map(opt => (
            <button
              key={opt}
              type="button"
              onClick={() => setHealthStatus(opt)}
              className={`px-3 py-1.5 rounded-lg text-sm font-medium border transition-all ${
                healthStatus === opt
                  ? 'bg-primary text-white border-primary'
                  : 'bg-surface border-border text-text-secondary hover:border-primary/50'
              }`}
            >
              {opt}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-2 gap-3">
        <div>
          <label className="text-xs font-semibold text-text-secondary uppercase tracking-wide">Peso (kg)</label>
          <input
            type="number"
            value={weight}
            onChange={e => setWeight(e.target.value)}
            placeholder="ej: 450"
            className="mt-1.5 w-full px-3 py-2 rounded-lg border border-border bg-surface text-sm focus:outline-none focus:ring-2 focus:ring-primary/30"
          />
        </div>
        <div>
          <label className="text-xs font-semibold text-text-secondary uppercase tracking-wide">Fecha</label>
          <input
            type="text"
            value={new Date().toLocaleDateString('es-CO')}
            readOnly
            className="mt-1.5 w-full px-3 py-2 rounded-lg border border-border bg-border/20 text-sm text-text-secondary"
          />
        </div>
      </div>

      <div>
        <label className="text-xs font-semibold text-text-secondary uppercase tracking-wide">Observaciones</label>
        <textarea
          value={description}
          onChange={e => setDescription(e.target.value)}
          placeholder="Observaciones del control..."
          rows={2}
          className="mt-1.5 w-full px-3 py-2 rounded-lg border border-border bg-surface text-sm focus:outline-none focus:ring-2 focus:ring-primary/30 resize-none"
        />
      </div>

      {mutation.isError && (
        <p className="text-xs text-red-600">Error al guardar. Intente de nuevo.</p>
      )}

      <button
        onClick={() => mutation.mutate()}
        disabled={mutation.isPending}
        className="w-full py-2.5 bg-primary text-white font-bold rounded-xl hover:bg-primary/90 disabled:opacity-50 transition-all"
      >
        {mutation.isPending ? 'Guardando...' : `✓ Registrar Control — ${animalRecord}`}
      </button>
    </div>
  );
}

// ─── Formulario de Tratamiento rápido ────────────────────────────────────────

function QuickTreatmentForm({
  animalId,
  animalRecord,
  suggestionDesc,
  onSuccess,
}: {
  animalId: number;
  animalRecord: string;
  suggestionDesc: string;
  onSuccess: () => void;
}) {
  const [description, setDescription] = useState(suggestionDesc);
  const [dosis, setDosis] = useState('');
  const [frequency, setFrequency] = useState('Única');
  const [observations, setObservations] = useState('');
  const [done, setDone] = useState(false);
  const qc = useQueryClient();

  const mutation = useMutation({
    mutationFn: () =>
      treatmentsService.createTreatment({
        animal_id: animalId,
        treatment_date: new Date().toISOString().split('T')[0],
        description,
        dosis: dosis || 'Ver indicaciones del producto',
        frequency,
        observations,
      } as any),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['treatments'] });
      qc.invalidateQueries({ queryKey: ['upcoming-events'] });
      qc.invalidateQueries({ queryKey: ['alerts'] });
      setDone(true);
      setTimeout(onSuccess, 1200);
    },
  });

  if (done) {
    return (
      <div className="flex flex-col items-center py-8 gap-3">
        <CheckCircleIcon className="w-12 h-12 text-green-500" />
        <p className="font-bold text-green-700">¡Tratamiento registrado para {animalRecord}!</p>
      </div>
    );
  }

  const FREQ_OPTIONS = ['Única', 'Diaria', 'Cada 48h', 'Cada 72h', 'Semanal', 'Mensual', 'Cada 3 meses', 'Cada 6 meses'];

  return (
    <div className="space-y-4 p-1">
      <div>
        <label className="text-xs font-semibold text-text-secondary uppercase tracking-wide">Descripción / Medicamento *</label>
        <input
          type="text"
          value={description}
          onChange={e => setDescription(e.target.value)}
          placeholder="ej: Vacunación Aftosa ICA, Ivermectina 1%..."
          className="mt-1.5 w-full px-3 py-2 rounded-lg border border-border bg-surface text-sm focus:outline-none focus:ring-2 focus:ring-primary/30"
        />
      </div>

      <div className="grid grid-cols-2 gap-3">
        <div>
          <label className="text-xs font-semibold text-text-secondary uppercase tracking-wide">Dosis</label>
          <input
            type="text"
            value={dosis}
            onChange={e => setDosis(e.target.value)}
            placeholder="ej: 2ml IM"
            className="mt-1.5 w-full px-3 py-2 rounded-lg border border-border bg-surface text-sm focus:outline-none focus:ring-2 focus:ring-primary/30"
          />
        </div>
        <div>
          <label className="text-xs font-semibold text-text-secondary uppercase tracking-wide">Frecuencia</label>
          <select
            value={frequency}
            onChange={e => setFrequency(e.target.value)}
            className="mt-1.5 w-full px-3 py-2 rounded-lg border border-border bg-surface text-sm focus:outline-none focus:ring-2 focus:ring-primary/30"
          >
            {FREQ_OPTIONS.map(f => <option key={f}>{f}</option>)}
          </select>
        </div>
      </div>

      <div>
        <label className="text-xs font-semibold text-text-secondary uppercase tracking-wide">Observaciones</label>
        <textarea
          value={observations}
          onChange={e => setObservations(e.target.value)}
          placeholder="Notas adicionales..."
          rows={2}
          className="mt-1.5 w-full px-3 py-2 rounded-lg border border-border bg-surface text-sm focus:outline-none focus:ring-2 focus:ring-primary/30 resize-none"
        />
      </div>

      {mutation.isError && (
        <p className="text-xs text-red-600">Error al guardar. Intente de nuevo.</p>
      )}

      <button
        onClick={() => mutation.mutate()}
        disabled={mutation.isPending || !description.trim()}
        className="w-full py-2.5 bg-primary text-white font-bold rounded-xl hover:bg-primary/90 disabled:opacity-50 transition-all"
      >
        {mutation.isPending ? 'Guardando...' : `✓ Registrar Tratamiento — ${animalRecord}`}
      </button>
    </div>
  );
}

// ─── Modal principal ──────────────────────────────────────────────────────────

const QuickActionModal: React.FC<Props> = ({ alert, onClose, onSuccess }) => {
  if (!alert) return null;

  const { action, suggestion } = detectAction(alert);
  const animalId     = alert.animal_id ?? 0;
  const animalRecord = alert.animal_record ?? `Animal ${animalId}`;

  const handleSuccess = () => {
    onSuccess?.();
    onClose();
  };

  const priorityColors: Record<string, string> = {
    crítica: 'bg-red-100 text-red-700',
    alta:    'bg-orange-100 text-orange-700',
    media:   'bg-yellow-100 text-yellow-700',
    baja:    'bg-blue-100 text-blue-700',
  };
  const prioKey = (alert.priority ?? '').toLowerCase();
  const prioBg  = priorityColors[prioKey] ?? priorityColors.media;

  return (
    <Modal isOpen onClose={onClose} size="lg">
      <ModalContent>
        <ModalHeader>
          <div className="flex items-center gap-2 flex-wrap">
            <span className="font-bold">⚡ Acción Rápida</span>
            <span className={`px-2 py-0.5 text-xs font-bold rounded-full ${prioBg}`}>
              {alert.priority}
            </span>
            <span className="text-sm text-text-secondary font-normal">— {animalRecord}</span>
          </div>
        </ModalHeader>
        <ModalBody>
          {/* Alerta original */}
          <div className="mb-4 p-3 rounded-xl bg-border/20 border border-border">
            <p className="text-xs font-semibold text-text-secondary uppercase tracking-wide mb-1">Alerta</p>
            <p className="text-sm text-text-primary">{alert.message}</p>
          </div>

          {action === 'none' ? (
            <div className="text-center py-6">
              <p className="text-text-secondary text-sm">
                Esta alerta no tiene una acción rápida disponible.
              </p>
              <p className="text-text-secondary text-xs mt-1">
                Ve a la sección correspondiente para gestionarla.
              </p>
            </div>
          ) : (
            <>
              <p className="text-sm font-semibold text-text-primary mb-3">
                📝 {suggestion}
              </p>
              {action === 'control' ? (
                <QuickControlForm
                  animalId={animalId}
                  animalRecord={animalRecord}
                  onSuccess={handleSuccess}
                />
              ) : (
                <QuickTreatmentForm
                  animalId={animalId}
                  animalRecord={animalRecord}
                  suggestionDesc={suggestDescription(alert)}
                  onSuccess={handleSuccess}
                />
              )}
            </>
          )}
        </ModalBody>
      </ModalContent>
    </Modal>
  );
};

export default QuickActionModal;

import React, { useState, useEffect } from 'react';
import { Card, CardContent } from '@/shared/ui/card';
import { TrendingUp, TrendingDown, Activity, Users, Package, AlertTriangle } from 'lucide-react';
import { reproductionService } from '@/entities/reproduction/api/reproduction.service';
import { useToast } from '@/app/providers/ToastContext';

interface QuickStat {
  label: string;
  value: string | number;
  trend: 'up' | 'down' | 'neutral';
  icon: React.ReactNode;
  color: string;
}

export default function QuickStats() {
  const { showToast } = useToast();
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState<QuickStat[]>([]);

  const loadStats = async () => {
    setLoading(true);
    try {
      const response = await reproductionService.getSummary();
      const data = response as any;

      const quickStats: QuickStat[] = [
        {
          label: 'Total Animales',
          value: data.total_females || 0,
          trend: 'neutral',
          icon: <Users className="h-4 w-4" />,
          color: 'text-blue-500',
        },
        {
          label: 'Preñeces Activas',
          value: data.active_pregnancies || 0,
          trend: 'up',
          icon: <Activity className="h-4 w-4" />,
          color: 'text-green-500',
        },
        {
          label: 'Partos Pendientes',
          value: data.births_next_30_days || 0,
          trend: 'neutral',
          icon: <Package className="h-4 w-4" />,
          color: 'text-orange-500',
        },
        {
          label: 'Partos Atrasados',
          value: data.overdue_births || 0,
          trend: data.overdue_births > 0 ? 'down' : 'neutral',
          icon: <AlertTriangle className="h-4 w-4" />,
          color: data.overdue_births > 0 ? 'text-red-500' : 'text-gray-500',
        },
      ];

      setStats(quickStats);
    } catch (error) {
      console.error('Error loading quick stats:', error);
      // Fallback stats
      setStats([
        {
          label: 'Total Animales',
          value: '---',
          trend: 'neutral',
          icon: <Users className="h-4 w-4" />,
          color: 'text-gray-500',
        },
        {
          label: 'Preñeces Activas',
          value: '---',
          trend: 'neutral',
          icon: <Activity className="h-4 w-4" />,
          color: 'text-gray-500',
        },
        {
          label: 'Partos Pendientes',
          value: '---',
          trend: 'neutral',
          icon: <Package className="h-4 w-4" />,
          color: 'text-gray-500',
        },
        {
          label: 'Partos Atrasados',
          value: '---',
          trend: 'neutral',
          icon: <AlertTriangle className="h-4 w-4" />,
          color: 'text-gray-500',
        },
      ]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadStats();
  }, []);

  if (loading) {
    return (
      <div className="space-y-2">
        {[1, 2, 3, 4].map(i => (
          <div key={i} className="h-12 bg-gray-700 rounded animate-pulse" />
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-2">
      <div className="px-3 py-2 text-sm font-medium text-gray-400">
        Estadísticas Rápidas
      </div>
      {stats.map((stat, index) => (
        <Card key={index} className="bg-gray-700 border-gray-600">
          <CardContent className="p-3">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <div className={stat.color}>{stat.icon}</div>
                <div>
                  <p className="text-xs text-gray-400">{stat.label}</p>
                  <p className="text-lg font-bold text-white">{stat.value}</p>
                </div>
              </div>
              {stat.trend === 'up' && (
                <TrendingUp className="h-4 w-4 text-green-500" />
              )}
              {stat.trend === 'down' && (
                <TrendingDown className="h-4 w-4 text-red-500" />
              )}
            </div>
          </CardContent>
        </Card>
      ))}
    </div>
  );
}

import React, { useState } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/shared/ui/card';
import { Button } from '@/shared/ui/button';
import { Badge } from '@/shared/ui/badge';
import { 
  FileText, 
  Download, 
  ClipboardList, 
  RefreshCw, 
  CircleCheck,
  CircleAlert,
  FileDown,
  ShieldCheck
} from 'lucide-react';
import { useToast } from '@/app/providers/ToastContext';
import { apiFetch } from '@/shared/api/apiFetch';
import { useT } from '@/shared/i18n';
import { motion } from 'framer-motion';
import { cn } from '@/shared/ui/cn';

const RegulatoryReportsWidget: React.FC = () => {
  const t = useT();
  const { showToast } = useToast();
  const [loading, setLoading] = useState<string | null>(null);

  const downloadReport = async (type: 'inventory' | 'movements' | 'health', format: 'pdf' | 'csv') => {
    setLoading(`${type}-${format}`);
    try {
      const response = await apiFetch({
        url: `/regulatory-reports/${type}`,
        method: 'GET',
        params: { format },
        responseType: 'blob'
      } as any);

      const url = window.URL.createObjectURL(new Blob([response as any]));
      const link = document.createElement('a');
      link.href = url;
      const date = new Date().toISOString().split('T')[0];
      link.setAttribute('download', `reporte_${type}_${date}.${format}`);
      document.body.appendChild(link);
      link.click();
      link.remove();
      
      showToast('Reporte generado exitosamente', 'success');
    } catch (error) {
      console.error('Error downloading report:', error);
      showToast('Error al generar el reporte', 'error');
    } finally {
      setLoading(null);
    }
  };

  const reports = [
    {
      id: 'inventory',
      title: 'Inventario de Ganado',
      description: 'Listado completo de animales activos, edades y ubicación.',
      icon: <ClipboardList className="h-6 w-6" />,
      gradient: 'from-blue-500/10 to-blue-600/5',
      iconColor: 'text-blue-500',
      formats: ['pdf', 'csv'] as const,
    },
    {
      id: 'movements',
      title: 'Trazabilidad',
      description: 'Historial de nacimientos, muertes y ventas en el periodo.',
      icon: <RefreshCw className="h-6 w-6" />,
      gradient: 'from-orange-500/10 to-orange-600/5',
      iconColor: 'text-orange-500',
      formats: ['pdf', 'csv'] as const,
    },
    {
      id: 'health',
      title: 'Sanidad y Vacunas',
      description: 'Registros de vacunación, tratamientos y controles.',
      icon: <FileText className="h-6 w-6" />,
      gradient: 'from-emerald-500/10 to-emerald-600/5',
      iconColor: 'text-emerald-500',
      formats: ['pdf', 'csv'] as const,
    },
    {
      id: 'production',
      title: 'Producción',
      description: 'Peso, rendimiento y productividad por periodo.',
      icon: <ShieldCheck className="h-6 w-6" />,
      gradient: 'from-violet-500/10 to-violet-600/5',
      iconColor: 'text-violet-500',
      formats: ['pdf', 'csv'] as const,
    },
    {
      id: 'reproduction',
      title: 'Reproducción',
      description: 'Montas, preñeces, partos y eventos reproductivos.',
      icon: <ClipboardList className="h-6 w-6" />,
      gradient: 'from-pink-500/10 to-pink-600/5',
      iconColor: 'text-pink-500',
      formats: ['pdf', 'csv'] as const,
    }
  ];

  return (
    <Card className="border-none shadow-2xl shadow-primary/5 bg-card/40 backdrop-blur-xl rounded-[2.5rem] overflow-hidden">
      <CardHeader className="p-8 border-b border-white/5 bg-gradient-to-r from-primary/5 to-transparent">
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <div className="h-12 w-12 rounded-2xl bg-primary/10 flex items-center justify-center border border-primary/20">
              <FileDown className="h-6 w-6 text-primary" />
            </div>
            <div>
              <CardTitle className="text-2xl font-black tracking-tighter">
                Módulo de Cumplimiento
              </CardTitle>
              <CardDescription className="font-bold uppercase tracking-widest text-[9px] opacity-60">
                Reportes Oficiales ICA / SENA
              </CardDescription>
            </div>
          </div>
          <Badge className="bg-emerald-500/10 text-emerald-500 border-emerald-500/20 font-black uppercase tracking-widest text-[10px] h-8 px-4">
            Normativa Certificada
          </Badge>
        </div>
      </CardHeader>
      
      <CardContent className="p-8 space-y-8">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {reports.map((report) => (
            <motion.div 
              key={report.id}
              whileHover={{ translateY: -5 }}
              className={cn(
                "group relative p-6 rounded-[2rem] border border-white/5 bg-gradient-to-br transition-all duration-300",
                report.gradient
              )}
            >
              <div className="flex flex-col gap-4">
                <div className={cn(
                  "h-12 w-12 rounded-2xl flex items-center justify-center bg-card shadow-sm group-hover:scale-110 transition-transform",
                  report.iconColor
                )}>
                  {report.icon}
                </div>
                <div>
                  <h3 className="font-black text-lg tracking-tight mb-1">{report.title}</h3>
                  <p className="text-xs text-muted-foreground leading-relaxed">
                    {report.description}
                  </p>
                </div>
              </div>

              <div className="flex gap-2 mt-6">
                {report.formats.map((format) => (
                  <Button
                    key={format}
                    variant="secondary"
                    className="h-10 flex-1 rounded-xl font-black uppercase tracking-widest text-[10px] gap-2 border border-white/5 hover:bg-primary hover:text-white transition-all"
                    disabled={!!loading}
                    onClick={() => downloadReport(report.id as any, format)}
                  >
                    {loading === `${report.id}-${format}` ? (
                      <RefreshCw className="h-3.5 w-3.5 animate-spin" />
                    ) : (
                      <Download className="h-3.5 w-3.5" />
                    )}
                    {format}
                  </Button>
                ))}
              </div>

              <div className="absolute top-4 right-4">
                <ShieldCheck className="h-4 w-4 text-primary/30" />
              </div>
            </motion.div>
          ))}
        </div>

        <div className="relative p-6 rounded-[2rem] bg-amber-500/5 border border-amber-500/10 overflow-hidden">
          <div className="flex items-start gap-4 relative z-10">
            <div className="h-10 w-10 rounded-xl bg-amber-500/10 flex items-center justify-center shrink-0">
              <CircleAlert className="h-5 w-5 text-amber-500" />
            </div>
            <div>
              <p className="text-[10px] font-black uppercase tracking-[0.2em] text-amber-600 mb-1">Nota Técnica Importante</p>
              <p className="text-xs text-amber-700/80 leading-relaxed font-medium">
                Estos reportes están diseñados para cumplir con los requerimientos técnicos del ICA. 
                Asegúrese de validar la <strong>trazabilidad completa</strong> y los <strong>registros de vacunación</strong> antes de proceder con el reporte final.
              </p>
            </div>
          </div>
          {/* Decorative blur */}
          <div className="absolute -bottom-10 -right-10 h-32 w-32 bg-amber-500/10 rounded-full blur-3xl" />
        </div>
      </CardContent>
    </Card>
  );
};

export default RegulatoryReportsWidget;

import React, { useMemo, useState, useRef, useEffect } from 'react';
import { cn } from '@/shared/ui/cn';
import { useAuth } from '@/features/auth/model/useAuth';
import { sidebarItems, type Role as SidebarRole } from '@/widgets/dashboard/sidebarConfig';
import { Link, useLocation } from 'react-router-dom';
import { Loader } from '@/shared/ui/Loader';
import { normalizeRole } from '@/features/auth/api/auth.service';
import { ChevronDown, ChevronUp, X, LogOut } from 'lucide-react';
import Button from '@/shared/ui/button';
import Badge from '@/shared/ui/badge';
import ThemeToggle from './ThemeToggle';
import { membershipService } from '@/entities/user/api/membership.service';
import { subscribeSSE } from '@/lib/events';

interface SidebarProps {
  isSidebarOpen: boolean;
  setIsSidebarOpen: React.Dispatch<React.SetStateAction<boolean>>; // Cambiar a un tipo que tu hook useAuth devuelve para el usuario
}

const RoleBasedSideBar: React.FC<SidebarProps> = ({ isSidebarOpen, setIsSidebarOpen }) => {
  const { user, role, loading, isAuthenticated, checkAuthStatus, logout: signOut } = useAuth() as any;
  const location = useLocation();
  const [pendingMemberships, setPendingMemberships] = useState(0);

  // Preferir el rol del contexto y, si no existe, usar el del usuario
  const rawRole = role ?? (user as any)?.role ?? null;
  const currentRole = useMemo(() => {
    const norm = (normalizeRole as any)?.(rawRole);
    return norm ?? (typeof rawRole === 'string' ? rawRole : null);
  }, [rawRole]);

  const [openGroups, setOpenGroups] = useState<Record<string, boolean>>({});
  const [sidebarWidth] = useState(288); // Ancho fijo en desktop (w-72 = 288px)
  const [isResizing, setIsResizing] = useState(false);
  const sidebarRef = useRef<HTMLElement>(null);
  const resizeRef = useRef<HTMLDivElement>(null);
  const closeBtnRef = useRef<HTMLButtonElement>(null);

  const minWidth = 200;
  const maxWidth = 320;

  useEffect(() => {
    // Exponer ancho a CSS para reservar espacio en desktop desde el layout
    document.documentElement.style.setProperty('--sidebar-width', `${sidebarWidth}px`);
  }, [sidebarWidth]);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isResizing || !sidebarRef.current) return;
      const newWidth = e.clientX;
      if (newWidth >= minWidth && newWidth <= maxWidth) {
        // setSidebarWidth(newWidth); // Deshabilitado: no permitimos redimensionar
      }
    };

    const handleMouseUp = () => {
      setIsResizing(false);
      document.body.classList.remove('resizing-sidebar');
    };

    if (isResizing) {
      document.addEventListener('mousemove', handleMouseMove);
      document.addEventListener('mouseup', handleMouseUp);
      document.body.classList.add('resizing-sidebar');
    }

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      document.body.classList.remove('resizing-sidebar');
    };
  }, [isResizing, minWidth, maxWidth]);

  // En móvil: enfocar el botón de cierre al abrir y permitir cerrar con ESC
  useEffect(() => {
    const isMobile = typeof window !== 'undefined' && window.innerWidth < 1024;
    if (isSidebarOpen && isMobile) {
      closeBtnRef.current?.focus();
    }
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isSidebarOpen && isMobile) {
        setIsSidebarOpen(false);
      }
    };
    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, [isSidebarOpen, setIsSidebarOpen]);

  const handleResizeStart = (e: React.MouseEvent) => {
    e.preventDefault();
    // Deshabilitado: no permitimos iniciar redimensionamiento
    setIsResizing(false);
  };

  const toggleGroup = (title: string) => {
    setOpenGroups(prev => ({ ...prev, [title]: !prev[title] }));
  };

  // Si el usuario está autenticado pero el rol aún no está resuelto (p. ej. tras F5),
  // disparar una revalidación y mostrar un loader temporal en lugar del mensaje de error.
  useEffect(() => {
    if (!loading && isAuthenticated && !currentRole) {
      try {
        void (checkAuthStatus as any)?.({ background: true });
      } catch {
        // no-op
      }
    }
  }, [loading, isAuthenticated, currentRole, checkAuthStatus]);

  // Cargar solicitudes pendientes si es admin
  useEffect(() => {
    if (currentRole === 'Administrador') {
      // Temporalmente deshabilitado hasta que el backend se reinicie
      // membershipService.getPendingCount().then(res => {
      //   setPendingMemberships(res.data?.count || 0);
      // });

      const unsubscribe = subscribeSSE((event) => {
        if (event.event === 'new_membership_request') {
          setPendingMemberships(prev => prev + 1);
        }
      });
      return () => unsubscribe();
    }
  }, [currentRole]);

  const filteredCategories = useMemo(() => {
    if (!currentRole) return [];
    return sidebarItems
      .filter((cat) => (cat.roles as SidebarRole[]).includes(currentRole as SidebarRole))
      .map((cat) => ({
        ...cat,
        children: (cat.children || []).filter((child) => (child.roles as SidebarRole[]).includes(currentRole as SidebarRole))
      }))
      .filter((cat) => (cat.children || []).length > 0);
  }, [currentRole]);

  if (loading) {
    return (
      <div className="h-full w-full flex items-center justify-center bg-card text-foreground">
        <Loader />
        <span className="ml-2 text-sm">Cargando menú...</span>
      </div>
    );
  }

  if (!currentRole) {
    if (!isAuthenticated) {
      return (
        <div className="h-full w-full flex items-center justify-center bg-card">
          <span className="text-muted-foreground text-sm">Inicia sesión para acceder al menú.</span>
        </div>
      );
    }
    return (
      <div className="h-full w-full flex items-center justify-center bg-card text-foreground">
        <Loader />
        <span className="ml-2 text-sm">Validando sesión y cargando menú...</span>
      </div>
    );
  }

  const getRolePrefix = (r: string): string => {
    switch (r) {
      case 'Administrador':
      case 'Propietario':
      case 'Capataz':
        return '/admin';
      case 'Instructor':
        return '/instructor';
      case 'Veterinario':
        return '/veterinario';
      case 'Aprendiz':
        return '/apprentice';
      case 'Operario':
        return '/operario';
      default:
        return '/';
    }
  };

  const getRoleStyle = (r: string) => {
    switch (r) {
      case 'Administrador': return { bg: 'bg-purple-600', text: 'text-purple-600', border: 'border-purple-200', light: 'bg-purple-50' };
      case 'Propietario': return { bg: 'bg-indigo-600', text: 'text-indigo-600', border: 'border-indigo-200', light: 'bg-indigo-50' };
      case 'Capataz': return { bg: 'bg-blue-600', text: 'text-blue-600', border: 'border-blue-200', light: 'bg-blue-50' };
      case 'Instructor': return { bg: 'bg-emerald-600', text: 'text-emerald-600', border: 'border-emerald-200', light: 'bg-emerald-50' };
      case 'Veterinario': return { bg: 'bg-rose-600', text: 'text-rose-600', border: 'border-rose-200', light: 'bg-rose-50' };
      case 'Aprendiz': return { bg: 'bg-amber-600', text: 'text-amber-600', border: 'border-amber-200', light: 'bg-amber-50' };
      case 'Operario': return { bg: 'bg-slate-600', text: 'text-slate-600', border: 'border-slate-200', light: 'bg-slate-50' };
      default: return { bg: 'bg-primary', text: 'text-primary', border: 'border-border', light: 'bg-surface' };
    }
  };

  const roleStyle = getRoleStyle(currentRole);

  const rolePrefix = getRolePrefix(currentRole);

  const handleItemClick = () => {
    if (typeof window !== 'undefined' && window.innerWidth < 1024) {
      setIsSidebarOpen(false);
    }
  };

  return (
    <>
      <aside
        ref={sidebarRef}
        id="dashboard-sidebar"
        className="h-full w-full bg-card/95 backdrop-blur-xl border-r border-border/50 flex flex-col overflow-hidden shadow-2xl relative"
        role="navigation"
      >
        {/* Branding Decorativo */}
        <div className="p-8 flex flex-col items-center gap-4 relative overflow-hidden border-b border-border/20">
          <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-b from-primary/10 to-transparent opacity-50" />
          
          <div className="w-14 h-14 rounded-3xl bg-gradient-to-br from-primary via-primary/80 to-primary-dark flex items-center justify-center text-white font-black text-xl shadow-2xl shadow-primary/40 rotate-3 ring-4 ring-white/5 relative z-10">
            VL
          </div>
          
          <div className="text-center relative z-10">
            <h2 className="text-base font-black text-foreground tracking-tighter uppercase leading-none mb-1">
              Villa Luz
            </h2>
            <span className="text-[9px] font-bold text-primary tracking-[0.3em] uppercase opacity-70">
              Ecosystem v2.5
            </span>
          </div>
        </div>

        {/* Header del sidebar con diseño premium (Info de Usuario) */}
        <div className="p-5 border-b border-border/40 bg-surface/30 backdrop-blur-md relative z-20">
          <div className="flex items-center justify-between gap-2">
            <Link
              to="/profile"
              onClick={handleItemClick}
              className="flex-1 flex items-center gap-3 group relative z-10 rounded-2xl px-3 py-2.5 transition-all hover:bg-primary/10 border border-transparent hover:border-primary/20 focus:outline-none focus:ring-2 focus:ring-primary/20"
              aria-label="Ir al perfil"
            >
              <div className={`flex h-12 w-12 flex-shrink-0 items-center justify-center rounded-2xl ${roleStyle.bg} text-white shadow-lg shadow-black/10 transform transition-all group-hover:scale-105 group-hover:rotate-3 relative overflow-hidden`}>
                <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity" />
                <span className="font-black text-lg tracking-tighter relative z-10">
                  {(user?.fullname || currentRole || '?').toString().trim().charAt(0).toUpperCase() || '?'}
                </span>
              </div>
              <div className="flex flex-col min-w-0 flex-1">
                <span className="font-black text-sm text-text-primary group-hover:text-primary transition-colors truncate">
                  {user?.fullname || 'Usuario'}
                </span>
                <div className={cn(
                  "mt-1.5 inline-flex items-center self-start px-2 py-0.5 rounded-lg text-[9px] font-black uppercase tracking-widest border",
                  roleStyle.light, roleStyle.text, roleStyle.border
                )}>
                  <div className={cn("w-1.5 h-1.5 rounded-full mr-1.5 animate-pulse", roleStyle.bg)} />
                  {currentRole || 'Rol'}
                </div>
              </div>
            </Link>
            
            <Button
              variant="ghost"
              size="icon"
              className="lg:hidden h-12 w-12 flex-shrink-0 flex flex-col items-center justify-center rounded-2xl bg-muted/40 hover:bg-destructive hover:text-white text-text-secondary transition-all duration-500 shadow-sm active:scale-95 group/close"
              onClick={() => setIsSidebarOpen(false)}
              aria-label="Cerrar menú lateral"
            >
              <X className="h-5 w-5 group-hover/close:rotate-90 transition-transform duration-500" />
              <span className="text-[8px] font-black uppercase mt-0.5 opacity-60 group-hover/close:opacity-100">Cerrar</span>
            </Button>
          </div>
        </div>

        {/* Navegación principal */}
        <nav className="flex-1 min-h-0 overflow-y-auto p-4 space-y-3 relative z-10 scrollbar-none" role="menu">
          {filteredCategories.map((category) => {
            const isOpen = openGroups[category.title] ?? true; // Por defecto abierto para mejor UX
            return (
              <div key={category.title} className="space-y-1">
                <button
                  type="button"
                  onClick={() => toggleGroup(category.title)}
                  className={cn(
                    "w-full flex items-center justify-between py-2.5 px-4 rounded-xl transition-all duration-300 group",
                    isOpen ? "bg-muted/30 text-primary" : "hover:bg-muted/50 text-text-muted hover:text-text-primary"
                  )}
                  aria-expanded={isOpen}
                >
                  <div className="flex items-center gap-3">
                    <span className={cn(
                      "p-2 rounded-lg transition-all duration-300",
                      isOpen ? "bg-primary/20 text-primary scale-110" : "bg-transparent group-hover:bg-muted group-hover:scale-105"
                    )}>
                      {category.icon}
                    </span>
                    <span className="font-bold text-xs uppercase tracking-widest">{category.title}</span>
                  </div>
                  <ChevronDown className={cn(
                    "h-4 w-4 transition-transform duration-500",
                    isOpen ? "rotate-180" : "rotate-0 opacity-50"
                  )} />
                </button>

                <div className={cn(
                  "grid transition-all duration-500 ease-in-out",
                  isOpen ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0 overflow-hidden"
                )}>
                  <div className="overflow-hidden pl-11 pr-1 space-y-1 mt-1">
                    {(category.children || []).map(child => {
                      const fullPath = `${rolePrefix}/${child.path}`;
                      const isActive = location.pathname === fullPath || location.pathname.startsWith(`${fullPath}/`);
                      
                      return (
                        <Link
                          key={`${category.title}-${child.title}-${child.path}`}
                          to={fullPath}
                          onClick={handleItemClick}
                          className={cn(
                            "flex items-center py-2.5 px-3.5 rounded-2xl transition-all duration-300 group relative overflow-hidden",
                            isActive 
                              ? "bg-primary/15 text-primary font-bold shadow-[0_4px_12px_rgba(var(--primary-rgb),0.1)] translate-x-1" 
                              : "text-text-muted hover:bg-muted/50 hover:text-text-primary hover:translate-x-1"
                          )}
                          role="menuitem"
                        >
                          {/* Left accent border for active item */}
                          {isActive && (
                            <div className="absolute left-0 top-2 bottom-2 w-1 bg-primary rounded-full shadow-[0_0_8px_rgba(var(--primary-rgb),0.5)] animate-in fade-in slide-in-from-left-2 duration-500" />
                          )}
                          
                          <div className={cn(
                            "p-2 rounded-xl mr-3 transition-all duration-300",
                            isActive ? "bg-primary/20 text-primary rotate-3 scale-110" : "bg-muted/40 text-text-muted group-hover:bg-muted group-hover:text-primary group-hover:rotate-6"
                          )}>
                            {child.icon}
                          </div>
                          <span className="flex-1 truncate text-[13px] tracking-tight">{child.title}</span>
                          {(child as any).badge && (
                            <Badge 
                              variant={(child as any).badge === 'Admin' ? 'destructive' : 'default'} 
                              className="ml-auto text-[8px] px-1.5 py-0 h-4 min-w-[32px] justify-center font-black tracking-tighter uppercase"
                            >
                              {(child as any).badge}
                            </Badge>
                          )}
                        </Link>
                      );
                    })}
                  </div>
                </div>
              </div>
            );
          })}
        </nav>

        {/* Pie de menú con acciones */}
        <div className="mt-auto border-t border-border/40 bg-surface/50 backdrop-blur-md p-4 space-y-4">
          <div className="flex items-center justify-between gap-3">
            <div className="flex-1 bg-muted/30 p-1 rounded-xl border border-border/30">
              <ThemeToggle />
            </div>
            <button
              type="button"
              onClick={() => signOut?.()}
              className="flex h-11 w-11 items-center justify-center rounded-xl bg-destructive/10 text-destructive hover:bg-destructive hover:text-white transition-all duration-300 group shadow-sm hover:shadow-destructive/20 focus:outline-none focus:ring-2 focus:ring-destructive/50"
              title="Cerrar Sesión"
            >
              <LogOut className="h-5 w-5 transition-transform group-hover:rotate-12" />
            </button>
          </div>
        </div>

        {/* Resizer deshabilitado (oculto) */}
        <div
          ref={resizeRef}
          className="hidden"
          onMouseDown={handleResizeStart}
          aria-hidden="true"
        />
      </aside>
    </>
  );
};

export default RoleBasedSideBar;

import { useEffect, useState } from 'react';
import { securityService } from '@/shared/api';
import { normalizeDisplayValue } from '@/shared/utils/normalization';
import StatisticsCard from './StatisticsCard';
import { Shield, ShieldAlert, ActivitySquare, RefreshCcw } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/shared/ui/card';
import { Separator } from '@/shared/ui/separator';

interface SecurityMetrics {
  vulnerabilities_total?: number;
  vulnerabilities_open?: number;
  vulnerabilities_critical?: number;
  scans_executed?: number;
  last_scan?: string;
  avg_scan_time_ms?: number;
  pending_patches?: number;
  [key: string]: any;
}

interface SecurityAlert {
  id?: number | string;
  title: string;
  message?: string;
  severity?: 'low' | 'medium' | 'high' | 'critical';
  created_at?: string;
  resolved_at?: string;
}

const severityColor: Record<string, string> = {
  low: 'bg-accent text-accent-foreground',
  medium: 'bg-accent text-accent-foreground',
  high: 'bg-accent text-accent-foreground',
  critical: 'bg-destructive text-destructive-foreground'
};

export const SecurityMetricsPanel = () => {
  const [metrics, setMetrics] = useState<SecurityMetrics | null>(null);
  const [alerts, setAlerts] = useState<SecurityAlert[]>([]);
  const [loading, setLoading] = useState(true);
  const [scanning, setScanning] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const load = async () => {
    setLoading(true);
    setError(null);
    try {
      const [m, a] = await Promise.all([
        securityService.getMetrics().catch(()=>({})),
        securityService.getAlerts().catch(()=>[]),
      ]);
      setMetrics(m);
      setAlerts(a);
    } catch (e:any) {
      setError(e?.message || 'Error cargando métricas de seguridad');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  const triggerScan = async () => {
    setScanning(true); setError(null);
    try {
      await securityService.performScan();
      await load();
    } catch(e:any){
      setError(e?.message || 'Error ejecutando escaneo');
    } finally {
      setScanning(false);
    }
  };

  if (loading) {
    return <div className="text-xs text-muted-foreground">Cargando seguridad...</div>;
  }

  return (
    <Card className="border-border">
      <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-3">
        <div>
          <CardTitle className="text-sm font-semibold flex items-center gap-2"><Shield className="h-4 w-4" /> Seguridad</CardTitle>
          <p className="text-[11px] text-muted-foreground">Estado resumido y alertas</p>
        </div>
        <div className="flex items-center gap-2">
          <Button size="sm" variant="outline" onClick={load} disabled={loading || scanning} className="h-7 px-2 text-[11px]"> <RefreshCcw className="h-3 w-3 mr-1" /> Refrescar</Button>
          <Button size="sm" onClick={triggerScan} disabled={scanning} className="h-7 px-2 text-[11px]">{scanning ? 'Escaneando...' : 'Scan'}</Button>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        {error && <div className="text-xs bg-destructive text-destructive-foreground border border-destructive rounded p-2">{error}</div>}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          <StatisticsCard
            title="Vulnerabilidades"
            value={normalizeDisplayValue(metrics?.vulnerabilities_total)}
            description="Totales"
            icon={<ShieldAlert className="h-4 w-4" />}
          />
          <StatisticsCard
            title="Abiertas"
            value={normalizeDisplayValue(metrics?.vulnerabilities_open)}
            description="Sin resolver"
            variant="warning"
          />
          <StatisticsCard
            title="Críticas"
            value={normalizeDisplayValue(metrics?.vulnerabilities_critical)}
            description="Prioridad alta"
            variant="destructive"
          />
          <StatisticsCard
            title="Escaneos"
            value={normalizeDisplayValue(metrics?.scans_executed)}
            description="Ejecutados"
            variant="success"
          />
        </div>
        <Separator />
        <div>
          <h3 className="text-xs font-semibold mb-2 flex items-center gap-1"><ActivitySquare className="h-3.5 w-3.5" /> Alertas recientes</h3>
          <ul className="space-y-2 max-h-56 overflow-auto pr-1">
            {alerts.length ? alerts.slice(0,8).map((al, index) => (
              <li key={al.id || `alert-${index}-${al.title}`} className="p-2 rounded border bg-muted text-[11px]">
                <div className="flex justify-between items-start">
                  <span className="font-medium line-clamp-1">{al.title}</span>
                  {al.severity && <span className={`px-1.5 py-0.5 rounded text-[10px] font-medium ${severityColor[al.severity] || 'bg-muted text-muted-foreground'}`}>{al.severity}</span>}
                </div>
                {al.message && <p className="text-muted-foreground line-clamp-2">{al.message}</p>}
                {al.created_at && <span className="text-[9px] text-muted-foreground mt-1 block">{normalizeDisplayValue(al.created_at)}</span>}
              </li>
            )) : <li key="no-alerts" className="text-[11px] text-muted-foreground">Sin alertas de seguridad</li>}
          </ul>
        </div>
        {metrics?.last_scan && (
          <p className="text-[10px] text-muted-foreground">Último scan: {normalizeDisplayValue(metrics.last_scan)} {metrics.avg_scan_time_ms && `(~${metrics.avg_scan_time_ms} ms)`}</p>
        )}
      </CardContent>
    </Card>
  );
};

export default SecurityMetricsPanel;

