import React from 'react';
import { normalizeDisplayValue } from '@/shared/utils/normalization';
import { Card, CardContent, CardHeader, CardTitle } from '@/shared/ui/card';
import { Progress } from '@/shared/ui/progress';
import { TrendingUp, TrendingDown, Minus } from 'lucide-react';

interface StatisticsCardProps {
  title: string;
  value: string | number;
  description?: string;
  trend?: {
    value: number;
    isPositive: boolean;
  };
  progress?: {
    value: number;
    max: number;
    label?: string;
  };
  icon?: React.ReactNode;
  variant?: 'default' | 'success' | 'warning' | 'destructive';
  color?: string; // Clase CSS para color personalizado
  showGeneticTree?: boolean; // Para funcionalidad específica
  extraClasses?: string; // Futurista: glassmorphism y neon effects
  onClick?: () => void; // Nuevo: soporte de click para navegación / drill-down
}

const StatisticsCard: React.FC<StatisticsCardProps> = ({
  title,
  value,
  description,
  trend,
  progress,
  icon,
  variant = 'default',
  // color y showGeneticTree se mantienen para compatibilidad futura
  extraClasses,
  onClick,
}) => {
  const getVariantStyles = () => {
    switch (variant) {
      case 'success':
        return 'border-green-200 bg-gradient-to-br from-green-50 to-green-100 dark:border-green-800 dark:from-green-950 dark:to-green-900';
      case 'warning':
        return 'border-yellow-200 bg-gradient-to-br from-yellow-50 to-yellow-100 dark:border-yellow-800 dark:from-yellow-950 dark:to-yellow-900';
      case 'destructive':
        return 'border-red-200 bg-gradient-to-br from-red-50 to-red-100 dark:border-red-800 dark:from-red-950 dark:to-red-900';
      default:
        return 'border-border bg-card';
    }
  };

  const getTrendIcon = () => {
    if (!trend) return null;
    if (trend.value > 0) return <TrendingUp className="h-4 w-4 text-green-600" />;
    if (trend.value < 0) return <TrendingDown className="h-4 w-4 text-red-600" />;
    return <Minus className="h-4 w-4 text-gray-600" />;
  };

  const getTrendColor = () => {
    if (!trend) return '';
    if (trend.isPositive && trend.value > 0) return 'text-green-600';
    if (!trend.isPositive && trend.value > 0) return 'text-red-600';
    if (trend.isPositive && trend.value < 0) return 'text-red-600';
    if (!trend.isPositive && trend.value < 0) return 'text-green-600';
    return 'text-gray-600';
  };

  return (
    // Si hay onClick, añadimos cursor-pointer y enfoque accesible
    <Card
      className={`rounded-lg shadow-sm transition-all duration-200 hover:shadow-lg hover:scale-[1.02] ring-1 ring-inset ring-border/50 ${getVariantStyles()} ${onClick ? 'cursor-pointer focus:outline-none focus:ring-2 focus:ring-primary/40' : ''} ${extraClasses ?? ""}`}
      onClick={onClick}
      role={onClick ? 'button' : undefined}
      tabIndex={onClick ? 0 : undefined}
    >
      <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
        <CardTitle className="text-sm font-medium text-muted-foreground">
          {title}
        </CardTitle>
        {icon && (
          <div className="h-4 w-4 text-muted-foreground">
            {icon}
          </div>
        )}
      </CardHeader>
      <CardContent>
        <div className="flex items-center justify-between">
          <div className="text-2xl font-bold">{normalizeDisplayValue(value)}</div>
          {trend && (
            <div className={`flex items-center space-x-1 ${getTrendColor()}`}>
              {getTrendIcon()}
              <span className="text-xs font-medium">
                {Math.abs(trend.value)}%
              </span>
            </div>
          )}
        </div>
        
        {description && (
          <p className="text-xs text-muted-foreground mt-1">
            {description}
          </p>
        )}
        
        {progress && (
          <div className="mt-3 space-y-1">
            <div className="flex justify-between text-xs">
              <span className="text-muted-foreground">
                {progress.label || 'Progreso'}
              </span>
              <span className="font-medium">
                {progress.value}/{progress.max}
              </span>
            </div>
            <Progress 
              value={(progress.value / progress.max) * 100} 
              className="h-2"
            />
          </div>
        )}
      </CardContent>
    </Card>
  );
};

export default StatisticsCard;

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Cloud, CloudOff, RefreshCw, CircleCheck, CircleAlert } from 'lucide-react';
import { cn } from '@/shared/ui/cn';
import { offlineQueue } from '@/shared/api/offline/offlineQueue';

/**
 * SyncProgressIndicator
 * 
 * Componente que muestra el estado de sincronización de la cola offline.
 * Proporciona feedback visual premium sobre cuántos registros están pendientes
 * de enviarse al servidor.
 */
export const SyncProgressIndicator: React.FC = () => {
  const [pendingCount, setPendingCount] = useState(0);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSyncStatus, setLastSyncStatus] = useState<'idle' | 'success' | 'error'>('idle');

  useEffect(() => {
    // Monitorear estado de red
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    // Monitorear cola offline
    const updateCount = () => {
      setPendingCount(offlineQueue.getPendingCount());
    };

    updateCount();
    const interval = setInterval(updateCount, 3000);

    // Escuchar mensajes del Service Worker
    const handleMessage = (event: MessageEvent) => {
      if (event.data?.type === 'OFFLINE_SYNC_SUCCESS') {
        setLastSyncStatus('success');
        setTimeout(() => setLastSyncStatus('idle'), 3000);
        updateCount();
      }
      if (event.data?.type === 'BACKGROUND_SYNC_TRIGGERED') {
        setIsSyncing(true);
        setTimeout(() => setIsSyncing(false), 5000);
      }
    };

    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.addEventListener('message', handleMessage);
    }

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      clearInterval(interval);
      if ('serviceWorker' in navigator) {
        navigator.serviceWorker.removeEventListener('message', handleMessage);
      }
    };
  }, []);

  if (pendingCount === 0 && isOnline && lastSyncStatus === 'idle') return null;

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0, y: 20, scale: 0.95 }}
        animate={{ opacity: 1, y: 0, scale: 1 }}
        exit={{ opacity: 0, y: 20, scale: 0.95 }}
        className={cn(
          "fixed bottom-20 right-4 z-40 flex max-w-[calc(100vw-2rem)] items-center gap-2 rounded-2xl border px-3 py-2 shadow-2xl backdrop-blur-xl transition-all duration-500 sm:bottom-24 sm:right-6 sm:gap-3 sm:px-4 sm:py-3",
          !isOnline 
            ? "bg-amber-500/90 border-amber-400 text-white" 
            : lastSyncStatus === 'success'
            ? "bg-emerald-600/90 border-emerald-400 text-white"
            : "bg-primary/90 border-primary/20 text-white"
        )}
      >
        <div className="relative">
          {isOnline ? (
            isSyncing || pendingCount > 0 ? (
              <RefreshCw className="w-5 h-5 animate-spin" />
            ) : lastSyncStatus === 'success' ? (
              <CircleCheck className="w-5 h-5" />
            ) : (
              <Cloud className="w-5 h-5" />
            )
          ) : (
            <CloudOff className="w-5 h-5 animate-pulse" />
          )}

          {pendingCount > 0 && (
            <span className="absolute -top-2 -right-2 bg-rose-500 text-[10px] font-black w-4 h-4 rounded-full flex items-center justify-center border-2 border-white">
              {pendingCount}
            </span>
          )}
        </div>

        <div className="flex flex-col">
          <span className="text-[11px] font-black uppercase tracking-widest opacity-80 leading-none mb-1">
            Sincronización
          </span>
          <span className="text-xs font-bold leading-none">
            {!isOnline 
              ? "Modo Offline (En espera)" 
              : pendingCount > 0 
              ? `Subiendo ${pendingCount} registros...`
              : lastSyncStatus === 'success'
              ? "Datos sincronizados"
              : "Conexión estable"}
          </span>
        </div>

        {pendingCount > 0 && isOnline && (
          <div className="ml-2 w-12 h-1.5 bg-white/20 rounded-full overflow-hidden">
            <motion.div 
              className="h-full bg-white"
              animate={{ 
                x: ["-100%", "100%"] 
              }}
              transition={{ 
                duration: 1.5, 
                repeat: Infinity, 
                ease: "linear" 
              }}
            />
          </div>
        )}
      </motion.div>
    </AnimatePresence>
  );
};

import React from 'react';
import { Wifi, WifiOff, RefreshCw, Zap } from 'lucide-react';
import { useOfflineSync } from '@/shared/hooks/useOfflineSync';
import { proximitySync } from '@/shared/api/offline/ProximitySyncService';
import { useState, useEffect } from 'react';

export const SyncStatus: React.FC = () => {
  const { isOnline, isSyncing, pendingCount, syncNow } = useOfflineSync();
  const [meshActive, setMeshActive] = useState(proximitySync.getDiscoveredPeers().some(p => p.isConnected));

  useEffect(() => {
    const unsub = proximitySync.onSyncStateChange((state) => {
      setMeshActive(proximitySync.getDiscoveredPeers().some(p => p.isConnected) || state.isSyncing);
    });
    return unsub;
  }, []);

  return (
    <div className="flex items-center gap-2 whitespace-nowrap">
      <div
        className={`flex items-center gap-2 px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider transition-all duration-500 whitespace-nowrap ${
          isOnline
            ? 'bg-emerald-500/10 text-emerald-600 border border-emerald-500/20'
            : 'bg-rose-500/10 text-rose-600 border border-rose-500/20'
        }`}
      >
        {isOnline ? (
          <>
            {isSyncing ? (
              <RefreshCw className="h-3 w-3 animate-spin" />
            ) : (
              <Wifi className="h-3 w-3" />
            )}
            <span className="hidden sm:inline whitespace-nowrap">
              {isSyncing ? 'Sincronizando' : 'En Línea'}
            </span>
          </>
        ) : (
          <>
            <WifiOff className="h-3 w-3 animate-pulse" />
            <span className="hidden sm:inline whitespace-nowrap">Modo Campo</span>
          </>
        )}
      </div>

      {meshActive && !isOnline && (
        <div className="flex items-center gap-2 px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider bg-purple-500/10 text-purple-600 border border-purple-500/20 animate-pulse">
          <Zap className="h-3 w-3" />
          <span className="hidden sm:inline">Mesh Activo</span>
        </div>
      )}

      {pendingCount > 0 && (
        <button
          onClick={syncNow}
          disabled={!isOnline || isSyncing}
          title={`${pendingCount} operación(es) pendiente(s). Click para sincronizar.`}
          className="flex items-center gap-1 px-2 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider bg-amber-500/10 text-amber-600 border border-amber-500/20 hover:bg-amber-500/20 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
        >
          <RefreshCw className={`h-3 w-3 ${isSyncing ? 'animate-spin' : ''}`} />
          <span>{pendingCount} pendiente{pendingCount !== 1 ? 's' : ''}</span>
        </button>
      )}
    </div>
  );
};

