import React from 'react';
import { cn } from '@/shared/ui/cn';
import { CircleAlert, CircleCheck, Info, Loader2 } from 'lucide-react';

interface TreeStatusIndicatorProps {
  counts?: { nodes: number; edges: number };
  depth: number;
  maxDepth?: number;
  isLoading?: boolean;
  hasError?: boolean;
  dependencyInfo?: {
    has_parents?: boolean;
    has_children?: boolean;
    father_id?: number;
    mother_id?: number;
    children_as_father?: number;
    children_as_mother?: number;
    total_children?: number;
  };
  type: 'ancestors' | 'descendants';
  className?: string;
}

export const TreeStatusIndicator: React.FC<TreeStatusIndicatorProps> = ({
  counts,
  depth,
  maxDepth,
  isLoading,
  hasError,
  dependencyInfo,
  type,
  className
}) => {
  if (isLoading) {
    return (
      <div className={cn("flex items-center gap-2 text-sm text-muted-foreground", className)}>
        <Loader2 className="w-4 h-4 animate-spin" />
        <span>Cargando información genealógica...</span>
      </div>
    );
  }

  if (hasError) {
    return (
      <div className={cn("flex items-center gap-2 text-sm text-red-600", className)}>
        <CircleAlert className="w-4 h-4" />
        <span>Error al cargar el árbol</span>
      </div>
    );
  }

  if (!counts || counts.nodes === 0) {
    return (
      <div className={cn("flex items-center gap-2 text-sm text-muted-foreground", className)}>
        <Info className="w-4 h-4" />
        <span>Sin datos genealógicos disponibles</span>
      </div>
    );
  }

  // Caso especial: solo la raíz sin relaciones
  if (counts.nodes === 1 && counts.edges === 0) {
    return (
      <div className={cn("flex items-center gap-2 text-sm text-yellow-600", className)}>
        <CircleAlert className="w-4 h-4" />
        <span>
          {type === 'ancestors' 
            ? 'Este animal no tiene padres registrados' 
            : 'Este animal no tiene hijos registrados'}
        </span>
      </div>
    );
  }

  // Estado normal con datos
  const hasMoreLevels = maxDepth ? depth < maxDepth : false;
  const hasRelations = counts.edges > 0;

  return (
    <div className={cn("flex items-center gap-4 text-sm", className)}>
      <div className="flex items-center gap-2">
        {hasRelations ? (
          <CircleCheck className="w-4 h-4 text-green-600" />
        ) : (
          <Info className="w-4 h-4 text-blue-600" />
        )}
        <span className="text-foreground">
          {counts.nodes} {counts.nodes === 1 ? 'nodo' : 'nodos'}
        </span>
        {hasRelations && (
          <span className="text-muted-foreground">
            · {counts.edges} {counts.edges === 1 ? 'relación' : 'relaciones'}
          </span>
        )}
      </div>

      <div className="text-muted-foreground">
        Profundidad: {depth}
        {maxDepth && `/${maxDepth}`}
      </div>

      {hasMoreLevels && (
        <div className="text-xs text-blue-600 bg-blue-50 px-2 py-1 rounded">
          Hay más niveles disponibles
        </div>
      )}

      {/* Información adicional de dependencias */}
      {dependencyInfo && (
        <div className="text-xs text-muted-foreground">
          {type === 'ancestors' ? (
            <span>
              Padre: {dependencyInfo.father_id ? `ID ${dependencyInfo.father_id}` : 'No'} · 
              Madre: {dependencyInfo.mother_id ? `ID ${dependencyInfo.mother_id}` : 'No'}
            </span>
          ) : (
            <span>
              Hijos: {dependencyInfo.total_children || 0}
              {dependencyInfo.children_as_father && ` (${dependencyInfo.children_as_father} como padre)`}
              {dependencyInfo.children_as_mother && ` (${dependencyInfo.children_as_mother} como madre)`}
            </span>
          )}
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useQuery } from '@tanstack/react-query';
import analyticsService from '@/features/reporting/api/analytics.service';

/**
 * Panel de Próximos Eventos — calendario ejecutivo de la finca.
 * Muestra en los próximos N días: partos, post-partos, vacunaciones y controles pendientes.
 */

type TabKey = 'births' | 'postparto' | 'vaccines' | 'controls';

const tabConfig: { key: TabKey; label: string; icon: string; emptyMsg: string }[] = [
  { key: 'births',    label: 'Partos',          icon: '🐄', emptyMsg: 'No hay partos esperados próximamente.' },
  { key: 'postparto', label: 'Post-parto',       icon: '🍼', emptyMsg: 'No hay animales en período post-parto.' },
  { key: 'vaccines',  label: 'Vacunas ICA',      icon: '💉', emptyMsg: 'Todas las vacunaciones ICA están al día.' },
  { key: 'controls',  label: 'Controles',        icon: '⚕️', emptyMsg: 'No hay controles veterinarios pendientes.' },
];

function statusBadge(status: string) {
  if (status === 'overdue' || status === 'imminent') {
    return <span className="px-2 py-0.5 text-xs font-bold bg-red-100 text-red-700 rounded-full">
      {status === 'imminent' ? 'Inminente' : 'Vencido'}
    </span>;
  }
  if (status === 'due_soon') {
    return <span className="px-2 py-0.5 text-xs font-bold bg-orange-100 text-orange-700 rounded-full">Pronto</span>;
  }
  return <span className="px-2 py-0.5 text-xs font-bold bg-blue-100 text-blue-700 rounded-full">Programado</span>;
}

const UpcomingEventsPanel: React.FC = () => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<TabKey>('births');
  const [days, setDays] = useState(30);

  const { data, isLoading, refetch } = useQuery({
    queryKey: ['upcoming-events', days],
    queryFn: () => analyticsService.getUpcomingEvents(days),
    staleTime: 5 * 60 * 1000,
    refetchInterval: 10 * 60 * 1000,
  });

  const summary = data?.summary ?? {};
  const counts: Record<TabKey, number> = {
    births:    summary.births           ?? 0,
    postparto: summary.postparto        ?? 0,
    vaccines:  summary.vaccinations_due ?? 0,
    controls:  summary.controls_due     ?? 0,
  };

  const rows: Record<TabKey, React.ReactNode[]> = {
    births: (data?.upcoming_births ?? []).map((b: any) => (
      <div key={b.animal_id} className="flex items-center justify-between py-2.5 border-b border-border last:border-0">
        <div>
          <p className="font-semibold text-text-primary text-sm">{b.record}</p>
          <p className="text-xs text-text-secondary">
            Gestación día {b.gestation_days} · Parto esperado {new Date(b.expected_birth).toLocaleDateString('es-CO')}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <span className="text-xs text-text-secondary">
            {b.days_to_birth < 0 ? `${Math.abs(b.days_to_birth)} días pasados` : `en ${b.days_to_birth} días`}
          </span>
          {statusBadge(b.status)}
        </div>
      </div>
    )),
    postparto: (data?.postparto_monitoring ?? []).map((p: any) => (
      <div key={p.animal_id} className="flex items-center justify-between py-2.5 border-b border-border last:border-0">
        <div>
          <p className="font-semibold text-text-primary text-sm">{p.record}</p>
          <p className="text-xs text-text-secondary">
            Parto {new Date(p.birth_date).toLocaleDateString('es-CO')} · Día {p.days_postparto} post-parto
          </p>
        </div>
        <div className="text-right">
          <p className="text-xs text-text-secondary">Próxima revisión</p>
          <p className="text-xs font-semibold text-orange-600">
            {new Date(p.next_check).toLocaleDateString('es-CO')}
          </p>
        </div>
      </div>
    )),
    vaccines: (data?.vaccination_due ?? []).map((v: any) => (
      <div key={v.animal_id} className="flex items-center justify-between py-2.5 border-b border-border last:border-0">
        <div>
          <p className="font-semibold text-text-primary text-sm">{v.record}</p>
          <p className="text-xs text-text-secondary">{v.vaccine}</p>
          <p className="text-xs text-text-secondary">Última: {new Date(v.last_date).toLocaleDateString('es-CO')}</p>
        </div>
        <div className="flex items-center gap-2">
          <span className="text-xs text-text-secondary">
            {v.days_remaining < 0 ? `${Math.abs(v.days_remaining)}d vencida` : `en ${v.days_remaining}d`}
          </span>
          {statusBadge(v.status)}
        </div>
      </div>
    )),
    controls: (data?.controls_due ?? []).map((c: any) => (
      <div key={c.animal_id} className="flex items-center justify-between py-2.5 border-b border-border last:border-0">
        <div>
          <p className="font-semibold text-text-primary text-sm">{c.record}</p>
          <p className="text-xs text-text-secondary">Último control: {new Date(c.last_control).toLocaleDateString('es-CO')}</p>
          <p className="text-xs text-text-secondary">{c.days_since} días sin revisión</p>
        </div>
        <button
          onClick={() => navigate('/admin/controls?create=1')}
          className="text-xs font-semibold text-primary hover:underline"
        >
          Programar →
        </button>
      </div>
    )),
  };

  const totalUrgent = counts.births + counts.postparto + counts.vaccines + counts.controls;

  return (
    <div className="bg-surface border border-border rounded-3xl overflow-hidden shadow-sm">
      {/* Header */}
      <div className="px-6 py-5 border-b border-border">
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-xl font-black text-text-primary tracking-tight">📅 Próximos Eventos</h2>
            <p className="text-sm text-text-secondary mt-0.5">{totalUrgent} eventos en los próximos {days} días</p>
          </div>
          <div className="flex items-center gap-2">
            <select
              value={days}
              onChange={e => setDays(Number(e.target.value))}
              className="text-xs bg-surface border border-border rounded-lg px-2 py-1 text-text-secondary"
            >
              <option value={14}>14 días</option>
              <option value={30}>30 días</option>
              <option value={60}>60 días</option>
            </select>
            <button
              onClick={() => refetch()}
              className="text-xs text-primary hover:underline"
            >
              ↻ Actualizar
            </button>
          </div>
        </div>

        {/* Tabs con badges */}
        <div className="flex gap-1 mt-4 flex-wrap">
          {tabConfig.map(tab => (
            <button
              key={tab.key}
              onClick={() => setActiveTab(tab.key)}
              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold transition-all ${
                activeTab === tab.key
                  ? 'bg-primary text-white shadow-sm'
                  : 'bg-border/40 text-text-secondary hover:bg-border/60'
              }`}
            >
              {tab.icon} {tab.label}
              {counts[tab.key] > 0 && (
                <span className={`px-1.5 py-0.5 rounded-full text-[10px] font-black ${
                  activeTab === tab.key ? 'bg-white/20 text-white' : 'bg-primary/10 text-primary'
                }`}>
                  {counts[tab.key]}
                </span>
              )}
            </button>
          ))}
        </div>
      </div>

      {/* Lista */}
      <div className="px-6 py-3 min-h-[180px]">
        {isLoading ? (
          <div className="space-y-2 py-4">
            {[1, 2, 3].map(i => (
              <div key={i} className="h-12 bg-border/20 rounded-xl animate-pulse" />
            ))}
          </div>
        ) : rows[activeTab].length > 0 ? (
          <div>{rows[activeTab]}</div>
        ) : (
          <div className="flex flex-col items-center justify-center py-10 text-center">
            <p className="text-3xl mb-2">✅</p>
            <p className="text-sm text-text-secondary">
              {tabConfig.find(t => t.key === activeTab)?.emptyMsg}
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

export default UpcomingEventsPanel;

import React, { useState, useEffect, useCallback } from 'react';
import { MoreVertical, Activity, Syringe, Eye, Plus, Trash2 } from 'lucide-react';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubTrigger,
  DropdownMenuSubContent,
} from '@/shared/ui/dropdown-menu';
import { GenericModal } from '@/shared/ui/common/GenericModal';
import { UserResponse } from '@/shared/api/generated/swaggerTypes';
import { getTodayColombia } from '@/shared/utils/dateUtils';

// Importar servicios
import { animalDiseasesService } from '@/entities/animal-disease/api/animalDiseases.service';
import { vaccinationsService } from '@/entities/vaccination/api/vaccinations.service';
import { diseaseService } from '@/entities/disease/api/disease.service';
import { animalsService } from '@/entities/animal/api/animal.service';
import { vaccinesService } from '@/entities/vaccine/api/vaccines.service';
import { getAnimalLabel } from '@/entities/animal/lib/animalHelpers';

interface UserActionsMenuProps {
  user: UserResponse;
}

type ModalType = 'animal_disease' | 'vaccination' | null;
type ModalMode = 'create' | 'list';

export const UserActionsMenu: React.FC<UserActionsMenuProps> = ({ user }) => {
  const [openModal, setOpenModal] = useState<ModalType>(null);
  const [modalMode, setModalMode] = useState<ModalMode>('create');
  const [formData, setFormData] = useState<any>({});
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [listData, setListData] = useState<any[]>([]);
  const [loadingList, setLoadingList] = useState(false);
  const [deletingId, setDeletingId] = useState<number | string | null>(null);
  const [animalLabelById, setAnimalLabelById] = useState<Map<number, string>>(new Map());

  // Opciones para los selects
  const [animalOptions, setAnimalOptions] = useState<Array<{ value: number; label: string }>>([]);
  const [diseaseOptions, setDiseaseOptions] = useState<Array<{ value: number; label: string }>>([]);
  const [vaccineOptions, setVaccineOptions] = useState<Array<{ value: number; label: string }>>([]);

  // Cargar opciones
  const loadOptions = useCallback(async () => {
    try {
      const [animals, diseases, vaccines] = await Promise.all([
        animalsService.getAnimals({ page: 1, limit: 1000 }).catch(() => []),
        diseaseService.getDiseases({ page: 1, limit: 1000 }).catch(() => []),
        vaccinesService.getVaccines?.({ page: 1, limit: 1000 }).catch(() => []),
      ]);

      const animalsData = animals || [];
      setAnimalOptions(animalsData.map((a: any) => ({
        value: a.id,
        label: a.record || `ID ${a.id}`
      })));

      const diseasesData = (diseases as any)?.data || diseases || [];
      setDiseaseOptions(diseasesData.map((d: any) => ({
        value: d.id,
        label: d.disease || d.name || `Enfermedad ${d.id}`
      })));

      const vaccinesData = (vaccines as any)?.data || vaccines || [];
      setVaccineOptions(vaccinesData.map((v: any) => ({
        value: v.id,
        label: v.name || `Vacuna ${v.id}`
      })));
    } catch (err) {
      console.error('Error loading options:', err);
    }
  }, []);

  // Cargar lista de datos
  const loadListData = useCallback(async () => {
    setLoadingList(true);
    try {
      let data: any[] = [];
      const userIdentity = String(user?.identification ?? user?.id ?? '');
      const userId = Number(user?.id ?? 0);

      const animalsList = await animalsService.getAnimals({ page: 1, limit: 1000 }).catch(() => []);
      const safeAnimals = Array.isArray(animalsList) ? animalsList : [];

      const userAnimalRecords = safeAnimals.filter((animal: any) => {
        const nestedId = animal?.user?.id;
        const nestedIdentification = animal?.user?.identification;
        const directId = animal?.user_id ?? animal?.userId;
        if (nestedId != null && Number(nestedId) === userId) return true;
        if (directId != null && Number(directId) === userId) return true;
        return String(nestedIdentification ?? '') === userIdentity;
      });

      const userAnimalIds = new Set(
        userAnimalRecords
          .map((animal: any) => Number(animal?.id))
          .filter((id: number) => Number.isFinite(id) && id > 0)
      );

      const labelMap = new Map(
        userAnimalRecords.map((animal: any) => [
          Number(animal?.id),
          getAnimalLabel(animal) || animal.code || animal.record || `Animal ${animal?.id}`,
        ])
      );
      setAnimalLabelById(labelMap);

      const getAnimalIdFromRecord = (record: any): number | null => {
        const candidates = [
          record?.animal_id,
          record?.animalId,
          record?.animals?.id,
          record?.animal?.id,
          record?.animals_id,
        ];
        const candidate = candidates.find((value) => value != null && value !== '');
        const num = Number(candidate);
        return Number.isFinite(num) ? num : null;
      };

      const isUserFkRecord = (record: any): boolean => {
        if (!record) return false;

        const animalId = getAnimalIdFromRecord(record);
        if (animalId != null && userAnimalIds.has(animalId)) {
          return true;
        }

        const directIdCandidates = [
          record?.user_id,
          record?.userId,
          record?.apprentice_id,
          record?.apprenticeId,
          record?.instructor_id,
          record?.instructorId,
          record?.owner_id,
          record?.ownerId,
        ];

        if (userId && directIdCandidates.some((value) => Number(value) === userId)) {
          return true;
        }

        const nestedUsers = [
          record?.user,
          record?.apprentice,
          record?.instructor,
          record?.owner,
        ].filter(Boolean);

        for (const nested of nestedUsers) {
          if (nested?.id != null && Number(nested.id) === userId) return true;
          if (nested?.identification != null && String(nested.identification) === userIdentity) return true;
        }

        return false;
      };

      switch (openModal) {
        case 'animal_disease':
          {
            const adResult = await animalDiseasesService.getAll({ page: 1, limit: 1000 }).catch(() => []);
            const allDiseases = Array.isArray(adResult) ? adResult : (adResult as any)?.data || (adResult as any)?.items || [];
            data = allDiseases.filter((item: any) => isUserFkRecord(item));
            break;
          }

        case 'vaccination':
          {
            const vResult = await vaccinationsService.getAll({ page: 1, limit: 1000 }).catch(() => []);
            const allVaccinations = Array.isArray(vResult) ? vResult : (vResult as any)?.data || (vResult as any)?.items || [];
            data = allVaccinations.filter((item: any) => isUserFkRecord(item));
            break;
          }
      }

      setListData(data);
    } catch (err: any) {
      console.error('Error loading list data:', err);
      setError('Error al cargar los registros');
    } finally {
      setLoadingList(false);
    }
  }, [openModal, user?.id, user?.identification]);

  // Cargar opciones cuando se abre un modal de creación
  useEffect(() => {
    if (openModal && modalMode === 'create') {
      loadOptions();
    }
  }, [openModal, modalMode, loadOptions]);

  // Cargar lista cuando se abre un modal de lista
  useEffect(() => {
    if (openModal && modalMode === 'list') {
      loadListData();
    }
  }, [openModal, modalMode, user?.id, user?.identification, loadListData]);

  const handleOpenModal = (type: ModalType, mode: ModalMode) => {
    setOpenModal(type);
    setModalMode(mode);
    setError(null);
    setListData([]);

    if (mode === 'create') {
      // Inicializar formulario según el tipo
      switch (type) {
        case 'animal_disease':
          setFormData({
            animal_id: undefined,
            disease_id: undefined,
            instructor_id: user.id,
            diagnosis_date: getTodayColombia(),
            status: 'Activo',
            notes: '',
          });
          break;
        case 'vaccination':
          setFormData({
            animal_id: undefined,
            vaccine_id: undefined,
            vaccination_date: getTodayColombia(),
            apprentice_id: user.role === 'Aprendiz' ? user.id : undefined,
            instructor_id: user.role === 'Instructor' ? user.id : undefined,
          });
          break;
      }
    }
  };

  const handleCloseModal = () => {
    setOpenModal(null);
    setFormData({});
    setError(null);
    setListData([]);
  };

  const getAnimalLabelForId = (animalId: number | null | undefined): string => {
    if (!animalId) return '-';
    return animalLabelById.get(Number(animalId)) || `Animal ${animalId}`;
  };

  const handleDeleteRecord = async (item: any) => {
    const rawId = item?.id;
    if (rawId == null) return;
    const idValue = typeof rawId === 'number' ? rawId : Number(rawId);
    const idForDelete = Number.isFinite(idValue) ? idValue : String(rawId);

    const confirmText = 'Eliminar este registro relacionado?';
    if (!window.confirm(confirmText)) return;

    setDeletingId(rawId);
    setError(null);

    try {
      switch (openModal) {
        case 'animal_disease':
          await animalDiseasesService.deleteAnimalDisease(String(idForDelete));
          break;
        case 'vaccination':
          await vaccinationsService.deleteVaccination(String(idForDelete));
          break;
      }

      setListData((prev) => prev.filter((row) => row?.id !== rawId));
    } catch (err: any) {
      setError(err?.response?.data?.message || err?.message || 'Error al eliminar el registro');
    } finally {
      setDeletingId(null);
    }
  };

  const handleSubmit = async () => {
    setLoading(true);
    setError(null);

    try {
      switch (openModal) {
        case 'animal_disease':
          if (!formData.animal_id || !formData.disease_id || !formData.instructor_id) {
            throw new Error('Animal, enfermedad e instructor son obligatorios');
          }
          await animalDiseasesService.createAnimalDisease(formData);
          break;
        case 'vaccination':
          if (!formData.animal_id || !formData.vaccine_id) {
            throw new Error('Animal y vacuna son obligatorios');
          }
          await vaccinationsService.createVaccination(formData);
          break;
      }

      handleCloseModal();
    } catch (err: any) {
      setError(err?.response?.data?.message || err.message || 'Error al guardar');
    } finally {
      setLoading(false);
    }
  };

  const renderListContent = () => {
    if (loadingList) {
      return (
        <div className="py-10 text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto mb-4"></div>
          <p className="text-muted-foreground">Cargando registros...</p>
        </div>
      );
    }

    if (listData.length === 0) {
      return (
        <div className="space-y-4">
          <div className="flex justify-end p-4 pb-0">
            <button
              onClick={() => handleOpenModal(openModal, 'create')}
              className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-primary bg-primary/10 hover:bg-primary/20 rounded-md transition-colors"
            >
              <Plus className="h-3.5 w-3.5" />
              Nuevo...
            </button>
          </div>
          <div className="pb-10 text-center">
            {error ? (
              <p className="text-destructive">{error}</p>
            ) : (
              <p className="text-muted-foreground">No hay registros para este usuario</p>
            )}
          </div>
        </div>
      );
    }

    return (
      <div className="space-y-3 max-h-[500px] overflow-y-auto">
        <div className="flex justify-end mb-2">
          <button
            onClick={() => handleOpenModal(openModal, 'create')}
            className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-primary bg-primary/10 hover:bg-primary/20 rounded-md transition-colors"
          >
            <Plus className="h-3.5 w-3.5" />
            Nuevo...
          </button>
        </div>
        {error && (
          <div className="p-3 bg-destructive/10 border border-destructive/30 rounded-md text-sm text-destructive">
            {error}
          </div>
        )}
        {listData.map((item, index) => (
          <div
            key={item.id || index}
            className="border border-border rounded-lg p-4 bg-card hover:bg-accent/50 transition-colors"
          >
            <div className="flex flex-col gap-3">
              {renderListItem(item)}
              <div className="flex justify-end">
                <button
                  onClick={() => handleDeleteRecord(item)}
                  className="inline-flex items-center gap-1.5 text-sm text-destructive hover:text-destructive/80"
                  disabled={deletingId === item?.id}
                >
                  <Trash2 className="h-4 w-4" />
                  {deletingId === item?.id ? 'Eliminando...' : 'Eliminar'}
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    );
  };

  const renderListItem = (item: any) => {
    switch (openModal) {
      case 'animal_disease':
        return (
          <div className="space-y-2 text-sm">
            <div className="flex justify-between">
              <span className="font-medium text-foreground">Animal:</span>
              <span className="text-muted-foreground">{item.animal_id ? getAnimalLabelForId(item.animal_id) : '-'}</span>
            </div>
            <div className="flex justify-between">
              <span className="font-medium text-foreground">Enfermedad:</span>
              <span className="text-muted-foreground">{item?.disease?.name || item?.disease_name || item?.disease_id || '-'}</span>
            </div>
            <div className="flex justify-between">
              <span className="font-medium text-foreground">Estado:</span>
              <span className={item.status === 'Activo' ? 'text-destructive font-medium' : 'text-green-600 font-medium'}>
                {item.status || '-'}
              </span>
            </div>
            <div className="flex justify-between">
              <span className="font-medium text-foreground">Diagnóstico:</span>
              <span className="text-muted-foreground">
                {item.diagnosis_date ? new Date(item.diagnosis_date).toLocaleDateString('es-ES') : '-'}
              </span>
            </div>
            {item.notes && (
              <div>
                <span className="font-medium text-foreground">Notas:</span>
                <p className="text-muted-foreground mt-1">{item.notes}</p>
              </div>
            )}
          </div>
        );

      case 'vaccination':
        {
          const roleLabel = item.instructor_id === user.id ? 'Instructor' : item.apprentice_id === user.id ? 'Aprendiz' : 'N/A';
          return (
            <div className="space-y-2 text-sm">
              <div className="flex justify-between">
                <span className="font-medium text-foreground">Animal:</span>
                <span className="text-muted-foreground">{item.animal_id ? getAnimalLabelForId(item.animal_id) : '-'}</span>
              </div>
              <div className="flex justify-between">
                <span className="font-medium text-foreground">Vacuna:</span>
                <span className="text-muted-foreground">{item?.vaccine?.name || item?.vaccines?.name || item.vaccine_id || '-'}</span>
              </div>
              <div className="flex justify-between">
                <span className="font-medium text-foreground">Fecha:</span>
                <span className="text-muted-foreground">
                  {item.application_date || item.vaccination_date ? new Date(item.application_date || item.vaccination_date).toLocaleDateString('es-ES') : '-'}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="font-medium text-foreground">Rol:</span>
                <span className="text-muted-foreground">{roleLabel}</span>
              </div>
            </div>
          );
        }

      default:
        return null;
    }
  };

  const renderFormContent = () => {
    const inputClass = "w-full px-3 py-2 text-sm rounded-md border border-input bg-background ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 transition-colors";
    const labelClass = "block text-sm font-medium mb-1.5 text-foreground";
    const selectClass = "w-full px-3 py-2 text-sm rounded-md border border-input bg-background ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 transition-colors";

    switch (openModal) {
      case 'animal_disease':
        return (
          <div className="space-y-4">
            <div>
              <label className={labelClass}>Instructor</label>
              <input
                type="text"
                value={user.fullname || `ID ${user.id}`}
                disabled
                className={`${inputClass} bg-muted/50`}
              />
            </div>
            <div>
              <label className={labelClass}>Animal *</label>
              <select
                value={formData.animal_id || ''}
                onChange={(e) => setFormData({ ...formData, animal_id: parseInt(e.target.value) })}
                className={selectClass}
              >
                <option value="">Seleccionar animal</option>
                {animalOptions.map((opt) => (
                  <option key={opt.value} value={opt.value}>{opt.label}</option>
                ))}
              </select>
            </div>
            <div>
              <label className={labelClass}>Enfermedad *</label>
              <select
                value={formData.disease_id || ''}
                onChange={(e) => setFormData({ ...formData, disease_id: parseInt(e.target.value) })}
                className={selectClass}
              >
                <option value="">Seleccionar enfermedad</option>
                {diseaseOptions.map((opt) => (
                  <option key={opt.value} value={opt.value}>{opt.label}</option>
                ))}
              </select>
            </div>
            <div>
              <label className={labelClass}>Fecha de Diagnóstico *</label>
              <input
                type="date"
                value={formData.diagnosis_date || ''}
                onChange={(e) => setFormData({ ...formData, diagnosis_date: e.target.value })}
                className={inputClass}
              />
            </div>
            <div>
              <label className={labelClass}>Estado</label>
              <select
                value={formData.status || 'Activo'}
                onChange={(e) => setFormData({ ...formData, status: e.target.value })}
                className={selectClass}
              >
                <option value="Activo">Activo</option>
                <option value="En tratamiento">En tratamiento</option>
                <option value="Curado">Curado</option>
              </select>
            </div>
            <div>
              <label className={labelClass}>Notas</label>
              <textarea
                value={formData.notes || ''}
                onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                placeholder="Observaciones"
                rows={3}
                className={inputClass}
              />
            </div>
          </div>
        );

      case 'vaccination':
        return (
          <div className="space-y-4">
            <div>
              <label className={labelClass}>Usuario</label>
              <input
                type="text"
                value={`${user.fullname} (${user.role})`}
                disabled
                className={`${inputClass} bg-muted/50`}
              />
            </div>
            <div>
              <label className={labelClass}>Animal *</label>
              <select
                value={formData.animal_id || ''}
                onChange={(e) => setFormData({ ...formData, animal_id: parseInt(e.target.value) })}
                className={selectClass}
              >
                <option value="">Seleccionar animal</option>
                {animalOptions.map((opt) => (
                  <option key={opt.value} value={opt.value}>{opt.label}</option>
                ))}
              </select>
            </div>
            <div>
              <label className={labelClass}>Vacuna *</label>
              <select
                value={formData.vaccine_id || ''}
                onChange={(e) => setFormData({ ...formData, vaccine_id: parseInt(e.target.value) })}
                className={selectClass}
              >
                <option value="">Seleccionar vacuna</option>
                {vaccineOptions.map((opt) => (
                  <option key={opt.value} value={opt.value}>{opt.label}</option>
                ))}
              </select>
            </div>
            <div>
              <label className={labelClass}>Fecha de Vacunación *</label>
              <input
                type="date"
                value={formData.vaccination_date || ''}
                onChange={(e) => setFormData({ ...formData, vaccination_date: e.target.value })}
                className={inputClass}
              />
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  const getModalTitle = () => {
    switch (openModal) {
      case 'animal_disease':
        return modalMode === 'create' ? 'Registrar Enfermedad' : 'Enfermedades Asignadas';
      case 'vaccination':
        return modalMode === 'create' ? 'Registrar Vacunación' : 'Vacunaciones Realizadas';
      default:
        return '';
    }
  };

  return (
    <>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <button
            className="icon-btn p-1.5 hover:bg-accent rounded-md transition-colors"
            onClick={(e) => e.stopPropagation()}
            title="Más acciones"
            aria-label="Más acciones"
          >
            <MoreVertical className="h-4 w-4" />
          </button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end" className="w-56">
          <DropdownMenuSub>
            <DropdownMenuSubTrigger>
              <Activity className="mr-2 h-4 w-4" />
              Enfermedades
            </DropdownMenuSubTrigger>
            <DropdownMenuSubContent>
              <DropdownMenuItem
                onClick={(e) => {
                  e.stopPropagation();
                  handleOpenModal('animal_disease', 'create');
                }}
                className="cursor-pointer"
              >
                <Plus className="mr-2 h-4 w-4" />
                Insertar
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={(e) => {
                  e.stopPropagation();
                  handleOpenModal('animal_disease', 'list');
                }}
                className="cursor-pointer"
              >
                <Eye className="mr-2 h-4 w-4" />
                Ver Lista
              </DropdownMenuItem>
            </DropdownMenuSubContent>
          </DropdownMenuSub>

          <DropdownMenuSeparator />

          <DropdownMenuSub>
            <DropdownMenuSubTrigger>
              <Syringe className="mr-2 h-4 w-4" />
              Vacunaciones
            </DropdownMenuSubTrigger>
            <DropdownMenuSubContent>
              <DropdownMenuItem
                onClick={(e) => {
                  e.stopPropagation();
                  handleOpenModal('vaccination', 'create');
                }}
                className="cursor-pointer"
              >
                <Plus className="mr-2 h-4 w-4" />
                Insertar
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={(e) => {
                  e.stopPropagation();
                  handleOpenModal('vaccination', 'list');
                }}
                className="cursor-pointer"
              >
                <Eye className="mr-2 h-4 w-4" />
                Ver Lista
              </DropdownMenuItem>
            </DropdownMenuSubContent>
          </DropdownMenuSub>
        </DropdownMenuContent>
      </DropdownMenu>

      <GenericModal
        isOpen={openModal !== null}
        onOpenChange={(open) => !open && handleCloseModal()}
        title={getModalTitle()}
        description={modalMode === 'list' ? `Registros del usuario ${user.fullname || user.id}` : undefined}
        size="2xl"
        enableBackdropBlur
        className="bg-card/95 backdrop-blur-md text-card-foreground border-border/50"
      >
        <div className="space-y-4">
          {modalMode === 'list' ? (
            renderListContent()
          ) : (
            <>
              {renderFormContent()}

              {error && (
                <div className="p-3 bg-destructive/10 border border-destructive/30 rounded-md text-sm text-destructive">
                  {error}
                </div>
              )}

              <div className="flex justify-end gap-2 pt-4 border-t border-border">
                <button
                  onClick={handleCloseModal}
                  className="px-4 py-2 text-sm rounded-md border border-input bg-background hover:bg-accent hover:text-accent-foreground transition-colors"
                  disabled={loading}
                >
                  Cancelar
                </button>
                <button
                  onClick={handleSubmit}
                  className="px-4 py-2 text-sm rounded-md bg-primary text-primary-foreground hover:bg-primary/90 transition-colors shadow-sm"
                  disabled={loading}
                >
                  {loading ? 'Guardando...' : 'Guardar'}
                </button>
              </div>
            </>
          )}
        </div>
      </GenericModal>
    </>
  );
};

import React from 'react';
import { Card, CardContent } from '@/shared/ui/card';
import { Badge } from '@/shared/ui/badge';
import { Button } from '@/shared/ui/button';
import { Mail, Calendar, MoreVertical, ExternalLink } from 'lucide-react';
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from '@/shared/ui/dropdown-menu';

interface User {
    id: number;
    username: string;
    fullname?: string;
    email?: string;
    role: string;
    isActive: boolean;
    lastLogin?: string;
    createdAt?: string;
    phone?: string;
    address?: string;
}

interface UserCardProps {
    user: User;
    onView?: (user: User) => void;
    onEdit?: (user: User) => void;
    className?: string;
}

export const UserCard: React.FC<UserCardProps> = ({ user, onView, className }) => {
    const getRoleColor = (role: string) => {
        switch (role?.toLowerCase()) {
            case 'administrador':
                return 'destructive';
            case 'instructor':
                return 'default';
            case 'aprendiz':
                return 'secondary';
            default:
                return 'outline';
        }
    };

    const getInitials = (name: string) => {
        return name?.charAt(0).toUpperCase() || '?';
    };

    return (
        <Card className={`h-full group hover:shadow-lg transition-all duration-300 border-l-4 ${user.isActive ? 'border-l-green-500' : 'border-l-gray-300'} ${className}`}>
            <CardContent className="p-5 h-full flex flex-col">
                <div className="flex justify-between items-start mb-4">
                    <div className="flex items-center gap-3">
                        {/* Manual Avatar Implementation */}
                        <div className="relative h-12 w-12 rounded-full border-2 border-white shadow-sm ring-1 ring-gray-100 flex items-center justify-center bg-primary/10 text-primary font-bold overflow-hidden">
                            <img
                                src={`https://ui-avatars.com/api/?name=${encodeURIComponent(user.username)}&background=random&length=1`}
                                alt={user.username}
                                className="h-full w-full object-cover opacity-90 hover:opacity-100 transition-opacity"
                                onError={(e) => {
                                    (e.target as HTMLImageElement).style.display = 'none';
                                    (e.target as HTMLImageElement).parentElement!.classList.remove('overflow-hidden');
                                }}
                            />
                            <span className="absolute">{getInitials(user.username)}</span>
                        </div>

                        <div>
                            <h3 className="font-bold text-lg leading-tight text-gray-900 truncate max-w-[150px]" title={user.username}>
                                {user.username}
                            </h3>
                            <div className="flex items-center gap-1 mt-1">
                                <Badge variant={getRoleColor(user.role) as any} className="text-[10px] h-5 px-1.5 font-medium">
                                    {user.role}
                                </Badge>
                                {!user.isActive && (
                                    <Badge variant="outline" className="text-[10px] h-5 px-1.5 text-gray-500 bg-gray-50 border-gray-200">
                                        Inactivo
                                    </Badge>
                                )}
                            </div>
                        </div>
                    </div>

                    <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                            <Button
                                variant="ghost"
                                size="icon"
                                aria-label="Más opciones"
                                className="h-8 w-8 text-gray-400 hover:text-gray-700"
                            >
                                <MoreVertical className="h-4 w-4" />
                            </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                            <DropdownMenuItem onClick={() => onView?.(user)}>
                                <ExternalLink className="mr-2 h-4 w-4" /> Ver detalles
                            </DropdownMenuItem>
                        </DropdownMenuContent>
                    </DropdownMenu>
                </div>

                <div className="space-y-2.5 text-sm text-gray-600 flex-1">
                    <div className="flex items-center gap-2.5 bg-gray-50/50 p-1.5 rounded-md hover:bg-gray-50 transition-colors">
                        <Mail className="h-4 w-4 text-gray-400 shrink-0" />
                        <span className="truncate flex-1" title={user.email}>{user.email || 'Sin email'}</span>
                    </div>

                    <div className="grid grid-cols-2 gap-2">
                        {user.createdAt && (
                            <div className="flex items-center gap-2 text-xs text-gray-500 bg-gray-50/50 p-1.5 rounded-md">
                                <Calendar className="h-3.5 w-3.5 text-gray-400" />
                                <span>{new Date(user.createdAt).toLocaleDateString()}</span>
                            </div>
                        )}
                        {user.lastLogin && (
                            <div className="flex items-center gap-2 text-xs text-green-600 bg-green-50/50 p-1.5 rounded-md">
                                <div className="h-1.5 w-1.5 rounded-full bg-green-500 animate-pulse" />
                                <span>{new Date(user.lastLogin).toLocaleDateString()}</span>
                            </div>
                        )}
                    </div>
                </div>

                <div className="mt-auto pt-3 border-t border-gray-100 flex justify-end">
                    <Button variant="outline" size="sm" className="w-full text-xs font-medium h-8 bg-transparent hover:bg-gray-50 border-gray-200" onClick={() => onView?.(user)}>
                        Ver Perfil
                    </Button>
                </div>
            </CardContent>
        </Card>
    );
};

import { useState, useMemo } from "react";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/shared/ui/tabs";
import { Card, CardContent, CardHeader, CardTitle } from "@/shared/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/shared/ui/table";
import { Input } from "@/shared/ui/input";
import { Button } from "@/shared/ui/button";
import { Badge } from "@/shared/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/shared/ui/select";
import { useAnimals } from "@/entities/animal/model/useAnimals";
import { useAnimalDiseases } from "@/entities/animal-disease/model/useAnimalDiseases";
import { useAnimalFields } from "@/entities/animal-field/model/useAnimalFields";
import { useTreatment } from "@/entities/treatment/model/useTreatment";
import { useControls } from "@/entities/control/model/useControl";
import { useGeneticImprovements } from "@/entities/genetic-improvement/model/useGeneticImprovement";
import { safeArray } from '@/shared/utils/apiHelpers';
import { format } from "date-fns";
import { es } from "date-fns/locale";
import { Calendar, Clock, Filter, Search, Activity, MapPin, Stethoscope, Syringe, Users, User, IdCard, Mail } from "lucide-react";
import { getAnimalLabel } from '@/entities/animal/lib/animalHelpers';
import { Modal, ModalContent, ModalHeader, ModalBody } from "@/shared/ui/common/UnifiedModal";

// Interfaces for data types

interface UserActivity {
  id: string;
  date: string;
  type: 'animal_created' | 'disease_treated' | 'control_performed' | 'treatment_applied' | 'genetic_improvement' | 'field_management';
  title: string;
  description: string;
  animalRecord?: string;
  status?: string;
  icon: React.ReactNode;
}

interface UserHistoryModalProps {
  user: {
    id?: number;
    identification: string | number;
    fullname: string;
    email: string;
    phone?: string;
    address?: string;
    role: string;
    status: boolean | string | number;
  };
  onClose: () => void;
}

export const UserHistoryModal = ({ user, onClose }: UserHistoryModalProps) => {
  const { animals } = useAnimals();
  const { animalDiseases } = useAnimalDiseases();
  const { animalFields } = useAnimalFields();
  const { treatments } = useTreatment();
  const { controls } = useControls();
  const { geneticImprovements } = useGeneticImprovements();
  
  // Filter and search states
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedActivityType, setSelectedActivityType] = useState<string>("all");
  const [selectedDateRange, setSelectedDateRange] = useState<string>("all");
  const [activeTab, setActiveTab] = useState("timeline");

  // Filter data for the selected user
  const safeAnimals = safeArray(animals);
  const safeAnimalDiseases = safeArray(animalDiseases);
  const safeAnimalFields = safeArray(animalFields);
  const safeTreatments = safeArray(treatments);
  const safeControls = safeArray(controls);
  const safeGeneticImprovements = safeArray(geneticImprovements);

  const userAnimals = safeAnimals.filter(
    (animal: any) => animal?.user?.identification === user.identification
  );

  const userDiseases = safeAnimalDiseases.filter(
    (disease: any) => disease?.instructor?.identification === user.identification
  );

  const userFields = safeAnimalFields.filter(
    (field: any) => field?.animal?.user?.identification === user.identification
  );

  const userTreatments = safeTreatments.filter(
    (treatment: any) => treatment?.animals?.user?.identification === user.identification
  );

  const userControls = safeControls.filter(
    (control: any) => control?.animals?.user?.identification === user.identification
  );

  const userGenetics = safeGeneticImprovements.filter(
    (genetic: any) => genetic?.user?.identification === user.identification
  );

  // Create timeline activities from all data sources
  const timelineActivities = useMemo(() => {
    const activities: UserActivity[] = [];

    // Add animal creation activities
    userAnimals.forEach(animal => {
      activities.push({
        id: `animal-${animal.idAnimal}`,
        date: animal.birth_date,
        type: 'animal_created',
        title: `Animal Registrado: ${getAnimalLabel(animal)}`,
        description: `${animal.breed?.name || 'Sin raza'} - ${animal.gender} - Estado: ${animal.status}`,
        animalRecord: getAnimalLabel(animal),
        status: animal.status,
        icon: <Users className="w-4 h-4" />
      });
    });

    // Add disease treatment activities
    userDiseases.forEach(disease => {
      activities.push({
        id: `disease-${disease.id}`,
        date: disease.diagnosis_date,
        type: 'disease_treated',
        title: `Diagnóstico de Enfermedad`,
        description: `${disease.disease?.name} en animal ${getAnimalLabel(disease.animal)}`,
        animalRecord: getAnimalLabel(disease.animal),
        status: disease.status ? 'Activo' : 'Inactivo',
        icon: <Stethoscope className="w-4 h-4" />
      });
    });

    // Add control activities
    userControls.forEach(control => {
      activities.push({
        id: `control-${control.id}`,
        date: control.checkup_date,
        type: 'control_performed',
        title: `Control de Salud Realizado`,
        description: `Estado: ${control.healt_status} - ${control.description}`,
        animalRecord: getAnimalLabel(control.animals),
        status: control.healt_status,
        icon: <Activity className="w-4 h-4" />
      });
    });

    // Add treatment activities
    userTreatments.forEach(treatment => {
      activities.push({
        id: `treatment-${treatment.id}`,
        date: treatment.treatment_date,
        type: 'treatment_applied',
        title: `Tratamiento Aplicado`,
        description: `${treatment.description} - Animal: ${getAnimalLabel(treatment.animals)}`,
        animalRecord: getAnimalLabel(treatment.animals),
        status: 'Aplicado',
        icon: <Syringe className="w-4 h-4" />
      });
    });

    // Add genetic improvement activities
    userGenetics.forEach(genetic => {
      activities.push({
        id: `genetic-${genetic.id}`,
        date: genetic.date,
        type: 'genetic_improvement',
        title: `Mejora Genética`,
        description: `${genetic.genetic_event_techique} - Animal: ${getAnimalLabel(genetic.animal)}`,
        animalRecord: getAnimalLabel(genetic.animal),
        status: 'Completado',
        icon: <Activity className="w-4 h-4" />
      });
    });

    // Add field management activities
    userFields.forEach(field => {
      activities.push({
        id: `field-${field.id}`,
        date: field.treatment_date,
        type: 'field_management',
        title: `Gestión de Campo`,
        description: `Animal ${getAnimalLabel(field.animal)} en ${field.field?.name}`,
        animalRecord: getAnimalLabel(field.animal),
        status: field.end_date ? 'Completado' : 'Activo',
        icon: <MapPin className="w-4 h-4" />
      });
    });

    // Sort activities by date (most recent first)
    return activities.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [userAnimals, userDiseases, userControls, userTreatments, userGenetics, userFields]);

  // Filter timeline activities based on search and filters
  const filteredTimelineActivities = useMemo(() => {
    return timelineActivities.filter(activity => {
      const matchesSearch = searchTerm === "" || 
        activity.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        activity.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (activity.animalRecord && activity.animalRecord.toLowerCase().includes(searchTerm.toLowerCase()));
      
      const matchesType = selectedActivityType === "all" || activity.type === selectedActivityType;
      
      const matchesDateRange = selectedDateRange === "all" || (() => {
        const activityDate = new Date(activity.date);
        const now = new Date();
        const daysDiff = Math.floor((now.getTime() - activityDate.getTime()) / (1000 * 60 * 60 * 24));
        
        switch (selectedDateRange) {
          case "week": return daysDiff <= 7;
          case "month": return daysDiff <= 30;
          case "year": return daysDiff <= 365;
          default: return true;
        }
      })();
      
      return matchesSearch && matchesType && matchesDateRange;
    });
  }, [timelineActivities, searchTerm, selectedActivityType, selectedDateRange]);

  // Calculate statistics
  const stats = useMemo(() => {
    return {
      totalActivities: timelineActivities.length,
      animalsManaged: userAnimals.length,
      diseasesHandled: userDiseases.length,
      controlsPerformed: userControls.length,
      treatmentsApplied: userTreatments.length,
      geneticImprovements: userGenetics.length,
      recentActivities: timelineActivities.filter(activity => {
        const activityDate = new Date(activity.date);
        const thirtyDaysAgo = new Date();
        thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
        return activityDate >= thirtyDaysAgo;
      }).length
    };
  }, [timelineActivities, userAnimals, userDiseases, userControls, userTreatments, userGenetics]);

  const formatDate = (dateString: string) => {
    try {
      return format(new Date(dateString), "PPP", { locale: es });
    } catch (error) {
      return dateString;
    }
  };

  return (
    <Modal
      isOpen={true}
      onClose={onClose}
      size="2xl"
      description={`${user.fullname} • ${user.email}`}
      variant="compact"
      fullScreen
      allowFullScreenToggle
    >
      <ModalHeader>
        <span className="flex items-center gap-2">
          <User className="w-5 h-5" />
          Historial - {user.fullname}
          <Badge variant="secondary">{user.role}</Badge>
        </span>
      </ModalHeader>
      <ModalContent>
        <ModalBody>
          {/* User Info and Statistics */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-6 gap-4 mb-6">
            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium text-gray-500 flex items-center gap-1">
                  <IdCard className="w-4 h-4" />
                  Identificación
                </CardTitle>
              </CardHeader>
              <CardContent>
                <p className="text-lg font-semibold">{user.identification}</p>
              </CardContent>
            </Card>
            
            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium text-gray-500 flex items-center gap-1">
                  <Mail className="w-4 h-4" />
                  Email
                </CardTitle>
              </CardHeader>
              <CardContent>
                <p className="text-sm break-words">{user.email}</p>
              </CardContent>
            </Card>
            
            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium text-gray-500">Total Actividades</CardTitle>
              </CardHeader>
              <CardContent>
                <p className="text-2xl font-bold text-blue-600">{stats.totalActivities}</p>
                <p className="text-xs text-gray-500">{stats.recentActivities} últimos 30 días</p>
              </CardContent>
            </Card>
            
            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm font-medium text-gray-500">Animales</CardTitle>
              </CardHeader>
              <CardContent>
                <p className="text-2xl font-bold text-green-600">{stats.animalsManaged}</p>
              </CardContent>
            </Card>
            
