      </ModalContent>
    </Modal>
  );
};

export default UserHistoryModal;

import React, { useState, useEffect } from 'react';
import { Mic, Square, Trash2, Play, Pause, CircleCheck, Clock } from 'lucide-react';
import { voiceNoteService, type VoiceNote } from '@/shared/api/offline/VoiceNoteService';
import { motion, AnimatePresence } from 'framer-motion';
import { useFieldMode } from '@/app/providers/FieldModeContext';

export const VoiceNoteWidget: React.FC = () => {
  const [isRecording, setIsRecording] = useState(false);
  const [notes, setNotes] = useState<VoiceNote[]>([]);
  const [playingId, setPlayingId] = useState<string | null>(null);
  const [audioElement, setAudioElement] = useState<HTMLAudioElement | null>(null);
  const { isFieldMode } = useFieldMode();

  useEffect(() => {
    loadNotes();
    // Recargar cada 30s para ver cambios de estado de sync
    const interval = setInterval(loadNotes, 30000);
    return () => clearInterval(interval);
  }, []);

  const loadNotes = async () => {
    const localNotes = await voiceNoteService.getNotes();
    setNotes(localNotes.sort((a, b) => b.timestamp - a.timestamp));
  };

  const handleStartRecording = async () => {
    try {
      await voiceNoteService.startRecording();
      setIsRecording(true);
    } catch (err) {
      alert('No se pudo acceder al micrófono');
    }
  };

  const handleStopRecording = async () => {
    await voiceNoteService.stopRecording();
    setIsRecording(false);
    loadNotes();
  };

  const handlePlay = (note: VoiceNote) => {
    if (playingId === note.id) {
      audioElement?.pause();
      setPlayingId(null);
      return;
    }

    if (audioElement) {
      audioElement.pause();
    }

    const url = URL.createObjectURL(note.blob);
    const audio = new Audio(url);
    audio.onended = () => {
      setPlayingId(null);
      URL.revokeObjectURL(url);
    };
    audio.play();
    setAudioElement(audio);
    setPlayingId(note.id);
  };

  const handleDelete = async (id: string) => {
    if (confirm('¿Borrar esta nota de voz?')) {
      await voiceNoteService.deleteNote(id);
      loadNotes();
    }
  };

  return (
    <div className={`bg-white rounded-2xl p-6 border border-gray-100 shadow-sm ${isFieldMode ? 'border-4 border-white bg-black text-white' : ''}`}>
      <div className="flex items-center justify-between mb-6">
        <div>
          <h3 className={`text-lg font-bold ${isFieldMode ? 'text-white uppercase text-2xl' : 'text-gray-900'}`}>Notas de Voz</h3>
          <p className={`text-sm ${isFieldMode ? 'text-gray-300' : 'text-gray-500'}`}>Graba novedades sin escribir</p>
        </div>
        <div className={`p-2 rounded-full ${isRecording ? 'bg-red-500 animate-pulse' : 'bg-blue-50'}`}>
          <Mic size={20} className={isRecording ? 'text-white' : 'text-blue-600'} />
        </div>
      </div>

      {/* Botón de Grabación Principal */}
      <div className="flex justify-center mb-8">
        {!isRecording ? (
          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            onClick={handleStartRecording}
            className={`flex flex-col items-center justify-center gap-3 w-40 h-40 rounded-full transition-all shadow-xl ${
              isFieldMode 
                ? 'bg-green-600 border-4 border-white' 
                : 'bg-blue-600 text-white hover:bg-blue-700'
            }`}
          >
            <Mic size={48} />
            <span className="font-bold uppercase tracking-widest text-xs">Grabar Ahora</span>
          </motion.button>
        ) : (
          <motion.button
            initial={{ scale: 0.8 }}
            animate={{ scale: 1 }}
            onClick={handleStopRecording}
            className={`flex flex-col items-center justify-center gap-3 w-40 h-40 rounded-full bg-red-600 text-white shadow-xl shadow-red-500/20 border-4 border-white`}
          >
            <Square size={48} />
            <span className="font-bold uppercase tracking-widest text-xs">Terminar</span>
          </motion.button>
        )}
      </div>

      {/* Lista de Notas Recientes */}
      <div className="space-y-3 max-h-60 overflow-y-auto pr-2 scrollbar-thin">
        <AnimatePresence>
          {notes.map((note) => (
            <motion.div
              key={note.id}
              initial={{ opacity: 0, x: -10 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: 10 }}
              className={`flex items-center justify-between p-3 rounded-xl border ${
                isFieldMode 
                  ? 'bg-zinc-900 border-white' 
                  : 'bg-gray-50 border-gray-100'
              }`}
            >
              <div className="flex items-center gap-3">
                <button
                  onClick={() => handlePlay(note)}
                  className={`p-2 rounded-full ${isFieldMode ? 'bg-white text-black' : 'bg-white shadow-sm text-blue-600'}`}
                >
                  {playingId === note.id ? <Pause size={18} /> : <Play size={18} />}
                </button>
                <div>
                  <p className={`text-xs font-bold ${isFieldMode ? 'text-white' : 'text-gray-700'}`}>
                    {new Date(note.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </p>
                  <p className={`text-[10px] ${isFieldMode ? 'text-gray-400' : 'text-gray-500'}`}>
                    {note.duration} segundos
                  </p>
                </div>
              </div>

              <div className="flex items-center gap-3">
                {note.status === 'completed' ? (
                  <span title="Sincronizado">
                    <CircleCheck size={16} className="text-green-500" />
                  </span>
                ) : (
                  <span title="Pendiente de envío">
                    <Clock size={16} className="text-amber-500 animate-pulse" />
                  </span>
                )}
                <button
                  onClick={() => handleDelete(note.id)}
                  className="text-gray-400 hover:text-red-500 transition-colors"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            </motion.div>
          ))}
        </AnimatePresence>

        {notes.length === 0 && !isRecording && (
          <div className="text-center py-8 opacity-50">
            <p className="text-sm">No tienes notas guardadas</p>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { MapPin, User as UserIcon, RefreshCw, Navigation } from 'lucide-react';
import { locationService, UserLocation } from '@/entities/user/api/location.service';

/**
 * WorkerMap: Visualización de personal en el campo.
 * En un entorno real, usaría Leaflet/Google Maps.
 * Aquí usamos una representación SVG de la Finca Villa Luz para un diseño 'Premium' y rápido.
 */
export const WorkerMap: React.FC = () => {
  const [workers, setWorkers] = useState<UserLocation[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchPositions = async () => {
    try {
      const res = await locationService.getLatestPositions();
      setWorkers(res.data || []);
    } catch (error) {
      console.error('Error al cargar posiciones:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPositions();
    const interval = setInterval(fetchPositions, 30000); // Actualizar cada 30s
    return () => clearInterval(interval);
  }, []);

  // Coordenadas de referencia para la Finca Villa Luz (SENA)
  // Lat: 5.9558, Long: -73.6498
  const fincaBounds = {
    minLat: 5.950, maxLat: 5.965,
    minLong: -73.655, maxLong: -73.640
  };

  // Conversión simple de Lat/Long a coordenadas SVG (0-100)
  const getCoords = (lat: number, lng: number) => {
    const x = ((lng - fincaBounds.minLong) / (fincaBounds.maxLong - fincaBounds.minLong)) * 100;
    const y = 100 - (((lat - fincaBounds.minLat) / (fincaBounds.maxLat - fincaBounds.minLat)) * 100);
    return { x, y };
  };

  return (
    <div className="bg-white rounded-3xl overflow-hidden border border-gray-100 shadow-sm flex flex-col h-[600px]">
      <div className="p-6 border-b border-gray-50 flex items-center justify-between bg-white/50 backdrop-blur-md">
        <div>
          <h3 className="text-xl font-bold text-gray-900 flex items-center gap-2">
            <Navigation className="text-green-600" size={20} />
            Mapa de Operaciones en Campo
          </h3>
          <p className="text-sm text-gray-500">Localización en tiempo real vía Red Mesh</p>
        </div>
        <button 
          onClick={() => fetchPositions()}
          className="p-2 hover:bg-gray-100 rounded-full transition-colors text-gray-400 hover:text-green-600"
          title="Refrescar posiciones"
        >
          <RefreshCw size={20} className={loading ? 'animate-spin' : ''} />
        </button>
      </div>

      <div className="flex-1 relative bg-slate-50 overflow-hidden">
        {/* Capa de Mapa SVG (Representación de la Finca) */}
        <svg viewBox="0 0 100 100" className="w-full h-full preserve-3d">
          {/* Fondo de terreno */}
          <rect width="100" height="100" fill="#f8fafc" />
          
          {/* Potreros (Polígonos simulados) */}
          <path d="M10,20 L40,15 L45,40 L15,45 Z" fill="#ecfdf5" stroke="#10b981" strokeWidth="0.2" />
          <path d="M45,15 L80,10 L85,35 L50,40 Z" fill="#f0fdf4" stroke="#22c55e" strokeWidth="0.2" />
          <path d="M15,50 L45,45 L40,80 L10,75 Z" fill="#f0fdf4" stroke="#22c55e" strokeWidth="0.2" />
          <path d="M50,45 L90,40 L85,85 L55,80 Z" fill="#ecfdf5" stroke="#10b981" strokeWidth="0.2" />
          
          {/* Caminos Internos */}
          <path d="M45,0 L45,100 M0,45 L100,45" stroke="#e2e8f0" strokeWidth="0.5" strokeDasharray="1,1" />

          {/* Marcadores de Trabajadores */}
          {workers.map((worker) => {
            const { x, y } = getCoords(worker.latitude, worker.longitude);
            return (
              <motion.g
                key={worker.id}
                initial={{ scale: 0 }}
                animate={{ scale: 1, x: `${x}%`, y: `${y}%` }}
                className="cursor-pointer"
                style={{ originX: "50%", originY: "50%" }}
              >
                {/* Sombra/Halo de señal */}
                <circle r="3" fill={worker.detection_method === 'GPS' ? '#3b82f6' : '#10b981'} className="animate-ping opacity-20" />
                
                {/* Pin */}
                <g transform="translate(-2, -5)">
                  <path d="M2,0 C0.895,0 0,0.895 0,2 C0,3.5 2,5 2,5 C2,5 4,3.5 4,2 C4,0.895 3.105,0 2,0 Z" fill={worker.detection_method === 'GPS' ? '#2563eb' : '#059669'} />
                  <circle cx="2" cy="2" r="0.8" fill="white" />
                </g>

                {/* Etiqueta (Tooltip simulado) */}
                <foreignObject x="3" y="-8" width="80" height="40" className="overflow-visible pointer-events-none">
                  <div className="bg-white/90 backdrop-blur-sm border border-gray-100 rounded-lg p-1.5 shadow-xl">
                    <p className="text-[8px] font-bold text-gray-900 leading-none whitespace-nowrap">Usuario #{worker.user_id}</p>
                    <p className="text-[6px] text-gray-500 mt-0.5">{worker.detection_method} • {new Date(worker.created_at).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                  </div>
                </foreignObject>
              </motion.g>
            );
          })}
        </svg>

        {/* Leyenda */}
