    {
      id: -Math.abs((animalId || 1) * 10),
      animal_id: animalId,
      filename: 'referencia-profesional.png',
      filepath: '',
      file_size: 0,
      mime_type: 'image/png',
      is_primary: true,
      url: animalReferenceImg,
      created_at: '',
      updated_at: '',
      isPlaceholder: true,
    }
  ];
}

const DEFAULT_ANIMAL_PLACEHOLDER = animalReferenceImg;

function AnimalPhotoPlaceholder({
