          </DialogHeader>
          {selectedImage && (
            <div
              className="fixed inset-0 w-screen h-screen flex items-center justify-center bg-black z-50"
              onTouchStart={handleTouchStart}
              onTouchMove={handleTouchMove}
              onTouchEnd={handleTouchEnd}
            >
              {/* Contenedor de imágenes del carrusel en modal - ocupa todo el viewport */}
              <div className="absolute inset-0 w-screen h-screen">
                {images.map((image, index) => (
                  <div
                    key={image.id}
                    className={`absolute inset-0 w-screen h-screen flex items-center justify-center transition-all duration-700 ease-out ${index === currentIndex
                      ? 'opacity-100 scale-100 z-10 carousel-slide-active'
                      : 'opacity-0 scale-95 z-0 blur-sm carousel-slide-inactive'
                      }`}
                  >
                    {imageErrors.has(image.id) ? (
                      <div className="w-full h-full flex items-center justify-center">
                        <div className="text-center">
                          <ImageIcon className="w-16 h-16 mx-auto text-white/30 mb-2" />
                          <p className="text-sm text-white/50">No se pudo cargar la imagen</p>
                        </div>
                      </div>
                    ) : (
                      <img
                        src={image.url}
                        alt={image.filename}
                        className="max-w-full max-h-full w-auto h-auto object-contain animate-in fade-in zoom-in duration-700 carousel-image-modal"
                        decoding="async"
                        loading="eager"
                        onError={() => {
                          setImageErrors(prev => new Set(prev).add(image.id));
                        }}
                      />
                    )}
                  </div>
                ))}
              </div>

              {/* Controles de navegación modernos y llamativos */}
              {images.length > 1 && (
                <>
                  {/* Botón anterior - diseño moderno con gradiente */}
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      goToPrevious();
                    }}
                    disabled={isTransitioning}
                    className="group absolute left-6 sm:left-10 top-1/2 -translate-y-1/2 z-30
                      p-4 sm:p-5
                      rounded-2xl
                      bg-gradient-to-br from-white/20 to-white/5 hover:from-white/30 hover:to-white/10
                      text-white backdrop-blur-xl
                      shadow-2xl border border-white/30
                      disabled:opacity-30 disabled:cursor-not-allowed
                      transform hover:scale-110 hover:-translate-x-1 active:scale-95
                      transition-all duration-300"
                    aria-label="Imagen anterior"
                  >
                    <ChevronLeft className="w-7 h-7 sm:w-9 sm:h-9 drop-shadow-lg group-hover:drop-shadow-2xl transition-all" />
                  </button>

                  {/* Botón siguiente - diseño moderno con gradiente */}
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      goToNext();
                    }}
                    disabled={isTransitioning}
                    className="group absolute right-6 sm:right-10 top-1/2 -translate-y-1/2 z-30
                      p-4 sm:p-5
                      rounded-2xl
                      bg-gradient-to-br from-white/20 to-white/5 hover:from-white/30 hover:to-white/10
                      text-white backdrop-blur-xl
                      shadow-2xl border border-white/30
                      disabled:opacity-30 disabled:cursor-not-allowed
                      transform hover:scale-110 hover:translate-x-1 active:scale-95
                      transition-all duration-300"
                    aria-label="Imagen siguiente"
                  >
                    <ChevronRight className="w-7 h-7 sm:w-9 sm:h-9 drop-shadow-lg group-hover:drop-shadow-2xl transition-all" />
                  </button>

                  {/* Indicadores de puntos modernos con efecto de brillo */}
                  <div className="absolute bottom-8 sm:bottom-12 left-0 right-0 flex justify-center gap-2 z-30 px-4">
                    <div className="flex gap-2.5 sm:gap-3 bg-gradient-to-r from-white/10 via-white/15 to-white/10 backdrop-blur-xl rounded-full px-6 py-3 sm:px-8 sm:py-4 border border-white/30 shadow-2xl">
                      {images.map((_, index) => (
                        <button
                          key={index}
                          onClick={(e) => {
                            e.stopPropagation();
                            goToIndex(index);
                          }}
                          disabled={isTransitioning}
                          className={`rounded-full transition-all duration-500 disabled:cursor-not-allowed
                            ${index === currentIndex
                              ? 'bg-gradient-to-r from-white via-white/90 to-white shadow-[0_0_20px_rgba(255,255,255,0.8)] w-10 sm:w-12 h-3 sm:h-3.5 scale-110'
                              : 'bg-white/40 hover:bg-white/60 active:bg-white/80 shadow-md w-3 sm:w-3.5 h-3 sm:h-3.5 hover:scale-110'
                            }`}
                          aria-label={`Ir a imagen ${index + 1}`}
                          aria-current={index === currentIndex ? 'true' : 'false'}
                        />
                      ))}
                    </div>
                  </div>

                  {/* Contador de imágenes con diseño moderno */}
                  <div className="absolute top-8 sm:top-10 left-8 sm:left-10 z-30">
                    <div className="bg-gradient-to-br from-white/20 to-white/5 backdrop-blur-xl text-white px-6 py-3 sm:px-7 sm:py-3.5 rounded-2xl text-base sm:text-lg font-semibold shadow-2xl border border-white/30">
                      <span className="drop-shadow-lg">{currentIndex + 1}</span>
                      <span className="mx-2 opacity-60">/</span>
                      <span className="opacity-80 drop-shadow-lg">{images.length}</span>
                    </div>
                  </div>
                </>
              )}

              {/* Botón de cierre moderno - top right */}
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  setSelectedImage(null);
                }}
                className="group absolute top-8 sm:top-10 right-8 sm:right-10 z-30
                  p-3 sm:p-4
                  rounded-2xl
                  bg-gradient-to-br from-red-500/30 to-red-600/20 hover:from-red-500/50 hover:to-red-600/40
                  text-white backdrop-blur-xl
                  shadow-2xl border border-red-400/40
                  transform hover:scale-110 hover:rotate-90 active:scale-95
                  transition-all duration-300"
                aria-label="Cerrar"
              >
                <svg className="w-6 h-6 sm:w-7 sm:h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>

              {/* Información minimalista - solo aparece en hover */}
              <div className="absolute bottom-28 sm:bottom-32 left-0 right-0 flex justify-center z-20 px-4 opacity-0 hover:opacity-100 transition-opacity duration-500 group-hover:opacity-100">
                <div className="bg-white/5 backdrop-blur-md text-white/70 px-4 py-2 sm:px-5 sm:py-2.5 rounded-full text-xs sm:text-sm font-light shadow-lg border border-white/10">
                  {images[currentIndex].filename.replace(/\.(jpg|jpeg|png|gif|webp)$/i, '')}
                </div>
              </div>

              {/* Overlay de gradiente sutil en los bordes para efecto cinematográfico */}
              <div className="absolute inset-0 pointer-events-none z-[5]">
                <div className="absolute inset-0 bg-gradient-to-t from-black/30 via-transparent to-black/20" />
                <div className="absolute inset-0 bg-gradient-to-r from-black/20 via-transparent to-black/20" />
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </>
  );
}

export default AnimalImageBanner;

import React, { useState, useEffect, useCallback } from 'react';
import {
  Image as ImageIcon,
  Star,
  Trash2,
  ZoomIn,
  Download,
  Loader2,
  CircleAlert,
  MoreVertical,
} from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Badge } from '@/shared/ui/badge';
import { Alert, AlertDescription } from '@/shared/ui/alert';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/shared/ui/dialog';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/shared/ui/dropdown-menu';
import {
  animalImageService,
  type AnimalImage,
} from '@/entities/animal/api/animalImage.service';
import {
  formatAnimalImageName,
  getAnimalImageId,
} from '@/entities/animal/lib/animalImageUtils';

interface AnimalImageGalleryProps {
  animalId: number;
  /** Callback cuando se actualiza la galería */
  onGalleryUpdate?: () => void;
  /** Mostrar controles de edición */
  showControls?: boolean;
  /** Trigger externo para recargar las imágenes */
  refreshTrigger?: number;
  /**
   * Solicitud para abrir la UI de subida desde el estado vacío
   * Si no se provee, se emitirá el evento global usado por `AnimalImageManager`
   */
  onRequestUpload?: () => void;
}

export function AnimalImageGallery({
  animalId,
  onGalleryUpdate,
  showControls = true,
  refreshTrigger = 0,
  onRequestUpload,
}: AnimalImageGalleryProps) {
  const [images, setImages] = useState<AnimalImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedImage, setSelectedImage] = useState<AnimalImage | null>(null);
  const [deletingId, setDeletingId] = useState<number | null>(null);
  const [settingPrimaryId, setSettingPrimaryId] = useState<number | null>(null);
  const [imageErrors, setImageErrors] = useState<Set<number>>(new Set());
  const selectedImageId = selectedImage ? getAnimalImageId(selectedImage) : null;
  const selectedImageHasError =
    selectedImageId !== null && imageErrors.has(selectedImageId);

  // Cargar imágenes
  const fetchImages = useCallback(async () => {
    if (!animalId || animalId <= 0) {
      setError('ID de animal inválido');
      setLoading(false);
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const response = await animalImageService.getAnimalImages(animalId);

      if (response.success) {
        setImages(response.data.images || []);
        setError(null);
      } else if (response.errorCode === 'NOT_FOUND') {
        // El backend indica que el recurso no existe: mostrar vacío sin marcar error
        setImages([]);
        setError(null);
      } else {
        setImages([]);
        setError(response.message || 'Error al cargar imágenes');
      }
    } catch (err: any) {
      const errorMessage =
        err.response?.data?.message ||
        err.message ||
        'Error al cargar imágenes';
      setImages([]);
      setError(errorMessage);
    } finally {
      setLoading(false);
    }
  }, [animalId]);

  // Cargar imágenes al montar y cuando cambie el trigger
  useEffect(() => {
    fetchImages();
  }, [fetchImages, refreshTrigger]);

  // Escuchar evento global de actualización de imágenes para refrescar sin recargar la página
  useEffect(() => {
    const handler = (e: Event) => {
      const detail = (e as CustomEvent).detail as { animalId?: number; uploaded?: any[] } | undefined;
      if (!detail || detail.animalId === animalId) {
        fetchImages();
        if (detail?.uploaded?.length) {
          setTimeout(fetchImages, 800);
          setTimeout(fetchImages, 1600);
        }
      }
    };
    window.addEventListener('animal-images:updated', handler as EventListener);
    return () => {
      window.removeEventListener('animal-images:updated', handler as EventListener);
    };
  }, [animalId, fetchImages]);

  // Establecer imagen principal
  const handleSetPrimary = useCallback(
    async (imageId: number) => {
      setSettingPrimaryId(imageId);
      setError(null);

      try {
        await animalImageService.setPrimaryImage(imageId);

        // Actualizar estado local
        setImages((prev) =>
          prev.map((img) => ({
            ...img,
            is_primary: img.id === imageId,
          }))
        );

        if (onGalleryUpdate) {
          onGalleryUpdate();
        }
      } catch (err: any) {
        const errorMessage =
          err.response?.data?.message ||
          err.message ||
          'Error al establecer imagen principal';
        setError(errorMessage);
      } finally {
        setSettingPrimaryId(null);
      }
    },
    [onGalleryUpdate]
  );

  // Eliminar imagen
  const handleDelete = useCallback(
    async (image: AnimalImage) => {
      const imageId = getAnimalImageId(image);
      if (imageId === null) {
        setError('No se pudo determinar el identificador de la imagen.');
        return;
      }

      const confirmationLabel = formatAnimalImageName(image);
      if (!confirm(`¿Está seguro de eliminar ${confirmationLabel}?`)) {
        return;
      }

      setDeletingId(imageId);
      setError(null);

      try {
        await animalImageService.deleteImage(imageId);

        setImages((prev) =>
          prev.filter((img) => getAnimalImageId(img) !== imageId)
        );

        // Asegurar que los listeners globales refresquen banners/galerías
        setTimeout(() => {
          window.dispatchEvent(
            new CustomEvent('animal-images:updated', { detail: { animalId } })
          );
        }, 0);
        if (onGalleryUpdate) {
          onGalleryUpdate();
        }
      } catch (err: any) {
        const status = err?.response?.status;
        const defaultMessage = 'No se pudo eliminar la imagen. Intenta nuevamente.';
        const errorMessage = err?.message || err?.response?.data?.message || defaultMessage;

        if (err?.code === 'AUTH_REQUIRED') {
          setError(
            errorMessage || 'Tu sesión expiró. Vuelve a iniciar sesión para administrar las imágenes.'
          );
        } else {
          setError(errorMessage);
        }

        if (status && status >= 500) {
          console.warn('[AnimalImageGallery] Error 5xx al eliminar imagen:', status);
        }
      } finally {
        setDeletingId(null);
      }
    },
    [animalId, onGalleryUpdate]
  );

  // Descargar imagen
  const handleDownload = useCallback((image: AnimalImage) => {
    const link = document.createElement('a');
    link.href = image.url;
    link.download = image.filename;
    link.target = '_blank';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }, []);

  // Loading state
  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="text-center space-y-3">
          <Loader2 className="w-8 h-8 animate-spin mx-auto text-primary" />
          <p className="text-sm text-muted-foreground">Cargando imágenes...</p>
        </div>
      </div>
    );
  }

  // Error state
  if (error && images.length === 0) {
    return (
      <Alert variant="destructive">
        <CircleAlert className="h-4 w-4" />
        <AlertDescription>{error}</AlertDescription>
      </Alert>
    );
  }

  // Empty state
  if (images.length === 0) {
    return (
      <div className="flex flex-col items-center gap-3 py-6 text-center text-muted-foreground">
        <div className="flex flex-col items-center gap-1.5">
          <ImageIcon className="w-8 h-8 text-muted-foreground/70" />
          <p className="text-sm">Aún no hay imágenes para este animal</p>
        </div>
        <Button
          type="button"
          variant="ghost"
          size="sm"
          onClick={() => {
            if (onRequestUpload) {
              onRequestUpload();
            } else {
              const uploadTabEvent = new CustomEvent('open-upload-tab', {
                detail: { animalId }
              });
              window.dispatchEvent(uploadTabEvent);
            }
          }}
          className="gap-1.5 rounded-full border border-dashed border-primary/40 px-3 py-1.5 text-xs font-medium text-primary hover:bg-primary/5"
        >
          <ImageIcon className="w-4 h-4" />
          Subir imagen
        </Button>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Error temporal (cuando hay imágenes pero falla una operación) */}
      {error && images.length > 0 && (
        <Alert variant="destructive">
          <CircleAlert className="h-4 w-4" />
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      )}

      {/* Info */}
      <div className="flex items-center justify-between">
        <p className="text-sm text-muted-foreground">
          {images.length} imagen(es)
        </p>
      </div>

      {/* Galería */}
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
        {images.map((image, index) => {
          const numericId = getAnimalImageId(image);
          const itemKey =
            numericId !== null ? `animal-image-${numericId}` : `animal-image-${index}`;
          const hasError = numericId !== null && imageErrors.has(numericId);
          const isDeleting = numericId !== null && deletingId === numericId;
          const isSettingPrimary = numericId !== null && settingPrimaryId === numericId;

          return (
            <div
              key={itemKey}
              className="relative group aspect-square rounded-lg overflow-hidden border bg-accent/5 hover:shadow-lg transition-all"
            >
              {/* Imagen */}
              {hasError ? (
                <div
                  className="w-full h-full flex items-center justify-center bg-muted/20 cursor-pointer"
                  onClick={() => setSelectedImage(image)}
                >
                  <div className="text-center">
                    <ImageIcon className="w-8 h-8 mx-auto text-muted-foreground mb-1" />
                    <p className="text-xs text-muted-foreground">Error</p>
                  </div>
                </div>
              ) : (
                <img
                  src={image.url}
                  alt={image.filename}
                  className="w-full h-full object-cover cursor-pointer transition-transform duration-300 hover:scale-110 gallery-image-thumb"
                  onClick={() => setSelectedImage(image)}
                  loading="lazy"
                  onError={() => {
                    if (numericId !== null) {
                      setImageErrors((prev) => {
                        const next = new Set(prev);
                        next.add(numericId);
                        return next;
                      });
                    }
                  }}
                />
              )}

              {/* Badge de imagen principal */}
              {image.is_primary && (
                <div className="absolute top-2 left-2">
                  <Badge className="bg-yellow-500 hover:bg-yellow-600 text-white">
                    <Star className="w-3 h-3 mr-1 fill-current" />
                    Principal
                  </Badge>
                </div>
              )}

              {/* Botón de ver imagen */}
              <div
                className="absolute inset-0 bg-black/0 group-hover:bg-black/40 transition-colors flex items-center justify-center cursor-pointer"
                onClick={() => setSelectedImage(image)}
              >
                <Button
                  type="button"
                  variant="secondary"
                  size="icon"
                  className="opacity-0 group-hover:opacity-100 transition-opacity"
                  title="Ver en grande"
                >
                  <ZoomIn className="w-5 h-5" />
                </Button>
              </div>

              {/* Menú desplegable de acciones (esquina superior derecha) */}
              {showControls && (
                <div className="absolute top-2 right-2 z-10">
                  <DropdownMenu modal={false}>
                    <DropdownMenuTrigger asChild>
                      <Button
                        type="button"
                        variant="secondary"
                        size="icon"
                        className="h-8 w-8 opacity-0 group-hover:opacity-100 transition-opacity shadow-lg"
                        onClick={(e) => e.stopPropagation()}
                      >
                        <MoreVertical className="w-4 h-4" />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end" className="w-48">
                      <DropdownMenuItem
                        onClick={(e) => {
                          e.stopPropagation();
                          setSelectedImage(image);
                        }}
                      >
                        <ZoomIn className="w-4 h-4 mr-2" />
                        Ver en grande
                      </DropdownMenuItem>

                      <DropdownMenuItem
                        onClick={(e) => {
                          e.stopPropagation();
                          handleDownload(image);
                        }}
                      >
                        <Download className="w-4 h-4 mr-2" />
                        Descargar
                      </DropdownMenuItem>

                      {!image.is_primary && (
                        <>
                          <DropdownMenuSeparator />
                          <DropdownMenuItem
                            onClick={(e) => {
                              e.stopPropagation();
                              if (numericId !== null) {
                                handleSetPrimary(numericId);
                              }
                            }}
                            disabled={isSettingPrimary}
                          >
                            {isSettingPrimary ? (
                              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                            ) : (
                              <Star className="w-4 h-4 mr-2" />
                            )}
                            Establecer como principal
                          </DropdownMenuItem>
                        </>
                      )}

                      <DropdownMenuSeparator />
                      <DropdownMenuItem
                        onClick={(e) => {
                          e.stopPropagation();
                          handleDelete(image);
                        }}
                        disabled={isDeleting}
                        className="text-destructive focus:text-destructive"
                      >
                        {isDeleting ? (
                          <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                        ) : (
                          <Trash2 className="w-4 h-4 mr-2" />
                        )}
                        Eliminar
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </div>
              )}

              {/* Info del archivo */}
              <div className="absolute bottom-0 left-0 right-0 p-2 bg-gradient-to-t from-black/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity">
                <p className="text-xs text-white truncate" title={image.filename}>
                  {image.filename}
                </p>
                <p className="text-xs text-white/70">
                  {(image.file_size / 1024).toFixed(0)} KB
                </p>
              </div>
            </div>
          );
        })}
      </div>

      {/* Modal de vista previa - pantalla completa */}
      <Dialog
        open={selectedImage !== null}
        onOpenChange={(open) => !open && setSelectedImage(null)}
      >
        <DialogContent
          className="max-w-[100vw] max-h-[100vh] w-screen h-screen p-0 bg-black border-none overflow-hidden rounded-none m-0 fixed inset-0"
          onPointerDownOutside={(e) => e.preventDefault()}
          onInteractOutside={(e) => e.preventDefault()}
        >
          <DialogHeader className="sr-only">
            <DialogTitle className="flex items-center gap-2">
              {selectedImage?.is_primary && (
                <Star className="w-5 h-5 text-yellow-500 fill-current" />
              )}
              {selectedImage?.filename}
            </DialogTitle>
            <DialogDescription>
              {selectedImage &&
                `${(selectedImage.file_size / 1024).toFixed(2)} KB - ${selectedImage.mime_type
                } - Subida el ${new Date(
                  selectedImage.created_at
                ).toLocaleDateString('es-ES')}`}
            </DialogDescription>
          </DialogHeader>

          {selectedImage && (
            <div className="absolute inset-0 w-full h-full flex items-center justify-center overflow-hidden bg-black group">
              {/* Imagen a pantalla completa */}
              {selectedImageHasError ? (
                <div className="w-full h-full flex items-center justify-center">
                  <div className="text-center">
                    <ImageIcon className="w-16 h-16 mx-auto text-muted-foreground mb-2" />
                    <p className="text-sm text-muted-foreground">No se pudo cargar la imagen</p>
                  </div>
                </div>
              ) : (
                <img
                  src={selectedImage.url}
                  alt={selectedImage.filename}
                  className="w-full h-full gallery-image-fullscreen"
                  decoding="async"
                  onError={() => {
                    if (selectedImageId !== null) {
                      setImageErrors((prev) => {
                        const next = new Set(prev);
                        next.add(selectedImageId);
                        return next;
                      });
                    }
                  }}
                />
              )}

              {/* Información de la imagen - aparece solo en hover */}
              <div className="absolute bottom-4 left-0 right-0 flex justify-center z-10 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                <div className="bg-black/80 backdrop-blur-md text-white px-6 py-3 rounded-full text-sm font-medium shadow-2xl border border-white/10">
                  {selectedImage.filename} • {(selectedImage.file_size / 1024).toFixed(0)} KB • {selectedImage.mime_type}
                  {selectedImage.is_primary && (
                    <span className="ml-2 text-yellow-400">⭐ Principal</span>
                  )}
                </div>
              </div>

              {/* Indicador de cierre - aparece solo en hover */}
              <div className="absolute top-4 right-4 z-10 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                <div className="bg-black/80 backdrop-blur-md text-white/70 px-4 py-2 rounded-full text-xs font-medium shadow-2xl border border-white/10">
                  ESC para cerrar
                </div>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Image as ImageIcon, Upload as UploadIcon } from 'lucide-react';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/shared/ui/tabs';
import { AnimalImageUpload } from './AnimalImageUpload';
import { AnimalImageGallery } from './AnimalImageGallery';

interface AnimalImageManagerProps {
  animalId: number;
  /** Título del componente */
  title?: string;
  /** Mostrar controles de edición */
  showControls?: boolean;
  /** Comprimir imágenes al subir */
  compress?: boolean;
  /** Calidad de compresión (0-1) */
  quality?: number;
  /** Máximo de archivos permitidos */
  maxFiles?: number;
  /** Callback cuando las imágenes se actualizan (para refrescar otros componentes) */
  onImagesUpdate?: () => void;
}

/**
 * Componente completo para gestionar imágenes de animales
 * Combina subida de imágenes y galería en una interfaz de pestañas
 */
export function AnimalImageManager({
  animalId,
  title = 'Imágenes del Animal',
  showControls = true,
  compress = true,
  quality = 0.8,
  maxFiles = 20,
  onImagesUpdate,
}: AnimalImageManagerProps) {
  const [activeTab, setActiveTab] = useState<string>('gallery');
  const [galleryRefreshTrigger, setGalleryRefreshTrigger] = useState(0);

  // Escuchar evento para abrir la pestaña de subida
  useEffect(() => {
    const handleOpenUploadTab = (e: Event) => {
      const detail = (e as CustomEvent).detail as { animalId?: number } | undefined;
      if (!detail || detail.animalId === animalId) {
        setActiveTab('upload');
      }
    };
    
    window.addEventListener('open-upload-tab', handleOpenUploadTab as EventListener);
    return () => {
      window.removeEventListener('open-upload-tab', handleOpenUploadTab as EventListener);
    };
  }, [animalId]);

  // Manejar éxito de subida
  const handleUploadSuccess = () => {
    // Cambiar a la pestaña de galería
    setActiveTab('gallery');
    // Disparar refresh de la galería
    setGalleryRefreshTrigger((prev) => prev + 1);
    // Notificar a componentes externos (como el banner)
    if (onImagesUpdate) {
      onImagesUpdate();
    }
  };

  return (
    <div className="space-y-4">
      {/* Título */}
      {title && (
        <div className="flex items-center gap-2">
          <ImageIcon className="w-5 h-5 text-primary" />
          <h3 className="text-lg font-semibold">{title}</h3>
        </div>
      )}

      {/* Tabs */}
      <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
        <TabsList className="grid w-full grid-cols-2">
          <TabsTrigger value="gallery" className="gap-2">
            <ImageIcon className="w-4 h-4" />
            Galería
          </TabsTrigger>
          <TabsTrigger value="upload" className="gap-2">
            <UploadIcon className="w-4 h-4" />
            Subir Imágenes
          </TabsTrigger>
        </TabsList>

        <TabsContent value="gallery" className="mt-4">
          <AnimalImageGallery
            animalId={animalId}
            showControls={showControls}
            refreshTrigger={galleryRefreshTrigger}
            onGalleryUpdate={() => {
              setGalleryRefreshTrigger((prev) => prev + 1);
              // Notificar también a componentes externos
              if (onImagesUpdate) {
                onImagesUpdate();
              }
            }}
          />
        </TabsContent>

        <TabsContent value="upload" className="mt-4">
          <AnimalImageUpload
            animalId={animalId}
            onUploadSuccess={handleUploadSuccess}
            maxFiles={maxFiles}
            compress={compress}
            quality={quality}
          />
        </TabsContent>
      </Tabs>
    </div>
  );
}

import React, { useState, useRef, useCallback } from 'react';
import { Upload, X, Image as ImageIcon } from 'lucide-react';
import { Button } from '@/shared/ui/button';

const ALLOWED_IMAGE_EXTENSIONS = ['jpg', 'jpeg', 'png', 'webp', 'gif'];
const ALLOWED_IMAGE_MIME_TYPES = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];

interface FilePreview {
  file: File;
  preview: string;
  id: string;
}

interface AnimalImagePreUploadProps {
  files: File[];
  onChange: (files: File[]) => void;
  maxFiles?: number;
}

/**
 * Componente para seleccionar imágenes durante la creación de un animal
 * Las imágenes se almacenan localmente y se subirán después de crear el animal
 */
export function AnimalImagePreUpload({
  files: _externalFiles,
  onChange,
  maxFiles = 20,
}: AnimalImagePreUploadProps) {
  const [filePreviews, setFilePreviews] = useState<FilePreview[]>([]);
  const [dragActive, setDragActive] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const isImageFile = useCallback((file: File) => {
    if (file.type) return ALLOWED_IMAGE_MIME_TYPES.includes(file.type);
    const ext = file.name.split('.').pop()?.toLowerCase();
    return ext ? ALLOWED_IMAGE_EXTENSIONS.includes(ext) : false;
  }, []);
  const maxFileSize = 5 * 1024 * 1024; // 5MB

  // Validar archivo
  const validateFile = useCallback(
    (file: File): string | null => {
      if (!isImageFile(file)) {
        return `${file.name}: Solo se permiten JPG, JPEG, PNG, WEBP o GIF`;
      }

      if (file.size > maxFileSize) {
        return `${file.name}: El archivo excede el tamaño máximo de 5MB`;
      }

      return null;
    },
    [isImageFile, maxFileSize]
  );

  // Procesar archivos seleccionados
  const processFiles = useCallback(
    (selectedFiles: FileList | File[]) => {
      const fileArray = Array.from(selectedFiles);
      const validFiles: FilePreview[] = [];
      const errors: string[] = [];

      for (const file of fileArray) {
        const validationError = validateFile(file);
        if (validationError) {
          errors.push(validationError);
          continue;
        }

        // Verificar que no exceda el límite
        if (filePreviews.length + validFiles.length >= maxFiles) {
          errors.push(`Máximo ${maxFiles} imágenes permitidas`);
          break;
        }

        // Crear preview
        const preview = URL.createObjectURL(file);
        validFiles.push({
          file,
          preview,
          id: `${Date.now()}-${Math.random()}`,
        });
      }

      if (errors.length > 0) {
        setError(errors.join('. '));
      } else {
        setError(null);
      }

      if (validFiles.length > 0) {
        const newPreviews = [...filePreviews, ...validFiles];
        setFilePreviews(newPreviews);
        onChange(newPreviews.map(fp => fp.file));
      }
    },
    [filePreviews, maxFiles, validateFile, onChange]
  );

  // Manejar drop
  const handleDrop = useCallback(
    (e: React.DragEvent<HTMLDivElement>) => {
      e.preventDefault();
      e.stopPropagation();
      setDragActive(false);

      if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
        processFiles(e.dataTransfer.files);
      }
    },
    [processFiles]
  );

  // Manejar drag over
  const handleDragOver = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(true);
  }, []);

  // Manejar drag leave
  const handleDragLeave = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
  }, []);

  // Manejar cambio de input
  const handleFileChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files.length > 0) {
        processFiles(e.target.files);
      }
    },
    [processFiles]
  );

  // Remover archivo
  const removeFile = useCallback((id: string) => {
    setFilePreviews((prev) => {
      const fileToRemove = prev.find((f) => f.id === id);
      if (fileToRemove) {
        URL.revokeObjectURL(fileToRemove.preview);
      }
      const newPreviews = prev.filter((f) => f.id !== id);
      onChange(newPreviews.map(fp => fp.file));
      return newPreviews;
    });
    setError(null);
  }, [onChange]);

  // Limpiar todos
  const clearAll = useCallback(() => {
    filePreviews.forEach((f) => URL.revokeObjectURL(f.preview));
    setFilePreviews([]);
    onChange([]);
    setError(null);
  }, [filePreviews, onChange]);

  // Limpiar previews al desmontar o cuando cambien
  React.useEffect(() => {
    return () => {
      filePreviews.forEach((f) => URL.revokeObjectURL(f.preview));
    };
  }, [filePreviews]);

  return (
    <div className="space-y-4">
      {/* Zona de drop */}
      <div
        className={`relative border-2 border-dashed rounded-xl p-6 transition-all ${
          dragActive
            ? 'border-primary bg-primary/5 scale-[1.01]'
            : 'border-border hover:border-primary/50 hover:bg-accent/5'
        }`}
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
      >
        <input
          ref={fileInputRef}
          type="file"
          multiple
          accept=".jpg,.jpeg,.png,.webp,.gif"
          onChange={handleFileChange}
          className="hidden"
        />

        <div className="flex flex-col items-center justify-center gap-3 text-center">
          <div
            className={`p-3 rounded-full transition-colors ${
              dragActive ? 'bg-primary text-primary-foreground' : 'bg-accent'
            }`}
          >
            <Upload className="w-6 h-6" />
          </div>

          <div>
            <p className="text-sm font-medium mb-1">
              {dragActive
                ? 'Suelta las imágenes aquí'
                : 'Arrastra y suelta imágenes'}
            </p>
            <p className="text-xs text-muted-foreground mb-3">
              o haz clic para seleccionar
            </p>
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={() => fileInputRef.current?.click()}
            >
              <ImageIcon className="w-4 h-4 mr-2" />
              Seleccionar
            </Button>
          </div>

          <p className="text-xs text-muted-foreground">
            JPG, PNG, WEBP, GIF - Max 5MB - Hasta {maxFiles} imágenes
          </p>
        </div>
      </div>

      {/* Mensaje de error */}
      {error && (
        <div className="text-sm text-destructive bg-destructive/10 border border-destructive/30 rounded-lg p-3">
          {error}
        </div>
      )}

      {/* Preview de archivos seleccionados */}
      {filePreviews.length > 0 && (
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <p className="text-sm font-medium">
              {filePreviews.length} imagen(es) seleccionada(s)
            </p>
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={clearAll}
            >
              Limpiar todo
            </Button>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3">
            {filePreviews.map((filePreview) => (
              <div
                key={filePreview.id}
                className="relative group aspect-square rounded-lg overflow-hidden border bg-accent/5"
              >
                <img
                  src={filePreview.preview}
                  alt={filePreview.file.name}
                  className="w-full h-full object-cover"
                />
                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/60 transition-colors flex items-center justify-center">
                  <Button
                    type="button"
                    variant="destructive"
                    size="icon"
                    className="opacity-0 group-hover:opacity-100 transition-opacity w-8 h-8"
                    onClick={() => removeFile(filePreview.id)}
                  >
                    <X className="w-4 h-4" />
                  </Button>
                </div>
                <div className="absolute bottom-0 left-0 right-0 p-1.5 bg-gradient-to-t from-black/80 to-transparent">
                  <p className="text-xs text-white truncate">
                    {filePreview.file.name}
                  </p>
                  <p className="text-xs text-white/70">
                    {(filePreview.file.size / 1024).toFixed(0)} KB
                  </p>
                </div>
              </div>
            ))}
          </div>

          <p className="text-xs text-muted-foreground bg-blue-50 dark:bg-blue-950/30 border border-blue-200 dark:border-blue-800 rounded-lg p-2.5">
            💡 <strong>Nota:</strong> Las imágenes se subirán automáticamente después de crear el animal
          </p>
        </div>
      )}
    </div>
  );
}

import React, { useState, useRef, useCallback } from 'react';
import { Upload, X, Image as ImageIcon, CircleAlert, CircleCheck } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Progress } from '@/shared/ui/progress';
import { Alert, AlertDescription } from '@/shared/ui/alert';
