  const fileInputRef = useRef<HTMLInputElement>(null);

  const isAllowedImage = useCallback(
    (file: File) => {
      if (file.type) return ALLOWED_IMAGE_MIME_TYPES.includes(file.type);
      const ext = file.name.split('.').pop()?.toLowerCase();
      return ext ? ALLOWED_IMAGE_EXTENSIONS.includes(ext) : false;
    },
    []
  );
  const maxFileSize = 5 * 1024 * 1024; // 5MB

  // Validar archivo
  const validateFile = useCallback(
    (file: File): string | null => {
      if (!isAllowedImage(file)) {
        return `${file.name}: Solo se permiten JPG, JPEG, PNG, WEBP o GIF`;
      }

      if (file.size > maxFileSize) {
        return `${file.name}: El archivo excede el tamaño máximo de 5MB`;
      }

      return null;
    },
    [isAllowedImage, maxFileSize]
  );

  // Procesar archivos seleccionados
  const processFiles = useCallback(
    (selectedFiles: FileList | File[]) => {
      const fileArray = Array.from(selectedFiles);
      const validFiles: FilePreview[] = [];
      const errors: string[] = [];

      for (const file of fileArray) {
        const validationError = validateFile(file);
        if (validationError) {
          errors.push(validationError);
          continue;
        }

        // Verificar que no exceda el límite
        if (files.length + validFiles.length >= maxFiles) {
          errors.push(`Máximo ${maxFiles} imágenes permitidas`);
          break;
        }

        // Crear preview
        const preview = URL.createObjectURL(file);
        validFiles.push({
          file,
          preview,
          id: `${Date.now()}-${Math.random()}`,
        });
      }

      if (errors.length > 0) {
        setError(errors.join('. '));
      } else {
        setError(null);
      }

      if (validFiles.length > 0) {
        setFiles((prev) => [...prev, ...validFiles]);
        setSuccess(null);
      }
    },
    [files.length, maxFiles, validateFile]
  );

  // Manejar drop
  const handleDrop = useCallback(
    (e: React.DragEvent<HTMLDivElement>) => {
      e.preventDefault();
      e.stopPropagation();
      setDragActive(false);

      if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
        processFiles(e.dataTransfer.files);
      }
    },
    [processFiles]
  );

  // Manejar drag over
  const handleDragOver = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(true);
  }, []);

  // Manejar drag leave
  const handleDragLeave = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
  }, []);

  // Manejar cambio de input
  const handleFileChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files.length > 0) {
        processFiles(e.target.files);
      }
    },
    [processFiles]
  );

  // Remover archivo
  const removeFile = useCallback((id: string) => {
    setFiles((prev) => {
      const fileToRemove = prev.find((f) => f.id === id);
      if (fileToRemove) {
        URL.revokeObjectURL(fileToRemove.preview);
      }
      return prev.filter((f) => f.id !== id);
    });
    setError(null);
    setSuccess(null);
  }, []);

  // Limpiar previews al desmontar
  React.useEffect(() => {
    return () => {
      files.forEach((f) => URL.revokeObjectURL(f.preview));
    };
  }, [files]);

  // Subir imágenes
  const handleUpload = useCallback(async () => {
    if (files.length === 0) {
      setError('Debe seleccionar al menos una imagen');
      return;
    }

    setUploading(true);
    setUploadProgress(0);
    setError(null);
    setSuccess(null);

    try {
      const filesToUpload = files.map((f) => f.file);

      const response = await animalImageService.uploadImages(
        animalId,
        filesToUpload,
        {
          compress,
          quality,
          onProgress: (progress) => {
            setUploadProgress(progress);
          },
        }
      );

      if (response.success) {
        const respMessage =
          response.message ||
          `${response.data?.total_uploaded ?? files.length} imagen(es) subida(s) exitosamente`;

        const partialErrors =
          response.data?.errors && Array.isArray(response.data.errors)
            ? response.data.errors.filter(Boolean)
            : [];

        setSuccess(respMessage);
        if (partialErrors.length > 0) {
          setError(partialErrors.join(' • '));
        } else {
          setError(null);
        }

        // Limpiar archivos
        files.forEach((f) => URL.revokeObjectURL(f.preview));
        setFiles([]);
        setUploadProgress(0);

        // Callback de éxito
        if (onUploadSuccess) {
          onUploadSuccess(response.data.uploaded);
        }

        // Mostrar toast de confirmación
        showToast(`✅ ${respMessage}`, 'success');
        // Despachar evento global para que cualquier galer¡a o banner se refresque
        try {
          const detail = { animalId, uploaded: response.data.uploaded };
          window.dispatchEvent(new CustomEvent('animal-images:updated', { detail }));
          setTimeout(() => {
            window.dispatchEvent(new CustomEvent('animal-images:updated', { detail }));
          }, 800);
        } catch (error) {
          if (process.env.NODE_ENV !== 'production') {
            console.warn('[AnimalImageUpload] No se pudo emitir evento de actualizaci¢n', error);
          }
        }
      } else {
        throw new Error(response.message || 'Error al subir imágenes');
      }
    } catch (err: any) {
      const data = (err as any)?.original?.response?.data || err?.response?.data || err?.data;
      const backendMessage =
        data?.message || data?.detail || data?.error || err?.message || 'Error al subir imágenes';

      const detailErrors =
        (err as any)?.validationErrors ||
        (err as any)?.details?.validation_errors ||
        (err as any)?.details?.errors ||
        data?.details?.errors ||
        data?.error?.details?.errors ||
        data?.errors ||
        data?.details?.validation_errors;

      let detailMsg: string | null = null;
      if (detailErrors) {
        try {
          if (Array.isArray(detailErrors)) {
            detailMsg = detailErrors
              .map((e: any) => (typeof e === 'string' ? e : e?.message || e?.detail || e))
              .filter(Boolean)
              .join(' • ');
          } else if (typeof detailErrors === 'object') {
            detailMsg = Object.entries(detailErrors)
              .map(([k, v]) => {
                const items = Array.isArray(v) ? v : [v];
                const msg = items
                  .map((e: any) => (typeof e === 'string' ? e : e?.message || e?.detail || e))
                  .filter(Boolean)
                  .join(' • ');
                return msg ? `${k}: ${msg}` : null;
              })
              .filter(Boolean)
              .join(' • ');
          }
        } catch {
          // noop
        }
      }

      const finalError = detailMsg ? `${backendMessage} • ${detailMsg}` : backendMessage;
      setError(finalError);
      showToast(`❌ ${finalError}`, 'error');

      if (onUploadError) {
        onUploadError(err);
      }
    } finally {
      setUploading(false);
    }
  }, [files, animalId, compress, quality, onUploadSuccess, onUploadError, showToast]);

  return (
    <div className="space-y-4">
      {/* Zona de drop */}
      <div
        className={`relative border-2 border-dashed rounded-xl p-8 transition-all ${
          dragActive
            ? 'border-primary bg-primary/5 scale-[1.02]'
            : 'border-border hover:border-primary/50 hover:bg-accent/5'
        } ${uploading ? 'opacity-50 pointer-events-none' : ''}`}
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
      >
        <input
          ref={fileInputRef}
          type="file"
          multiple
          accept=".jpg,.jpeg,.png,.webp,.gif"
          onChange={handleFileChange}
          className="hidden"
          disabled={uploading}
        />

        <div className="flex flex-col items-center justify-center gap-4 text-center">
          <div
            className={`p-4 rounded-full transition-colors ${
              dragActive ? 'bg-primary text-primary-foreground' : 'bg-accent'
            }`}
          >
            <Upload className="w-8 h-8" />
          </div>

          <div>
            <p className="text-lg font-medium mb-1">
              {dragActive
                ? 'Suelta las imágenes aquí'
                : 'Arrastra y suelta imágenes aquí'}
            </p>
            <p className="text-sm text-muted-foreground mb-4">
              o haz clic para seleccionar archivos
            </p>
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={() => fileInputRef.current?.click()}
              disabled={uploading}
            >
              <ImageIcon className="w-4 h-4 mr-2" />
              Seleccionar Imágenes
            </Button>
          </div>

          <p className="text-xs text-muted-foreground">
            JPG, PNG, WEBP, GIF - Máximo 5MB por archivo - Hasta {maxFiles}{' '}
            imágenes
          </p>
        </div>
      </div>

      {/* Preview de archivos seleccionados */}
      {files.length > 0 && (
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <p className="text-sm font-medium">
              {files.length} imagen(es) seleccionada(s)
            </p>
            {!uploading && (
              <Button
                type="button"
                variant="ghost"
                size="sm"
                onClick={() => {
                  files.forEach((f) => URL.revokeObjectURL(f.preview));
                  setFiles([]);
                  setError(null);
                }}
              >
                Limpiar todo
              </Button>
            )}
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
            {files.map((filePreview) => (
              <div
                key={filePreview.id}
                className="relative group aspect-square rounded-lg overflow-hidden border bg-accent/5"
              >
                <img
                  src={filePreview.preview}
                  alt={filePreview.file.name}
                  className="w-full h-full object-cover"
                />
                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/60 transition-colors flex items-center justify-center">
                  {!uploading && (
                    <Button
                      type="button"
                      variant="destructive"
                      size="icon"
                      className="opacity-0 group-hover:opacity-100 transition-opacity"
                      onClick={() => removeFile(filePreview.id)}
                    >
                      <X className="w-4 h-4" />
                    </Button>
                  )}
                </div>
                <div className="absolute bottom-0 left-0 right-0 p-2 bg-gradient-to-t from-black/80 to-transparent">
                  <p className="text-xs text-white truncate">
                    {filePreview.file.name}
                  </p>
                  <p className="text-xs text-white/70">
                    {(filePreview.file.size / 1024).toFixed(0)} KB
                  </p>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Progreso de subida */}
      {uploading && (
        <div className="space-y-2">
          <div className="flex items-center justify-between text-sm">
            <span>Subiendo imágenes...</span>
            <span className="font-medium">{uploadProgress}%</span>
          </div>
          <Progress value={uploadProgress} className="h-2" />
        </div>
      )}

      {/* Mensajes de error */}
      {error && (
        <Alert variant="destructive">
          <CircleAlert className="h-4 w-4" />
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      )}

      {/* Mensajes de éxito */}
      {success && (
        <Alert className="border-green-500 bg-green-500/10">
          <CircleCheck className="h-4 w-4 text-green-500" />
          <AlertDescription className="text-green-700 dark:text-green-400">
            {success}
          </AlertDescription>
        </Alert>
      )}

      {/* Botón de subida */}
      {files.length > 0 && !uploading && (
        <div className="flex justify-end gap-2">
          <Button
            type="button"
            variant="outline"
            onClick={() => {
              files.forEach((f) => URL.revokeObjectURL(f.preview));
              setFiles([]);
              setError(null);
              setSuccess(null);
            }}
          >
            Cancelar
          </Button>
          <Button type="button" onClick={handleUpload}>
            <Upload className="w-4 h-4 mr-2" />
            Subir {files.length} Imagen(es)
            {compress && ' (Con compresión)'}
          </Button>
        </div>
      )}
    </div>
  );
}

import React from 'react';
import { Line } from 'react-chartjs-2';
import {
    Chart as ChartJS,
    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,
    Title,
    Tooltip,
    Legend,
    Filler,
} from 'chart.js';
import { COLORS } from '@/shared/utils/colors';
import { calculateBMI } from '@/shared/utils/animalMetrics';

ChartJS.register(
    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,
    Title,
    Tooltip,
    Legend,
    Filler
);

interface ControlData {
    checkup_date: string;
    weight?: number;
    height?: number;
}

interface AnimalMetricsChartsProps {
    controls: ControlData[];
    onChartClick?: () => void;
}

export const AnimalMetricsCharts: React.FC<AnimalMetricsChartsProps> = ({ controls, onChartClick }) => {
    const sortedControls = [...controls].sort(
        (a, b) => new Date(a.checkup_date).getTime() - new Date(b.checkup_date).getTime()
    );

    const labels = sortedControls.map((c) => {
        const d = new Date(c.checkup_date);
        return d.toLocaleDateString('es-ES', { day: '2-digit', month: 'short' });
    });

    const weightData = {
        labels,
        datasets: [
            {
                label: 'Peso (kg)',
                data: sortedControls.map((c) => c.weight || null),
                borderColor: COLORS.charts.primary,
                backgroundColor: COLORS.charts.primary + '33',
                fill: true,
                tension: 0.3,
            },
        ],
    };

    const heightData = {
        labels,
        datasets: [
            {
                label: 'Altura (m)',
                data: sortedControls.map((c) => c.height || null),
                borderColor: COLORS.charts.secondary,
                backgroundColor: COLORS.charts.secondary + '33',
                fill: true,
                tension: 0.3,
            },
        ],
    };

    const bmiData = {
        labels,
        datasets: [
            {
                label: 'IMC',
                data: sortedControls.map((c) => calculateBMI(c.weight, c.height)),
                borderColor: COLORS.charts.success,
                backgroundColor: COLORS.charts.success + '33',
                fill: true,
                tension: 0.3,
            },
        ],
    };

    const options = {
        responsive: true,
        maintainAspectRatio: false,
        onClick: onChartClick,
        onHover: (event: any, chartElement: any) => {
            if (onChartClick) {
                event.native.target.style.cursor = chartElement[0] || event.native.target ? 'pointer' : 'default';
            }
        },
        plugins: {
            legend: {
                position: 'top' as const,
                labels: {
                    boxWidth: 8,
                    usePointStyle: true,
                    font: { size: 10 }
                }
            },
            tooltip: {
                mode: 'index' as const,
                intersect: false,
            },
        },
        scales: {
            y: {
                beginAtZero: false,
                grid: {
                    display: true,
                    color: 'rgba(0,0,0,0.05)',
                },
            },
            x: {
                grid: {
                    display: false,
                },
            },
        },
    };

    if (controls.length === 0) {
        return (
            <div className="flex items-center justify-center h-32 text-muted-foreground italic text-sm">
                No hay datos de controles para generar gráficos.
            </div>
        );
    }

    return (
        <div className="space-y-6 relative group">
            {onChartClick && (
                <div className="absolute top-0 right-0 z-10 opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none">
                    <span className="text-[10px] bg-primary/10 text-primary px-2 py-1 rounded-bl-lg font-bold border-l border-b border-primary/20 backdrop-blur-sm">
                        Clic para ver historial completo
                    </span>
                </div>
            )}
            <div className="h-48 cursor-pointer hover:bg-slate-50/50 dark:hover:bg-slate-800/20 rounded-xl transition-colors duration-200 p-2">
                <Line data={weightData} options={options} />
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="h-40 cursor-pointer hover:bg-slate-50/50 dark:hover:bg-slate-800/20 rounded-xl transition-colors duration-200 p-2">
                    <Line data={heightData} options={options} />
                </div>
                <div className="h-40 cursor-pointer hover:bg-slate-50/50 dark:hover:bg-slate-800/20 rounded-xl transition-colors duration-200 p-2">
                    <Line data={bmiData} options={options} />
                </div>
            </div>
        </div>
    );
};

import React, { useState, useCallback, useEffect } from 'react';
import { X } from 'lucide-react';
import { Badge } from '@/shared/ui/badge';
import { Button } from '@/shared/ui/button';
import { AnimalResponse } from '@/shared/api/generated/swaggerTypes';
import { AnimalImageGallery } from './AnimalImageGallery';
import { AnimalImageUpload } from './AnimalImageUpload';

interface AnimalModalProps {
  isOpen: boolean;
  onClose: () => void;
  animal: AnimalResponse & { [k: string]: any };
  breedLabel: string;
  fatherLabel: string;
  motherLabel: string;
  mode?: 'view' | 'edit' | 'create';
  children?: React.ReactNode;
}

import { GenericModal } from '@/shared/ui/common/GenericModal';

/**
 * Modal mejorado para animales
 * - Layout con columna de imágenes y 2 columnas de atributos en desktop
 * - 1 columna en móvil (mobile-first)
 * - Sección de carga de imágenes
 * - Botones con ancho del contenido
 * - Sombras y tipografía mejorada
 */
export function AnimalModal({
  isOpen,
  onClose,
  animal,
  breedLabel,
  fatherLabel,
  motherLabel,
  mode = 'view',
  children
}: AnimalModalProps) {
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const [showUpload, setShowUpload] = useState(false);

  // Escuchar evento para abrir la pestaña de subida
  useEffect(() => {
    const handleOpenUploadTab = (e: Event) => {
      const detail = (e as CustomEvent).detail as { animalId?: number } | undefined;
      if (!detail || detail.animalId === animal.id) {
        setShowUpload(true);
      }
    };

    window.addEventListener('open-upload-tab', handleOpenUploadTab as EventListener);
    return () => {
      window.removeEventListener('open-upload-tab', handleOpenUploadTab as EventListener);
    };
  }, [animal.id]);

  const gender = animal.sex || animal.gender;
  const birthDate = animal.birth_date
    ? new Date(animal.birth_date).toLocaleDateString('es-ES')
    : '-';
  const createdAt = animal.created_at
    ? new Date(animal.created_at).toLocaleString('es-ES')
    : '-';
  const updatedAt = animal.updated_at
    ? new Date(animal.updated_at).toLocaleString('es-ES')
    : '-';
  const ageMonths = animal.age_in_months ?? '-';
  const ageDays = animal.age_in_days ?? '-';
  const weight = animal.weight ?? '-';
  const status = animal.status || '-';
  const isAdult = animal.is_adult === true ? 'Sí' : animal.is_adult === false ? 'No' : '-';

  const handleUploadSuccess = useCallback(() => {
    setRefreshTrigger(prev => prev + 1);
    setShowUpload(false);
  }, []);

  const footer = (
    <div className="flex items-center justify-end gap-3 p-4 bg-background/50 backdrop-blur-md border-t">
      <Button
        type="button"
        variant="outline"
        onClick={onClose}
        className="min-w-[100px]"
      >
        Cerrar
      </Button>
    </div>
  );

  return (
    <GenericModal
      isOpen={isOpen}
      onOpenChange={(open) => !open && onClose()}
      title={animal.record || `Animal #${animal.id}`}
      description="Información detallada del animal"
      size="7xl"
      footer={footer}
    >
      <div className="space-y-6">
        {/* Chips de estado superior */}
        <div className="flex items-center gap-2 mb-4">
          <Badge
            variant="outline"
            className={`text-xs font-semibold shadow-sm ${status === 'Sano' ? 'bg-green-50/50 text-green-700 border-green-200 dark:bg-green-950/30 dark:text-green-400' :
              status === 'Enfermo' ? 'bg-red-50/50 text-red-700 border-red-200 dark:bg-red-950/30 dark:text-red-400' :
                'bg-blue-50/50 text-blue-700 border-blue-200 dark:bg-blue-950/30 dark:text-blue-400'
              }`}
          >
            {status}
          </Badge>
          <Badge
            variant="secondary"
            className={`text-xs font-semibold shadow-sm ${gender === 'Macho' ? 'bg-blue-100/50 text-blue-800 dark:bg-blue-950/30 dark:text-blue-300' :
              gender === 'Hembra' ? 'bg-pink-100/50 text-pink-800 dark:bg-pink-950/30 dark:text-pink-300' :
                'bg-purple-100/50 text-purple-800 dark:bg-purple-950/30 dark:text-purple-300'
              }`}
          >
            {gender || '-'}
          </Badge>
        </div>

        {/* Layout: Columna de imágenes + Columnas de atributos */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Columna de imágenes (1/3 en desktop, full en mobile) */}
          <div className="lg:col-span-1 space-y-4">
            <div className="bg-gradient-to-br from-accent/30 to-accent/10 rounded-xl p-4 shadow-lg border border-border/30 backdrop-blur-sm">
              <h3 className="text-sm font-bold uppercase tracking-wider text-foreground/80 mb-3">
                Imágenes
              </h3>

              {/* Galería de imágenes */}
              <AnimalImageGallery
                animalId={animal.id}
                showControls={mode !== 'view'}
                refreshTrigger={refreshTrigger}
                onGalleryUpdate={() => setRefreshTrigger(prev => prev + 1)}
              />

              {/* Botón para mostrar carga de imágenes */}
              {mode !== 'view' && !showUpload && (
                <div className="mt-4">
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => setShowUpload(true)}
                    className="w-full"
                  >
                    Cargar nuevas imágenes
                  </Button>
                </div>
              )}

              {/* Componente de carga de imágenes */}
              {showUpload && mode !== 'view' && (
                <div className="mt-4 bg-card/50 rounded-lg p-4 border border-border/30 shadow-sm backdrop-blur-sm">
                  <div className="flex items-center justify-between mb-3">
                    <h4 className="text-xs font-bold uppercase tracking-wider text-foreground/80">
                      Cargar imágenes
                    </h4>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={() => setShowUpload(false)}
                    >
                      <X className="w-4 h-4" />
                    </Button>
                  </div>
                  <AnimalImageUpload
                    animalId={animal.id}
                    onUploadSuccess={handleUploadSuccess}
                    maxFiles={10}
                  />
                </div>
              )}
            </div>
          </div>

          {/* Columnas de atributos (2/3 en desktop, full en mobile) */}
          <div className="lg:col-span-2 space-y-6">
            {/* Información básica */}
            <div className="bg-white/40 dark:bg-slate-800/20 rounded-xl p-5 shadow-lg border border-border/30 backdrop-blur-md">
              <h3 className="text-sm font-bold uppercase tracking-wider text-foreground/80 mb-4">
                Información Básica
              </h3>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-x-6 gap-y-4">
                <DetailField label="ID" value={animal.id} />
                <DetailField label="Registro" value={animal.record || '-'} />
                <DetailField label="Raza" value={breedLabel} />
                <DetailField label="Sexo" value={gender || '-'} />
                <DetailField label="Estado" value={status} />
                <DetailField label="Peso" value={`${weight} kg`} />
                <DetailField label="Fecha de nacimiento" value={birthDate} />
                <DetailField label="Edad (días)" value={ageDays} />
                <DetailField label="Edad (meses)" value={ageMonths} />
                <DetailField label="Adulto" value={isAdult} />
              </div>
            </div>

            {/* Genealogía */}
            <div className="bg-white/40 dark:bg-slate-800/20 rounded-xl p-5 shadow-lg border border-border/30 backdrop-blur-md">
              <h3 className="text-sm font-bold uppercase tracking-wider text-foreground/80 mb-4">
                Genealogía
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-4">
                <DetailField label="Padre" value={fatherLabel} />
                <DetailField label="Madre" value={motherLabel} />
              </div>
            </div>

            {/* Información del sistema */}
            <div className="bg-white/40 dark:bg-slate-800/20 rounded-xl p-5 shadow-lg border border-border/30 backdrop-blur-md">
              <h3 className="text-sm font-bold uppercase tracking-wider text-foreground/80 mb-4">
                Información del Sistema
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-4">
                <DetailField label="Creado" value={createdAt} />
                <DetailField label="Actualizado" value={updatedAt} />
              </div>
            </div>

            {/* Notas (si existen) */}
            {animal.notes && (
              <div className="bg-white/40 dark:bg-slate-800/20 rounded-xl p-5 shadow-lg border border-border/30 backdrop-blur-md">
                <h3 className="text-sm font-bold uppercase tracking-wider text-foreground/80 mb-3">
                  Notas
                </h3>
                <p className="text-sm text-foreground/80 leading-relaxed whitespace-pre-wrap">
                  {animal.notes}
                </p>
              </div>
            )}
          </div>
        </div>

        {/* Contenido personalizado (si se proporciona) */}
        {children && (
          <div className="border-t border-border/30 pt-6">
            {children}
          </div>
        )}
      </div>
    </GenericModal>
  );
}

/**
 * Campo de detalle individual
 */
function DetailField({ label, value }: { label: string; value: any }) {
  return (
    <div className="space-y-1.5">
      <div className="text-[10px] uppercase tracking-wider font-bold text-muted-foreground/70">
        {label}
      </div>
      <div className="text-sm font-semibold text-foreground">
        {value ?? '-'}
      </div>
    </div>
  );
}

import React, { useState, useCallback, useEffect } from 'react';
import { X, Activity, Syringe, MapPin, Pill, ClipboardList, TrendingUp, Plus, List, Eye, Edit, Trash2, RefreshCw, ChevronDown, ChevronUp, ImageIcon, Copy, AlertTriangle } from 'lucide-react';
import { cn } from '@/shared/ui/cn';
import { useToast } from '@/app/providers/ToastContext';
import { Badge } from '@/shared/ui/badge';
import { Button } from '@/shared/ui/button';
import { AnimalResponse } from '@/shared/api/generated/swaggerTypes';
import { ImageManager } from '@/shared/ui/common/ImageManager';
import { AnimalImageBanner } from './AnimalImageBanner';
import { GenericModal } from '@/shared/ui/common/GenericModal';
import { AnimalActionsMenu } from '@/widgets/dashboard/AnimalActionsMenu';
import { ParentMiniCard } from './ParentMiniCard';
import { geneticImprovementsService } from '@/entities/genetic-improvement/api/geneticImprovements.service';
import { animalDiseasesService } from '@/entities/animal-disease/api/animalDiseases.service';
import { animalFieldsService } from '@/entities/animal-field/api/animalFields.service';
import { vaccinationsService } from '@/entities/vaccination/api/vaccinations.service';
import { treatmentsService } from '@/entities/treatment/api/treatments.service';
import { controlService } from '@/entities/control/api/control.service';
import { animalImageService } from '@/entities/animal/api/animalImage.service';
// Importar servicio para limpiar caché de dependencias
import { clearAnimalDependencyCache, checkTreatmentDependencies } from '@/features/diagnostics/api/dependencyCheck.service';
import { diseaseService } from '@/entities/disease/api/disease.service';
import { fieldService } from '@/entities/field/api/field.service';
import { vaccinesService } from '@/entities/vaccine/api/vaccines.service';
import { usersService } from '@/entities/user/api/user.service';
import analyticsService from '@/features/reporting/api/analytics.service';
import { resolveRecordId } from '@/shared/utils/recordIdUtils';
import { AnimalMetricsCharts } from './AnimalMetricsCharts';
import { analyzeGrowthTrends } from '@/shared/utils/animalMetrics';

import { ItemDetailModal } from './ItemDetailModal';
import { CollapsibleCard } from '@/shared/ui/common/CollapsibleCard';
import { TreatmentSuppliesModal } from '../treatments/TreatmentSuppliesModal';
import { DetailField } from './components/DetailField';
import { RelatedDataSection } from './components/RelatedDataSection';
import { AnimalRecommendationsWidget } from '@/entities/knowledge-base/ui/AnimalRecommendationsWidget';


interface AnimalModalContentProps {
  animal: AnimalResponse & { [k: string]: any };
  breedLabel: string;
  fatherLabel: string;
  motherLabel: string;
  onFatherClick?: (fatherId: number) => void;
  onMotherClick?: (motherId: number) => void;
  currentUserId?: number;
  onOpenHistory?: () => void;
  onOpenAncestorsTree?: () => void;
  onOpenDescendantsTree?: () => void;
  onEdit?: () => void;
  onReplicate?: () => void;
  // Contenedor con scroll para preservar posición al refrescar
  scrollContainerRef?: React.RefObject<HTMLDivElement>;
}

export function AnimalModalContent({
  animal,
  breedLabel,
  fatherLabel,
  motherLabel,
  onFatherClick,
  onMotherClick,
  currentUserId,
  onOpenHistory,
  onOpenAncestorsTree,
  onOpenDescendantsTree,
  onEdit,
  onReplicate,
  scrollContainerRef
}: AnimalModalContentProps) {
  const { showToast } = useToast();
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const savedScrollTopRef = React.useRef(0);
  const [deletingItemId, setDeletingItemId] = useState<string | number | null>(null);
  const [confirmingDeleteId, setConfirmingDeleteId] = useState<string | number | null>(null);

  const preserveScroll = useCallback(() => {
    const node = scrollContainerRef?.current;
    if (node) savedScrollTopRef.current = node.scrollTop;
  }, [scrollContainerRef]);

  const restoreScroll = useCallback(() => {
    const node = scrollContainerRef?.current;
    if (!node) return;
    requestAnimationFrame(() => {
      node.scrollTop = savedScrollTopRef.current;
    });
  }, [scrollContainerRef]);

  // Estados para datos relacionados
  const [geneticImprovements, setGeneticImprovements] = useState<any[]>([]);
  const [diseases, setDiseases] = useState<any[]>([]);
  const [fields, setFields] = useState<any[]>([]);
  const [vaccinations, setVaccinations] = useState<any[]>([]);
  const [treatments, setTreatments] = useState<any[]>([]);
  const [controls, setControls] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [isManualRefreshing, setIsManualRefreshing] = useState(false);
  const [dataRefreshTrigger, setDataRefreshTrigger] = useState(0);
  const [hasRecentTreatments, setHasRecentTreatments] = useState<boolean | null>(null);
  const [animalImages, setAnimalImages] = useState<any[]>([]);
  const [imagesLoading, setImagesLoading] = useState(true);

  // Opciones para nombres
  const [diseaseOptions, setDiseaseOptions] = useState<Record<number, string>>({});
  const [fieldOptions, setFieldOptions] = useState<Record<number, string>>({});
  const [vaccineOptions, setVaccineOptions] = useState<Record<number, string>>({});
  const [userOptions, setUserOptions] = useState<Record<number, string>>({});

  // Estado para gestión de insumos (modal anidado)
  const [suppliesTreatment, setSuppliesTreatment] = useState<any | null>(null);

  const formatDate = (dateStr: string) => {
    if (!dateStr) return '-';
    try {
      const [year, month, day] = dateStr.split('T')[0].split('-');
      return `${day}/${month}/${year}`;
    } catch (e) {
      return dateStr;
    }
  };

  // Estado para controlar qué tipo de modal abrir y en qué modo
  const [actionModalType, setActionModalType] = useState<
    'genetic_improvement' | 'animal_disease' | 'animal_field' | 'vaccination' | 'treatment' | 'control' | null
  >(null);
  const [actionModalMode, setActionModalMode] = useState<'create' | 'list' | 'view' | 'edit'>('create');
  const [selectedItem, setSelectedItem] = useState<any>(null);

  // Estado para modal de insumos (tratamientos) - ELIMINADO por desuso (integrado en ItemDetailModal)


  // Funciones para abrir modales
  const openCreateModal = (type: typeof actionModalType) => {
    setActionModalType(type);
    setActionModalMode('create');
    setSelectedItem(null);
  };

  const openListModal = (type: typeof actionModalType) => {
    setActionModalType(type);
    setActionModalMode('list');
    setSelectedItem(null);
  };

  const openViewModal = (type: typeof actionModalType, item: any) => {
    setActionModalType(type);
    setActionModalMode('view');
    setSelectedItem(item);
  };

  const openEditModal = (type: typeof actionModalType, item: any) => {
    setActionModalType(type);
    setActionModalMode('edit');
    setSelectedItem(item);
  };

  const closeActionModal = () => {
    setActionModalType(null);
    setSelectedItem(null);
  };

  const gender = animal.sex || animal.gender;
  const birthDate = animal.birth_date
    ? new Date(animal.birth_date).toLocaleDateString('es-ES')
    : '-';
  const ageMonths = animal.age_in_months ?? '-';
  const ageDays = animal.age_in_days ?? '-';
  const weight = animal.weight ?? '-';
  const status = animal.status || '-';
  const isAdult = animal.is_adult === true ? 'Sí' : animal.is_adult === false ? 'No' : '-';

  // Cargar catálogos
  useEffect(() => {
    const loadOptions = async () => {
      try {
        const [diseasesRes, fieldsRes, vaccinesRes, usersRes] = await Promise.all([
          diseaseService.getDiseases({ page: 1, limit: 1000 }).catch(() => ({ data: [] })),
          fieldService.getFields({ page: 1, limit: 1000 }).catch(() => ({ data: [] })),
          vaccinesService.getVaccines?.({ page: 1, limit: 1000 }).catch(() => ({ data: [] })),
          usersService.getUsers({ page: 1, limit: 1000 }).catch(() => ({ data: [] })),
        ]);

        const dMap: Record<number, string> = {};
        ((diseasesRes as any)?.data || diseasesRes || []).forEach((d: any) => { dMap[d.id] = d.disease || d.name; });
        setDiseaseOptions(dMap);

        const fMap: Record<number, string> = {};
        ((fieldsRes as any)?.data || fieldsRes || []).forEach((f: any) => { fMap[f.id] = f.name; });
        setFieldOptions(fMap);

        const vMap: Record<number, string> = {};
        ((vaccinesRes as any)?.data || vaccinesRes || []).forEach((v: any) => { vMap[v.id] = v.name; });
        setVaccineOptions(vMap);

        const uMap: Record<number, string> = {};
        ((usersRes as any)?.data || usersRes || []).forEach((u: any) => { uMap[u.id] = u.fullname || u.name; });
        setUserOptions(uMap);
      } catch (err) {
        console.error('Error loading options in AnimalModalContent:', err);
      }
    };
    loadOptions();
  }, []);

  // Triggers individuales para cada sección
  const [triggers, setTriggers] = useState({
    genetic: 0,
    diseases: 0,
    fields: 0,
    vaccinations: 0,
    treatments: 0,
    controls: 0,
    images: 0,
    general: 0 // Para refrescos completos
  });

  // Función unificada para refrescar secciones específicas
  const handleRefresh = useCallback((type?: string) => {
    if (!type) {
      // Si no se especifica tipo, refrescar todo
      setTriggers(prev => ({
        ...prev,
        genetic: prev.genetic + 1,
        diseases: prev.diseases + 1,
        fields: prev.fields + 1,
        vaccinations: prev.vaccinations + 1,
        treatments: prev.treatments + 1,
        controls: prev.controls + 1,
        images: prev.images + 1,
        general: prev.general + 1
      }));
      return;
    }

    // Mapeo de tipos de modal a claves del estado triggers
    const mapping: Record<string, keyof typeof triggers> = {
      'genetic_improvement': 'genetic',
      'animal_disease': 'diseases',
      'animal_field': 'fields',
      'vaccination': 'vaccinations',
      'treatment': 'treatments',
      'control': 'controls'
    };

    const key = mapping[type];
    if (key) {
      console.log(`[AnimalModalContent] Refreshing specific section: ${key}`);
      setTriggers(prev => ({ ...prev, [key]: prev[key] + 1 }));

      // Si cambiamos tratamientos o vacunas, verificar fecha reciente
      if (key === 'treatments' || key === 'vaccinations') {
        // Se actualizará en el efecto correspondiente
      }
    } else {
      // Fallback a general si no coincide
      setTriggers(prev => ({ ...prev, general: prev.general + 1 }));
    }
  }, []);

  // Efectos individuales para cargar datos

  // 1. Mejoras Genéticas
  useEffect(() => {
    const fetchGenetic = async () => {
      try {
        const params = { animal_id: animal.id, page: 1, limit: 1000, cache_bust: triggers.genetic > 0 ? Date.now() : undefined };
        const res = await geneticImprovementsService.getGeneticImprovements(params);
        const allData = (res as any)?.data || res || [];
        const filtered = Array.isArray(allData) ? allData.filter((item: any) => String(item.animal_id) === String(animal.id)) : [];
        setGeneticImprovements(filtered);
      } catch (e) {
        console.error('Error fetching genetic stats', e);
      }
    };
    fetchGenetic();
  }, [animal.id, triggers.genetic]);

  // 2. Enfermedades
  useEffect(() => {
    const fetchDiseases = async () => {
      try {
        const params = { animal_id: animal.id, page: 1, limit: 1000, cache_bust: triggers.diseases > 0 ? Date.now() : undefined };
        const res = await animalDiseasesService.getAnimalDiseases(params);
        const allData = (res as any)?.data || res || [];
        const filtered = Array.isArray(allData) ? allData.filter((item: any) => String(item.animal_id) === String(animal.id)) : [];
        setDiseases(filtered);
      } catch (e) {
        console.error('Error fetching diseases', e);
      }
    };
    fetchDiseases();
  }, [animal.id, triggers.diseases]);

  // 3. Campos
  useEffect(() => {
    const fetchFields = async () => {
      try {
        const params = { animal_id: animal.id, page: 1, limit: 1000, cache_bust: triggers.fields > 0 ? Date.now() : undefined };
        const res = await animalFieldsService.getAnimalFields(params);
        const allData = (res as any)?.data || res || [];
        const filtered = Array.isArray(allData) ? allData.filter((item: any) => String(item.animal_id) === String(animal.id)) : [];
        setFields(filtered);
      } catch (e) {
        console.error('Error fetching fields', e);
      }
    };
    fetchFields();
  }, [animal.id, triggers.fields]);

  // 4. Vacunaciones
  useEffect(() => {
    const fetchVaccinations = async () => {
      try {
        const params = { animal_id: animal.id, page: 1, limit: 1000, cache_bust: triggers.vaccinations > 0 ? Date.now() : undefined };
        const res = await vaccinationsService.getVaccinations(params);
        const allData = (res as any)?.data || res || [];
        const filtered = Array.isArray(allData) ? allData.filter((item: any) => String(item.animal_id) === String(animal.id)) : [];
        setVaccinations(filtered);
      } catch (e) {
        console.error('Error fetching vaccinations', e);
      }
    };
    fetchVaccinations();
  }, [animal.id, triggers.vaccinations]);

  // 5. Tratamientos
  useEffect(() => {
    const fetchTreatments = async () => {
      try {
        const params = { animal_id: animal.id, page: 1, limit: 1000, cache_bust: triggers.treatments > 0 ? Date.now() : undefined };
        const res = await treatmentsService.getTreatments(params);
        const allData = (res as any)?.data || res || [];
        const filtered = Array.isArray(allData) ? allData.filter((item: any) => String(item.animal_id) === String(animal.id)) : [];
        setTreatments(filtered);
      } catch (e) {
        console.error('Error fetching treatments', e);
      }
    };
    fetchTreatments();
  }, [animal.id, triggers.treatments]);

  // 6. Controles
  useEffect(() => {
    const fetchControls = async () => {
      try {
        const params = { animal_id: animal.id, page: 1, limit: 1000, cache_bust: triggers.controls > 0 ? Date.now() : undefined };
        const res = await controlService.getControls(params);
        const allData = (res as any)?.data || res || [];
        const filtered = Array.isArray(allData) ? allData.filter((item: any) => String(item.animal_id) === String(animal.id)) : [];
        setControls(filtered);
      } catch (e) {
        console.error('Error fetching controls', e);
      }
    };
    fetchControls();
  }, [animal.id, triggers.controls]);

  // 7. Imágenes
  useEffect(() => {
    const fetchImages = async () => {
      setImagesLoading(true);
      try {
        const res = await animalImageService.getAnimalImages(animal.id);
        const allImages = res?.data?.images || [];
        setAnimalImages(allImages);
      } catch (e) {
        console.error('Error fetching images', e);
      } finally {
        setImagesLoading(false);
      }
    };
    fetchImages();
  }, [animal.id, triggers.images]);

  // Efecto global para calcular "Recientes" y loading inicial
  useEffect(() => {
    // Cuando cargan tanto tratamientos como vacunas, recalculamos la flag de recientes
    const now = new Date().getTime();
    const THIRTY_DAYS_MS = 30 * 24 * 60 * 60 * 1000;

    const hasRecentTreatment = treatments.some((t: any) => {
      const d = new Date(t.treatment_date || t.date || t.created_at);
      return !isNaN(d.getTime()) && (now - d.getTime() <= THIRTY_DAYS_MS);
    });

    const hasRecentVaccination = vaccinations.some((v: any) => {
      const d = new Date(v.vaccination_date || v.date || v.created_at);
      return !isNaN(d.getTime()) && (now - d.getTime() <= THIRTY_DAYS_MS);
    });

    setHasRecentTreatments(hasRecentTreatment || hasRecentVaccination);

    // Asumimos que si tenemos los arrays inicializados (aunque vacios si no hay error), ya no estamos cargando lo vital
    // Es una heurística simple
    setLoading(false);

  }, [treatments, vaccinations]);



  // Función centralizada para eliminar registros desde el modal de detalle
  const handleDeleteRecord = async (type: string | null, item: any) => {
    if (!type || !item) return;
    const recordId = resolveRecordId(item);
    if (!recordId) {
      showToast('No se pudo determinar el ID del registro', 'error');
      return;
    }

    try {
      // 1. Verificar dependencias para tratamientos
      if (type === 'treatment') {
        const depCheck = await checkTreatmentDependencies(recordId as number);
        if (depCheck.hasDependencies) {
          const depSummary = depCheck.dependencies?.map(d => `${d.count} ${d.entity}`).join(', ') || 'registros asociados';
          showToast(`⚠️ No se puede eliminar este tratamiento porque tiene ${depSummary}. Elimina primero las dependencias.`, 'error');
          throw new Error("Dependency check failed");
        }
      }

      // 2. Ejecutar eliminación según tipo
      switch (type) {
        case 'genetic_improvement': await geneticImprovementsService.deleteGeneticImprovement(recordId as any); break;
        case 'animal_disease': await animalDiseasesService.deleteAnimalDisease(recordId as any); break;
        case 'animal_field': await animalFieldsService.deleteAnimalField(recordId as any); break;
        case 'vaccination': await vaccinationsService.deleteVaccination(recordId as any); break;
        case 'treatment': await treatmentsService.deleteTreatment(recordId as any); break;
        case 'control': await controlService.deleteControl(recordId as any); break;
        default: throw new Error("Tipo de registro no soportado para eliminación");
      }

      // 3. Actualización Optimista del Estado Local
      const idStr = String(recordId);
      switch (type) {
        case 'genetic_improvement': setGeneticImprovements(prev => prev.filter(i => String(resolveRecordId(i)) !== idStr)); break;
        case 'animal_disease': setDiseases(prev => prev.filter(i => String(resolveRecordId(i)) !== idStr)); break;
        case 'animal_field': setFields(prev => prev.filter(i => String(resolveRecordId(i)) !== idStr)); break;
        case 'vaccination': setVaccinations(prev => prev.filter(i => String(resolveRecordId(i)) !== idStr)); break;
        case 'treatment': setTreatments(prev => prev.filter(i => String(resolveRecordId(i)) !== idStr)); break;
        case 'control': setControls(prev => prev.filter(i => String(resolveRecordId(i)) !== idStr)); break;
      }

      // 4. Limpiar Cachés
      switch (type) {
        case 'genetic_improvement': await geneticImprovementsService.clearCache(); break;
        case 'animal_disease': await animalDiseasesService.clearCache(); break;
        case 'animal_field': await animalFieldsService.clearCache(); break;
        case 'vaccination': await vaccinationsService.clearCache(); break;
        case 'treatment': await treatmentsService.clearCache(); break;
        case 'control': await controlService.clearCache(); break;
      }
      if (animal?.id) clearAnimalDependencyCache(animal.id);

      showToast('Registro eliminado correctamente', 'success');
      closeActionModal(); // Cerrar el modal de detalle

      // 5. Trigger refresh global por si acaso
      setDataRefreshTrigger(prev => prev + 1);

    } catch (error: any) {
      if (error.message === "Dependency check failed") return;

      const errorMessage = error.message || error.response?.data?.message || 'Error desconocido';
      const isIntegrityError =
        String(errorMessage).toLowerCase().includes('foreign key') ||
        String(errorMessage).toLowerCase().includes('constraint') ||
        String(errorMessage).toLowerCase().includes('dependenc') ||
        String(errorMessage).toLowerCase().includes('relacionado') ||
        error.status === 409 || error.response?.status === 409;

      if (isIntegrityError) {
        showToast('⚠️ No se puede eliminar este registro porque tiene datos dependientes.', 'error');
      } else if (error.status === 404 || error.response?.status === 404 || String(errorMessage).toLowerCase().includes('no encontrado')) {
        showToast('El registro ya no existe o fue eliminado.', 'info');
        closeActionModal();
        setDataRefreshTrigger(prev => prev + 1);
      } else {
        showToast('Error al eliminar: ' + errorMessage, 'error');
      }
    }
  };

  return (
    <>
      <div ref={scrollContainerRef} className="space-y-4 pb-6 h-full overflow-y-auto pr-2" onKeyDown={(e) => e.stopPropagation()}>
        {/* Banner de imágenes con carrusel - LO PRIMERO - se oculta si no hay imágenes */}
        {!imagesLoading && animalImages.length > 0 && (
          <div className="w-full rounded-xl overflow-hidden shadow-lg -mt-4">
            <AnimalImageBanner
              animalId={animal.id}
              height="clamp(200px, 40vh, 500px)"
              showControls={true}
              autoPlayInterval={5000}
              hideWhenEmpty={true}
              objectFit="contain"
              refreshTrigger={refreshTrigger}
              initialImages={animalImages}
            />
          </div>
        )}

        {/* Header con título y menú de acciones - DEBAJO DEL CARRUSEL */}
        <div className="flex items-start justify-between gap-4 bg-gradient-to-br from-accent/30 to-accent/10 rounded-xl p-4 shadow-md border border-border/50">
          <div className="flex-1 min-w-0">
            <h2 className="text-xl sm:text-2xl font-bold text-foreground truncate" data-testid="animal-modal-title">
              {animal.record || `Animal #${animal.id}`}
            </h2>
            <div className="flex flex-wrap items-center gap-2 mt-1">
              <p className="text-xs sm:text-sm text-muted-foreground">
                ID: {animal.id} • {breedLabel}
              </p>
              {hasRecentTreatments && (
                <Badge className="text-[10px] sm:text-xs bg-amber-500 text-white shadow-sm">
                  Tiene tratamientos recientes (≤ 30 días)
                </Badge>
              )}
            </div>
          </div>
          {/* Menú de acciones (tres puntos) y botón de refresco - visible en PC y móvil */}
          <div className="flex items-center gap-2 flex-shrink-0">
            {onReplicate && (
              <Button
                variant="ghost"
                size="sm"
                className="h-8 w-8 p-0 hover:bg-secondary/20 hover:text-secondary transition-colors hidden sm:flex"
                onClick={onReplicate}
                title="Replicar Animal"
              >
                <Copy className="h-4 w-4" />
              </Button>
            )}
            {onEdit && (
              <Button
                variant="ghost"
                size="sm"
                className="h-8 w-8 p-0 hover:bg-primary/20 hover:text-primary transition-colors hidden sm:flex"
                onClick={onEdit}
                title="Editar Animal"
              >
                <Edit className="h-4 w-4" />
              </Button>
            )}
            <Button
              variant="ghost"
              size="sm"
              className="h-8 w-8 p-0 hover:bg-primary/20 hover:text-primary transition-colors"
              onClick={() => {
                setIsManualRefreshing(true);
                setDataRefreshTrigger(prev => prev + 1);
              }}
              title="Refrescar datos (bypass cache)"
            >
              <RefreshCw className={cn("h-4 w-4", (loading || isManualRefreshing) && "animate-spin")} />
            </Button>
            <AnimalActionsMenu
              animal={animal as AnimalResponse}
              currentUserId={currentUserId}
              onOpenHistory={onOpenHistory}
              onOpenAncestorsTree={onOpenAncestorsTree}
              onOpenDescendantsTree={onOpenDescendantsTree}
              onRefresh={handleRefresh}
            />
          </div>
        </div>

        {/* Alertas de Salud Basadas en Controles */}
        {controls.length >= 2 && (
          <div className="space-y-2">
            {analyzeGrowthTrends(controls.map(c => ({
              date: c.checkup_date,
              weight: c.weight,
              height: c.height
            }))).map((alert, idx) => (
