                const recordId = resolveRecordId(item);
                if (!recordId) {
                  showToast('No se pudo determinar el ID del registro', 'error');
                  return;
                }
                if (confirmingDeleteId === recordId) {
                  setConfirmingDeleteId(null);
                  setDeletingItemId(recordId);

                  // Optimistic update
                  const previousItems = [...controls];
                  setControls(prev => prev.filter((i: any) => String(resolveRecordId(i)) !== String(recordId)));

                  try {
                    await controlService.deleteControl(recordId as any);
                    await controlService.clearCache();
                    if (animal?.id) clearAnimalDependencyCache(animal.id);
                    showToast('Control eliminado correctamente', 'success');


                  } catch (error: any) {
                    // Revert optimistic update
                    setControls(previousItems);

                    const errorMessage = error.message || error.response?.data?.message || 'Error desconocido';
                    if (error.status === 404 || error.response?.status === 404 || String(errorMessage).toLowerCase().includes('no encontrado')) {
                      showToast('El registro ya fue eliminado', 'info');
                      if (animal?.id) clearAnimalDependencyCache(animal.id);
                      setDataRefreshTrigger(prev => prev + 1);
                    } else {
                      showToast('Error al eliminar: ' + errorMessage, 'error');
                    }
                  } finally {
                    setDeletingItemId(null);
                  }
                } else {
                  setConfirmingDeleteId(recordId);
                  showToast('Haz clic de nuevo para confirmar la eliminación', 'warning');
                  setTimeout(() => setConfirmingDeleteId(prev => prev === recordId ? null : prev), 3000);
                }
              }}
              confirmingDeleteId={confirmingDeleteId}
              deletingItemId={deletingItemId}
            />

            {/* Análisis de Crecimiento y Gráficos - Sección Nueva */}
            <CollapsibleCard
              title="Análisis de Crecimiento (Gráficos)"
              accent="blue"
              defaultCollapsed={false}
              data-testid="collapsible-section-growth-analysis"
            >
              <div className="p-2">
                <AnimalMetricsCharts 
                  controls={controls} 
                  onChartClick={() => openListModal('control')}
                />
              </div>
            </CollapsibleCard>
          </div>
        </div>

        {/* Galería e imágenes - Al final */}
        {/* Galería e imágenes - Al final */}
        <CollapsibleCard
          title="Galería de Imágenes"
          defaultCollapsed={true}
          accent="slate"
        >
          {/* Componente unificado de gestión de imágenes */}
          <ImageManager
            animalId={animal.id}
            title=""
            onGalleryUpdate={() => {
              preserveScroll();
              // Refrescar también el estado local
              setDataRefreshTrigger(prev => prev + 1);
              setRefreshTrigger(prev => prev + 1);
              setTimeout(restoreScroll, 0);
            }}
            showControls={true}
            refreshTrigger={refreshTrigger}
            compact={true}
            initialImages={animalImages}
          />
        </CollapsibleCard>

        {/* Modal de detalle para VER */}
        {
          actionModalType && selectedItem && actionModalMode === 'view' && (
            <ItemDetailModal
              type={actionModalType}
              item={selectedItem}
              options={{
                diseases: diseaseOptions,
                fields: fieldOptions,
                vaccines: vaccineOptions,
                users: userOptions
              }}
              onClose={closeActionModal}
              onEdit={() => setActionModalMode('edit')}
              onDelete={() => handleDeleteRecord(actionModalType, selectedItem)}
              zIndex={2000}
            />
          )
        }

        {/* AnimalActionsMenu controlado externamente para CREAR/EDITAR/LISTAR */}
        {
          actionModalType && (actionModalMode === 'create' || actionModalMode === 'list' || actionModalMode === 'edit') && (
            <AnimalActionsMenu
              animal={animal as AnimalResponse}
              currentUserId={currentUserId}
              externalOpenModal={actionModalType}
              externalModalMode={actionModalMode === 'edit' ? 'create' : actionModalMode}
              externalEditingItem={selectedItem}
              onRefresh={handleRefresh}
              onModalClose={closeActionModal}
            />
          )
        }


      </div >

      {/* Modal de insumos de tratamiento (Nivel superior) */}
      <TreatmentSuppliesModal
        isOpen={!!suppliesTreatment}
        onClose={() => setSuppliesTreatment(null)}
        treatment={suppliesTreatment}
        zIndex={2100}
      />
    </>
  );
}

import React from 'react';
import { X, Syringe, MapPin, Pill, ClipboardList, TrendingUp, Edit, Activity, GitBranch, Calendar, Copy, Trash2 } from 'lucide-react';
import { TreatmentSuppliesPanel } from '@/widgets/dashboard/treatments/TreatmentSuppliesPanel';
import { cn } from '@/shared/ui/cn';
import { Badge } from '@/shared/ui/badge';
import { Button } from '@/shared/ui/button';
import { GenericModal } from '@/shared/ui/common/GenericModal';

interface ItemDetailModalProps {
    type: string;
    item: any;
    options: {
        diseases?: Record<number, string>;
        fields?: Record<number, string>;
        vaccines?: Record<number, string>;
        medications?: Record<number, string>;
        users?: Record<number, string>;
        routes?: Record<number, string>;
    };
    onClose: () => void;
    onEdit?: () => void;
    onReplicate?: () => void;
    onDelete?: () => Promise<void> | void;
    zIndex?: number;
}

export function ItemDetailModal({
    type,
    item,
    options,
    onClose,
    onEdit,
    onReplicate,
    onDelete,
    zIndex = 1000
}: ItemDetailModalProps) {
    const [showDeleteConfirm, setShowDeleteConfirm] = React.useState(false);
    const [isDeleting, setIsDeleting] = React.useState(false);

    const handleDeleteClick = async () => {
        if (!onDelete) return;

        if (showDeleteConfirm) {
            // Confirmado
            setIsDeleting(true);
            await onDelete();
            setIsDeleting(false);
            setShowDeleteConfirm(false);
        } else {
            // Primer click
            setShowDeleteConfirm(true);
            // Auto reset timer
            setTimeout(() => {
                setShowDeleteConfirm(current => {
                    // Solo resetear si sigue siendo true (no se ha eliminado ya)
                    return current ? false : current;
                });
            }, 3000);
        }
    };
    // onOpenSupplies removed/unused
    if (!item) return null;

    const formatDate = (dateStr: string) => {
        if (!dateStr) return '-';
        try {
            const date = new Date(dateStr);
            if (isNaN(date.getTime())) return dateStr;
            return date.toLocaleDateString('es-ES', { day: '2-digit', month: '2-digit', year: 'numeric' });
        } catch (e) {
            return dateStr;
        }
    };

    const formatDateTime = (dateStr: string) => {
        if (!dateStr) return '-';
        try {
            const date = new Date(dateStr);
            if (isNaN(date.getTime())) return dateStr;
            return date.toLocaleString('es-ES', {
                day: '2-digit',
                month: '2-digit',
                year: 'numeric',
                hour: '2-digit',
                minute: '2-digit'
            });
        } catch (e) {
            return dateStr;
        }
    };

    const safeOption = (map?: Record<number, string>, id?: number) => {
        if (!id || !map) return id || '-';
        return map[id] || `ID: ${id}`;
    };

    const getTitle = () => {
        const entityNames: Record<string, string> = {
            genetic_improvement: 'Mejora Genética',
            animal_disease: 'Enfermedad Diagnosticada',
            animal_field: 'Asignación de Campo',
            vaccination: 'Aplicación de Vacuna',
            treatment: 'Tratamiento Médico',
            control: 'Control de Crecimiento',
            milk_production: 'Registro de Ordeño',
            vaccine: 'Ficha de Vacuna',
            medication: 'Ficha de Medicamento',
            disease: 'Ficha de Enfermedad'
        };
        return `${entityNames[type] || 'Detalle'} #${item.id}`;
    };

    return (
        <GenericModal
            isOpen={true}
            onOpenChange={(open) => !open && onClose()}
            title={getTitle()}
            description="Información detallada del registro"
            size="2xl"
            enableBackdropBlur
            className="bg-card/95 backdrop-blur-md text-card-foreground border-border/10"
            zIndex={zIndex}
        >
            <div className="space-y-4 py-2">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {/* Genetic Improvement */}
                    {type === 'genetic_improvement' && (
                        <>
                            <DetailSection
                                title="Información del Evento"
                                accent="indigo"
                                icon={<GitBranch className="w-4 h-4" />}
                            >
                                <InfoField label="Técnica" value={item.genetic_event_technique || item.genetic_event_techique || '-'} />
                                <InfoField label="Fecha" value={formatDate(item.date)} />
                                <InfoField label="Resultados" value={item.results || '-'} badge />
                            </DetailSection>
                            <DetailSection
                                title="Detalles Adicionales"
                                accent="slate"
                                fullWidth
                            >
                                <InfoField label="Observaciones" value={item.details || 'Sin detalles adicionales.'} fullWidth />
                            </DetailSection>
                        </>
                    )}

                    {/* Animal Disease */}
                    {type === 'animal_disease' && (
                        <>
                            <DetailSection
                                title="Diagnóstico"
                                accent="red"
                                icon={<Activity className="w-4 h-4" />}
                            >
                                <InfoField label="Enfermedad" value={safeOption(options.diseases, item.disease_id)} fullWidth />
                                <InfoField label="Fecha Diagnóstico" value={formatDate(item.diagnosis_date)} />
                                <InfoField label="Estado" value={item.status || 'Activo'} badge badgeVariant={item.status === 'Activo' ? 'destructive' : 'success'} />
                            </DetailSection>
                            <DetailSection
                                title="Responsable y Notas"
                                accent="slate"
                            >
                                <InfoField label="Instructor" value={safeOption(options.users, item.instructor_id)} />
                                <InfoField label="Notas" value={item.notes || 'Ninguna'} fullWidth />
                            </DetailSection>
                        </>
                    )}

                    {/* Animal Field */}
                    {type === 'animal_field' && (
                        <>
                            <DetailSection
                                title="Ubicación"
                                accent="emerald"
                                icon={<MapPin className="w-4 h-4" />}
                            >
                                <InfoField label="Potrero / Campo" value={safeOption(options.fields, item.field_id)} fullWidth />
                                <InfoField label="Fecha Asignación" value={formatDate(item.assignment_date)} />
                                <InfoField label="Estado" value={item.removal_date ? 'Histórico' : 'Activo'} badge badgeVariant={item.removal_date ? 'secondary' : 'success'} />
                            </DetailSection>
                            <DetailSection
                                title="Tiempos"
                                accent="slate"
                            >
                                <InfoField label="Fecha Retiro" value={item.removal_date ? formatDate(item.removal_date) : '-'} />
                                <InfoField label="Notas" value={item.notes || 'Ninguna'} fullWidth />
                            </DetailSection>
                        </>
                    )}

                    {/* Vaccination */}
                    {type === 'vaccination' && (
                        <>
                            <DetailSection
                                title="Detalle Aplicación"
                                accent="cyan"
                                icon={<Syringe className="w-4 h-4" />}
                            >
                                <InfoField label="Vacuna" value={safeOption(options.vaccines, item.vaccine_id)} fullWidth />
                                <InfoField label="Fecha Aplicación" value={formatDate(item.vaccination_date)} />
                                <InfoField label="Número de Lote" value={item.batch_number || '-'} />
                            </DetailSection>
                            <DetailSection
                                title="Personal Responsable"
                                accent="slate"
                            >
                                <InfoField label="Instructor" value={safeOption(options.users, item.instructor_id)} />
                                <InfoField label="Aprendiz" value={safeOption(options.users, item.apprentice_id)} />
                            </DetailSection>
                        </>
                    )}

                    {/* Treatment */}
                    {type === 'treatment' && (
                        <>
                            <DetailSection
                                title="Plan de Tratamiento"
                                accent="purple"
                                icon={<ClipboardList className="w-4 h-4" />}
                                fullWidth
                            >
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full">
                                    <div className="space-y-3">
                                        <InfoField label="Descripción" value={item.description || '-'} fullWidth />
                                        <InfoField label="Fecha Inicio" value={formatDate(item.treatment_date)} />
                                    </div>
                                    <div className="space-y-3">
                                        <InfoField label="Dosis" value={item.dosis || '-'} />
                                        <InfoField label="Frecuencia" value={item.frequency || '-'} />
                                    </div>
                                </div>
                                {item.observations && <InfoField label="Observaciones" value={item.observations} fullWidth />}
                            </DetailSection>

                            <div className="col-span-full pt-2 border-t border-border/50 mt-2">
                                <TreatmentSuppliesPanel treatment={item} />
                            </div>
                        </>
                    )}
                    
                    {/* Control */}
                    {type === 'control' && (
                        <>
                            <DetailSection
                                title="Métricas de Crecimiento"
                                accent="amber"
                                icon={<TrendingUp className="w-4 h-4" />}
                            >
                                <InfoField label="Fecha" value={formatDate(item.checkup_date)} />
                                <InfoField label="Peso" value={item.weight ? `${item.weight} kg` : '-'} />
                                <InfoField label="Altura" value={item.height ? `${item.height} m` : '-'} />
                            </DetailSection>
                            <DetailSection
                                title="Estado y Notas"
                                accent="slate"
                            >
                                <InfoField label="Estado de Salud" value={item.health_status || '-'} badge badgeVariant={item.health_status === 'Excelente' || item.health_status === 'Bueno' || item.health_status === 'Sano' ? 'success' : 'default'} />
                                <InfoField label="Descripción" value={item.description || 'Sin notas.'} fullWidth />
                            </DetailSection>
                        </>
                    )}
                    
                    {/* Milk Production */}
                    {type === 'milk_production' && (
                        <>
                            <DetailSection
                                title="Detalle de Ordeño"
                                accent="cyan"
                                icon={<Activity className="w-4 h-4" />}
                            >
                                <InfoField label="Fecha" value={formatDate(item.date)} />
                                <InfoField label="Sesión" value={item.session} badge />
                                <InfoField label="Litros" value={`${item.liters} L`} badge badgeVariant="success" />
                            </DetailSection>
                            <DetailSection
                                title="Calidad y Notas"
                                accent="slate"
                            >
                                <InfoField label="Grasa (%)" value={item.fat_percentage ? `${item.fat_percentage}%` : '-'} />
                                <InfoField label="Proteína (%)" value={item.protein_percentage ? `${item.protein_percentage}%` : '-'} />
                                <InfoField label="Notas" value={item.notes || 'Ninguna'} fullWidth />
                            </DetailSection>
                        </>
                    )}

                    {/* Master Data: Vaccine / Medication */}
                    {(type === 'vaccine' || type === 'medication' || type === 'disease') && (
                        <>
                            <DetailSection
                                title="Información Básica"
                                accent="cyan"
                                icon={type === 'vaccine' ? <Syringe className="w-4 h-4" /> : type === 'medication' ? <Pill className="w-4 h-4" /> : <Activity className="w-4 h-4" />}
                            >
                                <InfoField label="Nombre" value={item.name || item.disease || '-'} fullWidth />
                                <div className="grid grid-cols-2 gap-4 w-full">
                                    <InfoField label="ID" value={`#${item.id}`} />
                                    {type === 'vaccine' ? (
                                        <InfoField label="Tipo" value={item.type || '-'} badge />
                                    ) : type === 'medication' ? (
                                        <InfoField label="Disponibilidad" value={item.availability ? 'Disponible' : 'No disponible'} badge badgeVariant={item.availability ? 'success' : 'destructive'} />
                                    ) : (
                                        <InfoField label="Código" value={item.code || '-'} />
                                    )}
                                </div>
                            </DetailSection>

                            {type !== 'disease' && (
                                <DetailSection
                                    title={type === 'vaccine' ? 'Especificaciones' : 'Detalles de Uso'}
                                    accent="teal"
                                >
                                    <InfoField label="Dosis" value={item.dosis || item.dose || '-'} />
                                    <InfoField label="Vía de Administración" value={item.route_administration_name || item.administration_route_name || '-'} />
                                    {type === 'vaccine' ? (
                                        <InfoField label="Intervalo" value={item.dose_interval || item.vaccination_interval ? `${item.dose_interval || item.vaccination_interval} días` : '-'} />
                                    ) : (
                                        <InfoField label="Frecuencia" value={item.frequency || '-'} />
                                    )}
                                </DetailSection>
                            )}

                            <DetailSection
                                title="Descripción y Notas"
                                accent="slate"
                                fullWidth
                            >
                                <p className="text-sm text-slate-600 dark:text-slate-400 leading-relaxed italic">
                                    {item.description || item.indications || item.details || item.symptoms || 'Sin información adicional.'}
                                </p>
                                {(item.contraindications || item.precautions) && (
                                    <div className="mt-3 pt-3 border-t border-slate-200/40">
                                        <InfoField label="Contraindicaciones / Precauciones" value={item.contraindications || item.precautions} fullWidth />
                                    </div>
                                )}
                            </DetailSection>
                        </>
                    )}
                </div>

                {/* Auditoría del Sistema */}
                <div className="bg-slate-50/50 dark:bg-slate-950/20 rounded-xl p-3 border border-border/10">
                    <div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest text-muted-foreground/60 mb-2">
                        <Calendar className="w-3 h-3" />
                        Registro del Sistema
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <InfoField label="Creado" value={formatDateTime(item.created_at)} />
                        <InfoField label="Actualizado" value={item.updated_at ? formatDateTime(item.updated_at) : '-'} />
                    </div>
                </div>
            </div>

            {/* Footer */}
            <div className="flex items-center justify-end gap-3 pt-6 mt-4 border-t border-border/40">
                {onDelete && (
                    <Button
                        variant={showDeleteConfirm ? "destructive" : "outline"}
                        onClick={handleDeleteClick}
                        className={cn(
                            "rounded-xl px-4 mr-auto",
                            showDeleteConfirm ? "bg-red-600 text-white hover:bg-red-700" : "text-red-600 border-red-200 hover:bg-red-50 dark:border-red-900/30 dark:hover:bg-red-900/10"
                        )}
                        disabled={isDeleting}
                    >
                        {isDeleting ? (
                            <>
                                <div className="w-3 h-3 border-2 border-white/50 border-t-white rounded-full animate-spin mr-2" />
                                Eliminando...
                            </>
                        ) : showDeleteConfirm ? (
                            <>
                                <X className="h-4 w-4 mr-2" />
                                ¿Seguro?
                            </>
                        ) : (
                            <>
                                <Trash2 className="h-4 w-4 mr-2" />
                                Eliminar
                            </>
                        )}
                    </Button>
                )}

                <Button variant="outline" onClick={onClose} className="rounded-xl px-6">
                    Cerrar
                </Button>
                {onReplicate && (
                    <Button
                        onClick={onReplicate}
                        variant="secondary"
                        className="rounded-xl px-6 bg-secondary/80 hover:bg-secondary text-secondary-foreground shadow-sm hover:opacity-90 active:scale-95 transition-all"
                    >
                        <Copy className="h-4 w-4 mr-2" />
                        Replicar
                    </Button>
                )}
                {onEdit && (
                    <Button
                        onClick={onEdit}
                        className="rounded-xl px-6 bg-primary text-white shadow-lg shadow-primary/20 hover:opacity-90 active:scale-95 transition-all"
                    >
                        <Edit className="h-4 w-4 mr-2" />
                        Editar Registro
                    </Button>
                )}
            </div>
        </GenericModal>
    );
}

export function DetailSection({
    title,
    children,
    accent = 'blue',
    fullWidth = false,
    icon
}: {
    title: string;
    children: React.ReactNode;
    accent?: string;
    fullWidth?: boolean;
    icon?: React.ReactNode;
}) {
    const accentClasses: Record<string, string> = {
        blue: "text-blue-700 dark:text-blue-300 before:bg-blue-500 shadow-blue-500/10",
        cyan: "text-cyan-700 dark:text-cyan-300 before:bg-cyan-500 shadow-cyan-500/10",
        teal: "text-teal-700 dark:text-teal-300 before:bg-teal-500 shadow-teal-500/10",
        emerald: "text-emerald-700 dark:text-emerald-300 before:bg-emerald-500 shadow-emerald-500/10",
        purple: "text-purple-700 dark:text-purple-300 before:bg-purple-500 shadow-purple-500/10",
        indigo: "text-indigo-700 dark:text-indigo-300 before:bg-indigo-500 shadow-indigo-500/10",
        red: "text-red-700 dark:text-red-300 before:bg-red-500 shadow-red-500/10",
        amber: "text-amber-700 dark:text-amber-300 before:bg-amber-500 shadow-amber-500/10",
        slate: "text-slate-700 dark:text-slate-300 before:bg-slate-500 shadow-slate-500/10",
    };

    const classes = accentClasses[accent] || accentClasses.slate;
    const [textClasses, barClasses] = [
        classes.split(' before:')[0],
        classes.split(' before:')[1]
    ];

    return (
        <div className={cn(
            "rounded-xl p-4 shadow-sm border transition-all hover:shadow-md h-full flex flex-col bg-card border-border/60",
            fullWidth && "col-span-full"
        )}>
            <h4 className={cn(
                "text-[10px] font-bold uppercase tracking-wider mb-3 flex items-center gap-2",
                textClasses
            )}>
                {icon}
                <span className={cn("flex items-center gap-2 before:content-[''] before:w-1 before:h-3 before:rounded-full", barClasses)}>
                    {title}
                </span>
            </h4>
            <div className="space-y-3 flex-grow">
                {children}
            </div>
        </div>
    );
}

export function InfoField({
    label,
    value,
    fullWidth = false,
    badge = false,
    badgeVariant = 'default'
}: {
    label: string;
    value: any;
    fullWidth?: boolean;
    badge?: boolean;
    badgeVariant?: 'default' | 'secondary' | 'destructive' | 'success' | 'outline';
}) {
    const displayValue = value !== null && value !== undefined ? String(value) : '-';

    return (
        <div className={cn("space-y-1", fullWidth && "col-span-full")}>
            <div className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground/70">
                {label}
            </div>
            {badge ? (
                <Badge
                    variant={badgeVariant as any}
                    className={cn(
                        "text-[10px] px-2 py-0 h-5",
                        badgeVariant === 'success' && "bg-green-600 text-white"
                    )}
                >
                    {displayValue}
                </Badge>
            ) : (
                <div className={cn(
                    "text-xs sm:text-sm font-medium text-foreground/90",
                    fullWidth && "whitespace-pre-wrap leading-relaxed"
                )}>
                    {displayValue}
                </div>
            )}
        </div>
    );
}

import React, { useState, useEffect, useCallback } from 'react';
import { ChevronLeft, ChevronRight, Image as ImageIcon } from 'lucide-react';
import { animalImageService, type AnimalImage } from '@/entities/animal/api/animalImage.service';

interface ParentMiniCardProps {
  parentId: number | null | undefined;
  parentLabel: string;
  gender: 'Padre' | 'Madre';
  onClick?: () => void;
}

/**
 * Mini card elegante y minimalista con carrusel de imágenes para mostrar padre/madre
 * Centrada en las fotos para permitir reconocimiento visual
 */
export function ParentMiniCard({ parentId, parentLabel, gender, onClick }: ParentMiniCardProps) {
  const [images, setImages] = useState<AnimalImage[]>([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [loading, setLoading] = useState(true);
  const [imageErrors, setImageErrors] = useState<Set<number>>(new Set());

  const fetchImages = useCallback(async () => {
    if (!parentId || parentId <= 0) {
      setLoading(false);
      return;
    }

    setLoading(true);
    setImageErrors(new Set());
    setCurrentIndex(0);
    try {
      const response = await animalImageService.getAnimalImages(parentId);
      if (response.success && response.data.images.length > 0) {
        // Ordenar: imagen principal primero
        const sorted = [...response.data.images].sort((a, b) => {
          if (a.is_primary) return -1;
          if (b.is_primary) return 1;
          return 0;
        });
        setImages(sorted);
      } else if (response.errorCode === 'NOT_FOUND') {
        setImages([]);
      } else {
        setImages([]);
      }
    } catch (err) {
      console.error(`Error al cargar imágenes del ${gender.toLowerCase()}:`, err);
      setImages([]);
    } finally {
      setLoading(false);
    }
  }, [parentId, gender]);

  useEffect(() => {
    fetchImages();
  }, [fetchImages]);

  // Refrescar al recibir evento global (para que se actualice sin F5)
  useEffect(() => {
    const handler = (e: Event) => {
      const detail = (e as CustomEvent).detail as { animalId?: number } | undefined;
      if (!detail?.animalId) return;
      if (detail.animalId === parentId) {
        fetchImages();
      }
    };
    window.addEventListener('animal-images:updated', handler as EventListener);
    return () => window.removeEventListener('animal-images:updated', handler as EventListener);
  }, [parentId, fetchImages]);

  const goToPrevious = (e: React.MouseEvent) => {
    e.stopPropagation();
    setCurrentIndex((prev) => (prev === 0 ? images.length - 1 : prev - 1));
  };

  const goToNext = (e: React.MouseEvent) => {
    e.stopPropagation();
    setCurrentIndex((prev) => (prev + 1) % images.length);
  };

  // Si no hay parentId, mostrar card vacía
  if (!parentId) {
    return (
      <div className="relative group rounded-xl overflow-hidden bg-gradient-to-br from-muted/30 to-muted/10 border-2 border-dashed border-border/50 aspect-[4/3] flex flex-col items-center justify-center p-3">
        <ImageIcon className="w-8 h-8 text-muted-foreground/40 mb-1.5" />
        <p className="text-xs font-medium text-muted-foreground/60">{gender}</p>
        <p className="text-[10px] text-muted-foreground/40">Sin registro</p>
      </div>
    );
  }

  return (
    <div
      onClick={onClick}
      className="relative group rounded-xl overflow-hidden bg-gradient-to-br from-accent/20 to-accent/5 border border-border/60 hover:border-primary/50 aspect-[4/3] cursor-pointer transition-all duration-300 hover:shadow-xl hover:scale-[1.02] active:scale-[0.98]"
    >
      {/* Carrusel de imágenes */}
      <div className="absolute inset-0 w-full h-full">
        {loading ? (
          <div className="w-full h-full flex items-center justify-center bg-muted/10">
            <ImageIcon className="w-10 h-10 text-muted-foreground/40 animate-pulse" />
          </div>
        ) : images.length === 0 ? (
          <div className="w-full h-full flex items-center justify-center bg-gradient-to-br from-muted/20 to-muted/5">
            <div className="text-center">
              <ImageIcon className="w-10 h-10 mx-auto text-muted-foreground/40 mb-1" />
              <p className="text-[10px] text-muted-foreground/50">Sin fotos</p>
            </div>
          </div>
        ) : (
          <>
            {/* Imágenes con transición */}
            {images.map((image, index) => (
              <div
                key={image.id}
                className={`absolute inset-0 w-full h-full transition-all duration-500 ease-in-out ${
                  index === currentIndex
                    ? 'opacity-100 scale-100 z-10'
                    : 'opacity-0 scale-95 z-0'
                }`}
              >
                {imageErrors.has(image.id) ? (
                  <div className="w-full h-full flex items-center justify-center bg-muted/10">
                    <ImageIcon className="w-8 h-8 text-muted-foreground/30" />
                  </div>
                ) : (
                  <img
                    src={image.url}
                    alt={image.filename}
                    className="w-full h-full object-cover"
                    loading="lazy"
                    onError={() => {
                      setImageErrors((prev) => new Set(prev).add(image.id));
                    }}
                  />
                )}
              </div>
            ))}

            {/* Controles de navegación - aparecen al hover */}
            {images.length > 1 && (
              <>
                <button
                  onClick={goToPrevious}
                  className="absolute left-1 top-1/2 -translate-y-1/2 z-20 opacity-0 group-hover:opacity-100 transition-opacity duration-300 p-1 rounded-full bg-black/60 hover:bg-black/80 text-white backdrop-blur-sm"
                  aria-label="Imagen anterior"
                >
                  <ChevronLeft className="w-3.5 h-3.5" />
                </button>

                <button
                  onClick={goToNext}
                  className="absolute right-1 top-1/2 -translate-y-1/2 z-20 opacity-0 group-hover:opacity-100 transition-opacity duration-300 p-1 rounded-full bg-black/60 hover:bg-black/80 text-white backdrop-blur-sm"
                  aria-label="Imagen siguiente"
                >
                  <ChevronRight className="w-3.5 h-3.5" />
                </button>

                {/* Indicadores de puntos */}
                <div className="absolute bottom-2 left-0 right-0 flex justify-center gap-1 z-20 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                  <div className="flex gap-1 bg-black/40 backdrop-blur-sm rounded-full px-1.5 py-0.5">
                    {images.map((_, index) => (
                      <div
                        key={index}
                        className={`rounded-full transition-all duration-300 ${
                          index === currentIndex
                            ? 'bg-white w-3 h-1.5'
                            : 'bg-white/50 w-1.5 h-1.5'
                        }`}
                      />
                    ))}
                  </div>
                </div>
              </>
            )}

            {/* Overlay gradient sutil para mejor legibilidad del texto */}
            <div className="absolute inset-0 bg-gradient-to-t from-black/40 via-transparent to-transparent pointer-events-none z-[5]" />
          </>
        )}
      </div>

      {/* Información del padre/madre - siempre visible */}
      <div className="absolute bottom-0 left-0 right-0 z-10 p-2 bg-gradient-to-t from-black/70 via-black/50 to-transparent backdrop-blur-[1px]">
        <div className="text-[10px] uppercase tracking-wider font-bold text-white/80 mb-0.5">
          {gender}
        </div>
        <div className="text-sm font-bold text-white truncate drop-shadow-lg">
          {parentLabel}
        </div>
      </div>

      {/* Indicador de click - sutil */}
      <div className="absolute top-2 right-2 z-10 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
        <div className="w-6 h-6 rounded-full bg-primary/80 backdrop-blur-sm flex items-center justify-center shadow-lg">
          <svg className="w-3.5 h-3.5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 5l7 7-7 7" />
          </svg>
        </div>
      </div>
    </div>
  );
}

