  );
};

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/shared/ui/card';
import { Badge } from '@/shared/ui/badge';
import { Button } from '@/shared/ui/button';
import { Activity, TrendingUp, FileText, Milk, Sparkles, Zap, ChevronRight } from 'lucide-react';
import { milkService } from '@/entities/milk/api/milk.service';
import { controlService } from '@/entities/control/api/control.service';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { motion } from 'framer-motion';
import { cn } from '@/shared/ui/cn';

export function PerformanceReport({ animal }: { animal: any }) {
  const [loading, setLoading] = useState(true);
  const [metrics, setMetrics] = useState<any>(null);

  useEffect(() => {
    const loadData = async () => {
      setLoading(true);
      try {
        const [milkData, controls] = await Promise.all([
          milkService.getByAnimal(animal.id),
          controlService.getControls({ animal_id: animal.id })
        ]);

        const milkArray = Array.isArray(milkData) ? milkData : (milkData?.data || []);
        const controlsArray = Array.isArray(controls) ? controls : (controls?.data || []);

        const totalLiters = milkArray.reduce((sum: number, r: any) => sum + r.liters, 0);
        const avgLiters = milkArray.length > 0 ? (totalLiters / milkArray.length).toFixed(2) : '0';

        const sortedControls = [...controlsArray].sort((a: any, b: any) => 
          new Date(a.checkup_date).getTime() - new Date(b.checkup_date).getTime()
        );

        let weightGain = '0';
        if (sortedControls.length >= 2) {
          const first = sortedControls[0];
          const last = sortedControls[sortedControls.length - 1];
          const weightDiff = last.weight - first.weight;
          const daysDiff = (new Date(last.checkup_date).getTime() - new Date(first.checkup_date).getTime()) / (1000 * 60 * 60 * 24);
          if (daysDiff > 0) {
            weightGain = (weightDiff / (daysDiff / 30)).toFixed(2);
          }
        }

        // Datos para la gráfica (últimos 10 ordeños)
        const chartData = milkArray
          .slice(-10)
          .map((m: any) => ({
            date: new Date(m.date).toLocaleDateString('es-CO', { day: '2-digit', month: 'short' }),
            litros: m.liters
          }));

        setMetrics({
          milk: { total: totalLiters.toFixed(1), avg: avgLiters, count: milkArray.length, history: milkArray, chartData },
          growth: { currentWeight: animal.weight, monthlyGain: weightGain, history: sortedControls }
        });
      } catch (err) {
        console.error('Error loading performance data:', err);
      } finally {
        setLoading(false);
      }
    };
    loadData();
  }, [animal]);

  const generatePDF = () => {
    const doc = new jsPDF();
    const runAutoTable = (docObj: any, options: any) => {
       try {
         if (typeof autoTable === 'function') autoTable(docObj, options);
         else if (typeof (autoTable as any).default === 'function') (autoTable as any).default(docObj, options);
       } catch (e) { console.error(e); }
    };

    doc.setFontSize(22);
    doc.setTextColor(15, 23, 42);
    doc.text('REPORTE DE RENDIMIENTO VILLA LUZ', 20, 20);

    doc.setFontSize(10);
    doc.setTextColor(100, 100, 100);
    doc.text(`Expedido: ${new Date().toLocaleString('es-CO')}`, 20, 30);
    doc.text(`Ejemplar: ${animal.record} | Raza: ${animal.breed_name || 'N/A'}`, 20, 35);

    runAutoTable(doc, {
      startY: 50,
      head: [['Métrica', 'Valor', 'Estado']],
      body: [
        ['Producción Total', `${metrics.milk.total} L`, 'Certificado'],
        ['Promedio Diario', `${metrics.milk.avg} L/día`, 'Estable'],
        ['Ganancia de Peso', `${metrics.growth.monthlyGain} kg/mes`, 'Óptimo'],
        ['Peso Actual', `${metrics.growth.currentWeight} kg`, 'En Rango']
      ],
      headStyles: { fillColor: [15, 23, 42] }
    });

    doc.save(`VillaLuz_Pro_${animal.record}.pdf`);
  };

  if (loading) return (
    <div className="p-20 flex flex-col items-center justify-center space-y-4">
      <div className="h-10 w-10 border-4 border-primary border-t-transparent rounded-full animate-spin" />
      <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Analizando Bio-Métricas...</p>
    </div>
  );

  return (
    <div className="space-y-8">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}>
          <Card className="overflow-hidden border-0 bg-gradient-to-br from-sky-500 to-blue-600 text-white shadow-xl shadow-blue-500/20 rounded-[2rem]">
            <CardContent className="p-8">
               <div className="flex justify-between items-start mb-6">
                  <div className="h-12 w-12 rounded-2xl bg-white/20 backdrop-blur-md flex items-center justify-center">
                    <Milk className="h-6 w-6" />
                  </div>
                  <Badge className="bg-white/20 text-white border-0 text-[9px] font-black uppercase tracking-widest px-3 py-1">Lactancia Activa</Badge>
               </div>
               <p className="text-sm font-bold text-blue-100 uppercase tracking-widest mb-1">Promedio de Ordeño</p>
