import React from 'react';
import { Syringe, Pill, Trash2 } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Badge } from '@/shared/ui/badge';

interface VaccineItem {
    id: number;
    vaccine_id: number;
    vaccine_name?: string;
    dose?: string;
    notes?: string;
}

interface MedicationItem {
    id: number;
    medication_id: number;
    medication_name?: string;
    dosage?: string;
    dose?: string;
    frequency?: string;
    duration_days?: number;
    notes?: string;
}

interface TreatmentSuppliesCardsProps {
    vaccines: VaccineItem[];
    medications: MedicationItem[];
    vaccineFullMap?: Record<number, any>;
    medicationFullMap?: Record<number, any>;
    vaccineRouteMap?: Record<number, string>;
    onViewVaccine?: (vaccineId: number) => void;
    onViewMedication?: (medicationId: number) => void;
    onDeleteVaccine?: (item: VaccineItem) => void;
    onDeleteMedication?: (item: MedicationItem) => void;
    confirmingDeleteId?: number | null;
    deleteLoadingId?: { type: 'vaccine' | 'medication'; id: number } | null;
    loading?: boolean;
    loadingVaccines?: boolean;
    loadingMedications?: boolean;
    className?: string;
}

export const TreatmentSuppliesCards: React.FC<TreatmentSuppliesCardsProps> = ({
    vaccines,
    medications,
    vaccineFullMap = {},
    medicationFullMap = {},
    vaccineRouteMap = {},
    onViewVaccine,
    onViewMedication,
    onDeleteVaccine,
    onDeleteMedication,
    confirmingDeleteId,
    deleteLoadingId,
    loading = false,
    loadingVaccines = false,
    loadingMedications = false,
    className = ''
}) => {
    // Si está cargando todo y NO hay nada de datos
    const showFullLoader = loading && vaccines.length === 0 && medications.length === 0;

    if (showFullLoader) {
        return (
            <div className="py-12 flex flex-col items-center justify-center text-muted-foreground animate-pulse">
                <Syringe className="w-8 h-8 mb-2 opacity-50" />
                <span>Cargando insumos...</span>
            </div>
        );
    }

    return (
        <div className={`grid grid-cols-1 lg:grid-cols-2 gap-4 relative ${className}`}>

            {/* Vacunas */}
            <div className="rounded-xl border border-cyan-200/60 dark:border-cyan-800/60 bg-card p-4 shadow-md has-[.group:hover]:shadow-lg transition-all duration-300 relative overflow-hidden">
                {(loading || loadingVaccines) && (
                    <div className="absolute inset-0 z-10 bg-background/50 backdrop-blur-[1px] flex items-center justify-center transition-all duration-300">
                        <div className="bg-background/80 px-3 py-1.5 rounded-full shadow-md border border-border flex items-center gap-2">
                            <div className="w-3.5 h-3.5 rounded-full border-2 border-cyan-500 border-t-transparent animate-spin" />
                            <span className="text-[10px] font-medium text-muted-foreground">Actualizando...</span>
                        </div>
                    </div>
                )}
                <h3 className="font-semibold mb-4 flex items-center gap-2 text-cyan-800 dark:text-cyan-300 border-b border-cyan-100 dark:border-cyan-800/50 pb-2">
                    <div className="p-1.5 rounded-full bg-cyan-50 dark:bg-cyan-900/40">
                        <Syringe className="w-4 h-4" />
                    </div>
                    Vacunas
                    <Badge variant="secondary" className="ml-auto bg-cyan-100 text-cyan-700 dark:bg-cyan-900/50 dark:text-cyan-300">
                        {vaccines.length}
                    </Badge>
                </h3>
                <div className="space-y-2 max-h-[400px] overflow-y-auto pr-1">
                    {vaccines.length === 0 ? (
                        <p className="text-sm text-muted-foreground py-8 text-center italic opacity-60">No hay vacunas asociadas.</p>
                    ) : (
                        vaccines.map(v => {
                            const fullVacc = v.vaccine_id ? vaccineFullMap[Number(v.vaccine_id)] : null;
                            return (
                                <div
                                    key={v.id}
                                    className="border border-border/60 bg-background/50 hover:bg-cyan-50/40 dark:hover:bg-cyan-900/20 rounded-lg p-3 text-sm flex items-center gap-4 cursor-pointer hover:border-cyan-200 dark:hover:border-cyan-800 transition-all group"
                                    onClick={() => onViewVaccine?.(Number(v.vaccine_id))}
                                >
                                    {/* Left: Icon & Name */}
                                    <div className="flex flex-col min-w-[100px] max-w-[180px]">
                                        <div className="font-bold text-foreground/90 truncate group-hover:text-cyan-700 dark:group-hover:text-cyan-300 transition-colors flex items-center gap-2">
                                            <Syringe className="w-3.5 h-3.5 flex-shrink-0 opacity-70" />
                                            <span title={fullVacc?.name || v.vaccine_name || ''}>{fullVacc?.name || v.vaccine_name || `Vacuna #${v.vaccine_id}`}</span>
                                        </div>
                                        <div className="flex items-center gap-2 mt-1.5">
                                            <Badge variant="outline" className="text-[10px] h-4 px-1 rounded-md font-normal text-muted-foreground border-border/60">
                                                #{v.vaccine_id}
                                            </Badge>
                                            {fullVacc?.type && (
                                                <span className="text-[10px] text-muted-foreground px-1 border-l border-border/50 truncate max-w-[80px]">
                                                    {fullVacc.type}
                                                </span>
                                            )}
                                        </div>
                                    </div>

                                    {/* Middle: Details Grid */}
                                    <div className="flex-1 grid grid-cols-3 gap-x-3 gap-y-1 text-xs text-muted-foreground border-l border-r border-border/40 px-3 min-w-0">
                                        <div className="flex flex-col">
                                            <span className="text-[9px] uppercase opacity-50 font-bold tracking-wider">Dosis</span>
                                            <span className="font-medium text-foreground">{v.dose || '-'}</span>
                                        </div>
                                        <div className="flex flex-col">
                                            <span className="text-[9px] uppercase opacity-50 font-bold tracking-wider">Vía</span>
                                            <span className="font-medium text-foreground">
                                                {(v.vaccine_id && vaccineRouteMap[Number(v.vaccine_id)]) || '-'}
                                            </span>
                                        </div>
                                        <div className="flex flex-col">
                                            <span className="text-[9px] uppercase opacity-50 font-bold tracking-wider">Intervalo</span>
                                            <span className="font-medium text-foreground">
                                                {fullVacc?.vaccination_interval ? `${fullVacc.vaccination_interval} días` : '-'}
                                            </span>
                                        </div>
                                    </div>

                                    {/* Right: Actions */}
                                    {onDeleteVaccine && (
                                        <Button
                                            size="icon"
                                            variant="ghost"
                                            className={`h-8 w-8 transition-all duration-200 rounded-full ${confirmingDeleteId === v.id
                                                ? 'bg-red-600 text-white shadow-lg shadow-red-500/50 animate-pulse scale-110 opacity-100'
                                                : 'opacity-0 group-hover:opacity-100 hover:bg-destructive/10 hover:text-destructive'
                                                }`}
                                            onClick={(e) => { e.stopPropagation(); onDeleteVaccine(v); }}
                                            disabled={deleteLoadingId?.type === 'vaccine' && deleteLoadingId?.id === v.id}
                                            title={confirmingDeleteId === v.id ? "¡Confirmar!" : "Desvincular"}
                                        >
                                            {deleteLoadingId?.type === 'vaccine' && deleteLoadingId?.id === v.id ? (
                                                <div className="w-3.5 h-3.5 border-2 border-primary border-t-transparent rounded-full animate-spin" />
                                            ) : confirmingDeleteId === v.id ? (
                                                <span className="text-[10px] font-bold">✓</span>
                                            ) : (
                                                <Trash2 className="w-4 h-4" />
                                            )}
                                        </Button>
                                    )}
                                </div>
                            );
                        })
                    )}
                </div>
            </div>

            {/* Medicamentos */}
            <div className="rounded-xl border border-purple-200/60 dark:border-purple-800/60 bg-card p-4 shadow-md has-[.group:hover]:shadow-lg transition-all duration-300 relative overflow-hidden">
                {(loading || loadingMedications) && (
                    <div className="absolute inset-0 z-10 bg-background/50 backdrop-blur-[1px] flex items-center justify-center transition-all duration-300">
                        <div className="bg-background/80 px-3 py-1.5 rounded-full shadow-md border border-border flex items-center gap-2">
                            <div className="w-3.5 h-3.5 rounded-full border-2 border-purple-500 border-t-transparent animate-spin" />
                            <span className="text-[10px] font-medium text-muted-foreground">Actualizando...</span>
                        </div>
                    </div>
                )}
                <h3 className="font-semibold mb-4 flex items-center gap-2 text-purple-800 dark:text-purple-300 border-b border-purple-100 dark:border-purple-800/50 pb-2">
                    <div className="p-1.5 rounded-full bg-purple-50 dark:bg-purple-900/40">
                        <Pill className="w-4 h-4" />
                    </div>
                    Medicamentos
                    <Badge variant="secondary" className="ml-auto bg-purple-100 text-purple-700 dark:bg-purple-900/50 dark:text-purple-300">
                        {medications.length}
                    </Badge>
                </h3>
                <div className="space-y-2 max-h-[400px] overflow-y-auto pr-1">
                    {medications.length === 0 ? (
                        <p className="text-sm text-muted-foreground py-8 text-center italic opacity-60">No hay medicamentos asociados.</p>
                    ) : (
                        medications.map(m => {
                            const fullMed = m.medication_id ? medicationFullMap[Number(m.medication_id)] : null;
                            return (
                                <div
                                    key={m.id}
                                    className="border border-border/60 bg-background/50 hover:bg-purple-50/40 dark:hover:bg-purple-900/20 rounded-lg p-3 text-sm flex items-center gap-4 cursor-pointer hover:border-purple-200 dark:hover:border-purple-800 transition-all group"
                                    onClick={() => onViewMedication?.(Number(m.medication_id))}
                                >
                                    {/* Left: Icon & Name */}
                                    <div className="flex flex-col min-w-[100px] max-w-[180px]">
                                        <div className="font-bold text-foreground/90 truncate group-hover:text-purple-700 dark:group-hover:text-purple-300 transition-colors flex items-center gap-2">
                                            <Pill className="w-3.5 h-3.5 flex-shrink-0 opacity-70" />
                                            <span title={fullMed?.name || m.medication_name || ''}>{fullMed?.name || m.medication_name || `Med. #${m.medication_id}`}</span>
                                        </div>
                                        <div className="flex items-center gap-2 mt-1.5">
                                            <Badge variant="outline" className="text-[10px] h-4 px-1 rounded-md font-normal text-muted-foreground border-border/60">
                                                #{m.medication_id}
                                            </Badge>
                                            {fullMed?.concentration && (
                                                <span className="text-[10px] text-muted-foreground px-1 border-l border-border/50 truncate max-w-[80px]">
                                                    {fullMed.concentration}
                                                </span>
                                            )}
                                        </div>
                                    </div>

                                    {/* Middle: Details Grid */}
                                    <div className="flex-1 grid grid-cols-3 gap-x-3 gap-y-1 text-xs text-muted-foreground border-l border-r border-border/40 px-3 min-w-0">
                                        <div className="flex flex-col">
                                            <span className="text-[9px] uppercase opacity-50 font-bold tracking-wider">Dosis</span>
                                            <span className="font-medium text-foreground">{m.dosage || m.dose || '-'}</span>
                                        </div>
                                        <div className="flex flex-col">
                                            <span className="text-[9px] uppercase opacity-50 font-bold tracking-wider">Frecuencia</span>
                                            <span className="font-medium text-foreground">{m.frequency || '-'}</span>
                                        </div>
                                        <div className="flex flex-col">
                                            <span className="text-[9px] uppercase opacity-50 font-bold tracking-wider">Duración</span>
                                            <span className="font-medium text-foreground">
                                                {m.duration_days ? `${m.duration_days} días` : '-'}
                                            </span>
                                        </div>
                                    </div>

                                    {/* Right: Actions */}
                                    {onDeleteMedication && (
                                        <Button
                                            size="icon"
                                            variant="ghost"
                                            className={`h-8 w-8 transition-all duration-200 rounded-full ${confirmingDeleteId === m.id
                                                ? 'bg-red-600 text-white shadow-lg shadow-red-500/50 animate-pulse scale-110 opacity-100'
                                                : 'opacity-0 group-hover:opacity-100 hover:bg-destructive/10 hover:text-destructive'
                                                }`}
                                            onClick={(e) => { e.stopPropagation(); onDeleteMedication(m); }}
                                            disabled={deleteLoadingId?.type === 'medication' && deleteLoadingId?.id === m.id}
                                            title={confirmingDeleteId === m.id ? "¡Confirmar!" : "Desvincular"}
                                        >
                                            {deleteLoadingId?.type === 'medication' && deleteLoadingId?.id === m.id ? (
                                                <div className="w-3.5 h-3.5 border-2 border-primary border-t-transparent rounded-full animate-spin" />
                                            ) : confirmingDeleteId === m.id ? (
                                                <span className="text-[10px] font-bold">✓</span>
                                            ) : (
                                                <Trash2 className="w-4 h-4" />
                                            )}
                                        </Button>
                                    )}
                                </div>
                            );
                        })
                    )}
                </div>
            </div>
        </div>
    );
};

export default TreatmentSuppliesCards;

import React, { useEffect, useState, useMemo, useCallback, useRef } from 'react';
import { cn } from '@/shared/ui/cn';
import { Settings, Plus, Trash2, Search, Filter, RefreshCw, Syringe, Pill, Save, X, Eye, FileText, CheckSquare, Square, ArrowUpDown } from 'lucide-react';
import { GenericModal } from '@/shared/ui/common/GenericModal';
import { Button } from '@/shared/ui/button';
import { Badge } from '@/shared/ui/badge';
import { Card, CardHeader, CardTitle, CardContent } from '@/shared/ui/card';
import { Checkbox } from '@/shared/ui/checkbox';
import { Toolbar } from '@/shared/ui/common/Toolbar';
import { useToast } from '@/app/providers/ToastContext';
import { TreatmentResponse, VaccineResponse, MedicationResponse, TreatmentVaccineResponse, TreatmentMedicationResponse } from '@/shared/api/generated/swaggerTypes';
import { vaccinesService } from '@/entities/vaccine/api/vaccines.service';
import { medicationsService } from '@/entities/medication/api/medications.service';
import { treatmentVaccinesService } from '@/entities/treatment-vaccine/api/treatmentVaccines.service';
import { treatmentMedicationService } from '@/entities/treatment-medication/api/treatmentMedication.service';
import { TreatmentSuppliesCards } from './TreatmentSuppliesCards';
import { ItemDetailModal, DetailSection, InfoField } from '../animals/ItemDetailModal';
import { ConfirmDialog } from '@/shared/ui/common/ConfirmDialog';
import { ClipboardList } from 'lucide-react';

interface TreatmentSuppliesModalProps {
    isOpen: boolean;
    onClose: () => void;
    treatment: TreatmentResponse | null;
    className?: string;
    zIndex?: number;
}

export const TreatmentSuppliesModal: React.FC<TreatmentSuppliesModalProps> = ({
    isOpen,
    onClose,
    treatment,
    className,
    zIndex
}) => {
    const { showToast } = useToast();

    // Data State
    const [vaccines, setVaccines] = useState<TreatmentVaccineResponse[]>([]);
    const [medications, setMedications] = useState<TreatmentMedicationResponse[]>([]);
    const [loadingVaccines, setLoadingVaccines] = useState(false);
    const [loadingMedications, setLoadingMedications] = useState(false);

    // Options State
    const [vaccineOptions, setVaccineOptions] = useState<{ value: number; label: string }[]>([]);
    const [medicationOptions, setMedicationOptions] = useState<{ value: number; label: string }[]>([]);
    const [vaccineDoseMap, setVaccineDoseMap] = useState<Record<number, string>>({});

    const [vaccineRouteMap, setVaccineRouteMap] = useState<Record<number, string>>({});
    const [vaccineFullMap, setVaccineFullMap] = useState<Record<number, any>>({});
    const [medicationFullMap, setMedicationFullMap] = useState<Record<number, any>>({});

    // View Detail State
    const [viewDetailItem, setViewDetailItem] = useState<any>(null);
    const [viewDetailType, setViewDetailType] = useState<'vaccine' | 'medication' | null>(null);

    // Create State
    const [showAddVaccine, setShowAddVaccine] = useState(false);
    const [showAddMedication, setShowAddMedication] = useState(false);
    const [vaccineSearch, setVaccineSearch] = useState('');
    const [medicationSearch, setMedicationSearch] = useState('');
    const [newVaccines, setNewVaccines] = useState<number[]>([]);
    const [newMedications, setNewMedications] = useState<number[]>([]);
    const [savingVaccine, setSavingVaccine] = useState(false);
    const [savingMedication, setSavingMedication] = useState(false);
    const [newVaccineError, setNewVaccineError] = useState<string | null>(null);
    const [newMedicationError, setNewMedicationError] = useState<string | null>(null);

    // Detail Info State
    const [selectedVaccineInfo, setSelectedVaccineInfo] = useState<VaccineResponse | null>(null);
    const [selectedMedicationInfo, setSelectedMedicationInfo] = useState<MedicationResponse | null>(null);
    const [loadingVaccineInfo, setLoadingVaccineInfo] = useState(false);
    const [loadingMedicationInfo, setLoadingMedicationInfo] = useState(false);

    // Delete State
    const [confirmingDeleteId, setConfirmingDeleteId] = useState<number | null>(null);
    const [deleteLoadingId, setDeleteLoadingId] = useState<{ type: 'vaccine' | 'medication'; id: number } | null>(null);

    // List & Filter State
    const [vaccListSearch, setVaccListSearch] = useState('');
    const [medListSearch, setMedListSearch] = useState('');
    const [vaccSort] = useState<'recent' | 'oldest' | 'name_asc' | 'name_desc'>('recent');
    const [medSort] = useState<'recent' | 'oldest' | 'name_asc' | 'name_desc'>('recent');

    // Single Delete State
    const [pendingDeleteVaccine, setPendingDeleteVaccine] = useState<any | null>(null);
    const [pendingDeleteMedication, setPendingDeleteMedication] = useState<any | null>(null);

    // Pagination
    const [vaccPage] = useState(1);
    const [medPage] = useState(1);
    const [vaccPageSize] = useState(5);
    const [medPageSize] = useState(5);

    // Refs
    // const associationsLoadingRef = useRef<Promise<void> | null>(null);
    const associationsIdRef = useRef<number | null>(null);
    const optionsLoadedRef = useRef(false);
    const optionsLoadingRef = useRef<Promise<void> | null>(null);

    // Maps
    const vaccineLabelById = useMemo(() => {
        const map = new Map<number, string>();
        (vaccineOptions || []).forEach((o) => map.set(Number(o.value), o.label));
        return map;
    }, [vaccineOptions]);

    const medicationLabelById = useMemo(() => {
        const map = new Map<number, string>();
        (medicationOptions || []).forEach((o) => map.set(Number(o.value), o.label));
        return map;
    }, [medicationOptions]);

    // Load Options
    const loadOptions = useCallback(async () => {
        if (optionsLoadedRef.current) return;
        if (optionsLoadingRef.current) return optionsLoadingRef.current;

        const req = (async () => {
            try {
                const [vaccList, medList] = await Promise.all([
                    (vaccinesService as any).getAll?.({ limit: 200 }).catch(async () => (vaccinesService as any).getVaccines?.({ limit: 200 })),
                    (medicationsService as any).getAll?.({ limit: 200 }).catch(async () => (medicationsService as any).getMedications?.({ limit: 200 })),
                ]);

                const vaccData = Array.isArray(vaccList) ? vaccList : (vaccList as any)?.data || [];
                const medData = Array.isArray(medList) ? medList : (medList as any)?.data || [];

                setVaccineOptions((vaccData || []).map((v: any) => ({ value: v.id, label: v.name || `Vacuna ${v.id}` })));
                setMedicationOptions((medData || []).map((m: any) => ({ value: m.id, label: m.name || `Medicamento ${m.id}` })));

                const doseEntries: [number, string][] = (vaccData || []).map((v: any) => {
                    const dose = (v as any).dosis ?? (v as any).dose ?? '';
                    return [Number(v.id), typeof dose === 'string' && dose.trim() ? String(dose) : '1 dosis'];
                }).filter(([id]: [number, string]) => !!id);
                const doseMap: Record<number, string> = {};
                doseEntries.forEach(([id, dose]: [number, string]) => { doseMap[id] = dose; });
                setVaccineDoseMap(doseMap);

                const routeEntries: [number, string][] = (vaccData || []).map((v: any) => [Number(v.id), (v as any).route_administration_name || '']).filter(([id, name]: [number, string]) => !!id && !!String(name).trim());
                const routeMap: Record<number, string> = {};
                routeEntries.forEach(([id, name]: [number, string]) => { routeMap[id] = String(name); });
                setVaccineRouteMap(routeMap);

                const vaccMap: Record<number, any> = {};
                (vaccData || []).forEach((v: any) => { vaccMap[v.id] = v; });
                setVaccineFullMap(vaccMap);

                const medMap: Record<number, any> = {};
                (medData || []).forEach((m: any) => { medMap[m.id] = m; });
                setMedicationFullMap(medMap);

                optionsLoadedRef.current = true;
            } catch (e) {
                console.error('Failed to load options', e);
            }
        })();

        optionsLoadingRef.current = req;
        try {
            await req;
        } finally {
            if (optionsLoadingRef.current === req) {
                optionsLoadingRef.current = null;
            }
        }
    }, []);

    // Fetch Associations
    const refreshAssociations = useCallback(async (treatmentId: number, bypassCache: boolean = false, target: 'all' | 'vaccines' | 'medications' = 'all', silent: boolean = false) => {
        if (!treatmentId) return;

        if (!silent) {
            if (target === 'all' || target === 'vaccines') setLoadingVaccines(true);
            if (target === 'all' || target === 'medications') setLoadingMedications(true);
        }

        associationsIdRef.current = treatmentId;

        // Helper recursivo para garantizar la carga completa de datos
        const fetchAllItems = async (service: any, method: string, queryParams: any) => {
            let allData: any[] = [];
            let page = 1;
            const ITEMS_PER_PAGE = 50;

            while (page <= 10) { // Límite de seguridad
                const p = { ...queryParams, page, limit: ITEMS_PER_PAGE };
                try {
                    const res = await service[method](p);
                    const list = res.data || (Array.isArray(res) ? res : []);

                    if (!list || list.length === 0) break;

                    const newItems = list.filter((item: any) => !allData.some((existing) => existing.id === item.id));
                    if (newItems.length === 0) break;

                    allData = [...allData, ...newItems];
                    page++;
                } catch (e) {
                    console.error(`Error fetching page ${page}`, e);
                    break;
                }
            }
            return allData;
        };

        const params: any = {
            treatment_id: treatmentId,
            treatmentId: treatmentId,
            sort_by: 'id',
            sort_order: 'desc',
            _t: Date.now()
        };

        if (bypassCache) {
            params.cache_bust = Date.now();
        }

        const tIdStr = String(treatmentId);
        const isNotDeleted = (item: any) => !item.deleted_at && !item.deletedAt;
        const getGhosts = (): number[] => {
            try {
                const store = localStorage.getItem('ghost_items_v1');
                const map = store ? JSON.parse(store) : {};
                return map[Number(treatmentId)] || [];
            } catch { return []; }
        };
        const ghostIds = new Set(getGhosts());

        try {
            const promises: Promise<void>[] = [];

            if (target === 'all' || target === 'vaccines') {
                promises.push((async () => {
                    try {
                        const vData = await fetchAllItems(treatmentVaccinesService, 'getTreatmentVaccines', params);
                        const filteredVaccines = vData.filter((v: any) => {
                            const vTId = v.treatment_id ?? v.treatmentId;
                            return String(vTId) === tIdStr && isNotDeleted(v) && !ghostIds.has(v.id);
                        });
                        setVaccines(filteredVaccines);
                    } catch (err) {
                        console.error('Error fetching vaccines', err);
                    } finally {
                        if (!silent) setLoadingVaccines(false);
                    }
                })());
            }

            if (target === 'all' || target === 'medications') {
                promises.push((async () => {
                    try {
                        const mData = await fetchAllItems(treatmentMedicationService, 'getTreatmentMedications', params);
                        const filteredMedications = mData.filter((m: any) => {
                            const mTId = m.treatment_id ?? m.treatmentId;
                            return String(mTId) === tIdStr && isNotDeleted(m) && !ghostIds.has(m.id);
                        });
                        setMedications(filteredMedications);
                    } catch (err) {
                        console.error('Error fetching medications', err);
                    } finally {
                        if (!silent) setLoadingMedications(false);
                    }
                })());
            }

            await Promise.all(promises);

        } catch (err) {
            console.error('[TreatmentSuppliesModal] Error refreshing associations:', err);
            if (!silent) {
                setLoadingVaccines(false);
                setLoadingMedications(false);
            }
        }
    }, []);

    // Initial Load
    useEffect(() => {
        if (isOpen && treatment?.id) {
            loadOptions();
            // SIEMPRE forzar recarga fresca al abrir para evitar "items fantasmas" de caché vieja
            refreshAssociations(treatment.id, true, 'all');
        }
    }, [isOpen, treatment, loadOptions, refreshAssociations]);

    // Reset State on Close
    useEffect(() => {
        if (!isOpen) {
            setVaccines([]);
            setMedications([]);
            setShowAddVaccine(false);
            setShowAddMedication(false);
            setNewVaccines([]);
            setNewMedications([]);
            setSelectedVaccineInfo(null);
            setSelectedMedicationInfo(null);
        }
    }, [isOpen]);

    // --- Handlers ---

    const handleCreateVaccine = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!treatment) return;
        setNewVaccineError(null);
        if (!Array.isArray(newVaccines) || newVaccines.length === 0) {
            setNewVaccineError('Selecciona una vacuna.');
            return;
        }
        const selectedIds = newVaccines.filter((id) => !!id);
        const existingIds = (vaccines || []).map((v: any) => Number(v.vaccine_id)).filter(Boolean);
        const toCreateIds = selectedIds.filter((id) => !existingIds.includes(Number(id)));

        if (toCreateIds.length === 0) {
            setNewVaccineError('Todas las vacunas seleccionadas ya están asociadas.');
            return;
        }

        setSavingVaccine(true);
        try {
            const payload = toCreateIds.map((id) => ({
                treatment_id: treatment.id,
                treatmentId: treatment.id, // Redundancia
                vaccine_id: id,
                dose: vaccineDoseMap[id] ?? '1 dosis',
            }));
            if (payload.length === 1) {
                const res = await treatmentVaccinesService.createTreatmentVaccine(payload[0] as any);

            } else {
                const res = await (treatmentVaccinesService as any).createBulk(payload as any);

            }
            // INVALIDAR CACHÉ ANTES DE REFRESCAR
            await treatmentVaccinesService.clearCache();
            // Mayor retardo para asegurar consistencia DB y replicación
            setTimeout(() => {
                refreshAssociations(treatment.id, true, 'vaccines');
            }, 1200);

            setShowAddVaccine(false);
            setNewVaccines([]);
            setSelectedVaccineInfo(null);
            const names = toCreateIds.map((id) => vaccineLabelById.get(Number(id)) || `#${id}`);
            showToast(`Vacuna(s) asociadas: ${names.join(', ')}`, 'success');
        } catch (err: any) {
            console.error('Error al crear tratamiento-vacuna:', err);
            const apiMsg = err?.response?.data?.message || err?.response?.data?.error || err?.message;
            setNewVaccineError(apiMsg ? `No se pudo añadir la vacuna: ${typeof apiMsg === 'string' ? apiMsg : JSON.stringify(apiMsg)}` : 'No se pudo añadir la vacuna al tratamiento.');
        } finally {
            setSavingVaccine(false);
        }
    };

    const handleCreateMedication = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!treatment) return;
        setNewMedicationError(null);
        if (!Array.isArray(newMedications) || newMedications.length === 0) {
            setNewMedicationError('Selecciona un medicamento.');
            return;
        }
        const selectedIds = newMedications.filter((id) => !!id);
        const existingIds = (medications || []).map((m: any) => Number(m.medication_id)).filter(Boolean);
        const toCreateIds = selectedIds.filter((id) => !existingIds.includes(Number(id)));
        if (toCreateIds.length === 0) {
            setNewMedicationError('Todos los medicamentos seleccionados ya están asociados.');
            return;
        }
        setSavingMedication(true);
        try {
            const payload = toCreateIds.map((id) => ({
                treatment_id: treatment.id,
                treatmentId: treatment.id, // Redundancia
                medication_id: id,
            }));
            if (payload.length === 1) {
                const res = await treatmentMedicationService.createTreatmentMedication(payload[0] as any);

            } else {
                const res = await (treatmentMedicationService as any).createBulk(payload as any);

            }
            // INVALIDAR CACHÉ ANTES DE REFRESCAR
            await treatmentMedicationService.clearCache();
            // Mayor retardo para asegurar consistencia DB y replicación
            setTimeout(() => {
                refreshAssociations(treatment.id, true, 'medications');
            }, 1200);

            setShowAddMedication(false);
            setNewMedications([]);
            setSelectedMedicationInfo(null);
            const names = toCreateIds.map((id) => medicationLabelById.get(Number(id)) || `#${id}`);
            showToast(`Medicamento(s) asociados: ${names.join(', ')}`, 'success');
        } catch (err: any) {
            setNewMedicationError('No se pudo añadir el medicamento al tratamiento.');
        } finally {
            setSavingMedication(false);
        }
    };

    const openDeleteVaccine = async (v: any) => {
        const itemId = v.id;
        if (confirmingDeleteId === itemId) {
            setConfirmingDeleteId(null);
            await confirmDeleteVaccine(v);
        } else {
            setConfirmingDeleteId(itemId);
            showToast('Haz clic de nuevo para desvincular', 'warning');
            setTimeout(() => setConfirmingDeleteId(prev => prev === itemId ? null : prev), 3000);
        }
    };

    const confirmDeleteVaccine = async (v: any) => {
        if (!v || !treatment) return;
        const itemId = v.id;
        setDeleteLoadingId({ type: 'vaccine', id: itemId });

        // OPTIMISTIC UPDATE: Remover inmediatamente de la UI
        setVaccines(prev => prev.filter(v => v.id !== itemId));

        try {
            await (treatmentVaccinesService as any).deleteTreatmentVaccine(String(itemId));
            // INVALIDAR CACHÉ ANTES DE REFRESCAR
            await treatmentVaccinesService.clearCache();
            await refreshAssociations(treatment.id, true, 'vaccines', true);
            showToast('Vacuna desvinculada', 'success');
        } catch (e: any) {
            // Manejo de consistencia: Si da 404, es que ya no existe.
            if (e?.response?.status === 404 || e?.status === 404) {
                console.warn('Item fantasma detectado (404), limpiando caché...');
                await treatmentVaccinesService.clearCache();
                await refreshAssociations(treatment.id, true, 'vaccines', true);
            } else {
                // ROLLBACK: Restaurar item si falla
                await refreshAssociations(treatment.id, true, 'vaccines');
                showToast('Error al desvincular vacuna', 'error');
            }
        } finally {
            setDeleteLoadingId(null);
            setPendingDeleteVaccine(null);
        }
    };

    const openDeleteMedication = async (m: any) => {
        const itemId = m.id;
        if (confirmingDeleteId === itemId) {
            setConfirmingDeleteId(null);
            await confirmDeleteMedication(m);
        } else {
            setConfirmingDeleteId(itemId);
            showToast('Haz clic de nuevo para desvincular', 'warning');
            setTimeout(() => setConfirmingDeleteId(prev => prev === itemId ? null : prev), 3000);
        }
    };

    const confirmDeleteMedication = async (m: any) => {
        if (!m || !treatment) return;
        const itemId = m.id;
        setDeleteLoadingId({ type: 'medication', id: itemId });

        // OPTIMISTIC UPDATE: Remover inmediatamente de la UI
        setMedications(prev => prev.filter(m => m.id !== itemId));

        try {
            await (treatmentMedicationService as any).deleteTreatmentMedication(String(itemId));
            // INVALIDAR CACHÉ ANTES DE REFRESCAR
            await treatmentMedicationService.clearCache();
            await refreshAssociations(treatment.id, true, 'medications', true);
            showToast('Medicamento desvinculado', 'success');
        } catch (e: any) {
            // Manejo de consistencia: Si da 404, es que ya no existe.
            if (e?.response?.status === 404 || e?.status === 404) {
                console.warn('Item fantasma detectado (404), limpiando caché...');
                await treatmentMedicationService.clearCache();
                await refreshAssociations(treatment.id, true, 'medications', true);
            } else {
                // ROLLBACK: Restaurar item si falla
                await refreshAssociations(treatment.id, true, 'medications');
                showToast('Error al desvincular medicamento', 'error');
            }
        } finally {
            setDeleteLoadingId(null);
            setPendingDeleteMedication(null);
        }
    };

    // --- Filtering & Sorting Lists ---
    const sortedVaccines = useMemo(() => {
        let arr = [...(vaccines || [])];
        const q = vaccListSearch.toLowerCase().trim();
        if (q) {
            arr = arr.filter((v: any) => {
                const name = String(v.vaccine_name ?? (v.vaccine_id ? (vaccineLabelById.get(Number(v.vaccine_id)) || '') : ''));
                const route = v.vaccine_id ? vaccineRouteMap[Number(v.vaccine_id)] : '';
                const fields = [name, v.dose, v.notes, v.vaccination_status, route]
                    .map((x) => String(x || '').toLowerCase());
                return fields.some((s) => s.includes(q));
            });
        }
        arr.sort((a: any, b: any) => {
            if (vaccSort === 'name_asc' || vaccSort === 'name_desc') {
                const an = String(a.vaccine_name ?? (a.vaccine_id ? (vaccineLabelById.get(Number(a.vaccine_id)) || '') : '')).toLowerCase();
                const bn = String(b.vaccine_name ?? (b.vaccine_id ? (vaccineLabelById.get(Number(b.vaccine_id)) || '') : '')).toLowerCase();
                const cmp = an.localeCompare(bn);
                return vaccSort === 'name_asc' ? cmp : -cmp;
            }
            const ad = a.updated_at || a.created_at || '';
            const bd = b.updated_at || b.created_at || '';
            if (ad && bd) {
                const diff = new Date(ad as string).getTime() - new Date(bd as string).getTime();
                return vaccSort === 'oldest' ? diff : -diff;
            }
            return 0;
        });
        return arr;
    }, [vaccines, vaccListSearch, vaccSort, vaccineLabelById, vaccineRouteMap]);

    const sortedMedications = useMemo(() => {
        let arr = [...(medications || [])];
        const q = medListSearch.toLowerCase().trim();
        if (q) {
            arr = arr.filter((m: any) => {
                const name = String(m.medication_name ?? (m.medication_id ? (medicationLabelById.get(Number(m.medication_id)) || '') : ''));
                const fields = [name, m.dosage ?? m.dose, m.frequency, m.duration_days, m.administration_route, m.notes]
                    .map((x) => String(x || '').toLowerCase());
                return fields.some((s) => s.includes(q));
            });
        }
        arr.sort((a: any, b: any) => {
            if (medSort === 'name_asc' || medSort === 'name_desc') {
                const an = String(a.medication_name ?? (a.medication_id ? (medicationLabelById.get(Number(a.medication_id)) || '') : '')).toLowerCase();
                const bn = String(b.medication_name ?? (b.medication_id ? (medicationLabelById.get(Number(b.medication_id)) || '') : '')).toLowerCase();
                const cmp = an.localeCompare(bn);
                return medSort === 'name_asc' ? cmp : -cmp;
            }
            const ad = a.updated_at || a.created_at || '';
            const bd = b.updated_at || b.created_at || '';
            if (ad && bd) {
                const diff = new Date(ad as string).getTime() - new Date(bd as string).getTime();
                return medSort === 'oldest' ? diff : -diff;
            }
            return 0;
        });
        return arr;
    }, [medications, medListSearch, medSort, medicationLabelById]);


    // Fetch Full Detail - Use cached data first, then fetch if needed
    const handleViewItem = (type: 'vaccine' | 'medication', id: number) => {
        if (!id) {
            console.warn('handleViewItem: No ID provided');
            return;
        }


        let itemData: any = null;
        if (type === 'vaccine') {
            itemData = vaccineFullMap[id];
        } else {
            itemData = medicationFullMap[id];
        }

        if (itemData) {
            setViewDetailType(type);
            setViewDetailItem(itemData);
        } else {
            // Fallback: create a minimal object with the ID so user sees something
            setViewDetailType(type);
            setViewDetailItem({
                id,
                name: type === 'vaccine' ? `Vacuna #${id}` : `Medicamento #${id}`,
                _notFound: true
            });
            showToast('Los datos completos no están disponibles. Mostrando información básica.', 'warning');
        }
    };

    // Pagination Logic
    const paginatedVaccines = useMemo(() => {
        const start = (vaccPage - 1) * vaccPageSize;
        return sortedVaccines.slice(start, start + vaccPageSize);
    }, [sortedVaccines, vaccPage, vaccPageSize]);

    const paginatedMedications = useMemo(() => {
        const start = (medPage - 1) * medPageSize;
        return sortedMedications.slice(start, start + medPageSize);
    }, [sortedMedications, medPage, medPageSize]);

    return (
        <>
            <GenericModal
                isOpen={isOpen}
                onOpenChange={(open) => !open && onClose()}
                title={
                    <div className="flex items-center justify-between w-full pr-8">
                        <div className="flex items-center gap-2">
                            <span>Detalle del Tratamiento {treatment?.id ? `#${treatment.id}` : ''}</span>
                            <Button
                                variant="ghost"
                                size="sm"
                                className="h-7 w-7 p-0 hover:bg-primary/20 hover:text-primary transition-colors"
                                onClick={(e) => {
                                    e.stopPropagation();
                                    if (treatment?.id) refreshAssociations(treatment.id, true, 'all');
                                }}
                                title="Refrescar datos (bypass cache)"
                            >
                                <RefreshCw className={cn("h-4 w-4", (loadingVaccines || loadingMedications) && "animate-spin")} />
                            </Button>
                        </div>
                    </div>
                }
                size="2xl"
                enableBackdropBlur
                description="Vacunas y medicamentos asociados al tratamiento seleccionado"
                className={`bg-card text-card-foreground border border-border/80 shadow-2xl ${className}`}
                zIndex={zIndex || 1000}
            >
                <div className="space-y-4">
                    {/* Actions Header */}
                    {/* Treatment Details and Actions Header */}
                    {treatment && (
                        <div className="grid grid-cols-1 gap-4 mb-4">
                            <DetailSection
                                title="Información del Tratamiento"
                                accent="purple"
                                icon={<ClipboardList className="w-4 h-4" />}
                                fullWidth
                            >
                                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 w-full">
                                    <InfoField label="Diagnóstico" value={treatment.diagnosis || '-'} fullWidth />
                                    <InfoField label="Fecha" value={treatment.treatment_date ? new Date(treatment.treatment_date).toLocaleDateString('es-ES') : '-'} />
                                    <InfoField
                                        label="Estado"
                                        value={treatment.status || 'Iniciado'}
                                        badge
                                        badgeVariant={
                                            treatment.status === 'Completado' ? 'success' :
                                                treatment.status === 'Suspendido' ? 'destructive' :
                                                    treatment.status === 'En progreso' ? 'secondary' : 'default'
                                        }
                                    />
                                </div>

                                {((treatment as any).description || (treatment as any).notes) && (
                                    <div className="pt-2 border-t border-border/40 mt-2">
                                        <InfoField label="Descripción / Notas" value={(treatment as any).description || (treatment as any).notes} fullWidth />
                                    </div>
                                )}
                            </DetailSection>
                        </div>
                    )}

                    <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-3 bg-secondary/10 p-3 rounded-lg border border-secondary/20">
                        <div className="text-sm font-medium flex items-center gap-2">
                            <Syringe className="w-4 h-4 text-primary" />
                            <span>Gestión de Insumos</span>
                        </div>
                        <div className="flex items-center gap-2">
                            <Button
                                variant="primary"
                                size="sm"
                                onClick={() => { setShowAddVaccine((s) => !s); setShowAddMedication(false); }}
                                disabled={!treatment}
                            >
                                Añadir vacuna
                            </Button>
                            <Button
                                variant="primary"
                                size="sm"
                                onClick={() => { setShowAddMedication((s) => !s); setShowAddVaccine(false); }}
                                disabled={!treatment}
                            >
                                Añadir medicamento
                            </Button>
                        </div>
                    </div>

                    {/* Forms */}
                    {showAddVaccine && treatment && (
                        <form onSubmit={handleCreateVaccine} className="rounded-lg border bg-background/80 p-3 space-y-3">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                                <div>
                                    <label className="block text-xs text-muted-foreground mb-1">Vacuna</label>
                                    <input
                                        type="text"
                                        className="mb-2 w-full h-8 rounded-md border bg-background px-2 text-sm"
                                        placeholder="Buscar vacuna…"
                                        value={vaccineSearch}
                                        onChange={(e) => setVaccineSearch(e.target.value)}
                                    />
                                    <select
                                        aria-label="Seleccionar vacunas"
                                        className="w-full h-9 rounded-md border bg-background px-2 text-sm"
                                        multiple
                                        value={newVaccines.map(String)}
                                        onChange={(e) => setNewVaccines(Array.from(e.target.selectedOptions).map((o) => Number(o.value)))}
                                        required
                                    >
                                        {vaccineOptions
                                            .filter((opt) => opt.label.toLowerCase().includes(vaccineSearch.toLowerCase()))
                                            .map((opt) => (
                                                <option key={opt.value} value={opt.value}>{opt.label}</option>
                                            ))}
                                    </select>
                                </div>
                                <div className="flex items-end gap-2">
                                    <Button type="submit" size="sm" disabled={savingVaccine}>Guardar</Button>
                                    <Button type="button" variant="ghost" size="sm" onClick={() => setShowAddVaccine(false)}>Cancelar</Button>
                                </div>
                            </div>
                            {newVaccineError && <div className="text-xs text-destructive">{newVaccineError}</div>}
                        </form>
                    )}

                    {showAddMedication && treatment && (
                        <form onSubmit={handleCreateMedication} className="rounded-lg border bg-background/80 p-3 space-y-3">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                                <div>
                                    <label className="block text-xs text-muted-foreground mb-1">Medicamento</label>
                                    <input
                                        type="text"
                                        className="mb-2 w-full h-8 rounded-md border bg-background px-2 text-sm"
                                        placeholder="Buscar medicamento…"
                                        value={medicationSearch}
                                        onChange={(e) => setMedicationSearch(e.target.value)}
                                    />
                                    <select
                                        aria-label="Seleccionar medicamentos"
                                        className="w-full h-9 rounded-md border bg-background px-2 text-sm"
                                        multiple
                                        value={newMedications.map(String)}
                                        onChange={(e) => setNewMedications(Array.from(e.target.selectedOptions).map((o) => Number(o.value)))}
                                        required
                                    >
                                        {medicationOptions
                                            .filter((opt) => opt.label.toLowerCase().includes(medicationSearch.toLowerCase()))
                                            .map((opt) => (
                                                <option key={opt.value} value={opt.value}>{opt.label}</option>
                                            ))}
                                    </select>
                                </div>
                                <div className="flex items-end gap-2">
                                    <Button type="submit" size="sm" disabled={savingMedication}>Guardar</Button>
                                    <Button type="button" variant="ghost" size="sm" onClick={() => setShowAddMedication(false)}>Cancelar</Button>
                                </div>
                            </div>
                            {newMedicationError && <div className="text-xs text-destructive">{newMedicationError}</div>}
                        </form>
                    )}

                    <TreatmentSuppliesCards
                        vaccines={paginatedVaccines as any}
                        medications={paginatedMedications as any}
                        vaccineFullMap={vaccineFullMap}
                        medicationFullMap={medicationFullMap}
                        vaccineRouteMap={vaccineRouteMap}
                        onViewVaccine={(id) => handleViewItem('vaccine', id)}
                        onViewMedication={(id) => handleViewItem('medication', id)}
                        onDeleteVaccine={openDeleteVaccine}
                        onDeleteMedication={openDeleteMedication}
                        confirmingDeleteId={confirmingDeleteId}
                        deleteLoadingId={deleteLoadingId}
                        loadingVaccines={loadingVaccines}
                        loadingMedications={loadingMedications}
                    />

                    <div className="flex justify-end pt-4 border-t">
                        <Button variant="outline" onClick={(e) => { e.stopPropagation(); onClose(); }}>Cerrar</Button>
                    </div>
                </div>
            </GenericModal>


            {/* Item Detail Modal - Rendered with VERY high z-index for proper stacking */}
            {viewDetailItem && viewDetailType && (
                <ItemDetailModal
                    type={viewDetailType}
                    item={viewDetailItem}
                    options={{}} // Los datos ya vienen enriquecidos en viewDetailItem
                    onClose={() => {
                        setViewDetailItem(null);
                        setViewDetailType(null);
                    }}
                    onEdit={() => {
                        // Navigate to the appropriate admin page for editing
                        const itemId = viewDetailItem?.id;
                        if (!itemId) return;

                        // Determine the admin route based on type
                        const route = viewDetailType === 'vaccine'
                            ? `/admin/vaccines?edit=${itemId}`
                            : `/admin/medications?edit=${itemId}`;

                        // Close modal and navigate
                        setViewDetailItem(null);
                        setViewDetailType(null);
                        window.location.href = route;
                    }}
                    zIndex={(zIndex || 2000) + 500}
                />
            )}
        </>
    );
};

import React, { useEffect, useState, useMemo, useCallback, useRef } from 'react';
import { cn } from '@/shared/ui/cn';
import { RefreshCw } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { TreatmentResponse, TreatmentVaccineResponse, TreatmentMedicationResponse } from '@/shared/api/generated/swaggerTypes';
import { vaccinesService } from '@/entities/vaccine/api/vaccines.service';
import { medicationsService } from '@/entities/medication/api/medications.service';
import { treatmentVaccinesService } from '@/entities/treatment-vaccine/api/treatmentVaccines.service';
import { treatmentMedicationService } from '@/entities/treatment-medication/api/treatmentMedication.service';
import { TreatmentSuppliesCards } from './TreatmentSuppliesCards';
import { useToast } from '@/app/providers/ToastContext';
import { ItemDetailModal } from '../animals/ItemDetailModal';

interface TreatmentSuppliesPanelProps {
    treatment: TreatmentResponse | null;
    className?: string;
}

export const TreatmentSuppliesPanel: React.FC<TreatmentSuppliesPanelProps> = ({
    treatment,
    className
}) => {
    const { showToast } = useToast();

    // Data State
    const [vaccines, setVaccines] = useState<TreatmentVaccineResponse[]>([]);
    const [medications, setMedications] = useState<TreatmentMedicationResponse[]>([]);
    const [loadingVaccines, setLoadingVaccines] = useState(false);
    const [loadingMedications, setLoadingMedications] = useState(false);

    // Options State
    const [vaccineOptions, setVaccineOptions] = useState<{ value: number; label: string }[]>([]);
    const [medicationOptions, setMedicationOptions] = useState<{ value: number; label: string }[]>([]);
    const [vaccineDoseMap, setVaccineDoseMap] = useState<Record<number, string>>({});

    const [vaccineRouteMap, setVaccineRouteMap] = useState<Record<number, string>>({});
    const [vaccineFullMap, setVaccineFullMap] = useState<Record<number, any>>({});
    const [medicationFullMap, setMedicationFullMap] = useState<Record<number, any>>({});

    // View Detail State
    const [viewDetailItem, setViewDetailItem] = useState<any>(null);
    const [viewDetailType, setViewDetailType] = useState<'vaccine' | 'medication' | null>(null);

    // Create State
    const [showAddVaccine, setShowAddVaccine] = useState(false);
    const [showAddMedication, setShowAddMedication] = useState(false);
    const [vaccineSearch, setVaccineSearch] = useState('');
    const [medicationSearch, setMedicationSearch] = useState('');
    const [newVaccines, setNewVaccines] = useState<number[]>([]);
    const [newMedications, setNewMedications] = useState<number[]>([]);
    const [savingVaccine, setSavingVaccine] = useState(false);
    const [savingMedication, setSavingMedication] = useState(false);
    const [newVaccineError, setNewVaccineError] = useState<string | null>(null);
    const [newMedicationError, setNewMedicationError] = useState<string | null>(null);

    // Filter State (Simplified for panel)
    const [confirmingDeleteId, setConfirmingDeleteId] = useState<number | null>(null);
    const [deleteLoadingId, setDeleteLoadingId] = useState<{ type: 'vaccine' | 'medication'; id: number } | null>(null);

    // Refs
    // const associationsLoadingRef = useRef<Promise<void> | null>(null); // Removed to avoid stale promise issues with granular refresh
    const associationsIdRef = useRef<number | null>(null);
    const optionsLoadedRef = useRef(false);
    const optionsLoadingRef = useRef<Promise<void> | null>(null);

    // Maps
    const vaccineLabelById = useMemo(() => {
        const map = new Map<number, string>();
        (vaccineOptions || []).forEach((o) => map.set(Number(o.value), o.label));
        return map;
    }, [vaccineOptions]);

    const medicationLabelById = useMemo(() => {
        const map = new Map<number, string>();
        (medicationOptions || []).forEach((o) => map.set(Number(o.value), o.label));
        return map;
    }, [medicationOptions]);

    // Load Options
    const loadOptions = useCallback(async () => {
        if (optionsLoadedRef.current) return;
        if (optionsLoadingRef.current) return optionsLoadingRef.current;

        const req = (async () => {
            try {
                const [vaccList, medList] = await Promise.all([
                    (vaccinesService as any).getAll?.({ limit: 200 }).catch(async () => (vaccinesService as any).getVaccines?.({ limit: 200 })),
                    (medicationsService as any).getAll?.({ limit: 200 }).catch(async () => (medicationsService as any).getMedications?.({ limit: 200 })),
                ]);

                const vaccData = Array.isArray(vaccList) ? vaccList : (vaccList as any)?.data || [];
                const medData = Array.isArray(medList) ? medList : (medList as any)?.data || [];

                setVaccineOptions((vaccData || []).map((v: any) => ({ value: v.id, label: v.name || `Vacuna ${v.id}` })));
                setMedicationOptions((medData || []).map((m: any) => ({ value: m.id, label: m.name || `Medicamento ${m.id}` })));

                const doseEntries: [number, string][] = (vaccData || []).map((v: any) => {
                    const dose = (v as any).dosis ?? (v as any).dose ?? '';
                    return [Number(v.id), typeof dose === 'string' && dose.trim() ? String(dose) : '1 dosis'];
                }).filter(([id]: [number, string]) => !!id);
                const doseMap: Record<number, string> = {};
                doseEntries.forEach(([id, dose]: [number, string]) => { doseMap[id] = dose; });
                setVaccineDoseMap(doseMap);

                const routeEntries: [number, string][] = (vaccData || []).map((v: any) => [Number(v.id), (v as any).route_administration_name || '']).filter(([id, name]: [number, string]) => !!id && !!String(name).trim());
                const routeMap: Record<number, string> = {};
                routeEntries.forEach(([id, name]: [number, string]) => { routeMap[id] = String(name); });
                setVaccineRouteMap(routeMap);

                const vaccMap: Record<number, any> = {};
                (vaccData || []).forEach((v: any) => { vaccMap[v.id] = v; });
                setVaccineFullMap(vaccMap);

                const medMap: Record<number, any> = {};
                (medData || []).forEach((m: any) => { medMap[m.id] = m; });
                setMedicationFullMap(medMap);

                optionsLoadedRef.current = true;
            } catch (e) {
                console.error('Failed to load options', e);
            }
        })();

        optionsLoadingRef.current = req;
        try {
            await req;
        } finally {
            if (optionsLoadingRef.current === req) {
                optionsLoadingRef.current = null;
            }
        }
    }, []);

    // Fetch Associations
    const refreshAssociations = useCallback(async (treatmentId: number, bypassCache: boolean = false, target: 'all' | 'vaccines' | 'medications' = 'all', silent: boolean = false) => {
        if (!treatmentId) return;

        if (!silent) {
            if (target === 'all' || target === 'vaccines') setLoadingVaccines(true);
            if (target === 'all' || target === 'medications') setLoadingMedications(true);
        }

        associationsIdRef.current = treatmentId;

        // Helper recursivo para garantizar la carga completa de datos
        const fetchAllItems = async (service: any, method: string, queryParams: any) => {
            let allData: any[] = [];
            let page = 1;
            const ITEMS_PER_PAGE = 50;

            while (page <= 10) { // Límite de seguridad
                const p = { ...queryParams, page, limit: ITEMS_PER_PAGE };
                try {
                    const res = await service[method](p);
                    const list = res.data || (Array.isArray(res) ? res : []);

                    if (!list || list.length === 0) break;

                    const newItems = list.filter((item: any) => !allData.some((existing) => existing.id === item.id));
                    if (newItems.length === 0) break;

                    allData = [...allData, ...newItems];
                    page++;
                } catch (e) {
                    console.error(`Error fetching page ${page}`, e);
                    break;
                }
            }
            return allData;
        };

        const params: any = {
            treatment_id: treatmentId,
            treatmentId: treatmentId,
            sort_by: 'id',
            sort_order: 'desc',
            _t: Date.now()
        };

        if (bypassCache) {
            params.cache_bust = Date.now();
        }

        const tIdStr = String(treatmentId);
        const isNotDeleted = (item: any) => !item.deleted_at && !item.deletedAt;

        try {
            const promises: Promise<void>[] = [];

            if (target === 'all' || target === 'vaccines') {
                promises.push((async () => {
                    try {
                        const vData = await fetchAllItems(treatmentVaccinesService, 'getTreatmentVaccines', params);
                        const filteredVaccines = vData.filter((v: any) => {
                            const vTId = v.treatment_id ?? v.treatmentId;
                            return String(vTId) === tIdStr && isNotDeleted(v);
                        });
                        setVaccines(filteredVaccines);
                    } catch (err) {
                        console.error('Error fetching vaccines', err);
                    } finally {
                        if (!silent) setLoadingVaccines(false);
                    }
                })());
            }

            if (target === 'all' || target === 'medications') {
                promises.push((async () => {
                    try {
                        const mData = await fetchAllItems(treatmentMedicationService, 'getTreatmentMedications', params);
                        const filteredMedications = mData.filter((m: any) => {
                            const mTId = m.treatment_id ?? m.treatmentId;
                            return String(mTId) === tIdStr && isNotDeleted(m);
                        });
                        setMedications(filteredMedications);
                    } catch (err) {
                        console.error('Error fetching medications', err);
                    } finally {
                        if (!silent) setLoadingMedications(false);
                    }
                })());
            }

            await Promise.all(promises);

        } catch (err) {
            console.error('[TreatmentSuppliesPanel] Error refreshing associations:', err);
            if (!silent) {
                setLoadingVaccines(false);
                setLoadingMedications(false);
            }
        }
    }, []);

    // Initial Load
    useEffect(() => {
        if (treatment?.id) {
            loadOptions();
            refreshAssociations(treatment.id, true, 'all');
        }
    }, [treatment, loadOptions, refreshAssociations]);

    // Handlers
    const handleCreateVaccine = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!treatment) return;
        setNewVaccineError(null);
        if (!Array.isArray(newVaccines) || newVaccines.length === 0) {
            setNewVaccineError('Selecciona una vacuna.');
            return;
        }

        const existingIds = (vaccines || []).map((v: any) => Number(v.vaccine_id)).filter(Boolean);
        const toCreateIds = newVaccines.filter((id) => !!id && !existingIds.includes(Number(id)));

        if (toCreateIds.length === 0) {
            setNewVaccineError('Todas las vacunas seleccionadas ya están asociadas.');
            return;
        }

        setSavingVaccine(true);
        try {
            const payload = toCreateIds.map((id) => ({
                treatment_id: treatment.id,
                treatmentId: treatment.id,
                vaccine_id: id,
                dose: vaccineDoseMap[id] ?? '1 dosis',
            }));
            if (payload.length === 1) {
                await treatmentVaccinesService.createTreatmentVaccine(payload[0] as any);
            } else {
                await (treatmentVaccinesService as any).createBulk(payload as any);
            }

            await treatmentVaccinesService.clearCache();

            setTimeout(() => {
                refreshAssociations(treatment.id, true, 'vaccines');
            }, 1200);

            setShowAddVaccine(false);
            setNewVaccines([]);
            const names = toCreateIds.map((id) => vaccineLabelById.get(Number(id)) || `#${id}`);
            showToast(`Vacuna(s) asociadas: ${names.join(', ')}`, 'success');
        } catch (err: any) {
            console.error('Error al crear tratamiento-vacuna:', err);
            const apiMsg = err?.response?.data?.message || err?.response?.data?.error || err?.message;
            setNewVaccineError(apiMsg ? `No se pudo añadir la vacuna: ${typeof apiMsg === 'string' ? apiMsg : JSON.stringify(apiMsg)}` : 'No se pudo añadir la vacuna al tratamiento.');
        } finally {
            setSavingVaccine(false);
        }
    };

    const handleCreateMedication = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!treatment) return;
        setNewMedicationError(null);
        if (!Array.isArray(newMedications) || newMedications.length === 0) {
            setNewMedicationError('Selecciona un medicamento.');
            return;
        }

        const existingIds = (medications || []).map((m: any) => Number(m.medication_id)).filter(Boolean);
        const toCreateIds = newMedications.filter((id) => !!id && !existingIds.includes(Number(id)));

        if (toCreateIds.length === 0) {
            setNewMedicationError('Todos los medicamentos seleccionados ya están asociados.');
            return;
        }

        setSavingMedication(true);
        try {
            const payload = toCreateIds.map((id) => ({
                treatment_id: treatment.id,
                treatmentId: treatment.id,
                medication_id: id,
            }));
            if (payload.length === 1) {
                await treatmentMedicationService.createTreatmentMedication(payload[0] as any);
            } else {
                await (treatmentMedicationService as any).createBulk(payload as any);
            }

            await treatmentMedicationService.clearCache();

            setTimeout(() => {
                refreshAssociations(treatment.id, true, 'medications');
            }, 1200);

            setShowAddMedication(false);
            setNewMedications([]);
            const names = toCreateIds.map((id) => medicationLabelById.get(Number(id)) || `#${id}`);
            showToast(`Medicamento(s) asociados: ${names.join(', ')}`, 'success');
        } catch (err: any) {
            setNewMedicationError('No se pudo añadir el medicamento al tratamiento.');
        } finally {
            setSavingMedication(false);
        }
    };

    const openDeleteVaccine = async (v: any) => {
        const itemId = v.id;
        if (confirmingDeleteId === itemId) {
            setConfirmingDeleteId(null);
            await confirmDeleteVaccine(v);
        } else {
            setConfirmingDeleteId(itemId);
            showToast('Haz clic de nuevo para desvincular', 'warning');
            setTimeout(() => setConfirmingDeleteId(prev => prev === itemId ? null : prev), 3000);
        }
    };

    const confirmDeleteVaccine = async (v: any) => {
        if (!v || !treatment) return;
        const itemId = v.id;
        setDeleteLoadingId({ type: 'vaccine', id: itemId });
        setVaccines(prev => prev.filter(v => v.id !== itemId));

        try {
            await (treatmentVaccinesService as any).deleteTreatmentVaccine(String(itemId));
            await treatmentVaccinesService.clearCache();
            await refreshAssociations(treatment.id, true, 'vaccines', true);
            showToast('Vacuna desvinculada', 'success');
        } catch (e: any) {
            if (e?.response?.status === 404 || e?.status === 404) {
                await treatmentVaccinesService.clearCache();
                await refreshAssociations(treatment.id, true, 'vaccines', true);
            } else {
                await refreshAssociations(treatment.id, true, 'vaccines');
                showToast('Error al desvincular vacuna', 'error');
            }
        } finally {
            setDeleteLoadingId(null);
        }
    };

    const openDeleteMedication = async (m: any) => {
        const itemId = m.id;
        if (confirmingDeleteId === itemId) {
            setConfirmingDeleteId(null);
            await confirmDeleteMedication(m);
        } else {
            setConfirmingDeleteId(itemId);
            showToast('Haz clic de nuevo para desvincular', 'warning');
            setTimeout(() => setConfirmingDeleteId(prev => prev === itemId ? null : prev), 3000);
        }
    };

    const confirmDeleteMedication = async (m: any) => {
        if (!m || !treatment) return;
        const itemId = m.id;
        setDeleteLoadingId({ type: 'medication', id: itemId });
        setMedications(prev => prev.filter(m => m.id !== itemId));

        try {
            await (treatmentMedicationService as any).deleteTreatmentMedication(String(itemId));
            await treatmentMedicationService.clearCache();
            await refreshAssociations(treatment.id, true, 'medications', true);
            showToast('Medicamento desvinculado', 'success');
        } catch (e: any) {
            if (e?.response?.status === 404 || e?.status === 404) {
                await treatmentMedicationService.clearCache();
                await refreshAssociations(treatment.id, true, 'medications', true);
            } else {
                await refreshAssociations(treatment.id, true, 'medications');
                showToast('Error al desvincular medicamento', 'error');
            }
        } finally {
            setDeleteLoadingId(null);
        }
    };

    const handleViewItem = (type: 'vaccine' | 'medication', id: number) => {
        if (!id) return;
        let itemData: any = null;
        if (type === 'vaccine') {
            itemData = vaccineFullMap[id];
        } else {
            itemData = medicationFullMap[id];
        }

        if (itemData) {
            setViewDetailType(type);
            setViewDetailItem(itemData);
        } else {
            setViewDetailType(type);
            setViewDetailItem({
                id,
                name: type === 'vaccine' ? `Vacuna #${id}` : `Medicamento #${id}`,
                _notFound: true
            });
            showToast('Los datos completos no están disponibles. Mostrando información básica.', 'warning');
        }
    };

    return (
        <div className={cn("space-y-4", className)}>
            {/* Header Actions */}
            <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-3 bg-muted/30 p-3 rounded-lg border border-border/50">
                <div className="flex items-center gap-2">
                    <span className="text-sm font-medium text-muted-foreground">Gestión de Insumos</span>
                    <Button
                        variant="ghost"
                        size="sm"
                        className="h-6 w-6 p-0 hover:bg-primary/20 hover:text-primary transition-colors"
                        onClick={() => treatment?.id && refreshAssociations(treatment.id, true, 'all')}
                        title="Refrescar datos (bypass cache)"
                    >
                        <RefreshCw className={cn("h-3.5 w-3.5", (loadingVaccines || loadingMedications) && "animate-spin")} />
                    </Button>
                </div>
                <div className="flex items-center gap-2">
                    <Button
                        variant="primary"
                        size="sm"
                        onClick={() => { setShowAddVaccine((s) => !s); setShowAddMedication(false); }}
                        disabled={!treatment}
                        className="h-8 text-xs bg-cyan-600 hover:bg-cyan-700"
                    >
                        + Vacuna
                    </Button>
                    <Button
                        variant="primary"
                        size="sm"
                        onClick={() => { setShowAddMedication((s) => !s); setShowAddVaccine(false); }}
                        disabled={!treatment}
                        className="h-8 text-xs bg-purple-600 hover:bg-purple-700"
                    >
                        + Medicamento
                    </Button>
                </div>
            </div>

            {/* Forms */}
            {showAddVaccine && treatment && (
                <form onSubmit={handleCreateVaccine} className="rounded-lg border bg-background/80 p-3 space-y-3 animate-in fade-in zoom-in-95 duration-200">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                        <div>
                            <label className="block text-xs text-muted-foreground mb-1">Vacuna</label>
                            <input
                                type="text"
                                className="mb-2 w-full h-8 rounded-md border bg-background px-2 text-sm"
                                placeholder="Buscar vacuna…"
                                value={vaccineSearch}
                                onChange={(e) => setVaccineSearch(e.target.value)}
                            />
                            <select
                                aria-label="Seleccionar vacunas"
                                className="w-full h-9 rounded-md border bg-background px-2 text-sm"
                                multiple
                                value={newVaccines.map(String)}
                                onChange={(e) => setNewVaccines(Array.from(e.target.selectedOptions).map((o) => Number(o.value)))}
                                required
                            >
                                {vaccineOptions
                                    .filter((opt) => opt.label.toLowerCase().includes(vaccineSearch.toLowerCase()))
                                    .map((opt) => (
                                        <option key={opt.value} value={opt.value}>{opt.label}</option>
                                    ))}
                            </select>
                        </div>
                        <div className="flex items-end gap-2">
                            <Button type="submit" size="sm" disabled={savingVaccine}>Guardar</Button>
                            <Button type="button" variant="ghost" size="sm" onClick={() => setShowAddVaccine(false)}>Cancelar</Button>
                        </div>
                    </div>
                    {newVaccineError && <div className="text-xs text-destructive">{newVaccineError}</div>}
                </form>
            )}

            {showAddMedication && treatment && (
                <form onSubmit={handleCreateMedication} className="rounded-lg border bg-background/80 p-3 space-y-3 animate-in fade-in zoom-in-95 duration-200">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                        <div>
                            <label className="block text-xs text-muted-foreground mb-1">Medicamento</label>
                            <input
                                type="text"
                                className="mb-2 w-full h-8 rounded-md border bg-background px-2 text-sm"
                                placeholder="Buscar medicamento…"
                                value={medicationSearch}
                                onChange={(e) => setMedicationSearch(e.target.value)}
                            />
                            <select
                                aria-label="Seleccionar medicamentos"
                                className="w-full h-9 rounded-md border bg-background px-2 text-sm"
                                multiple
                                value={newMedications.map(String)}
                                onChange={(e) => setNewMedications(Array.from(e.target.selectedOptions).map((o) => Number(o.value)))}
                                required
                            >
                                {medicationOptions
                                    .filter((opt) => opt.label.toLowerCase().includes(medicationSearch.toLowerCase()))
                                    .map((opt) => (
                                        <option key={opt.value} value={opt.value}>{opt.label}</option>
                                    ))}
                            </select>
                        </div>
                        <div className="flex items-end gap-2">
                            <Button type="submit" size="sm" disabled={savingMedication}>Guardar</Button>
                            <Button type="button" variant="ghost" size="sm" onClick={() => setShowAddMedication(false)}>Cancelar</Button>
                        </div>
                    </div>
                    {newMedicationError && <div className="text-xs text-destructive">{newMedicationError}</div>}
                </form>
            )}

            {/* Cards */}
            <TreatmentSuppliesCards
                vaccines={vaccines as any}
                medications={medications as any}
                vaccineFullMap={vaccineFullMap}
                medicationFullMap={medicationFullMap}
                vaccineRouteMap={vaccineRouteMap}
                onViewVaccine={(id) => handleViewItem('vaccine', id)}
                onViewMedication={(id) => handleViewItem('medication', id)}
                onDeleteVaccine={openDeleteVaccine}
                onDeleteMedication={openDeleteMedication}
                confirmingDeleteId={confirmingDeleteId}
                deleteLoadingId={deleteLoadingId}
                loadingVaccines={loadingVaccines}
                loadingMedications={loadingMedications}
            />

            {/* Nested Detail Modal for Vaccines/Meds */}
            {viewDetailItem && viewDetailType && (
                <ItemDetailModal
                    type={viewDetailType}
                    item={viewDetailItem}
                    options={{}}
                    onClose={() => {
                        setViewDetailItem(null);
                        setViewDetailType(null);
                    }}
                    onEdit={() => {
                        const itemId = viewDetailItem?.id;
                        if (!itemId) return;
                        const route = viewDetailType === 'vaccine'
                            ? `/admin/vaccines?edit=${itemId}`
                            : `/admin/medications?edit=${itemId}`;
                        setViewDetailItem(null);
                        setViewDetailType(null);
                        window.location.href = route;
                    }}
                    zIndex={2500}
                />
            )}
        </div>
    );
};

import React from 'react';
import { Loader2 } from 'lucide-react';

interface LoadingOverlayProps {
  /** Mostrar el overlay */
  show: boolean;
  /** Mensaje personalizado (opcional) */
  message?: string;
  /** Hacer el overlay más opaco (menos transparente) */
  opaque?: boolean;
  /** Permitir clicks a través del overlay (no bloqueante) */
  allowInteraction?: boolean;
  /** Tipo de operación para colores temáticos */
  variant?: 'default' | 'success' | 'warning' | 'danger' | 'info';
}

/**
 * Overlay elegante de carga con código de colores y mejor visibilidad
 * Indica al usuario el tipo de operación con colores temáticos
 */
export function LoadingOverlay({
  show,
  message = 'Cargando...',
  opaque = false,
  allowInteraction = false,
  variant = 'default',
}: LoadingOverlayProps) {
  if (!show) return null;

  const tokens: Record<NonNullable<LoadingOverlayProps['variant']>, {
    spinnerClass: string;
    accentVar: string;
    ghostVar: string;
    ghostStrongVar: string;
  }> = {
    default: {
      spinnerClass: 'text-primary',
      accentVar: '--color-primary',
      ghostVar: '--primary-ghost',
      ghostStrongVar: '--primary-ghost-strong',
    },
    success: {
      spinnerClass: 'text-success',
      accentVar: '--color-success',
      ghostVar: '--success-ghost',
      ghostStrongVar: '--success-ghost-strong',
    },
    warning: {
      spinnerClass: 'text-warning',
      accentVar: '--color-warning',
      ghostVar: '--warning-ghost',
      ghostStrongVar: '--warning-ghost-strong',
    },
    danger: {
      spinnerClass: 'text-danger',
      accentVar: '--color-danger',
      ghostVar: '--danger-ghost',
      ghostStrongVar: '--danger-ghost-strong',
    },
    info: {
      spinnerClass: 'text-info',
      accentVar: '--color-info',
      ghostVar: '--info-ghost',
      ghostStrongVar: '--info-ghost-strong',
    },
  };

  const selected = tokens[variant];
  const accentColor = `hsl(var(${selected.accentVar}))`;
  const ghostColor = `hsl(var(${selected.ghostVar}))`;
  const ghostStrongColor = `hsl(var(${selected.ghostStrongVar}))`;

  return (
    <div
      className={`fixed inset-0 z-[99998] flex items-center justify-center transition-all duration-300 ease-out animate-fade-in ${
        allowInteraction ? 'pointer-events-none' : ''
      }`}
      style={{
        backgroundColor: opaque
          ? `hsl(var(--overlay-strong))`
          : allowInteraction
            ? `hsl(var(--overlay-muted))`
            : `hsl(var(--overlay-soft))`,
        backdropFilter: show ? 'blur(14px)' : 'blur(0px)',
        WebkitBackdropFilter: show ? 'blur(14px)' : 'blur(0px)',
        opacity: show ? 1 : 0,
      }}
    >
      {/* Contenedor del indicador - siempre encima con mejor visibilidad */}
      <div
        className={`flex flex-col items-center gap-4 px-8 py-6 rounded-2xl shadow-xl border transform transition-all duration-300 ease-out animate-scale-in bg-surface ${
          show ? 'scale-100 opacity-100 translate-y-0' : 'scale-90 opacity-0 translate-y-4'
        } ${allowInteraction ? 'pointer-events-auto' : ''}`}
        style={{
          borderColor: ghostStrongColor,
          boxShadow: `0 25px 55px -20px ${ghostStrongColor}, 0 12px 30px -12px ${ghostColor}`,
          backgroundColor: `hsl(var(--surface-primary))`,
        }}
      >
        {/* Spinner animado con color temático */}
        <div className="relative">
          <Loader2
            className={`w-12 h-12 ${selected.spinnerClass} animate-spin`}
            strokeWidth={2.5}
          />
          {/* Anillo pulsante de fondo */}
          <div
            className="absolute inset-0 rounded-full border-4 opacity-30 animate-pulse"
            style={{ borderStyle: 'dashed', borderColor: accentColor }}
          />
        </div>

        {/* Mensaje con mejor tipografía */}
        {message && (
          <div className="text-center space-y-1">
            <p className="text-base font-semibold text-foreground">
              {message}
            </p>
            <p className="text-xs text-muted-foreground">
              Por favor espere...
            </p>
          </div>
        )}

        {/* Barra de progreso indeterminada mejorada */}
        <div className="w-32 h-1.5 bg-surface-secondary rounded-full overflow-hidden shadow-inner">
          <div
            className="h-full rounded-full"
            style={{
              backgroundColor: ghostStrongColor,
              animation: 'progressIndeterminate 1.5s cubic-bezier(0.4, 0, 0.2, 1) infinite',
            }}
          />
        </div>

        {/* Dots loading animation */}
        <div className="flex gap-1.5">
          {[0, 0.15, 0.3].map((delay) => (
            <span
              key={delay}
              className={`w-2 h-2 rounded-full animate-bounce ${selected.spinnerClass}`}
              style={{ animationDelay: `${delay}s`, backgroundColor: accentColor }}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

/**
 * Hook personalizado para manejar estados de carga
 */
// eslint-disable-next-line react-refresh/only-export-components
export function useLoadingOverlay() {
  const [isLoading, setIsLoading] = React.useState(false);
  const [message, setMessage] = React.useState<string>('Cargando...');

  const showLoading = React.useCallback((msg?: string) => {
    setMessage(msg || 'Cargando...');
    setIsLoading(true);
  }, []);

  const hideLoading = React.useCallback(() => {
    setIsLoading(false);
  }, []);

  const withLoading = React.useCallback(
    async <T,>(
      promise: Promise<T>,
      loadingMessage?: string
    ): Promise<T> => {
      showLoading(loadingMessage);
      try {
        const result = await promise;
        return result;
      } finally {
        // Pequeño delay para que el usuario vea la transición
        setTimeout(hideLoading, 200);
      }
    },
    [showLoading, hideLoading]
  );

  return {
    isLoading,
    message,
    showLoading,
    hideLoading,
    withLoading,
  };
}

import React from 'react';

export interface SkeletonTableProps {
  columnLabels: string[];
  columnWidths?: Array<number | undefined>;
  rows?: number;
}

/**
 * SkeletonTable: muestra un esqueleto de tabla accesible mientras se cargan los datos.
 * - Respeta los anchos numéricos de columnas (width -> w-{n}).
 * - Usa bg-muted y animate-pulse para alinearse con el patrón visual y dark mode.
 */
export const SkeletonTable: React.FC<SkeletonTableProps> = ({
  columnLabels,
  columnWidths = [],
  rows = 8,
}) => {
  const headCells = columnLabels.map((label, idx) => {
    const w = columnWidths[idx];
    return (
      <th
        key={`sk-head-${idx}`}
        className={[
          'px-2 py-1 text-left text-[11px] md:text-xs font-medium text-muted-foreground uppercase tracking-wider',
          w ? `w-${w}` : '',
        ].join(' ')}
        aria-hidden="true"
      >
        {label}
      </th>
    );
  });

  const bodyRows = Array.from({ length: rows }).map((_, rIdx) => (
    <tr key={`sk-row-${rIdx}`} className="h-8 md:h-9">
      {columnLabels.map((_, cIdx) => {
        const w = columnWidths[cIdx];
        return (
          <td
            key={`sk-cell-${rIdx}-${cIdx}`}
            className={[
              'px-2 py-1 whitespace-nowrap text-[11px] md:text-xs',
              w ? `w-${w}` : '',
            ].join(' ')}
          >
            {/* Contenedor del skeleton con efecto shimmer mejorado */}
            <div
              className="h-4 w-full rounded relative overflow-hidden bg-muted/40"
              style={{ maxWidth: Math.floor(Math.random() * (100 - 60) + 60) + '%' }}
            >
              <div className="absolute inset-0 animate-shimmer" />
            </div>
          </td>
        );
      })}
    </tr>
  ));

  return (
    <div className="overflow-x-auto overflow-y-hidden">
      <table className="min-w-full divide-y divide-border/70 text-[12px] md:text-sm">
        <thead className="sticky top-0 z-10 bg-muted/60 backdrop-blur-sm supports-[backdrop-filter]:bg-muted/50">
          <tr className="h-8">{headCells}</tr>
        </thead>
        <tbody className="divide-y divide-border/60 bg-card">{bodyRows}</tbody>
      </table>
    </div>
  );
};

export default SkeletonTable;
