                <div className="space-y-2">
                  <Label htmlFor="sex">Sexo</Label>
                  <select
                    id="sex"
                    className="w-full h-10 rounded-md border border-input bg-white px-3 py-2 text-sm"
                    value={formData.sex}
                    onChange={(e) => handleChange('sex', e.target.value)}
                  >
                    <option value="Hembra">Hembra</option>
                    <option value="Macho">Macho</option>
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="birth_weight">Peso al nacer (kg)</Label>
                  <Input
                    id="birth_weight"
                    type="number"
                    step="0.5"
                    placeholder="Ej: 35"
                    value={formData.birth_weight}
                    onChange={(e) => handleChange('birth_weight', e.target.value)}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="vitality">Vitalidad</Label>
                  <select
                    id="vitality"
                    className="w-full h-10 rounded-md border border-input bg-white px-3 py-2 text-sm"
                    value={formData.vitality}
                    onChange={(e) => handleChange('vitality', e.target.value)}
                  >
                    <option value="Vigoroso">Vigoroso / Fuerte</option>
                    <option value="Normal">Normal</option>
                    <option value="Débil">Débil / Aletargado</option>
                  </select>
                </div>
              </div>

              <div className="space-y-3 pt-2">
                <div className="flex items-center space-x-2">
                  <Checkbox 
                    id="colostrum" 
                    checked={formData.colostrum_intake}
                    onCheckedChange={(c) => handleChange('colostrum_intake', c)}
                  />
                  <Label htmlFor="colostrum" className="cursor-pointer">Toma de Calostro Confirmada (1-4h)</Label>
                </div>
                <div className="flex items-center space-x-2">
                  <Checkbox 
                    id="navel" 
                    checked={formData.navel_disinfected}
                    onCheckedChange={(c) => handleChange('navel_disinfected', c)}
                  />
                  <Label htmlFor="navel" className="cursor-pointer">Ombligo desinfectado (Yodo)</Label>
                </div>
              </div>
            </div>
          </div>

          <div className="flex items-start gap-2 p-4 bg-yellow-50 text-yellow-800 rounded-lg border border-yellow-200 text-sm">
            <Info className="h-5 w-5 flex-shrink-0 mt-0.5 text-yellow-600" />
            <p>
              Llenar este formulario activará las alertas post-parto automáticas para la madre (revisión de metritis, hipocalcemia, primer celo) y las vacunas pediátricas de la cría.
            </p>
          </div>

          <div className="flex justify-end pt-4">
            <Button type="submit" disabled={loading} className="w-full md:w-auto bg-primary hover:bg-primary/90 text-white min-w-[200px]">
              {loading ? 'Guardando...' : 'Guardar Registro de Parto'}
            </Button>
          </div>

        </form>
      </CardContent>
    </Card>
  );
}

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/shared/ui/card';
import { Button } from '@/shared/ui/button';
import { Badge } from '@/shared/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/shared/ui/tabs';
import { TreeDeciduous, Users } from 'lucide-react';
import { reproductionService } from '@/entities/reproduction/api/reproduction.service';
import { useToast } from '@/app/providers/ToastContext';
import { cn } from '@/shared/ui/cn';

interface TreeNode {
  id: number;
  record: string;
  sex: string;
  breeds_id?: number;
  idFather?: number;
  idMother?: number;
}

interface TreeData {
  rootId: number;
  root_record: string;
  root_sex: string;
  ancestors?: {
    nodes: Record<number, TreeNode>;
    edges: Array<{ from: number; to: number; relation: string }>;
    depth: number;
  };
  descendants?: {
    nodes: Record<number, TreeNode>;
    edges: Array<{ from: number; to: number; relation: string }>;
    depth: number;
  };
}

interface GenealogyTreeProps {
  animalId: number;
}

export default function GenealogyTree({ animalId }: GenealogyTreeProps) {
  const { showToast } = useToast();
  const [loading, setLoading] = useState(true);
  const [data, setData] = useState<TreeData | null>(null);
  const [activeTab, setActiveTab] = useState<'ancestors' | 'descendants'>('ancestors');
  const [depth, setDepth] = useState(3);

  const loadGenealogy = async () => {
    setLoading(true);
    try {
      const response = await reproductionService.getGenealogy(animalId, depth, 'both');
      setData(response as TreeData);
    } catch (error) {
      console.error('Error loading genealogy:', error);
      showToast('Error al cargar genealogía', 'error');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadGenealogy();
  }, [animalId, depth]);
  const getSexStyles = (sex: string) => {
    return sex === 'Macho' 
      ? 'from-blue-500/20 to-blue-600/5 border-blue-500/30 text-blue-700 dark:text-blue-300' 
      : 'from-rose-500/20 to-rose-600/5 border-rose-500/30 text-rose-700 dark:text-rose-300';
  };

  const renderNode = (node: TreeNode, isRoot: boolean = false) => (
    <div
      key={node.id}
      className={cn(
        "relative flex flex-col items-center gap-2 p-3 rounded-2xl border transition-all duration-500 group/node",
        "bg-gradient-to-br backdrop-blur-xl shadow-lg hover:shadow-2xl hover:scale-105 hover:-translate-y-1",
        isRoot 
          ? "from-primary/30 to-primary/5 border-primary shadow-primary/20 ring-4 ring-primary/5" 
          : getSexStyles(node.sex)
      )}
    >
      <div className="flex items-center gap-2">
        <div className={cn(
          "h-8 w-8 rounded-full flex items-center justify-center text-xs font-black shadow-inner",
          node.sex === 'Macho' ? "bg-blue-500/20 text-blue-600" : "bg-rose-500/20 text-rose-600"
        )}>
          {node.sex === 'Macho' ? '♂' : '♀'}
        </div>
        <div className="flex flex-col">
          <span className="text-[10px] font-black uppercase tracking-tighter opacity-50">{node.sex}</span>
          <span className="font-black text-sm tracking-tight">{node.record}</span>
        </div>
      </div>
      {isRoot && (
        <Badge variant="default" className="text-[9px] h-4 bg-primary text-primary-foreground font-black px-1.5 uppercase tracking-widest">
          Sujeto Central
        </Badge>
      )}
      
      {/* Decorative background element */}
      <div className="absolute -z-10 inset-0 bg-white/40 dark:bg-black/20 rounded-2xl opacity-0 group-hover/node:opacity-100 transition-opacity" />
    </div>
  );

  const renderAncestors = () => {
    if (!data?.ancestors) return null;
    const { nodes, edges } = data.ancestors;

    const childrenByParent: Record<number, number[]> = {};
    edges.forEach(edge => {
      if (!childrenByParent[edge.from]) childrenByParent[edge.from] = [];
      childrenByParent[edge.from].push(edge.to);
    });

    const renderHierarchy = (nodeId: number, level: number = 0) => {
      const node = nodes[nodeId];
      if (!node) return null;

      const children = childrenByParent[nodeId] || [];
      const isRoot = nodeId === data.rootId;

      return (
        <div key={nodeId} className="flex flex-col items-center gap-8">
          {renderNode(node, isRoot)}
          
          {children.length > 0 && (
            <div className="relative flex items-start gap-12 pt-8">
              {/* Connecting line to children */}
              <div className="absolute top-0 left-1/2 -translate-x-1/2 h-8 w-[2px] bg-gradient-to-b from-primary/50 to-transparent" />
              
              {children.map((childId, idx) => (
                <div key={childId} className="relative">
                  {/* Horizontal connecting line */}
                  {children.length > 1 && (
                    <div className={cn(
                      "absolute top-0 h-[2px] bg-primary/20",
                      idx === 0 ? "left-1/2 right-0" : idx === children.length - 1 ? "left-0 right-1/2" : "left-0 right-0"
                    )} />
                  )}
                  {renderHierarchy(childId, level + 1)}
                </div>
              ))}
            </div>
          )}
        </div>
      );
    };

    return (
      <div className="py-10 overflow-x-auto scrollbar-hide">
        <div className="flex justify-center min-w-max px-20">
          {renderHierarchy(data.rootId)}
        </div>
      </div>
    );
  };

  const renderDescendants = () => {
    if (!data?.descendants) return null;
    const { nodes, edges } = data.descendants;

    const childrenByParent: Record<number, number[]> = {};
    edges.forEach(edge => {
      if (!childrenByParent[edge.from]) childrenByParent[edge.from] = [];
      childrenByParent[edge.from].push(edge.to);
    });

    const renderHierarchy = (nodeId: number, level: number = 0) => {
      const node = nodes[nodeId];
      if (!node) return null;

      const children = childrenByParent[nodeId] || [];
      const isRoot = nodeId === data.rootId;

      return (
        <div key={nodeId} className="flex flex-col items-center gap-8">
          {renderNode(node, isRoot)}
          
          {children.length > 0 && (
            <div className="relative flex items-start gap-12 pt-8">
              <div className="absolute top-0 left-1/2 -translate-x-1/2 h-8 w-[2px] bg-gradient-to-b from-primary/50 to-transparent" />
              
              {children.map((childId, idx) => (
                <div key={childId} className="relative">
                  {children.length > 1 && (
                    <div className={cn(
                      "absolute top-0 h-[2px] bg-primary/20",
                      idx === 0 ? "left-1/2 right-0" : idx === children.length - 1 ? "left-0 right-1/2" : "left-0 right-0"
                    )} />
                  )}
                  {renderHierarchy(childId, level + 1)}
                </div>
              ))}
            </div>
          )}
        </div>
      );
    };

    return (
      <div className="py-10 overflow-x-auto scrollbar-hide">
        <div className="flex justify-center min-w-max px-20">
          {renderHierarchy(data.rootId)}
        </div>
      </div>
    );
  };

  if (loading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Genealogía</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-center py-8">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (!data) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Genealogía</CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-center text-muted-foreground">No hay datos de genealogía</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="text-lg flex items-center gap-2">
              <TreeDeciduous className="h-5 w-5" />
              Genealogía
            </CardTitle>
            <CardDescription className="text-xs">
              {data.root_record} ({data.root_sex})
            </CardDescription>
          </div>
          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => setDepth(Math.max(1, depth - 1))}
              disabled={depth <= 1}
            >
              -
            </Button>
            <span className="text-sm font-medium">{depth} niveles</span>
            <Button
              variant="outline"
              size="sm"
              onClick={() => setDepth(Math.min(6, depth + 1))}
              disabled={depth >= 6}
            >
              +
            </Button>
          </div>
        </div>
      </CardHeader>
      <CardContent>
        <Tabs value={activeTab} onValueChange={(v: string) => setActiveTab(v as 'ancestors' | 'descendants')}>
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="ancestors" className="flex items-center gap-2">
              <Users className="h-4 w-4" />
              Ancestros
            </TabsTrigger>
            <TabsTrigger value="descendants" className="flex items-center gap-2">
              <TreeDeciduous className="h-4 w-4" />
              Descendientes
            </TabsTrigger>
          </TabsList>
          <TabsContent value="ancestors" className="mt-4">
            {renderAncestors()}
          </TabsContent>
          <TabsContent value="descendants" className="mt-4">
            {renderDescendants()}
          </TabsContent>
        </Tabs>
      </CardContent>
    </Card>
  );
}

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/shared/ui/card';
import { Button } from '@/shared/ui/button';
import { Badge } from '@/shared/ui/badge';
import { AlertTriangle, Clock, Calendar, Plus, RefreshCw } from 'lucide-react';
import { reproductionService } from '@/entities/reproduction/api/reproduction.service';
import { useToast } from '@/app/providers/ToastContext';
import { useNavigate } from 'react-router-dom';

interface HeatAlert {
  animal_id: number;
  record: string;
  breed: string;
  days_since_last_heat: number;
  last_heat_date: string;
  priority: 'Alta' | 'Media' | 'Baja';
  age_days: number | null;
}

export default function HeatAlertsWidget() {
  const navigate = useNavigate();
  const { showToast } = useToast();
  const [loading, setLoading] = useState(true);
  const [alerts, setAlerts] = useState<HeatAlert[]>([]);

  const loadAlerts = async () => {
    setLoading(true);
    try {
      const response = await reproductionService.getHeatAlerts();
      setAlerts(response as HeatAlert[]);
    } catch (error) {
      console.error('Error loading heat alerts:', error);
      showToast('Error al cargar alertas de celo', 'error');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadAlerts();
  }, []);

  const handleRegisterHeat = (animalId: number) => {
    navigate('/admin/reproduction', { state: { preselectAnimal: animalId, eventType: 'Celo' } });
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'Alta': return 'bg-red-500';
      case 'Media': return 'bg-yellow-500';
      case 'Baja': return 'bg-blue-500';
      default: return 'bg-gray-500';
    }
  };

  const getPriorityVariant = (priority: string): 'default' | 'destructive' | 'outline' | 'secondary' => {
    switch (priority) {
      case 'Alta': return 'destructive';
      case 'Media': return 'default';
      case 'Baja': return 'secondary';
      default: return 'outline';
    }
  };

  if (loading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Alertas de Celo</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-center py-4">
            <RefreshCw className="h-5 w-5 animate-spin text-muted-foreground" />
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="text-lg flex items-center gap-2">
              <AlertTriangle className="h-5 w-5 text-orange-500" />
              Alertas de Celo
            </CardTitle>
            <CardDescription className="text-xs">
              Hembras en ventana de celo (18-23 días)
            </CardDescription>
          </div>
          <Button variant="ghost" size="icon" onClick={loadAlerts}>
            <RefreshCw className="h-4 w-4" />
          </Button>
        </div>
      </CardHeader>
      <CardContent>
        {alerts.length === 0 ? (
          <div className="text-center py-6 text-muted-foreground text-sm">
            <Clock className="h-8 w-8 mx-auto mb-2 opacity-50" />
            <p>No hay alertas de celo activas</p>
          </div>
        ) : (
          <div className="space-y-3">
            {alerts.slice(0, 5).map((alert) => (
              <div
                key={alert.animal_id}
                className="flex items-center justify-between p-3 bg-muted/50 rounded-lg hover:bg-muted transition-colors"
              >
                <div className="flex items-center gap-3 flex-1 min-w-0">
                  <Badge className={getPriorityColor(alert.priority)}>
                    {alert.priority}
                  </Badge>
                  <div className="min-w-0">
                    <p className="font-medium text-sm truncate">{alert.record}</p>
                    <p className="text-xs text-muted-foreground">
                      {alert.breed} • {alert.age_days ? `${Math.floor(alert.age_days / 365)} años` : '---'}
                    </p>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <div className="text-right mr-2">
                    <p className="text-xs text-muted-foreground">Días desde celo</p>
                    <p className="font-semibold text-sm">{alert.days_since_last_heat}</p>
                  </div>
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => handleRegisterHeat(alert.animal_id)}
                  >
                    <Plus className="h-4 w-4" />
                  </Button>
                </div>
              </div>
            ))}
            {alerts.length > 5 && (
              <Button
                variant="ghost"
                size="sm"
                className="w-full"
                onClick={() => navigate('/admin/reproduction')}
              >
                Ver {alerts.length - 5} más
              </Button>
            )}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/shared/ui/card';
import { Button } from '@/shared/ui/button';
import { Badge } from '@/shared/ui/badge';
import { Calendar as CalendarIcon, ChevronLeft, ChevronRight, Filter } from 'lucide-react';
import { reproductionService } from '@/entities/reproduction/api/reproduction.service';
import { useToast } from '@/app/providers/ToastContext';
import { addDays, subDays, format, isSameDay } from 'date-fns';
import { es } from 'date-fns/locale';

interface CalendarEvent {
  id: string;
  title: string;
  start: string;
  backgroundColor: string;
  borderColor: string;
  extendedProps: {
    event_type: string;
    animal_id: number;
    animal_record: string;
    notes?: string;
    is_pending?: boolean;
  };
}

export default function ReproductionCalendar() {
  const { showToast } = useToast();
  const [loading, setLoading] = useState(true);
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [currentDate, setCurrentDate] = useState(new Date());

  const loadEvents = async () => {
    setLoading(true);
    try {
      const startDate = format(subDays(currentDate, 30), 'yyyy-MM-dd');
      const endDate = format(addDays(currentDate, 60), 'yyyy-MM-dd');
      const response = await reproductionService.getCalendar(startDate, endDate);
      setEvents(response as CalendarEvent[]);
    } catch (error) {
      console.error('Error loading calendar:', error);
      showToast('Error al cargar calendario', 'error');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadEvents();
  }, [currentDate]);

  const groupEventsByDate = () => {
    const grouped: Record<string, CalendarEvent[]> = {};
    events.forEach(event => {
      const date = event.start;
      if (!grouped[date]) {
        grouped[date] = [];
      }
      grouped[date].push(event);
    });
    return grouped;
  };

  const getEventTypeColor = (type: string) => {
    switch (type) {
      case 'Celo': return 'bg-yellow-500';
      case 'Inseminacion': return 'bg-blue-500';
      case 'Diagnostico': return 'bg-orange-500';
      case 'Parto': return 'bg-green-500';
      case 'Parto_Pendiente': return 'bg-red-500 border-2 border-red-600';
      default: return 'bg-gray-500';
    }
  };

  const groupedEvents = groupEventsByDate();
  const sortedDates = Object.keys(groupedEvents).sort();

  if (loading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Calendario Reproductivo</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-center py-8">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="text-lg flex items-center gap-2">
              <CalendarIcon className="h-5 w-5" />
              Calendario Reproductivo
            </CardTitle>
            <CardDescription className="text-xs">
              {format(currentDate, 'MMMM yyyy', { locale: es })}
            </CardDescription>
          </div>
          <div className="flex items-center gap-2">
            <Button variant="outline" size="icon" onClick={() => setCurrentDate(subDays(currentDate, 30))}>
              <ChevronLeft className="h-4 w-4" />
            </Button>
            <Button variant="outline" size="icon" onClick={() => setCurrentDate(addDays(currentDate, 30))}>
              <ChevronRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
      </CardHeader>
      <CardContent>
        {sortedDates.length === 0 ? (
          <div className="text-center py-8 text-muted-foreground text-sm">
            <CalendarIcon className="h-8 w-8 mx-auto mb-2 opacity-50" />
            <p>No hay eventos en este período</p>
          </div>
        ) : (
          <div className="space-y-4 max-h-96 overflow-y-auto">
            {sortedDates.map((date) => (
              <div key={date} className="space-y-2">
                <div className="flex items-center gap-2 text-sm font-medium text-muted-foreground">
                  <CalendarIcon className="h-4 w-4" />
                  {format(new Date(date), 'EEEE, d MMMM yyyy', { locale: es })}
                </div>
                <div className="space-y-2 pl-6">
                  {groupedEvents[date].map((event) => (
                    <div
                      key={event.id}
                      className="flex items-center justify-between p-2 rounded-lg hover:bg-muted/50 transition-colors"
                      style={{ borderLeft: `4px solid ${event.borderColor}` }}
                    >
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium truncate">{event.title}</p>
                        {event.extendedProps.notes && (
                          <p className="text-xs text-muted-foreground truncate">
                            {event.extendedProps.notes}
                          </p>
                        )}
                      </div>
                      <Badge className={getEventTypeColor(event.extendedProps.event_type)}>
                        {event.extendedProps.event_type.replace('_', ' ')}
                      </Badge>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}

